    FOREX_DEPOSIT DMDBCR DEFAULT 0,
    FOREX_ADJUST DMDBCR DEFAULT 0,
    FOREX_PAID DMDBCR DEFAULT 0,
    FOREX_PAIDPREPARE DMDBCR DEFAULT 0,
    FOREX_TOTALDUE COMPUTED BY (forex_total+forex_adjust-forex_deposit-forex_paid),
    FOREX_ADJUST_FO DMDBCR DEFAULT 0,
    FOREX_TOTALDUE_PREPARE COMPUTED BY (forex_total+forex_adjust-forex_deposit-forex_paid-forex_paidprepare+forex_adjust_fo),
    FOREX_GAINLOSS DMDBCR,
    TOTALDUE COMPUTED BY (total+adjust-deposit-paid+forex_gainloss),
    TOTALDUE_PREPARE COMPUTED BY (total+adjust-deposit-paid-paidprepare+adjust_fo+forex_gainloss),
    GLSTATUS DMCODE1 DEFAULT 'O',
    SOURCEID DMDOCNUMBER,
    SOURCE_REMARK DMNAMEFULL,
    NAME DMNAME,
    ADDRESS1 DMNAME,
    ADDRESS2 DMNAME,
    ADDRESS3 DMNAME,
    ADDRESS4 DMNAME,
    PHONE DMNAME,
