    HU_QTY DMINVQTY,
    PARTNO DMINVPARTNO,
    RECIPE DMIRRECIPE,
    RECIPE_QTY DMINVQTY,
    CALC_SALES COMPUTED BY (QTY*PRICE),
    CALC_COST COMPUTED BY (QTY*COST),
    CALC_HU COMPUTED BY (HU_QTY*PRICE),
    CALC_HU_COST COMPUTED BY (HU_QTY*COST),
    CREATEUSER DMUSER,
    EDITUSER DMUSER,
    CREATEDATE DMDATEEDIT,
    EDITDATE DMDATEEDIT,
