CREATE TABLE INVPO1 (
    NUMBER DMDOCNUMBER NOT NULL,
    LINE DMLINE NOT NULL,
    PARTNO DMINVPARTNO,
    QTYF DMINVQTY,
    QTY DMINVQTY,
    KONVERSI DMINVKONVERSI,
    DELVQTY DMINVQTY,
    COST DMINVCOSTPRICE,
    COSTO DMINVCOSTPRICE,
    TAX DMPERSENT,
    DISCOUNTA DMINVCOSTPRICE,
    DISCOUNT DMPERSENT,
    DISCOUNT2 DMPERSENT,
    DELVCOST DMINVCOSTPRICE,
    NOTE DMNOTE,
    REQNO DMDOCNUMBER DEFAULT 0,
    CALC_COSTO COMPUTED BY ((QTYF+(QTY/KONVERSI))*COSTO),
    CALC_DISCOUNTA COMPUTED BY ((QTYF+QTY/KONVERSI)*DISCOUNTA),
    CALC_DISCOUNT COMPUTED BY ((CALC_COSTO-CALC_DISCOUNTA)*DISCOUNT/100),
    CALC_DISCOUNT2 COMPUTED BY ((CALC_COSTO-CALC_DISCOUNTA-CALC_DISCOUNT)*DISCOUNT2/100),
    CALC_NETCOST COMPUTED BY (CALC_COSTO-CALC_DISCOUNTA-CALC_DISCOUNT-CALC_DISCOUNT2),
    CALC_TAX COMPUTED BY (CALC_NETCOST*TAX/100),
    CALC_COST COMPUTED BY (CALC_NETCOST+CALC_TAX),
    CALC_QTY COMPUTED BY (QTYF*KONVERSI+QTY),
    ML_NUMBER DMDOCNUMBER,
    CREATEUSER DMUSER,
    EDITUSER DMUSER,
    CREATEDATE DMDATEEDIT,
    EDITDATE DMDATEEDIT,
    ICOST DMINVCOSTCENTER);


