    CALC_DISCOUNTA COMPUTED BY ((QTYF+QTY/KONVERSI)*DISCOUNTA),
    CALC_DISCOUNT COMPUTED BY ((CALC_COSTO-CALC_DISCOUNTA)*DISCOUNT/100),
    CALC_DISCOUNT2 COMPUTED BY ((CALC_COSTO-CALC_DISCOUNTA-CALC_DISCOUNT)*DISCOUNT2/100),
    CALC_NETCOST COMPUTED BY (CALC_COSTO-CALC_DISCOUNTA-CALC_DISCOUNT-CALC_DISCOUNT2),
    CALC_TAX COMPUTED BY (CALC_NETCOST*TAX/100),
    CALC_COST COMPUTED BY (CALC_NETCOST+CALC_TAX),
    CALC_QTY COMPUTED BY (QTYF*KONVERSI+QTY),
    CALC_NETUNITCOST COMPUTED BY (CALC_NETCOST/CALC_QTY),
    CALC_UNITCOST_AFTERTAX COMPUTED BY (CALC_COST/CALC_QTY),
    CURRENCY DMCURRENCY,
    PAYMENT VARCHAR(2) CHARACTER SET NONE COLLATE NONE,
    PAYMENTDUE DMLINE,
    FLAG_MARKED DMLOGICAL DEFAULT 0,
    PAYMENT_DEPOSIT DMAMTINFO,
    PAYMENT_RETENTION DMAMTINFO,
    PAYMENT_REMARK DMTEXT);


