    PARTNO DMINVPARTNO NOT NULL,
    NAME DMNAME,
    GRP DMINVGROUP,
    UNITCOST DMDBCR,
    QTYONHAND DMINVQTY,
    QTYOPEN DMINVQTY,
    QTYIN DMINVQTY,
    QTYTRFIN DMINVQTY,
    QTYRETURN DMINVQTY,
    QTYTRFOUT DMINVQTY,
    QTYISSUE DMINVQTY,
    QTYSPOILAGE DMINVQTY,
    QTYPRODIN DMINVQTY,
    QTYPRODOUT DMINVQTY,
    QTYSALES DMINVQTY,
    QTYADJ DMINVQTY,
    QTYOUTRECIPE DMINVQTY,
    QTYOTRFOUT DMINVQTY DEFAULT 0,
    QTYOTRFIN DMINVQTY DEFAULT 0,
    QTYSALESRET DMINVQTY,
    QTYWIP DMINVQTY,
    QTYDIRECTUSE DMINVQTY DEFAULT 0.0,
    QTYTOTALIN COMPUTED BY ((QTYIN + QTYTRFIN + QTYPRODIN + QTYADJ + QTYSALESRET + QTYOTRFIN)),
    QTYCONSUME COMPUTED BY (-QTYADJ + QTYISSUE + QTYSPOILAGE + QTYPRODOUT + QTYSALES + QTYDIRECTUSE + QTYOUTRECIPE),
    AMTONHAND DMINVAMT,
    AMTOPEN DMINVAMT,
    AMTIN DMINVAMT,
    AMTTRFIN DMINVAMT,
    AMTRETURN DMINVAMT,
    AMTTRFOUT DMINVAMT,
    AMTISSUE DMINVAMT,
    AMTPRODIN DMINVAMT,
    AMTSPOILAGE DMINVAMT,
    AMTPRODOUT DMINVAMT,
    AMTSALES DMINVAMT,
    AMTADJ DMINVAMT,
    AMTDIRECTUSE DMINVAMT DEFAULT 0.0,
    AMTSALESRET DMINVAMT,
    AMTOUTRECIPE DMINVAMT DEFAULT 0,
    AMTOTRFIN DMINVAMT DEFAULT 0,
    AMTOTRFOUT DMINVAMT DEFAULT 0,
    AMTWIP DMINVAMT,
    AMTTOTALIN COMPUTED BY (AMTIN + AMTTRFIN + AMTPRODIN + AMTADJ + AMTSALESRET + AMTOTRFIN),
    AMTTOTALOUT COMPUTED BY (AMTRETURN   + AMTTRFOUT  + AMTISSUE + AMTSPOILAGE + AMTPRODOUT + AMTSALES + AMTDIRECTUSE + AMTOTRFOUT + AMTOUTRECIPE),
    AMTCONSUME COMPUTED BY (-AMTADJ + AMTISSUE + AMTSPOILAGE + AMTPRODOUT + AMTSALES + AMTDIRECTUSE + AMTOUTRECIPE),
    QTYTOTALOUT COMPUTED BY (QTYRETURN   + QTYTRFOUT  + QTYISSUE + QTYSPOILAGE + QTYPRODOUT + QTYSALES + QTYDIRECTUSE + QTYOTRFOUT),
    ICLASS DMINVCLASS,
    ITYPE DMINVTYPE,
    FL_QTY_FULL DMINVQTY,
    FL_QTY_LOOSE DMINVQTY,
    FL_COST_FULL DMINVCOSTPRICE,
