CREATE TABLE SLDO0 (
    NUMBER DMDOCNUMBER NOT NULL,
    CUSTOMER DMCUSTOMER,
    DOCUMENT DMDOCUMENT,
    STATUS DMSTATUSTRANS,
    OPENDATE DMDATEEDIT,
    DELVDATE DMDATEEDIT,
    TOTQTY DMINVQTY,
    TOTAL DMINVAMT,
    TEXT1 DMNAME,
    TEXT2 DMNAME,
    TEXT3 DMNAME,
    LINE DMLINE,
    CREATEDATE DMDATEEDIT,
    EDITDATE DMDATEEDIT,
    CREATEUSER DMUSER,
    EDITUSER DMUSER,
    TOTALCOST DMINVAMT DEFAULT 0.0,
    TOTALO DMINVAMT DEFAULT 0,
    STORE DMINVSTORE DEFAULT '0000' COLLATE NONE,
    SALESMAN DMSALESMAN COLLATE NONE,
    DISCOUNTA DMINVAMT DEFAULT 0.0,
    DISCOUNT DMINVAMT DEFAULT 0.0,
    DISCOUNT2 DMINVAMT DEFAULT 0.0,
    TAX DMINVAMT DEFAULT 0.0,
    ARNUMBER DMDOCNUMBER DEFAULT 0,
    TRANSPORT DMINVAMT DEFAULT 0,
    DOPRINTED DMLOGICAL DEFAULT 0);


CREATE TABLE SLDO1 (
    NUMBER DMDOCNUMBER NOT NULL,
    LINE DMLINE NOT NULL,
    SONUMBER DMDOCNUMBER,
    PARTNO DMINVPARTNO NOT NULL,
    QTYF DMINVQTY,
    QTY DMINVQTY,
    KONVERSI DMINVKONVERSI,
    COST DMINVCOSTPRICE,
    PRICE DMINVCOSTPRICE DEFAULT 0.0,
    NOTE DMNOTE,
    PRICEO DMINVCOSTPRICE DEFAULT 0.0,
    DISCOUNT DMPERSENT DEFAULT 0,
    DISCOUNT2 DMPERSENT,
    DISCOUNTA DMINVCOSTPRICE,
    TAX DMPERSENT DEFAULT 0,
    QTYRET DMINVQTY DEFAULT 0.0,
    DOPRINTED DMLOGICAL DEFAULT 0,
    CALC_DISCOUNTA COMPUTED BY ((QTYF+QTY/KONVERSI)*DISCOUNTA),
    CALC_PRICEO COMPUTED BY ((QTYF+(QTY/KONVERSI))*PRICEO),
    CALC_DISCOUNT COMPUTED BY ((CALC_PRICEO-CALC_DISCOUNTA)*DISCOUNT/100),
    CALC_DISCOUNT2 COMPUTED BY ((CALC_PRICEO-CALC_DISCOUNTA-CALC_DISCOUNT)*DISCOUNT2/100),
    CALC_NETPRICE COMPUTED BY (CALC_PRICEO-CALC_DISCOUNTA-CALC_DISCOUNT-CALC_DISCOUNT2+CALC_TRANSPORT),
    CALC_TAX COMPUTED BY (CALC_NETPRICE*TAX/100),
    CALC_PRICE COMPUTED BY (CALC_NETPRICE+CALC_TAX),
    CALC_QTY COMPUTED BY (QTYF*KONVERSI+QTY),
    CALC_COST COMPUTED BY ((QTY/KONVERSI+QTYF)*COST),
    TRANSPORT DMPERSENT,
    CALC_TRANSPORT COMPUTED BY ((TRANSPORT/100)*(CALC_PRICEO-CALC_DISCOUNTA-CALC_DISCOUNT-CALC_DISCOUNT2)),
    CREATEUSER DMUSER,
    EDITUSER DMUSER,
    CREATEDATE DMDATEEDIT,
    EDITDATE DMDATEEDIT);


CREATE TABLE SLORD0 (
    NUMBER DMDOCNUMBER NOT NULL,
    CUSTOMER DMCUSTOMER,
