    EDITDATE DMDATEEDIT,
    CREATEUSER DMUSER,
    EDITUSER DMUSER,
    TOTALO DMINVAMT DEFAULT 0,
    DISCOUNTA DMINVAMT,
    DISCOUNT DMINVAMT,
    DISCOUNT2 DMINVAMT,
    TAX DMINVAMT,
    DELVQTY DMINVQTY DEFAULT 0);


CREATE TABLE SLORD1 (
    NUMBER DMDOCNUMBER NOT NULL,
    LINE DMLINE,
    PARTNO DMINVPARTNO NOT NULL,
