    CALC_PRICEO COMPUTED BY ((QTYF+(QTY/KONVERSI))*PRICEO),
    CALC_DISCOUNTA COMPUTED BY ((QTYF+QTY/KONVERSI)*DISCOUNTA),
    CALC_DISCOUNT COMPUTED BY ((CALC_PRICEO-CALC_DISCOUNTA)*DISCOUNT/100),
    CALC_DISCOUNT2 COMPUTED BY ((CALC_PRICEO-CALC_DISCOUNTA-CALC_DISCOUNT)*DISCOUNT2/100),
    CALC_NETPRICE COMPUTED BY (CALC_PRICEO-CALC_DISCOUNTA-CALC_DISCOUNT-CALC_DISCOUNT2),
    CALC_TAX COMPUTED BY (CALC_NETPRICE*TAX/100),
    CALC_PRICE COMPUTED BY (CALC_NETPRICE+CALC_TAX),
    CALC_QTY COMPUTED BY (QTYF*KONVERSI+QTY),
