CREATE TRIGGER AR_CARD_BATCH_BD FOR AR_CARD_BATCH
ACTIVE BEFORE DELETE POSITION 0
as
begin
  if (old.status <> 'O') then
     exception all_doc_status_not_open;
end
^

CREATE TRIGGER AR_CARD_BATCH_BU FOR AR_CARD_BATCH
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable vRow integer;
begin
  if (not ((old.status ='R') and (new.status = 'C'))) then begin
     if (old.status <> 'O') then exception all_doc_status_not_open;

     if ((new.batch  <> old.batch) or
         (new.bank   <> old.bank ) or
         (new.outlet <> old.outlet)) then begin
        select count(*) from ar_card_jur
        where batch = new.batch
        and bank = new.bank
        and outlet = new.outlet
        into vRow;
        if (vRow <> 0) then
           exception AR_CREDIT_CARD_BATCH_DELETE;
     end
  end
end
^

CREATE TRIGGER AR_CARD_BATCH_RELEASE FOR AR_CARD_BATCH
ACTIVE AFTER UPDATE POSITION 0
as
declare variable vAccount varchar(20);
declare variable vDept varchar(4);
declare variable vCost varchar(4);
declare variable vFee_Account varchar(20);
declare variable vFee_Dept varchar(4);
declare variable vFee_Cost varchar(4);
declare variable vBK_Account varchar(20);
declare variable vBK_Dept varchar(4);
declare variable vBK_Cost varchar(4);
declare variable vName VARCHAR(40);
declare variable vCreditCard varchar(6);
declare variable vTotal DOUBLE PRECISION;
declare variable vFee   DOUBLE PRECISION;
declare variable vTotalGrand DOUBLE PRECISION;
declare variable vTotalFee   DOUBLE PRECISION;
declare variable vLine integer;
declare variable vARBankBook integer;
begin

  if ((new.status = 'R') and (old.status <> 'R')) then begin

     select gl_account, gl_dept from sysbank
     where bank = old.bank
     into :vBK_Account, :vBK_Dept;


     update ar_card_jur set status = 'C'
     where batch = old.batch;

     vLine = 1;
     vTotalGrand = 0;
     vTotalFee = 0;
     for select creditcard, sum(total) from ar_card_jur
         where batch = new.batch
         and bank = new.bank
         and outlet = new.outlet
         group by creditcard
        into :vCreditCard, :vTotal
     do begin
        select name, fee, gl_ar_account,  gl_ar_dept,  gl_ar_cost,
                          gl_fee_account, gl_fee_dept, gl_fee_cost
        from ar_card where creditcard = :vCreditcard
        into :vName, :vFee, :vAccount,     :vDept,     :vCost,
                            :vFee_Account, :vFee_Dept, :vFee_Cost;

        if (vFee is null) then vFee = 0;

        if ((vDept is null) or (vCost = '')) then vCost = '0000';
        if ((vCost is null) or (vCost = '')) then vCost = '0000';

/*
           -------------------------------
           CASH        |
           FEE         |
                       |  A/R CREDIT CARD
*/
        /* CASH RECIEVE   */
        insert into glbuffer
               (APPLICATION, SOURCE, NUMBER, ID, transdate,
                ACCOUNT, DEPT, COST, PROJECT,
                NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
        values ('AR', 'CCPY', old.batch, :vLine, old.pay_date,
                :vFee_Account, :vFee_Dept, :vFee_Cost, '0000',
                :vName, '', :vTotal*(100-:vFee)/100, 0, 'now', new.edituser);
        vLine = vLine + 1;
        /* A/R FEE       */
        insert into glbuffer
               (APPLICATION, SOURCE, NUMBER, ID, transdate,
                ACCOUNT, DEPT, COST, PROJECT,
                NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
        values ('AR', 'CCPY', old.batch, :vLine, old.pay_date,
                :vFee_Account, :vFee_Dept, :vFee_Cost, '0000',
                :vName, '', :vTotal*:vFee/100, 0, 'now', new.edituser);
        vLine = vLine + 1;

        /* A/R CREDIT CARD */
        insert into glbuffer
               (APPLICATION, SOURCE, NUMBER, ID, transdate,
                ACCOUNT, DEPT, COST, PROJECT,
                NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
        values ('AR', 'CCPY', old.batch, :vLine, old.pay_date,
                :vAccount, :vDept, :vCost, '0000',
                :vName, '', 0, :vTotal, 'now', new.edituser);

        vLine = vLine + 1;

     end


      select ar_bankbook_link from sysparam into :vARBankBook;
      
      if (vARBankBook = 1) then begin
         INSERT INTO BBJUR (NUMBER, BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
                            BBCODE, ACCOUNT, DEPT, COST,
                            DB, CR,
                            NOTE, REMARK, REF,
                            CURRENCY, EXCHANGE,
                            APPLICATION, SOURCE, SOURCENUMBER,
                            CREATE_BY, CREATE_DATE, EDIT_BY,EDIT_DATE)
          VALUES           (0, NEW.BANK, NEW.PAY_DATE, 0, 'T', NEW.PAY_REF,
                            'ARCC', :vBK_Account, :vBK_Dept,'0000',
                            0, new.calc_amount_net,
                            '', :vName, '',
                            'IDR', 1,
                            'AR', 'CCPY', NEW.BATCH,
                            NEW.EDITUSER, 'NOW', NEW.EDITUSER, 'NOW');

      end

  end
end
^

CREATE TRIGGER AR_CARD_BU FOR AR_CARD
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  if (new.fee <> old.fee) then begin
     update ar_card_jur set card_fee = new.fee
     where creditcard = old.creditcard
     and status = 'O';
  end
  
  if (new.bank <> old.bank) then begin
     update ar_card_jur set bank = new.bank
     where creditcard = old.creditcard
     and status = 'O';
  end  
end
^

CREATE TRIGGER AR_CARD_JUR_BD FOR AR_CARD_JUR
ACTIVE BEFORE DELETE POSITION 0
as
declare variable vBank VARCHAR(4);
begin
  if (NOT (old.status IN ('O', 'D'))) then
     exception all_doc_status_not_open;
     
  if (old.batch <> 0) then begin
      select bank from ar_card where creditcard = old.creditcard into :vBank;
      update ar_card_batch set amount = amount - old.total,
             amount_fee = amount_fee-old.calc_fee
      where bank = :vBank and batch = old.batch and outlet = old.outlet;
  end
end
^

CREATE TRIGGER AR_CARD_JUR_BI FOR AR_CARD_JUR
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vBank varchar(4);
declare variable vRow INTEGER;
begin
  select fee, bank from ar_card
  where creditcard = new.creditcard
  into new.card_fee, new.bank;
  
  if (new.batch <> 0) then begin
      select bank from ar_card where creditcard = new.creditcard into :vBank;
      select count(*) from ar_card_batch
      where bank = :vBank and batch = new.batch and outlet = new.outlet
      into :vRow;
      if (vRow = 0) then 
         exception ar_credit_card_batch_not_exist;

      update ar_card_batch set amount = amount + new.total,
             amount_fee = amount_fee+new.calc_fee
      where bank = :vBank and batch = new.batch and outlet = new.outlet;
  end
  NEW.NUMBER = GEN_ID(gen_ar_card_jur,1);
end
^

CREATE TRIGGER AR_CARD_JUR_BU FOR AR_CARD_JUR
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable vRow INTEGER;
begin

  if (old.status <> 'O') then
     exception all_doc_status_not_open;

  if ((old.creditcard <> new.creditcard) and (old.batch <> 0)) then
     exception AR_CREDIT_CARD_CHANGE;


  select fee, bank from ar_card
  where creditcard = new.creditcard
  into new.card_fee, new.bank;

  if (not ((new.status = 'C') and (old.status = 'O'))) then
  if ((new.batch <> old.batch)
      or (new.total <> old.total)
      or (new.card_fee <> old.card_fee))  then begin

     if  ((old.batch <> 0) or
          (new.total <> old.total) or
          (new.card_fee <> old.card_fee)) then begin
         update ar_card_batch set amount = amount - old.total,
                amount_fee = amount_fee-old.calc_fee
         where bank = old.Bank and batch = old.batch and outlet = old.outlet;
     end
  
     if ((new.batch <> 0) or
         (new.total <> old.total) or
         (new.card_fee <> old.card_fee)) then begin

        if (new.batch <> 0) then begin
           select count(*) from ar_card_batch
           where bank = new.Bank and batch = new.batch and outlet = new.outlet
           into :vRow;

           if (vRow = 0) then 
              exception ar_credit_card_batch_not_exist;
              
           update ar_card_batch set amount = amount + new.total,
                  amount_fee = amount_fee+new.calc_fee
           where bank = new.Bank and batch = new.batch and outlet = new.outlet;
        end
     end
  end
end
^

CREATE TRIGGER ARADJ_BDELETE FOR ARADJ
ACTIVE BEFORE DELETE POSITION 0
as
begin
  if (old.status <> 'D') then
  begin
    if (old.status <> 'O') then
        EXCEPTION ALL_DOC_STATUS_NOT_OPEN;
        
     update ARVCH set adjust = adjust - (old.db-old.cr),
      forex_adjust = forex_adjust - (old.forex_db-old.forex_cr)
      where number = old.voucherno;
  end
  else
     insert into ARPURGE (VOUCHERNO, NUMBER, DOCTYPE, DOCUMENT,
                          OPENDATE, DUEDATE, SOURCENUMBER, TOTAL,
                          CUSTOMER, NOTE, DELETEDATE, DELETEUSER)
     values
       (old.voucherno, old.number, 'ADJ', old.document,
       old.opendate, old.opendate, 0, old.db-old.cr,
       old.CUSTOMER, old.NOTE, 'now', user);
end
^

CREATE TRIGGER ARADJ_BINSERT FOR ARADJ
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vCUSTOMER varchar(8);
declare variable vSysDate date;
begin
  select arsysdate from sysparam into :vSysDate;
  if (new.opendate < :vSysDate) then
     exception all_date_error;
  select CUSTOMER, opendate from ARVCH
   where number = new.voucherno into :vCUSTOMER, :vSysDate;
  if (new.opendate < :vSysDate ) then
     exception ar_date_less_than_voucher;
  if (new.number = 0) then
  begin
     select Max(number) from ARADJ into new.number;
     if (new.number is null) then new.number = 1;
     else
     new.number = new.number+1;
  end
  new.createdate = 'now';
  new.CUSTOMER = :vCUSTOMER;
  update ARVCH set
    adjust = adjust  + (new.db-new.cr)
   where number = new.voucherno;     
end
^

CREATE TRIGGER ARADJ_BUPDATE FOR ARADJ
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable vCUSTOMER varchar(8);
declare variable vSysDate date;
begin
  IF (old.Status = 'O' and new.status = 'O') THEN
  begin
    select arsysdate from sysparam into :vSysDate;
    if (new.opendate < :vSysDate) then exception all_date_error;
    select CUSTOMER, opendate from ARVCH
     where number = new.voucherno into :vCUSTOMER, :vSysDate;
    if (new.opendate < :vSysDate ) then exception ar_date_less_than_voucher;
    if (new.CUSTOMER <> :vCUSTOMER) then exception  ar_CUSTOMER_not_match;
    update ARVCH set adjust = adjust  + (new.db-new.cr) - (old.db-old.cr)
     where number = new.voucherno;
  end
  ELSE
     /* jika "STATUS" bukan "O" -> "R" (release)
                            "R" -> "C" (end of day)
     */
 if (not ((old.status IN ('C', 'R', 'O')) and (new.status = 'D'))) then
     begin
       IF (NOT ((old.status = 'O' AND new.status = 'R')  OR
                (old.status = 'O' AND new.status = 'C')  OR
                (old.status = 'R' AND new.status = 'C'))) THEN
          EXCEPTION DOCUMENT_IS_NOT_OPEN;
     end
end
^

CREATE TRIGGER ARADJ_POST_GL FOR ARADJ
ACTIVE AFTER UPDATE POSITION 0
as
declare variable vAccount varchar(20);
declare variable vName VARCHAR(40);
declare variable vRow integer;
begin
  if ((old.status <> 'C') AND (new.status = 'C')) then
  begin
     select name, glaccount from sysCUSTOMER
       left join sysCUSTOMERtype on CUSTOMERtype = CUSTTYPE
      where CUSTOMER = old.CUSTOMER
       into :vname, :vAccount;
     /* --------------------------------------------------------------------- */
     /* adjustment account                                                    */
     /* --------------------------------------------------------------------- */
     if (old.cr <> 0) then vRow = 1;
     else vRow = 2;
     insert into glbuffer
            (APPLICATION, SOURCE, NUMBER, ID, transdate,
             ACCOUNT, DEPT, COST, PROJECT,
             NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
     values ('AR', 'ADJ', old.number, :vRow, old.opendate,
             old.Account, old.Dept, old.Cost, '',
             :vName, new.document, old.cr, old.db, 'now', USER);
     /* --------------------------------------------------------------------- */
     /* CUSTOMER account                                                      */
     /* --------------------------------------------------------------------- */
     if (old.cr <> 0) then vRow = 2;
     else vRow = 1;
     insert into glbuffer
            (APPLICATION, SOURCE, NUMBER, ID, transdate,
             ACCOUNT, DEPT, COST, PROJECT,
             NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
     values ('AR', 'ADJ', old.number, :vRow, old.opendate,
             :vAccount, '', '', '',
             :vName, new.document, old.db, old.cr, 'now', USER);
  end
end
^

CREATE TRIGGER ARCAHS0_BDELETE FOR ARCASH0
ACTIVE BEFORE DELETE POSITION 0
as
begin
  update ARCAshbatch set totalcheck = totalcheck - old.total
   where number = old.batchno;
end
^

CREATE TRIGGER ARCASH0_AU_GIRO_TOLAK FOR ARCASH0
ACTIVE AFTER UPDATE POSITION 0
as
declare variable vAccount varchar(20);
declare variable vDept varchar(4);
declare variable vCost varchar(4);
declare variable vName VARCHAR(40);
declare variable vRow integer;
declare variable vVCH integer;
declare variable vTotal double precision;
declare variable vTotal_forex double precision;
begin
  if ((old.status = 'R') AND (new.status = 'T') AND (new.total <> 0)) then
  begin
     /* CHECK DITERIMA TAPI BELUM CAIR */
     select name from sysCUSTOMER
     where CUSTOMER = old.CUSTOMER
     into :vname;
     /*        ----------------------------------
               db               | cr
               ----------------------------------
               a/r              | giro belum cair
     */
     /* --------------------------------------------------------------------- */
     /* bank account                                                          */
     /* --------------------------------------------------------------------- */
     select gl_account_arprepare, gl_dept_arprepare from sysbank
      where bank = old.bank
       into :vAccount, :vDept;
       
     insert into glbuffer
            (APPLICATION, SOURCE, NUMBER, ID, transdate,
             ACCOUNT, DEPT, COST, PROJECT,
             NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
     values ('AR', 'CASD', old.number, 2, old.opendate,
             :vAccount, :vDept, '0000', '0000',
             :vName, new.document, 0, old.total, 'now', USER);
     /* --------------------------------------------------------------------- */
     /* CUSTOMER account                                                      */
     /* --------------------------------------------------------------------- */    
     select account, gl_dept, gl_cost from sysCUSTOMER
      where CUSTOMER = old.CUSTOMER
       into :vAccount, vDept, vCost;
       
     if ((vAccount is Null) or (vAccount = '')) then
        select glaccount, gldept from sysCUSTOMER
          left join sysCUSTOMERtype on CUSTOMERtype = CUSTTYPE
         where CUSTOMER = old.CUSTOMER
          into :vAccount, vDept;

     if ((vDept is null) or (vCost = '')) then vCost = '0000';
     if ((vCost is null) or (vCost = '')) then vCost = '0000';
          
     insert into glbuffer
            (APPLICATION, SOURCE, NUMBER, ID, transdate,
             ACCOUNT, DEPT, COST, PROJECT,
             NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
     values ('AR', 'CASD', old.number, 1, old.opendate,
             :vAccount, :vDept, :vCost, '0000',
             :vName, new.document, old.total, 0, 'now', new.edituser);
             
     /* recalculate */
     for select voucherno from arcash1
         where number = new.number
         into vVCH
     do
     begin
         update arvch set sourceid = -1
         where Number = :vVCH;
     end
  end
end
^

CREATE TRIGGER ARCASH0_BI FOR ARCASH0
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vCUSTOMER VARCHAR(8);
declare variable vSysDate date;
declare variable vARBANK_TRANSIENT_ACTIVE integer;
declare variable vRow INTEGER;
begin
  if (NEW.SOURCE IS NULL) then NEW.SOURCE = 'LEAS';
  select arsysdate, ARBANK_TRANSIENT_ACTIVE from sysparam
  into :vSysDate, vARBANK_TRANSIENT_ACTIVE;
  
  if (new.opendate < :vSysDate) then
     exception all_date_error;
  if (new.number = 0) then
  begin
     select Max(number) from ARCAsh0 into new.number;
     if (new.number is null) then new.number = 1;
     else
     new.number = new.number+1;
  end
  new.createdate = 'now';
  update ARCAshbatch set totalcheck = totalcheck + new.total
   where number = new.batchno;
   
 if (new.currency is null) then new.currency = 'IDR';
 select exchange from foforex where currency = new.currency
 into new.exchange;
 
 if (vARBANK_TRANSIENT_ACTIVE = 0) then
    if (new.bank is null) then new.bank = '';
 else begin
    select count(*) from SYSBANK
    where bank = new.bank
    into :vrow;
    if (vRow = 0) then
       EXCEPTION AR_BANK_NOT_DEFINE;
 end
end
^

CREATE TRIGGER ARCASH0_BINSERT FOR ARCASH0
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vCUSTOMER VARCHAR(8);
declare variable vSysDate date;
begin
  select arsysdate from sysparam into :vSysDate;
  if (new.opendate < :vSysDate) then
     exception all_date_error;
  if (new.number = 0) then
  begin
     select Max(number) from ARCAsh0 into new.number;
     if (new.number is null) then new.number = 1;
     else
     new.number = new.number+1;
  end
  new.createdate = 'now';
  update ARCAshbatch set totalcheck = totalcheck + new.total
   where number = new.batchno;
end
^

CREATE TRIGGER ARCASH0_BU_RECALC FOR ARCASH0
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable TOTAL DOUBLE PRECISION;
declare variable GAINLOSS DOUBLE PRECISION;
begin
  /* 31-oct-2003*/
  if ((new.total = -1) and (OLD.STATUS = 'O')) then
  begin
     select sum(total), sum(vch_gainloss)
     from arcash1
     where number = new.number
     into total, gainloss;
     
     if (total is null) then
     begin
        TOTAL = 0;
        GAINLOSS = 0;
     END
     if (NEW.TOTAL <> TOTAL) then
        new.total = :TOTAL;
     if (NEW.forex_gainloss <> GAINLOSS) then     
        new.forex_gainloss = GAINLOSS;
  end
end
^

CREATE TRIGGER ARCASH0_BUPDATE FOR ARCASH0
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable vSysDate date;
begin
  IF (old.Status = 'O' and new.status = 'O') THEN
  begin
    select arsysdate from sysparam into :vSysDate;
    if ((new.opendate < :vSysDate) and (new.status = 'O')) then
       exception all_date_error;
    if ((old.total <> new.total) or (old.batchno <> new.batchno)) then
    begin
     if (new.status <> 'O') then
        exception all_doc_status_not_open;
     update ARCAshbatch set totalcheck = totalcheck - old.total
      where number = old.batchno;
     update ARCAshbatch set totalcheck = totalcheck + new.total
      where number = new.batchno;
    end
    /* JIKA DATA SUDAH DIAMBIL DARI BUKU GIRO */
    if (new.bbgiro_apno <> 0) then new.status = 'R';
  end
  ELSE
     /* jika "STATUS" bukan "O" -> "R" (release   ) [MANUAL] : CHECK DITERIMA
                            "R" -> "L" (reconcile ) [MANUAL] : CHECK CAIR
                            "R" -> "C" (end of day) [EOD]
     */
     if (NEW.STATUS = 'T') then /* 12 jan 2004, giro tolak */
     BEGIN
        if (OLD.STATUS <> 'R') then
           EXCEPTION ALL_DOC_STATUS_NOT_RELEASE;
        if (OLD.STATUS = 'T') then
           EXCEPTION DOCUMENT_IS_NOT_OPEN;
     END
     ELSE
     BEGIN
       if (not ((old.status IN ('C', 'R', 'O')) and (new.status = 'D'))) then
       begin
         IF (NOT ((old.status = 'O' AND new.status = 'R')  OR
                  (old.status = 'R' AND new.status = 'L')  OR
                  (old.status = 'L' AND new.status = 'R')  OR
                (old.status = 'L' AND new.status = 'C'))) THEN
            EXCEPTION DOCUMENT_IS_NOT_OPEN;
       end
     END
end
^

CREATE TRIGGER ARCASH0_POST_GL FOR ARCASH0
ACTIVE AFTER UPDATE POSITION 0
as
declare variable vAccount varchar(20);
declare variable vDept varchar(4);
declare variable vCost varchar(4);
declare variable vName VARCHAR(40);
declare variable vRow integer;
declare variable vVCH integer;
declare variable vTotal double precision;
declare variable vTotal_forex double precision;
DECLARE VARIABLE NOTE VARCHAR(40);
DECLARE VARIABLE GL_ACCOUNT VARCHAR(20);
DECLARE VARIABLE GL_DEPT VARCHAR(4);
DECLARE VARIABLE GL_COST VARCHAR(4);
begin
  /* CHECK DITERIMA TAPI BELUM CAIR */
  select name from sysCUSTOMER
   where CUSTOMER = old.CUSTOMER
    into :vname;
         
  if ((old.status = 'O') AND (new.status = 'R') AND (new.total <> 0)) then
  begin
     /*        ----------------------------------
               db               | cr
               ----------------------------------
               giro belum cair  | a/r
     */
     /* --------------------------------------------------------------------- */
     /* bank account                                                          */
     /* --------------------------------------------------------------------- */
     select gl_account_arprepare, gl_dept_arprepare from sysbank
      where bank = old.bank
       into :vAccount, :vDept;
     insert into glbuffer
            (APPLICATION, SOURCE, NUMBER, ID, transdate,
             ACCOUNT, DEPT, COST, PROJECT,
             NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
     values ('AR', 'CASH', old.number, 2, old.opendate,
             :vAccount, :vDept, '0000', '0000',
             :vName, new.document, old.total, 0, 'now', USER);
     /* --------------------------------------------------------------------- */
     /* CUSTOMER account                                                      */
     /* --------------------------------------------------------------------- */    
     select account, gl_dept, gl_cost from sysCUSTOMER
      where CUSTOMER = old.CUSTOMER
       into :vAccount, vDept, vCost;
       
     if ((vAccount is Null) or (vAccount = '')) then
        select glaccount, gldept from sysCUSTOMER
          left join sysCUSTOMERtype on CUSTOMERtype = CUSTTYPE
         where CUSTOMER = old.CUSTOMER
          into :vAccount, vDept;

     if ((vDept is null) or (vCost = '')) then vCost = '0000';
     if ((vCost is null) or (vCost = '')) then vCost = '0000';
          
     insert into glbuffer
            (APPLICATION, SOURCE, NUMBER, ID, transdate,
             ACCOUNT, DEPT, COST, PROJECT,
             NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
     values ('AR', 'CASH', old.number, 1, old.opendate,
             :vAccount, :vDept, :vCost, '0000',
             :vName, new.document, 0, old.total, 'now', new.edituser);
             
     for select voucherno, total, forex_total from arcash1
         where number = new.number
         into vVCH, vTotal, vTotal_forex do
     begin
         update arvch set paidprepare = paidprepare - :vTotal,
                          forex_paidprepare = forex_paidprepare - :vTotal_forex,
                          paid = paid + :vTotal
         where Number = :vVCH;
     end
     /* recalculate */
     for select voucherno from arcash1
         where number = new.number
         into vVCH
     do
     begin
         update arvch set sourceid = -1
         where Number = :vVCH;
     end
  end
  /* ------------------------------------------------------ */
  /* CHECK SUDAH CAIR (TELAH DIRECONCILE) STATUS "L" -> "C" */
  /* PROSES PERUBAHAN DILAKUKAN PADA EOD                    */
  /* ------------------------------------------------------ */
  if ((old.status = 'L') AND (new.status = 'C') AND (new.total <> 0)) then
  begin
     /* --------------------------------------------------------------------- */
     /* EXPORT TO BANK BOOK                                                   */
     /* --------------------------------------------------------------------- */
     IF (NOT EXISTS(SELECT * from sysbank where bank = old.bank)) THEN
        exception AR_BANK_NOT_DEFINE;


     select name from sysCUSTOMER where CUSTOMER = old.CUSTOMER
     into :NOTE;
     
     select gl_account_arprepare, gl_dept_arprepare, gl_cost_arprepare from sysbank
     where bank = old.bank
     into :GL_ACCOUNT, :GL_DEPT, :GL_COST;
     
     INSERT INTO BBJUR (NUMBER, BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
                        BBCODE, ACCOUNT, DEPT, COST,
                        FOREX_DB, FOREX_CR,
                        REMARK,  REF,
                        CURRENCY, EXCHANGE,
                        APPLICATION, SOURCE, SOURCENUMBER, SOURCEID,
                        CREATE_BY, CREATE_DATE, EDIT_BY,EDIT_DATE)
     VALUES           (0, NEW.BANK, old.RECONCILEDATE, 0, 'O', NEW.CHECK_NUMBER,
                       'AR', :GL_ACCOUNT, :GL_DEPT, :GL_COST,
                        0, old.forex_total,
                        :NOTE,NEW.NUMBER,
                        OLD.CURRENCY, OLD.EXCHANGE,
                        'AR', 'REC', NEW.NUMBER, 0,
                        NEW.EDITUSER, 'NOW', NEW.EDITUSER, 'NOW');            


   end   
end
^

CREATE TRIGGER ARCASH1_BDELETE FOR ARCASH1
ACTIVE BEFORE DELETE POSITION 0
as
declare variable vStatus CHAR(1);
declare variable vCheck_Number varchar(20);
declare variable vOpenDate date;
declare variable vDueDate date;
begin
  select Status, Check_Number, OpenDate, DueDate from ARCAsh0
    where number = old.number
    into :vStatus, vCheck_Number, vOpenDate, vDueDate;
  if (vStatus <> 'D') then
  begin
    if (vStatus <> 'O') then exception all_doc_status_not_open;

    /* hapus prepare payment */
    update ARVCH set paidprepare = paidprepare - old.total,
     forex_paidprepare = forex_paidprepare - old.forex_total,
     forex_gainloss = forex_gainloss - old.vch_gainloss /* 19 sep 2002 */
     where number = old.voucherno;
     
    update ARCAsh0 set total = total - old.total,
           forex_gainloss = forex_gainloss - old.vch_gainloss /* 19 sep 2002 */
     where number = old.number;
  end

/*
  else
    insert into ARPURGE (VOUCHERNO, NUMBER, DOCTYPE, DOCUMENT,
                         OPENDATE, DUEDATE, SOURCENUMBER, TOTAL, FOREX_TOTAL,
                         CUSTOMER, NOTE, DELETEDATE, DELETEUSER)
     values
       (old.voucherno, old.number, 'CASH', :vCheck_Number,
        :vOpenDate, :vDueDate, 0, old.total, old.forex_total,
        old.CUSTOMER, old.text1, 'now', user);
*/
end
^

CREATE TRIGGER ARCASH1_BINSERT FOR ARCASH1
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vStatus CHAR(1);
declare variable vCashDate DATE;
declare variable vVoucherDate DATE;
declare variable vVoucherCUSTOMER VARCHAR(8);
declare variable vCUSTOMER VARCHAR(8);
declare variable vVCHCurrency VARCHAR(4);
declare variable vtotaldue double precision ;
begin
  select Status, OpenDate, CUSTOMER,
  CURRENCY, EXCHANGE /* 17 APRIL 2002 */
  from ARCAsh0
    where number = new.number
    into :vStatus, :vCashDate, :vCUSTOMER,
  NEW.CURRENCY, NEW.EXCHANGE; /* 17 APRIL 2002 */
    
  select OpenDate, CUSTOMER,
         CURRENCY,totaldue /* 17 APRIL 2002 */
  from ARVCH
   where number = new.voucherno
    into :vVoucherDate, NEW.CUSTOMER,
         vVCHcurrency,vtotaldue ; /* 17 APRIL 2002 */
    
  if (vVoucherCUSTOMER is null) then exception ar_vchr_not_exist;
  if (NEW.CUSTOMER <> vCUSTOMER) then exception ar_CUSTOMER_not_match;
  if (vVoucherDate > vCashDate) then exception ar_date_less_than_voucher;
  if (vVCHCurrency <> new.currency) then exception AR_DIFFRENT_CURRENCY; /* 17 APRIL 2002 */
  if (vtotaldue < new.total ) then exception ar_payment_over_then_voucher ;
  



  /* -> START <- 19 SEP 2002 */
  SELECT EXCHANGE FROM ARVCH
  WHERE NUMBER = NEW.VOUCHERNO
  INTO NEW.VCH_EXCHANGE;
  /* -> END <- 19 SEP 2002 */
  
  update ARCAsh0 set total = total + new.total,
         forex_gainloss = forex_gainloss + new.vch_gainloss /* 19 sep 2002 */
   where number = new.number;
     
  update ARVCH set paidprepare = paidprepare + new.total,
                   forex_paidprepare = forex_paidprepare + new.forex_total, /* 17 APRIL 2002 */
                   forex_gainloss = forex_gainloss + new.vch_gainloss /* 19 sep 2002 */
   where number = new.voucherno;
end
^

CREATE TRIGGER ARCASH1_BUPDATE FOR ARCASH1
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable vStatus CHAR(1);
declare variable vCashDate DATE;
declare variable vVoucherDate DATE;
declare variable vCUSTOMER VARCHAR(8);
declare variable vVoucherCUSTOMER VARCHAR(8);
declare variable vVCHCurrency VARCHAR(4);
begin
  if (old.number <> new.number) then
     exception all_detail_number_change;
     
  select Status, OpenDate, CUSTOMER,
         currency, exchange /* 17 APRIL 2002 */
    from ARCAsh0
    where number = new.number
    into :vStatus, :vCashDate, :vCUSTOMER,
         new.currency, new.exchange; /* 17 APRIL 2002 */
    
  if (vStatus <> 'O') then
     exception all_doc_status_not_open;
     
  select OpenDate, CUSTOMER, currency from ARVCH
   where number = new.voucherno
    into :vVoucherDate, NEW.CUSTOMER,
         vVCHCurrency; /* 17 APRIL 2002 */
    
  if (vVoucherCUSTOMER is null) then
     exception ar_vchr_not_exist;
  if (NEW.CUSTOMER <> vCUSTOMER) then
     exception ar_CUSTOMER_not_match;
  if (vVoucherDate > vCashDate) then
     exception ar_date_less_than_voucher;
     
  if (new.currency <> vVCHCurrency) then exception ar_diffrent_currency; /* 17 APRIL 2002 */

  /* -> START <- 19 SEP 2002 */
  SELECT EXCHANGE FROM ARVCH
  WHERE NUMBER = NEW.VOUCHERNO
  INTO NEW.VCH_EXCHANGE;
  /* -> END <- 19 SEP 2002 */


  update ARCAsh0 set total = total - old.total,
         forex_gainloss = forex_gainloss - old.vch_gainloss /* 19 sep 2002 */
   where number = old.number;
   
  update ARCAsh0 set total = total + new.total,
         forex_gainloss = forex_gainloss + new.vch_gainloss /* 19 sep 2002 */
   where number = new.number;   


  /* check preparation */
  update ARVCH set paidprepare = paidprepare - old.total,
        forex_paidprepare = forex_paidprepare - old.forex_total,
        forex_gainloss = forex_gainloss - old.vch_gainloss /* 19 sep 2002 */
  where number = old.voucherno;
  
  update ARVCH set paidprepare = paidprepare + new.total,
         forex_paidprepare = forex_paidprepare + new.forex_total,
         forex_gainloss = forex_gainloss + new.vch_gainloss /* 19 sep 2002 */
  where number = new.voucherno;

end
^

