CREATE TRIGGER ARVCH_AU_EOD FOR ARVCH
ACTIVE AFTER UPDATE POSITION 0
AS
declare variable vAccount varchar(20);
declare variable vDept varchar(4);
declare variable vCost varchar(4);
declare variable vName VARCHAR(40);
declare variable vRow integer;
declare variable vVCH integer;
declare variable vTotal double precision;
declare variable vARBANK_TRANSIENT_ACTIVE integer;
declare variable vBK_Account varchar(20);
declare variable vBK_Dept varchar(4);
declare variable vDebug integer;
begin
  /* ------------------------------------------------------------------------ */
  /* 27 MAY 2003                                                              */
  /*        GLSTATUS ->   Open (O) ==> Close (C)                              */
  /* perubahan terjadi pada saat EOD, see FOSYSPARAM_AR_EOD TRINGGER          */
  /* ------------------------------------------------------------------------ */
  if ((old.glstatus = 'O') AND (new.glstatus = 'C') AND (new.total <> 0)) then
  begin
     /*        -----------------------------------
               db               | cr
               -----------------------------------
               a/r per customer | a/r transient
     */
     /* --------------------------------------------------------------------- */
     /* A/R TRANSIENT account                                                 */
     /* --------------------------------------------------------------------- */
     select  ARVCH_TRANSIENT_ACC, ARVCH_TRANSIENT_DEPT, ARVCH_TRANSIENT_COST  from sysparam
     into :vAccount, :vDept, vCost;
     if (vAccount is null) then vAccount = '';
     if (vAccount <> '') then
     begin
       /* ------------------------------------------------------------------- */
       /* CUSTOMER NAME                                                       */
       /* ------------------------------------------------------------------- */
       select name from sysCUSTOMER
       where CUSTOMER = old.CUSTOMER
       into :vname;
       /* ------------------------------------------------------------------- */
       /* CUSTOMER account                                                    */
       /* ------------------------------------------------------------------- */
       select account, gl_dept, gl_cost from sysCUSTOMER
       where CUSTOMER = old.CUSTOMER
       into :vAccount, vDept, vCost;
       /* find customer a/p account */
       if ((vAccount is Null) or (vAccount = '')) then
          select glaccount, gldept from sysCUSTOMER
            left join sysCUSTOMERtype on CUSTOMERtype = CUSTTYPE
           where CUSTOMER = old.CUSTOMER
            into :vAccount, vDept;
       if ((vDept is null) or (vDept = '')) then vDept = '0000';
       if ((vCost is null) or (vCost = '')) then vCost = '0000';
       /* customer account */
       insert into glbuffer
            (APPLICATION, SOURCE, NUMBER, ID, transdate,
             ACCOUNT, DEPT, COST, PROJECT,
             NOTE, REF,
             DB, CR,
             EXPORTDATE, EXPORTUSER)
       values ('AR', 'VCH', old.number, 1, old.opendate,
             :vAccount, :vDept, :vCost, '0000',
             :vName, new.document,
             old.total, 0,
             'now', new.edituser);       
       /* ------------------------------------------------------------------- */
       /* a/r transient                                                       */
       /* ------------------------------------------------------------------- */
       select  ARVCH_TRANSIENT_ACC, ARVCH_TRANSIENT_DEPT, ARVCH_TRANSIENT_COST
       from sysparam
       into :vAccount, :vDept, vCost;
       
       if ((vDept is null) or (vDept = '')) then vDept = '0000';
       if ((vCost is null) or (vCost = '')) then vCost = '0000';
       
       insert into glbuffer
            (APPLICATION, SOURCE, NUMBER, ID, transdate,
             ACCOUNT, DEPT, COST, PROJECT,
             NOTE, REF,
             DB, CR,
             EXPORTDATE, EXPORTUSER)
       values ('AR', 'VCH', old.number, 2, old.opendate,
             :vAccount, :vDept, :vCost, '0000',
             :vName, new.document,
             0, old.total,
             'now', new.edituser);

    end
  end
end
^

CREATE TRIGGER ARVCH_BDELETE FOR ARVCH
ACTIVE BEFORE DELETE POSITION 0
as
declare variable PYEAR INTEGER;
declare variable PMONTH INTEGER;
declare variable VROW INTEGER;
begin
  if (old.status <> 'D') then begin
     update sysCUSTOMER
        set totalar = totalar - old.totaldue where CUSTOMER = old.CUSTOMER;
  end
  else
    insert into ARPURGE (VOUCHERNO, NUMBER, DOCTYPE, DOCUMENT,
                          OPENDATE, DUEDATE, SOURCENUMBER, TOTAL,
                          CUSTOMER, NOTE, DELETEDATE, DELETEUSER)
     values
       (old.number, old.number, 'VCH', old.document,
       old.opendate, old.opendate, 0, old.total,
       old.CUSTOMER, OLD.NOTE, 'now', user);

end
