CREATE TRIGGER ARVCH_BINSERT FOR ARVCH
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vSysDate date;
begin
  select arsysdate from sysparam into :vSysDate;
  if (new.opendate < :vSysDate) then
  begin
    new.duedate = :vSysDate + (new.duedate-new.opendate);
    new.opendate = :vSysDate;
  end
  /* Trigger Text */
  if (new.number = 0) then
  begin
     select Max(number) from ARVCH into new.number; 
     if (new.number is null) then new.number = 1;
     else
     new.number = new.number+1;
  end
  new.createdate = 'now';
  update sysCUSTOMER
     set totalar = totalar + new.total
  where CUSTOMER = new.CUSTOMER;

  SELECT NAME, ADDRESS1, ADDRESS2, ADDRESS3, ADDRESS4, PHONE, FAX FROM SYSCUSTOMER
  WHERE CUSTOMER = NEW.CUSTOMER
  INTO NEW.NAME, NEW.ADDRESS1, NEW.ADDRESS2, NEW.ADDRESS3, NEW.ADDRESS4,
       NEW.PHONE, NEW.FAX;
end
^

CREATE TRIGGER ARVCH_BU_RECALC FOR ARVCH
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable paidprepare DOUBLE PRECISION;
declare variable forex_paidprepare DOUBLE PRECISION;
declare variable paid DOUBLE PRECISION;
declare variable forex_paid DOUBLE PRECISION;
declare variable adjust DOUBLE PRECISION;
declare variable forex_adjust DOUBLE PRECISION;

declare variable forex_gainloss DOUBLE PRECISION;
begin
  /* Trigger Text */
  if (NEW.SOURCEID = -1) then
  BEGIN
     NEW.SOURCEID = OLD.SOURCEID;
     SELECT SUM(D.total), SUM(D.forex_total), SUM(D.vch_gainloss) FROM  ARCASH1 D
     LEFT JOIN ARCASH0 H ON H.NUMBER = D.NUMBER
     WHERE D.VOUCHERNO = NEW.NUMBER
     AND H.STATUS = 'O'
     INTO paidprepare, forex_paidprepare, forex_gainloss;
     if (paidprepare is null) then
     begin
        paidprepare  = 0;
        forex_paidprepare = 0;
        forex_gainloss = 0;
     end
     new.paidprepare = paidprepare;
     new.forex_paidprepare = forex_paidprepare;
     new.forex_gainloss = forex_gainloss;
     
     SELECT SUM(D.total), SUM(D.forex_total), SUM(D.vch_gainloss) FROM  ARCASH1 D
     LEFT JOIN ARCASH0 H ON H.NUMBER = D.NUMBER
     WHERE D.VOUCHERNO = NEW.NUMBER
     AND H.STATUS IN ('R','L','C')
     INTO paid, forex_paid,forex_gainloss;
     
     if (paid is null) then
     begin
        paid = 0;
        forex_paid = 0;
        forex_gainloss = 0;
     end
     
     new.paid = paid;
     new.forex_paid = forex_paid;
     new.forex_gainloss = new.forex_gainloss + forex_gainloss;
     /* ADJUSTMENT */
     select sum(db-cr), sum(forex_db-forex_cr)
     from aradj
     where voucherno = new.number
     into new.adjust, new.forex_adjust;
     
     if (new.adjust is null) then
     begin
        new.adjust = 0;
        new.forex_adjust = 0;
     end
     
     SELECT SUM(TOTAL), SUM(FOREX_TOTAL)
     FROM ARDEPOS1
     where voucherno = new.number
     INTO NEW.DEPOSIT, NEW.FOREX_DEPOSIT;
     if (NEW.DEPOSIT IS NULL) then
     BEGIN
        NEW.DEPOSIT = 0;
        NEW.FOREX_DEPOSIT = 0;
     END
  END
  IF (NEW.NAME IS NULL) THEN
  BEGIN
     SELECT NAME, ADDRESS1, ADDRESS2, ADDRESS3, ADDRESS4, PHONE, FAX FROM SYSCUSTOMER
     WHERE CUSTOMER = NEW.CUSTOMER
     INTO NEW.NAME, NEW.ADDRESS1, NEW.ADDRESS2, NEW.ADDRESS3, NEW.ADDRESS4,
          NEW.PHONE, NEW.FAX;
  END
end
^

CREATE TRIGGER ARVCH_BUPDATE FOR ARVCH
ACTIVE BEFORE UPDATE POSITION 9
AS
declare variable iRow Integer;
declare variable vSysDate date;
declare variable PYEAR INTEGER;
declare variable PMONTH INTEGER;
declare variable VROW INTEGER;
begin
  select arsysdate from sysparam into :vSysDate;
  
  new.editdate = 'now';

/*  if (new.forex_totaldue < -0.001) then exception ar_over_paid;*/

  if ((new.forex_totaldue < 0.01) and (new.forex_totaldue > -0.01) and (new.forex_total <> 0)) then begin
     new.paidstatus = 'P';
     new.status = 'C';
  end
  else begin
    new.paidstatus = 'O';
    new.status = 'O';    
  end
  
  if (new.forex_paidprepare <> 0) then
  begin
     new.paidstatus = 'O';
     new.status = 'R';
  end  
  /* LEASE STATUS */
  if (NEW.SOURCE = 'LEAS') then
  BEGIN
     UPDATE TN_LEASE_JUR SET AR_PAID = NEW.PAID + NEW.DEPOSIT - NEW.ADJUST,
            AR_STATUS = NEW.STATUS
     WHERE TRANS_ID = NEW.SOURCEID;
  END


  update sysCUSTOMER set totalar = totalar - old.totaldue
  where CUSTOMER = old.CUSTOMER;
  
  update sysCUSTOMER set totalar = totalar + new.totaldue
  where CUSTOMER = new.CUSTOMER;
end
