CREATE TRIGGER BBACC_AU FOR BBACC
ACTIVE AFTER UPDATE POSITION 0
as
DECLARE VARIABLE M0 INTEGER;
DECLARE VARIABLE M1 INTEGER;
DECLARE VARIABLE NDATE DATE;
begin
  if ((new.ending <> old.ending) or (new.forex_ending <> old.forex_ending)) then
  BEGIN
     NDATE = NEW.BBDATE - 1; /* POSTING SAMPAI TANGGAL SATI BERIKUTNYA, KALAU GAK BISA STACK OVERFLOW */
     M0 = EXTRACT(MONTH FROM NEW.BBDATE);
     M1 = EXTRACT(MONTH FROM NDATE);

     IF (M0 = M1) THEN
     BEGIN
       update bbacc set opening = new.ending,
       forex_opening = new.forex_ending
       where bank = new.bank
       and bbdate = new.bbdate+1;
     END
  end
end
^

CREATE TRIGGER BBACC_BI FOR BBACC
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vDay   integer;
declare variable vMonth integer;
declare variable vYear  integer;
declare variable vEOM   date;
begin
  EXECUTE PROCEDURE SP_Day(NEW.BBDATE) RETURNING_VALUES(vDay);
  EXECUTE PROCEDURE SP_ENDOFMONTH(NEW.BBDATE) RETURNING_VALUES(vEOM);

  NEW.DB = 0;
  NEW.CR = 0;
  NEW.ENDING = 0;
  NEW.FOREX_ENDING = 0;
  NEW.GAINLOSS = 0;
  NEW.EXCHANGE = 1;

  SELECT ENDING, FOREX_ENDING FROM BBACC
  WHERE BANK = NEW.BANK 
  AND BBDATE = NEW.BBDATE - 1
  INTO NEW.OPENING, NEW.FOREX_OPENING;

  if (NEW.OPENING IS NULL) then NEW.OPENING = 0;
  if (vEOM = NEW.BBDATE) then NEW.FLAG_EOM = 1;
  ELSE NEW.FLAG_EOM = 0;
  
  SELECT CURRENCY FROM SYSBANK
  WHERE BANK = NEW.BANK
  INTO NEW.CURRENCY;
end

