CREATE TRIGGER BBACC_BI_PERIODE FOR BBACC
ACTIVE BEFORE INSERT POSITION 1
AS
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;

DECLARE VARIABLE GLYEAR INTEGER;
DECLARE VARIABLE GLMONTH INTEGER;
BEGIN
  /* -------------------------------------------------------------------- */
  /* 3/14/2012                                                            */
  /* LOCK SUPAYA GAK BISA DIUBAH DILUAR PERIODE YANG BERJALAN             */
  /* -------------------------------------------------------------------- */
  SELECT GLYEAR, GLMONTH FROM SYSPARAM WHERE ID=1 INTO GLYEAR, GLMONTH;
  EXECUTE PROCEDURE SP_DATE_EXTRACT_MONTHYEAR(NEW.BBDATE) RETURNING_VALUES(PMONTH, PYEAR); /* 3/14/2012 */
  IF (GLYEAR*12+GLMONTH > PYEAR*12+PMONTH) THEN
     EXCEPTION ALL_DATE_ERROR 'Access denied, G/L Period: '||GLMONTH||'-'||GLYEAR||', Trans. Period: '||PMONTH||'-'||PYEAR;
END

^

CREATE TRIGGER BBACC_BU FOR BBACC
ACTIVE BEFORE UPDATE POSITION 0
as
DECLARE VARIABLE EOM DATE;
/* 2 desember 2006 */
DECLARE VARIABLE BB_NO_GAINLOSS INTEGER;






begin
  /* ------------------------------------------------------------------------ */
  /* recalculate                                                              */
  /* ------------------------------------------------------------------------ */
  if (new.status = 'r') then
  begin
     /* --------------------------------------------------------------------- */
     /* LOAD DETAIL TRANSACTION                                               */
     /* --------------------------------------------------------------------- */
     select sum(cr), sum(db), sum(forex_cr), sum(forex_db)
     from bbjur
     WHERE BANK = NEW.BANK
     AND BBDATE = NEW.BBDATE
     INTO NEW.DB, NEW.CR, NEW.FOREX_DB, NEW.FOREX_CR;
     if (NEW.DB IS NULL) then NEW.DB = 0;
     if (NEW.CR IS NULL) then NEW.CR = 0;
     if (NEW.FOREX_DB IS NULL) then NEW.FOREX_DB = 0;
     if (NEW.FOREX_CR IS NULL) then NEW.FOREX_CR = 0;
     SELECT ENDING, FOREX_ENDING FROM BBACC
     WHERE BANK = NEW.BANK
     AND BBDATE = NEW.BBDATE-1
     INTO NEW.OPENING, NEW.FOREX_OPENING;
     IF (NEW.OPENING IS NULL) THEN
     BEGIN
         NEW.OPENING = 0;
         NEW.FOREX_OPENING = 0;
     END
     new.status = old.status;
  end
  /* --------------------------------------------------------------------- */
  /* LOAD CURRENCY EXCHANGE                                                */
  /* --------------------------------------------------------------------- */
  /* 16 JUNI 2005 */
  SELECT EXCHANGE FROM SYSCURRENCY_LOG
  WHERE CURRENCY = NEW.CURRENCY AND OPENDATE = NEW.BBDATE
  INTO NEW.EXCHANGE;
     
  IF (NEW.EXCHANGE IS NULL) THEN
     SELECT EXCHANGE FROM SYSCURRENCY WHERE CURRENCY = NEW.CURRENCY
     INTO NEW.EXCHANGE;

  IF (NEW.EXCHANGE IS NULL) THEN
     NEW.EXCHANGE = OLD.EXCHANGE;
  /* 16 JUNI 2005 */
  /* ------------------------------------------------------------------------ */
  /* CALCULATE ENDING                                                         */
  /* ------------------------------------------------------------------------ */  
  NEW.FOREX_ENDING = NEW.FOREX_OPENING + NEW.FOREX_DB - NEW.FOREX_CR;

  EXECUTE PROCEDURE SP_ENDOFMONTH(NEW.BBDATE) RETURNING_VALUES(EOM);

  IF (NEW.BBDATE = EOM) THEN NEW.FLAG_EOM = 1;
  ELSE NEW.FLAG_EOM = 0;

  /* ---------------------------------------------------------------- */
  /* 2 DESEMBER 2006                                                  */
  /* ---------------------------------------------------------------- */
  SELECT BB_NO_GAINLOSS FROM SYSPARAM INTO BB_NO_GAINLOSS;
  IF (BB_NO_GAINLOSS IS NULL) THEN BB_NO_GAINLOSS = 0;

  IF (BB_NO_GAINLOSS = 1) THEN NEW.FLAG_EOM = 0; /* tidak pernah ada end of month, jadi tidak dihitung gain & loss */



  /* ---------------------------------------------------------------- */
  /* 2 DESEMBER 2006                                                  */
  /* ---------------------------------------------------------------- */

  if ((NEW.FLAG_EOM = 0) or (NEW.GAINLOSS IS NULL)) then NEW.GAINLOSS = 0;

  NEW.ENDING_BEFORE_GAINLOSS = NEW.OPENING + NEW.DB-NEW.CR;

  if (NEW.FLAG_EOM = 0) then
     NEW.ENDING = NEW.OPENING + NEW.DB-NEW.CR;

  if (NEW.FLAG_EOM = 1) then
  begin
     new.ending   = new.exchange * new.forex_ending;
     new.gainloss = new.ending - (NEW.OPENING + NEW.DB-NEW.CR);
  end
  /* ------------------------------------------------------------------------ */
  /* release                                                                  */
  /* ------------------------------------------------------------------------ */  
  if ((old.status = 'O') and (new.status = 'R')) then begin
     select sum(cr), sum(db), sum(forex_cr), sum(forex_db)
     from bbjur
     WHERE BANK = NEW.BANK
     AND BBDATE = NEW.BBDATE
     INTO NEW.DB, NEW.CR, NEW.FOREX_DB, NEW.FOREX_CR;
     
     if (NEW.DB IS NULL) then NEW.DB = 0;
     if (NEW.CR IS NULL) then NEW.CR = 0;
     if (NEW.FOREX_DB IS NULL) then NEW.FOREX_DB = 0;
     if (NEW.FOREX_CR IS NULL) then NEW.FOREX_CR = 0;
  end
end

^

CREATE TRIGGER BBACC_BU_PERIODE FOR BBACC
ACTIVE BEFORE UPDATE POSITION 0
AS
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;

DECLARE VARIABLE GLYEAR INTEGER;
DECLARE VARIABLE GLMONTH INTEGER;
BEGIN
  /* -------------------------------------------------------------------- */
  /* 3/14/2012                                                            */
  /* LOCK SUPAYA GAK BISA DIUBAH DILUAR PERIODE YANG BERJALAN             */
  /* -------------------------------------------------------------------- */
  IF (NEW.OPENING = OLD.OPENING) THEN /* 4/12/2012 */
  BEGIN
      SELECT GLYEAR, GLMONTH FROM SYSPARAM WHERE ID=1 INTO GLYEAR, GLMONTH;
      EXECUTE PROCEDURE SP_DATE_EXTRACT_MONTHYEAR(NEW.BBDATE) RETURNING_VALUES(PMONTH, PYEAR); /* 3/14/2012 */
      IF (GLYEAR*12+GLMONTH > PYEAR*12+PMONTH) THEN
         EXCEPTION ALL_DATE_ERROR 'Access denied, G/L Period: '||GLMONTH||'-'||GLYEAR||', Trans. Period: '||PMONTH||'-'||PYEAR;
  END
END

^

CREATE TRIGGER BBACC_BU_REOPEN FOR BBACC
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  /* 12 APRIL 2005 */
  if ((NEW.STATUS = 'O') AND (OLD.STATUS = 'R')) then
  BEGIN
     /* DELETE GL TRANSACTION */
     UPDATE GLTRANS SET STATUS = 'R', NOTE = 'Re-open by Bank Book'
     WHERE PYEAR = NEW.GL_PYEAR
     AND PMONTH = NEW.GL_PMONTH
     AND TRANSNO = NEW.GL_TRANSNO;
     
     DELETE FROM GLJUR 
     WHERE PYEAR = NEW.GL_PYEAR
     AND PMONTH = NEW.GL_PMONTH
     AND TRANSNO = NEW.GL_TRANSNO;     
  END
end
^

CREATE TRIGGER BBACC_POST_TO_GL FOR BBACC
ACTIVE BEFORE UPDATE POSITION 1
as
declare variable vAccount VARCHAR(20);
declare variable vDept VARCHAR(4);
declare variable vCost VARCHAR(4);
declare variable vDB double precision;
declare variable vCR double precision;
declare variable vNumber INTEGER;
declare variable vNote VARCHAR(40);
declare variable vRef VARCHAR(20);
declare variable vBBAccount VARCHAR(20);
declare variable vBBDept VARCHAR(4);
declare variable vBBCost VARCHAR(4);
declare variable vExportType CHAR(1);
declare variable vTotDB double precision;
declare variable vTotCR double precision;
declare variable vApplication VARCHAR(4);
declare variable vSource VARCHAR(4);
declare variable vSourceNumber INTEGER;
declare variable vJurCode VARCHAR(4);
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE DOC VARCHAR(20);
DECLARE VARIABLE EOM DATE;
begin
  EXECUTE PROCEDURE SP_ENDOFMONTH(new.bbdate) RETURNING_VALUES(EOM);
  IF ((OLD.STATUS = 'O') AND (NEW.STATUS = 'R') AND
      ((NEW.BBDATE = EOM) OR /* 16 MAY 2008, SUPAYA HITUNG EOM LOSS & GAIN WALAUPUN TIDAK ADA TRANSAKSI */
       (EXISTS (SELECT * FROM BBJUR WHERE BANK = NEW.BANK AND BBDATE = NEW.BBDATE)))) THEN
  begin
  
     SELECT GL_ACCOUNT, GL_DEPT, GL_COST, JURCODE FROM SYSBANK
     WHERE BANK = OLD.BANK
     INTO :VBBACCOUNT, :VBBDEPT, :VBBCOST, VJURCODE;
     
     /* --------------------------------------------------------------------- */
     /* CALC DOCUMENT NUMBER                                                  */
     /* --------------------------------------------------------------------- */
     SELECT PYEAR, PMONTH FROM GLPERIOD
     WHERE NEW.BBDATE BETWEEN DATE_START AND DATE_END
     AND (PYEAR <> 0) AND (PMONTH <> 0)
     INTO NEW.GL_PYEAR, NEW.GL_PMONTH;


     IF ((NEW.GL_PYEAR = 0) OR (NEW.GL_PYEAR IS NULL)) THEN
     BEGIN
        NEW.GL_PYEAR = EXTRACT (YEAR FROM NEW.BBDATE);
        NEW.GL_PMONTH = EXTRACT (MONTH FROM NEW.BBDATE);
     END
     D = EXTRACT (DAY FROM NEW.BBDATE);

     DOC = NEW.BANK||'/'||NEW.GL_PYEAR||'/'||NEW.GL_PMONTH||'/'||D;
     
     IF (NOT EXISTS(SELECT * FROM GLTRANS WHERE (PYEAR = NEW.GL_PYEAR)
                    AND (PMONTH = NEW.GL_PMONTH)
                    AND (TRANSNO = NEW.GL_TRANSNO)
                    AND (TRANSDATE = NEW.BBDATE)
                    AND (SOURCE = 'BB')
                    AND (DOCUMENT = :DOC))) THEN
     BEGIN
        /* ---------------------------------------------------------------- */
        /* 27 MAY 2008                                                      */
        /* GET TRANSACTION NUMBER                                           */
        /* ---------------------------------------------------------------- */

        
        
        /* GET TRANSACTION ID */
        SELECT MAX(TRANSNO) TRANSNO FROM GLTRANS
        WHERE PYEAR = NEW.GL_PYEAR
        AND PMONTH = NEW.GL_PMONTH
        INTO NEW.GL_TRANSNO;
        IF (NEW.GL_TRANSNO IS NULL) THEN NEW.GL_TRANSNO = 0;
        NEW.GL_TRANSNO = NEW.GL_TRANSNO + 1;
        /* ---------------------------------------------------------------- */
        /* 27 MAY 2008, END OF TRANSACTION NO                               */
        /* ---------------------------------------------------------------- */
        
     
        INSERT INTO GLTRANS
         (PYEAR, PMONTH, TRANSNO, DOCUMENT, JURCODE,
          TRANSDATE, STATUS, REFACCOUNT,
          APPLICATION, SOURCE, SOURCENUMBER, DB, CR,
          CREATEUSER, EDITUSER)
         VALUES
         (NEW.GL_PYEAR, NEW.GL_PMONTH, NEW.GL_TRANSNO, :DOC, :vJurCode,
          NEW.BBDATE, 'H', '',
          'GL', 'BB', 0, 0, 0,
          NEW.POST_BY, NEW.POST_BY);
     END
     ELSE
     BEGIN
       UPDATE GLTRANS SET CREATEUSER = NEW.POST_BY, EDITUSER = NEW.POST_BY,
              NOTE = 'Export from Bank Book', DOCUMENT = :DOC,
              TRANSDATE = NEW.BBDATE,
              APPLICATION = 'GL', SOURCE='BB'
       WHERE PYEAR = NEW.GL_PYEAR
       AND PMONTH = NEW.GL_PMONTH
       AND TRANSNO = NEW.GL_TRANSNO;
     END
     /* --------------------------------------------------------------------- */
  
     SELECT BBEXPORT_TYPE FROM sysparam WHERE ID = 1
     INTO :vExportType;
     
     if (vExportType is null) then vExportType = 'D';
     
     vTotDB = 0;
     vTotCR = 0;
     for select number, account, dept, cost, db, cr, ref, remark,
                Application, Source, SourceNumber
         from bbjur
         where bank = new.bank and bbdate = new.bbdate
         order by bbline
         into vNumber, vAccount, vDept, vCost, vDB, vCR, vRef, vNote,
              vApplication, vSource, vSourceNumber
     do
     begin
         if (not exists (select * from glcoadept where account = :vAccount and depart = :vDept)) THEN
         BEGIN
            /* 20 AGUSTUS 2007*/
            exception gl_coa_dept 'Dept "'||vDept||'" not valid for A/C "'|| vAccount||'"';
         END

         if (not exists (select * from glcoacost where account = :vAccount and cost = :vCost)) THEN
         BEGIN
            /* 20 AGUSTUS 2007*/
            exception gl_coa_cost 'Cost Center "'||vCost||'" not valid for A/C "'|| vAccount||'"';
         END
     
         vTotDB = vTotDB + vDB;
         vTotCR = vTotCR + vCR;
     /* --------------------------------------------------------------------- */            
         insert into gljur
               (PYEAR, PMONTH, TRANSNO,
                ACCOUNT, DEPART, COST, PROJECT,
                NOTE,
                REFACCOUNT, REFDEPT, REFCOST,
                JURDATE, REF,
                DB, CR,
                APPLICATION, SOURCE, SOURCENUMBER,
                CREATEUSER, EDITUSER)
         VALUES (NEW.GL_PYEAR, NEW.GL_PMONTH, NEW.GL_TRANSNO,
                :vAccount, :vDept, :vCost, '',
                :vNote,
                :vBBAccount, :vBBDept, :vBBCost,
                NEW.BBDATE, :vRef,
                :vDB, :vCR,
                :vApplication, :vSource, :vSourceNumber,
                NEW.POST_BY, NEW.POST_BY);
     /* --------------------------------------------------------------------- */
     /* DETAIL TRANSACTION                                                    */
     /* --------------------------------------------------------------------- */
         if (vExportType = 'D') then begin
            insert into gljur
                  (PYEAR, PMONTH, TRANSNO,
                   ACCOUNT, DEPART, COST, PROJECT,
                   NOTE,
                   REFACCOUNT, REFDEPT, REFCOST,
                   JURDATE, REF,
                   DB, CR,
                   APPLICATION, SOURCE, SOURCENUMBER,
                   CREATEUSER, EDITUSER)
            VALUES (NEW.GL_PYEAR, NEW.GL_PMONTH, NEW.GL_TRANSNO,
                   :vBBAccount, :vBBDept, :vBBCost, '',
                   :vNote,
                   :vAccount, :vDept, :vCost,
                   NEW.BBDATE, :vRef,
                   :vCR, :vDB,
                   :vApplication, :vSource, :vSourceNumber,
                   NEW.POST_BY, NEW.POST_BY);
         end
     /* --------------------------------------------------------------------- */            
     end
     /* --------------------------------------------------------------------- */
     /* if summary of transaction                                             */
     /* --------------------------------------------------------------------- */     
     if (vExportType = 'S') then
     begin
        vDB = 0;
        vCR = 0;
        if (vTotdb > vTotcr) then vCR = vTotdb-vTotcr;
        if (vTotdb < vTotcr) then vDB = vTotcr-vTotdb;
           
        insert into gljur
               (PYEAR, PMONTH, TRANSNO,
                ACCOUNT, DEPART, COST, PROJECT,
                NOTE, REFACCOUNT, JURDATE, REF,
                DB, CR,
                APPLICATION, SOURCE, SOURCENUMBER,
                CREATEUSER, EDITUSER)
        VALUES (NEW.GL_PYEAR, NEW.GL_PMONTH, NEW.GL_TRANSNO,
                :vBBAccount, :vBBDept, :vBBCost, '',
                'Summary of transaction', '', 'NOW', :vRef,
                :vDB, :vCR,
                'GL', 'BB', :vNumber,
                NEW.POST_BY, NEW.POST_BY);
     end
     /* --------------------------------------------------------------------- */
     /* change DETAIL status                                                  */
     /* --------------------------------------------------------------------- */               
     update bbjur set status = 'R'
     where bank = new.bank and bbdate = new.bbdate;
     /* --------------------------------------------------------------------- */
     /* LOSS & GAIN CURRENCY                                                  */
     /* --------------------------------------------------------------------- */
     if ((new.bbdate = new.bbdate) and (new.gainloss <> 0)) then
     begin
        /* ------------------------------------------------------------------ */
        /* load gain/loss account                                             */
        /* ------------------------------------------------------------------ */
        select bank_gainloss_glaccount,
               bank_gainloss_gldept,
               bank_gainloss_glcost
        from sysparam
        into vAccount, vDept, vCost;
        /* ---------------------------------------------------------------- */
        /* 8 MARET 2009                                                     */
        /* CHECK LOSS & GAIN ACCOUNT                                        */
        /* ---------------------------------------------------------------- */
        IF (NOT EXISTS (SELECT * FROM GLCOA WHERE ACCOUNT = :VACCOUNT)) THEN
           EXCEPTION GL_ACCOUNT_NOT_EXIST 'Loss & Gain Account "'||vAccount||'" does not exists';
        
        IF (NOT EXISTS (SELECT * FROM GLCOADEPT WHERE ACCOUNT = :VACCOUNT AND DEPART = :VDEPT)) THEN
           EXCEPTION gl_coa_dept 'Loss & Gain Dept. "'||vDept||'" not valid for A/C "'|| vAccount||'"';

        IF (NOT EXISTS (SELECT * FROM GLCOACOST WHERE ACCOUNT = :VACCOUNT AND COST = :VCOST)) THEN
           EXCEPTION gl_coa_cost 'Loss & Gain Cost Center "'||vCost||'" not valid for A/C "'|| vAccount||'"';
        

        /* ------------------------------------------------------------------ */
        vDB = 0;
        vCR = 0;
        if (NEW.GAINLOSS > 0) then vDB = NEW.GAINLOSS;
        else vCR = -NEW.GAINLOSS;
        /* ------------------------------------------------------------------ */
        /* bank account                                                       */
        /* ------------------------------------------------------------------ */
        insert into gljur
               (PYEAR, PMONTH, TRANSNO,
                ACCOUNT, DEPART, COST, PROJECT,
                NOTE,
                REFACCOUNT, REFDEPT, REFCOST,
                JURDATE, REF,
                DB, CR,
                APPLICATION, SOURCE, SOURCENUMBER,
                CREATEUSER, EDITUSER)
        VALUES (NEW.GL_PYEAR, NEW.GL_PMONTH, NEW.GL_TRANSNO,
                :vBBAccount, :vBBDept, :vBBCost, '',
                'Gain / Loss Currency',
                :vAccount, :vDept, :vCost,
                'NOW', :vRef,
                :vDB, :vCR,
                'GL', 'BB', :vNumber,
                NEW.POST_BY, NEW.POST_BY);
        /* ------------------------------------------------------------------ */
        /* gain/loss account                                                  */
        /* ------------------------------------------------------------------ */
        insert into gljur
               (PYEAR, PMONTH, TRANSNO,
                ACCOUNT, DEPART, COST, PROJECT,
                NOTE,
                REFACCOUNT, REFDEPT, REFCOST,
                JURDATE, REF,
                DB, CR,
                APPLICATION, SOURCE, SOURCENUMBER,
                CREATEUSER, EDITUSER)
        VALUES (NEW.GL_PYEAR, NEW.GL_PMONTH, NEW.GL_TRANSNO,
                :vAccount, :vDept, :vCost, '',
                'Gain / Loss Currency',
                :vBBAccount, :vBBDept, :vBBCost, 
                'NOW', :vRef,
                :vCR, :vDB,
                'GL', 'BB', :vNumber,
                NEW.POST_BY, NEW.POST_BY);
     end
  end /* END OF CHANGE STATUS */

end

^

CREATE TRIGGER BBJUR_BD FOR BBJUR
ACTIVE BEFORE DELETE POSITION 0
as
begin
  /* remove old data */
  update bbacc
  set db = db - old.cr, cr = cr - old.db,
      forex_db = forex_db - old.forex_cr,
      forex_cr = forex_cr - old.forex_db
  WHERE BANK = OLD.BANK
  AND BBDATE = OLD.BBDATE;
end
^

CREATE TRIGGER BBJUR_BI FOR BBJUR
ACTIVE BEFORE INSERT POSITION 10
as
declare variable vStatus CHAR(1);
begin
  /* ---------------------------------------------------------------- */
  /* error with message                                               */
  /* 20 AGUSTUS 2007                                                  */
  /* ---------------------------------------------------------------- */
  if (not exists (select * from glcoadept where account = NEW.ACCOUNT and depart = NEW.DEPT)) THEN
     exception gl_coa_dept 'Dept "'||new.DEPT||'" not valid for A/C "'|| NEW.ACCOUNT||'"';

  if (not exists (select * from glcoacost where account = NEW.ACCOUNT and cost = NEW.COST)) THEN
       exception gl_coa_cost 'Cost Center "'||new.cost||'" not valid for A/C "'|| NEW.ACCOUNT||'"';

  /* ---------------------------------------------------------------- */
  /* end of 20 AGUSTUS 2007                                           */
  /* ---------------------------------------------------------------- */
  
  if (not exists(SELECT * FROM SYSBANK WHERE BANK = NEW.BANK AND CURRENCY = new.currency)) then /* 5/31/2011, message pakai tex yg jelas */
     EXCEPTION BB_CURRENCY_DIFFRENT 'Diffrent currency in Bank: "'||NEW.BANK||'", Source: "'||NEW.APPLICATION||'.'||NEW.SOURCE||'", No: '||NEW.SOURCENUMBER;
  
  if ((new.forex_db =  0) and (new.forex_cr =  0)) then exception gl_jur_db_cr_not_valid;
  if ((new.forex_db <> 0) and (new.forex_cr <> 0)) then exception gl_jur_db_cr_not_valid;
  
  if (new.exchange <= 0) then
     select exchange from SYSCURRENCY_LOG
     where currency = NEW.Currency
     and opendate = new.bbdate
     into new.exchange;
  
  new.db = new.forex_db*new.exchange;
  new.cr = new.forex_cr*new.exchange;
  
  
  EXECUTE PROCEDURE BB_ACC_CREATE (NEW.BANK, NEW.BBDATE);

  select bbline +1, status from bbacc
  WHERE BANK = NEW.BANK
  AND BBDATE = NEW.BBDATE
  into new.bbline, vStatus;
  
  if (vStatus <> 'O') then /* 12 APRIL 2005 */
     exception BB_EXPORTED_REOPEN;
  
  update bbacc
  set db = db + new.cr, cr = cr + new.db,
      forex_db = forex_db + new.forex_cr,
      forex_cr = forex_cr + new.forex_db,
      bbline = bbline + 1
  WHERE BANK = NEW.BANK 
  AND BBDATE = NEW.BBDATE;
  
  NEW.NUMBER = GEN_ID(GEN_BB_NUMBER,1);  
  
  if ((NEW.APPLICATION ='GL') AND (NEW.SOURCE = 'BB')) then
     NEW.SOURCENUMBER = NEW.NUMBER;
end
^

CREATE TRIGGER BBJUR_BI_PERIOD FOR BBJUR
INACTIVE BEFORE INSERT POSITION 1
AS
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;
BEGIN
  /* -------------------------------------------------------------------- */
  /* 3/14/2012                                                            */
  /* lock supaya gak bisa diubah diluar periode yang berjalan             */
  /* 6/12/2012 ada message date nya             */
  /* -------------------------------------------------------------------- */
  EXECUTE PROCEDURE SP_DATE_EXTRACT_MONTHYEAR(NEW.BBDATE) RETURNING_VALUES(PMONTH, PYEAR); /* 3/14/2012 */
  IF (NOT EXISTS(SELECT * FROM SYSPARAM WHERE GLYEAR=:PYEAR AND GLMONTH=:PMONTH)) THEN
     EXCEPTION ALL_DATE_ERROR 'Please check G/L Periode, Tran: '||NEW.BBDATE||
               ', '||
               NEW.APPLICATION ||'.'||
               NEW.SOURCE || '.' ||
               NEW.SOURCENUMBER;
END
