CREATE TRIGGER BBJUR_OUTSTANDING_BI FOR BBJUR_OUTSTANDING
ACTIVE BEFORE INSERT POSITION 0
as
begin
  SELECT CURRENCY FROM SYSBANK WHERE BANK = NEW.BANK INTO NEW.CURRENCY;

  SELECT MAX(NUMBER) FROM BBJUR_OUTSTANDING INTO NEW.NUMBER;
  IF (NEW.NUMBER IS NULL) THEN NEW.NUMBER = 0;
  NEW.NUMBER = NEW.NUMBER + 1;
  
  NEW.CREATE_DATE = 'NOW';
  NEW.EDIT_DATE = 'NOW';
  NEW.STATUS = 'O';
end
^

CREATE TRIGGER BBJUR_OUTSTANDING_BU FOR BBJUR_OUTSTANDING
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  IF (NEW.AMOUNT <= 0) THEN
  BEGIN
     SELECT SUM(AMOUNT) FROM BBJUR_OUTSTANDING_DETAIL
     WHERE NUMBER = NEW.NUMBER
     INTO NEW.AMOUNT;
     IF (NEW.AMOUNT IS NULL) THEN NEW.AMOUNT = 0;
  END

  IF (NEW.REF IS NULL) THEN NEW.REF = '';
  IF (NEW.REMARK IS NULL) THEN NEW.REMARK = '';

  SELECT CURRENCY FROM SYSBANK WHERE BANK = NEW.BANK INTO NEW.CURRENCY;

  NEW.EDIT_DATE = 'NOW';
end
^

CREATE TRIGGER BBJUR_OUTSTANDING_DETAIL_BD FOR BBJUR_OUTSTANDING_DETAIL
ACTIVE BEFORE DELETE POSITION 0
as
begin
  UPDATE BBJUR_OUTSTANDING SET AMOUNT = AMOUNT - OLD.AMOUNT
  WHERE NUMBER = OLD.NUMBER;
end
^

CREATE TRIGGER BBJUR_OUTSTANDING_DETAIL_BI FOR BBJUR_OUTSTANDING_DETAIL
ACTIVE BEFORE INSERT POSITION 0
as
begin
  SELECT LINE FROM BBJUR_OUTSTANDING WHERE NUMBER = NEW.NUMBER
  INTO NEW.LINE;
  IF (NEW.LINE IS NULL) THEN NEW.LINE = 0;
  NEW.LINE = NEW.LINE + 1;

  UPDATE BBJUR_OUTSTANDING SET AMOUNT = AMOUNT + NEW.AMOUNT,
         LINE = NEW.LINE
  WHERE NUMBER = NEW.NUMBER;
  
  NEW.CREATE_DATE = 'NOW';
  NEW.EDIT_DATE = 'NOW';
end
^

CREATE TRIGGER BBJUR_OUTSTANDING_DETAIL_BU FOR BBJUR_OUTSTANDING_DETAIL
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  UPDATE BBJUR_OUTSTANDING SET AMOUNT = AMOUNT + NEW.AMOUNT
  WHERE NUMBER = NEW.NUMBER;
  
  UPDATE BBJUR_OUTSTANDING SET AMOUNT = AMOUNT - OLD.AMOUNT
  WHERE NUMBER = OLD.NUMBER;
  
  NEW.EDIT_DATE = 'NOW';
end
^

CREATE TRIGGER BBJUR_OUTSTANDING_RELEASE FOR BBJUR_OUTSTANDING
ACTIVE BEFORE UPDATE POSITION 9
as
DECLARE VARIABLE EXCHANGE DOUBLE PRECISION;
DECLARE VARIABLE GL_ACCOUNT VARCHAR(20);
DECLARE VARIABLE GL_COST VARCHAR(4);
DECLARE VARIABLE GL_DEPT VARCHAR(4);
DECLARE VARIABLE JURCODE VARCHAR(4);
DECLARE VARIABLE REMARK VARCHAR(40);
DECLARE VARIABLE REFF VARCHAR(20);
DECLARE VARIABLE NOTE VARCHAR(1000);
DECLARE VARIABLE AMOUNT DOUBLE PRECISION;
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
DECLARE VARIABLE D INTEGER;
begin
  IF (OLD.STATUS <> 'O') THEN
     EXCEPTION ALL_DOC_STATUS_NOT_OPEN;
     
  IF ((NEW.STATUS = 'R') AND (OLD.STATUS = 'O')) THEN
  BEGIN
    SELECT SUM(AMOUNT) FROM BBJUR_OUTSTANDING_DETAIL
    WHERE NUMBER = NEW.NUMBER INTO NEW.AMOUNT;
    IF (NEW.AMOUNT IS NULL) THEN NEW.AMOUNT = 0;
    
    SELECT EXCHANGE FROM SYSCURRENCY_LOG WHERE CURRENCY = NEW.CURRENCY
    AND OPENDATE = NEW.BBDATE
    INTO EXCHANGE;
    
    IF (EXCHANGE IS NULL) THEN
       SELECT EXCHANGE FROM SYSCURRENCY WHERE CURRENCY = NEW.CURRENCY
       INTO EXCHANGE;
       
       
    if ((NEW.GL_PYEAR = 0) or (NEW.GL_PYEAR IS NULL) OR (NEW.GL_PMONTH = 0) or (NEW.GL_PMONTH IS NULL) ) then
    BEGIN
       SELECT PYEAR, PMONTH FROM GLPERIOD
       WHERE NEW.BBDATE BETWEEN DATE_START AND DATE_END
       AND (PYEAR <> 0) AND (PMONTH <> 0)
       INTO NEW.GL_PYEAR, NEW.GL_PMONTH;
       if ((NEW.GL_PYEAR = 0) or (NEW.GL_PYEAR IS NULL)) then
       begin
          NEW.GL_PYEAR  = EXTRACT(YEAR FROM NEW.BBDATE);
          NEW.GL_PMONTH = EXTRACT(MONTH FROM NEW.BBDATE);
       end
       /* GET TRANSACTION ID */
       SELECT MAX(TRANSNO) transno FROM GLTRANS
       WHERE PYEAR = NEW.GL_PYEAR
       AND PMONTH = NEW.GL_PMONTH
       INTO NEW.GL_TRANSNO;
       if (NEW.GL_TRANSNO is null) then NEW.GL_TRANSNO = 0;
       NEW.GL_TRANSNO = NEW.GL_TRANSNO + 1;
    END
    
    select JURCODE from sysbank where bank = old.bank into JURCODE;
    /* ---------------------------------------------------------------------- */
    /* EXPORT HEADER GL TRANSACTION                                           */
    /* ---------------------------------------------------------------------- */
    if (NOT EXISTS(SELECT * FROM GLTRANS WHERE (PYEAR = NEW.GL_PYEAR)
                    AND (PMONTH = NEW.GL_PMONTH) AND (TRANSNO = NEW.GL_TRANSNO))) then
    BEGIN
        INSERT INTO GLTRANS
         (PYEAR, PMONTH, TRANSNO, DOCUMENT, JURCODE,
          TRANSDATE, STATUS, REFACCOUNT,
          APPLICATION, SOURCE, SOURCENUMBER, DB, CR,
          CREATEUSER, EDITUSER, NOTE)
         VALUES
         (NEW.GL_PYEAR, NEW.GL_PMONTH, NEW.GL_TRANSNO, NEW.DOCUMENT, :JURCODE,
          NEW.BBDATE, 'H', '',
          'GL', 'BB', 0, 0, 0,
          NEW.POST_BY, NEW.POST_BY, NEW.REMARK);
    END
    ELSE
       UPDATE GLTRANS SET CREATEUSER = NEW.POST_BY, EDITUSER = NEW.POST_BY,
              NOTE = 'Export from Bank Book', DOCUMENT = NEW.DOCUMENT
       WHERE PYEAR = NEW.GL_PYEAR
       AND PMONTH = NEW.GL_PMONTH
       AND TRANSNO = NEW.GL_TRANSNO;       
    /* ---------------------------------------------------------------------- */
    /* EXPORT DETAIL GL TRANSACTION                                           */
    /* ---------------------------------------------------------------------- */                         
    FOR SELECT ACCOUNT, DEPT, COST, NOTE, REMARK, REF, AMOUNT
        FROM BBJUR_OUTSTANDING_DETAIL
        WHERE NUMBER = NEW.NUMBER
    INTO GL_ACCOUNT, GL_DEPT, GL_COST, NOTE, REMARK, REFF, AMOUNT
    DO
    BEGIN
    

        if (not exists (select * from glcoadept where account = :GL_ACCOUNT and depart = :GL_DEPT)) THEN
        BEGIN
           /* 20 AGUSTUS 2007*/
           exception gl_coa_dept 'Dept "'||GL_DEPT||'" not valid for A/C "'|| GL_ACCOUNT||'"';
        END
        if (not exists (select * from glcoacost where account = :GL_ACCOUNT and cost = :GL_COST)) THEN
        BEGIN
           /* 20 AGUSTUS 2007*/
           exception gl_coa_cost 'Cost Center "'||GL_COST||'" not valid for A/C "'|| GL_ACCOUNT||'"';
        END
        IF (REFF IS NULL) THEN REFF = '';
        
        insert into gljur
               (PYEAR, PMONTH, TRANSNO,
                ACCOUNT, DEPART, COST, PROJECT,
                NOTE,
                REFACCOUNT, REFDEPT, REFCOST,
                JURDATE, REF,
                DB, CR,
                APPLICATION, SOURCE, SOURCENUMBER,
                CREATEUSER, EDITUSER)
         VALUES (NEW.GL_PYEAR, NEW.GL_PMONTH, NEW.GL_TRANSNO,
                :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                :REMARK,
                '','','',
                NEW.BBDATE, :REFF,
                :AMOUNT*:EXCHANGE, 0,
                'GL', 'BBS', NEW.NUMBER,
                NEW.POST_BY, NEW.POST_BY);        
    END
    /* ---------------------------------------------------------------------- */
    /* EXPORT AP CLEARANCE                                                    */
    /* ---------------------------------------------------------------------- */
    select DISBURSMENT_GL_ACCOUNT, DISBURSMENT_GL_DEPT, DISBURSMENT_GL_COST
    from SYSPARAM where ID = 1
    into GL_ACCOUNT, GL_DEPT, GL_COST;

    insert into gljur
               (PYEAR, PMONTH, TRANSNO,
                ACCOUNT, DEPART, COST, PROJECT,
                NOTE,
                REFACCOUNT, REFDEPT, REFCOST,
                JURDATE, REF,
                DB, CR,
                APPLICATION, SOURCE, SOURCENUMBER,
                CREATEUSER, EDITUSER)
    VALUES (NEW.GL_PYEAR, NEW.GL_PMONTH, NEW.GL_TRANSNO,
                :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                NEW.REMARK,
                '','','',
                NEW.BBDATE, NEW.REF,
                0, NEW.AMOUNT*:EXCHANGE,
                'GL', 'BBS', NEW.NUMBER,
                NEW.POST_BY, NEW.POST_BY);    
    /* ---------------------------------------------------------------------- */
    /* EXPORT TO BANK BOOK                                                    */
    /* ---------------------------------------------------------------------- */                
     INSERT INTO BBJUR
        (BANK,BBDATE,DOCUMENT,BBCODE,
         ACCOUNT,DEPT,COST,NOTE,REMARK,REF,
         CURRENCY, EXCHANGE,APPLICATION,SOURCE,SOURCENUMBER,
         FOREX_DB, FOREX_CR, SOURCEID)
     VALUES
        (NEW.BANK, NEW.BBDATE, NEW.DOCUMENT,'BBS',
         :GL_ACCOUNT, :GL_DEPT, :GL_COST, NEW.NOTE, :REMARK, :REFF,
         NEW.CURRENCY, :EXCHANGE, 'GL', 'BBS', NEW.NUMBER,
         NEW.AMOUNT, 0, NEW.NUMBER);
  END
  
end
^

CREATE TRIGGER FA_MASTER_ADJ_AU_RELEASE FOR FA_MASTER_ADJ
ACTIVE AFTER UPDATE POSITION 0
as
declare variable ID integer;
declare variable GL_ACCOUNT VARCHAR(20);
declare variable GL_COST VARCHAR(4);
declare variable GL_DEPT VARCHAR(4);
declare variable NOTE VARCHAR(40);
declare variable REFF VARCHAR(20);
declare variable DB DOUBLE PRECISION;
declare variable CR DOUBLE PRECISION;
DECLARE VARIABLE TRANSDATE DATE;
begin
  if ((OLD.STATUS = 'O') AND (NEW.STATUS = 'R')) then
  BEGIN
     IF (NEW.CR <> 0) THEN  /* 19 MAY 2007 */
     BEGIN
        FOR SELECT ID, GL_ACCOUNT, GL_COST, GL_DEPT,
                   NOTE, REF, DEBIT, CREDIT, TRANSDATE
            FROM FA_GLBUFFER_ADJUST(OLD.NUMBER)
            INTO ID, GL_ACCOUNT, GL_COST, GL_DEPT,
                 NOTE, REFF, DB, CR, TRANSDATE
        DO
        BEGIN
           insert into glbuffer
                  (APPLICATION, SOURCE, NUMBER, ID, transdate,
                   ACCOUNT, DEPT, COST, PROJECT,
                   NOTE, REF,
                   DB, CR,
                   EXPORTDATE, EXPORTUSER)
           values ('FA','ADJ', NEW.NUMBER, :ID, :TRANSDATE,
                   :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                   :NOTE, :REFF,
                   :DB, :CR,
                   'now', NEW.EDITUSER);
        END
     END
  END
end
^

CREATE TRIGGER FA_MASTER_ADJ_BD FOR FA_MASTER_ADJ
ACTIVE BEFORE DELETE POSITION 0
AS
BEGIN
  IF (OLD.STATUS <> 'O') THEN EXCEPTION ALL_DOC_STATUS_NOT_OPEN;
  UPDATE FA_MASTER SET VALUE_ADJUST = VALUE_ADJUST - OLD.CR_EXPENSES,
                       VALUE_QTY_ADJ = VALUE_QTY_ADJ - OLD.QTY
  WHERE FA_MASTER_ID = OLD.FA_MASTER_ID;
END
^

CREATE TRIGGER FA_MASTER_ADJ_BI FOR FA_MASTER_ADJ
ACTIVE BEFORE INSERT POSITION 0
AS
BEGIN
  SELECT MAX(NUMBER) FROM FA_MASTER_ADJ INTO NEW.NUMBER;
  
  IF (NEW.NUMBER IS NULL) THEN NEW.NUMBER = 1;
  ELSE NEW.NUMBER = NEW.NUMBER + 1;
  
  NEW.EDITDATE = 'NOW';
  NEW.CREATEDATE = 'NOW';
  NEW.STATUS = 'O';
  
  UPDATE FA_MASTER SET VALUE_ADJUST = VALUE_ADJUST + NEW.CR_EXPENSES,
                       VALUE_QTY_ADJ = VALUE_QTY_ADJ + NEW.QTY
  WHERE FA_MASTER_ID = NEW.FA_MASTER_ID;
END
^

CREATE TRIGGER FA_MASTER_ADJ_BU FOR FA_MASTER_ADJ
ACTIVE BEFORE UPDATE POSITION 0
AS
BEGIN
  IF (OLD.STATUS <> 'O') THEN EXCEPTION ALL_DOC_STATUS_NOT_OPEN;
END
^

CREATE TRIGGER FA_MASTER_AI_CR_DEPRE FOR FA_MASTER
ACTIVE AFTER INSERT POSITION 0
as
declare variable M INTEGER;
declare variable PYEAR INTEGER;
declare variable PMONTH INTEGER;
declare variable AMOUNT DOUBLE PRECISION;
begin
  IF (NEW.FA_METHOD = 'SL') THEN
  BEGIN
      PYEAR = NEW.DEPRE_START_YEAR;
      PMONTH = NEW.DEPRE_START_MONTH;
      M = 1;
      AMOUNT = NEW.VALUE_OPEN/NEW.DEPRE_AGE;
      WHILE (M <= NEW.DEPRE_AGE) DO
      BEGIN
        INSERT INTO FA_MASTER_DEPRE
           (FA_MASTER_ID,LISTINDEX,PYEAR,PMONTH,AMOUNT,STATUS, CREATEUSER, EDITUSER)
        VALUES
           (NEW.FA_MASTER_ID, :M, :PYEAR, :PMONTH, :AMOUNT, 'O', NEW.CREATEUSER, NEW.CREATEUSER);
        PMONTH = PMONTH + 1;
        if (PMONTH > 12) then
        BEGIN
           PMONTH = 1;
           PYEAR = PYEAR + 1;
        END
        M = M + 1;
      END
  END
  ELSE /* 9/25/2013 */
  BEGIN
    SELECT COUNT(*) FROM FA_DEPRE_CREATE(NEW.FA_MASTER_ID, 1, NEW.CREATEUSER)
    INTO M;
  END
end
^

CREATE TRIGGER FA_MASTER_AU_CR_DEPRE FOR FA_MASTER
ACTIVE AFTER UPDATE POSITION 0
as
declare variable M INTEGER;
declare variable PYEAR INTEGER;
declare variable PMONTH INTEGER;
declare variable AMOUNT DOUBLE PRECISION;
declare variable POSTED_AMOUNT DOUBLE PRECISION;
declare variable POSTED_MONTH INTEGER;
begin
  if ((NEW.FA_METHOD <> OLD.FA_METHOD) OR /* 9/25/2013 */
      (NEW.DEPRE_AGE <> OLD.DEPRE_AGE) or
      (NEW.DEPRE_START_YEAR <> OLD.DEPRE_START_YEAR) or
      (NEW.DEPRE_START_MONTH <> OLD.DEPRE_START_MONTH) or
      (NEW.VALUE_OPEN <> OLD.VALUE_OPEN)) then
  BEGIN
    /* JIKA DEPRECIATION PERNAH DIBUAT */
    if (EXISTS(SELECT * FROM FA_MASTER_DEPRE WHERE FA_MASTER_ID = NEW.FA_MASTER_ID)) THEN
    BEGIN
       if (NOT EXISTS(SELECT * FROM FA_MASTER_DEPRE
           WHERE FA_MASTER_ID = NEW.FA_MASTER_ID AND STATUS = 'O')) then
           EXCEPTION FA_DEPRE_ALL_POSTED;
    END

    SELECT SUM(AMOUNT), COUNT(*) FROM FA_MASTER_DEPRE
    WHERE FA_MASTER_ID = NEW.FA_MASTER_ID
    AND STATUS = 'R'
    INTO POSTED_AMOUNT, POSTED_MONTH;
  
    if (POSTED_AMOUNT IS NULL) then
    BEGIN
       POSTED_AMOUNT = 0;
       POSTED_MONTH  = 0;
    END
    if (NEW.VALUE_OPEN-POSTED_AMOUNT = 0) then
       EXCEPTION FA_DEPRE_ALL_POSTED;
  
    DELETE FROM FA_MASTER_DEPRE
    WHERE FA_MASTER_ID = NEW.FA_MASTER_ID
    AND STATUS = 'O';
  

    /* -------------------------------------------------------------------- */
    /* STRAIGHT LINE                                                        */
    /* -------------------------------------------------------------------- */
    
    IF (NEW.FA_METHOD='SL') THEN
    BEGIN
        FOR SELECT LISTINDEX, PYEAR, PMONTH FROM FA_MASTER_DEPRE
            WHERE FA_MASTER_ID = NEW.FA_MASTER_ID
            ORDER BY LISTINDEX
        INTO M, PYEAR, PMONTH
        DO M = M+1;
        /* NEXT PERIOD DEPRECIATION */
        PMONTH = PMONTH + 1;
        if (PMONTH > 12) then
        BEGIN
           PMONTH = 1;
           PYEAR = PYEAR + 1;
        END
        /* if NO DEPECIATION CREATE then */
        if (M IS NULL) then
        BEGIN
          M = 1;
          PYEAR = NEW.DEPRE_START_YEAR;
          PMONTH = NEW.DEPRE_START_MONTH;
        END

        AMOUNT = (NEW.VALUE_OPEN-POSTED_AMOUNT)/(NEW.DEPRE_AGE-POSTED_MONTH);
        WHILE (M <= NEW.DEPRE_AGE) DO
        BEGIN
          INSERT INTO FA_MASTER_DEPRE
             (FA_MASTER_ID,LISTINDEX,PYEAR,PMONTH,AMOUNT,STATUS,CREATEUSER, EDITUSER)
          VALUES
             (NEW.FA_MASTER_ID, :M, :PYEAR, :PMONTH, :AMOUNT, 'O', NEW.EDITUSER, NEW.EDITUSER);
          PMONTH = PMONTH + 1;
          if (PMONTH > 12) then
          BEGIN
             PMONTH = 1;
             PYEAR = PYEAR + 1;
          END
          M = M + 1;
        END
     END
     /* 9/25/2013 DOUBLE DECLINING */
     ELSE IF ((NEW.FA_METHOD='DD') AND ((NEW.DEPRE_AGE IS NOT NULL) AND (NEW.DEPRE_AGE <> 0))) THEN
     BEGIN
        SELECT COUNT(*) FROM FA_DEPRE_CREATE(NEW.FA_MASTER_ID, 1, NEW.EDITUSER)
        INTO M;
     END
  END
end
^

CREATE TRIGGER FA_MASTER_AU_RELEASE FOR FA_MASTER
ACTIVE AFTER UPDATE POSITION 0
as
declare variable ID integer;
declare variable GL_ACCOUNT VARCHAR(20);
declare variable GL_COST VARCHAR(4);
declare variable GL_DEPT VARCHAR(4);
declare variable NOTE VARCHAR(40);
declare variable REFF VARCHAR(20);
declare variable DB DOUBLE PRECISION;
declare variable CR DOUBLE PRECISION;
DECLARE VARIABLE TRANSDATE DATE;
begin
  IF (NEW.INV_RECV_NO <> 0) THEN
  BEGIN
    if (((OLD.INV_RECV_GLSTATUS <> 'R') OR
         (OLD.INV_RECV_GLSTATUS IS NULL)) AND (NEW.INV_RECV_GLSTATUS = 'R')) then
    BEGIN
       FOR SELECT ID, GL_ACCOUNT, GL_COST, GL_DEPT,
                  NOTE, REF, DEBIT, CREDIT, TRANSDATE
           FROM FA_GLBUFFER_RELEASE(OLD.FA_MASTER_ID)
           INTO ID, GL_ACCOUNT, GL_COST, GL_DEPT,
                NOTE, REFF, DB, CR, TRANSDATE
       DO
       BEGIN
          insert into glbuffer
                 (APPLICATION, SOURCE, NUMBER, ID, transdate,
                  ACCOUNT, DEPT, COST, PROJECT,
                  NOTE, REF,
                  DB, CR,
                  EXPORTDATE, EXPORTUSER)
          values ('FA','NEW', NEW.FA_MASTER_ID, :ID, :TRANSDATE,
                  :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                  :NOTE, :REFF,
                  :DB, :CR,
                  'now', NEW.EDITUSER);
       END
    END
  END
end
^

CREATE TRIGGER FA_MASTER_BI FOR FA_MASTER
ACTIVE BEFORE INSERT POSITION 0
AS
BEGIN
   SELECT MAX(FA_MASTER_ID) FROM FA_MASTER
   INTO NEW.FA_MASTER_ID;
   
   if (NEW.FA_MASTER_ID IS NULL) then NEW.FA_MASTER_ID = 0;
   NEW.FA_MASTER_ID = NEW.FA_MASTER_ID +1;
   
   IF (NEW.FA_TYPE IS NULL) THEN
      SELECT MIN(FA_TYPE) FROM FA_TYPE INTO NEW.FA_TYPE;
      
   IF (NEW.FA_METHOD IS NULL) THEN
      NEW.FA_METHOD = 'SL';

   IF (NEW.FA_STATUS IS NULL) THEN
      NEW.FA_STATUS = 'A';
      
   NEW.GL_EXPORT_STATUS = 'O';
   
   IF ((NEW.VALUE_QTY = 0) OR (NEW.VALUE_QTY IS NULL)) THEN NEW.VALUE_QTY = 1; /* 11-MARET 2008, KALAU NEGATIF TETAP BISA */
   
   IF (NEW.DEPRE_START_YEAR IS NULL) THEN
      SELECT GLYEAR FROM SYSPARAM INTO NEW.DEPRE_START_YEAR;
      
   IF (NEW.DEPRE_START_MONTH IS NULL) THEN
      SELECT GLMONTH FROM SYSPARAM INTO NEW.DEPRE_START_MONTH;
      
   /* ---------------------------------------------------------------- */
   /* 8 JUNE 2009                                                      */
   /* ---------------------------------------------------------------- */
      
   IF (NEW.PO_NUMBER IS NULL) THEN NEW.PO_NUMBER = 0;
   IF (NEW.INV_RECV_NO IS NULL) THEN NEW.INV_RECV_NO = 0;
   IF (NEW.VALUE_QTY_ADJ IS NULL) THEN NEW.VALUE_QTY_ADJ = 0;
END
^

CREATE TRIGGER FA_MASTER_BU FOR FA_MASTER
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  if (NEW.FA_STATUS = 'S') then
     exception fa_asset_already_sold;

  if (NEW.FA_STATUS = 'I') then
  BEGIN
     if (NEW.VALUE_DEPRE <> OLD.VALUE_DEPRE) then
        exception fa_inactive;
  END

  if ((NEW.VALUE_DEPRE <> 0) AND (NEW.VALUE_OPEN <> OLD.VALUE_OPEN)) then
     exception fa_depre_posted;

   IF (NEW.VALUE_QTY = 0) THEN NEW.VALUE_QTY = 1; /* 11 MARET 2008, BOLEH NEGATIVE KARENA IMPORT FOR CORRECTION */

   IF (NEW.INV_RECV_NO <> 0) THEN
   BEGIN
      IF ((NEW.VALUE_QTY <> OLD.VALUE_QTY) OR
          (NEW.VALUE_COST <> OLD.VALUE_COST))
      THEN EXCEPTION ALL_MODIFY_AUTOMATIC_RECORD;

      IF ((NEW.INV_RECV_GLSTATUS IS NULL) OR (NEW.INV_RECV_GLSTATUS = '')) THEN
         NEW.INV_RECV_GLSTATUS = 'O';

      IF (NEW.INV_RECV_GLSTATUS = 'R') THEN
      BEGIN
         IF ((NEW.FA_TYPE <> OLD.FA_TYPE) OR
             (NEW.DEPRE_START_MONTH <> OLD.DEPRE_START_MONTH) OR
             (NEW.DEPRE_START_YEAR <> OLD.DEPRE_START_YEAR) OR
             (NEW.DATEACTIVE <> OLD.DATEACTIVE))
         THEN EXCEPTION ALL_DOC_STATUS_NOT_OPEN;
      END
   END
   ELSE
      NEW.INV_RECV_GLSTATUS = 'R';

   IF ((NEW.VALUE_BOOK <> OLD.VALUE_BOOK) AND (NEW.VALUE_BOOK < -0.5)) THEN
      EXCEPTION FA_BOOK_VALUE_NEGATIVE 'Access denied. Asset ID#'|| NEW.FA_MASTER_ID || '''s, book value Negative ! ';
end
^

CREATE TRIGGER FA_MASTER_BU_RECALC FOR FA_MASTER
ACTIVE BEFORE UPDATE POSITION 1
AS
BEGIN
  IF (NEW.VALUE_DEPRE = -1) THEN
  BEGIN
     SELECT SUM(AMOUNT) FROM FA_MASTER_DEPRE
     WHERE FA_MASTER_ID = NEW.FA_MASTER_ID
     AND STATUS = 'R'
     INTO NEW.VALUE_DEPRE;
     
     IF (NEW.VALUE_DEPRE IS NULL) THEN NEW.VALUE_DEPRE = 0;
     /* 13 APRIL 2010, ADJUST EXPENSES ONLY */
     SELECT SUM(CR_EXPENSES), SUM(QTY) FROM FA_MASTER_ADJ /* 2 OCT 2007, CALCULATE QTY ADJ */
     WHERE FA_MASTER_ID = NEW.FA_MASTER_ID
     AND STATUS = 'R'
     INTO NEW.VALUE_ADJUST, NEW.VALUE_QTY_ADJ;

     IF (NEW.VALUE_ADJUST IS NULL) THEN NEW.VALUE_ADJUST = 0;
     IF (NEW.VALUE_QTY_ADJ IS NULL) THEN NEW.VALUE_QTY_ADJ = 0;
  END
END
^

