CREATE TRIGGER FA_MASTER_LOCATION_LOG_RELASE FOR FA_MASTER_LOCATION_LOG
ACTIVE BEFORE UPDATE POSITION 1
AS
DECLARE VARIABLE QTY DOUBLE PRECISION;
DECLARE VARIABLE FA_MASTER_ID INTEGER;
BEGIN
  IF ((NEW.STATUS = 'R') AND (OLD.STATUS = 'O')) THEN
  BEGIN
     SELECT FA_MASTER_ID, QTY FROM FA_MASTER_LOCATION WHERE ID = NEW.ID
     INTO FA_MASTER_ID, QTY;
     
     IF (QTY = OLD.QTY) THEN
     BEGIN
       UPDATE FA_MASTER_LOCATION SET LOCATION = NEW.LOCATION_NEW, QTY = QTY - NEW.QTY
       WHERE ID  = NEW.ID;
     END
     ELSE
     BEGIN
       INSERT INTO FA_MASTER_LOCATION (FA_MASTER_ID, LOCATION, REMARK,
           QTY, NOTE, CREATEUSER, EDITUSER, SPLIT_LOG_ID, ORIGINAL_LOCATION_ID)
       VALUES (:FA_MASTER_ID, NEW.LOCATION_NEW, NEW.REMARK, NEW.QTY, NEW.NOTE,
           NEW.RELEASE_USER, NEW.RELEASE_USER, NEW.LOG_ID, NEW.ID);
     END
  END
END
