     SELECT COUNT(*) FROM GLTRANS
     WHERE CSOURCE=NEW.CSOURCE
     AND PYEAR = NEW.PYEAR
     AND PMONTH = NEW.PMONTH
     INTO NEW.RECORD_TRANS;

     SELECT COUNT(*) FROM GLJUR
     WHERE CSOURCE=NEW.CSOURCE
