CREATE TRIGGER GL_RCURR_JUR_BI FOR GL_RCURR_JUR
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vLine INTEGER;
declare variable vRefAccount VARCHAR(20);
declare variable vHeader char(1);
declare variable iRow integer;
begin
  select count(*) from glcoadept
   where account = new.account and depart = new.depart
    into :iRow;
    
  if (iRow = 0) then exception gl_coa_dept;

  select count(*) from glcoacost
   where account = new.account and cost = new.cost
    into :iRow;
    
  if (iRow = 0) then exception gl_coa_cost;
  
  select header from glcoa where account = new.account into :vHeader;
  if (vHeader <> 'D') then exception gl_coa_not_detail;
  
  SELECT LINE FROM gl_rcurr_trans
   WHERE (RCURR_ID = NEW.RCURR_ID)
    INTO :vLINE;
       
  new.line = :vLine+1;
end
^

CREATE TRIGGER GL_RCURR_JUR_BU FOR GL_RCURR_JUR
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable vStatus char(1);
declare variable vRefAccount VARCHAR(20);
declare variable vHeader char(1);
declare variable iRow integer;
begin
  SELECT status FROM gl_rcurr_trans
  WHERE (RCURR_ID = NEW.RCURR_ID)
  INTO :vStatus;
      
  if (:vStatus IN ('C','X')) then
        exception document_is_not_open;

  select count(*) from glcoadept
   where account = new.account and depart = new.depart
    into :iRow;
  if (iRow = 0) then exception gl_coa_dept;

  select count(*) from glcoacost
   where account = new.account and cost = new.cost
    into :iRow;
  if (iRow = 0) then exception gl_coa_cost;
  
  select header from glcoa where account = new.account into :vHeader;
  if (vHeader <> 'D') then exception gl_coa_not_detail;
  
  if (((new.db <> old.db) or (new.cr <> old.cr))) then
  begin
     UPDATE gl_rcurr_trans SET
            db = db-old.db + new.db,
            cr = cr-old.cr + new.cr
      WHERE (RCURR_ID = NEW.RCURR_ID);
  end
end
^

