CREATE TRIGGER GL_RCURR_SCHEDULE_BU_POST FOR GL_RCURR_SCHEDULE
ACTIVE BEFORE UPDATE POSITION 99
as
declare variable vTransNo INTEGER;
declare variable vID INTEGER;
declare variable vACCOUNT VARCHAR(20);
declare variable vDEPT VARCHAR(4);
declare variable vCOST VARCHAR(4);
declare variable vPROJECT VARCHAR(8);
declare variable vNOTE VARCHAR(40);
declare variable vREF VARCHAR(20);
declare variable vDB NUMERIC(15,4);
declare variable vCR NUMERIC(15,4);
declare variable vJurCode VARCHAR(4);
declare variable vFirstRow integer;
declare variable vExist integer;
declare variable vImportType CHAR(3) ;
begin
  if ((NEW.STATUS = 'P') AND (OLD.STATUS = 'O')) then
  BEGIN
    SELECT MAX(TRANSNO) FROM GLTRANS
    WHERE PYEAR = NEW.PYEAR
    AND PMONTH = NEW.PMONTH
    INTO NEW.GLTRANS_NUMBER;
    if (NEW.GLTRANS_NUMBER IS NULL) then NEW.GLTRANS_NUMBER = 0;
    NEW.GLTRANS_NUMBER = NEW.GLTRANS_NUMBER +1;


   INSERT INTO GLTRANS
          (PYEAR, PMONTH, TRANSNO, DOCUMENT, JURCODE,
           TRANSDATE, STATUS, REFACCOUNT,
           APPLICATION, SOURCE, SOURCENUMBER, DB, CR)
   VALUES
          (NEW.PYEAR, NEW.PMONTH, NEW.GLTRANS_NUMBER, NEW.DOCUMENT, 'RC',
           '1'||'.'||NEW.PMONTH||'.'||NEW.PYEAR,/* Update ke tgl 1 setiap bulan, supaya tdk ambil tgl PC  14-12-16 */
            'H', '', 'GL', 'RC', NEW.RCURR_ID, 0, 0);
           

  FOR SELECT ACCOUNT, DEPART, COST, PROJECT,
             NOTE, REF, DB, CR
      FROM gl_rcurr_jur
      WHERE RCURR_ID = NEW.RCURR_ID
      INTO :vACCOUNT, :vDEPT, :vCOST, :vPROJECT,
           :vNOTE, :vREF, :vDB, :vCR
      DO
      BEGIN
         insert into gljur
             (PYEAR, PMONTH, TRANSNO,
              ACCOUNT, DEPART, COST, PROJECT,
              NOTE, REFACCOUNT, JURDATE, REF, DB, CR,
              APPLICATION, SOURCE, SOURCENUMBER)
         VALUES (NEW.PYEAR, NEW.PMONTH, NEW.GLTRANS_NUMBER,
              :vAccount, :vDept, :vCost, :vProject,
              :vNote, '', 'NOW', :vRef, :vDB, :vCR,
              'GL', 'RC', NEW.RCURR_ID);
      END
  END
end
^

