CREATE TRIGGER GLACC_AU FOR GLACC
ACTIVE AFTER UPDATE POSITION 0
as
declare variable NYear INTEGER;
declare variable NMonth INTEGER;
declare variable vAccType CHAR(1);
DECLARE VARIABLE GLCUREARN VARCHAR(20);
DECLARE VARIABLE GLRETEARN VARCHAR(20);
declare variable DEFA_COST VARCHAR(4);
declare variable DEFA_DEPT VARCHAR(4);
begin
  SELECT acctype from glcoa where account = new.account into :vAccType;
  select GLCUREARN, GLRETEARN, GL_DEFAULT_COST, GL_DEFAULT_DEPT from sysparam
  into GLCUREARN, GLRETEARN, DEFA_COST, DEFA_DEPT;
        
  if (new.ending <> old.ending) then
  BEGIN
    if (vAccType in ('A','P')) then
    begin
      NYear  = NEW.PYEAR;
      NMonth = NEW.PMONTH + 1;
      if (NMonth > 12) then
      begin
         NMonth = 1;
         NYear  = NYear + 1;
      end
/*      UPDATE glacc set opening = new.ending
      where pyear = :NYear
      AND pmonth = :NMonth
      AND account = new.Account
      and depart = new.Depart
      and cost = new.cost;*/
    end
    ELSE
    if (vAccType in ('I','C'))  then
    begin
      select GLCUREARN, GL_DEFAULT_COST, GL_DEFAULT_DEPT from sysparam
      into GLCUREARN, DEFA_COST, DEFA_DEPT;

      if (NOT EXISTS(SELECT * FROM GLACC      
                      where pyear = NEW.PYEAR
                      AND pmonth = NEW.PMONTH
                      AND account = :GLCUREARN
                      and depart = :DEFA_DEPT
                      and cost = :DEFA_COST)) then
      BEGIN
         INSERT INTO GLACC
         (PYEAR, PMONTH, ACCOUNT, DEPART, COST, OPENING, DB, CR)
         VALUES
         (NEW.PYEAR, NEW.PMONTH, :GLCUREARN, :DEFA_DEPT,:DEFA_COST, 0, 0, 0);
      END


      UPDATE glacc set CR = CR + (NEW.CR-OLD.CR)-(NEW.DB-OLD.DB)
      where pyear = NEW.PYEAR
      AND pmonth = NEW.PMONTH
      AND account = :GLCUREARN
      and depart = :DEFA_DEPT
      and cost = :DEFA_COST;
    end
  END
end
^

CREATE TRIGGER GLACC_BINSERT FOR GLACC
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vAccType CHAR(1);
declare variable vHeader CHAR(1);
declare variable iRow integer;
begin
  IF (not exists(select * from glcoadept
      where account = new.account and depart = new.depart)) then
  begin
    /* 20 AGUSTUS 2007*/
    exception gl_coa_dept 'Dept "'||new.depart||'" not valid for A/C "'|| NEW.ACCOUNT||'"';
  end

  IF (not exists(select * from glcoacost
          where account = new.account and cost = new.cost)) then
  begin
    /* 20 AGUSTUS 2007*/
    exception gl_coa_cost 'Cost Center "'||new.cost||'" not valid for A/C "'|| NEW.ACCOUNT||'"';
  end

  SELECT acctype, header from glcoa where account = new.account into :vAccType, vHeader;
  if (vHeader <> 'D') then exception gl_coa_not_detail;
  if (vAccType IN ('A', 'C')) then
  begin
     new.ending = new.opening + new.db - new.cr;
     new.mutation = new.db - new.cr;
  end
  else
  begin
    new.ending = new.opening - new.db + new.cr;
    new.mutation = - new.db + new.cr;
  end
end
^

CREATE TRIGGER GLACC_BU_READONLY FOR GLACC
ACTIVE BEFORE UPDATE POSITION 0
AS
BEGIN
  /* -------------------------------- */
  /* CREATED AT 06-Jun-2003 13:44:32  */
  /* -------------------------------- */
  if ((NEW.READONLY = 1) AND
      ((NEW.DB <> OLD.DB) OR
       (NEW.CR <> OLD.CR) OR
       (NEW.OPENING <> OLD.OPENING))) THEN
  BEGIN
     EXCEPTION ALL_READONLY 'Ledger already LOCKED (GLACC '||NEW.PMONTH||'-'||NEW.PYEAR||')'; /* 1/26/2012 */
     NEW.DB = OLD.DB;
     NEW.CR = OLD.CR;
     NEW.OPENING = OLD.OPENING;
  END
END
^

CREATE TRIGGER GLACC_BU_RETEARNING FOR GLACC
ACTIVE BEFORE UPDATE POSITION 99
as
DECLARE VARIABLE GL_CURRENT  VARCHAR(20);
DECLARE VARIABLE GL_RETAINED VARCHAR(20);
declare variable EARNING numeric(18,4);
begin
  /* ------------------------------------------------------------------------ */
  /* UNTUK MENGHITUNG RETAIL EARNING PADA SAAT GANTI TAHUN                    */
  /* ------------------------------------------------------------------------ */
  IF (NEW.PMONTH = 1) THEN
  BEGIN
     /* ---------------------------------------------------------------- */
     /* 14 FEB 2007, AMBIL RETAINED ACCOUNT DARI SETUP                   */
     /* ---------------------------------------------------------------- */
     IF (EXISTS(SELECT * FROM GLCOA_RETAINED WHERE PYEAR = NEW.PYEAR-1)) THEN
        SELECT ACCOUNT FROM GLCOA_RETAINED WHERE PYEAR = NEW.PYEAR-1 INTO GL_RETAINED;
     ELSE
        select GLRETEARN from sysparam into GL_RETAINED;

     /* ---------------------------------------------------------------- */
     select GLCUREARN from sysparam into GL_CURRENT;
     
     /* ---------------------------------------------------------------- */
     /* CHECK APAKAH INI RETAINED EARNING ATAU BUKAN                     */
     /* ---------------------------------------------------------------- */
     if (new.account = GL_RETAINED) then
     begin
        /* AMBIL ENDING RETURN EARNING TAHUN LALU */
        SELECT ENDING FROM GLACC WHERE PYEAR = NEW.PYEAR -1 AND PMONTH = 12
        AND ACCOUNT = NEW.ACCOUNT AND DEPART = NEW.DEPART AND COST = NEW.COST
        INTO NEW.OPENING;
        if (NEW.OPENING IS NULL) then NEW.OPENING = 0;
        /* AMBIL CURRENT EARNING TAHUN LALU */
        SELECT ENDING FROM GLACC WHERE PYEAR = NEW.PYEAR -1 AND PMONTH = 12
        AND ACCOUNT = :GL_CURRENT
        AND DEPART = NEW.DEPART AND COST = NEW.COST
        INTO EARNING;
        if (EARNING IS NULL) then EARNING = 0;
        /* JUMLAH KAN */
        NEW.OPENING = NEW.OPENING + EARNING;
        NEW.ENDING  = NEW.OPENING;
        NEW.DB = 0;
        NEW.CR = 0;
     end
  END
end
^

CREATE TRIGGER GLACC_BUPDATE FOR GLACC
ACTIVE BEFORE UPDATE POSITION 2
as
declare variable vAccType CHAR(1);
declare variable iRow integer;
declare variable NYear INTEGER;
declare variable NMonth INTEGER;
DECLARE VARIABLE GLCUREARN VARCHAR(20);
DECLARE VARIABLE GLRETEARN VARCHAR(20);
begin
  /* ---------------------------------------------------------------- */
  /* 3 SEP 2007 - VALIDATE NULL VALUES                                */
  /* ---------------------------------------------------------------- */
  IF (NEW.OPENING IS NULL) THEN NEW.OPENING = 0;
  IF (NEW.DB IS NULL) THEN NEW.DB = 0;
  IF (NEW.CR IS NULL) THEN NEW.CR = 0;
  IF (NEW.BUDGET IS NULL) THEN NEW.BUDGET = 0;


  /* ---------------------------------------------------------------- */
  /* END OF 3 SEP 2007                                                */
  /* ---------------------------------------------------------------- */
  
  SELECT acctype from glcoa where account = new.account into :vAccType;
  select GLCUREARN, GLRETEARN
  from sysparam
  into GLCUREARN, GLRETEARN;  

  if (new.mutation = -1) then
  begin
/*    if (not ((new.account = GLCUREARN) or (new.account = GLRETEARN))) then*/
    if (vAccType IN ('A','P')) then
    begin
      NYear  = NEW.PYEAR;
      NMonth = NEW.PMONTH + 1;
      if (NMonth > 12) then
      begin
         NMonth = 1;
         NYear  = NYear + 1;
      end
      UPDATE glacc set opening = new.ending
      where pyear = :NYear
      AND pmonth = :NMonth
      AND account = new.Account
      and depart = new.Depart
      and cost = new.cost;
    end
  end
  
  if ((new.account = GLCUREARN) and (NEW.PMONTH = 1)) then NEW.OPENING = 0;
  
  IF (not exists(select * from glcoadept
      where account = new.account and depart = new.depart)) then
  begin
    /* 20 AGUSTUS 2007*/
    exception gl_coa_dept 'Dept "'||new.depart||'" not valid for A/C "'|| NEW.ACCOUNT||'"';
  end

  IF (not exists(select * from glcoacost
          where account = new.account and cost = new.cost)) then
  begin
    /* 20 AGUSTUS 2007*/
    exception gl_coa_cost 'Cost Center "'||new.cost||'" not valid for A/C "'|| NEW.ACCOUNT||'"';
  end

  if (vAccType IN ('A', 'C', 'S')) then
  begin
     new.ending = new.opening + new.db - new.cr;
     new.mutation = new.db - new.cr;
  end
  else
  begin
    new.ending = new.opening - new.db + new.cr;
    new.mutation = - new.db + new.cr;
  end
end
^

CREATE TRIGGER GLBUFFER_BINSERT FOR GLBUFFER
ACTIVE BEFORE INSERT POSITION 0
as
declare variable INSTALLGL integer;
declare variable VROW INTEGER;
declare variable PYEAR INTEGER;
declare variable PMONTH INTEGER;
declare variable AP_YEAR INTEGER;
declare variable AP_MONTH INTEGER;
begin
  if (not exists(select * from glimport where application = new.application
          and source = new.source)) then
  begin
     insert into glimport (Application, Source)
            values (new.Application, new.Source);
  end
  SELECT GLYEAR, GLMONTH , INSTALLGL FROM SYSPARAM WHERE ID = 1 INTO :PYEAR, :PMONTH, INSTALLGL;

  if (INSTALLGL = 1) then
  BEGIN
    if (new.application = 'INV') then
    BEGIN
      if (not exists (SELECT * FROM GLCOA WHERE ACCOUNT = NEW.ACCOUNT)) THEN
      begin
         /* 20 AGUSTUS 2007*/
         exception GL_ACCOUNT_NOT_EXIST 'A/C "'|| NEW.ACCOUNT||'" does not exists';
      end
     
      if (not exists (select * from glcoadept where account = new.account and depart = new.dept)) THEN
      BEGIN
          /* 20 AGUSTUS 2007*/
          exception gl_coa_dept 'Dept "'||new.dept||'" not valid for A/C "'|| NEW.ACCOUNT||'"';
      END

      if (not exists (select * from glcoacost where account = new.account and cost = new.cost)) THEN
      BEGIN
          /* 20 AGUSTUS 2007*/
          exception gl_coa_cost 'Cost Center "'||new.cost||'" not valid for A/C "'|| NEW.ACCOUNT||'"';
      END
    END
  
    if (NEW.APPLICATION = '*AP*') then
    BEGIN
       AP_YEAR = EXTRACT(YEAR FROM NEW.TRANSDATE);
       AP_MONTH = EXTRACT(MONTH FROM NEW.TRANSDATE);
     
       if ((PYEAR <> AP_YEAR) or (PMONTH <> AP_MONTH)) then
          exception ALL_OUT_OF_SYSTEM_PERIOD;
    END
  END
  
  IF (NEW.RELATION_CODE IS NULL) THEN NEW.RELATION_CODE = '';
  IF (NEW.RELATION_DOCTYPE IS NULL) THEN NEW.RELATION_DOCTYPE = 0;  
  
  NEW.ORI_ACCOUNT = NEW.ACCOUNT;
  NEW.ORI_DEPT    = NEW.DEPT;
  NEW.ORI_COST    = NEW.COST;
end
^

