CREATE TRIGGER GLCOA_AUPDATE FOR GLCOA
ACTIVE AFTER UPDATE POSITION 0
as
declare variable vAccount VARCHAR(20);
declare variable iRow integer;
begin
  select glretearn from sysparam where id = 1 into :vAccount;
  if ((vAccount is not Null) and (vAccount = old.account)) then
     update sysparam set glretearn = new.Account;
     
  select glcurearn from sysparam where id = 1 into :vAccount;
  if ((vAccount is not Null) and (vAccount = old.account)) then
     update sysparam set glcurearn = new.Account;     
     
     
     
  if (new.Header = 'D') then
  begin
     if (new.defadept <> old.defadept) then
     begin
       select count(*) from glcoadept where account = new.account
       into :iRow;
       if (iRow = 0) then
       begin
         insert into glcoadept (Account, Depart, Note)
                values (new.account, new.defadept, '');
       end
     end
  
     if (new.defacost <> old.defacost) then
     begin
       select count(*) from glcoacost where account = new.account
       into :iRow;

       if (iRow = 0) then
       begin
         insert into glcoacost (Account, Cost, Note)
              values (new.account, new.defacost, '');
       end
     end
  end     
end
