CREATE TRIGGER GLCOA_BINSERT FOR GLCOA
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vIndent integer;
declare variable iRow integer;
begin


  if (new.header <> 'D') then
  begin
     SELECT GL_DEFAULT_DEPT,  GL_DEFAULT_COST FROM SYSPARAM INTO new.defadept, new.defacost;
    new.activestatus = 0;
  end
  
  if ((new.defacost is null) or (new.defacost = '')) then SELECT GL_DEFAULT_DEPT FROM SYSPARAM INTO new.defadept;
  if ((new.defadept is null) or (new.defadept = '')) then SELECT GL_DEFAULT_COST FROM SYSPARAM INTO new.defacost;
  
  if (new.defacost is null) then new.defadept = '0000';
  if (new.defadept is null) then new.defacost = '0000';
    
  if ((NEW.acclevel < 0) or (new.acclevel > 5)) then new.acclevel = 3;
  new.displayname = new.name;
  vIndent = 1;
  WHILE (vIndent < new.AccLevel) do
  begin
    new.displayname  = '    ' || new.displayname;
    vIndent = vIndent + 1;
  end
  if (new.Header = 'D') then
      new.DisplayName = '  ' || new.displayname;
      
end
^

CREATE TRIGGER GLCOA_BUPDATE FOR GLCOA
ACTIVE BEFORE UPDATE POSITION 0
AS
DECLARE VARIABLE VINDENT INTEGER;
DECLARE VARIABLE MAXLEVEL INTEGER;
BEGIN
  IF (NEW.ACCTYPE <> 'S') THEN
  BEGIN
    IF (NEW.HEADER <> 'D') THEN
    BEGIN
       IF (OLD.HEADER = 'D') THEN
       BEGIN
          IF (EXISTS(SELECT * FROM GLJUR WHERE ACCOUNT = NEW.ACCOUNT)) THEN
             EXCEPTION GL_ACCOUNT_USED;

          IF (EXISTS(SELECT * FROM GLACC WHERE ACCOUNT = NEW.ACCOUNT)) THEN
             EXCEPTION GL_ACCOUNT_USED;

          IF (EXISTS(SELECT * FROM GLJURCODE WHERE REFACCOUNT = NEW.ACCOUNT)) THEN
             EXCEPTION GL_ACCOUNT_USED;
       END
    END
    IF ((NEW.ACCLEVEL < 0) OR (NEW.ACCLEVEL > 5)) THEN NEW.ACCLEVEL = 3;
    NEW.DISPLAYNAME = NEW.NAME;
    VINDENT = 0;
    MAXLEVEL = NEW.ACCLEVEL;
    IF (NEW.HEADER <> 'D') THEN MAXLEVEL = MAXLEVEL-1;
    WHILE (VINDENT < MAXLEVEL) DO
    BEGIN
      NEW.DISPLAYNAME  = '    ' || NEW.DISPLAYNAME;
      VINDENT = VINDENT + 1;
    END
  END
  ELSE /* STATISTIC */
  BEGIN
    IF (OLD.ACCTYPE <> 'S') THEN
    BEGIN
      IF (NOT EXISTS(SELECT * FROM GLDEPT WHERE DEPART = NEW.DEFADEPT)) THEN
         SELECT GL_DEFAULT_DEPT FROM SYSPARAM
         INTO NEW.DEFACOST; /* 9 JULY 2007 */

      IF (NOT EXISTS(SELECT * FROM GLCOST WHERE COST = NEW.DEFACOST)) THEN
         SELECT GL_DEFAULT_COST FROM SYSPARAM
         INTO NEW.DEFACOST; /* 9 JULY 2007 */
         
      NEW.ACTIVESTATUS = 1;
      NEW.HEADER = 'D';
      NEW.ACCLEVEL = 1;
      NEW.DISPLAYNAME = NEW.NAME;

      DELETE FROM GLCOADEPT WHERE ACCOUNT = NEW.ACCOUNT AND DEPART <>  NEW.DEFADEPT;
      DELETE FROM GLCOACOST WHERE ACCOUNT = NEW.ACCOUNT AND COST <> NEW.DEFACOST;

      IF (EXISTS(SELECT * FROM GLDEPT WHERE DEPART = NEW.DEFADEPT) AND
          NOT EXISTS(SELECT * FROM GLCOADEPT WHERE ACCOUNT=NEW.ACCOUNT AND DEPART=NEW.DEFADEPT)) THEN
      BEGIN
         INSERT INTO GLCOADEPT (ACCOUNT, DEPART, NOTE)
                VALUES (NEW.ACCOUNT, NEW.DEFADEPT, ''); /* 9 JULY 2007, TADINYA DEFADEPT = '0000' */
      END

      IF (EXISTS(SELECT * FROM GLCOST WHERE COST = NEW.DEFACOST) AND
          NOT EXISTS(SELECT * FROM GLCOACOST WHERE ACCOUNT = NEW.ACCOUNT AND COST=NEW.DEFACOST)) THEN
      BEGIN
         INSERT INTO GLCOACOST (ACCOUNT, COST, NOTE)
              VALUES (NEW.ACCOUNT, NEW.DEFACOST, ''); /* 9 JULY 2007, TADINYA DEFACOST = '0000' */
      END
    END
  END
END
^

