CREATE TRIGGER GLJUR_AU_LOG FOR GLJUR
ACTIVE AFTER UPDATE POSITION 0
AS
BEGIN
  IF (OLD.ACCOUNT <> NEW.ACCOUNT) THEN
     INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                 EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
     VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, OLD.LINE, 'U', NEW.EDITUSER,
                 'ACCOUNT', OLD.ACCOUNT, NEW.ACCOUNT);
                 
  IF (OLD.DEPART <> NEW.DEPART) THEN
     INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                 EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
     VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, OLD.LINE, 'U', NEW.EDITUSER,
                 'DEPART', OLD.DEPART, NEW.DEPART);
                 
  IF (OLD.COST <> NEW.COST) THEN
     INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                 EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
     VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, OLD.LINE, 'U', NEW.EDITUSER,
                 'COST', OLD.COST, NEW.COST);
                 
  IF (OLD.NOTE <> NEW.NOTE) THEN
     INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                 EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
     VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, OLD.LINE, 'U', NEW.EDITUSER,
                 'NOTE', OLD.NOTE, NEW.NOTE);

  IF (OLD.JURDATE <> NEW.JURDATE) THEN
     INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                 EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
     VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, OLD.LINE, 'U', NEW.EDITUSER,
                 'JURDATE', OLD.JURDATE, NEW.JURDATE);

  IF (OLD.REF <> NEW.REF) THEN
     INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                 EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
     VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, OLD.LINE, 'U', NEW.EDITUSER,
                 'REF', OLD.REF, NEW.REF);
  IF (NOT ((OLD.APPLICATION = 'GL') AND (OLD.SOURCE = 'GL'))) THEN
  BEGIN
     IF (OLD.DB <> NEW.DB) THEN
        INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                    EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
        VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, OLD.LINE, 'U', NEW.EDITUSER,
                    'DB', CAST(OLD.DB AS NUMERIC(10,2)), CAST(NEW.DB AS NUMERIC(10,2)));
                    
     IF (OLD.CR <> NEW.CR) THEN
        INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                    EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
        VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, OLD.LINE, 'U', NEW.EDITUSER,
                    'CR', CAST(OLD.CR AS NUMERIC(10,2)), CAST(NEW.CR AS NUMERIC(10,2)));
  END
END
^

