CREATE TRIGGER GLJUR_BUPDATE FOR GLJUR
ACTIVE BEFORE UPDATE POSITION 10
as
declare variable vStatus char(1);
declare variable vRefAccount VARCHAR(20);
declare variable vHeader char(1);
declare variable iRow integer;
declare variable JURCODE VARCHAR(4);
declare variable ACCTYPE CHAR(1);
begin
  if (not exists (select * from GLCOA where account = NEW.ACCOUNT)) THEN
  BEGIN
     /* 7 MARET 2008 */
     exception gl_coa_dept 'Account "'||new.ACCOUNT||'" does not exists !';
  END

  IF (not exists(select * from glcoadept
      where account = new.account and depart = new.depart)) then
  begin
    /* 20 AGUSTUS 2007*/
    exception gl_coa_dept 'Dept "'||new.depart||'" not valid for A/C "'|| NEW.ACCOUNT||'"';
  end

  IF (not exists(select * from glcoacost
          where account = new.account and cost = new.cost)) then
  begin
    /* 20 AGUSTUS 2007*/
    exception gl_coa_cost 'Cost Center "'||new.cost||'" not valid for A/C "'|| NEW.ACCOUNT||'"';
  end
  
  select header, ACCTYPE from glcoa where account = new.account into :vHeader, ACCTYPE;
  if (vHeader <> 'D') then exception gl_coa_not_detail;
  
  if (((new.db = 0) and (new.cr = 0)) or ((new.db <> 0) and (new.cr <> 0)))then
     exception gl_jur_db_cr_not_valid;
     
     
  SELECT RefAccount, status, JURCODE FROM gltrans
  WHERE (PYEAR = NEW.PYEAR)
  AND (PMONTH = NEW.PMONTH)
  AND (TRANSNO = NEW.TRANSNO)
  INTO :vRefAccount, :vStatus, JURCODE;
      
  if (((JURCODE = 'STAT') AND (ACCTYPE <> 'S')) or
      ((JURCODE <> 'STAT') AND (ACCTYPE = 'S'))) then
     exception GL_STATISTIC_ERROR;      
          
  if ((new.counter = 0) and ((new.db <> old.db) or (new.cr <> old.cr))) then
  begin

      
     if (:vStatus <> 'R') then
        exception document_is_not_open;

    if (:vRefAccount = new.Account) then
       exception gl_refaccount_same;
  
     UPDATE gltrans SET
            db = db-old.db + new.db,
            cr = cr-old.cr + new.cr
      WHERE (PYEAR = NEW.PYEAR)
        AND (PMONTH = NEW.PMONTH)
        AND (TRANSNO = NEW.TRANSNO);

     new.RefAccount = :vRefAccount;
  end
end
^

