CREATE TRIGGER GLPERIOD_AI FOR GLPERIOD
ACTIVE AFTER INSERT POSITION 0
as
declare variable vMonth integer;
declare variable vRow Integer;
begin
  vMonth = 1;
  while (vMonth <= 12) do begin
    if (vMonth <> new.pmonth) then begin
       select count(*) from glperiod
       where pyear = new.pyear and pmonth = :vMonth
       into :vRow;
       if (vRow = 0) then
          insert into glperiod (pyear, pmonth, date_start, date_end)
          values (new.pyear, :vMonth, null, null);
          
    end
    vMonth = vMonth + 1;
  end
end
^

CREATE TRIGGER GLPERIOD_BI FOR GLPERIOD
ACTIVE BEFORE INSERT POSITION 0
as
begin
  new.notrans = 0;
  new.notransposted = 0;
  new.status = 'O';
  if (new.date_start is null) then
     execute procedure sp_encodedate(new.pyear, new.pmonth, 1)
             returning_values new.date_start;

  if (new.date_end is null) then
     execute procedure sp_endofmonth(new.date_start)
             returning_values new.date_end;
  
end

^

CREATE TRIGGER GLPERIOD_BU FOR GLPERIOD
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  if (new.date_start is null) then
     execute procedure sp_encodedate(new.pyear, new.pmonth, 1)
             returning_values new.date_start;

  if (new.date_end is null) then
     execute procedure sp_endofmonth(new.date_start)
             returning_values new.date_end;
end

^

CREATE TRIGGER GLSTAT_AI FOR GLSTAT
ACTIVE AFTER INSERT POSITION 0
as
declare variable PYEAR INTEGER;
declare variable M INTEGER;
begin
   SELECT GLYEAR FROM sysparam WHERE ID = 1
   INTO :PYEAR;
   M = 1;
   WHILE (M<=12) DO
   BEGIN
     INSERT INTO GLSTAT (
        PYEAR, PMONTH,CODE,
        BUDGET, ACTUAL,
        EDITDATE,EDITUSER)
     VALUES (
        :PYEAR, :M, NEW.CODE,
        0, 0,
        'NEW', '');
     M = M + 1;
   END
end
^

CREATE TRIGGER GLTRANS_AU_LOG FOR GLTRANS
ACTIVE AFTER UPDATE POSITION 1
AS
BEGIN
  IF (OLD.DOCUMENT <> NEW.DOCUMENT) THEN
     INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                 EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
     VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, 0, 'U', NEW.EDITUSER,
                 'DOCUMENT', OLD.DOCUMENT, NEW.DOCUMENT);
                 
  IF (OLD.STATUS <> NEW.STATUS) THEN
     INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                 EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
     VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, 0, 'U', NEW.EDITUSER,
                 'STATUS', OLD.STATUS, NEW.STATUS);
                 
  IF (OLD.JURCODE <> NEW.JURCODE) THEN
     INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                 EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
     VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, 0, 'U', NEW.EDITUSER,
                 'JURCODE', OLD.JURCODE, NEW.JURCODE);
                 
  IF (OLD.TRANSDATE <> NEW.TRANSDATE) THEN
     INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                 EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
     VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, 0, 'U', NEW.EDITUSER,
                 'TRANSDATE', OLD.TRANSDATE, NEW.TRANSDATE);
                 
  IF (OLD.NOTE <> NEW.NOTE) THEN
     INSERT INTO GLTRANS_LOG (PYEAR, PMONTH, TRANSNO, LINE, DATA_ACTION,
                 EDITUSER, FIELDNAME, OLD_VALUE, NEW_VALUE)
     VALUES(OLD.PYEAR, OLD.PMONTH, OLD.TRANSNO, 0, 'U', NEW.EDITUSER,
                 'NOTE', OLD.NOTE, NEW.NOTE);
END
^

CREATE TRIGGER GLTRANS_AUPDATE FOR GLTRANS
ACTIVE AFTER UPDATE POSITION 0
AS
declare variable vFaktor  NUMERIC(18,4);
DECLARE VARIABLE numrows INTEGER;
DECLARE VARIABLE vLine   INTEGER;
declare variable vAccount VARCHAR(20);
declare variable vRefAcct VARCHAR(20);
declare variable vDept    VARCHAR(4);
declare variable vCost    VARCHAR(4);
declare variable vProject VARCHAR(4);
declare variable vAccType CHAR(1);
declare variable vDB      NUMERIC(18,4);
declare variable vCR      NUMERIC(18,4);
declare variable vJurDate Date;
declare variable vRef varchar(20);
declare variable vNote varchar(40);
declare variable DELTA DOUBLE PRECISION;
BEGIN
vFaktor = 0;
/*
 POSTED TRANSACTION
*/
IF ((NEW.Status = 'R') AND (OLD.Status = 'P')) THEN
BEGIN
   UPDATE GLPERIOD SET
          NoTransPosted = NoTransPosted + 1
   WHERE PYEAR = NEW.PYEAR
     AND PMONTH = NEW.PMONTH;
   vFaktor = -1;
END
/*
  UNPOSTED TRANSACTION
*/
IF ((NEW.Status IN ('P', 'H')) AND (OLD.Status = 'R')) THEN
BEGIN
   UPDATE GLPERIOD SET
          NoTransPosted = NoTransPosted - 1
   WHERE PYEAR = NEW.PYEAR
     AND PMONTH = NEW.PMONTH;
   vFaktor = 1;
END

if (:vFaktor <> 0) then
begin
  /*---------------------------------------------------------------------------*/
  if (old.refaccount <> '') then
  begin
    if (vFaktor = 1) then
    begin
      for select Account, Cost, Depart, Project, DB, CR,
                 Line, JurDate, note, ref
            from gljur
           where (PYear   = Old.PYear)
             and (PMonth  = Old.PMonth)
             and (TransNo =  Old.TransNo)
             and (counter = 0)
            INTO vAccount,  vCost, VDept, vProject, vDB, vCR,
                 vLine, vJurDate, vNote, vRef
      do
      begin
         insert into gljur
           (PYear, PMonth, TransNo, Line, Counter,
                   Account, Depart, Cost, Project,
                   RefAccount, RefDept, RefCost, 
                   DB, CR,
                   Jurdate, Note, Ref)
         values
           (Old.PYear, Old.PMonth, Old.TransNo, :vLine, 1,
                   Old.RefAccount, Old.RefDept, Old.RefCost, :vProject,
                   :vAccount, :VDept, :vCost, :vCR, :vDB,
                   :vJurDate, :vNote, :vRef);
      end
    end
    
  end
  /*---------------------------------------------------------------------------*/
  for select JR.Account, JR.Cost, JR.Depart, JR.Project, JR.DB, JR.CR, COA.ACCTYPE
        from gljur JR
        LEFT JOIN GLCOA COA ON COA.ACCOUNT = JR.ACCOUNT
       where (JR.PYear   = Old.PYear)
         and (JR.PMonth  = Old.PMonth)
         and (JR.TransNo =  Old.TransNo)
        INTO vAccount,  vCost, VDept, vProject, vDB, vCR, vAccType
  do
  begin
      vDB = vFaktor * vDB;
      vCR = vFaktor * vCR;
      
     if (NOT EXISTS(SELECT * FROM GLACC
       where (PYear   = Old.PYear)
         and (PMonth  = Old.PMonth)
         and (Account = :vAccount)
         and (Depart = :vDept)
         and (Cost = :vCost))) THEN
     BEGIN
        insert into glacc
           (PYear, PMonth, Account, Depart, Cost, DB, CR, Opening, Budget)
        values
           (Old.PYear, Old.PMonth, :vAccount, :vDept, :vCost, 0,0,0,0);
     END

     UPDATE GLACC SET DB = DB + :vDB, CR = CR + :vCR
       where (PYear   = Old.PYear)
         and (PMonth  = Old.PMonth)
         and (Account = :vAccount)
         and (Depart = :vDept)
         and (Cost = :vCost);
         
  end
  
  if (vFaktor = -1) then
     delete from gljur
            where (PYear   = Old.PYear)
              and (PMonth  = Old.PMonth)
              and (TransNo =  Old.TransNo)
              and (counter <> 0);
end
END
^

CREATE TRIGGER GLTRANS_BDELETE FOR GLTRANS
ACTIVE BEFORE DELETE POSITION 0
AS
/* ERwin Builtin Fri Mar 31 09:36:02 2000 */
/* default body for GLTRANS_BDELETE */
DECLARE VARIABLE numrows INTEGER;
BEGIN
  IF (OLD.STATUS = 'P') THEN exception all_doc_status_not_open;
  DELETE FROM GLJUR
  WHERE PYEAR = OLD.PYEAR
  AND PMONTH = OLD.PMONTH
  AND TRANSNO = OLD.TRANSNO;

  UPDATE GLPERIOD SET NoTrans = NoTrans - 1
  WHERE PYEAR = OLD.PYEAR
  AND PMONTH = OLD.PMONTH;
END
^

CREATE TRIGGER GLTRANS_BI_PERIOD FOR GLTRANS
ACTIVE BEFORE INSERT POSITION 1
AS
BEGIN
  /* -------------------------------------------------------------------- */
  /* 3/14/2012                                                            */
  /* lock supaya gak bisa diubah diluar periode yang berjalan             */
  /* -------------------------------------------------------------------- */
  IF (NOT EXISTS(SELECT * FROM SYSPARAM WHERE GLYEAR=NEW.PYEAR AND GLMONTH=NEW.PMONTH)) THEN
     EXCEPTION ALL_DATE_ERROR 'Access denied, please check G/L Periode !';
END
^

CREATE TRIGGER GLTRANS_BINSERT FOR GLTRANS
ACTIVE BEFORE INSERT POSITION 0
AS
/* ERwin Builtin Fri Mar 31 09:36:02 2000 */
/* default body for GLTRANS_BINSERT */
DECLARE VARIABLE numrows INTEGER;
DECLARE VARIABLE Nomor INTEGER;
BEGIN
SELECT COUNT(*) FROM GLPERIOD    
     WHERE PYEAR  = NEW.PYEAR
       AND PMONTH = NEW.PMONTH INTO :numrows;
IF (numrows = 0) THEN
BEGIN
  INSERT INTO GLPERIOD
     (PYEAR, PMONTH, STATUS)
  VALUES
     (NEW.PYEAR, NEW.PMONTH, 'O');
END
IF (NEW.TransNo = 0) THEN
BEGIN
   SELECT NoTrans+1 FROM GLPERIOD 
    WHERE PYEAR  = NEW.PYEAR
      AND PMONTH = NEW.PMONTH 
     INTO NEW.TransNo;
END
UPDATE GLPERIOD SET
NoTrans = NoTrans + 1
WHERE PYEAR = NEW.PYEAR
  AND PMONTH = NEW.PMONTH;
  
SELECT RefAccount,RefDept, RefCost From gljurcode
 WHERE jurcode = new.jurcode into
       new.RefAccount, new.RefDept, new.RefCost;

  
END
^

CREATE TRIGGER GLTRANS_BU_CHECK_BALANCE FOR GLTRANS
ACTIVE BEFORE UPDATE POSITION 6
AS
DECLARE VARIABLE NEW_STATUS CHAR(1);
BEGIN
  /* ---------------------------------------------------------------- */
  /* 18 OCT 2007                                                      */
  /* ---------------------------------------------------------------- */
  IF (NEW.DB IS NULL) THEN NEW.DB = 0;
  IF (NEW.CR IS NULL) THEN NEW.CR = 0;

  /* ---------------------------------------------------------------- */
  /* END OF 18 OCT 2007                                               */
  /* ---------------------------------------------------------------- */
  if (NEW.JURCODE <> 'STAT') then
  BEGIN
    NEW_STATUS = NEW.STATUS;
    if (NEW.STATUS = 'p') then NEW.STATUS = 'P';

    IF ((NEW.STATUS IN ('P', 'H')) AND (OLD.STATUS = 'R')) THEN
    BEGIN
      IF (NOT EXISTS(SELECT * FROM GLCOA WHERE ACCOUNT = NEW.REFACCOUNT)) THEN
      BEGIN
         IF (NEW_STATUS <> 'p')  then
         BEGIN
            IF (NEW.DB - NEW.CR NOT BETWEEN -0.05 AND 0.05) THEN
               EXCEPTION GL_TRN_NOTBALANCED;
         END
      END
    END
  END
END
^

