CREATE TRIGGER GLTRANS_LOG_BI FOR GLTRANS_LOG
ACTIVE BEFORE INSERT POSITION 0
AS
BEGIN
  SELECT MAX(LOG_ID) FROM GLTRANS_LOG INTO NEW.LOG_ID;
  IF (NEW.LOG_ID IS NULL) THEN NEW.LOG_ID = 0;
  NEW.LOG_ID = NEW.LOG_ID + 1;
END
