CREATE TRIGGER GLWKS_BINSERT FOR GLWKS
ACTIVE BEFORE INSERT POSITION 0
as
begin
  SELECT MAX(WKS_ID) FROM GLWKS INTO new.wks_id;
  if (new.wks_id is null) then new.wks_id = 0;
  new.wks_id = new.wks_id + 1;
  new.editdate = 'now';
  new.createdate = 'now';
end
