CREATE TRIGGER INVMASTER_BU_LASTUPDATE_ECOS FOR INVMASTER
ACTIVE BEFORE UPDATE POSITION 0
AS
BEGIN
  /* ECOS trigger created at {TIMESTAMP} */
  IF ((NEW.NAME <> OLD.NAME) OR (NEW.GRP <> OLD.GRP) OR
      (NEW.UNIT <> OLD.UNIT) OR (NEW.UNITF <> OLD.UNITF) OR
      (NEW.KONVERSI <> OLD.KONVERSI)) THEN
  BEGIN
      NEW.LASTUPDATE = 'NOW';
  END
END
