CREATE TRIGGER INVPO1_BUPDATE FOR INVPO1
ACTIVE BEFORE UPDATE POSITION 10
AS
DECLARE VARIABLE vStatus CHAR(1);
declare variable iRow integer;
/* 17 FEBRUARY 2005 */
declare variable POCURRENCY VARCHAR(4);
declare variable POPAYMENT VARCHAR(4);
declare variable POPAYMENTDUE VARCHAR(4);

declare variable PRCURRENCY VARCHAR(4);
declare variable PRPAYMENT  VARCHAR(4);
declare variable PRPAYMENTDUE  VARCHAR(4);

BEGIN
  select konversi from invmaster where partno = new.partno into new.konversi;

  if (new.qtyf*new.konversi+new.qty = 0) then
     exception inv_qty_should_not_be_zero;
   if (new.number <> old.number) then
      exception all_detail_number_change;

  /* JIKA BUKAN RECEIVING */
  IF (new.delvqty = old.delvqty) THEN
  BEGIN

     /* 11 JUNE 2001 -CALC CONVERSION */
     SELECT QTYF, QTY FROM inv_calc_konversi(NEW.QTYF, NEW.QTY, NEW.KONVERSI)
     INTO NEW.QTYF, NEW.QTY;
     /* 11 JUNE 2001 -CALC CONVERSION */

     if (NEW.REQNO <> 0) then
     begin
        if (NOT EXISTS(select * from invpr1 where number = NEW.REQNO and partno = new.partno)) THEN
           exception inv_po_rq_notexist;

        /* 17 FEBRUARY 2005 */
        SELECT CURRENCY, PAYMENT, PAYMENTDUE FROM INVPR1
        where number = NEW.REQNO and partno = new.partno
        INTO PRCURRENCY, PRPAYMENT, PRPAYMENTDUE;

        SELECT CURRENCY, PAYMENT, PAYMENTDUE FROM INVPO0
        WHERE NUMBER = NEW.NUMBER INTO POCURRENCY, POPAYMENT, POPAYMENTDUE;

        if (PRCURRENCY <> POCURRENCY) then EXCEPTION AP_DIFFRENT_CURRENCY;
        /* END OF 17 FEBRUARY 2005 */

        select  DISCOUNT, DISCOUNT2, DISCOUNTA, /* 2 DESC 2004 */
                TAX
         from invpr1
        where number = NEW.REQNO
         and partno = new.partno
        INTO  NEW.DISCOUNT, NEW.DISCOUNT2, NEW.DISCOUNTA,
              NEW.TAX;
     end
    /*
     PERHITUNGAN COST SETELAH DISCOUNT DAN TAX
    */
     UPDATE INVPO0 SET
            TOTAL     = TOTAL     - OLD.CALC_COST,
            TOTALO    = TOTALO    - OLD.CALC_COSTO,
            discounta = discounta - OLD.CALC_DISCOUNTA,
            discount  = discount  - OLD.CALC_DISCOUNT,
            discount2 = discount2 - OLD.CALC_DISCOUNT2,
            tax       = tax       - OLD.CALC_TAX,
            TOTQTY    = TOTQTY    - OLD.CALC_QTY
       WHERE NUMBER = old.NUMBER;

    if (OLD.REQNO <> 0) then
    BEGIN


       UPDATE invpr1 SET poqty = poqty - old.calc_qty
       where number = OLD.REQNO
       and partno = old.partno;
    END
    /*
     PERHITUNGAN COST SETELAH DISCOUNT DAN TAX
    */
     new.cost   = new.calc_cost/new.calc_qty*new.konversi;
     UPDATE INVPO0 SET
            TOTAL     = TOTAL     + NEW.CALC_COST,
            TOTALO    = TOTALO    + NEW.CALC_COSTO,
            discounta = discounta + NEW.CALC_DISCOUNTA,
            discount  = discount  + NEW.CALC_DISCOUNT,
            discount2 = discount2 + NEW.CALC_DISCOUNT2,
            tax       = tax       + NEW.CALC_TAX,
            TOTQTY    = TOTQTY    + new.CALC_QTY
       WHERE NUMBER = NEW.NUMBER;

    if (NEW.REQNO<> 0) then
       UPDATE invpr1 SET
           poqty = poqty + new.calc_qty,
           ponumber = new.number
      where number = NEW.REQNO
        and partno = new.partno;
  END
  /* ADA RETUR */
  IF (new.delvqty <> old.delvqty) THEN
  BEGIN
     /* -------------------------------------------------------------------- */
     /* 5/3/2011, RECALC DELIVERED QTY                                       */
     /* -------------------------------------------------------------------- */
     IF (NEW.DELVQTY < 0) THEN
     BEGIN
        SELECT SUM(CALC_QTY) FROM INVRECV1 WHERE PONUMBER = NEW.NUMBER AND PARTNO = NEW.PARTNO
        INTO NEW.DELVQTY;
     END
     /* -------------------------------------------------------------------- */
     /* END OF RECALC DELIVERED QTY                                          */
     /* -------------------------------------------------------------------- */
     ELSE
     BEGIN
        SELECT status FROM INVPO0 WHERE number = new.number INTO :vstatus;
        IF (:vstatus = 'O') THEN EXCEPTION DOCUMENT_IS_OPEN 'PO1#'||NEW.NUMBER ||', status is NOT OPEN ("'||vstatus||'")';
        IF ((new.calc_qty - new.delvqty) < 0) THEN EXCEPTION inv_received_over_qty;
        UPDATE INVPO0 SET delvqty = delvqty - old.delvqty + new.delvqty WHERE NUMBER = OLD.NUMBER;
     END
  END

  UPDATE INVMASTER SET ONORDER = ONORDER - OLD.CALC_QTY+OLD.DELVQTY
  WHERE PARTNO = OLD.PARTNO;

  UPDATE INVMASTER SET ONORDER = ONORDER + NEW.CALC_QTY-NEW.DELVQTY
  WHERE PARTNO = NEW.PARTNO;

END
^

