CREATE TRIGGER INVSTOCK_AUPDATE FOR INVSTOCK
ACTIVE BEFORE UPDATE POSITION 99
AS
declare variable ATEXT CHAR(70);
declare variable vKonversi double precision;

BEGIN

  NEW.QTYONHAND =
           NEW.QTYOPEN     + NEW.QTYIN      + NEW.QTYTRFIN + NEW.QTYPRODIN + NEW.QTYADJ + NEW.QTYSALESRET + NEW.QTYOTRFIN
        -( NEW.QTYRETURN   + NEW.QTYTRFOUT  + NEW.QTYISSUE + 
           NEW.QTYSPOILAGE + NEW.QTYPRODOUT + NEW.QTYSALES + NEW.QTYDIRECTUSE+NEW.QTYOTRFOUT +
           NEW.QTYOUTRECIPE);
  NEW.AMTONHAND =
           NEW.AMTOPEN     + NEW.AMTIN      + NEW.AMTTRFIN + NEW.AMTPRODIN + NEW.AMTADJ + NEW.AMTSALESRET + NEW.AMTOTRFIN
        -( NEW.AMTRETURN   + NEW.AMTTRFOUT  + NEW.AMTISSUE +
           NEW.AMTSPOILAGE + NEW.AMTPRODOUT + NEW.AMTSALES + NEW.AMTDIRECTUSE+NEW.AMTOTRFOUT +
           NEW.AMTOUTRECIPE);

  /* ---------------------------------------------------------------- */
  /* save error log                                                   */
  /* ---------------------------------------------------------------- */
  /* NO DEBUG UDF 20 AGUSTUS 2007                                     */
  /* EXCEPTION WITH TEXT                                              */
  /* ---------------------------------------------------------------- */
  if (new.qtyonhand < -0.09) then
  begin
     ATEXT = OLD.STORE ||' Part No '|| OLD.PARTNO || ' ' || OLD.NAME;
     EXECUTE PROCEDURE SP_DEBUG('** Inventory : Quantity Negative, Store ', ATEXT);
     ATEXT = NEW.QTYONHAND || ' Amount : ' || NEW.AMTONHAND;
     EXECUTE PROCEDURE SP_DEBUG('   Quantity : ', ATEXT);

     /* ---------------------------------------------------------------- */
     /* 31 JAN 2007                                                      */
     /* TO CHANGE FLAG ALLOW NEGATIVE AMOUNT, RUN SETUP IN GL            */
     /* ---------------------------------------------------------------- */
     
     IF (EXISTS(SELECT * FROM SYSPARAM WHERE ID=1 AND INV_STOCK_ALLOW_NEGATIVE<>1)) THEN /* 31 JAN 2007 */
        exception inv_should_not_be_negative_qty 'Negative QUANTITY, Location:"' || OLD.STORE ||'" Part#:"'|| OLD.PARTNO||'"';
  end
  if (new.amtonhand < -0.9) then
  begin
     ATEXT = OLD.STORE ||' Part No '|| OLD.PARTNO || ' ' || OLD.NAME;
     EXECUTE PROCEDURE SP_DEBUG('** Inventory : Amount Negative, Store ', ATEXT);
     ATEXT = NEW.QTYONHAND || ' Amount : ' || NEW.AMTONHAND;
     EXECUTE PROCEDURE SP_DEBUG('   Quantity : ', ATEXT);

     /* ---------------------------------------------------------------- */
     /* 31 JAN 2007                                                      */
     /* TO CHANGE FLAG ALLOW NEGATIVE AMOUNT, RUN SETUP IN GL            */
     /* ---------------------------------------------------------------- */
     
     IF (EXISTS(SELECT * FROM SYSPARAM WHERE ID=1 AND INV_STOCK_ALLOW_NEGATIVE<>1)) THEN /* 31 JAN 2007 */
         exception inv_should_not_be_negative_amt  'Negative AMOUNT, Location:"' || OLD.STORE ||'" Part#:"'|| OLD.PARTNO||'"';
  end

  IF ((NEW.QTYONHAND <> 0) AND (NEW.QTYONHAND NOT BETWEEN -0.001 AND 0.001)) THEN
     NEW.UNITCOST = NEW.AMTONHAND/NEW.QTYONHAND;

  SELECT KONVERSI FROM INVMASTER WHERE PARTNO = NEW.PARTNO INTO VKONVERSI;

  IF ((VKONVERSI < 1) OR (VKONVERSI IS NULL)) THEN VKONVERSI = 1;

  SELECT QTYF, QTY FROM INV_CALC_KONVERSI (0, NEW.QTYONHAND, :VKONVERSI)
  INTO NEW.FL_QTY_FULL, NEW.FL_QTY_LOOSE;
  NEW.FL_COST_FULL = NEW.UNITCOST * VKONVERSI;

  IF (NEW.FL_COST_FULL IS NULL) THEN NEW.FL_COST_FULL = 0;
  IF (NEW.FL_QTY_FULL  IS NULL) THEN NEW.FL_QTY_FULL = 0;
  IF (NEW.FL_QTY_LOOSE IS NULL) THEN NEW.FL_QTY_LOOSE = 0;
  
  /* ------------------------------------------------------------------------ */
  /* MOVE TO BOTTOM 20 AGUSTUS 2007                                           */
  /* update onhand total di master inventory                                  */
  /* ------------------------------------------------------------------------ */
  UPDATE INVMASTER SET
         ONHAND_QTY = ONHAND_QTY-OLD.QTYONHAND + NEW.QTYONHAND,
         ONHAND_AMT = ONHAND_AMT-OLD.AMTONHAND + NEW.AMTONHAND
  WHERE PARTNO = NEW.PARTNO;
END
^

