CREATE TRIGGER SLDO0_RELEASE FOR SLDO0
ACTIVE BEFORE UPDATE POSITION 1
AS
DECLARE VARIABLE VPARTNO VARCHAR(10);
DECLARE VARIABLE VQTY  NUMERIC(18,8);
DECLARE VARIABLE VCOST NUMERIC(18,4);
DECLARE VARIABLE VPRICE NUMERIC(18,4);
DECLARE VARIABLE IROW INTEGER;
DECLARE VARIABLE IYEAR INTEGER;
DECLARE VARIABLE IMONTH INTEGER;
declare variable iSysYear integer;
declare variable iSysMonth integer;
declare variable vSysDate Date;
declare variable VTAX NUMERIC(18,4);
declare variable vInstallAR integer;
declare variable vINV_SALES integer;
declare variable vDue integer;
declare variable VNOTE VARCHAR(40);
declare variable vLINE integer;
BEGIN
  IF ((OLD.STATUS = 'O') AND (NEW.STATUS = 'R')) THEN
  BEGIN
     EXECUTE PROCEDURE SP_YEAR  OLD.OPENDATE RETURNING_VALUES :IYEAR;
     EXECUTE PROCEDURE SP_MONTH OLD.OPENDATE RETURNING_VALUES :IMONTH;
     /*----------------------------------------------------------------------*/
     /* check system date -> month & year                                    */
     /* period harus sama dengan system supaya on hand yang diupdate periode */
     /* yang sama                                                            */
     /*----------------------------------------------------------------------*/
     SELECT invsysdate, installAR, INV_SALES FROM SYSPARAM
      WHERE ID = 1 INTO :vSysDate, :vInstallAR, vINV_SALES;
      
     EXECUTE PROCEDURE SP_YEAR  :vSysDate RETURNING_VALUES :iSysYear;
     EXECUTE PROCEDURE SP_MONTH :vSysDate RETURNING_VALUES :iSysMonth;
     
     if (vINV_SALES = 1) then
        if ((iYear <> iSysYear) or (iMonth <> iSysMonth)) then
           exception inv_period_invalid;
     /*----------------------------------------------------------------------*/
     FOR SELECT PARTNO, calc_qty, PRICE/KONVERSI, COST/KONVERSI, TAX, LINE
           FROM SLDO1
          WHERE NUMBER = OLD.NUMBER 
            INTO VPARTNO, VQTY, VPRICE, VCOST, VTAX, VLINE
     DO
     BEGIN
        /* ************************* UPDATE INVENTORY *********************** */
        if (vINV_SALES = 1) then begin /* jika inv+sales link */
           SELECT unitcost FROM INVSTOCK
           WHERE PYEAR = :iYEAR
           AND PMONTH = :iMONTH
           AND STORE = old.store
           AND PARTNO = :VPARTNO
           INTO :VCOST;
           
           UPDATE SLDO1 SET COST = :VCOST*KONVERSI
           WHERE NUMBER = OLD.NUMBER
           AND PARTNO = :VPARTNO
           AND LINE = :VLINE;

           UPDATE INVSTOCK SET
                  qtysales = qtysales + :vqty,
                  amtsales = amtsales + :vqty*unitcost
            WHERE PYEAR = :IYEAR
              AND PMONTH = :IMONTH
              AND STORE = NEW.STORE
              AND PARTNO = :VPARTNO;
           /**************************************************
               BIN CARD
           **************************************************/
           SELECT NAME FROM SYSCUSTOMER
            WHERE customer = OLD.CUSTOMER  INTO :VNOTE;

           INSERT INTO INVSTOCKBIN
           (STORE, PARTNO, TRANSDATE, COUNTER, QTYIN, QTYOUT, UNITCOST, SOURCE, NOTE, NUMBER)
           VALUES
           (NEW.STORE, :VPARTNO, NEW.OPENDATE, 0, 0, :vqty, :VCost, 'SALE', NEW.CUSTOMER || "-" || :VNOTE, NEW.NUMBER);
         end /* jika inv+sales ling */
        /**************************************************
            MASTER INVENTORY
        **************************************************/
        UPDATE INVMASTER SET
               lastsold = OLD.OPENDATE
        WHERE PARTNO = :VPARTNO;
        
        SELECT COUNT(*) FROM slpart
         WHERE PYEAR = :IYEAR
           AND PMONTH = :IMONTH
           AND CUSTOMER = OLD.CUSTOMER
           AND PARTNO = :VPARTNO INTO :IROW;
           
        if (IROW = 0) then
           INSERT INTO slpart (PYEAR, PMONTH, CUSTOMER, PARTNO, QTY, AMT, QTYRET, AMTRET, COST, COSTRET)
             VALUES (:IYEAR, :IMONTH, OLD.CUSTOMER, :VPARTNO, 0,0,0,0,0,0);
             
        UPDATE slpart SET
               QTY = QTY + :VQTY,
               AMT = AMT + :VQTY * :VPRICE,
               COST = COST + :VQTY * :VCOST
         WHERE PYEAR = :IYEAR
           AND PMONTH = :IMONTH
           AND CUSTOMER = OLD.CUSTOMER
           AND PARTNO = :VPARTNO;
     END
        
     /**************************************************
         CUSTOMER
     **************************************************/
     UPDATE syscustomer SET LASTORDER = OLD.OPENDATE
      WHERE CUSTOMER = OLD.CUSTOMER;
      SELECT COUNT(*) FROM syscustomerinfo WHERE
        CUSTOMER = OLD.CUSTOMER AND
        PYEAR = :IYEAR AND
        PMONTH = :IMONTH
      INTO :IROW;
      if (IROW = 0) then

      INSERT INTO syscustomerinfo (PYEAR, PMONTH, CUSTOMER)
           VALUES (:IYEAR, :IMONTH, OLD.CUSTOMER);

     UPDATE syscustomerinfo
           SET orderamt = orderamt + OLD.TOTAL, ordercount = ordercount + 1
     WHERE
       CUSTOMER = OLD.CUSTOMER AND
       PYEAR = :IYEAR AND
       PMONTH = :IMONTH;
  END
END
^

CREATE TRIGGER SLDO1_BDELETE FOR SLDO1
ACTIVE BEFORE DELETE POSITION 0
AS
declare variable irow integer;
declare variable vdiscount  numeric(18,4);
declare variable vdiscount2 numeric(18,4);
declare variable vtax numeric(18,4);
declare variable vtqty numeric(18,8);
declare variable voldprice numeric(18,4);
declare variable vStatus CHAR(1);
declare variable vTransPercent numeric(18,8);
declare variable vTransFlag integer;
declare variable vPrice numeric(18,4);
declare variable vYear INTEGER;
declare variable vMonth INTEGER;
BEGIN
  select status from sldo0 where number = old.number into :vStatus;

  if (:vStatus <> 'D') then
  BEGIN
      if (old.doprinted = 1) then
       exception inv_sales_do_print;
       
    select inv_salestransport from sysparam into :vTransPercent;

    select trans_flag, price from invmaster
     where partno = old.partno
     into :vTransFlag, :vPrice;  
    /*
     PERHITUNGAN price SETELAH DISCOUNT DAN TAX
    */
    UPDATE sldo0 SET
       TOTAL     = TOTAL     - old.calc_price,
       TOTALO    = TOTALO    - old.calc_priceo,
       totalcost = totalcost - old.calc_cost,
       discounta = discounta - old.calc_discounta,
       discount  = discount  - old.calc_discount,
       discount2 = discount2 - old.calc_discount2,
       tax       = tax       - old.calc_tax,
       transport = transport - old.CALC_TRANSPORT,
       totqty    = totqty    - old.calc_qty
      WHERE NUMBER = old.NUMBER;
      
     /*
      REMOVE PO JIKA SUDAH DITERIMA
     */
    IF (old.sonumber <> 0) THEN
    BEGIN
      UPDATE slord1 SET DelvQty = DelvQty - old.calc_qty
       WHERE Number = old.sonumber
         AND PartNo = old.partno;
    END
    
  END
END
^

CREATE TRIGGER SLDO1_BINSERT FOR SLDO1
ACTIVE BEFORE INSERT POSITION 0
AS
declare variable IROW integer;
declare variable vUnitCost  numeric(18,4);
declare variable vTransPercent numeric(18,8);
declare variable vTransFlag integer;
declare variable vStore varchar(4);
declare variable vOpenDate Date;
declare variable vYear INTEGER;
declare variable vMonth INTEGER;
declare variable vCustomer varchar(6);
declare variable vPrice NUMERIC(18,4);
declare variable vINV_SALES INTEGER;
BEGIN

  select inv_sales, inv_salestransport from sysparam
  into :vINV_SALES, :vTransPercent;
  if ((vTransPercent is null) or (vTransPercent <0)) then vTransPercent = 0;
  /*
    JIKA INV_SALES = 1 STOCK DIPERIKSA, JIKA TIDAK LANGSUNG AJA
  */
  select store, opendate from sldo0
   where number = new.number
    into :vStore, :vOpenDate;

  EXECUTE PROCEDURE SP_YEAR  :vOPENDATE RETURNING_VALUES :vYear;
  EXECUTE PROCEDURE SP_MONTH :vOPENDATE RETURNING_VALUES :vMonth;

  if (vINV_SALES = 1) then begin
     select count(*) from invstock
      where store = :vStore
        and partno = new.partno
        and PYEAR = :vYear
        and PMONTH = :vMonth
       into :iRow;

     if (iRow = 0) then
        exception inv_item_does_not_exist;
  end

  if ((new.qtyf*new.konversi+new.qty) = 0) then
     exception inv_qty_should_not_be_zero;

  select trans_flag, price, konversi from invmaster
    where partno = new.partno
    into :vTransFlag, :vPrice, new.konversi;
    
  if ((new.price is null) or new.price = 0) then new.price = :vPrice;
  if ((vTransFlag is null) or (vTransFlag <0)) then vTransFlag = 0;
  
     
  SELECT LINE+1 FROM sldo0
   WHERE NUMBER = NEW.NUMBER INTO NEW.LINE;
  
  new.transport = :vTransPercent*:vTransFlag;
  /*
    PERHITUNGAN PRICE SETELAH DISCOUNT DAN TAX
  */
  if (new.priceo = 0) then new.priceo = :vPrice;
  new.price  = new.calc_price/new.calc_qty*new.konversi;
  
  
  if ((vUnitCost is null) or (vUnitCost = 0)) then
    select lastcost from invmaster where partno = new.partno into :vUnitCost;
  else
    new.cost   = :vUnitCost * new.konversi;
  UPDATE sldo0 SET
     LINE = LINE + 1,
     TOTAL     = TOTAL     + new.calc_price,
     TOTALO    = TOTALO    + new.calc_priceo,
     totalcost = totalcost + new.calc_cost,
     discounta = discounta + new.calc_discounta,
     discount  = discount  + new.calc_discount,
     discount2 = discount2 + new.calc_discount2,
     tax       = tax       + new.calc_tax,
     transport = transport + new.calc_transport,
     totqty    = totqty    + new.calc_qty
    WHERE NUMBER = NEW.NUMBER;
  /*
   SAVE SALESORDER JIKA SUDAH DITERIMA
  */
  IF (new.sonumber <> 0) THEN
  BEGIN
     SELECT COUNT(*) FROM SLORD1
      WHERE Number = new.sonumber
        AND PartNo = new.partno INTO :IROW;
     if (:IROW = 0 ) then
        exception inv_do_does_not_exist;
     UPDATE SLORD1 SET DelvQty = DelvQty + new.calc_qty
      WHERE Number = new.sonumber
        AND PartNo = new.partno;
  END

END
^

CREATE TRIGGER SLDO1_BUPDATE FOR SLDO1
ACTIVE BEFORE UPDATE POSITION 0
AS
DECLARE VARIABLE vStatus CHAR(1);
declare variable irow integer;
declare variable vUnitCost  numeric(18,4);
declare variable vPrice numeric(18,4);
declare variable vStore varchar(4);
declare variable vOpenDate Date;
declare variable vYear INTEGER;
declare variable vMonth INTEGER;
declare variable vINV_SALES INTEGER;
BEGIN
  if (new.qtyf*new.konversi+new.qty = 0) then exception inv_qty_should_not_be_zero;
  if (new.number <> old.number) then  exception all_detail_number_change;

  select inv_sales from sysparam into :vINV_SALES;

  select store, opendate
   from sldo0 where number = new.number
   into :vStore, :vOpenDate;

  EXECUTE PROCEDURE SP_YEAR  vOPENDATE RETURNING_VALUES :vYear;
  EXECUTE PROCEDURE SP_MONTH vOPENDATE RETURNING_VALUES :vMonth;
  
  /* PERIKSA APAKAH ITEM ADA DI STOCK ATAU TIDAK */
  if (vINV_SALES = 1) then begin /* JIKA INV+SALES LINK */
     select count(*) from invstock
      where store = :vStore
        and partno = new.partno
        and PYEAR = :vYear
        and PMONTH = :vMonth
       into :iRow;
      if (iRow = 0) then exception inv_item_does_not_exist;
  end
  
/************************************** OLD  **********************************/

  /* JIKA BUKA RETURN */
  IF (new.qtyret = old.qtyret) THEN
  BEGIN
    if (old.doprinted = 1) then exception inv_sales_do_print;
    /*
        PERHITUNGAN COST SETELAH DISCOUNT DAN TAX
   */
   UPDATE sldo0 SET
       TOTAL     = TOTAL     - old.calc_price,
       TOTALO    = TOTALO    - old.calc_priceo,
       totalcost = totalcost - old.calc_cost,
       discounta = discounta - old.calc_discounta,
       discount  = discount  - old.calc_discount,
       discount2 = discount2 - old.calc_discount2,
       tax       = tax       - old.calc_tax,
       transport = transport - old.CALC_TRANSPORT,
       totqty    = totqty    - old.calc_qty
      WHERE NUMBER = old.NUMBER;
     /*
      REMOVE SALES ORDER JIKA SUDAH DITERIMA
     */
     IF (old.sonumber <> 0) THEN
     BEGIN
       UPDATE slord1 SET DelvQty = DelvQty - old.calc_qty
        WHERE Number = old.sonumber
          AND PartNo = old.partno;
     END   
/************************************** NEW ***********************************/
    /*
     PERHITUNGAN COST SETELAH DISCOUNT DAN TAX
    */
    SELECT unitcost FROM INVSTOCK
     WHERE PYEAR = :vYEAR
       AND PMONTH = :vMONTH
       AND STORE = :vSTORE
       AND PARTNO = NEW.PARTNO
      INTO :VUNITCOST;

     select price from invmaster
      where partno = new.partno
       into :vPrice;
      
    if ((new.price is null) or new.price = 0) then new.price = :vPrice;
    new.price  = new.calc_price/new.calc_qty*new.konversi;
    if (vUnitCost is null) then
       select lastcost from invmaster where partno = new.partno into :vUnitCost;
    else
       new.cost   = :vUnitCost * new.konversi;
    UPDATE sldo0 SET
       TOTAL     = TOTAL     + new.calc_price,
       TOTALO    = TOTALO    + new.calc_priceo,
       totalcost = totalcost + new.calc_cost,
       discounta = discounta + new.calc_discounta,
       discount  = discount  + new.calc_discount,
       discount2 = discount2 + new.calc_discount2,
       tax       = tax       + new.calc_tax,
       transport = transport + new.CALC_TRANSPORT,
       totqty    = totqty    + new.calc_qty
      WHERE NUMBER = NEW.NUMBER;

     /*
       SAVE NEW SALES ORDER
     */
     IF (new.sonumber <> 0) THEN
     BEGIN
       SELECT COUNT(*) FROM slord1
        WHERE Number = new.sonumber
          AND PartNo = new.partno INTO :IROW;
       if (:IROW = 0 ) then
          exception INV_DO_DOES_NOT_EXIST;
       UPDATE slord1 SET DelvQty = DelvQty + new.calc_qty
        WHERE Number = new.sonumber
          AND PartNo = new.partno;
     END

  END
  /* ADA RETUR */
  IF (new.qtyret <> old.qtyret) THEN
  BEGIN
     SELECT status FROM sldo0
      WHERE number = new.number INTO :vstatus;
     IF (:vstatus = 'O') THEN
        EXCEPTION DOCUMENT_IS_OPEN;
     IF ((new.calc_qty - new.qtyret) < 0) THEN
        EXCEPTION INV_RETUR_OVER_QTY;   
  END
END
^

