CREATE TRIGGER SLORD0_BINSERT FOR SLORD0
ACTIVE BEFORE INSERT POSITION 0
AS
DECLARE VARIABLE vNumber INTEGER; 
BEGIN
 IF ((new.number IS NULL) OR (new.number = 0)) THEN
 BEGIN
    SELECT MAX(number) FROM slord0 INTO :vNumber;
    IF (vNumber IS NULL) THEN vNumber = 1;
    ELSE vNumber = :vNumber + 1;
    new.number = :vNumber; 
 END
 NEW.LINE = 0;
 NEW.TOTAL = 0;
 NEW.STATUS = 'O';
END
^

CREATE TRIGGER SLORD0_BUPDATE FOR SLORD0
ACTIVE BEFORE UPDATE POSITION 0
AS
declare variable irow integer;
BEGIN
  /* Trigger Text */
  if (NEW.CUSTOMER <> OLD.CUSTOMER) then
  BEGIN
     SELECT COUNT(*) FROM sldo1
     WHERE NUMBER = NEW.NUMBER
     INTO :IROW;
     if (IROW <> 0) then
        exception SALES_CUST_NOT_MATCH;
  END
     
  new.editdate = 'now';  
  IF (old.Status = 'O' and new.status = 'O') THEN
  BEGIN     
    /* tolak ubah store atau supplier kalau detail sudah ada */   
    select count(*) from slord1
     where Number = new.number into :irow;
  END
  ELSE
     /* jika "STATUS" bukan "O" -> "S" (send)
                            "S" -> "P" (partial delivered)
     */
  BEGIN
     if (new.status <> 'D') then
     BEGIN
     if (new.delvqty = old.delvqty) then
        IF (NOT (((old.status = 'O') AND (new.status = 'R')) OR
                 ((old.status = 'R') AND (new.status = 'P')) OR
                 ((old.status = 'P') AND (new.status = 'D')) )) THEN
           EXCEPTION DOCUMENT_IS_NOT_OPEN;
     if (new.delvqty <> old.delvqty) then
     begin
        if (new.totqty = new.delvqty) then
            new.status = 'F';
        if (new.totqty > new.delvqty) then
            new.status = 'P';
        if (new.delvqty = 0) then
            new.status = 'R';
     end
     END
  END
END
^

CREATE TRIGGER SLORD1_BDELETE FOR SLORD1
ACTIVE BEFORE DELETE POSITION 0
AS
declare variable vdiscount  numeric(18,4);
declare variable vdiscount2 numeric(18,4);
declare variable vtax numeric(18,4);
declare variable vtqty numeric(18,8);
declare variable voldprice numeric(18,4);
declare variable vStatus CHAR(1);
begin
  SELECT status FROM slord0
   WHERE NUMBER = OLD.NUMBER
    INTO :vStatus;
  if (:vStatus <> 'D') then
  begin
  /*
   PERHITUNGAN price SETELAH DISCOUNT DAN TAX
  */
   UPDATE slord0 SET
        TOTAL     = TOTAL     - old.calc_price,
        TOTALO    = TOTALO    - old.calc_priceo,
        discounta = discounta - old.calc_discounta,
        discount  = discount  - old.calc_discount,
        discount2 = discount2 - old.calc_discount2,
        tax       = tax       - old.calc_tax,
        TOTQTY    = TOTQTY    - old.calc_qty   
     WHERE NUMBER = old.NUMBER;

   update INVMASTER set SalesOrder = SalesOrder - old.calc_qty
     where PARTNO = OLD.PARTNO;     
  END
