CREATE TRIGGER SLORD1_BINSERT FOR SLORD1
ACTIVE BEFORE INSERT POSITION 0
AS
BEGIN
  if (new.qtyf*new.konversi+new.qty = 0) then
     exception inv_qty_should_not_be_zero;
  SELECT LINE+1, CUSTOMER FROM SLORD0
   WHERE NUMBER = NEW.NUMBER INTO NEW.LINE,
     NEW.CUSTOMER;
  /*
    PERHITUNGAN COST SETELAH DISCOUNT DAN TAX
  */
  new.price = new.calc_price;
  UPDATE SLORD0 SET
     LINE = LINE + 1,
     TOTAL     = TOTAL     + new.calc_price,
     TOTALO    = TOTALO    + new.calc_priceo,
     discounta = discounta + new.calc_discounta,
     discount  = discount  + new.calc_discount,
     discount2 = discount2 + new.calc_discount2,
     tax       = tax       + new.calc_tax,
     TOTQTY    = TOTQTY    + new.calc_qty
    WHERE NUMBER = NEW.NUMBER;

  update INVMASTER set SalesOrder = SalesOrder + new.calc_qty
   where PARTNO = NEW.PARTNO;
  new.delvqty = 0;
  NEW.FLAG_DELIVERED = 0;
END
^

CREATE TRIGGER SLORD1_BUPDATE FOR SLORD1
ACTIVE BEFORE UPDATE POSITION 0
AS
DECLARE VARIABLE vStatus CHAR(1);
declare variable vcustomer VARCHAR(6);
BEGIN
  select konversi from invmaster where partno = new.partno into new.konversi;
  
  if (new.qtyf*new.konversi+new.qty = 0) then exception inv_qty_should_not_be_zero;
   if (new.number <> old.number) then exception all_detail_number_change;
  /* JIKA BUKAN RECEIVING */
  IF (new.delvqty = old.delvqty) THEN
  BEGIN   
    /*
     PERHITUNGAN price SETELAH DISCOUNT DAN TAX
    */
     UPDATE slord0 SET
        TOTAL     = TOTAL     - old.calc_price,
        TOTALO    = TOTALO    - old.calc_priceo,
        discounta = discounta - old.calc_discounta,
        discount  = discount  - old.calc_discount,
        discount2 = discount2 - old.calc_discount2,
        tax       = tax       - old.calc_tax,
        TOTQTY    = TOTQTY    - old.calc_qty
       WHERE NUMBER = old.NUMBER;  
    /*
     PERHITUNGAN price SETELAH DISCOUNT DAN TAX
    */  
     new.price  = new.calc_price;
     UPDATE slord0 SET
        TOTAL     = TOTAL     + new.calc_price,
        TOTALO    = TOTALO    + new.calc_priceo,
        discounta = discounta + new.calc_discounta,
        discount  = discount  + new.calc_discount,
        discount2 = discount2 + new.calc_discount2,
        tax       = tax       + new.calc_tax,
        TOTQTY    = TOTQTY    + new.calc_qty
       WHERE NUMBER = NEW.NUMBER;

    update INVMASTER set SalesOrder = SalesOrder - old.calc_qty
     where PARTNO = OLD.PARTNO;
            
    update INVMASTER set SalesOrder = SalesOrder + new.calc_qty
     where PARTNO = NEW.PARTNO;

  END
  SELECT status, customer FROM slord0 WHERE number = new.number
  INTO :vstatus, vcustomer;
  /* ADA DELIVERY (DI UPDATE DARI SLDO1) */
  IF (new.delvqty <> old.delvqty) THEN
  BEGIN
     IF (:vstatus = 'O') THEN
         EXCEPTION DOCUMENT_IS_OPEN;
     IF ((new.calc_qty - new.delvqty) < 0) THEN
        EXCEPTION inv_received_over_qty;
        
    UPDATE slord0 SET 
       delvqty = delvqty - old.delvqty + new.delvqty
      WHERE NUMBER = OLD.NUMBER;
      
    update INVMASTER set SalesOrder = SalesOrder + old.delvqty - new.delvqty
     where PARTNO = NEW.PARTNO;
  END

  if (new.customer <> vcustomer) then
     select customer from slord1 where number = new.number
     into new.customer;
     
  if (new.delvqty >= new.calc_qty) then new.flag_delivered = '1';
  else new.flag_delivered = '0';
END
^

