CREATE TRIGGER SLRET0_BINSERT FOR SLRET0
ACTIVE BEFORE INSERT POSITION 0
AS
DECLARE VARIABLE vSysDate DATE;
DECLARE VARIABLE vNumber INTEGER; 
BEGIN
 SELECT invsysdate FROM SYSPARAM
  WHERE ID = 1 INTO :vSysDate;


 IF (new.opendate < :vSysDate) THEN
    EXCEPTION INV_TRANS_DATE_INVALID;


 IF ((new.number IS NULL) OR (new.number = 0)) THEN
 BEGIN
    SELECT MAX(number) FROM SLRET0 INTO :vNumber;
    IF (vNumber IS NULL) THEN vNumber = 1;
    ELSE vNumber = :vNumber + 1;
    new.number = :vNumber; 
 END
 NEW.LINE = 0;
 NEW.TOTAL = 0;
 NEW.STATUS = 'O';
END
^

CREATE TRIGGER SLRET0_BUPDATE FOR SLRET0
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable irow integer;
DECLARE VARIABLE vSysDate DATE;
BEGIN
  /* Trigger Text */
  new.editdate = 'now';  
  IF (old.Status = 'O' and new.status = 'O') THEN
  BEGIN     
    /* tolak ubah store atau supplier kalau detail sudah ada */   
    select count(*) from SLRET1
     where Number = new.number into :irow;

    if ((:irow > 0) and
        ((NEW.STORE <> OLD.Store) or (new.customer <> old.customer))) then
        EXCEPTION DETAIL_ALREADY_EXIST;
   /* check date of transaction */
   SELECT invsysdate FROM SYSPARAM
    WHERE ID = 1 INTO :vSysDate;
    
   IF ((new.opendate < :vSysDate) and (new.status = 'O')) THEN
      EXCEPTION INV_TRANS_DATE_INVALID;
  END
  ELSE
     /* jika "STATUS" bukan "O" -> "R" (release)
                            "R" -> "C" (end of day)
     */
     if (not ((old.status IN ('C', 'R', 'O')) and (new.status = 'D'))) then
     begin
       IF (NOT (((old.status = 'O') AND (new.status = 'R'))  OR
                ((old.status = 'R') AND (new.status = 'C'))  or
                ((old.status = 'O') AND (NEW.STATUS = 'X')))) THEN
          EXCEPTION DOCUMENT_IS_NOT_OPEN;
     end
END
^

CREATE TRIGGER SLRET0_POST_AR FOR SLRET0
ACTIVE BEFORE UPDATE POSITION 0
as
dECLARE VARIABLE vARNUMBER INTEGER;
declare variable vInstallAR Integer;
declare variable FLAG_AR INTEGER;
begin
  IF ((OLD.STATUS = 'O') AND (NEW.STATUS = 'R')) THEN
  BEGIN
     SELECT installAR FROM SYSPARAM WHERE ID = 1 INTO :vInstallAR;
    /**************************************************
         UPDATE A/R KALAU DIINSTALL
      **************************************************/        
     if (vInstallAR = 1) then
     begin
        SELECT FLAG_AR FROM SYSCUSTOMER WHERE CUSTOMER = NEW.CUSTOMER INTO FLAG_AR;
        if (FLAG_AR = 1) then /* 17-JAN-2005 */
        BEGIN
          select max(Number) from arvch into new.ARNumber;
          if (new.ARNumber is null) then new.arnumber = 0;

          new.arnumber = new.ARnumber+1;
          INSERT INTO arvch
            (number, document, opendate, duedate, customer,
             source, sourceid,
             total, adjust, paid, paidprepare)
          VALUES
            (new.ARnumber, new.document, old.opendate, old.opendate, old.customer,
            'CN', new.number,
             old.total, 0, 0, 0);
        END
     end
  END
end
^

CREATE TRIGGER SLRET0_POST_GL FOR SLRET0
ACTIVE AFTER UPDATE POSITION 0
as
declare variable vInstallGL integer;
declare variable vRow integer;
declare variable vRowInv integer;
declare variable vPrice NUMERIC(18,4);
declare variable vNetPrice NUMERIC(18,4);
declare variable vCost NUMERIC(18,4);
declare variable vName VARCHAR(40);
declare variable vAccount VARCHAR(20);
declare variable vAccSales VARCHAR(20);
declare variable vAccCOGS VARCHAR(20);
declare variable vTaxAccount VARCHAR(20);
declare variable vDept varchar(4);
declare variable vSplitTax INTEGER;
declare variable vINV_SALES integer;
begin
   /**************************************************
    UPDATE G/P KALAU DIINSTALL
   **************************************************/
   select inv_ar_split_tax, inv_ar_tax_account,installgl, inv_sales
    from sysparam
    into :vSplitTax, vTaxAccount, :vInstallGL, vINV_SALES;

   if ((old.status <> 'R') and (new.status = 'R') and (old.total <> 0) and (vInstallGL = 1)) then
   begin
      select invdept.gl_dept from invstore
      left join invdept on invdept.dept = invstore.dept
      where invstore.store = new.store into :vDept;

      vRow = 2;
      vRowInv = 1;
      for select invgroup.accinv, invgroup.accsales, invgroup.acccogs, invgroup.name,
                 sum(calc_price), sum(calc_netprice), sum(calc_cost)
            from SLRET1 RT1
                 left join invmaster on RT1.partno = invmaster.partno
                 left join invgroup  on invgroup.grp    = invmaster.grp
            where RT1.number = old.number
            group by invgroup.accinv, invgroup.accsales, invgroup.acccogs, invgroup.name
            into :vAccount, :vAccSales, :vAccCOGS, :vName,
                 :vPrice,   :vNetPrice, :vCost
      do
      begin
         if (vINV_SALES = 1) then begin /* JIKA SALES + INVENTORY LINK */
            /*----------------------------------------------------------------*/
            /* inventory (db) pada cost (cr)                                  */
            /*----------------------------------------------------------------*/
            /* db - inventory bertambah */
            insert into glbuffer
                       (APPLICATION, SOURCE, NUMBER, ID, transdate,
                        ACCOUNT, DEPT, COST, PROJECT,
                        NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
                values ('SL', 'RET', old.number, :vRow, old.opendate,
                        :vAccount, :vDept, '0000', '',
                        :vName, new.document, :vCost, 0, 'now', NEW.EDITUSER);
             vRowInv = vRowInv + 1;
             /* cr - harga pokok penjualan berkurang */
            insert into glbuffer
                       (APPLICATION, SOURCE, NUMBER, ID, transdate,
                        ACCOUNT, DEPT, COST, PROJECT,
                        NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
                values ('SL', 'RET', old.number, :vRow, old.opendate,
                        :vAccCOGS, '0000', '0000', '',
                        :vName, new.document, 0, :vCost, 'now', NEW.EDITUSER);
             vRowInv = vRowInv + 1;             
         end /* jika inv+sales link */
         /*----------------------- --------------------------------------------*/
         /* sales(db) sales berkurang                                         */
         /*-------------------------------------------------------------------*/                                     
         if (vSplitTax = 1) then vPrice = vNetPrice;
           insert into glbuffer
                    (APPLICATION, SOURCE, NUMBER, ID, transdate,
                     ACCOUNT, DEPT, COST, PROJECT,
                     NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
             values ('SL', 'CN', old.number, :vRow, old.opendate,
                     :vAccSales, '0000', '0000', '',
                     :vName, new.document, :vPrice, 0, 'now', NEW.EDITUSER);
          vRow = vRow + 1;
      end
      if (vSplitTax = 1) then
      begin
         insert into glbuffer
                    (APPLICATION, SOURCE, NUMBER, ID, transdate,
                     ACCOUNT, DEPT, COST, PROJECT,
                     NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
             values ('SL', 'CN', old.number, :vRow, old.opendate,
                     :vTaxAccount, '0000', '0000', '',
                     'Tax', new.document, new.tax, 0, 'now', NEW.EDITUSER);
          vRow = vRow + 1;
      end
      /* posting pada a/r, ar berkurang (credit) */
      select name, account from syscustomer
       where customer = old.customer
        into :vName, :vAccount;
        
      if (vAccount = '') then
         select glaccount from syscustomer
           left join syscustomertype on customertype = custtype
          where customer = old.customer
           into :vAccount;

       insert into glbuffer
                  (APPLICATION, SOURCE, NUMBER, ID, TRANSDATE,
                   ACCOUNT, DEPT, COST, PROJECT,
                   NOTE, REF, DB, CR, EXPORTDATE, EXPORTUSER)
           values ('SL', 'CN', old.number, :vRow, old.opendate,
                   :vAccount, '0000', '0000', '',
                   :vName, new.document, 0, old.total, 'now', USER);
  END
end
^

CREATE TRIGGER SLRET0_RELEASE FOR SLRET0
ACTIVE BEFORE UPDATE POSITION 1
AS
DECLARE VARIABLE VPARTNO VARCHAR(10);
DECLARE VARIABLE VQTY  DOUBLE PRECISION;
DECLARE VARIABLE VCOST DOUBLE PRECISION;
DECLARE VARIABLE IROW INTEGER;
DECLARE VARIABLE VNOTE VARCHAR(40);
DECLARE VARIABLE IYEAR INTEGER;
DECLARE VARIABLE IMONTH INTEGER;
declare variable iSysYear integer;
declare variable iSysMonth integer;
declare variable vSysDate Date;
declare variable VTAX DOUBLE PRECISION;
declare variable vINV_SALES integer;
BEGIN
  SELECT invsysdate, INV_SALES FROM SYSPARAM
  WHERE ID = 1 INTO :vSysDate, :vINV_SALES;

  IF ((OLD.STATUS = 'O') AND (NEW.STATUS = 'R') AND (vINV_SALES=1)) THEN
  BEGIN
     EXECUTE PROCEDURE SP_YEAR  OLD.OPENDATE RETURNING_VALUES :IYEAR;
     EXECUTE PROCEDURE SP_MONTH OLD.OPENDATE RETURNING_VALUES :IMONTH;
     /*----------------------------------------------------------------------*/
     /* check system date -> month & year                                    */
     /* period harus sama dengan system supaya on hand yang diupdate periode */
     /* yang sama                                                            */
     /*----------------------------------------------------------------------*/

     EXECUTE PROCEDURE SP_YEAR  :vSysDate RETURNING_VALUES :iSysYear;
     EXECUTE PROCEDURE SP_MONTH :vSysDate RETURNING_VALUES :iSysMonth;
     
     if ((iYear <> iSysYear) or (iMonth <> iSysMonth))then
        exception inv_period_invalid;
     /*----------------------------------------------------------------------*/
     FOR SELECT PARTNO, QTYF*KONVERSI+QTY, TAX
           FROM SLRET1
          WHERE NUMBER = OLD.NUMBER
            INTO VPARTNO, VQTY, VTAX
     DO
     BEGIN
        SELECT COUNT(*) FROM INVSTOCK
         WHERE PYEAR = :IYEAR
           AND PMONTH = :IMONTH
           AND STORE = OLD.STORE
           AND PARTNO = :VPARTNO
         INTO :IROW;
         
         if (IROW = 0) then exception inv_item_does_not_exist;
           
         SELECT unitcost FROM INVSTOCK
         WHERE PYEAR = :IYEAR
           AND PMONTH = :IMONTH
           AND STORE = OLD.STORE
           AND PARTNO = :VPARTNO
          INTO :VCOST;
         
        UPDATE INVSTOCK SET
               qtysales = qtysales + :VQTY,
               amtsales = amtsales + :VQTY*:VCOST
         WHERE PYEAR = :IYEAR
           AND PMONTH = :IMONTH
           AND STORE = OLD.STORE
           AND PARTNO = :VPARTNO;
        /**************************************************
               BIN CARD
        **************************************************/
        SELECT NAME FROM SYSCUSTOMER
         WHERE customer = OLD.CUSTOMER  INTO :VNOTE;
          INSERT INTO INVSTOCKBIN
               (STORE, PARTNO, TRANSDATE, COUNTER, QTYIN, QTYOUT, UNITCOST, SOURCE, NOTE, NUMBER)
        VALUES
               (OLD.STORE, :VPARTNO, OLD.OPENDATE, 0, 0, :VQTY, :VCOST, 'SALE', OLD.CUSTOMER || "-" || :VNOTE, OLD.NUMBER);
        /**************************************************
            MASTER INVENTORY
        **************************************************/
        UPDATE INVMASTER SET
               lastsold = OLD.OPENDATE
        WHERE PARTNO = :VPARTNO;
     END

     /**************************************************
         CUSTOMER
     **************************************************/
      SELECT COUNT(*) FROM syscustomerinfo WHERE
        CUSTOMER = OLD.CUSTOMER AND
        PYEAR = :IYEAR AND
        PMONTH = :IMONTH
      INTO :IROW;
      if (IROW = 0) then

      INSERT INTO syscustomerinfo (PYEAR, PMONTH, CUSTOMER)
           VALUES (:IYEAR, :IMONTH, OLD.CUSTOMER);

     UPDATE syscustomerinfo
           SET returnamt = returnamt + OLD.TOTAL, returncount = returncount + 1
     WHERE
       CUSTOMER = OLD.CUSTOMER AND
       PYEAR = :IYEAR AND
       PMONTH = :IMONTH;
  END
END
^

CREATE TRIGGER SLRET1_BDELETE FOR SLRET1
ACTIVE BEFORE DELETE POSITION 0
AS
declare variable IROW integer;
declare variable vtax numeric(18,4);
declare variable vtQty numeric(18,4);
declare variable vPrice numeric(18,4);
declare variable vStore varchar(10);
BEGIN
  /*
    PERHITUNGAN COST SETELAH DISCOUNT DAN TAX
  */
  vtqty      = old.qty / old.konversi + old.qtyf;  
  vtax       = old.price * old.tax /100;

  UPDATE SLRET0 SET
     TOTAL     = TOTAL     - :vtqty * old.price,
     totalcost = totalcost - :vtqty * old.cost,
     tax       = tax       - :vtqty * :vtax
    WHERE NUMBER = old.NUMBER;

  /*
   UPDATE DO JIKA SUDAH DITERIMA
  */
  UPDATE SLDO1 SET QtyRet = QtyRet - (old.qty + old.qtyf * old.konversi)
   WHERE Number = old.donumber
     AND PartNo = old.partno;
END
^

CREATE TRIGGER SLRET1_BINSERT FOR SLRET1
ACTIVE BEFORE INSERT POSITION 0
AS
declare variable IROW integer;
declare variable vtax numeric(18,4);
declare variable vtqty numeric(18,8);
declare variable vPrice numeric(18,4);
declare variable vStore varchar(10);
declare variable vCustomer VARCHAR(6);
declare variable vDOCustomer VARCHAR(6);
BEGIN

  /*
   periksa apakah return ada di do atau tidak
  */
  SELECT COUNT(*) FROM SLDO1
   WHERE Number = new.donumber
     AND PartNo = new.partno INTO :IROW;
     if (:IROW = 0 ) then
        exception inv_do_does_not_exist;
        

  select customer from SLDO0
    where number = new.donumber into :vDOCustomer;

  select store, customer, line+1 from SLRET0
   where number = new.number
    into :vStore, :vCustomer, new.line;

  if (vDOCustomer <> vCustomer) then exception sales_cust_not_match;

  select cost/calc_qty, konversi, calc_netprice/calc_qty, tax from SLDO1
  where number = new.number
  and line = new.doline
  and partno = new.partno
  into new.cost, new.konversi, new.price, new.tax;

  if ((new.qtyf*new.konversi+new.qty) = 0) then
     exception inv_qty_should_not_be_zero;

  /*
    PERHITUNGAN COST SETELAH DISCOUNT DAN TAX
  */
  vtqty      = new.qty / new.konversi + new.qtyf;  
  vtax       = new.price * new.tax /100;

  UPDATE SLRET0 SET
     LINE = LINE + 1,
     TOTAL     = TOTAL     + :vtqty * NEW.price,
     totalcost = totalcost + :vtqty * new.cost,
     tax       = tax       + :vtqty * :vtax
    WHERE NUMBER = NEW.NUMBER;

  UPDATE SLDO1 SET QtyRet = QtyRet + (new.qty + new.qtyf * new.konversi)
   WHERE Number = new.donumber
     AND PartNo = new.partno;
END
^

CREATE TRIGGER SLRET1_BUPDATE FOR SLRET1
ACTIVE BEFORE UPDATE POSITION 0
AS
DECLARE VARIABLE vStatus CHAR(1);
declare variable irow integer;
declare variable vtax numeric(18,4);
declare variable vtqty numeric(18,8);

declare variable vPrice numeric(18,4);
declare variable vStore varchar(10);
declare variable vOpenDate Date;
declare variable vCustomer VARCHAR(6);
declare variable vDOCustomer VARCHAR(6);
BEGIN
   /*
     PERIKSA APAKAH ADA DI DO ATAU TIDAK
   */
   SELECT COUNT(*) FROM sldo1
    WHERE Number = new.donumber
      AND PartNo = new.partno INTO :IROW;

   if (:IROW = 0 ) then exception INV_DO_DOES_NOT_EXIST;

  select customer from SLDO0
    where number = new.donumber into :vDOCustomer;
    
  select store, opendate, customer from SLRET0
   where number = new.number
    into :vStore, :vOpenDate, :vcustomer;
    
  if (vDOCustomer <> vCustomer) then
     exception sales_cust_not_match;

  if (new.qtyf*new.konversi+new.qty = 0) then exception inv_qty_should_not_be_zero;
  if (new.number <> old.number) then exception all_detail_number_change;

  /*
   PERHITUNGAN COST SETELAH DISCOUNT DAN TAX
  */
   vtqty      = old.qty / old.konversi + old.qtyf;
   vtax       = old.price * old.tax /100;
   UPDATE SLRET0 SET
      TOTAL     = TOTAL     - :vtqty * old.price,
      totalcost = totalcost - :vtqty * old.cost,
      tax       = tax       - :vtqty * :vtax
     WHERE NUMBER = old.NUMBER;
   /*
    REMOVE DELIVERY ORDER JIKA SUDAH DITERIMA
   */
   UPDATE sldo1 SET QtyRET = QtyRET - (old.qty + old.qtyf * old.konversi)
      WHERE Number = old.donumber
        AND PartNo = old.partno;
        
        
  /* LOAD INFO DARI DELIVERY ORDER */
  select cost/calc_qty, konversi, calc_netprice/calc_qty, tax from SLDO1
    where number = new.number 
    and partno = new.partno
    into new.cost, new.konversi, new.price, new.tax;
  /*
   PERHITUNGAN COST SETELAH DISCOUNT DAN TAX
  */
   vtqty      = new.qty / new.konversi + new.qtyf;
   vtax       = new.price * new.tax /100;
    UPDATE SLRET0 SET
      TOTAL     = TOTAL     + :vtqty * NEW.price,
      totalcost = totalcost + :vtqty * new.cost,
      tax       = tax       + :vtqty * :vtax
     WHERE NUMBER = NEW.NUMBER;
   /*
    ADD DELIVERY ORDER JIKA SUDAH DITERIMA
   */
     UPDATE sldo1 SET QtyRET = QtyRET + (new.qty + new.qtyf * new.konversi)
      WHERE Number = new.donumber
        AND PartNo = new.partno;
END
^

