CREATE TRIGGER SYS_PARAM_APEOD FOR SYSPARAM
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable vToday DATE;
declare variable vTomorow DATE;
declare variable vDebug INTEGER;
begin
  execute procedure sp_dateonly(old.apsysdate) returning_values(vToday);
  vTomorow = vToday + 1;
  if (new.apsysdate = vTomorow) then
  begin
     /* ------------------------------------------------------------------ */
     /* STATUS ADJUSTMENT                                                  */
     /*   O=(Prepare) -> C=(Release)-> Masuk ke GL                         */
     /* ------------------------------------------------------------------ */
     IF (EXISTS (SELECT * FROM APADJ WHERE OPENDATE <= :VTODAY AND STATUS = 'O')) THEN
        EXCEPTION AP_EOD_ADJ_OPEN;

     IF (EXISTS (SELECT * FROM APDEPOS0 WHERE OPENDATE <= :VTODAY AND STATUS = 'O')) THEN
        EXCEPTION AP_EOD_DEP0_OPEN;

     IF (EXISTS (SELECT * FROM APDEPOS1 WHERE APPLIEDDATE <= :VTODAY AND STATUS = 'O')) THEN
        EXCEPTION AP_EOD_DEP1_OPEN;
        
     IF (EXISTS (SELECT * FROM APDEPOS0_JUR WHERE OPENDATE <= :VTODAY AND STATUS = 'O')) THEN /* 31 MARET 2008 */
        EXCEPTION AP_EOD_DEP0_OPEN 'Access denied, please release Deposit Adjustment Document.';
        
     /* 22 APRIL 2006 */
     IF (EXISTS (SELECT * FROM APVCH WHERE OPENDATE <= :VTODAY AND GLSTATUS = 'O' AND SOURCE IN ('F','S'))) THEN
        EXCEPTION AP_EOD_COMMISSION;

     IF (EXISTS (SELECT * FROM APCASH0 WHERE DUEDATE <= :VTODAY AND STATUS IN ('O', 'A'))) THEN
        EXCEPTION AP_EOD_CASH_DUE_INVALID;
     /* 22 april 2006 */
     update apadj set status = 'C'
      where opendate = :vToday
        and status = 'O';
        /* ------------------------------------------------------------------ */
        /* STATUS CASH                                                        */
        /*  PERUBAHAN STATUS DARI CASH PAYMENT                                */
        /*    1. PREPARE=O   [MANUAL] ATAU OPEN PERTAMA KALI DIBUAT           */
        /*    2. APPROVED=A  [MANUAL] SETELAH CHECK DIBUAT & DITANDATANGANI   */
        /*    3. ISSUED=R    [MANUAL] SETELAH CHECK DISERHAKAN PADA SUPPLIER  */
        /*                            -> ==> MASUK KE G/L                     */
        /*                            -> ==> MASUK KE BANK BOOK               */
        /*    4. RECONCILE=L [MANUAL] CHECK TELAH CAIR                        */
        /*    5. CLOSE=C     [EOD]    SESUAI DENGAN reconciledate <= :vToday  */
        /*                            -> EOD ==> MASUK KE G/L                 */
        /* ------------------------------------------------------------------ */
        update apcash0 set status = 'C'
          where reconciledate <= :vToday and status = 'L';
        /* ------------------------------------------------------------------ */
        /* STATUS DEPOSIT                                                     */
        /*   O=(Prepare) -> C=(Release)-> Masuk ke GL                         */
        /* ------------------------------------------------------------------ */          
        /*update apdepos0 set status = 'C'
          where opendate <= :vToday and status = 'R';
          
        update apdepos1 set status = 'C'
          where applieddate <= :vToday and status = 'R';*/
     /* ---------------------------------------------------------------- */
     /* 16 nov 2005                                                      */
     /* ---------------------------------------------------------------- */
     UPDATE APVCH SET GLSTATUS = 'R' WHERE OPENDATE <= :vToday
     AND SOURCE IN ('F','S') AND ((GLSTATUS <> 'R') OR (GLSTATUS IS NULL));
  end
end

^

CREATE TRIGGER SYS_PARAM_AREOD FOR SYSPARAM
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable vToday DATE;
declare variable vTomorow DATE;
begin
  execute procedure sp_dateonly(old.arsysdate) returning_values(vToday);
  vTomorow = vToday + 1;
  if (new.arsysdate = vTomorow) then
  begin
     update aradj set status = 'C' where opendate <= :vToday
        and status = 'O';
     /* ------------------------------------------------------------------ */
     /* STATUS CASH SBB                                                    */
     /*   O=(Prepare)   -> R=(Release)   [MANUAL] -> Masuk ke GL           */
     /*      -ditagih-       -check diterima-                              */
     /*   R=(Release)   -> L=(Reconcile) [MANUAL]                          */
     /*   L=(Reconcile) -> C=(Close/Paid)         -> Masuk ke GL           */
     /*      -check sudah cair-                                            */
     /* ------------------------------------------------------------------ */
     update arcash0 set status = 'C'
      where reconciledate <= :vToday and status = 'L';
     /* ------------------------------------------------------------------ */
     update ardepos0 set status = 'C'
      where opendate <= :vToday and status = 'O';
          
     update ardepos1 set status = 'C'
      where applieddate <= :vToday and status = 'O';
     /* ------------------------------------------------------------------ */
     /* credit card                                                        */
     /* ------------------------------------------------------------------ */     
     update ar_card_batch set status = 'C'
      where pay_date <= :vToday and status = 'R';
  end
end
^

