CREATE TRIGGER SYSBANK_BI FOR SYSBANK
ACTIVE BEFORE INSERT POSITION 0
as
declare variable ACCTYPE CHAR(1);
begin
   /* BANK ACCOUNT */
   SELECT ACCTYPE FROM GLCOA WHERE ACCOUNT = NEW.GL_ACCOUNT INTO ACCTYPE;
   if (ACCTYPE <> 'A') then EXCEPTION INV_ACCOUNT_ACTIVE;

   if (NOT EXISTS(SELECT COUNT(*) FROM GLCOACOST
          WHERE ACCOUNT = NEW.GL_ACCOUNT AND COST = NEW.GL_COST)) then
      NEW.GL_COST = '*NV*';
   if (NOT EXISTS(SELECT COUNT(*) FROM GLCOADEPT
          WHERE ACCOUNT = NEW.GL_ACCOUNT AND DEPART = NEW.GL_DEPT)) then
      NEW.GL_DEPT = '*NV*';
      
   /* AP CLEARANCE */
   SELECT ACCTYPE FROM GLCOA WHERE ACCOUNT = NEW.GL_ACCOUNT_APPREPARE INTO ACCTYPE;
   if (ACCTYPE <> 'P') then EXCEPTION INV_ACCOUNT_PASIVA;

   if (NOT EXISTS(SELECT COUNT(*) FROM GLCOACOST
          WHERE ACCOUNT = NEW.GL_ACCOUNT_APPREPARE AND COST = NEW.GL_COST_APPREPARE)) then
      NEW.GL_COST_APPREPARE = '*NV*';
   if (NOT EXISTS(SELECT COUNT(*) FROM GLCOADEPT
          WHERE ACCOUNT = NEW.GL_ACCOUNT_APPREPARE AND DEPART = NEW.GL_DEPT_APPREPARE)) then
      NEW.GL_DEPT_APPREPARE = '*NV*';

   /* AR CLEARANCE */
   SELECT ACCTYPE FROM GLCOA WHERE ACCOUNT = NEW.GL_ACCOUNT_ARPREPARE INTO ACCTYPE;
   if (ACCTYPE <> 'A') then EXCEPTION INV_ACCOUNT_ACTIVE;

   if (NOT EXISTS(SELECT COUNT(*) FROM GLCOACOST
          WHERE ACCOUNT = NEW.GL_ACCOUNT_ARPREPARE AND COST = NEW.GL_COST_APPREPARE)) then
      NEW.GL_COST_ARPREPARE = '*NV*';
   if (NOT EXISTS(SELECT COUNT(*) FROM GLCOADEPT
          WHERE ACCOUNT = NEW.GL_ACCOUNT_ARPREPARE AND DEPART = NEW.GL_DEPT_APPREPARE)) then
      NEW.GL_DEPT_ARPREPARE = '*NV*';   
END
^

