CREATE TRIGGER SYSLOGERROR_BINSERT FOR SYSLOGERROR
ACTIVE BEFORE INSERT POSITION 0
as
declare variable vCounter integer;
begin
  /* Trigger Text */
  select max(counter) from syslogerror into :vCounter;
  if (:vCounter is null) then new.counter = 1;
  else new.counter = :vCounter + 1;
  new.datetime = 'now';
end
^

CREATE TRIGGER SYSPARAM_AU_FA_ACCOUNT FOR SYSPARAM
ACTIVE AFTER UPDATE POSITION 3
AS
BEGIN
  /* ---------------------------------------------------------------- */
  /* CROSSING FIXED ASSET ACCOUNT CHANGED                             */
  /* CHANGE COST ALLOCATION ACCOUNT FOR "FA" COST CENTER              */
  /* ---------------------------------------------------------------- */
  IF ((NEW.FA_TRANS_GL_ACCOUNT <> OLD.FA_TRANS_GL_ACCOUNT) OR
      (NEW.FA_TRANS_GL_DEPT <> OLD.FA_TRANS_GL_DEPT) OR
      (NEW.FA_TRANS_GL_COST <> OLD.FA_TRANS_GL_COST)) THEN
  BEGIN
    UPDATE INVGROUPACC SET GL_ACCOUNT = NEW.FA_TRANS_GL_ACCOUNT,
           GL_DEPT = NEW.FA_TRANS_GL_DEPT,
           GL_COST = NEW.FA_TRANS_GL_COST
    WHERE ICOST = 'FA';
  END
END
^

CREATE TRIGGER SYSPARAM_AU_GLPERIOD FOR SYSPARAM
ACTIVE AFTER UPDATE POSITION 5
AS
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE C INTEGER;
BEGIN
  /* -------------------------------------------------------------------- */
  /* 16 OCT 2010                                                          */
  /* AGAR SALDO PINDAH KE BULAN BERIKUT                                   */
  /* -------------------------------------------------------------------- */
  M = OLD.GLMONTH;
  Y = OLD.GLYEAR;
  IF ((NEW.GLYEAR *12+NEW.GLMONTH >= Y *12+M)) THEN
  BEGIN
     M = M + 1;
     IF (M > 12) THEN
     BEGIN
        M = 1;
        Y = Y + 1;
     END
     SELECT COUNT(*) FROM GLACC_CHECK_OPENING(:Y, :M, 1) INTO C;
     WHEN ANY DO BEGIN END
  END
END
^

CREATE TRIGGER SYSPARAM_AU_LOG FOR SYSPARAM
ACTIVE AFTER UPDATE POSITION 4
AS
DECLARE VARIABLE TXT VARCHAR(80);

BEGIN
  IF ((NEW.GLMONTH <> OLD.GLMONTH) OR (NEW.GLYEAR <> OLD.GLYEAR)) THEN
  BEGIN
     TXT = 'GL Period: ' || OLD.GLMONTH || '-' || OLD.GLYEAR || ' to ' || NEW.GLMONTH || '-' || NEW.GLYEAR;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF (NEW.INVSYSDATE <> OLD.INVSYSDATE) THEN
  BEGIN
     TXT = 'Inventory Sysdate: ' || OLD.INVSYSDATE ||  ' to ' || NEW.INVSYSDATE;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF (NEW.INV_AP_SPLIT_TAX <> OLD.INV_AP_SPLIT_TAX) THEN
  BEGIN
     TXT = 'Split Tax: ' || OLD.INV_AP_SPLIT_TAX ||  ' to ' || NEW.INV_AP_SPLIT_TAX;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF (NEW.GL_ACCOUNT_PICTURE <> OLD.GL_ACCOUNT_PICTURE) THEN
  BEGIN
     TXT = 'A/C Picture: ' || OLD.GL_ACCOUNT_PICTURE ||  ' to ' || NEW.GL_ACCOUNT_PICTURE;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF (NEW.INSTALLAP <> OLD.INSTALLAP) THEN
  BEGIN
     TXT = 'A/P Installed: ' || OLD.INSTALLAP ||  ' to ' || NEW.INSTALLAP;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF (NEW.INSTALLAR <> OLD.INSTALLAR) THEN
  BEGIN
     TXT = 'A/R Installed: ' || OLD.INSTALLAR ||  ' to ' || NEW.INSTALLAR;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF (NEW.INSTALLGL <> OLD.INSTALLGL) THEN
  BEGIN
     TXT = 'G/L Installed: ' || OLD.INSTALLGL ||  ' to ' || OLD.INSTALLGL;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF (NEW.INSTALLFO <> OLD.INSTALLFO) THEN
  BEGIN
     TXT = 'FO Installed: ' || OLD.INSTALLFO ||  ' to ' || NEW.INSTALLFO;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  IF (NEW.INSTALLINV <> OLD.INSTALLINV) THEN
  BEGIN
     TXT = 'FO Installed: ' || OLD.INSTALLINV ||  ' to ' || NEW.INSTALLINV;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF (NEW.APSYSDATE <> OLD.APSYSDATE) THEN
  BEGIN
     TXT = 'AP Sysdate: ' || OLD.APSYSDATE ||  ' to ' || NEW.APSYSDATE;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF (NEW.INV_STOCK_ALLOW_NEGATIVE <> NEW.INV_STOCK_ALLOW_NEGATIVE) THEN
  BEGIN
     TXT = 'Inventory Allow Negative: ' || OLD.INV_STOCK_ALLOW_NEGATIVE ||  ' to ' || OLD.INV_STOCK_ALLOW_NEGATIVE;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END

  IF ((NEW.FA_TRANS_GL_ACCOUNT <> OLD.FA_TRANS_GL_ACCOUNT) OR
      (NEW.FA_TRANS_GL_DEPT <> OLD.FA_TRANS_GL_DEPT) OR
      (NEW.FA_TRANS_GL_COST <> OLD.FA_TRANS_GL_COST)) THEN
  BEGIN
     TXT = 'FA Transient: ' || OLD.FA_TRANS_GL_ACCOUNT || '.' ||
                               OLD.FA_TRANS_GL_DEPT || '.' ||
                               OLD.FA_TRANS_GL_COST || ' to ' || 
                               NEW.FA_TRANS_GL_ACCOUNT || '.' ||
                               NEW.FA_TRANS_GL_DEPT || '.' ||
                               NEW.FA_TRANS_GL_COST;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF ((NEW.BANK_GAINLOSS_GLACCOUNT <> OLD.BANK_GAINLOSS_GLACCOUNT) OR
      (NEW.BANK_GAINLOSS_GLDEPT <> OLD.BANK_GAINLOSS_GLDEPT) OR
      (NEW.BANK_GAINLOSS_GLCOST <> OLD.BANK_GAINLOSS_GLCOST)) THEN
  BEGIN
     TXT = 'BB loss/gain: ' || OLD.BANK_GAINLOSS_GLACCOUNT || '.' ||
                               OLD.BANK_GAINLOSS_GLDEPT || '.' ||
                               OLD.BANK_GAINLOSS_GLCOST || ' to ' ||
                               NEW.BANK_GAINLOSS_GLACCOUNT || '.' ||
                               NEW.BANK_GAINLOSS_GLDEPT || '.' ||
                               NEW.BANK_GAINLOSS_GLCOST;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF ((NEW.DISBURSMENT_GL_ACCOUNT <> OLD.DISBURSMENT_GL_ACCOUNT) OR
      (NEW.DISBURSMENT_GL_DEPT <> OLD.DISBURSMENT_GL_DEPT) OR
      (NEW.DISBURSMENT_GL_COST <> OLD.DISBURSMENT_GL_COST)) THEN
  BEGIN
     TXT = 'BB Disbursment: ' || OLD.DISBURSMENT_GL_ACCOUNT || '.' ||
                               OLD.DISBURSMENT_GL_DEPT || '.' ||
                               OLD.DISBURSMENT_GL_COST || ' to ' ||
                               NEW.DISBURSMENT_GL_ACCOUNT || '.' ||
                               NEW.DISBURSMENT_GL_DEPT || '.' ||
                               NEW.DISBURSMENT_GL_COST;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF ((NEW.BANK_GAINLOSS_GLACCOUNT <> OLD.BANK_GAINLOSS_GLACCOUNT) OR
      (NEW.BANK_GAINLOSS_GLDEPT <> OLD.BANK_GAINLOSS_GLDEPT) OR
      (NEW.BANK_GAINLOSS_GLCOST <> OLD.BANK_GAINLOSS_GLCOST)) THEN
  BEGIN
     TXT = 'BB loss/gain: ' || OLD.BANK_GAINLOSS_GLACCOUNT || '.' ||
                               OLD.BANK_GAINLOSS_GLDEPT || '.' ||
                               OLD.BANK_GAINLOSS_GLCOST || ' to ' ||
                               NEW.BANK_GAINLOSS_GLACCOUNT || '.' ||
                               NEW.BANK_GAINLOSS_GLDEPT || '.' ||
                               NEW.BANK_GAINLOSS_GLCOST;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  IF ((NEW.APFOREX_GAINLOSS_GLACCOUNT <> OLD.APFOREX_GAINLOSS_GLACCOUNT) OR
      (NEW.APFOREX_GAINLOSS_GLDEPT <> OLD.APFOREX_GAINLOSS_GLDEPT) OR
      (NEW.APFOREX_GAINLOSS_GLCOST <> OLD.APFOREX_GAINLOSS_GLCOST)) THEN
  BEGIN
     TXT = 'AP loss/gain: ' || OLD.APFOREX_GAINLOSS_GLACCOUNT || '.' ||
                               OLD.APFOREX_GAINLOSS_GLDEPT || '.' ||
                               OLD.APFOREX_GAINLOSS_GLCOST || ' to ' ||
                               NEW.APFOREX_GAINLOSS_GLACCOUNT || '.' ||
                               NEW.APFOREX_GAINLOSS_GLDEPT || '.' ||
                               NEW.APFOREX_GAINLOSS_GLCOST;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  




  IF ((NEW.AP_SHARE_GL_ACCOUNT <> OLD.AP_SHARE_GL_ACCOUNT) OR
      (NEW.AP_SHARE_GL_DEPT <> OLD.AP_SHARE_GL_DEPT) OR
      (NEW.AP_SHARE_GL_COST <> OLD.APFOREX_GAINLOSS_GLCOST)) THEN
  BEGIN
     TXT = 'AP Share: ' || OLD.AP_SHARE_GL_ACCOUNT || '.' ||
                               OLD.AP_SHARE_GL_DEPT || '.' ||
                               OLD.AP_SHARE_GL_COST || ' to ' ||
                               NEW.AP_SHARE_GL_ACCOUNT || '.' ||
                               NEW.AP_SHARE_GL_DEPT || '.' ||
                               NEW.AP_SHARE_GL_COST;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END

  IF ((NEW.AP_COMMISSION_GL_ACCOUNT <> OLD.AP_COMMISSION_GL_ACCOUNT) OR
      (NEW.AP_COMMISSION_GL_DEPT <> OLD.AP_COMMISSION_GL_DEPT) OR
      (NEW.AP_COMMISSION_GL_COST <> OLD.AP_COMMISSION_GL_COST)) THEN
  BEGIN
     TXT = 'AP Share: ' || OLD.AP_COMMISSION_GL_ACCOUNT || '.' ||
                           OLD.AP_COMMISSION_GL_DEPT || '.' ||
                           OLD.AP_COMMISSION_GL_COST || ' to ' ||
                           NEW.AP_COMMISSION_GL_ACCOUNT || '.' ||
                           NEW.AP_COMMISSION_GL_DEPT || '.' ||
                           NEW.AP_COMMISSION_GL_COST;
     EXECUTE PROCEDURE SYSPARAM_LOG_SAVE('$DB', 'TRIGGER', NEW.EDITUSER, TXT);
  END
  
  
  WHEN ANY DO
  BEGIN
    /* for fb 2.x 31 agustus 2011 */
  END
END
