CREATE TRIGGER SYSPARAM_LOG_BI FOR SYSPARAM_LOG
ACTIVE BEFORE INSERT POSITION 0
AS
BEGIN
  SELECT MAX(LOG_ID) FROM SYSPARAM_LOG INTO NEW.LOG_ID;
  IF (NEW.LOG_ID IS NULL) THEN NEW.LOG_ID = 0;
  NEW.LOG_ID = NEW.LOG_ID + 1;
  NEW.SYSDATE = 'NOW';
END
