CREATE TRIGGER TN_CASUAL_BI FOR TN_CASUAL
ACTIVE BEFORE INSERT POSITION 0
as
declare variable SYSDATE DATE;
begin
  SELECT CASUAL_SYSDATE FROM TN_SYSPARAM INTO SYSDATE;
  if (NEW.DATECI < SYSDATE) then exception tn_dateci_invalid;
  if (NEW.DATECI > NEW.DATECO) then exception tn_dateci_invalid;

  SELECT MAX(FOLIO) FROM tn_casual
  INTO NEW.FOLIO;
  if (NEW.FOLIO IS NULL) then NEW.FOLIO = 0;
  NEW.FOLIO = NEW.FOLIO + 1;
  
  if (NEW.FOLIOSTATUS = 'I') then NEW.LISTINDEX = 0;
  ELSE if (NEW.FOLIOSTATUS IN ('C','T')) then NEW.LISTINDEX = 1;
  ELSE NEW.LISTINDEX = 9;  
end
^

CREATE TRIGGER TN_CASUAL_BU FOR TN_CASUAL
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  if (NEW.FOLIOSTATUS <> OLD.FOLIOSTATUS) then
  BEGIN
     if (NEW.FOLIOSTATUS = 'I') then NEW.LISTINDEX = 0;
     ELSE if (NEW.FOLIOSTATUS IN ('C','T')) then NEW.LISTINDEX = 1;
     ELSE NEW.LISTINDEX = 9;
  END
end
^

CREATE TRIGGER TN_CASUAL_BU_RECALC FOR TN_CASUAL
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  if ((NEW.DB = -1) AND (NEW.CR = -1)) then
  BEGIN
     SELECT SUM(DB), SUM(CR) FROM tn_casual_journal
     WHERE FOLIO = NEW.FOLIO
     INTO NEW.DB, NEW.CR;
     if (NEW.DB IS NULL) then NEW.DB = 0;
     if (NEW.CR IS NULL) then NEW.CR = 0;
  END
end
^

CREATE TRIGGER TN_CASUAL_BU_SAVE_ROOM FOR TN_CASUAL
ACTIVE BEFORE UPDATE POSITION 3
as
declare variable ROOM VARCHAR(8);
begin
  if ((NEW.DATECI <> OLD.DATECI) or (NEW.DATECO <> OLD.DATECO)) then
  BEGIN
     /* DELETE ROOM BLOCKING */
     FOR SELECT ROOM FROM TN_CASUAL_ROOM WHERE FOLIO = NEW.FOLIO
         INTO :ROOM
     DO
     BEGIN
      if (EXISTS (SELECT * FROM TN_CASUAL_RI_ASSIGN WHERE ROOM = :ROOM AND
                  TNDATE BETWEEN NEW.DATECI AND NEW.DATECO
                   AND FOLIO <> NEW.FOLIO)) then
          EXCEPTION TN_CASUAL_BOOKED;
     END
     /* SAVE ROOM BLOCKING */
     FOR SELECT ROOM FROM TN_CASUAL_RI_ASSIGN ROOM WHERE FOLIO = NEW.FOLIO
         INTO :ROOM
     DO
     BEGIN
         EXECUTE PROCEDURE TN_CASUAL_RI_SAVE_ASSIGN(NEW.FOLIO, :ROOM, NEW.DATECI, NEW.DATECO, 1);

         /* DELETE ROOM INVENTORY */
         EXECUTE PROCEDURE TN_CASUAL_RI_SAVE(OLD.FOLIO, :ROOM, OLD.DATECI, OLD.DATECO,
                                                    OLD.FOLIOSTATUS, -1);
         /* SAVE ROOM INVENTORY */
         EXECUTE PROCEDURE TN_CASUAL_RI_SAVE(NEW.FOLIO, :ROOM, NEW.DATECI, NEW.DATECO,
                                                    NEW.FOLIOSTATUS, 1);
     END
  END
  ELSE
  if (NEW.FOLIOSTATUS <> OLD.FOLIOSTATUS) then
  BEGIN
     FOR SELECT ROOM FROM TN_CASUAL_RI_ASSIGN ROOM WHERE FOLIO = NEW.FOLIO
         INTO :ROOM
     DO
     BEGIN
         EXECUTE PROCEDURE tn_casual_ri_save_assign(NEW.FOLIO, :ROOM, NEW.DATECI, NEW.DATECO, 1);

         /* DELETE ROOM INVENTORY */
         EXECUTE PROCEDURE TN_CASUAL_RI_SAVE(OLD.FOLIO, :ROOM, OLD.DATECI, OLD.DATECO,
                                                    OLD.FOLIOSTATUS, -1);
         /* SAVE ROOM INVENTORY */
         EXECUTE PROCEDURE TN_CASUAL_RI_SAVE(NEW.FOLIO, :ROOM, NEW.DATECI, NEW.DATECO,
                                                    NEW.FOLIOSTATUS, 1);
     END  
  END
end
^

CREATE TRIGGER TN_CASUAL_BU_STATUS FOR TN_CASUAL
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable SYSDATE DATE;
begin
  SELECT CASUAL_SYSDATE FROM TN_SYSPARAM INTO SYSDATE;

  if (NEW.DATECI > NEW.DATECO) then exception tn_dateci_invalid;
  if ((NEW.FOLIOSTATUS IN ('T','C')) AND (NEW.DATECI < SYSDATE)) then exception tn_dateci_invalid;
     
  if (NEW.FOLIOSTATUS <> OLD.FOLIOSTATUS) then
  BEGIN
     if ((NEW.FOLIOSTATUS = 'I') AND (OLD.FOLIOSTATUS NOT IN ('C','T'))) then
        EXCEPTION TN_CASAUL_INVALID_STATUS;

     if ((NEW.FOLIOSTATUS = 'X') AND (OLD.FOLIOSTATUS NOT IN ('C','T'))) then
        EXCEPTION TN_CASAUL_INVALID_STATUS;

     if ((NEW.FOLIOSTATUS = 'O') AND (OLD.FOLIOSTATUS <> 'I')) then
        EXCEPTION TN_CASAUL_INVALID_STATUS;

     if ((NEW.FOLIOSTATUS = 'C') AND (OLD.FOLIOSTATUS <> 'T')) then
        EXCEPTION TN_CASAUL_INVALID_STATUS;

     if ((NEW.FOLIOSTATUS = 'T') AND (OLD.FOLIOSTATUS <> 'C')) then
        EXCEPTION TN_CASAUL_INVALID_STATUS;


     if (NEW.FOLIOSTATUS = 'I') then
     BEGIN
        if (NEW.DATECI <> SYSDATE) then exception tn_dateci_invalid;
        NEW.LISTINDEX = 0;
     END
     ELSE if (NEW.FOLIOSTATUS IN ('C','T')) then NEW.LISTINDEX = 1;
     ELSE
     if (NEW.FOLIOSTATUS = 'O') then
     BEGIN
        NEW.DATECO = SYSDATE;
        NEW.LISTINDEX = 9;
     END
     ELSE NEW.LISTINDEX = 9;
  END
end
^

CREATE TRIGGER TN_CASUAL_BU_VALIDATE FOR TN_CASUAL
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  if ((NEW.FOLIOSTATUS = 'I') AND (NEW.DATECI <> OLD.DATECI)) THEN
     exception tn_casual_checkin;

  if (OLD.FOLIOSTATUS = 'O') then
     exception tn_casual_checkout;

  if (OLD.FOLIOSTATUS = 'X') then
     exception tn_casual_cancel;

  if ((NEW.FOLIOSTATUS = 'O') AND (NEW.FOLIOSTATUS <> 'O')) then
     exception TN_CASUAL_BILLING_NOT_BALANCE;
     
  if ((NEW.FOLIOSTATUS = 'X') AND (NEW.FOLIOSTATUS <> 'X')) then
     exception TN_CASUAL_BILLING_NOT_BALANCE;     

end
^

CREATE TRIGGER TN_CASUAL_DSR_AU FOR TN_CASUAL_DSR
ACTIVE AFTER UPDATE POSITION 0
as
declare variable NUMBER INTEGER;
declare variable LINE INTEGER;
declare variable GL_ACCOUNT VARCHAR(20);
declare variable GL_DEPT VARCHAR(4);
declare variable GL_COST VARCHAR(4);
begin
  if ((NEW.POSTED = 'P') AND (OLD.POSTED <> 'P') AND (NEW.DB + NEW.CR <> 0)) then
  BEGIN
     NUMBER = NEW.TNDATE - '1.1.2000';
     SELECT LISTINDEX FROM TN_CATEGORY WHERE CODE = NEW.CATEGORY INTO :LINE;
     LINE = LINE*10;
     
     /* DEBIT */
     SELECT CASUAL_DB_ACCOUNT, CASUAL_DB_DEPT, CASUAL_DB_COST
     FROM TN_CATEGORY WHERE CODE = NEW.CATEGORY
     INTO GL_ACCOUNT, GL_DEPT, GL_COST;
     
     insert into glbuffer
     (APPLICATION, SOURCE, NUMBER, ID, transdate,
     ACCOUNT, DEPT, COST, PROJECT,
     NOTE, REF,
     DB, CR,
     EXPORTDATE, EXPORTUSER)
     values ('TENT','DSR', :NUMBER, :LINE, old.TNDATE,
     :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
     NEW.REMARK, '',
     NEW.DB+NEW.CR, 0,
     NEW.POSTED_DATE,
     NEW.POSTED_USER);
     
     /* CREDIT */
     SELECT CASUAL_CR_ACCOUNT, CASUAL_CR_DEPT, CASUAL_CR_COST
     FROM TN_CATEGORY WHERE CODE = NEW.CATEGORY
     INTO GL_ACCOUNT, GL_DEPT, GL_COST;
     
     insert into glbuffer
     (APPLICATION, SOURCE, NUMBER, ID, transdate,
     ACCOUNT, DEPT, COST, PROJECT,
     NOTE, REF,
     DB, CR,
     EXPORTDATE, EXPORTUSER)
     values ('TENT','DSR', :NUMBER, :LINE+1, old.TNDATE,
     :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
     NEW.REMARK, '',
     0, NEW.DB+NEW.CR,
     NEW.POSTED_DATE,
     NEW.POSTED_USER);     
  END
end
^

