CREATE TRIGGER TN_CASUAL_JOURNAL_BI FOR TN_CASUAL_JOURNAL
ACTIVE BEFORE INSERT POSITION 0
AS
BEGIN
  NEW.TRANS_ID = GEN_ID(GEN_TN_CASUAL_JUR_TRANS_ID,1);
  if (NEW.CORRECTION_TRANS_ID IS NULL) THEN NEW.CORRECTION_TRANS_ID = 0;
  
  if (NEW.CORRECTION_TRANS_ID <> 0) then
  BEGIN
     UPDATE TN_CASUAL_JOURNAL SET CORRECTION_TRANS_ID = NEW.TRANS_ID
     WHERE TRANS_ID = NEW.CORRECTION_TRANS_ID;
     
     NEW.JURCODE = 'COR';
     NEW.CREATEDATE = 'NOW';
     SELECT TNDATE, FOLIO, CATEGORY, REMARK, REF, DB, CR
     FROM TN_CASUAL_JOURNAL
     WHERE TRANS_ID = NEW.CORRECTION_TRANS_ID
     INTO NEW.TNDATE, NEW.FOLIO, NEW.CATEGORY, NEW.REMARK, NEW.REF, NEW.CR, NEW.DB;
  END
END
