CREATE TRIGGER TN_CASUAL_JOURNAL_BU FOR TN_CASUAL_JOURNAL
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  UPDATE TN_CASUAL SET DB = DB - OLD.DB, CR = CR - OLD.CR
  WHERE FOLIO = NEW.FOLIO;
  
  UPDATE TN_CASUAL SET DB = DB + NEW.DB, CR = CR + NEW.CR
  WHERE FOLIO = NEW.FOLIO;
end
^

CREATE TRIGGER TN_CASUAL_RI_ASSIGN_AI FOR TN_CASUAL_RI_ASSIGN
ACTIVE AFTER INSERT POSITION 0
as
declare variable OROOM VARCHAR(8);
declare variable FLAG INTEGER;
begin
  /* OVERLAPPED DITUTUP */
  if (NEW.OVERLAPPED = 0) then
  BEGIN
     FOR SELECT OROOM, FLAG FROM TN_CASUAL_RI_SAVE_ASSIGN_OL(NEW.ROOM)
         GROUP BY OROOM, FLAG
         INTO OROOM, FLAG
     DO
     BEGIN
       if (NOT EXISTS (SELECT * FROM TN_CASUAL_RI_ASSIGN
          WHERE ROOM = :OROOM AND TNDATE = NEW.TNDATE AND FOLIO = NEW.FOLIO)) then
       BEGIN
           INSERT INTO TN_CASUAL_RI_ASSIGN (ROOM, TNDATE, FOLIO, OVERLAPPED, ASSIGN_ID)
           VALUES (:OROOM, NEW.TNDATE,NEW.FOLIO, :FLAG, NEW.ASSIGN_ID);
       END
     END
  END
end
^

CREATE TRIGGER TN_CASUAL_RI_ASSIGN_BD FOR TN_CASUAL_RI_ASSIGN
ACTIVE BEFORE DELETE POSITION 0
as
declare variable OROOM VARCHAR(8);
begin
  /* DELETE OVERLAPPED  */
  if (OLD.OVERLAPPED = 0) then
  BEGIN
     FOR SELECT OROOM FROM TN_CASUAL_RI_SAVE_ASSIGN_OL(OLD.ROOM)
         GROUP BY OROOM
         INTO OROOM
     DO
     BEGIN
       DELETE FROM TN_CASUAL_RI_ASSIGN
       WHERE ROOM = :OROOM AND TNDATE = OLD.TNDATE AND FOLIO = OLD.FOLIO;
     END
  END
end
^

