as
begin
  if (EXISTS(SELECT * FROM tn_casual_ri_assign WHERE (ROOM = NEW.ROOM) AND
     (TNDATE = NEW.TNDATE) AND (OVERLAPPED = 0) AND (FOLIO <> NEW.FOLIO))) then
     EXCEPTION TN_CASUAL_BOOKED;
     
  if (NEW.OVERLAPPED = 0) then
     NEW.ASSIGN_ID = GEN_ID(GEN_ROOM_ASSIGN_ID,1);
end
