CREATE TRIGGER TN_CASUAL_RI_BI FOR TN_CASUAL_RI
ACTIVE BEFORE INSERT POSITION 0
as
begin
  SELECT TOTAL_COUNT, TOTAL_M2 FROM TN_CASUAL_ROOMNO_TYPE
  WHERE ROOMTYPE = NEW.ROOMTYPE
  INTO NEW.COUNT_TOTAL, NEW.M2_TOTAL;
  
  NEW.M2_TOTAL = 0;
  NEW.M2_CONFIRM = 0;
  NEW.M2_TENTATIVE = 0;
  NEW.M2_INHOUSE = 0;
  NEW.COUNT_CONFIRM = 0;
  NEW.COUNT_TENTATIVE = 0;
  NEW.COUNT_INHOUSE = 0;
  NEW.REVENUE_TOTAL = 0;
  NEW.REVENUE_INHOUSE = 0;
  NEW.REVENUE_CONFIRM = 0;
  NEW.REVENUE_TENTATIVE = 0;

end
^

CREATE TRIGGER TN_CASUAL_RI_BU FOR TN_CASUAL_RI
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  NEW.M2_AVAILABLE = NEW.M2_TOTAL - NEW.M2_CONFIRM - NEW.M2_TENTATIVE - NEW.M2_INHOUSE;
  NEW.COUNT_AVAILABLE = NEW.COUNT_TOTAL - NEW.COUNT_CONFIRM - NEW.COUNT_TENTATIVE - NEW.COUNT_INHOUSE;
  NEW.REVENUE_TOTAL = NEW.REVENUE_CONFIRM + NEW.REVENUE_TENTATIVE + NEW.REVENUE_INHOUSE;
end
^

CREATE TRIGGER TN_CASUAL_ROOM_BD FOR TN_CASUAL_ROOM
ACTIVE BEFORE DELETE POSITION 0
as
declare variable FOLIOSTATUS CHAR(1);
begin
   EXECUTE PROCEDURE TN_CASUAL_RI_SAVE_ASSIGN(OLD.FOLIO, OLD.ROOM, OLD.DATECI, OLD.DATECO, -1);
     
   SELECT FOLIOSTATUS FROM TN_CASUAL WHERE FOLIO = OLD.FOLIO INTO FOLIOSTATUS;
   EXECUTE PROCEDURE TN_CASUAL_RI_SAVE(OLD.FOLIO, OLD.ROOM, OLD.DATECI, OLD.DATECO,
                                               FOLIOSTATUS, -1);
end
^

CREATE TRIGGER TN_CASUAL_ROOM_BI FOR TN_CASUAL_ROOM
ACTIVE BEFORE INSERT POSITION 0
as
declare variable FOLIOSTATUS CHAR(1);
begin
  SELECT DATECI, DATECO, FOLIOSTATUS FROM TN_CASUAL WHERE FOLIO = NEW.FOLIO
  INTO NEW.DATECI,NEW.DATECO, FOLIOSTATUS;
  
  EXECUTE PROCEDURE TN_CASUAL_RI_SAVE_ASSIGN(NEW.FOLIO, NEW.ROOM, NEW.DATECI, NEW.DATECO, 1);
  
  EXECUTE PROCEDURE TN_CASUAL_RI_SAVE(NEW.FOLIO, NEW.ROOM, NEW.DATECI, NEW.DATECO, :FOLIOSTATUS, 1);


end
^

CREATE TRIGGER TN_CASUAL_ROOM_BU FOR TN_CASUAL_ROOM
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable FOLIOSTATUS CHAR(1);
begin
   NEW.ROOM = NEW.ROOM;
   SELECT DATECI, DATECO, FOLIOSTATUS FROM TN_CASUAL WHERE FOLIO = NEW.FOLIO
   INTO NEW.DATECI,NEW.DATECO, FOLIOSTATUS;
  
  /* DELETE OLD ASSIGN */
   EXECUTE PROCEDURE TN_CASUAL_RI_SAVE_ASSIGN(OLD.FOLIO, OLD.ROOM, OLD.DATECI, OLD.DATECO, -1);
     
   EXECUTE PROCEDURE TN_CASUAL_RI_SAVE(OLD.FOLIO, OLD.ROOM, OLD.DATECI, OLD.DATECO,
                                               FOLIOSTATUS, -1);
   /* CREATE NEW ASSIGN */
  
   EXECUTE PROCEDURE TN_CASUAL_RI_SAVE_ASSIGN(NEW.FOLIO, NEW.ROOM, NEW.DATECI, NEW.DATECO, 1);
  
   EXECUTE PROCEDURE TN_CASUAL_RI_SAVE(NEW.FOLIO, NEW.ROOM, NEW.DATECI, NEW.DATECO, :FOLIOSTATUS, 1);

end
^

CREATE TRIGGER TN_CASUAL_ROOMNO_AI FOR TN_CASUAL_ROOMNO
ACTIVE AFTER INSERT POSITION 0
as
begin
  UPDATE TN_CASUAL_ROOMNO_TYPE
         SET TOTAL_COUNT = TOTAL_COUNT + 1,
         TOTAL_M2 = TOTAL_M2 + NEW.M2
  WHERE ROOMTYPE = NEW.ROOMTYPE;
end
^

CREATE TRIGGER TN_CASUAL_ROOMNO_AU FOR TN_CASUAL_ROOMNO
ACTIVE AFTER UPDATE POSITION 0
as
begin

  UPDATE TN_CASUAL_ROOMNO_TYPE
         SET TOTAL_COUNT = TOTAL_COUNT - 1,
         TOTAL_M2 = TOTAL_M2 - OLD.M2
  WHERE ROOMTYPE = OLD.ROOMTYPE;
  
  UPDATE TN_CASUAL_ROOMNO_TYPE
         SET TOTAL_COUNT = TOTAL_COUNT + 1,
         TOTAL_M2 = TOTAL_M2 + NEW.M2
  WHERE ROOMTYPE = NEW.ROOMTYPE;
end
^

CREATE TRIGGER TN_CASUAL_ROOMNO_BD FOR TN_CASUAL_ROOMNO
ACTIVE AFTER DELETE POSITION 0
as
begin
  UPDATE TN_CASUAL_ROOMNO_TYPE
         SET TOTAL_COUNT = TOTAL_COUNT - 1,
         TOTAL_M2 = TOTAL_M2 - OLD.M2
  WHERE ROOMTYPE = OLD.ROOMTYPE;
end
^

CREATE TRIGGER TN_CASUAL_ROOMNO_BU FOR TN_CASUAL_ROOMNO
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  if (NEW.OVERLAPPED_COUNTER < 0) then
  BEGIN
     SELECT COUNT(*) FROM tn_casual_roomno_overlapped
     WHERE ROOM = NEW.ROOM
     INTO NEW.OVERLAPPED_COUNTER;
     
     if (NEW.OVERLAPPED_COUNTER IS NULL) then
        NEW.OVERLAPPED_COUNTER = 0;
     
     if (NEW.OVERLAPPED_COUNTER > 0) then
     BEGIN
       SELECT SUM(R.M2) FROM tn_casual_roomno_overlapped O
       INNER JOIN tn_casual_roomno R ON R.ROOM = O.OVERLAPPED
       WHERE O.ROOM = NEW.ROOM
       INTO NEW.M2;
       
       if (NEW.M2 IS NULL) then NEW.M2 = 0;
     END
  END
end
^

CREATE TRIGGER TN_CASUAL_ROOMNO_OVERLAPPED_BD FOR TN_CASUAL_ROOMNO_OVERLAPPED
ACTIVE BEFORE DELETE POSITION 0
as
declare variable M2 DOUBLE PRECISION;
begin
  SELECT T.TOTAL_M2 FROM tn_casual_roomno R
  INNER JOIN tn_casual_roomno_type T ON R.ROOMTYPE = T.ROOMTYPE
  WHERE R.ROOM = OLD.ROOM
  INTO M2;
  
  UPDATE tn_casual_roomno SET OVERLAPPED_COUNTER = OVERLAPPED_COUNTER - 1,
         M2 = M2 - :M2
  WHERE ROOM = OLD.ROOM;
end
^

CREATE TRIGGER TN_CASUAL_ROOMNO_OVERLAPPED_BI FOR TN_CASUAL_ROOMNO_OVERLAPPED
ACTIVE BEFORE INSERT POSITION 0
as
declare variable FLAG_OVERLLAPED INTEGER;
declare variable M2 DOUBLE PRECISION;
begin
  if (EXISTS(SELECT * FROM tn_casual_roomno_overlapped WHERE ROOM = NEW.OVERLAPPED)) then
     exception TN_OVERLAPPED_INVALID;
  
  /* KALAU BUKAN OVERLAPPED ROOM MAKA TIDAK BOLEH */
  SELECT T.FLAG_OVERLAPPED, T.TOTAL_M2 FROM tn_casual_roomno R
  INNER JOIN tn_casual_roomno_type T ON R.ROOMTYPE = T.ROOMTYPE
  WHERE R.ROOM = NEW.ROOM
  INTO FLAG_OVERLLAPED, M2;
  
  if (FLAG_OVERLLAPED <> 1) then exception TN_FLAG_OVERLAPPED;
  
  UPDATE tn_casual_roomno SET OVERLAPPED_COUNTER = OVERLAPPED_COUNTER + 1,
         M2 = M2 + :M2
  WHERE ROOM = NEW.ROOM;
end
^

CREATE TRIGGER TN_CASUAL_ROOMNO_TYPE_BU FOR TN_CASUAL_ROOMNO_TYPE
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  /* RECALCULATE  */
  if (NEW.TOTAL_COUNT < 0) then
  BEGIN
    SELECT COUNT(*), SUM(M2) FROM TN_CASUAL_ROOMNO
    WHERE ROOMTYPE = NEW.ROOMTYPE
    INTO NEW.TOTAL_COUNT, NEW.TOTAL_M2;
  
    if (NEW.TOTAL_COUNT IS NULL) then NEW.TOTAL_COUNT = 0;
     
    if (NEW.TOTAL_M2 IS NULL) then NEW.TOTAL_M2 = 0;
  END
end
^

