CREATE TRIGGER TN_FIXED_CHARGE_BD FOR TN_FIXED_CHARGE
ACTIVE BEFORE DELETE POSITION 0
as
declare variable ROOM VARCHAR(8);
declare variable PYEAR INTEGER;
declare variable PMONTH INTEGER;
begin
  FOR SELECT PYEAR, PMONTH, ROOM FROM tn_tenant_jur
  WHERE STATUS = 'O' 
  INTO PYEAR, PMONTH, ROOM
  DO
  BEGIN
    delete from tn_tenant_jur_detail
    where PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND ROOM = :ROOM
    AND CATEGORY = OLD.CATEGORY;
  END
end
