CREATE TRIGGER TN_LEASE_ACTION_BI FOR TN_LEASE_ACTION
ACTIVE BEFORE INSERT POSITION 0
AS
BEGIN
  NEW.ACTION_ID = GEN_ID(GEN_TN_LEASE_ACTION_ID,1);
  if (NEW.ACTION_TYPE = 'MOVE') then
     SELECT ROOM FROM TN_LEASE 
     WHERE NUMBER = NEW.NUMBER INTO NEW.O_DATA;
  ELSE
  if (NEW.ACTION_TYPE = 'CNX') then
     SELECT STATUS FROM TN_LEASE
     WHERE NUMBER = NEW.NUMBER INTO NEW.O_DATA;  
  ELSE
  if (NEW.ACTION_TYPE = 'CUST') then
     SELECT CUSTOMER FROM TN_LEASE
     WHERE NUMBER = NEW.NUMBER INTO NEW.O_DATA;       
END
^

CREATE TRIGGER TN_LEASE_ACTION_BU FOR TN_LEASE_ACTION
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  if (OLD.STATUS <> 'O') then
     exception all_doc_status_not_open;

  if (NEW.ACTION_TYPE = 'MOVE') then
     SELECT ROOM FROM TN_LEASE 
     WHERE NUMBER = NEW.NUMBER INTO NEW.O_DATA;
  ELSE
  if (NEW.ACTION_TYPE = 'CNX') then
     SELECT STATUS FROM TN_LEASE
     WHERE NUMBER = NEW.NUMBER INTO NEW.O_DATA;  
  ELSE
  if (NEW.ACTION_TYPE = 'CUST') then
     SELECT CUSTOMER FROM TN_LEASE
     WHERE NUMBER = NEW.NUMBER INTO NEW.O_DATA;      

  if ((NEW.STATUS = 'R') AND (OLD.STATUS = 'O')) then
  BEGIN
     if (NEW.ACTION_TYPE = 'MOVE') then
     BEGIN
        UPDATE TN_LEASE SET ROOM = NEW.N_DATA, EDITDATE = NEW.EDITDATE, EDITUSER = NEW.EDITUSER
        WHERE NUMBER = NEW.NUMBER;
     END
     ELSE
     if (NEW.ACTION_TYPE = 'CNX') then
     BEGIN
        UPDATE TN_LEASE SET STATUS = 'X', EDITDATE = NEW.EDITDATE, EDITUSER = NEW.EDITUSER
        WHERE NUMBER = NEW.NUMBER;
     END     
     ELSE
     if (NEW.ACTION_TYPE = 'CUST') then
     BEGIN
        UPDATE TN_LEASE SET CUSTOMER = NEW.N_DATA, EDITDATE = NEW.EDITDATE, EDITUSER = NEW.EDITUSER
        WHERE NUMBER = NEW.NUMBER;
     END          
  END
end
^

