CREATE TRIGGER TN_LEASE_BI FOR TN_LEASE
ACTIVE BEFORE INSERT POSITION 0
as
begin
   select Max(number) from TN_LEASE into new.number;
   if (new.number is null) then new.number = 1;
   else
   new.number = new.number+1;
   NEW.TOTAL_EXPORT  = 0;
   NEW.TOTAL_CHARGE  = 0;
   NEW.TOTAL_TAX     = 0;
end
^

CREATE TRIGGER TN_LEASE_BU FOR TN_LEASE
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable AR_NUMBER INTEGER;
begin
   if (new.status = 'X') then
      exception  all_doc_status_not_open;
      
   if (NEW.CUSTOMER <> OLD.CUSTOMER) then
   BEGIN
      UPDATE TN_LEASE_JUR SET CUSTOMER = NEW.CUSTOMER
      WHERE NUMBER = OLD.NUMBER
      AND STATUS = 'O';
      
      FOR SELECT AR_NUMBER FROM TN_LEASE_JUR
      WHERE NUMBER = OLD.NUMBER
      INTO AR_NUMBER
      DO
      BEGIN
         UPDATE ARVCH SET CUSTOMER = NEW.CUSTOMER
         WHERE NUMBER = :AR_NUMBER
         AND PAIDSTATUS = 'O';
      END
   END
end
^

CREATE TRIGGER TN_LEASE_JUR_BD FOR TN_LEASE_JUR
ACTIVE BEFORE DELETE POSITION 0
as
begin
      UPDATE TN_LEASE SET TOTAL_CHARGE = TOTAL_CHARGE - OLD.AMOUNT,
             TOTAL_TAX = TOTAL_TAX - OLD.TAX
       WHERE NUMBER = OLD.NUMBER;
end
^

CREATE TRIGGER TN_LEASE_JUR_BI FOR TN_LEASE_JUR
ACTIVE BEFORE INSERT POSITION 0
as
begin
   select Max(TRANS_ID) from tn_lease_jur into new.TRANS_ID;
   if (new.TRANS_ID is null) then new.TRANS_ID = 1;
   else
   new.TRANS_ID = new.TRANS_ID+1;


   SELECT CUSTOMER FROM TN_LEASE WHERE NUMBER = NEW.NUMBER
   INTO NEW.CUSTOMER;

   UPDATE TN_LEASE SET TOTAL_CHARGE = TOTAL_CHARGE + NEW.AMOUNT,
          TOTAL_TAX = TOTAL_TAX + NEW.TAX
   WHERE NUMBER = NEW.NUMBER;
   
   execute procedure sp_year(NEW.OPENDATE) returning_values(NEW.PYEAR);
   execute procedure sp_month(NEW.OPENDATE) returning_values(NEW.PMONTH);
end
^

CREATE TRIGGER TN_LEASE_JUR_BU FOR TN_LEASE_JUR
ACTIVE BEFORE UPDATE POSITION 0
as
begin
   SELECT CUSTOMER FROM TN_LEASE WHERE NUMBER = NEW.NUMBER
   INTO NEW.CUSTOMER;

   if (NEW.STATUS IN ('O', 'X')) then
      UPDATE TN_LEASE SET TOTAL_CHARGE = TOTAL_CHARGE - OLD.AMOUNT,
             TOTAL_TAX = TOTAL_TAX - OLD.TAX
       WHERE NUMBER = OLD.NUMBER;
      
   if (NEW.STATUS = 'O') then
       UPDATE TN_LEASE SET TOTAL_CHARGE = TOTAL_CHARGE + NEW.AMOUNT,
          TOTAL_TAX = TOTAL_TAX + NEW.TAX
       WHERE NUMBER = NEW.NUMBER;

   if (NEW.OPENDATE <> OLD.OPENDATE) then
   BEGIN
      execute procedure sp_year(NEW.OPENDATE) returning_values(NEW.PYEAR);
      execute procedure sp_month(NEW.OPENDATE) returning_values(NEW.PMONTH);
   END
   
   if (((OLD.AMOUNT <> NEW.AMOUNT) OR
        (OLD.JUR_TYPE <> NEW.JUR_TYPE) OR
        (OLD.OPENDATE <> NEW.OPENDATE) or
        (OLD.DUEDATE <> NEW.DUEDATE)) AND (NEW.STATUS <> 'O')) then
   BEGIN
      EXCEPTION ALL_DOC_STATUS_NOT_OPEN;
   END
end
^

CREATE TRIGGER TN_LEASE_JUR_RELEASE FOR TN_LEASE_JUR
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable GL_ACCOUNT VARCHAR(20);
declare variable GL_DEPT VARCHAR(4);
declare variable GL_COST VARCHAR(4);
declare variable AR_ACCOUNT VARCHAR(20);
declare variable AR_DEPT    VARCHAR(4);
declare variable AR_COST    VARCHAR(4);
declare variable REMARK VARCHAR(40);
begin
  if ((NEW.STATUS = 'R') AND (OLD.STATUS = 'O')) then
  BEGIN
     UPDATE TN_LEASE SET TOTAL_EXPORT = TOTAL_EXPORT + NEW.AMOUNT + NEW.TAX
     WHERE NUMBER = NEW.NUMBER;

     SELECT MAX(NUMBER) FROM ARVCH INTO NEW.AR_NUMBER;
     if (NEW.AR_NUMBER IS NULL) then NEW.AR_NUMBER = 0;
     NEW.AR_NUMBER = NEW.AR_NUMBER + 1;
     
     INSERT INTO arvch
     (CUSTOMER,
     DOCUMENT,
     OPENDATE, DUEDATE,
     STATUS, SOURCE, SOURCEID,
     CURRENCY, EXCHANGE,
     TOTAL, FOREX_TOTAL)
     VALUES
     (NEW.CUSTOMER,
     NEW.NUMBER || '/'||NEW.LINE,
     NEW.OPENDATE, NEW.DUEDATE,
     'O', 'LEAS', NEW.TRANS_ID,
     'IDR', 1,
     NEW.AMOUNT + NEW.TAX, NEW.AMOUNT + NEW.TAX);
     /* --------------------------------------------------------------------- */
     /* DETAIL TO GL BUFFER                                                   */
     /* --------------------------------------------------------------------- */
     SELECT T.GLACCOUNT, T.GLDEPT
     FROM syscustomertype T
     WHERE T.CUSTOMERTYPE = '0000'
     INTO AR_ACCOUNT, AR_DEPT;

     SELECT NAME FROM SYSCUSTOMER
     WHERE CUSTOMER = NEW.CUSTOMER
     INTO :REMARK;
     /* AR ACCOUNT */
     insert into glbuffer
          (APPLICATION, SOURCE, NUMBER, ID, transdate,
           ACCOUNT, DEPT, COST, PROJECT,
           NOTE, REF,
           DB, CR,
           EXPORTDATE, EXPORTUSER)
     values ('AR', 'LEAS', old.trans_id, 1, NEW.OPENDATE,
            :AR_ACCOUNT, :AR_DEPT, '0000', '0000',
            :REMARK, NEW.CUSTOMER,
            NEW.AMOUNT + NEW.TAX, 0,
            'now', NEW.EDITUSER);
     /* REVENUE */
     SELECT C.GL_ACCOUNT, C.GL_DEPT, C.GL_COST
     FROM TN_CATEGORY C
     WHERE C.CODE = NEW.JUR_TYPE
     INTO :GL_ACCOUNT, :GL_DEPT, :GL_COST;

     insert into glbuffer
           (APPLICATION, SOURCE, NUMBER, ID, transdate,
            ACCOUNT, DEPT, COST, PROJECT,
            NOTE, REF,
            DB, CR,
            EXPORTDATE, EXPORTUSER)
     values ('AR', 'LEAS', old.trans_id, 2, NEW.OPENDATE,
            :GL_ACCOUNT, :GL_DEPT, :GL_COST, '0000',
            :REMARK, NEW.CUSTOMER,
            0, NEW.AMOUNT,
            'now', NEW.EDITUSER);

     if (NEW.TAX <> 0) then
     BEGIN
        SELECT INV_AR_TAX_ACCOUNT FROM SYSPARAM INTO GL_ACCOUNT;
        insert into glbuffer
              (APPLICATION, SOURCE, NUMBER, ID, transdate,
               ACCOUNT, DEPT, COST, PROJECT,
               NOTE, REF, DB, CR,
               EXPORTDATE, EXPORTUSER)
        values ('AR', 'LEAS', old.trans_id, 3, NEW.OPENDATE,
               :GL_ACCOUNT, '0000', '0000', '0000',
               :REMARK, NEW.CUSTOMER, 0, NEW.TAX,
               'now', NEW.EDITUSER);
     END
  END
end
^

