CREATE TRIGGER TN_ROOM_BINS1 FOR TN_ROOM
ACTIVE BEFORE INSERT POSITION 0
AS
BEGIN
  /* -------------------------------- */
  /* CREATED AT 18-Apr-2004 13:13:38  */
  /* -------------------------------- */
  /* PUT YOUR TRIGGER HERE            */
  /* -------------------------------- */
  NEW.EDITDATE = 'NOW';
  NEW.CREATEDATE = 'NOW';
  if (NOT EXISTS(SELECT * FROM syscustomer WHERE CUSTOMER = NEW.ROOM)) THEN
  INSERT INTO SYSCUSTOMER (
    CUSTOMER,
    NAME,
    PHONE,
    FAX,
    CREATEUSER,
    CREATEDATE,
    EDITDATE,
    EDITUSER,
    FLAG_ACTIVE,
    PHONE_MOBILE)
  VALUES (
    NEW.ROOM,
    NEW.OWNER_NAME,
    NEW.OWNER_PHONE,
    NEW.OWNER_FAX,
    NEW.CREATEUSER,
    NEW.CREATEDATE,
    NEW.EDITDATE,
    NEW.EDITUSER,
    1,
    NEW.OWNER_MOBILE);
    
  if (NEW.MERGE_ROOM IS NULL) then NEW.MERGE_ROOM = '';
  
  if (NEW.MERGE_ROOM <> '') then
  BEGIN
     if (NEW.ROOM = NEW.MERGE_ROOM) then EXCEPTION TN_MERGE_ROOM_SAME;
     
     if (NOT EXISTS(SELECT * FROM TN_ROOM WHERE ROOM = NEW.MERGE_ROOM)) then
        exception TN_MERGE_ROOM_NOT_EXIST;
     NEW.FLAG_BILLING = 0;
  END
     
  SELECT MAX(FOLIO) FROM TN_ROOM INTO NEW.FOLIO;
  if (NEW.FOLIO IS NULL) then NEW.FOLIO = 0;
  NEW.FOLIO = NEW.FOLIO + 1;
  
  /* 23 APRIL 2005 */
  if (NEW.PERSON_ADULT IS NULL) then NEW.PERSON_ADULT = 0;
  if (NEW.PERSON_CHILD IS NULL) then NEW.PERSON_CHILD = 0;
  /* 23 APRIL 2005 */  
END
^

CREATE TRIGGER TN_ROOM_BU_CUSTOMER FOR TN_ROOM
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable X INTEGER;
begin
  if (NEW.OWNER_NAME = '?*?') then
  BEGIN
     NEW.OWNER_NAME = OLD.OWNER_NAME;
     SELECT COUNT(*) FROM SYSCUSTOMER
     WHERE CUSTOMER = NEW.ROOM
     INTO X;
     if (X = 0) then
     BEGIN
       INSERT INTO SYSCUSTOMER
       (CUSTOMER, NAME, CUSTAREA, CUSTTYPE, PHONE, FAX, PHONE_MOBILE)
       VALUES
       (NEW.ROOM, NEW.OWNER_NAME, '0000','0000', NEW.OWNER_PHONE, NEW.OWNER_FAX, NEW.OWNER_MOBILE);
     END
  END
end
^

CREATE TRIGGER TN_ROOM_BUPD1 FOR TN_ROOM
ACTIVE BEFORE UPDATE POSITION 0
AS
BEGIN
  if (NEW.MERGE_ROOM IS NULL) then NEW.MERGE_ROOM = '';
  
  if (NEW.MERGE_ROOM <> '') then
  BEGIN
     if (NEW.ROOM = NEW.MERGE_ROOM) then EXCEPTION TN_MERGE_ROOM_SAME;
     
     if (NOT EXISTS(SELECT * FROM TN_ROOM WHERE ROOM = NEW.MERGE_ROOM)) then
        exception TN_MERGE_ROOM_NOT_EXIST;
     NEW.FLAG_BILLING = 0;
  END
     
  if ((NEW.FOLIO = 0) or (NEW.FOLIO IS NULL)) then
  BEGIN
     SELECT MAX(FOLIO) FROM TN_ROOM INTO NEW.FOLIO;
     if (NEW.FOLIO IS NULL) then NEW.FOLIO = 0;
     NEW.FOLIO = NEW.FOLIO + 1;
  END
  
  NEW.EDITDATE = 'NOW';
  if (NEW.CUSTOMER IS NULL) then
     NEW.CUSTOMER = NEW.ROOM;
     
  if (NEW.OWNER_NAME = '?') then
  BEGIN
    NEW.OWNER_NAME = OLD.OWNER_NAME;
    INSERT INTO TN_ROOM_LOG_OWNER (
      ROOM,
      OWNER_NAME,
      OWNER_ADDRESS,
      OWNER_PHONE,
      OWNER_FAX,
      OWNER_MOBILE,
      CREATEDATE,
      CREATEUSER)
    VALUES (
      OLD.ROOM,
      OLD.OWNER_NAME,
      OLD.OWNER_ADDRESS,
      OLD.OWNER_PHONE,
      OLD.OWNER_FAX,
      OLD.OWNER_MOBILE,
      'NOW', NEW.EDITUSER);
  END     
  /* 23 APRIL 2005 */
  if (NEW.PERSON_ADULT IS NULL) then NEW.PERSON_ADULT = 0;
  if (NEW.PERSON_CHILD IS NULL) then NEW.PERSON_CHILD = 0;
  /* 23 APRIL 2005 */
END
^

