CREATE TRIGGER TN_TENANT_JUR_AU FOR TN_TENANT_JUR
ACTIVE AFTER UPDATE POSITION 0
as
declare variable LUAS DOUBLE PRECISION;
declare variable SC DOUBLE PRECISION;
declare variable DB DOUBLE PRECISION;
declare variable OYEAR INTEGER;
declare variable OMONTH INTEGER;
declare variable DAYA VARCHAR(8);
declare variable CAT VARCHAR(4);
declare variable REMARK VARCHAR(40);
declare variable XMETER  DOUBLE PRECISION;
declare variable O_POWER DOUBLE PRECISION;
declare variable O_WATER DOUBLE PRECISION;
declare variable O_GAS   DOUBLE PRECISION;
declare variable REFF VARCHAR(20);
declare variable X INTEGER;
declare variable Y INTEGER;
declare variable flag_Service integer ;
declare variable flag_Counted integer ;
declare variable STATUS char (1); /*2906*/
declare variable SF double precision;/*0207*/
declare variable PPn double precision;/*0207*/
declare variable PARAM_SERVICE_CHARGE  DOUBLE PRECISION;
declare variable PARAM_SINKING_FUND    DOUBLE PRECISION;
declare variable TOTAL_SERVICE_SINKING DOUBLE PRECISION;
declare variable SERVICE_CHARGE_PERIOD INTEGER;

declare variable LAST_YEAR INTEGER;
declare variable LAST_MONTH INTEGER;
declare variable DELTA_PERIOD INTEGER;

declare variable vdebug integer ;
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE S1 VARCHAR(20);
DECLARE VARIABLE S2 VARCHAR(20);
DECLARE VARIABLE STEXT VARCHAR(20);
declare variable SC_POSTING INTEGER;
declare variable SC_PERIOD  INTEGER;
declare variable SC_TEXT    VARCHAR(40);

begin
  /* CREATE DETAIL TRANSACTION */
  Flag_Counted = 0 ;
  if ((NEW.METER_ELECTRIC <> OLD.METER_ELECTRIC) or
     (NEW.METER_WATER <> OLD.METER_WATER) OR
     (NEW.METER_GAS <> OLD.METER_GAS) OR
     ((NEW.RECALCULATE <> OLD.RECALCULATE) AND (NEW.RECALCULATE = 1 ))) then
  BEGIN

    /* ---------------------------------------------------------------------- */
    /* FIXED CHARGE                                                           */
    /* ---------------------------------------------------------------------- */
    if (NEW.RECALCULATE <> OLD.RECALCULATE) then
    BEGIN
       DELETE FROM TN_TENANT_JUR_DETAIL
       WHERE ROOM = NEW.ROOM
       AND PYEAR = NEW.PYEAR
       AND PMONTH = NEW.PMONTH
       AND FLAG_SYSTEM = 1;
    END
    
    SELECT STATUS FROM TN_ROOM  /*2906*/
    WHERE ROOM = NEW.ROOM
    INTO :STATUS;
       
    IF (STATUS IS NULL) THEN STATUS = 'A';

    FOR SELECT CATEGORY, REMARK, REFERENCE, DB FROM tn_fixed_charge
        WHERE FLAG_ACTIVE = 1
        INTO :CAT, :REMARK, :REFF, :DB
    DO
    BEGIN
    if (STATUS = 'P') THEN DB = 0;   /*2906*/
    EXECUTE PROCEDURE TN_TENANT_JUR_DETAIL_SAVE (
      NEW.ROOM,
      NEW.PYEAR,
      NEW.PMONTH,
      :CAT,
      :REMARK,
      :REFF,
      :DB);
    END
    /* ---------------------------------------------------------------------- */
    /* FIXED CHARGE EACH ROOM                                                 */
    /* ---------------------------------------------------------------------- */    
    FOR SELECT CATEGORY, REMARK, REFERENCE, DB FROM tn_room_fixed_charge
        WHERE ROOM = NEW.ROOM
        AND FLAG_ACTIVE = 1
        INTO :CAT, :REMARK, :REFF, :DB
    DO
    BEGIN
    EXECUTE PROCEDURE TN_TENANT_JUR_DETAIL_SAVE (
      NEW.ROOM,
      NEW.PYEAR,
      NEW.PMONTH,
      :CAT,
      :REMARK,
      :REFF,
      :DB);
    END        
    /* ---------------------------------------------------------------------- */
    /* CALC DATE                                                              */
    /* ---------------------------------------------------------------------- */
    OYEAR = NEW.PYEAR;
    OMONTH = NEW.PMONTH-1;
    if (OMONTH = 0) then
    BEGIN
      OYEAR = OYEAR-1;
      OMONTH = 12;
    END
    /* ---------------------------------------------------------------------- */
    /* SERVICE CHARGE                                                         */
    /* ---------------------------------------------------------------------- */
    SC_POSTING = 0;
    SC_PERIOD  = 1;
    SC_TEXT    = '';
    /* FIND ROOM - SERVICE CHARGE SCHEDULE */
    if (EXISTS (SELECT * FROM TN_TENANT_SC_SHECDULE
                WHERE PYEAR = NEW.PYEAR AND PMONTH = NEW.PMONTH AND ROOM = NEW.ROOM)) THEN
    BEGIN
       SELECT FLAG_POSTING, PERIOD, TEXT FROM TN_TENANT_SC_SHECDULE
       WHERE PYEAR = NEW.PYEAR
       AND PMONTH = NEW.PMONTH
       AND ROOM = NEW.ROOM
       INTO SC_POSTING, SC_PERIOD, SC_TEXT;
       if (SC_POSTING IS NULL) then
       BEGIN
          SC_POSTING = 0;
          SC_PERIOD  = 1;
          SC_TEXT    = '';
       END
    END
    ELSE
    BEGIN
    /* JIKA TIDAK ADA, FIND GLOBAL - SERVICE CHARGE SCHEDULE */
       if (EXISTS (SELECT * FROM TN_TENANT_SC_SHECDULE
                WHERE PYEAR = NEW.PYEAR AND PMONTH = NEW.PMONTH AND ROOM = 'Global')) THEN
      BEGIN
         SELECT FLAG_POSTING, PERIOD, TEXT FROM TN_TENANT_SC_SHECDULE
         WHERE PYEAR = NEW.PYEAR
         AND PMONTH = NEW.PMONTH
         AND ROOM = 'Global'
         INTO SC_POSTING, SC_PERIOD, SC_TEXT;
         if (SC_POSTING IS NULL) then
         BEGIN
            SC_POSTING = 0;
            SC_PERIOD  = 1;
            SC_TEXT    = '';
         END
      END
    END
    /* ---------------------------------------------------------------------- */
    /* SERVICE CHARGE                                                         */
    /* ---------------------------------------------------------------------- */
    if (SC_POSTING = 1) then /* 13-APRIL-2005 */
    BEGIN
       SELECT SQUARE_METER, FLAG_SERVICE, SERVICE_CHARGE, SINKING_FUND,
              SERVICE_CHARGE_PERIOD FROM TN_ROOM
       WHERE ROOM = NEW.ROOM
       INTO LUAS, FLAG_SERVICE, SC, SF, SERVICE_CHARGE_PERIOD;

       if (SC IS NULL) then SC = 0;
       if (SF IS NULL) then SF = 0;
    
       SERVICE_CHARGE_PERIOD = SC_PERIOD; /* DARI SCHEDULE */
       
       SELECT SERVICE_CHARGE, SINKING_FUND FROM tn_sysparam
       WHERE ID = 1
       INTO PARAM_SERVICE_CHARGE, PARAM_SINKING_FUND;

       if (SC = 0) then SC = PARAM_SERVICE_CHARGE;
       if (SF = 0) then SF = PARAM_SINKING_FUND;

       /* FLAG_SERVICE = 1 BERARTI HOTEL, SERVICE APPARTMENT */
       IF ((FLAG_SERVICE = 1) or (SC < 0)) then DB = 0;
       else DB = SC*LUAS;
       
       REFF = SC_TEXT;

       /*REFF = 'Per ' || SERVICE_CHARGE_PERIOD || ' bulan' ;*/
       DB = DB * SERVICE_CHARGE_PERIOD; /* 5-MARET-05 */
       EXECUTE PROCEDURE TN_TENANT_JUR_DETAIL_SAVE (
             NEW.ROOM,
             NEW.PYEAR,
             NEW.PMONTH,
             'SC',
             'Service Charge',
             :REFF,
             :DB);

       /* ----------------------------------------------------------------------*/
       /* SINKING FUND                                                          */
       /* ----------------------------------------------------------------------*/
       /* FLAG_SERVICE = 1 BERARTI HOTEL, SERVICE APPARTMENT */
       IF ((FLAG_SERVICE = 1) or (SF < 0)) then DB = 0;
       else DB = SF*LUAS;

       DB = DB * SERVICE_CHARGE_PERIOD; /* 5-MARET-05 */
       EXECUTE PROCEDURE TN_TENANT_JUR_DETAIL_SAVE (
               NEW.ROOM,
               NEW.PYEAR,
               NEW.PMONTH,
               'SF',
               'Sinking Fund',
               :REFF,
               :DB);
      /* ---------------------------------------------------------------------- */
      /* PPn   0207                                                             */
      /* ---------------------------------------------------------------------- */
      SELECT SQUARE_METER FROM TN_ROOM
      WHERE ROOM = NEW.ROOM
      INTO LUAS;
  
      SELECT SERVICE_CHARGE FROM tn_sysparam
      WHERE ID = 1 and ID = 2
      INTO PPn;

      IF (Flag_service = 1 ) then DB = 0;
      else DB = (SF * LUAS * 0.1) + (SC * LUAS * 0.1)  ;
      
      DB = DB * SERVICE_CHARGE_PERIOD; /* 5-MARET-05 */
      EXECUTE PROCEDURE TN_TENANT_JUR_DETAIL_SAVE (
                    NEW.ROOM,
                    NEW.PYEAR,
                    NEW.PMONTH,
                    'PPn',
                    'PPn',
                    :REFF,
                    :DB);
    END
    /* ---------------------------------------------------------------------- */
    /* POWER AND WATER                                                        */
    /* ---------------------------------------------------------------------- */
    SELECT PARAM_ELECTRIC, METER_ELECTRIC, METER_WATER, METER_GAS FROM TN_ROOM
    WHERE ROOM = NEW.ROOM
    INTO :DAYA, :O_POWER, O_WATER, O_GAS;
    if (DAYA IS NULL) then DAYA = '';
  
    FOR SELECT CATEGORY, REMARK, AMOUNT FROM tn_calc_power(:DAYA, new.meter_electric)
        INTO :CAT, :REMARK, :DB
    DO
    BEGIN
    EXECUTE PROCEDURE TN_TENANT_JUR_DETAIL_SAVE (
      NEW.ROOM,
      NEW.PYEAR,
      NEW.PMONTH,
      :CAT,
      :REMARK,
      '',
      :DB);
    END
    /* ---------------------------------------------------------------------- */
    /* WATER                                                                  */
    /* ---------------------------------------------------------------------- */
    FOR SELECT CATEGORY, REMARK, AMOUNT FROM tn_calc_water(NEW.METER_WATER)
        INTO :CAT, :REMARK, :DB
    DO
    BEGIN
    EXECUTE PROCEDURE TN_TENANT_JUR_DETAIL_SAVE (
      NEW.ROOM,
      NEW.PYEAR,
      NEW.PMONTH,
      :CAT,
      :REMARK,
      '',
      :DB);
    END
    /* ---------------------------------------------------------------------- */
    /* pinalty                                                                */
    /* ---------------------------------------------------------------------- */    
    FOR SELECT CATEGORY, REMARK, AMOUNT, REFERENCE FROM tn_calc_pinalty(NEW.CUSTOMER, NEW.PYEAR, NEW.PMONTH)
        INTO :CAT, :REMARK, :DB, :REFF
    DO
    BEGIN
    EXECUTE PROCEDURE TN_TENANT_JUR_DETAIL_SAVE (
      NEW.ROOM,
      NEW.PYEAR,
      NEW.PMONTH,
      :CAT,
      :REMARK,
      :REFF,
      :DB);
    END    
  END
end
^

CREATE TRIGGER TN_TENANT_JUR_AU_RELEASE FOR TN_TENANT_JUR
ACTIVE BEFORE UPDATE POSITION 99
as
declare variable OPENDATE DATE;
declare variable DUEDATE DATE;
declare variable CATEGORY VARCHAR(4);
declare variable DB DOUBLE PRECISION;
declare variable CR DOUBLE PRECISION;
declare variable REMARK VARCHAR(40);
declare variable GL_ACCOUNT VARCHAR(20);
declare variable GL_DEPT VARCHAR(4);
declare variable GL_COST VARCHAR(4);
declare variable AR_ACCOUNT VARCHAR(20);
declare variable AR_DEPT    VARCHAR(4);
declare variable AR_COST    VARCHAR(4);
declare variable xdate date;
declare variable ID INTEGER;
/* 16 JULI 2005 */
DECLARE VARIABLE VCH_STATUS CHAR(1);
begin
  if ((NEW.STATUS = 'R') AND (OLD.STATUS = 'O')) then
  BEGIN
     IF ((NEW.VOUCHER_NO = 0) OR (NEW.VOUCHER_NO IS NULL)) THEN
     BEGIN
        select Max(number) from ARVCH into new.voucher_no;
        if (new.voucher_no is null) then new.voucher_no = 1;
        else new.voucher_no = new.voucher_no+1;
     
        INSERT INTO arvch
        (CUSTOMER,
        DOCUMENT,
        OPENDATE, DUEDATE,
        STATUS, SOURCE, SOURCEID,
        CURRENCY, EXCHANGE,
        TOTAL, FOREX_TOTAL)
        VALUES
        (NEW.CUSTOMER,
        NEW.ROOM||'-'||NEW.PYEAR||'-'||NEW.PMONTH,
        NEW.OPENDATE, NEW.DUEDATE,
        'O', 'TN', NEW.TRANS_ID,
        'IDR', 1,
        NEW.DB-NEW.CR, NEW.DB-NEW.CR);
     END
     ELSE
     BEGIN
        UPDATE arvch SET CUSTOMER = NEW.CUSTOMER,
                DOCUMENT  = NEW.ROOM||'-'||NEW.PYEAR||'-'||NEW.PMONTH,
                OPENDATE = NEW.OPENDATE,
                DUEDATE = NEW.DUEDATE,
                STATUS = 'O',
                SOURCE = 'TN',
                SOURCEID = NEW.TRANS_ID,
                CURRENCY = 'IDR',
                EXCHANGE = 1,
                TOTAL = NEW.DB-NEW.CR,
                FOREX_TOTAL = NEW.DB-NEW.CR
        WHERE NUMBER = NEW.VOUCHER_NO;     
     END
     /* --------------------------------------------------------------------- */
     /* DETAIL TO GL BUFFER                                                   */
     /* --------------------------------------------------------------------- */
     xdate = '1.'||new.pmonth||'.'||new.pyear;
     FOR SELECT ID, GL_ACCOUNT, GL_COST, GL_DEPT,
                NOTE, DEBIT, CREDIT
         FROM TN_GLBUFFER_TENANT(NEW.ROOM, NEW.PYEAR, NEW.PMONTH)
         INTO ID, GL_ACCOUNT, GL_COST, GL_DEPT,
              REMARK, DB, CR
     DO
     BEGIN
        insert into glbuffer
               (APPLICATION, SOURCE, NUMBER, ID, transdate,
                ACCOUNT, DEPT, COST, PROJECT,
                NOTE, REF,
                DB, CR,
                EXPORTDATE, EXPORTUSER)
        values ('TN','TENT', old.trans_id, :ID, :xdate,
                :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                :REMARK, NEW.ROOM,
                :DB, :CR,
                'now', NEW.EDITUSER);
     END
  END
  ELSE
  IF ((NEW.STATUS = 'O') AND (OLD.STATUS = 'R')) THEN
  BEGIN
     SELECT STATUS FROM ARVCH WHERE NUMBER = NEW.VOUCHER_NO INTO VCH_STATUS;
     IF (VCH_STATUS <> 'O') THEN EXCEPTION ALL_DETAIL_NUMBER_CHANGE;

     UPDATE ARVCH SET TOTAL = 0, FOREX_TOTAL = 0, SOURCE_REMARK = 'REOPEN'
     WHERE NUMBER = NEW.VOUCHER_NO;
     
     DELETE FROM GLBUFFER
     WHERE APPLICATION = 'TN'
     AND SOURCE = 'TENT'
     AND NUMBER = NEW.TRANS_ID;  
     
     DELETE FROM GLBUFFER
     WHERE APPLICATION = 'AR'
     AND SOURCE = 'TENT'
     AND NUMBER = NEW.TRANS_ID;       
  END
end
^

CREATE TRIGGER TN_TENANT_JUR_BD FOR TN_TENANT_JUR
ACTIVE BEFORE DELETE POSITION 0
as
begin
  delete from tn_tenant_jur_detail
  where room =old.room
  and pyear = old.pyear and pmonth =old.pmonth;
end
^

CREATE TRIGGER TN_TENANT_JUR_BI FOR TN_TENANT_JUR
ACTIVE BEFORE INSERT POSITION 0
as
declare variable O_POWER DOUBLE PRECISION;
declare variable O_WATER DOUBLE PRECISION;
declare variable O_GAS   DOUBLE PRECISION;
declare variable OYEAR   INTEGER;
declare variable OMONTH  INTEGER;
begin
   NEW.TRANS_ID = GEN_ID(GEN_TN_TENANT_JUR_TRANS_ID,1);
   SELECT NAME, ADDRESS1, ADDRESS2, ADDRESS3, ADDRESS4 FROM SYSCUSTOMER
   WHERE CUSTOMER = NEW.ROOM
   INTO NEW.NAME, NEW.ADDRESS1, NEW.ADDRESS2, NEW.ADDRESS3, NEW.ADDRESS4;
   NEW.OPENDATE = '1.'||NEW.PMONTH||'.'|| NEW.PYEAR;
   NEW.DUEDATE  = '20.'||NEW.PMONTH||'.'||NEW.PYEAR;
   
   if (NEW.POWER_START IS NULL) then NEW.POWER_START = 0;
   if (NEW.POWER_END   IS NULL) then NEW.POWER_END = 0;
   
   if (NEW.WATER_START IS NULL) then NEW.WATER_START = 0;
   if (NEW.WATER_END   IS NULL) then NEW.WATER_END   = 0;
   
  OYEAR = NEW.PYEAR;
  OMONTH = NEW.PMONTH;
  
  OMONTH = OMONTH - 1;
  if (OMONTH < 1) then
  BEGIN
     OYEAR = OYEAR - 1;
     OMONTH = 12;
  END
  
  if (EXISTS (SELECT * FROM tn_tenant_jur
              WHERE ROOM = NEW.ROOM
              AND PYEAR = :OYEAR
              AND PMONTH = :OMONTH)) THEN
  BEGIN
     SELECT POWER_END, WATER_END FROM tn_tenant_jur
     WHERE ROOM = NEW.ROOM
     AND PYEAR = :OYEAR
     AND PMONTH = :OMONTH
     INTO :O_POWER, O_WATER;
     if (new.power_start = 0) then new.power_start = O_POWER;
     if (new.power_end   = 0) then new.power_end   = O_POWER;
     
     if (new.water_start = 0) then new.water_start = O_WATER;
     if (new.water_end   = 0) then new.water_end   = O_WATER;
  END
  
  if ((NEW.WATER_START <> 0) AND (NEW.WATER_END <> 0)) then
     NEW.METER_WATER = NEW.WATER_END - NEW.WATER_START;

  
  if ((NEW.POWER_START <> 0) AND (NEW.POWER_END <> 0)) then
     NEW.METER_ELECTRIC = NEW.POWER_END - NEW.POWER_START;
     
end
^

CREATE TRIGGER TN_TENANT_JUR_BU FOR TN_TENANT_JUR
ACTIVE BEFORE UPDATE POSITION 0
as
declare variable O_POWER DOUBLE PRECISION;
declare variable O_WATER DOUBLE PRECISION;
declare variable O_GAS   DOUBLE PRECISION;
declare variable OYEAR   INTEGER;
declare variable OMONTH  INTEGER;
declare variable MIN_WATER DOUBLE PRECISION;
declare variable MIN_POWER DOUBLE PRECISION;
/* 7 JULY 2005 */
declare variable DAY_OPEN INTEGER;
declare variable DAY_DUE  INTEGER;
begin
  if (NEW.POWER_START IS NULL) then NEW.POWER_START = 0;
  if (NEW.POWER_END   IS NULL) then NEW.POWER_END = 0;

  if (NEW.WATER_START IS NULL) then NEW.WATER_START = 0;
  if (NEW.WATER_END   IS NULL) then NEW.WATER_END   = 0;
  
  OYEAR = NEW.PYEAR;
  OMONTH = NEW.PMONTH;
  
  OMONTH = OMONTH - 1;
  if (OMONTH < 1) then
  BEGIN
     OYEAR = OYEAR - 1;
     OMONTH = 12;
  END
  
  
  if (EXISTS (SELECT * FROM tn_tenant_jur
              WHERE ROOM = NEW.ROOM
              AND PYEAR = :OYEAR
              AND PMONTH = :OMONTH)) THEN
  BEGIN
     SELECT POWER_END, WATER_END FROM tn_tenant_jur
     WHERE ROOM = NEW.ROOM
     AND PYEAR = :OYEAR
     AND PMONTH = :OMONTH
     INTO :O_POWER, O_WATER;
     if (new.power_start = 0) then new.power_start = O_POWER;
     if (new.power_end   = 0) then new.power_end   = O_POWER;
     
     if (new.water_start = 0) then new.water_start = O_WATER;
     if (new.water_end   = 0) then new.water_end   = O_WATER;
  END
  
  if ((NEW.WATER_START <> 0) AND (NEW.WATER_END <> 0)) then
     NEW.METER_WATER = NEW.WATER_END - NEW.WATER_START;

  
  if ((NEW.POWER_START <> 0) AND (NEW.POWER_END <> 0)) then
     NEW.METER_ELECTRIC = NEW.POWER_END - NEW.POWER_START;
  /* 24 MARET 2005 */
  SELECT MINIMUM_WATER, MINIMUM_POWER FROM TN_ROOM
  WHERE ROOM = NEW.ROOM
  INTO MIN_WATER, MIN_POWER;
  
  if (MIN_WATER IS NULL) then MIN_WATER = 0;
  if (MIN_POWER IS NULL) then MIN_POWER = 0;
  
  if ((MIN_WATER <> 0) AND (NEW.METER_WATER < MIN_WATER))    then NEW.METER_WATER    = MIN_WATER;
  if ((MIN_POWER <> 0) AND (NEW.METER_ELECTRIC < MIN_POWER)) then NEW.METER_ELECTRIC = MIN_POWER;
  /* 24 MARET 2005 */
   
  if ((old.status <> 'O') and ((OLD.DB <> NEW.DB) or (OLD.CR <> NEW.CR)))  then
     exception all_doc_status_not_open;
     
  if (NEW.CUSTOMER IS NULL) then NEW.CUSTOMER = NEW.ROOM;
  
  OYEAR = NEW.PYEAR;
  OMONTH = NEW.PMONTH;
  
  OMONTH = OMONTH - 1;
  if (OMONTH < 1) then
  BEGIN
     OYEAR = OYEAR - 1;
     OMONTH = 12;
  END
  
  if (EXISTS (SELECT * FROM tn_tenant_jur
              WHERE ROOM = NEW.ROOM
              AND PYEAR = :OYEAR
              AND PMONTH = :OMONTH)) THEN
   BEGIN
     SELECT METER_ELECTRIC, METER_WATER, METER_GAS FROM tn_tenant_jur
     WHERE ROOM = NEW.ROOM
     AND PYEAR = :OYEAR
     AND PMONTH = :OMONTH
     INTO :O_POWER, O_WATER, O_GAS;
   END
   ELSE
   BEGIN
     SELECT METER_ELECTRIC, METER_WATER, METER_GAS FROM TN_ROOM
     WHERE ROOM = NEW.ROOM
     INTO :O_POWER, O_WATER, O_GAS;
   END

   NEW.CONSUME_ELECTRIC = NEW.METER_ELECTRIC - O_POWER;
   NEW.CONSUME_WATER    = NEW.METER_WATER - O_WATER;
   NEW.CONSUME_GAS      = NEW.METER_GAS - O_GAS;
   /* ----------------------------------------------------------------------- */
   /* 7 JULY 2005,  DAY OPEN & DAY DUE                                        */
   /* ----------------------------------------------------------------------- */
   SELECT INVOICE_DAY, INVOICE_OPEN FROM TN_SYSPARAM
   WHERE ID = 1 INTO DAY_DUE, DAY_OPEN;
   
   if ((DAY_OPEN IS NULL) or (DAY_OPEN < 1)) then DAY_OPEN = 1;
   if ((DAY_DUE IS NULL) or (DAY_DUE <1)) then DAY_DUE = 20;

   NEW.OPENDATE = DAY_OPEN || '.' ||NEW.PMONTH||'.'|| NEW.PYEAR;
   OMONTH = NEW.PMONTH;
   IF (DAY_DUE < DAY_OPEN) THEN
   BEGIN
      OMONTH = OMONTH + 1;
      IF (OMONTH > 12) THEN
      BEGIN
         OMONTH = 1;
         NEW.PYEAR  = NEW.PYEAR + 1;
      END
   END
   NEW.DUEDATE  = DAY_DUE  || '.' ||OMONTH||'.'|| NEW.PYEAR;
end
^

CREATE TRIGGER TN_TENANT_JUR_BU_NAME FOR TN_TENANT_JUR
ACTIVE BEFORE UPDATE POSITION 1
AS
begin
   IF ((NEW.ROOM <> OLD.ROOM) OR (NEW.NAME IS NULL) OR ((NEW.RECALCULATE <> OLD.RECALCULATE) AND (NEW.RECALCULATE = 1 ))) THEN
   BEGIN
      SELECT CUSTOMER FROM TN_ROOM WHERE ROOM = NEW.ROOM
      INTO NEW.CUSTOMER;
      SELECT NAME, ADDRESS1, ADDRESS2, ADDRESS3, ADDRESS4 FROM SYSCUSTOMER
      WHERE CUSTOMER = NEW.CUSTOMER
      INTO NEW.NAME, NEW.ADDRESS1, NEW.ADDRESS2, NEW.ADDRESS3, NEW.ADDRESS4;
   END
end
^

CREATE TRIGGER TN_TENANT_JUR_BU_VOUCHERNO FOR TN_TENANT_JUR
ACTIVE BEFORE UPDATE POSITION 9
as
declare variable v integer;
begin
  if ((new.voucher_no <= 0) or (new.voucher_no is null) and (old.status = 'R')) then
  begin
     for select number from arvch
         where document = NEW.ROOM||'-'||NEW.PYEAR||'-'||NEW.PMONTH
         and source = 'TN'
     into v
     do
       if (v is null) then v = 0;
     new.voucher_no = v;
  end
end
^

CREATE TRIGGER TN_TENANT_JUR_DETAIL_AU0 FOR TN_TENANT_JUR_DETAIL
ACTIVE AFTER UPDATE POSITION 0
AS
DECLARE VARIABLE VDB DOUBLE PRECISION ;
DECLARE VARIABLE VCR DOUBLE PRECISION ;
begin
  /* Trigger text */
  SELECT SUM(DB),SUM(CR) FROM TN_TENANT_JUR_DETAIL
  WHERE ROOM=OLD.ROOM
    AND PYEAR=OLD.PYEAR
    AND PMONTH=OLD.PMONTH
   INTO :VDB,VCR ;

UPDATE TN_TENANT_JUR SET DB = :VDB, CR = :VCR
  WHERE ROOM = OLD.ROOM
  AND PYEAR = OLD.PYEAR
  AND PMONTH = OLD.PMONTH;

end
^

CREATE TRIGGER TN_TENANT_JUR_DETAIL_BD FOR TN_TENANT_JUR_DETAIL
ACTIVE BEFORE DELETE POSITION 0
as
begin
  UPDATE TN_TENANT_JUR SET DB = DB - OLD.DB, CR = CR - OLD.CR
  WHERE ROOM = OLD.ROOM
  AND PYEAR = OLD.PYEAR
  AND PMONTH = OLD.PMONTH;
end
^

CREATE TRIGGER TN_TENANT_JUR_DETAIL_BI FOR TN_TENANT_JUR_DETAIL
ACTIVE BEFORE INSERT POSITION 0
as
begin
  SELECT MAX(TRANS_ID) FROM TN_TENANT_JUR_DETAIL
  INTO NEW.TRANS_ID;
  if (NEW.TRANS_ID IS NULL) then NEW.TRANS_ID = 0;
  NEW.TRANS_ID = NEW.TRANS_ID + 1;
  
  if (NEW.DB IS NULL) then NEW.DB = 0;
  if (NEW.CR IS NULL) then NEW.CR = 0;
  
  UPDATE TN_TENANT_JUR SET DB = DB + NEW.DB, CR = CR + NEW.CR
  WHERE ROOM = NEW.ROOM
  AND PYEAR = NEW.PYEAR
  AND PMONTH = NEW.PMONTH;  
end
^

CREATE TRIGGER TN_TENANT_JUR_DETAIL_BU FOR TN_TENANT_JUR_DETAIL
ACTIVE BEFORE UPDATE POSITION 0
as
begin
  UPDATE TN_TENANT_JUR SET DB = DB - OLD.DB, CR = CR - OLD.CR
  WHERE ROOM = OLD.ROOM
  AND PYEAR = OLD.PYEAR
  AND PMONTH = OLD.PMONTH;


  UPDATE TN_TENANT_JUR SET DB = DB + NEW.DB, CR = CR + NEW.CR
  WHERE ROOM = NEW.ROOM
  AND PYEAR = NEW.PYEAR
  AND PMONTH = NEW.PMONTH;
end
^

CREATE TRIGGER TN_TENANT_JUR_FIXED_CHARGE FOR TN_TENANT_JUR
ACTIVE AFTER INSERT POSITION 0
as
declare variable CAT VARCHAR(4);
declare variable REMARK VARCHAR(40);
declare variable REFF VARCHAR(20);
declare variable DB DOUBLE PRECISION;
begin
    FOR SELECT CATEGORY, REMARK, REFERENCE, DB FROM tn_fixed_charge
        WHERE FLAG_ACTIVE = 1
        INTO :CAT, :REMARK, :REFF, :DB
    DO
    BEGIN
    EXECUTE PROCEDURE TN_TENANT_JUR_DETAIL_SAVE (
      NEW.ROOM,
      NEW.PYEAR,
      NEW.PMONTH,
      :CAT,
      :REMARK,
      :REFF,
      :DB);
    END
    
    FOR SELECT CATEGORY, REMARK, REFERENCE, DB FROM tn_room_fixed_charge
        WHERE ROOM = NEW.ROOM
        AND FLAG_ACTIVE = 1
        INTO :CAT, :REMARK, :REFF, :DB
    DO
    BEGIN
    EXECUTE PROCEDURE TN_TENANT_JUR_DETAIL_SAVE (
      NEW.ROOM,
      NEW.PYEAR,
      NEW.PMONTH,
      :CAT,
      :REMARK,
      :REFF,
      :DB);
    END    
end
^

