ALTER PROCEDURE AP_ADJ_CHECK_SUPPLIER
RETURNS (
    ADJ_NUMBER INTEGER,
    VOUCHERNO INTEGER,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    OPENDATE DATE,
    STATUS CHAR(1),
    VCH_SUPPLIER VARCHAR(6),
    VCH_NAME VARCHAR(40),
    CASH_SUPPLIER VARCHAR(6),
    CASH_NAME VARCHAR(40))
AS
BEGIN
  FOR
    SELECT A.NUMBER, A.VOUCHERNO, A.SUPPLIER, S.NAME, A.OPENDATE, A.STATUS
    FROM APADJ A
    LEFT JOIN SYSSUPPLIER S ON A.SUPPLIER=S.SUPPLIER
    ORDER BY A.VOUCHERNO
    INTO
      :ADJ_NUMBER,
      :VOUCHERNO,
      :SUPPLIER,
      :NAME,
      :OPENDATE,
      :STATUS
  DO
  BEGIN
    VCH_SUPPLIER = '';
    VCH_NAME = '';

    IF (EXISTS(SELECT * FROM APVCH WHERE NUMBER = :VOUCHERNO AND SUPPLIER <> :SUPPLIER)) THEN
    BEGIN
       SELECT V.SUPPLIER, S.NAME FROM APVCH V
       LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = V.SUPPLIER
       WHERE NUMBER = :VOUCHERNO
       INTO VCH_SUPPLIER, VCH_NAME;
       SUSPEND;
    END
    CASH_SUPPLIER = '';
    CASH_NAME = '';
    IF (EXISTS(SELECT * FROM APCASH1 WHERE VOUCHERNO = :VOUCHERNO AND SUPPLIER <> :SUPPLIER)) THEN
    BEGIN
       FOR SELECT V.SUPPLIER, S.NAME FROM APCASH1 V
          LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = V.SUPPLIER
          WHERE NUMBER = :VOUCHERNO
          INTO CASH_SUPPLIER, CASH_NAME
       DO
       BEGIN
          SUSPEND;
       END
    END
  END
END^


ALTER PROCEDURE AP_AGING(
    SSUPPLIER VARCHAR(6),
    ESUPPLIER VARCHAR(6),
    DETAILFLAG INTEGER,
    CURRENCY VARCHAR(4))
RETURNS (
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    CURR NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4),
    TOTAL NUMERIC(15,4),
    AGE INTEGER,
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    DOCUMENT VARCHAR(20),
    SUPLTYPE VARCHAR(4),
    TYPENAME VARCHAR(40))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable voucher double precision;
declare variable cash    double precision;
declare variable adjust  double precision;
declare variable depos   double precision;

declare variable F_voucher double precision;
declare variable F_cash    double precision;
declare variable F_adjust  double precision;
declare variable F_depos   double precision;
declare variable vPayDate Date;
declare variable ARDate DATE;
declare variable XDEPOSIT DOUBLE PRECISION;
begin
  /* Procedure Text */
  if ((SSUPPLIER IS NULL) or (SSUPPLIER || ESUPPLIER = '')) then BEGIN
     SSUPPLIER = '';
     ESUPPLIER = 'zzzzzz';
  END
  
  if (DETAILFLAG IS NULL) then
      DETAILFLAG = 0;
      
  if (CURRENCY IS NULL) then CURRENCY = 'All';
  
  
  SELECT APSYSDATE+1 FROM SYSPARAM INTO ARDATE;


  for select SUPPLIER, name, SUPLTYPE from sysSUPPLIER
  where SUPPLIER between :sSUPPLIER and :eSUPPLIER
  into :SUPPLIER, name, SUPLTYPE
  do
  begin
    SELECT NAME FROM SYSSUPPLIERTYPE
    WHERE SUPPLIERTYPE = :SUPLTYPE
    INTO :TYPENAME;
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    end
    opendate = null;
    duedate = null;
    document = null;

    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/
    for select number, totaldue, forex_totaldue,
               opendate, duedate, document
          from APVCH
         where SUPPLIER = :SUPPLIER
           and ((totaldue <> 0) or (forex_totaldue <> 0))
           and ((:CURRENCY = 'All') or (CURRENCY = :CURRENCY))
         into number, voucher, f_voucher, opendate, duedate, document
    do
    begin
       if (CURRENCY <> 'All') then
          voucher = f_voucher;
       d = ARDate - opendate;
      /*======================================================================*/
      /* jika aging detail                                                    */
      /*======================================================================*/
       if (detailflag = 1) then
       begin
          curr = 0;
          over30 = 0;
          over60 = 0;
          over90 = 0;
       end
       if (d <= 30)      then curr   = curr + voucher;
       else if (d <= 60) then over30 = over30 + voucher;
       else if (d <= 90) then over60 = over60 + voucher;
       else over90 = over90 + voucher;

       /* ------------------------------------------------------------------- */
       /* detail aging (ada nomor vouchernya                                  */
       /* ------------------------------------------------------------------- */
       if (detailflag = 1) then
       begin
         age = d;
         total = curr + over30 + over60 + over90;
         if (total <> 0) then
            suspend;
       end
    end

    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       total = curr + over30 + over60 + over90;
       number = 0;
       document = '';
       if (total <> 0) then
          suspend;
    end
  end
end^


ALTER PROCEDURE AP_AGING_OLD(
    SSUPPLIER VARCHAR(6),
    ESUPPLIER VARCHAR(6),
    REFDATE DATE,
    DETAILFLAG INTEGER,
    CURRENCY VARCHAR(4))
RETURNS (
    PREFDATE DATE,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NAMETYPE VARCHAR(40),
    CODETYPE VARCHAR(40),
    CURR NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4),
    TOTAL NUMERIC(15,4),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    DOCUMENT VARCHAR(20),
    AGE INTEGER,
    T DOUBLE PRECISION,
    RECEIVINGNO INTEGER,
    SOURCE CHAR(1),
    RCVDOC VARCHAR(100))
AS
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE VOUCHER DOUBLE PRECISION;
DECLARE VARIABLE CASH DOUBLE PRECISION;
DECLARE VARIABLE ADJUST DOUBLE PRECISION;
DECLARE VARIABLE DEPOS DOUBLE PRECISION;
DECLARE VARIABLE F_VOUCHER DOUBLE PRECISION;
DECLARE VARIABLE F_CASH DOUBLE PRECISION;
DECLARE VARIABLE F_ADJUST DOUBLE PRECISION;
DECLARE VARIABLE F_DEPOS DOUBLE PRECISION;
begin
  if (SSUPPLIER IS NULL) then
  BEGIN
     SSUPPLIER = '';
     ESUPPLIER = 'zzzzzz';
     SELECT APSYSDATE FROM SYSPARAM INTO REFDATE;
     REFDATE = '27.3.2008';
     DETAILFLAG = 0;
     CURRENCY = 'SIN';
  END
  T = 0;
  PREFDATE = REFDATE;



  for select A.supplier,A.name,A.SUPLTYPE,T.NAME,
             T.GLACCOUNT,T.GLDEPT,T.GLCOST,COA.NAME
  from syssupplier A
       LEFT JOIN SYSSUPPLIERTYPE T ON T.SUPPLIERTYPE = A.SUPLTYPE
       LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.GLACCOUNT
  where supplier between :ssupplier and :esupplier
  into :supplier,name,CODETYPE,NAMETYPE,
       GL_ACCOUNT,GL_DEPT,GL_COST,ACCNAME
  do
  begin
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    end
    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/
    for select number,total,opendate,duedate,document,receivingno,source,supplier,
               forex_total /* 27 MARET 2008 */
        from apvch
         where supplier = :supplier
           and opendate <= :RefDate
           and ((:CURRENCY = 'All') or (CURRENCY = :CURRENCY)) /* 27 MARET 2008 */
         plan (apvch index (APVCH_IDX_SUPPLIER_DATE))
         into number,voucher,opendate,duedate,document,receivingno,source,supplier,
              f_voucher /* 27 MARET 2008 */
    do
    begin

       select sum(apcash1.total-apcash1.vch_gainloss),
              sum(apcash1.forex_total) /* 27 MARET 2008 */
        from apcash1
         inner join apcash0 on apcash0.number = apcash1.number
        where apcash1.voucherno = :number and apcash0.duedate <= :RefDate
          and apcash0.status in ('R','C','L')
         into cash,f_cash; /* 27 MARET 2008 */

       select sum(total+VCH_GAINLOSS),/* 5/20/2011 tadinya cuma forex_total */
              sum(forex_total) /* 27 MARET 2008 */
       from apdepos1
        where voucherno = :number and applieddate <= :RefDate
          and status in ('R','C','L')
         into depos,f_depos; /* 27 MARET 2008 */

       select sum(cr-db),
              sum(forex_cr-forex_db)/* 27 MARET 2008 */
        from apadj where voucherno = :number and OpenDate <= :RefDate
         into adjust,f_adjust;
/*
name = 'voucher';
accname = voucher;
suspend;
name = 'cash';
accname = cash;
suspend;
name = 'adjust';
accname = adjust;
suspend;
name = 'depos';
accname = depos;
suspend;
*/
       if (voucher is null) then voucher = 0;
       if (cash    is null) then cash    = 0;
       if (adjust  is null) then adjust  = 0;
       if (depos   is null) then depos   = 0;
       /* ---------------------------------------------------------------- */
       /* 27 MARET 2008                                                    */
       /* ---------------------------------------------------------------- */
       if (f_voucher is null) then f_voucher = 0;
       if (f_cash    is null) then f_cash    = 0;
       if (f_adjust  is null) then f_adjust  = 0;
       if (f_depos   is null) then f_depos   = 0;
       /* ---------------------------------------------------------------- */
       IF (CURRENCY = 'All') THEN
       begin
          voucher = voucher - cash + adjust - depos;
       end
       ELSE
       begin
          voucher = f_voucher - f_cash + f_adjust - f_depos;
       end
       d = RefDate - opendate;
       /*========================================================================*/
       /* jika aging detail                                                      */
       /*========================================================================*/
       if (detailflag = 1) then
       begin
          curr = 0;
          over30 = 0;
          over60 = 0;
          over90 = 0;
       end
       if (voucher between -0.009 and 0.009) then voucher=0; /* 1/18/2012 SPY KALAU KECIL2 GAK JADI PEMBULATAN*/
              
       if (d <= 30)      then curr   = curr + voucher;
       else if (d <= 60) then over30 = over30 + voucher;
       else if (d <= 90) then over60 = over60 + voucher;
       else over90 = over90 + voucher;
       if (detailflag = 1) then
       begin
         age = d;
         total = curr + over30 + over60 + over90;
         if (total not between -0.001 and 0.001) then suspend;
       end
    end
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       total = curr + over30 + over60 + over90;
       number = 0;
       document = '';
       T = T + TOTAL;
       if (total not between -0.009 and 0.009) then suspend;
    end
  end
end^


ALTER PROCEDURE AP_AGING_OLD_CURRENCY(
    SSUPPLIER VARCHAR(6),
    ESUPPLIER VARCHAR(6),
    REFDATE DATE,
    DETAILFLAG INTEGER,
    CURRENCY VARCHAR(4))
RETURNS (
    PREFDATE DATE,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NAMETYPE VARCHAR(40),
    CODETYPE VARCHAR(40),
    CURR NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4),
    TOTAL NUMERIC(15,4),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    DOCUMENT VARCHAR(20),
    AGE INTEGER,
    T DOUBLE PRECISION,
    RECEIVINGNO INTEGER,
    SOURCE CHAR(1),
    RCVDOC VARCHAR(100))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable voucher numeric(15,4);
declare variable cash    numeric(15,4);
declare variable adjust  numeric(15,4);
declare variable depos   numeric(15,4);
/* ---------------------------------------------------------------- */
/* 28 MARET 2008                                                    */
/* MULTI CURRENCIES DISPLAY                                         */
/* ---------------------------------------------------------------- */
declare variable f_voucher numeric(15,4);
declare variable f_cash    numeric(15,4);
declare variable f_adjust  numeric(15,4);
declare variable f_depos   numeric(15,4);
begin
  if (SSUPPLIER IS NULL) then
  BEGIN
     SSUPPLIER = '';
     ESUPPLIER = 'zzzzzz';
     SELECT APSYSDATE FROM SYSPARAM INTO REFDATE;
     REFDATE = '27.3.2008';
     DETAILFLAG = 0;
     CURRENCY = 'SIN';
  END
  T = 0;
  PREFDATE = REFDATE;
  
  
  
  for select A.supplier,A.name,A.SUPLTYPE,T.NAME,
             T.GLACCOUNT,T.GLDEPT,T.GLCOST,COA.NAME
  from syssupplier A
       LEFT JOIN SYSSUPPLIERTYPE T ON T.SUPPLIERTYPE = A.SUPLTYPE
       LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.GLACCOUNT
  where supplier between :ssupplier and :esupplier
  into :supplier,name,CODETYPE,NAMETYPE,
       GL_ACCOUNT,GL_DEPT,GL_COST,ACCNAME
  do
  begin
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/    
    if (detailflag <> 1) then
    begin
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    end
    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/    
    for select number,total,opendate,duedate,document,receivingno,source,supplier,
               forex_total /* 27 MARET 2008 */
        from apvch
         where supplier = :supplier
           and opendate <= :RefDate
           and ((:CURRENCY = 'All') or (CURRENCY = :CURRENCY)) /* 27 MARET 2008 */
         plan (apvch index (APVCH_IDX_SUPPLIER_DATE))
         into number,voucher,opendate,duedate,document,receivingno,source,supplier,
              f_voucher /* 27 MARET 2008 */
    do
    begin
       select sum(apcash1.total-apcash1.vch_gainloss),
              sum(apcash1.forex_total) /* 27 MARET 2008 */
        from apcash1
         inner join apcash0 on apcash0.number = apcash1.number
        where apcash1.voucherno = :number and apcash0.duedate <= :RefDate
          and apcash0.status in ('R','C','L')
         into cash,
              f_cash; /* 27 MARET 2008 */
         
       select sum(forex_total*vch_exchange),
              sum(apdepos1.forex_total) /* 27 MARET 2008 */
       from apdepos1
        where apdepos1.voucherno = :number and apdepos1.applieddate <= :RefDate
          and apdepos1.status in ('R','C','L')        
         into depos,
              f_depos; /* 27 MARET 2008 */
                  
       select sum(cr-db),
              sum(forex_cr-forex_db)/* 27 MARET 2008 */
        from apadj where voucherno = :number and OpenDate <= :RefDate
         into adjust,f_adjust;

       if (voucher is null) then voucher = 0;
       if (cash    is null) then cash    = 0;
       if (adjust  is null) then adjust  = 0;
       if (depos   is null) then depos   = 0;
       
       /* ---------------------------------------------------------------- */
       /* 27 MARET 2008                                                    */
       /* ---------------------------------------------------------------- */
       if (f_voucher is null) then f_voucher = 0;
       if (f_cash    is null) then f_cash    = 0;
       if (f_adjust  is null) then f_adjust  = 0;
       if (f_depos   is null) then f_depos   = 0;
       /* ---------------------------------------------------------------- */
       IF (CURRENCY = 'All') THEN
          voucher = voucher - cash + adjust - depos;
       ELSE
          voucher = f_voucher - f_cash + f_adjust - f_depos;
          
       d = RefDate - opendate;
       /*========================================================================*/
       /* jika aging detail                                                      */
       /*========================================================================*/
       if (detailflag = 1) then
       begin
          curr = 0;
          over30 = 0;
          over60 = 0;
          over90 = 0;
       end
       if (d <= 30)      then curr   = curr + voucher;
       else if (d <= 60) then over30 = over30 + voucher;
       else if (d <= 90) then over60 = over60 + voucher;
       else over90 = over90 + voucher;
       if (detailflag = 1) then
       begin
         age = d;
         total = curr + over30 + over60 + over90;
         if (total <> 0) then suspend;
       end
    end
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/    
    if (detailflag <> 1) then
    begin
       total = curr + over30 + over60 + over90;
       number = 0;
       document = '';
       T = T + TOTAL;
       if (total <> 0) then suspend;
    end
  end
end^


ALTER PROCEDURE AP_ANALISYS(
    PYEAR INTEGER)
RETURNS (
    REFDATE DATE,
    PMONTH INTEGER,
    CURR DOUBLE PRECISION,
    OVER30 DOUBLE PRECISION,
    OVER60 DOUBLE PRECISION,
    OVER90 DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    P_CURR DOUBLE PRECISION,
    P_OVER30 DOUBLE PRECISION,
    P_OVER60 DOUBLE PRECISION,
    P_OVER90 DOUBLE PRECISION,
    P_TOTAL DOUBLE PRECISION,
    MUT_OPENING DOUBLE PRECISION,
    MUT_VOUCHER DOUBLE PRECISION,
    MUT_CASH DOUBLE PRECISION,
    MUT_DEPOSIT DOUBLE PRECISION,
    MUT_ADJUST DOUBLE PRECISION,
    MUT_ENDING DOUBLE PRECISION,
    TURN_OVER DOUBLE PRECISION,
    Z_TOTAL DOUBLE PRECISION,
    Z_VOUCHER DOUBLE PRECISION,
    AVG_TOTAL DOUBLE PRECISION,
    AVG_VOUCHER DOUBLE PRECISION,
    COLLECT_PERIOD DOUBLE PRECISION)
AS
DECLARE VARIABLE APSYSDATE DATE;
DECLARE VARIABLE EOM DATE;
BEGIN
  SELECT APSYSDATE FROM SYSPARAM INTO APSYSDATE;
  EXECUTE PROCEDURE SP_ENDOFMONTH(APSYSDATE) RETURNING_VALUES EOM;
  
  IF ((PYEAR IS NULL) OR (PYEAR = 0)) THEN 
     PYEAR = EXTRACT(YEAR FROM APSYSDATE);
     
  PMONTH = 1;
  Z_TOTAL = 0;
  Z_VOUCHER = 0;
  WHILE (PMONTH <= 12) DO
  BEGIN
    REFDATE = '1.'|| PMONTH ||'.'||PYEAR;
    EXECUTE PROCEDURE SP_ENDOFMONTH(REFDATE) RETURNING_VALUES REFDATE;
    IF (REFDATE > EOM) THEN EXIT;
    
    SELECT SUM(CURR), SUM(OVER30), SUM(OVER60), SUM(OVER90)
    FROM AP_AGING_OLD('','zzzz', :REFDATE, 0, 'All')
    INTO CURR, OVER30, OVER60, OVER90;
    IF (CURR IS NULL) THEN
    BEGIN
      CURR = 0;
      OVER30 = 0;
      OVER60 = 0;
      OVER90 = 0;
    END
    TOTAL = CURR + OVER30 + OVER60 + OVER90;
    IF (TOTAL <> 0) THEN
    BEGIN
      P_CURR = CURR/TOTAL*100;
      P_OVER30 = OVER30/TOTAL*100;
      P_OVER60 = OVER60/TOTAL*100;
      P_OVER90 = OVER90/TOTAL*100;
      P_TOTAL  = 100;
    END
    ELSE
    BEGIN
      P_CURR = 0;
      P_OVER30 = 0;
      P_OVER60 = 0;
      P_OVER90 = 0;
      P_TOTAL = 0;
    END
    SELECT SUM(OPENING), SUM(VOUCHER), SUM(CASH), SUM(ADJUST), SUM(DEPOSIT), SUM(ENDING)
    FROM AP_MUTATION_OLD('','zzzz', :REFDATE)
    INTO MUT_OPENING, MUT_VOUCHER, MUT_CASH, MUT_ADJUST, MUT_DEPOSIT, MUT_ENDING;
    
    IF (MUT_OPENING IS NULL) THEN
    BEGIN
       MUT_OPENING = 0;
       MUT_VOUCHER = 0;
       MUT_CASH = 0;
       MUT_ADJUST = 0;
       MUT_DEPOSIT = 0;
       MUT_ENDING = 0;
    END
    Z_TOTAL = Z_TOTAL + TOTAL;
    Z_VOUCHER = Z_VOUCHER + MUT_VOUCHER;
    AVG_TOTAL = Z_TOTAL / PMONTH;
    AVG_VOUCHER = Z_VOUCHER / PMONTH;
    IF (AVG_TOTAL <> 0) THEN TURN_OVER = (AVG_VOUCHER/AVG_TOTAL);
    ELSE TURN_OVER = 0;
    
    SUSPEND;
    PMONTH = PMONTH + 1;
  END
END^


ALTER PROCEDURE AP_CASHQ(
    SDATE DATE)
RETURNS (
    WK INTEGER,
    WKSDATE DATE,
    WKEDATE DATE,
    VOUCHERDUE NUMERIC(15,4),
    CASHDUE NUMERIC(15,4),
    BANKDUE NUMERIC(15,4),
    TOTAL NUMERIC(15,4))
AS
declare variable d integer;
begin
  
  if (sDate is null) then
     SELECT APSYSDATE FROM SYSPARAM INTO :SDATE;
     
     
  d = -1;
  while (d <> 5) do
  begin
    execute procedure sp_dayofweek(SDate) returning_values d;
    SDate = SDate-1;
  end
  wk = 0;
  while (wk <= 7) do
  begin

    wksdate = sDate+wk*7;
    wkedate = wksdate+6;
    
    if (wk = 0 ) then wksdate = wksdate - 3650;
    if (wk = 7) then wkedate = wkedate + 3650;
    
    SELECT SUM(totaldue_prepare) FROM apvch
     WHERE opendate between :wksdate and :wkedate into voucherdue;

    SELECT SUM(TOTAL) FROM apcash0
     WHERE opendate between :wksdate and :wkedate
       and status IN ('O','A')
      into cashdue;

    SELECT SUM(TOTAL) FROM apcash0
     WHERE OPENDATE between :wksdate and :wkedate
       and status IN ('R','L')
      into bankdue;
      
    if (voucherdue is null) then voucherdue = 0;
    if (cashdue    is null) then cashdue    = 0;
    if (bankdue    is null) then bankdue    = 0;
    total = voucherdue + cashdue + bankdue;
    suspend;
    wk = wk+1;    
  end
  
end^


ALTER PROCEDURE AP_CASH_RECONCILE(
    PMONTH INTEGER,
    PYEAR INTEGER,
    FLAG_MTD_ONLY INTEGER,
    FLAG_OUTSTANDING_ONLY INTEGER)
RETURNS (
    DATAINFO VARCHAR(20),
    NUMBER INTEGER,
    STATUS CHAR(1),
    DOCUMENT VARCHAR(20),
    CHECK_NUMBER VARCHAR(20),
    OPENDATE DATE,
    RECONCILEDATE DATE,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    BANK VARCHAR(4),
    BANKNAME VARCHAR(40),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    TOTAL_FOREX DOUBLE PRECISION,
    PREV_ISSUED DOUBLE PRECISION,
    PREV_RECONCILED DOUBLE PRECISION,
    MTD_ISSUED DOUBLE PRECISION,
    MTD_RECONCILED DOUBLE PRECISION,
    TOTAL_OUTSTANDING DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE RYEAR INTEGER;
DECLARE VARIABLE RMONTH INTEGER;
DECLARE VARIABLE X INTEGER;
BEGIN
  IF ((PYEAR IS NULL) OR (PMONTH = 0)) THEN
  BEGIN
     PYEAR = 2005;
     PMONTH = 8;
     FLAG_MTD_ONLY = 1;
     FLAG_OUTSTANDING_ONLY = 0;
  END
  EXECUTE PROCEDURE SP_ENCODEDATE(PYEAR, PMONTH, 1) RETURNING_VALUES SDATE;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES EDATE;
  
  IF (FLAG_MTD_ONLY = 0) THEN
     EXECUTE PROCEDURE SP_ENCODEDATE(1980, PMONTH, 1) RETURNING_VALUES SDATE;
  /* ---------------------------------------------------------------- */
  /* CASH PAYMENT                                                     */
  /* ---------------------------------------------------------------- */
  DATAINFO = 'Cash Payment';
  FOR
    SELECT C.NUMBER, C.STATUS,
           C.DOCUMENT, C.CHECK_NUMBER, C.DUEDATE, C.RECONCILEDATE,
           C.SUPPLIER, S.NAME,
           C.BANK, B.BANKNAME,
           C.TOTAL, C.CURRENCY, C.EXCHANGE, C.FOREX_TOTAL
    FROM APCASH0 C
    LEFT JOIN SYSBANK B ON B.BANK = C.BANK
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = C.SUPPLIER
    WHERE ((DUEDATE BETWEEN :SDATE AND :EDATE) OR
           (RECONCILEDATE BETWEEN :SDATE AND :EDATE))
    AND STATUS IN ('C','R','L')
    AND TOTAL <> 0
    ORDER BY C.BANK, C.OPENDATE, C.NUMBER
    INTO
      :NUMBER,
      :STATUS,
      :DOCUMENT,
      :CHECK_NUMBER,
      :OPENDATE,
      :RECONCILEDATE,
      :SUPPLIER,
      :NAME,
      :BANK,
      :BANKNAME,
      :TOTAL, :CURRENCY, :EXCHANGE, :TOTAL_FOREX
  DO
  BEGIN
    RYEAR  = EXTRACT(YEAR FROM RECONCILEDATE);
    RMONTH = EXTRACT(MONTH FROM RECONCILEDATE);
    
    PREV_ISSUED = 0;
    MTD_ISSUED = 0;
    IF (STATUS IN ('C','R','L')) THEN
    BEGIN
       IF (OPENDATE BETWEEN SDATE AND :EDATE) THEN
       BEGIN
          MTD_ISSUED = TOTAL;
       END
       IF (OPENDATE < SDATE) THEN PREV_ISSUED = TOTAL;
    END

    MTD_RECONCILED = 0;
    PREV_RECONCILED = 0;
    IF (STATUS = 'C') THEN
    BEGIN
      IF (RECONCILEDATE BETWEEN SDATE AND EDATE) THEN
      BEGIN
        MTD_RECONCILED = TOTAL;
        PREV_RECONCILED = 0;
      END
      ELSE
      IF (RECONCILEDATE < SDATE)  THEN
      BEGIN
        MTD_RECONCILED = 0;
        PREV_RECONCILED = TOTAL;
      END
    END

    TOTAL_OUTSTANDING = (MTD_ISSUED + PREV_ISSUED) - (MTD_RECONCILED+PREV_RECONCILED);
    IF (FLAG_OUTSTANDING_ONLY = 1) THEN
    BEGIN
       IF (TOTAL_OUTSTANDING <> 0) THEN
          SUSPEND;
    END
    ELSE SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* DEPOSIT                                                          */
  /* ---------------------------------------------------------------- */
  DATAINFO = 'Deposit';
  FOR
    SELECT C.NUMBER, C.STATUS,
           C.DOCUMENT, C.CHECK_NUMBER, C.OPENDATE, C.RECONCILEDATE,
           C.SUPPLIER, S.NAME,
           C.BANK, B.BANKNAME,
           C.TOTAL, C.CURRENCY, C.EXCHANGE, C.FOREX_TOTAL
    FROM APDEPOS0 C
    LEFT JOIN SYSBANK B ON B.BANK = C.BANK
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = C.SUPPLIER
    WHERE ((OPENDATE BETWEEN :SDATE AND :EDATE) OR
           (RECONCILEDATE BETWEEN :SDATE AND :EDATE))
    AND STATUS IN ('C','R','L')
    AND TOTAL <> 0
    ORDER BY C.BANK, C.OPENDATE, C.NUMBER
    INTO
      :NUMBER,
      :STATUS,
      :DOCUMENT,
      :CHECK_NUMBER,
      :OPENDATE,
      :RECONCILEDATE,
      :SUPPLIER,
      :NAME,
      :BANK,
      :BANKNAME,
      :TOTAL, :CURRENCY, :EXCHANGE, :TOTAL_FOREX
  DO
  BEGIN

    RYEAR  = EXTRACT(YEAR FROM RECONCILEDATE);
    RMONTH = EXTRACT(MONTH FROM RECONCILEDATE);

    PREV_ISSUED = 0;
    MTD_ISSUED = 0;
    IF (STATUS IN ('C','R','L')) THEN
    BEGIN
       IF (OPENDATE BETWEEN SDATE AND :EDATE) THEN
       BEGIN
          MTD_ISSUED = TOTAL;
       END
       IF (OPENDATE < SDATE) THEN PREV_ISSUED = TOTAL;
    END

    MTD_RECONCILED = 0;
    PREV_RECONCILED = 0;
    IF (STATUS = 'C') THEN
    BEGIN
      IF (RECONCILEDATE BETWEEN SDATE AND EDATE) THEN
      BEGIN
        MTD_RECONCILED = TOTAL;
        PREV_RECONCILED = 0;
      END
      ELSE
      IF (RECONCILEDATE < SDATE)  THEN
      BEGIN
        MTD_RECONCILED = 0;
        PREV_RECONCILED = TOTAL;
      END
    END

    TOTAL_OUTSTANDING = (MTD_ISSUED + PREV_ISSUED) - (MTD_RECONCILED+PREV_RECONCILED);
    IF (FLAG_OUTSTANDING_ONLY = 1) THEN
    BEGIN
       IF (TOTAL_OUTSTANDING <> 0) THEN
          SUSPEND;
    END
    ELSE SUSPEND;
  END
END^


ALTER PROCEDURE AP_CASH_RECONCILE_CHECK(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    NUMBER INTEGER,
    RECONCILEDATE DATE,
    TOTAL DOUBLE PRECISION,
    REC_BB DOUBLE PRECISION,
    REC_BB_DELTA DOUBLE PRECISION,
    REC_GL DOUBLE PRECISION,
    REC_GL_DELTA DOUBLE PRECISION)
AS
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.7.2005';
     EDATE = '31.12.2005';
  END
  APPLICATION = 'AP';
  /* ---------------------------------------------------------------- */
  /* CASH RECONCILIATION                                              */
  /* ---------------------------------------------------------------- */
  SOURCE = 'REC';
  FOR
    SELECT NUMBER, RECONCILEDATE, TOTAL
    FROM APCASH0
    WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
    AND STATUS = 'C'
    AND TOTAL <> 0
    PLAN (APCASH0 INDEX (APCASH0_IDX_RECONCILE))
    ORDER BY NUMBER
    INTO
      :NUMBER,
      :RECONCILEDATE,
      :TOTAL
  DO
  BEGIN
    SELECT SUM(DB) FROM GLJUR
    WHERE APPLICATION = :APPLICATION
    AND SOURCE = :SOURCE
    AND SOURCENUMBER = :NUMBER
    PLAN (GLJUR INDEX (GLJUR_IDX_SOURCE))
    INTO REC_GL;
    IF (REC_GL IS NULL) THEN REC_GL = 0;
    REC_GL_DELTA = REC_GL-TOTAL;

    SELECT SUM(FOREX_DB) FROM BBJUR
    WHERE APPLICATION = :APPLICATION
    AND SOURCE = :SOURCE
    AND SOURCENUMBER = :NUMBER
    PLAN (BBJUR INDEX (BBJUR_IDX_APPLICATION))
    INTO REC_BB;
    IF (REC_BB IS NULL) THEN REC_BB = 0;
    REC_BB_DELTA = REC_BB-TOTAL;

    IF ((REC_GL_DELTA NOT BETWEEN -0.1 AND 0.1) OR (REC_BB_DELTA NOT BETWEEN -0.1 AND 0.1)) THEN
       SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* DEPOSIT RECONCILIATION                                           */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DREC';
  FOR
    SELECT NUMBER, RECONCILEDATE, TOTAL
    FROM APDEPOS0
    WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
    AND STATUS = 'C'
    AND TOTAL <> 0
    PLAN (APDEPOS0 INDEX (APDEPOS0_IDX_RECONCILE))
    ORDER BY NUMBER
    INTO
      :NUMBER,
      :RECONCILEDATE,
      :TOTAL
  DO
  BEGIN
    SELECT SUM(DB) FROM GLJUR
    WHERE APPLICATION = :APPLICATION
    AND SOURCE = :SOURCE
    AND SOURCENUMBER = :NUMBER
    PLAN (GLJUR INDEX (GLJUR_IDX_SOURCE))
    INTO REC_GL;
    IF (REC_GL IS NULL) THEN REC_GL = 0;
    REC_GL_DELTA = REC_GL-TOTAL;

    SELECT SUM(FOREX_DB) FROM BBJUR
    WHERE APPLICATION = :APPLICATION
    AND SOURCE = :SOURCE
    AND SOURCENUMBER = :NUMBER
    PLAN (BBJUR INDEX (BBJUR_IDX_APPLICATION))
    INTO REC_BB;
    IF (REC_BB IS NULL) THEN REC_BB = 0;
    REC_BB_DELTA = REC_BB-TOTAL;

    IF ((REC_GL_DELTA NOT BETWEEN -0.1 AND 0.1) OR (REC_BB_DELTA NOT BETWEEN -0.1 AND 0.1)) THEN
       SUSPEND;
  END
END^


ALTER PROCEDURE AP_CASH_RECONCILE_RECREATE(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    SOURCENUMBER INTEGER,
    BANK VARCHAR(4),
    BBDATE DATE,
    DOCUMENT VARCHAR(20),
    BBCODE VARCHAR(4),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    FOREX_DB DOUBLE PRECISION,
    FOREX_CR DOUBLE PRECISION,
    REMARK VARCHAR(40),
    REF VARCHAR(20),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    CREATE_BY VARCHAR(8),
    CREATE_DATE DATE,
    NOTE VARCHAR(1000))
AS
DECLARE VARIABLE SUPPLIER VARCHAR(6);
DECLARE VARIABLE FLAG INTEGER;
BEGIN
  /* ---------------------------------------------------------------- */
  /* PSAVE                                                            */
  /*  0 : DISPLAY ONLY                                                */
  /*  1 : DELETE ALL & RECREATE                                       */
  /*  2 : DISPLAY DISCREPANCY ONLY                                    */
  /*  3 : CREATE DISCREPANCY                                          */
  /* ---------------------------------------------------------------- */
  
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.1.2005';
     EDATE = '31.12.2005';
     PSAVE = 2;
  END
  IF (PSAVE = 1) THEN
  BEGIN
     DELETE FROM BBJUR WHERE BBDATE BETWEEN :SDATE AND :EDATE
     AND APPLICATION = 'AP' AND SOURCE IN ('REC', 'DREC');
  END
  BBCODE = 'AP';
  APPLICATION = 'AP';
  /* ---------------------------------------------------------------- */
  /* CASH RECONCILIATION                                              */
  /* ---------------------------------------------------------------- */
  SOURCE = 'REC';
  FOREX_CR = 0;
  FOR
    SELECT NUMBER, BANK, RECONCILEDATE, DOCUMENT, SUPPLIER,
           FOREX_TOTAL,
           CHECK_NUMBER, NOTE,
           CURRENCY, EXCHANGE,
           EDITUSER, EDITDATE
    FROM APCASH0
    WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
    AND STATUS = 'C'
    PLAN (APCASH0 INDEX (APCASH0_IDX_RECONCILE))
    INTO
      :SOURCENUMBER, :BANK, :BBDATE, :DOCUMENT, :SUPPLIER,
      :FOREX_DB,
      :REF, NOTE,
      :CURRENCY,  :EXCHANGE,
      :CREATE_BY, :CREATE_DATE
  DO
  BEGIN
     /* ---------------------------------------------------------------- */
     /* PREVENT DATE WITH TIME                                           */
     /* ---------------------------------------------------------------- */
     EXECUTE PROCEDURE SP_DATEONLY(BBDATE) RETURNING_VALUES BBDATE;
     /* ---------------------------------------------------------------- */
     SELECT NAME FROM SYSSUPPLIER WHERE SUPPLIER = :SUPPLIER
     INTO :REMARK;

     SELECT GL_ACCOUNT_APPREPARE, GL_DEPT_APPREPARE, GL_COST_APPREPARE FROM SYSBANK
     WHERE BANK = :BANK
     INTO GL_ACCOUNT, GL_DEPT, GL_COST;
     /* ---------------------------------------------------------------- */
     /* CHECK EXISTS                                                     */
     /* ---------------------------------------------------------------- */
     IF (PSAVE >= 2) THEN
     BEGIN
        FLAG = 0;
        IF (EXISTS(SELECT * FROM BBJUR WHERE APPLICATION = :APPLICATION
                   AND SOURCE = :SOURCE AND SOURCENUMBER = :SOURCENUMBER
                   PLAN (BBJUR INDEX (BBJUR_IDX_APPLICATION)) )) THEN
        BEGIN
           FLAG = 1;
        END
     END
     /* ---------------------------------------------------------------- */
     IF (PSAVE = 0) THEN SUSPEND; /* DISPLAY ONLY*/
     ELSE
     IF ((PSAVE = 1) OR ((FLAG = 0) AND (PSAVE = 3))) THEN  /* SAVE ALL OR IF NOT EXISTS */
     BEGIN
        INSERT INTO BBJUR (NUMBER, BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
                        BBCODE, ACCOUNT, DEPT, COST,
                        FOREX_DB, FOREX_CR,
                        REMARK,  REF, NOTE,
                        CURRENCY, EXCHANGE,
                        APPLICATION, SOURCE, SOURCENUMBER, SOURCEID,
                        CREATE_BY, CREATE_DATE, EDIT_BY,EDIT_DATE)
        VALUES         (0, :BANK, :BBDATE, 0, 'O', :DOCUMENT,
                        :BBCODE, :GL_ACCOUNT, :GL_DEPT, :GL_COST,
                        :FOREX_DB, :FOREX_CR,
                        :REMARK, :REF, :NOTE,
                        :CURRENCY, :EXCHANGE,
                        :APPLICATION, :SOURCE, :SOURCENUMBER, 0,
                        :CREATE_BY, :CREATE_DATE, :CREATE_BY, :CREATE_DATE);
     END
     ELSE
     IF (PSAVE = 2) THEN /* CHECK FOR DISCREPANCEY */
     BEGIN
        IF (FLAG = 0) THEN SUSPEND;
     END
  END
  /* ---------------------------------------------------------------- */
  /* DEPOSIT RECONCILIATION                                           */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DREC';
  FOREX_CR = 0;
  FOR
    SELECT NUMBER, BANK, RECONCILEDATE, DOCUMENT, SUPPLIER,
           FOREX_TOTAL,
           CHECK_NUMBER, NOTE,
           CURRENCY, EXCHANGE,
           EDITUSER, EDITDATE
    FROM APDEPOS0
    WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
    AND STATUS = 'C'
    PLAN (APDEPOS0 INDEX (APDEPOS0_IDX_RECONCILE))
    INTO
      :SOURCENUMBER, :BANK, :BBDATE, :DOCUMENT, :SUPPLIER,
      :FOREX_DB,
      :REF, :NOTE,
      :CURRENCY,  :EXCHANGE,
      :CREATE_BY, :CREATE_DATE
  DO
  BEGIN
     /* ---------------------------------------------------------------- */
     /* PREVENT DATE WITH TIME                                           */
     /* ---------------------------------------------------------------- */
     EXECUTE PROCEDURE SP_DATEONLY(BBDATE) RETURNING_VALUES BBDATE;

     SELECT NAME FROM SYSSUPPLIER WHERE SUPPLIER = :SUPPLIER
     INTO :REMARK;

     SELECT GL_ACCOUNT_APPREPARE, GL_DEPT_APPREPARE, GL_COST_APPREPARE FROM SYSBANK
     WHERE BANK = :BANK
     INTO GL_ACCOUNT, GL_DEPT, GL_COST;
     /* ---------------------------------------------------------------- */
     /* CHECK EXISTS                                                     */
     /* ---------------------------------------------------------------- */
     IF (PSAVE >= 2) THEN
     BEGIN
        FLAG = 0;
        IF (EXISTS(SELECT * FROM BBJUR WHERE APPLICATION = :APPLICATION
                   AND SOURCE = :SOURCE AND SOURCENUMBER = :SOURCENUMBER
                   PLAN (BBJUR INDEX (BBJUR_IDX_APPLICATION)) )) THEN
        BEGIN
           FLAG = 1;
        END
     END
     /* ---------------------------------------------------------------- */
     IF (PSAVE = 0) THEN SUSPEND; /* DISPLAY ONLY*/
     ELSE
     IF ((PSAVE = 1) OR ((FLAG = 0) AND (PSAVE = 3))) THEN  /* SAVE ALL OR IF NOT EXISTS */
     BEGIN
        INSERT INTO BBJUR (NUMBER, BANK, BBDATE, BBLINE, STATUS, DOCUMENT,
                        BBCODE, ACCOUNT, DEPT, COST,
                        FOREX_DB, FOREX_CR,
                        REMARK,  REF, NOTE,
                        CURRENCY, EXCHANGE,
                        APPLICATION, SOURCE, SOURCENUMBER, SOURCEID,
                        CREATE_BY, CREATE_DATE, EDIT_BY,EDIT_DATE)
        VALUES         (0, :BANK, :BBDATE, 0, 'O', :DOCUMENT,
                        :BBCODE, :GL_ACCOUNT, :GL_DEPT, :GL_COST,
                        :FOREX_DB, :FOREX_CR,
                        :REMARK, :REF, :NOTE,
                        :CURRENCY, :EXCHANGE,
                        :APPLICATION, :SOURCE, :SOURCENUMBER, 0,
                        :CREATE_BY, :CREATE_DATE, :CREATE_BY, :CREATE_DATE);
     END
     ELSE
     IF (PSAVE = 2) THEN /* CHECK FOR DISCREPANCEY */
     BEGIN
        IF (FLAG = 0) THEN SUSPEND;
     END
  END
END^


ALTER PROCEDURE AP_CASH_RECONCILE_XX(
    PMONTH INTEGER,
    PYEAR INTEGER,
    FLAG_MTD_ONLY INTEGER,
    FLAG_OUTSTANDING_ONLY INTEGER)
RETURNS (
    DATAINFO VARCHAR(20),
    NUMBER INTEGER,
    STATUS CHAR(1),
    DOCUMENT VARCHAR(20),
    CHECK_NUMBER VARCHAR(20),
    OPENDATE DATE,
    RECONCILEDATE DATE,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    BANK VARCHAR(4),
    BANKNAME VARCHAR(40),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    TOTAL_FOREX DOUBLE PRECISION,
    PREV_ISSUED DOUBLE PRECISION,
    PREV_RECONCILED DOUBLE PRECISION,
    MTD_ISSUED DOUBLE PRECISION,
    MTD_RECONCILED DOUBLE PRECISION,
    TOTAL_OUTSTANDING DOUBLE PRECISION,
    GL DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE RYEAR INTEGER;
DECLARE VARIABLE RMONTH INTEGER;
BEGIN
  IF ((PYEAR IS NULL) OR (PMONTH = 0)) THEN
  BEGIN
     PYEAR = 2005;
     PMONTH = 7;
     FLAG_MTD_ONLY = 0;
     FLAG_OUTSTANDING_ONLY = 1;
  END
  EXECUTE PROCEDURE SP_ENCODEDATE(PYEAR, PMONTH, 1) RETURNING_VALUES SDATE;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES EDATE;
  
  IF (FLAG_MTD_ONLY = 0) THEN
     EXECUTE PROCEDURE SP_ENCODEDATE(1980, PMONTH, 1) RETURNING_VALUES SDATE;
  /* ---------------------------------------------------------------- */
  /* CASH PAYMENT                                                     */
  /* ---------------------------------------------------------------- */
  DATAINFO = 'Cash Payment';
  FOR
    SELECT C.NUMBER, C.STATUS,
           C.DOCUMENT, C.CHECK_NUMBER, C.OPENDATE, C.RECONCILEDATE,
           C.SUPPLIER, S.NAME,
           C.BANK, B.BANKNAME,
           C.TOTAL, C.CURRENCY, C.EXCHANGE, C.FOREX_TOTAL
    FROM APCASH0 C
    LEFT JOIN SYSBANK B ON B.BANK = C.BANK
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = C.SUPPLIER
    WHERE OPENDATE BETWEEN :SDATE AND :EDATE
    AND STATUS IN ('C','R','L')
    AND TOTAL <> 0
    ORDER BY C.BANK, C.OPENDATE, C.NUMBER
    INTO
      :NUMBER,
      :STATUS,
      :DOCUMENT,
      :CHECK_NUMBER,
      :OPENDATE,
      :RECONCILEDATE,
      :SUPPLIER,
      :NAME,
      :BANK,
      :BANKNAME,
      :TOTAL, :CURRENCY, :EXCHANGE, :TOTAL_FOREX
  DO
  BEGIN
    RYEAR  = EXTRACT(YEAR FROM RECONCILEDATE);
    RMONTH = EXTRACT(MONTH FROM RECONCILEDATE);
    
    IF (STATUS IN ('C','R','L')) THEN MTD_ISSUED = TOTAL;
    ELSE MTD_ISSUED = 0;
    
    IF (NOT((EXTRACT(YEAR FROM OPENDATE) = PYEAR) AND (EXTRACT(MONTH FROM OPENDATE) = PMONTH))) THEN
    BEGIN
       PREV_ISSUED = MTD_ISSUED;
       MTD_ISSUED = 0;
    END
    ELSE PREV_ISSUED = 0;

    MTD_RECONCILED = 0;
    PREV_RECONCILED = 0;
    IF (STATUS = 'C') THEN
    BEGIN
      IF ((RYEAR = PYEAR) AND (RMONTH = PMONTH)) THEN
      BEGIN
        MTD_RECONCILED = TOTAL;
        PREV_RECONCILED = 0;
      END
      ELSE
      IF (RYEAR*12+RMONTH < PYEAR*12+PMONTH)  THEN
      BEGIN
        MTD_RECONCILED = 0;
        PREV_RECONCILED = TOTAL;
      END
    END
        
    SELECT SUM(DB-CR) FROM GLJUR
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND APPLICATION = 'AP'
    AND SOURCE = 'CASH'
    AND SOURCENUMBER = :NUMBER
    INTO GL;

    TOTAL_OUTSTANDING = (MTD_ISSUED + PREV_ISSUED) - (MTD_RECONCILED+PREV_RECONCILED);
    IF (FLAG_OUTSTANDING_ONLY = 1) THEN
    BEGIN
       IF (TOTAL_OUTSTANDING <> 0) THEN
          SUSPEND;
    END
    ELSE SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* DEPOSIT                                                          */
  /* ---------------------------------------------------------------- */
  DATAINFO = 'Deposit';
  FOR
    SELECT C.NUMBER, C.STATUS,
           C.DOCUMENT, C.CHECK_NUMBER, C.OPENDATE, C.RECONCILEDATE,
           C.SUPPLIER, S.NAME,
           C.BANK, B.BANKNAME,
           C.TOTAL, C.CURRENCY, C.EXCHANGE, C.FOREX_TOTAL
    FROM APDEPOS0 C
    LEFT JOIN SYSBANK B ON B.BANK = C.BANK
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = C.SUPPLIER
    WHERE OPENDATE BETWEEN :SDATE AND :EDATE
    AND STATUS IN ('C','R','L')
    AND TOTAL <> 0
    ORDER BY C.BANK, C.OPENDATE, C.NUMBER
    INTO
      :NUMBER,
      :STATUS,
      :DOCUMENT,
      :CHECK_NUMBER,
      :OPENDATE,
      :RECONCILEDATE,
      :SUPPLIER,
      :NAME,
      :BANK,
      :BANKNAME,
      :TOTAL, :CURRENCY, :EXCHANGE, :TOTAL_FOREX
  DO
  BEGIN

    RYEAR  = EXTRACT(YEAR FROM RECONCILEDATE);
    RMONTH = EXTRACT(MONTH FROM RECONCILEDATE);

    IF (STATUS IN ('C','R','L')) THEN MTD_ISSUED = TOTAL;
    ELSE MTD_ISSUED = 0;

    MTD_RECONCILED = 0;
    PREV_RECONCILED = 0;
    IF (STATUS = 'C') THEN
    BEGIN
      IF ((RYEAR = PYEAR) AND (RMONTH = PMONTH)) THEN
      BEGIN
        MTD_RECONCILED = TOTAL;
        PREV_RECONCILED = 0;
      END
      ELSE
      IF (RYEAR*12+RMONTH < PYEAR*12+PMONTH)  THEN
      BEGIN
        MTD_RECONCILED = 0;
        PREV_RECONCILED = TOTAL;
      END
    END

    MTD_RECONCILED = 0;
    IF ((STATUS = 'C') AND (RYEAR = PYEAR) AND (RMONTH = PMONTH)) THEN
        MTD_RECONCILED = TOTAL;

    IF (NOT((EXTRACT(YEAR FROM OPENDATE) = PYEAR) AND (EXTRACT(MONTH FROM OPENDATE) = PMONTH))) THEN
    BEGIN
       PREV_RECONCILED = MTD_RECONCILED;
       MTD_RECONCILED = 0;
    END
    ELSE PREV_RECONCILED = 0;

    TOTAL_OUTSTANDING = (MTD_ISSUED + PREV_ISSUED) - (MTD_RECONCILED+PREV_RECONCILED);
    IF (FLAG_OUTSTANDING_ONLY = 1) THEN
    BEGIN
       IF (TOTAL_OUTSTANDING <> 0) THEN
          SUSPEND;
    END
    ELSE SUSPEND;
  END
END^


ALTER PROCEDURE AP_CHECK_PAYMENTDATE(
    PSAVE INTEGER)
RETURNS (
    NUMBER INTEGER,
    OPENDATE DATE,
    PAYMENT_NUMBER INTEGER,
    PAYMENT_DATE DATE,
    PAYMENT_TOTAL DOUBLE PRECISION)
AS
BEGIN
  FOR
    SELECT NUMBER, OPENDATE FROM APVCH
    INTO
      :NUMBER,
      :OPENDATE
  DO
  BEGIN
    FOR SELECT D.NUMBER, H.DUEDATE, D.TOTAL FROM APCASH1 D
        LEFT JOIN APCASH0 H ON H.NUMBER = D.NUMBER
        WHERE D.VOUCHERNO = :NUMBER
    INTO PAYMENT_NUMBER, PAYMENT_DATE, PAYMENT_TOTAL
    DO
    BEGIN
       IF (PAYMENT_DATE < OPENDATE) THEN
       BEGIN
          IF (PSAVE = 1) THEN
          BEGIN
             UPDATE APCASH0 SET DUEDATE = :OPENDATE
             WHERE NUMBER = :PAYMENT_NUMBER;
          END
          ELSE
             SUSPEND;
       END
    END
  END
END^


ALTER PROCEDURE AP_CHECK_RECEIVING(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER)
RETURNS (
    NUMBER INTEGER,
    OPENDATE DATE,
    TOTAL DOUBLE PRECISION,
    FOREX_TOTAL DOUBLE PRECISION,
    STATUS CHAR(1),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    APNUMBER INTEGER,
    AP_VOUCHERNO INTEGER,
    AP_COUNTER INTEGER,
    AP_DATE DATE,
    AP_TOTAL DOUBLE PRECISION,
    AP_FOREX_TOTAL DOUBLE PRECISION,
    AP_STATUS CHAR(1),
    AP_EXCHANGE DOUBLE PRECISION,
    DELTA_TOTAL DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION,
    REMARK VARCHAR(60))
AS
DECLARE VARIABLE XVOUCHERNO INTEGER;
DECLARE VARIABLE XTOTAL DOUBLE PRECISION;
DECLARE VARIABLE XFOREX_TOTAL DOUBLE PRECISION;
DECLARE VARIABLE XCURRENCY VARCHAR(4);
DECLARE VARIABLE XEXCHANGE DOUBLE PRECISION;
DECLARE VARIABLE XTAX DOUBLE PRECISION;
DECLARE VARIABLE XFOREX_TAX DOUBLE PRECISION;
DECLARE VARIABLE XREF VARCHAR(20);
DECLARE VARIABLE SUPPLIER VARCHAR(6);
DECLARE VARIABLE AP_SUPPLIER VARCHAR(6);
DECLARE VARIABLE AP_TOTALDUE DOUBLE PRECISION;
DECLARE VARIABLE FLAG_DELETED INTEGER;
DECLARE VARIABLE SRECV_NUMBER INTEGER;
DECLARE VARIABLE ERECV_NUMBER INTEGER;

DECLARE VARIABLE XCOUNTER INTEGER;
DECLARE VARIABLE SVCH_NUMBER INTEGER;
DECLARE VARIABLE EVCH_NUMBER INTEGER;
DECLARE VARIABLE X INTEGER;
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.9.2006';
     EDATE = '30.9.2006';
     PSAVE = 0;
  END
  IF (PSAVE IS NULL) THEN PSAVE = 0;
  /* -------------------------------------------------------------------- */
  /* 8 MARET 2010                                                         */
  /* -------------------------------------------------------------------- */
  SRECV_NUMBER = 0;
  ERECV_NUMBER = 9999999;
  SVCH_NUMBER  = 0;
  EVCH_NUMBER  = 9999999;
  IF (PSAVE NOT IN (0,1)) THEN
  BEGIN
     IF (PSAVE > 0) THEN
     BEGIN
        SRECV_NUMBER = PSAVE;
        ERECV_NUMBER = PSAVE;
     END
     ELSE IF (PSAVE < 0) THEN
     BEGIN
       SVCH_NUMBER = -PSAVE;
       EVCH_NUMBER = -PSAVE;
     END
     PSAVE = 1;
  END

  /* -------------------------------------------------------------------- */
  BALANCE = 0;
  FOR
    SELECT H.NUMBER, H.OPENDATE, H.APNUMBER, H.STATUS, H.FOREX_TOTAL, H.TOTAL,  /* 14-OCT-2008 ADA EXCHANGE */
           H.EXCHANGE, H.CURRENCY /* 10/12/2011 */
    FROM INVRECV0 H
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = H.SUPPLIER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE
    AND H.STATUS IN ('R', 'C')
    AND S.SUPLTYPE <> 'CASH' /* 20 feb 2008, BUKAN CASH */
    AND H.NUMBER BETWEEN :SRECV_NUMBER AND :ERECV_NUMBER
/*     PLAN (INVRECV0 INDEX (INVRECV0_IDX_OPENDATE)) For FB.2.x 31-Aug-2011 */
    ORDER BY H.NUMBER, H.OPENDATE, H.APNUMBER, H.STATUS
    INTO :NUMBER, :OPENDATE, :APNUMBER, STATUS, XFOREX_TOTAL, XTOTAL,  /* FOREX_TOTAL, 20 APRIL 2010 */
         EXCHANGE, CURRENCY
  DO
  BEGIN
    REMARK = '';
    
    /* ---------------------------------------------------------------- */
    /* CALCULATE DETAIL RECEIVING                                       */
    /* ---------------------------------------------------------------- */
    SELECT SUM(D.CALC_COST) FROM INVRECV1 D  /* 14-OCT-2008 ADA EXCHANGE */
    WHERE D.NUMBER = :NUMBER
    INTO TOTAL;
    IF (TOTAL IS NULL) THEN TOTAL = 0;
    FOREX_TOTAL = TOTAL * EXCHANGE; /* 10/12/2011 */
    IF (NOT (XTOTAL - TOTAL BETWEEN -0.0001 AND 0.0001)) THEN /* 10/12/2011 tadinya 0.01*/
    BEGIN
       /*SUSPEND; */
    END


    /* ---------------------------------------------------------------- */
    /* CALCULATE NUMBER OF AP VOUCHER                                   */
    /* ---------------------------------------------------------------- */
    SELECT COUNT(*) FROM APVCH WHERE  SOURCE = 'R' AND RECEIVINGNO = :NUMBER
/*     PLAN (APVCH INDEX (APVCH_IDX_SOURCE_NUMBER)) For FB.2.x 31-Aug-2011 */
    INTO AP_COUNTER;



    /* ---------------------------------------------------------------- */
    /* JIKA ADA 1 VOUCHER DARI RECEIVING TSB                            */
    /* ---------------------------------------------------------------- */
    IF (AP_COUNTER = 1) THEN
    BEGIN
      SELECT NUMBER, STATUS, TOTAL, FOREX_TOTAL, OPENDATE, EXCHANGE FROM APVCH
      WHERE SOURCE = 'R' AND RECEIVINGNO = :NUMBER
/*       PLAN (APVCH INDEX (APVCH_IDX_SOURCE_NUMBER)) For FB.2.x 31-Aug-2011 */
      INTO AP_VOUCHERNO, AP_STATUS, AP_TOTAL, AP_FOREX_TOTAL, AP_DATE,
           AP_EXCHANGE; /* 10/12/2011 */
      /* ----------------------------------------------------------- */
      /* NOMOR APVCH NULL                                            */
      /* 1 JULY 2009                                                 */
      /* ----------------------------------------------------------- */
      IF (AP_VOUCHERNO IS NULL) THEN
      BEGIN
         IF (PSAVE = 0) THEN
         BEGIN
            REMARK = 'AP Voucher Number is null (APVCH)';
            SUSPEND;
         END
         ELSE
         BEGIN
            SELECT MAX(NUMBER) FROM APVCH WHERE NUMBER IS NOT NULL
            INTO AP_VOUCHERNO;
            IF (AP_VOUCHERNO IS NULL) THEN AP_VOUCHERNO = 0;
            AP_VOUCHERNO = AP_VOUCHERNO + 1;
            UPDATE APVCH SET NUMBER = :AP_VOUCHERNO
            WHERE SOURCE = 'R' AND RECEIVINGNO = :NUMBER;

            IF (SRECV_NUMBER = ERECV_NUMBER) THEN EXIT; /* 24 MARCH 2010 */
         END
      END

      IF ((AP_VOUCHERNO <> 0) AND (APNUMBER = 0)) THEN
      BEGIN
         IF (PSAVE = 0) THEN
         BEGIN
            REMARK = 'Receiving''s AP Voucher Number is ZERO (INVRECV0)';
            SUSPEND;
         END
         ELSE
         BEGIN
            UPDATE INVRECV0 SET APNUMBER = :AP_VOUCHERNO
            WHERE NUMBER = :NUMBER;
            IF (SRECV_NUMBER = ERECV_NUMBER) THEN EXIT; /* 24 MARCH 2010 */
         END
      END
      /* ---------------------------------------------------------------- */
      /* 21 NOVEMBER 2006, ANTARA OPENDATE & TOTAL DIPISAH                */
      /* ---------------------------------------------------------------- */
      IF (OPENDATE <> AP_DATE) THEN
      BEGIN
         DELTA_TOTAL = AP_TOTAL - TOTAL;
         BALANCE = BALANCE + DELTA_TOTAL;
         IF (PSAVE = 0) THEN
         BEGIN
            REMARK = 'Receiving: Open Date discrepancy';
            SUSPEND;
         END
         ELSE
         BEGIN
            UPDATE APVCH SET OPENDATE = :OPENDATE
            WHERE NUMBER = :AP_VOUCHERNO;
            IF (SRECV_NUMBER = ERECV_NUMBER) THEN EXIT; /* 24 MARCH 2010 */
         END
      END
      ELSE
      IF ((AP_TOTAL - TOTAL NOT BETWEEN -0.0001 AND 0.0001) OR  /* tadi nya 0.01*/
          (AP_FOREX_TOTAL - FOREX_TOTAL NOT BETWEEN -0.0001 AND 0.0001)) THEN /* 10/12/2011 tadinya 0.01*/
      BEGIN
         DELTA_TOTAL = AP_TOTAL - TOTAL;
         BALANCE = BALANCE + DELTA_TOTAL;
         IF (PSAVE = 0) THEN
         BEGIN
            IF (EXCHANGE <> AP_EXCHANGE) THEN  /* 10/12/2011 */
               REMARK = 'Exchange Discrepacy'; /* 10/12/2011 */
            ELSE
               REMARK = 'Receiving: Total Discrepancy1';
            SUSPEND;
         END
         ELSE
         BEGIN
            UPDATE APVCH SET OPENDATE = :OPENDATE, TOTAL = :TOTAL, FOREX_TOTAL = :FOREX_TOTAL,
                   EXCHANGE = :EXCHANGE /* 10/12/2011 */
            WHERE NUMBER = :AP_VOUCHERNO;
            IF (SRECV_NUMBER = ERECV_NUMBER) THEN EXIT; /* 24 MARCH 2010 */
         END
      END
      /* ---------------------------------------------------------------- */
      /* END OF 21 NOVEMBER 2006, ANTARA OPENDATE & TOTAL DIPISAH         */
      /* ---------------------------------------------------------------- */
    END
    /* ---------------------------------------------------------------- */
    /* AP VOUCHER DI RELEASE LEBIH DARI SATU KALI                       */
    /* ---------------------------------------------------------------- */
    ELSE IF (AP_COUNTER > 1) THEN
    BEGIN
      SELECT SUM(FOREX_TOTAL), SUM(TOTAL) FROM APVCH WHERE SOURCE = 'R' AND RECEIVINGNO = :NUMBER
/*       PLAN (APVCH INDEX (APVCH_IDX_SOURCE_NUMBER)) For FB.2.x 31-Aug-2011 */
      INTO AP_TOTAL, AP_FOREX_TOTAL;
      AP_VOUCHERNO = 0;
      AP_DATE = NULL;
      DELTA_TOTAL = AP_TOTAL - TOTAL;
      BALANCE = BALANCE + DELTA_TOTAL;
      IF (PSAVE = 0) THEN
      BEGIN
         REMARK = 'Receiving: Export to AP '|| AP_COUNTER || ' times';
         SUSPEND;
      END
      ELSE
      BEGIN
         FLAG_DELETED = 0;
         FOR SELECT NUMBER FROM APVCH
             WHERE SOURCE = 'R' AND RECEIVINGNO = :NUMBER AND PAID = 0
             AND STATUS = 'O'
/*              PLAN (APVCH INDEX (APVCH_IDX_SOURCE_NUMBER)) For FB.2.x 31-Aug-2011 */
         INTO AP_VOUCHERNO
         DO
         BEGIN
            IF (FLAG_DELETED = 0) THEN
            BEGIN
               DELETE FROM APVCH WHERE NUMBER = :AP_VOUCHERNO;
               FLAG_DELETED = 1;
            END
         END
         IF (SRECV_NUMBER = ERECV_NUMBER) THEN EXIT; /* 24 MARCH 2010 */
      END
    END
    ELSE
    /* ---------------------------------------------------------------- */
    /* AP VOUCHER TIDAK TER-TRANSFER                                    */
    /* ---------------------------------------------------------------- */
    BEGIN
       AP_DATE = NULL;
       AP_TOTAL = 0;
       AP_VOUCHERNO = 0;
       AP_TOTAL = 0;
       AP_STATUS = '';
       DELTA_TOTAL = -TOTAL;
       BALANCE = BALANCE + DELTA_TOTAL;
       IF (PSAVE = 0) THEN
       BEGIN
         REMARK = 'Receiving: DID NOT Export to AP';
         SUSPEND;
       END
       ELSE
       BEGIN
         SELECT TOTAL, FOREX_TOTAL, CURRENCY, EXCHANGE, TAX, FOREX_TAX,
                REFERENCE, SUPPLIER
         FROM INVRECV0 WHERE NUMBER = :NUMBER
         INTO XTOTAL, XFOREX_TOTAL, XCURRENCY, XEXCHANGE, XTAX, XFOREX_TAX,
              XREF, :SUPPLIER;

         XVOUCHERNO = 0; /* 17 November 2009 */

         INSERT INTO apvch
            (number, document, opendate, duedate, supplier, source, receivingno,
             forex_total, total,  adjust, paidgiro, paid, paidprepare, Dept, currency,
             exchange, tax, forex_tax)
          VALUES
            (:XVOUCHERNO, :XREF, :OPENDATE, :OPENDATE, :SUPPLIER, 'R', :NUMBER,
             :xtotal, :xforex_total, 0,0,0, 0, '', :xcurrency,
             :xexchange, :xtax, :xforex_tax);
         /* -------------------------------------------------------------------- */
         /* Posting one by one, 23 maret 2010                                    */
         /* -------------------------------------------------------------------- */
         IF (SRECV_NUMBER = ERECV_NUMBER) THEN EXIT;
         /* -------------------------------------------------------------------- */
       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* HITUNG APVCH DARI VOUCHER AP APAKAH ADA RECEIVING TSB            */
  /* ---------------------------------------------------------------- */
  AP_COUNTER = 1;
  NUMBER = 0;
  OPENDATE = NULL;
  TOTAL = 0;
  STATUS = '';
  APNUMBER = 0;

  FOR
    SELECT V.NUMBER, V.STATUS, V.OPENDATE, V.RECEIVINGNO, TOTAL, TOTALDUE, SUPPLIER
     FROM APVCH V
     WHERE V.OPENDATE BETWEEN :SDATE AND :EDATE
     AND SOURCE = 'R' AND RECEIVINGNO <> 0
     AND V.NUMBER BETWEEN :SVCH_NUMBER AND :EVCH_NUMBER
     INTO AP_VOUCHERNO, AP_STATUS, AP_DATE, NUMBER, AP_TOTAL, AP_TOTALDUE, AP_SUPPLIER
  DO
  BEGIN
    IF (NOT EXISTS(SELECT * FROM INVRECV0 WHERE NUMBER = :NUMBER)) THEN
    BEGIN
      IF (PSAVE= 0) THEN
      BEGIN
         REMARK = 'Voucher exists but Receiving '|| NUMBER || ' not exist';
         DELTA_TOTAL = AP_TOTAL;
         BALANCE = BALANCE + DELTA_TOTAL;
         SUSPEND;
      END
      ELSE
      BEGIN
        IF (EXISTS(SELECT * FROM APVCH WHERE NUMBER = :AP_VOUCHERNO AND STATUS  = 'O')) THEN
        BEGIN
           DELETE FROM APVCH WHERE NUMBER = :AP_VOUCHERNO;
           IF (AP_VOUCHERNO = SVCH_NUMBER) THEN EXIT; /* 24 MARCH 2010 */
        END
      END
    END
    ELSE IF (NOT(EXISTS(SELECT * FROM INVRECV0 WHERE NUMBER = :NUMBER AND STATUS IN ('R', 'C')))) THEN
    BEGIN
      SELECT STATUS FROM INVRECV0 WHERE NUMBER = :NUMBER INTO STATUS;
      IF (PSAVE= 0) THEN
      BEGIN
         REMARK = 'Voucher exists but Receiving '|| NUMBER || ' NOT Released';
         DELTA_TOTAL = AP_TOTAL;
         BALANCE = BALANCE + DELTA_TOTAL;
         SUSPEND;




      END
      ELSE
      BEGIN
        IF (EXISTS(SELECT * FROM APVCH WHERE NUMBER = :AP_VOUCHERNO AND STATUS  = 'O')) THEN
        BEGIN
           DELETE FROM APVCH WHERE NUMBER = :AP_VOUCHERNO;
           IF (AP_VOUCHERNO = SVCH_NUMBER) THEN EXIT; /* 24 MARCH 2010 */
        END
      END
    END
    ELSE
    BEGIN /* 21 NOVEMBER 2006 */
       SELECT H.OPENDATE, H.STATUS, H.TOTAL, SUPPLIER FROM INVRECV0 H
       WHERE H.NUMBER = :NUMBER
       INTO :OPENDATE, STATUS, XTOTAL, SUPPLIER;

       IF (OPENDATE <> AP_DATE) THEN
       BEGIN
          DELTA_TOTAL = AP_TOTAL - TOTAL;
          BALANCE = BALANCE + DELTA_TOTAL;
          IF (PSAVE = 0) THEN
          BEGIN
             REMARK = 'Receiving: Open Date discrepancy';
             SUSPEND;
          END
          ELSE
          BEGIN
             UPDATE APVCH SET OPENDATE = :OPENDATE
             WHERE NUMBER = :AP_VOUCHERNO;
             IF (AP_VOUCHERNO = SVCH_NUMBER) THEN EXIT; /* 24 MARCH 2010 */
          END
       END
       IF (AP_SUPPLIER <> SUPPLIER) THEN
       BEGIN
          DELTA_TOTAL = AP_TOTAL - TOTAL;
          BALANCE = BALANCE + DELTA_TOTAL;
          IF (PSAVE = 0) THEN
          BEGIN
             REMARK = 'Receiving: Supplier discrepancy';
             SUSPEND;
          END
          ELSE
          BEGIN
             UPDATE APVCH SET SUPPLIER = :SUPPLIER WHERE NUMBER = :AP_VOUCHERNO;
             IF (AP_VOUCHERNO = SVCH_NUMBER) THEN EXIT; /* 24 MARCH 2010 */
          END
       END

    END  /* END 21 NOVEMBER 2006 */
  END

END^


ALTER PROCEDURE AP_CHECK_SUPPLIER
RETURNS (
    ADJ_NUMBER INTEGER,
    VOUCHERNO INTEGER,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    OPENDATE DATE,
    STATUS CHAR(1),
    ADJ_SUPPLIER VARCHAR(6),
    ADJ_NAME VARCHAR(40),
    CASH_NUMBER INTEGER,
    CASH_SUPPLIER VARCHAR(6),
    CASH_NAME VARCHAR(40))
AS
BEGIN
  FOR
    SELECT V.NUMBER, V.SUPPLIER, S.NAME, V.OPENDATE, V.STATUS
    FROM APVCH V
    LEFT JOIN SYSSUPPLIER S ON V.SUPPLIER=S.SUPPLIER
    ORDER BY V.NUMBER
    INTO
      :VOUCHERNO,
      :SUPPLIER,
      :NAME,
      :OPENDATE,
      :STATUS
  DO
  BEGIN
    CASH_NUMBER = 0;
    CASH_SUPPLIER = '';
    CASH_NAME = '';

    IF (EXISTS(SELECT * FROM APADJ WHERE VOUCHERNO = :VOUCHERNO AND SUPPLIER <> :SUPPLIER)) THEN
    BEGIN
       FOR SELECT A.NUMBER, A.SUPPLIER, S.NAME FROM APADJ A
          LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = A.SUPPLIER
          WHERE VOUCHERNO = :VOUCHERNO
          INTO ADJ_NUMBER, ADJ_SUPPLIER, ADJ_NAME
       DO
       BEGIN
          SUSPEND;
       END
    END
    ADJ_SUPPLIER = '';
    ADJ_NAME = '';
    ADJ_NUMBER = 0;
    IF (EXISTS(SELECT * FROM APCASH1 WHERE VOUCHERNO = :VOUCHERNO AND SUPPLIER <> :SUPPLIER)) THEN
    BEGIN
       FOR SELECT V.NUMBER, V.SUPPLIER, S.NAME FROM APCASH1 V
          LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = V.SUPPLIER
          WHERE NUMBER = :VOUCHERNO
          INTO CASH_NUMBER, CASH_SUPPLIER, CASH_NAME
       DO
       BEGIN
          SUSPEND;
       END
    END
  END
END^


ALTER PROCEDURE AP_CHECK_SUPPLIER_CODE(
    PSAVE INTEGER)
RETURNS (
    INFO VARCHAR(30),
    VOUCHERNO INTEGER,
    CASH_NUMBER INTEGER,
    SUPPLIER_VOUCHER VARCHAR(6),
    SUPPLIER_VOUCHER_NAME VARCHAR(40),
    SUPPLIER_CASH_DETAIL VARCHAR(6),
    SUPPLIER_CASH_DETAIL_NAME VARCHAR(40),
    SUPPLIER_CASH_HEADER VARCHAR(6),
    SUPPLIER_CASH_HEADER_NAME VARCHAR(40),
    OPENDATE DATE,
    DUEDATE DATE,
    TOTAL DOUBLE PRECISION)
AS
DECLARE VARIABLE X INTEGER;
BEGIN
  IF (PSAVE IS NULL) THEN PSAVE = 0;
  INFO = 'Supplier Discrepancy';
  FOR
    SELECT V.SUPPLIER SUPPLIER_VOUCHER,
           C.SUPPLIER SUPPLIER_CASH_DETAIL,
           H.SUPPLIER SUPPLIER_CASH_HEADER,
           C.VOUCHERNO, C.NUMBER,
           H.OPENDATE, H.DUEDATE,
           C.TOTAL
    FROM APCASH1 C
    LEFT JOIN APVCH V ON V.NUMBER = C.VOUCHERNO
    LEFT JOIN APCASH0 H ON H.NUMBER = C.NUMBER
    WHERE C.SUPPLIER <> V.SUPPLIER
    OR C.SUPPLIER <> H.SUPPLIER
    OR H.SUPPLIER <> V.SUPPLIER

    INTO
      :SUPPLIER_VOUCHER,
      :SUPPLIER_CASH_DETAIL,
      :SUPPLIER_CASH_HEADER,
      :VOUCHERNO,
      :CASH_NUMBER,
      :OPENDATE,
      :DUEDATE,
      :TOTAL
  DO
  BEGIN
    SUPPLIER_CASH_HEADER_NAME = '?';
    SUPPLIER_CASH_DETAIL_NAME = '?';
    SUPPLIER_VOUCHER_NAME     = '?';
    
    SELECT NAME FROM SYSSUPPLIER WHERE SUPPLIER = :SUPPLIER_CASH_HEADER
    INTO SUPPLIER_CASH_HEADER_NAME;
    
    SELECT NAME FROM SYSSUPPLIER WHERE SUPPLIER = :SUPPLIER_CASH_DETAIL
    INTO SUPPLIER_CASH_DETAIL_NAME;
    
    SELECT NAME FROM SYSSUPPLIER WHERE SUPPLIER = :SUPPLIER_VOUCHER
    INTO SUPPLIER_VOUCHER_NAME;


    IF (PSAVE = 0) THEN SUSPEND;
    ELSE
    IF (PSAVE = 1) THEN
    BEGIN
      IF (EXISTS(SELECT * FROM SYSSUPPLIER WHERE SUPPLIER = :SUPPLIER_VOUCHER)) THEN
      BEGIN
         UPDATE APCASH0 SET SUPPLIER = :SUPPLIER_VOUCHER
         WHERE NUMBER = :CASH_NUMBER;

         UPDATE APCASH1 SET SUPPLIER = :SUPPLIER_VOUCHER
         WHERE NUMBER = :CASH_NUMBER;
      END
      ELSE
      IF (EXISTS(SELECT * FROM SYSSUPPLIER WHERE SUPPLIER = :SUPPLIER_CASH_HEADER)) THEN
      BEGIN
         UPDATE APVCH SET SUPPLIER = :SUPPLIER_CASH_HEADER
         WHERE NUMBER = :VOUCHERNO AND SUPPLIER <> :SUPPLIER_CASH_HEADER;
      END
    END
    IF (PSAVE = 2) THEN
    BEGIN
      IF (EXISTS(SELECT * FROM SYSSUPPLIER WHERE SUPPLIER = :SUPPLIER_CASH_HEADER)) THEN
      BEGIN
         UPDATE APVCH SET SUPPLIER = :SUPPLIER_CASH_HEADER
         WHERE NUMBER = :VOUCHERNO;
         
         UPDATE APCASH1 SET SUPPLIER = :SUPPLIER_CASH_HEADER
         WHERE NUMBER = :CASH_NUMBER;
      END
      ELSE
      IF (EXISTS(SELECT * FROM SYSSUPPLIER WHERE SUPPLIER = :SUPPLIER_VOUCHER)) THEN
      BEGIN
         UPDATE APCASH0 SET SUPPLIER = :SUPPLIER_VOUCHER
         WHERE NUMBER = :CASH_NUMBER;

         UPDATE APCASH1 SET SUPPLIER = :SUPPLIER_VOUCHER
         WHERE NUMBER = :CASH_NUMBER;
      END
    END
  END
  EXIT;
  /* ---------------------------------------------------------------- */
  /* DELETE ORPHAN CASH PAYMENT                                       */
  /* ---------------------------------------------------------------- */
  INFO = 'Orphan Cash Receipt';
  IF (PSAVE=0) THEN
  BEGIN
    FOR
      SELECT V.SUPPLIER SUPPLIER_VOUCHER,
             C.SUPPLIER SUPPLIER_CASH_DETAIL,
             H.SUPPLIER SUPPLIER_CASH_HEADER,
             C.VOUCHERNO, C.NUMBER,
             H.OPENDATE, H.DUEDATE,
             C.TOTAL
      FROM APCASH1 C
      LEFT JOIN APVCH V ON V.NUMBER = C.VOUCHERNO
      LEFT JOIN APCASH0 H ON H.NUMBER = C.NUMBER
      WHERE NOT (EXISTS(SELECT * FROM APVCH V WHERE V.NUMBER = C.VOUCHERNO))
    INTO
      :SUPPLIER_VOUCHER,
      :SUPPLIER_CASH_DETAIL,
      :SUPPLIER_CASH_HEADER,
      :VOUCHERNO,
      :CASH_NUMBER,
      :OPENDATE,
      :DUEDATE,
      :TOTAL
    DO
      SUSPEND;
  END
  IF (PSAVE=1) THEN
  BEGIN
      DELETE FROM APCASH1 D
      WHERE NOT (EXISTS(SELECT * FROM APVCH V WHERE V.NUMBER = D.VOUCHERNO));
  END
END^


ALTER PROCEDURE AP_COMPARE_MUT_AGE(
    REFDATE DATE)
RETURNS (
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    MUT_ENDING DOUBLE PRECISION,
    AGE_ENDING DOUBLE PRECISION,
    DELTA DOUBLE PRECISION)
AS
BEGIN
  IF (REFDATE IS NULL) THEN
  BEGIN
     SELECT APSYSDATE FROM SYSPARAM WHERE ID = 1 INTO REFDATE;
     EXECUTE PROCEDURE SP_BEGINOFMONTH(REFDATE) RETURNING_VALUES (REFDATE);
     REFDATE = REFDATE - 1;
  END
  FOR
    SELECT SUPPLIER, NAME, ENDING FROM AP_MUTATION_OLD('','ZZZZ',:REFDATE)
    INTO
      :SUPPLIER,
      :NAME,
      :MUT_ENDING
  DO
  BEGIN
    AGE_ENDING = NULL;
    SELECT TOTAL FROM AP_AGING_OLD(:SUPPLIER, :SUPPLIER, :REFDATE, 0, 'All')
    INTO AGE_ENDING;
    IF (AGE_ENDING IS NULL) THEN AGE_ENDING = 0;
    DELTA = MUT_ENDING - AGE_ENDING;
    IF (DELTA NOT BETWEEN -0.5 AND 0.5) THEN SUSPEND;
  END
END^


ALTER PROCEDURE AP_DEPOSIT_AGING(
    SDATE DATE)
RETURNS (
    REFDATE DATE,
    PYEAR INTEGER,
    PMONTH INTEGER,
    NUMBER INTEGER,
    OPENDATE DATE,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    TOTAL DOUBLE PRECISION,
    APPLIED DOUBLE PRECISION,
    ADJUSTMENT DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION,
    AGE INTEGER,
    CURR DOUBLE PRECISION,
    OVER30 DOUBLE PRECISION,
    OVER60 DOUBLE PRECISION,
    OVER90 DOUBLE PRECISION,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40))
AS
BEGIN
  IF (SDATE IS NULL) THEN
      SELECT APSYSDATE FROM SYSPARAM INTO :SDATE;
  REFDATE = SDATE;
  PYEAR = EXTRACT(YEAR FROM REFDATE);
  PMONTH = EXTRACT(MONTH FROM REFDATE);
  FOR
    SELECT D.NUMBER, D.OPENDATE,  D.SUPPLIER, S.NAME, D.TOTAL,
           T.DEPOS_GLACCOUNT, T.DEPOS_GLDEPT, T.DEPOS_GLCOST,
           A.NAME
    FROM APDEPOS0 D
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = D.SUPPLIER
    LEFT JOIN SYSSUPPLIERTYPE T ON T.SUPPLIERTYPE = S.SUPLTYPE
    LEFT JOIN GLCOA A ON A.ACCOUNT = T.DEPOS_GLACCOUNT
    WHERE D.OPENDATE <= :SDATE
    INTO :NUMBER, OPENDATE, :SUPPLIER, :NAME, :TOTAL,
         GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME
  DO
  BEGIN
    SELECT SUM(TOTAL) FROM APDEPOS1
    WHERE NUMBER = :NUMBER
    AND APPLIEDDATE <= :SDATE
    INTO APPLIED;
    IF (APPLIED IS NULL) THEN APPLIED = 0;
    /* -------------------------------------------------------------------- */
    /* 9/12/2011                                                            */
    /* ADJUSTMENT                                                           */
    /* -------------------------------------------------------------------- */
    SELECT SUM(DB-CR) FROM APDEPOS0_JUR
    WHERE DEPOSITNO = :NUMBER
    AND OPENDATE <= :SDATE
    INTO ADJUSTMENT;
    IF (ADJUSTMENT IS NULL) THEN ADJUSTMENT = 0;
    /* -------------------------------------------------------------------- */
    BALANCE = TOTAL - APPLIED - ADJUSTMENT;
    IF (BALANCE NOT BETWEEN -0.5 AND 0.5) THEN
    BEGIN
       AGE = SDATE - OPENDATE;
       CURR = 0;
       OVER30 = 0;
       OVER60 = 0;
       OVER90 = 0;
       IF (AGE < 30) THEN CURR = BALANCE;
       ELSE IF (AGE < 60) THEN OVER30 = BALANCE;
       ELSE IF (AGE < 90) THEN OVER60 = BALANCE;
       ELSE OVER90 = BALANCE;
       SUSPEND;
    END
  END
END^


ALTER PROCEDURE AP_DEPOSIT_MUTATION(
    MYEAR INTEGER,
    MMONTH INTEGER,
    CURRENCY VARCHAR(4))
RETURNS (
    REFDATE DATE,
    PYEAR INTEGER,
    PMONTH INTEGER,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    SUPLTYPE VARCHAR(4),
    TYPENAME VARCHAR(40),
    DEPOSIT_OPEN DOUBLE PRECISION,
    DEPOSIT_NEW DOUBLE PRECISION,
    DEPOSIT_APPLY DOUBLE PRECISION,
    DEPOSIT_APPADJ DOUBLE PRECISION,
    DEPOSIT_ADJUSTMENT DOUBLE PRECISION,
    DEPOSIT_ENDING DOUBLE PRECISION,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40))
AS
declare variable apply double precision;
declare variable deposit double precision;
declare variable sdate date;
declare variable edate date;
declare variable adjustment double precision;
BEGIN
  IF ((MYEAR IS NULL) OR (MYEAR = 0)) THEN
  BEGIN
     MYEAR = 2005;
     MMONTH = 10;
  END
  PYEAR = MYEAR;
  PMONTH = MMONTH;
  SDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES(EDATE);
  REFDATE = EDATE;
  
  FOR SELECT C.SUPPLIER,C.NAME,C.SUPLTYPE,T.NAME,
             T.DEPOS_GLACCOUNT,T.DEPOS_GLDEPT,T.DEPOS_GLCOST,A.NAME
      FROM syssupplier C
      LEFT JOIN SYSSUPPLIERTYPE T ON T.SUPPLIERTYPE = C.supltype
      LEFT JOIN GLCOA A ON A.ACCOUNT = T.DEPOS_GLACCOUNT
      INTO SUPPLIER,NAME,SUPLTYPE,TYPENAME,
           GL_ACCOUNT,GL_DEPT,GL_COST,ACCNAME
  DO
  BEGIN
     IF ((CURRENCY IN ('All','ALL','')) OR (CURRENCY IS NULL)) THEN
     BEGIN
        SELECT SUM(BALANCE) FROM APDEPOS0 /* DI GANTI BALANCE BY ADIT 16-02-2016 */
        WHERE SUPPLIER = :SUPPLIER
        AND  OPENDATE < :SDATE
        INTO DEPOSIT_OPEN;
     
        SELECT SUM(TOTAL) FROM APDEPOS1
        WHERE SUPPLIER = :SUPPLIER
        AND APPLIEDDATE < :SDATE
        INTO APPLY;

        SELECT SUM(TOTAL) FROM APDEPOS0
        WHERE SUPPLIER = :SUPPLIER
        AND OPENDATE BETWEEN :SDATE AND :EDATE
        INTO DEPOSIT_NEW;
     
        SELECT SUM(AP.TOTAL) FROM APDEPOS1 AP
        WHERE SUPPLIER = :SUPPLIER
        AND APPLIEDDATE BETWEEN :SDATE AND :EDATE
        INTO DEPOSIT_APPLY;
        
        /* -------------------------------------------------------------------- */
        /* 9/12/2011                                                            */
        /* ADJUSTMENT                                                           */
        /* -------------------------------------------------------------------- */
        SELECT SUM(DB-CR) FROM APDEPOS0_JUR
        WHERE SUPPLIER = :SUPPLIER
        AND OPENDATE BETWEEN :SDATE AND :EDATE
        INTO ADJUSTMENT;

    
     END
     ELSE
     BEGIN
        SELECT SUM(FOREX_BALANCE) FROM APDEPOS0  /* DI GANTI FOREX_BALANCE BY ADIT 16-02-2016 */
        WHERE SUPPLIER = :SUPPLIER
        AND  OPENDATE < :SDATE
        AND CURRENCY = :CURRENCY
        INTO DEPOSIT_OPEN;

        SELECT SUM(D.FOREX_TOTAL)FROM APDEPOS1 D
        LEFT JOIN APDEPOS0 H ON H.NUMBER = D.NUMBER
        LEFT JOIN APDEPOS0_JUR AD ON AD.NUMBER = D.NUMBER
        WHERE D.SUPPLIER = :SUPPLIER
        AND D.APPLIEDDATE < :SDATE
        AND H.CURRENCY = :CURRENCY
        INTO APPLY;

        SELECT SUM(FOREX_TOTAL) FROM APDEPOS0
        WHERE SUPPLIER = :SUPPLIER
        AND OPENDATE BETWEEN :SDATE AND :EDATE
        AND CURRENCY = :CURRENCY
        INTO DEPOSIT_NEW;

        SELECT SUM(D.FOREX_TOTAL) FROM APDEPOS1 D
        LEFT JOIN APDEPOS0_JUR AD ON AD.NUMBER = D.NUMBER
        LEFT JOIN APDEPOS0 H ON H.NUMBER = D.NUMBER
        WHERE D.SUPPLIER = :SUPPLIER
        AND D.APPLIEDDATE BETWEEN :SDATE AND :EDATE
        AND H.CURRENCY = :CURRENCY
        INTO DEPOSIT_APPLY;
        
        /* -------------------------------------------------------------------- */
        /* 9/12/2011                                                            */
        /* ADJUSTMENT                                                           */
        /* -------------------------------------------------------------------- */
        SELECT SUM(FOREX_DB-FOREX_CR) FROM APDEPOS0_JUR
        WHERE SUPPLIER = :SUPPLIER
        AND OPENDATE BETWEEN :SDATE AND :EDATE
        AND CURRENCY = :CURRENCY
        INTO ADJUSTMENT;
     END
     IF (DEPOSIT_OPEN IS NULL) THEN DEPOSIT_OPEN = 0;
     IF (APPLY IS NULL) THEN APPLY = 0;
     IF (DEPOSIT_NEW IS NULL) THEN DEPOSIT_NEW = 0;
     IF (DEPOSIT_APPLY IS NULL) THEN DEPOSIT_APPLY = 0;
     IF (ADJUSTMENT IS NULL) THEN ADJUSTMENT = 0; /* 9/12/2011 */

     DEPOSIT_APPADJ = DEPOSIT_APPLY + ADJUSTMENT;  /*UNTUK APPLIED + ADJUSMENT by ADIT 16-02-2016*/
     DEPOSIT_ADJUSTMENT = ADJUSTMENT;       /*UNTUK ADJUSMENT by ADIT 4-04-2016*/
     DEPOSIT_APPLY =  DEPOSIT_APPLY + ADJUSTMENT;  /*UNTUK APPLIED + ADJUSMENT Karena Di Report tidak bisa muncul kalo ada tambah field by ADIT 04-04-2016*/
     DEPOSIT_ENDING = DEPOSIT_OPEN + DEPOSIT_NEW - DEPOSIT_APPADJ;
     IF ((DEPOSIT_OPEN <> 0) OR (DEPOSIT_NEW <> 0) OR (DEPOSIT_APPLY <> 0)) THEN
        SUSPEND;
  END
END^


ALTER PROCEDURE AP_EOM_EXCHANGE(
    USR_ID VARCHAR(8),
    PSAVE INTEGER)
RETURNS (
    DOCTYPE VARCHAR(4),
    NUMBER INTEGER,
    OPENDATE DATE,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    CURRENCY VARCHAR(4),
    FOREX_TOTAL DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    V_EXCHANGE DOUBLE PRECISION,
    E_EXCHANGE DOUBLE PRECISION,
    DELTA_EXCHANGE DOUBLE PRECISION,
    GAINLOSS DOUBLE PRECISION,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    DOCUMENT VARCHAR(20),
    NOTE VARCHAR(40))
AS
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE EOM DATE;
DECLARE VARIABLE APSYSDATE DATE;
BEGIN
  IF (PSAVE IS NULL) THEN PSAVE = 0;
  IF (PSAVE NOT IN (0,1,-1)) THEN PSAVE = 0;

  SELECT APSYSDATE,
         EXTRACT(MONTH FROM APSYSDATE),
         EXTRACT(YEAR FROM APSYSDATE),
         APFOREX_GAINLOSS_GLDEPT,
         APFOREX_GAINLOSS_GLCOST,
         APFOREX_GAINLOSS_GLACCOUNT
  FROM SYSPARAM
  INTO APSYSDATE,M,Y,
       GL_DEPT,GL_COST,GL_ACCOUNT;
  /* ---------------------------------------------------------------- */
  /* HITUNG AKHIR BULAN                                               */
  /* ---------------------------------------------------------------- */
  EXECUTE PROCEDURE SP_ENDOFMONTH(APSYSDATE) RETURNING_VALUES EOM;

  /* ---------------------------------------------------------------- */
  /* JIKA BUKAN AKHIR BULAN TIDAK ADA                                 */
  /* ---------------------------------------------------------------- */
  /*  IF (APSYSDATE <> EOM) THEN EXIT; */

  /* ---------------------------------------------------------------- */
  /* DELETE OLD REVALUATION                                           */
  /* ---------------------------------------------------------------- */
  IF (PSAVE = -1) THEN
  BEGIN
     DELETE FROM APADJ WHERE SOURCE='RE'
                 AND OPENDATE = :EOM
                 AND STATUS = 'O';

     DELETE FROM APDEPOS0_JUR WHERE SOURCE='RE'
                 AND OPENDATE = :EOM
                 AND STATUS = 'O';
     EXIT;
  END

  /* ---------------------------------------------------------------- */
  /* START PROCESS                                                    */
  /* ---------------------------------------------------------------- */

  DOCTYPE = 'VCH';
  IF (PSAVE = 1) THEN
  BEGIN
    UPDATE APVCH SET TAX = -1
    WHERE EXCHANGE <> 1
    AND FOREX_TOTALDUE_PREPARE NOT BETWEEN - 0.05 AND 0.05
    AND OPENDATE <= :EOM;
  END
  
  FOR
    SELECT V.NUMBER,V.OPENDATE,V.CURRENCY,
           V.FOREX_TOTALDUE_PREPARE,
           V.TOTALDUE_PREPARE,V.SUPPLIER,C.NAME
    FROM APVCH V
    LEFT JOIN SYSSUPPLIER C ON C.SUPPLIER = V.SUPPLIER
    WHERE V.EXCHANGE <> 1
    AND V.FOREX_TOTALDUE_PREPARE NOT BETWEEN - 0.05 AND 0.05
    AND V.OPENDATE <= :EOM
    INTO
      NUMBER,OPENDATE,CURRENCY,
      FOREX_TOTAL,
      TOTAL,SUPPLIER,NAME
  DO
  BEGIN

    V_EXCHANGE = TOTAL/FOREX_TOTAL;

    IF (NOT EXISTS(SELECT EXCHANGE FROM SYSCURRENCY_LOG_GL
               WHERE PYEAR = :Y AND PMONTH = :M AND CURRENCY = :CURRENCY)) THEN
    BEGIN
       EXCEPTION AP_GAINLOSS_INVALID 'Currency '|| CURRENCY || ' on period ' || M || '-'||Y|| ' does not exists';
    END

    SELECT EXCHANGE FROM SYSCURRENCY_LOG_GL
    WHERE PYEAR = :Y
    AND PMONTH = :M
    AND CURRENCY = :CURRENCY
    INTO E_EXCHANGE;


    IF ((E_EXCHANGE IS NOT NULL) AND (E_EXCHANGE <> V_EXCHANGE)) THEN
    BEGIN
       DELTA_EXCHANGE = E_EXCHANGE - V_EXCHANGE;
       GAINLOSS = FOREX_TOTAL * DELTA_EXCHANGE;
       IF (GAINLOSS NOT BETWEEN -0.05 AND 0.05) THEN
       BEGIN
          DOCUMENT = 'PV-RE/'|| Y || '/'||M || '/' || NUMBER;
          /* 9/21/2013 */
          BEGIN
             NOTE = 'Due ' || CAST(FOREX_TOTAL AS NUMERIC(8,2)) ||
                    ',Old Exch:' || CAST(:V_EXCHANGE AS NUMERIC(8,2));
          /* -------------------------------------------------------------------- */
          /* 9/21/2013                                                            */
          /* -------------------------------------------------------------------- */
          WHEN ANY
             DO
             BEGIN
                NOTE = '';
             END
          END
          /* -------------------------------------------------------------------- */
          /* 9/21/2013 end of                                                     */
          /* -------------------------------------------------------------------- */
          IF (PSAVE = 0) THEN
          BEGIN
             IF (NOT EXISTS(SELECT * FROM APADJ
                     WHERE VOUCHERNO=:NUMBER
                     AND SOURCE='RE'
                     AND OPENDATE = :EOM)) THEN
                SUSPEND; /* JIKA TIDAK DISIMPAN,DI SUSPEND */
          END
          ELSE
          BEGIN /* SAVE = 1 */
             /* ---------------------------------------------------------------- */
             /* DELETE IF STATUS "O"                                             */
             /* ---------------------------------------------------------------- */
             DELETE FROM APADJ WHERE VOUCHERNO=:NUMBER
                 AND SOURCE='RE'
                 AND OPENDATE = :EOM
                 AND STATUS = 'O';
             /* ---------------------------------------------------------------- */
             /* CREATE NEW ADJUSTMENT                                            */
             /* ---------------------------------------------------------------- */
             IF (NOT EXISTS(SELECT * FROM APADJ
                     WHERE VOUCHERNO=:NUMBER
                     AND SOURCE='RE'
                     AND OPENDATE = :EOM)) THEN
             BEGIN
                INSERT INTO APADJ (
                 VOUCHERNO,DOCUMENT,OPENDATE,STATUS,SUPPLIER,
                 ACCOUNT,DEPT,COST,PROJECT,
                 TEXT1,
                 CREATEDATE,EDITDATE,CREATEUSER,EDITUSER,
                 FOREX_DB,FOREX_CR,
                 CURRENCY,EXCHANGE,
                 DB,CR,
                 SOURCE,SOURCENUMBER)
                VALUES (
                 :NUMBER,:DOCUMENT,:EOM,'O',:SUPPLIER,
                 :GL_ACCOUNT,:GL_DEPT,:GL_COST,'0000',
                 :NOTE,
                 'NOW','NOW',:USR_ID,:USR_ID,
                 0,/* FOREX_DB */
                 0,/* FOREX_CR */
                 :CURRENCY,
                 :E_EXCHANGE,
                 0,/* DB */
                 :GAINLOSS,/* CR */
                 'RE',0);
             END
             UPDATE APVCH SET TAX = -1 WHERE NUMBER = :NUMBER;
          END /* SAVE = 1*/
       END /*  IF (DELTA NOT BETWEEN -0.05 AND 0.05) THEN */
    END /* IF ((E_EXCHANGE IS NOT NULL) AND (E_EXCHANGE <> V_EXCHANGE)) THEN */

  END

  /* ---------------------------------------------------------------- */
  /* DEPOSTI                                                          */
  /* ---------------------------------------------------------------- */
  IF (PSAVE = 1) THEN
  BEGIN
    UPDATE APDEPOS0 V SET FOREX_GAINLOSS = -1
    WHERE V.EXCHANGE <> 1
    AND V.FOREX_BALANCE NOT BETWEEN - 0.05 AND 0.05
    AND V.OPENDATE <= :EOM;
  END
  
  DOCTYPE = 'DEP';
  FOR
    SELECT V.NUMBER,V.OPENDATE,V.CURRENCY,
           V.FOREX_BALANCE,V.BALANCE,
           V.SUPPLIER,C.NAME
    FROM APDEPOS0 V
    LEFT JOIN SYSSUPPLIER C ON C.SUPPLIER = V.SUPPLIER
    WHERE V.EXCHANGE <> 1
    AND V.FOREX_BALANCE NOT BETWEEN - 0.05 AND 0.05
    AND V.OPENDATE <= :EOM
    INTO
      NUMBER,OPENDATE,CURRENCY,
      FOREX_TOTAL,TOTAL,
      SUPPLIER,NAME
  DO
  BEGIN

    V_EXCHANGE = TOTAL/FOREX_TOTAL;

    IF (NOT EXISTS(SELECT EXCHANGE FROM SYSCURRENCY_LOG_GL
               WHERE PYEAR = :Y AND PMONTH = :M AND CURRENCY = :CURRENCY)) THEN
    BEGIN
       EXCEPTION AP_GAINLOSS_INVALID 'Currency '|| CURRENCY || ' on period ' || M || '-'||Y|| ' does not exists';
    END
    SELECT EXCHANGE FROM SYSCURRENCY_LOG_GL
    WHERE PYEAR = :Y
    AND PMONTH = :M
    AND CURRENCY = :CURRENCY
    INTO E_EXCHANGE;


    IF ((E_EXCHANGE IS NOT NULL) AND (E_EXCHANGE <> V_EXCHANGE)) THEN
    BEGIN
       DELTA_EXCHANGE = E_EXCHANGE-V_EXCHANGE;
       GAINLOSS = FOREX_TOTAL * DELTA_EXCHANGE;
       IF (GAINLOSS NOT BETWEEN -0.05 AND 0.05) THEN
       BEGIN
          DOCUMENT = 'PD-RE/'|| Y || '/'||M || '/' || NUMBER;
          NOTE = 'Due ' || CAST(FOREX_TOTAL AS NUMERIC(8,2)) ||
                 ',Old Exch:' || CAST(:V_EXCHANGE AS NUMERIC(8,2));
                 
          IF (PSAVE = 0) THEN
          BEGIN
             IF (NOT EXISTS(SELECT * FROM APDEPOS0_JUR
                     WHERE DEPOSITNO =:NUMBER
                     AND SOURCE='RE'
                     AND OPENDATE = :EOM)) THEN
                SUSPEND; /* JIKA TIDAK DISIMPAN,DI SUSPEND */
          END
          ELSE
          BEGIN /* SAVE = 1 */
             /* ---------------------------------------------------------------- */
             /* DELETE IF STATUS "O"                                             */
             /* ---------------------------------------------------------------- */
             DELETE FROM APDEPOS0_JUR WHERE DEPOSITNO=:NUMBER
                 AND SOURCE='RE'
                 AND OPENDATE = :EOM
                 AND STATUS = 'O';
             /* ---------------------------------------------------------------- */
             /* CREATE NEW ADJUSTMENT                                            */
             /* ---------------------------------------------------------------- */
             IF (NOT EXISTS(SELECT * FROM APDEPOS0_JUR
                     WHERE DEPOSITNO=:NUMBER
                     AND SOURCE='RE'
                     AND OPENDATE = :EOM)) THEN
             BEGIN
                INSERT INTO APDEPOS0_JUR (
                 DEPOSITNO,DOCUMENT,OPENDATE,STATUS,SUPPLIER,
                 ACCOUNT,DEPT,COST,PROJECT,
                 NOTE,
                 CREATEDATE,EDITDATE,CREATEUSER,EDITUSER,
                 FOREX_DB,FOREX_CR,
                 CURRENCY,EXCHANGE,
                 DB,CR,
                 SOURCE,SOURCENUMBER)
                VALUES (
                 :NUMBER,:DOCUMENT,:EOM,'O',:SUPPLIER,
                 :GL_ACCOUNT,:GL_DEPT,:GL_COST,'0000',
                 :NOTE,
                 'NOW','NOW',:USR_ID,:USR_ID,
                 0,/* FOREX_DB */
                 0,/* FOREX_CR */
                 :CURRENCY,:E_EXCHANGE,
                 :GAINLOSS,/* DB */
                 0,/* CR */
                 'RE',0);
             END
             UPDATE APDEPOS0 SET FOREX_GAINLOSS = -1 WHERE NUMBER = :NUMBER;
          END /* SAVE = 1*/
       END /*  IF (DELTA NOT BETWEEN -0.05 AND 0.05) THEN */
    END /* IF ((E_EXCHANGE IS NOT NULL) AND (E_EXCHANGE <> V_EXCHANGE)) THEN */

  END
END^


ALTER PROCEDURE AP_GLBUFFER_AALL_RECREATE(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    NUMBER INTEGER,
    OPENDATE DATE,
    INFO VARCHAR(20),
    SUPLTYPE VARCHAR(4),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER,
    ERROR_TEXT VARCHAR(128))
AS
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SELECT APSYSDATE FROM SYSPARAM INTO SDATE;
     SDATE = '1.8.2000';
     EDATE = '31.8.2005';
     PSAVE = 0;
  END
  APPLICATION = 'AP';
  /* ------------------------------------------------------------------------ */
  /* ADJUSTMENT                                                               */
  /* ------------------------------------------------------------------------ */
  SOURCE = 'ADJ';
  FOR
      SELECT NUMBER, OPENDATE, INFO, SUPLTYPE, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
             GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
      FROM AP_GLBUFFER_ADJ_RECREATE(:SDATE, :EDATE, :PSAVE)
      INTO NUMBER, OPENDATE, :INFO, :SUPLTYPE, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
           :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
           RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
  DO
  BEGIN
    IF (PSAVE = 0) THEN SUSPEND;
  END
  /* ------------------------------------------------------------------------ */
  /* CASH PAYMENT                                                             */
  /* ------------------------------------------------------------------------ */
  SOURCE = 'CASH';
  FOR
      SELECT NUMBER, OPENDATE, INFO, SUPLTYPE, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
             GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
      FROM AP_GLBUFFER_CASH_RECREATE(:SDATE, :EDATE, :PSAVE)
      INTO NUMBER, OPENDATE, :INFO, :SUPLTYPE, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
           :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
           RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
  DO
  BEGIN
    IF (PSAVE = 0) THEN SUSPEND;
  END
  /* ========================================================================*/
  /* RECONCILE CASH, TIDAK DISIMPAN HANYA UNTUK CONTROL SAJA                 */
  /* ========================================================================*/
  IF (PSAVE = 0) THEN
  BEGIN
    SOURCE = 'REC';
    FOR SELECT NUMBER  FROM APCASH0
        WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
        AND STATUS = 'C'
    INTO :NUMBER
    DO
    BEGIN
      FOR
        SELECT INFO, SUPLTYPE, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
               GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
               RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
        FROM AP_GLBUFFER_CASH_RECONCILE(:NUMBER)
        INTO :INFO, :SUPLTYPE, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
             :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
       DO
       BEGIN
         if (DEBIT + CREDIT <> 0) then
            SUSPEND;
       END
    END
  END
  /* ------------------------------------------------------------------------ */
  /* DEPOSIT                                                                  */
  /* ------------------------------------------------------------------------ */
  SOURCE = 'DEP0';
  FOR
      SELECT NUMBER, OPENDATE, INFO, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
             GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
      FROM AP_GLBUFFER_DEPOSIT_RECREATE(:SDATE, :EDATE, :PSAVE)
      INTO NUMBER, OPENDATE, :INFO, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
           :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
           RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
  DO
  BEGIN
    IF (PSAVE = 0) THEN SUSPEND;
  END
  /* ------------------------------------------------------------------------ */
  /* DEPOSIT APPLY                                                                 */
  /* ------------------------------------------------------------------------ */
  SOURCE = 'DEP1';
  FOR
      SELECT NUMBER, OPENDATE, INFO, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
             GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
      FROM AP_GLBUFFER_DEP_APPLY_RECREATE(:SDATE, :EDATE, :PSAVE)
      INTO NUMBER, OPENDATE, :INFO, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
           :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
           RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
  DO
  BEGIN
    IF (PSAVE = 0) THEN SUSPEND;
  END
  /* ------------------------------------------------------------------------ */
  /* VOUCHER FROM SHARED REVENUE / FO AGENT COMMISSION                        */
  /* ------------------------------------------------------------------------ */
  SOURCE = 'VCH';
  FOR
      SELECT NUMBER, OPENDATE, INFO, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
             GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
      FROM AP_GLBUFFER_VCH_RECREATE(:SDATE, :EDATE, :PSAVE)
      INTO NUMBER, OPENDATE, :INFO, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
           :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
           RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
  DO
  BEGIN
    IF (PSAVE = 0) THEN SUSPEND;
  END
  /* ========================================================================*/
  /* RECONCILE CASH, TIDAK DISIMPAN HANYA UNTUK CONTROL SAJA                 */
  /* 8 DESEMBER 2006                                                         */
  /* ========================================================================*/
  IF (PSAVE = 0) THEN
  BEGIN
    SOURCE = 'DREC';
    FOR SELECT NUMBER  FROM APDEPOS0
        WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
        AND STATUS = 'C'
    INTO :NUMBER
    DO
    BEGIN
      FOR
        SELECT INFO, SUPLTYPE, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
               GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
               RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
        FROM AP_GLBUFFER_DEPOSIT_RECONCILE(:NUMBER)
        INTO :INFO, :SUPLTYPE, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
             :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
       DO
       BEGIN
         if (DEBIT + CREDIT <> 0) then
            SUSPEND;
       END
    END
  END
END^


ALTER PROCEDURE AP_GLBUFFER_ADJUSTMENT(
    NUMBER INTEGER)
RETURNS (
    INFO VARCHAR(20),
    SUPLTYPE VARCHAR(4),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE SUPPLIER VARCHAR(6);
DECLARE VARIABLE NAME VARCHAR(40);
DECLARE VARIABLE DB DOUBLE PRECISION;
DECLARE VARIABLE CR DOUBLE PRECISION;
BEGIN
  if (NUMBER IS NULL) then
  BEGIN
     NUMBER = 6;
  END
  /* ------------------------------------------------------------------------ */
  /*  ADJUSTMENT                                                              */
  /* ------------------------------------------------------------------------ */
  SELECT A.ACCOUNT, A.DEPT, A.COST, A.DB, A.CR, A.TEXT1, DOCUMENT,
         A.SUPPLIER, A.OPENDATE, S.NAME, S.SUPLTYPE,
         S.RELATION_DOCTYPE FROM APADJ A
  LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = A.SUPPLIER
  WHERE A.NUMBER = :NUMBER
  INTO GL_ACCOUNT, GL_DEPT, GL_COST, DB, CR, NOTE, REF,
       SUPPLIER, TRANSDATE, NAME, SUPLTYPE, RELATION_DOCTYPE;

  DEBIT = CR;
  CREDIT = DB;
  INFO = 'Adjustment';
  ERROR_TEXT = '';
  SETUP_INFO = 'APADJ';  
  RELATION_CODE = :SUPPLIER;
  SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
  if (CREDIT <> 0) then ID = 1;
  else ID = 2;
  EXECUTE PROCEDURE INV_GLBUFFER_ERROR('APADJ', GL_ACCOUNT, GL_DEPT, GL_COST, SUPLTYPE, SUPLTYPE)
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;  
  SUSPEND;
  /* ------------------------------------------------------------------------ */
  /*  SUPPLIER TYPE                                                           */
  /* ------------------------------------------------------------------------ */
  SELECT GLACCOUNT, GLDEPT, GLCOST FROM SYSSUPPLIERTYPE T
  WHERE T.SUPPLIERTYPE = :SUPLTYPE
  INTO GL_ACCOUNT, GL_DEPT, GL_COST;
  
  SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;  
  if (CREDIT <> 0) then ID = 2;
  else ID = 1;
  DEBIT = DB;
  CREDIT = CR;
  INFO = 'A/P';
  ERROR_TEXT = '';
  SETUP_INFO = 'SUPPLIER_TYPE';
  NOTE = NAME;
  SUSPEND;
END^


ALTER PROCEDURE AP_GLBUFFER_ADJ_RECREATE(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER)
RETURNS (
    NUMBER INTEGER,
    OPENDATE DATE,
    INFO VARCHAR(20),
    SUPLTYPE VARCHAR(4),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER,
    ERROR_TEXT VARCHAR(128))
AS
declare variable USR VARCHAR(8);
BEGIN
  if (SDATE IS NULL) then
  BEGIN
     SDATE = '1.5.2005';
     EDATE = '31.5.2005';
     PSAVE = 0;
  END
  if (PSAVE = 1) then
  BEGIN
     DELETE FROM glbuffer
     WHERE APPLICATION = 'AP'
     AND SOURCE = 'ADJ'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE;
     
     DELETE FROM GLTRANS
     WHERE APPLICATION = 'AP'
     AND SOURCE = 'ADJ'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE
     AND ((CSOURCE='') OR (CSOURCE IS NULL)) /* 29 OCT 2007 */;
  END
  FOR SELECT NUMBER, OPENDATE, EDITUSER FROM APADJ
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND STATUS IN ('R','C')
  INTO :NUMBER, :OPENDATE, USR
  DO
  BEGIN
    FOR
      SELECT INFO, SUPLTYPE, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
             GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
      FROM ap_glbuffer_adjustment(:NUMBER)
      INTO :INFO, :SUPLTYPE, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
           :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
           RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
    DO
    BEGIN
       if (DEBIT + CREDIT <> 0) then
       BEGIN    
         if (PSAVE = 1) then
         BEGIN
          insert into glbuffer
                 (APPLICATION, SOURCE, NUMBER, ID, transdate,
                  ACCOUNT, DEPT, COST, PROJECT,
                  NOTE, REF,
                  DB, CR,
                  EXPORTDATE, EXPORTUSER)
          values ('AP','ADJ', :number, :ID, :opendate,
                  :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                  :NOTE, :REF,
                  :DEBIT, :CREDIT,
                  'now', :USR);
          END
          ELSE
            SUSPEND;
       END
    END
  END
END^


ALTER PROCEDURE AP_GLBUFFER_CASH(
    NUMBER INTEGER)
RETURNS (
    INFO VARCHAR(20),
    SUPLTYPE VARCHAR(4),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE SUPPLIER VARCHAR(6);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
DECLARE VARIABLE FOREX_GAINLOSS DOUBLE PRECISION;
DECLARE VARIABLE BANK VARCHAR(4);
BEGIN
  if (NUMBER IS NULL) then
  BEGIN
     NUMBER = 3644;
  END
  /* ------------------------------------------------------------------------ */
  /*  ADJUSTMENT                                                              */
  /* ------------------------------------------------------------------------ */
  SELECT A.TEXT1, DOCUMENT, TOTAL, FOREX_GAINLOSS,
         A.SUPPLIER, A.DUEDATE, S.NAME, S.SUPLTYPE,
         S.RELATION_DOCTYPE,
         T.GLACCOUNT, T.GLDEPT, T.GLCOST, A.BANK
  FROM APCASH0 A
  LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = A.SUPPLIER
  LEFT JOIN SYSSUPPLIERTYPE T ON T.SUPPLIERTYPE = S.SUPLTYPE
  WHERE A.NUMBER = :NUMBER
  INTO NOTE, REF, TOTAL, FOREX_GAINLOSS,
       SUPPLIER, TRANSDATE, NOTE, SUPLTYPE,
       RELATION_DOCTYPE, GL_ACCOUNT, GL_DEPT, GL_COST, BANK;

  DEBIT = TOTAL-FOREX_GAINLOSS;
  CREDIT = 0;
  INFO = 'Payable';
  ERROR_TEXT = '';
  SETUP_INFO = 'SUPLTYPE';
  RELATION_CODE = :SUPPLIER;
  ID = 1;
  SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
  EXECUTE PROCEDURE INV_GLBUFFER_ERROR(SETUP_INFO, GL_ACCOUNT, GL_DEPT, GL_COST, SUPLTYPE, SUPLTYPE)
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;  
  SUSPEND;
  /* ------------------------------------------------------------------------ */
  /*  SUPPLIER TYPE                                                           */
  /* ------------------------------------------------------------------------ */
  select gl_account_apprepare, gl_dept_apprepare, gl_cost_apprepare from sysbank
  where bank = :BANK
  into GL_ACCOUNT, GL_DEPT, GL_COST;
  
  SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;  
  ID = 2;
  DEBIT = 0;
  CREDIT = TOTAL;
  INFO = 'Bank';
  ERROR_TEXT = '';
  SETUP_INFO = 'SYSBANK';
  EXECUTE PROCEDURE INV_GLBUFFER_ERROR(SETUP_INFO, GL_ACCOUNT, GL_DEPT, GL_COST, SUPLTYPE, SUPLTYPE)
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;    
  SUSPEND;
  
  IF (FOREX_GAINLOSS <> 0) THEN
  BEGIN
     select apforex_gainloss_glaccount, apforex_gainloss_gldept, apforex_gainloss_glcost
     from sysparam
     into GL_ACCOUNT, GL_DEPT, GL_COST;
     
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME; 
       
     INFO = 'Gain/Loss Forex';
     ERROR_TEXT = '';
     SETUP_INFO = 'SYSPARAM';
     EXECUTE PROCEDURE INV_GLBUFFER_ERROR(SETUP_INFO, GL_ACCOUNT, GL_DEPT, GL_COST, SUPLTYPE, SUPLTYPE)
     RETURNING_VALUES ERROR_TEXT, SETUP_INFO;
     ID = 3;
     DEBIT = 0;
     CREDIT = 0;
     IF (FOREX_GAINLOSS > 0) THEN DEBIT = FOREX_GAINLOSS;
     ELSE CREDIT = -FOREX_GAINLOSS;
     SUSPEND;
  END
END^


