ALTER PROCEDURE AP_GLBUFFER_DEPOSIT(
    NUMBER INTEGER)
RETURNS (
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE SUPPLIER VARCHAR(6);
DECLARE VARIABLE BANK VARCHAR(4);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
BEGIN
  if (NUMBER IS NULL) then
  BEGIN
     NUMBER = 6;
  END
  
  SELECT OPENDATE, SUPPLIER, TOTAL, DOCUMENT, BANK FROM APDEPOS0
  WHERE NUMBER = :NUMBER
  INTO TRANSDATE, SUPPLIER, TOTAL, REF, BANK;
  
  ERROR_TEXT = '';
  select name, depos_glaccount, depos_gldept, depos_glcost, RELATION_DOCTYPE  from syssupplier
  left join syssuppliertype on suppliertype = SUPLTYPE
  where SUPPLIER = :SUPPLIER
  into NOTE, GL_ACCOUNT, GL_DEPT, GL_COST, RELATION_DOCTYPE;

  IF (RELATION_DOCTYPE IS NULL) THEN RELATION_DOCTYPE = 0;
  SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
  INFO = 'Deposit';
  ID = 1;
  DEBIT = TOTAL;
  CREDIT = 0;
  RELATION_CODE = :SUPPLIER;
  SETUP_INFO = 'SYSSUPPLIER';
  SUSPEND;
  /* --------------------------------------------------------------------- */
  /* bank account                                                    */
  /* --------------------------------------------------------------------- */
  select bankname, gl_account_apprepare, gl_dept_apprepare, gl_cost_apprepare, RELATION_DOCTYPE
  from sysbank
  where bank = :BANK
  into :NOTE, GL_ACCOUNT, GL_DEPT, GL_COST, RELATION_DOCTYPE;

  IF (RELATION_DOCTYPE IS NULL) THEN RELATION_DOCTYPE = 0;
  SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
  INFO = 'Bank';
  ID = 2;
  RELATION_CODE = BANK;
  DEBIT = 0;
  CREDIT = TOTAL;
  SETUP_INFO = 'SYSBANK';
  SUSPEND;
END^


ALTER PROCEDURE AP_GLBUFFER_DEPOSIT_APPLY(
    NUMBER INTEGER)
RETURNS (
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE SUPPLIER VARCHAR(6);
DECLARE VARIABLE BANK VARCHAR(4);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
DECLARE VARIABLE FOREX_GAINLOSS DOUBLE PRECISION;
DECLARE VARIABLE EXCHANGE DOUBLE PRECISION;
DECLARE VARIABLE VCH_EXCHANGE DOUBLE PRECISION;
BEGIN
  if (NUMBER IS NULL) then
  BEGIN
     NUMBER = 11;
  END
  
  SELECT D.APPLIEDDATE,D.SUPPLIER,D.TOTAL,H.DOCUMENT,H.BANK,D.vch_gainloss,
         EXCHANGE,VCH_EXCHANGE FROM APDEPOS1 D
  LEFT JOIN APDEPOS0 H ON H.NUMBER = D.NUMBER
  WHERE APPLY_NUMBER = :NUMBER
  INTO TRANSDATE,SUPPLIER,TOTAL,REF,BANK,FOREX_GAINLOSS,
       EXCHANGE,VCH_EXCHANGE;
  IF (FOREX_GAINLOSS IS NULL) THEN FOREX_GAINLOSS = 0;
  /* ----------------------------------------------------------------  */
  /* A/P (DB)                                                          */
  /* ----------------------------------------------------------------  */
  ERROR_TEXT = '';
  select S.name,T.glaccount,T.gldept,T.glcost,S.RELATION_DOCTYPE  from syssupplier S
  left join syssuppliertype T on suppliertype = SUPLTYPE
  where SUPPLIER = :SUPPLIER
  into NOTE,GL_ACCOUNT,GL_DEPT,GL_COST,RELATION_DOCTYPE;

  IF (RELATION_DOCTYPE IS NULL) THEN RELATION_DOCTYPE = 0;
  SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
  INFO = 'A/P';
  ID = 1;
/*  DEBIT = TOTAL; 
  CREDIT = 0; */
  DEBIT = TOTAL+FOREX_GAINLOSS;
  CREDIT = 0;
  
  RELATION_CODE = :SUPPLIER;
  SETUP_INFO = 'SYSSUPPLIER';
  SUSPEND;
  /* --------------------------------------------------------------------- */
  /* DEPOSIT (CR)                                                          */
  /* --------------------------------------------------------------------- */
  select S.name,T.depos_glaccount,T.depos_gldept,T.depos_glcost,S.RELATION_DOCTYPE  from syssupplier S
  left join syssuppliertype T on suppliertype = SUPLTYPE
  where S.SUPPLIER = :SUPPLIER
  into NOTE,GL_ACCOUNT,GL_DEPT,GL_COST,RELATION_DOCTYPE;

  IF (RELATION_DOCTYPE IS NULL) THEN RELATION_DOCTYPE = 0;
  SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
  INFO = 'Apply Deposit';
  ID = 2;
  RELATION_CODE = BANK;
  DEBIT = 0;
  CREDIT = TOTAL;
  SETUP_INFO = 'SYSBANK';
  SUSPEND;
  /* --------------------------------------------------------------------- */
  /* LOSS & GAIN CURRENCY (CR)                                             */
  /* --------------------------------------------------------------------- */
  if (FOREX_GAINLOSS <> 0) then
  begin
     INFO = 'Gain/Loss';
     select aPforex_gainloss_glaccount,apforex_gainloss_gldept,apforex_gainloss_glcost
     from sysparam
     into GL_ACCOUNT,GL_DEPT,GL_COST;
     SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
     ID = 2;
     IF (FOREX_GAINLOSS < 0) THEN
     BEGIN
        DEBIT = -FOREX_GAINLOSS;
        CREDIT = 0;
     END
     ELSE
     BEGIN
        DEBIT = 0;
        CREDIT = FOREX_GAINLOSS;
     END
     SETUP_INFO = 'SYSPARAM';
     NOTE = 'Xchg Vchr: ' || CAST(VCH_EXCHANGE AS NUMERIC(8,2)) || ',Dep: ' ||
           CAST(EXCHANGE AS NUMERIC(8,2));
     SUSPEND;
  end
END^


ALTER PROCEDURE AP_GLBUFFER_DEPOSIT_JUR_RELEASE(
    NUMBER INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    SETUP_DATA VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
declare variable supplier varchar(6);
declare variable bank varchar(4);
declare variable supltype varchar(4);
declare variable vname varchar(40);
declare variable db double precision;
declare variable cr double precision;
begin
 /* ------------------------------------------------------------------------- */
 /* EXPORT PADA SAAT STATUS CASH RECIPT DI RELEASE                            */
 /* ------------------------------------------------------------------------- */
 IF (NUMBER IS NULL) THEN SELECT MAX(NUMBER) FROM APDEPOS0_JUR INTO NUMBER;

 SELECT D.DOCUMENT, D.SUPPLIER, D.OPENDATE, D.DB, D.CR FROM APDEPOS0_JUR D
 WHERE D.NUMBER = :NUMBER
 INTO REF, SUPPLIER, TRANSDATE, DB, CR;
 /* ------------------------------------------------------------------- */
 /* CREDIT TO AR                                                        */
 /* ------------------------------------------------------------------- */
 SELECT NAME, SUPLTYPE, RELATION_DOCTYPE
 FROM SYSSUPPLIER
 WHERE SUPPLIER = :SUPPLIER
 INTO :VNAME, SUPLTYPE, RELATION_DOCTYPE;
 RELATION_CODE = SUPPLIER;

 SELECT DEPOS_GLACCOUNT, DEPOS_GLDEPT, DEPOS_GLCOST FROM SYSSUPPLIERTYPE
 WHERE SUPPLIERTYPE = :SUPLTYPE
 INTO GL_ACCOUNT, GL_DEPT, GL_COST;

 IF ((GL_DEPT IS NULL) OR (GL_DEPT = '')) THEN GL_DEPT = '0000';
 IF ((GL_COST IS NULL) OR (GL_COST = '')) THEN GL_COST = '0000';

 APPLICATION = 'AP';
 SOURCE = 'DADJ';
 INFO = 'Deposit';
 ID = 1;
 NOTE = vName;
 DEBIT = CR;
 CREDIT = DB;
 SETUP_INFO = 'SUPPLIER_TYPE';
 SETUP_DATA = SUPLTYPE;
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
 SUSPEND;
 /* ------------------------------------------------------------------- */
 /* DEPOSIT                                                             */
 /* ------------------------------------------------------------------- */
 SELECT ACCOUNT, DEPT, COST, DEPOSITNO FROM APDEPOS0_JUR WHERE NUMBER = :NUMBER
 INTO GL_ACCOUNT, GL_DEPT, GL_COST, SETUP_DATA;

 IF ((GL_DEPT IS NULL) OR (GL_DEPT = '')) THEN GL_DEPT = '0000';
 IF ((GL_COST IS NULL) OR (GL_COST = '')) THEN GL_COST = '0000';

 INFO = 'Adjustment';
 ID = 2;
 DEBIT = DB;
 CREDIT = CR;
 SETUP_INFO = 'APDEPOS0_JUR';
 SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
 SUSPEND;
end^


