  ERROR_TEXT = '';
  SETUP_INFO = 'SYSBANK';
  EXECUTE PROCEDURE INV_GLBUFFER_ERROR(SETUP_INFO, GL_ACCOUNT, GL_DEPT, GL_COST, SUPLTYPE, SUPLTYPE)
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;
  SUSPEND;
END^


ALTER PROCEDURE AP_GLBUFFER_DEPOSIT_RECREATE(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER)
RETURNS (
    NUMBER INTEGER,
    OPENDATE DATE,
    INFO VARCHAR(20),
    SUPLTYPE VARCHAR(4),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER,
    ERROR_TEXT VARCHAR(128))
AS
declare variable USR VARCHAR(8);
BEGIN
  if (SDATE IS NULL) then
  BEGIN
     SDATE = '1.7.2005';
     EDATE = '31.7.2005';
     PSAVE = 0;
  END
  if (PSAVE = 1) then
  BEGIN
     DELETE FROM glbuffer
     WHERE APPLICATION = 'AP'
     AND SOURCE = 'DEP0'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE;
     
     DELETE FROM GLTRANS
     WHERE APPLICATION = 'AP'
     AND SOURCE = 'DEP0'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE
     AND ((CSOURCE='') OR (CSOURCE IS NULL)) /* 29 OCT 2007 */;
  END
  FOR SELECT NUMBER, OPENDATE, EDITUSER FROM APDEPOS0
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND STATUS IN ('R','C','L')
  INTO :NUMBER, :OPENDATE, USR
  DO
  BEGIN
    FOR
      SELECT INFO, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
             GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
      FROM ap_glbuffer_deposit(:NUMBER)
      INTO :INFO, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
           :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
           RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
    DO
    BEGIN
       if (DEBIT + CREDIT <> 0) then
       BEGIN    
         if (PSAVE = 1) then
         BEGIN
          insert into glbuffer
                 (APPLICATION, SOURCE, NUMBER, ID, transdate,
                  ACCOUNT, DEPT, COST, PROJECT,
                  NOTE, REF,
                  DB, CR,
                  EXPORTDATE, EXPORTUSER)
          values ('AP','DEP0', :number, :ID, :opendate,
                  :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                  :NOTE, :REF,
                  :DEBIT, :CREDIT,
                  'now', :USR);
          END
          ELSE
            SUSPEND;
       END
    END
  END

  /* ---------------------------------------------------------------- */
  /* 31 MARET 2008                                                    */
  /* DEPOSIT JOURNAL                                                  */
  /* ---------------------------------------------------------------- */
  if (PSAVE = 1) then
  BEGIN
     DELETE FROM glbuffer
     WHERE APPLICATION = 'AP'
     AND SOURCE = 'DADJ'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE;

     DELETE FROM GLTRANS
     WHERE APPLICATION = 'AP'
     AND SOURCE = 'DADJ'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE
     AND ((CSOURCE='') OR (CSOURCE IS NULL)) /* 29 OCT 2007 */;
  END
  FOR SELECT NUMBER, OPENDATE, EDITUSER FROM APDEPOS0_JUR
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND STATUS IN ('R','C')
  INTO :NUMBER, :OPENDATE, USR
  DO
  BEGIN
    FOR
      SELECT INFO, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
             GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
      FROM AP_GLBUFFER_DEPOSIT_JUR_RELEASE(:NUMBER)
      INTO :INFO, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
           :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
           RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
    DO
    BEGIN
       IF (DEBIT + CREDIT <> 0) THEN
       BEGIN
         IF (PSAVE = 1) THEN
         BEGIN
          INSERT INTO GLBUFFER
                 (APPLICATION, SOURCE, NUMBER, ID, TRANSDATE,
                  ACCOUNT, DEPT, COST, PROJECT,
                  NOTE, REF,
                  DB, CR,
                  EXPORTDATE, EXPORTUSER)
          VALUES ('AP','DADJ', :NUMBER, :ID, :OPENDATE,
                  :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                  :NOTE, :REF,
                  :DEBIT, :CREDIT,
                  'NOW', :USR);
          END
          ELSE
            SUSPEND;
       END
    END
  END

END^


