ALTER PROCEDURE AP_GLBUFFER_VCH_COMMISSION(
    NUMBER INTEGER)
RETURNS (
    INFO VARCHAR(20),
    SUPLTYPE VARCHAR(4),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE SUPPLIER VARCHAR(6);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
BEGIN
  if (NUMBER IS NULL) then
  BEGIN
     NUMBER = 2;
  END
  /* ------------------------------------------------------------------------ */
  /*  VOCUCHER                                                                */
  /* ------------------------------------------------------------------------ */
  SELECT V.TEXT1,DOCUMENT,TOTAL,
         V.SUPPLIER,V.OPENDATE,S.NAME,S.SUPLTYPE,
         S.RELATION_DOCTYPE,
         T.GLACCOUNT,T.GLDEPT,T.GLCOST
  FROM APVCH V
  LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = V.SUPPLIER
  LEFT JOIN SYSSUPPLIERTYPE T ON T.SUPPLIERTYPE = S.SUPLTYPE
  WHERE V.NUMBER = :NUMBER
  INTO NOTE,REF,TOTAL,
       SUPPLIER,TRANSDATE,NOTE,SUPLTYPE,
       RELATION_DOCTYPE,GL_ACCOUNT,GL_DEPT,GL_COST;

  DEBIT = 0;
  CREDIT = TOTAL;
  INFO = 'Commission';

  ERROR_TEXT = '';
  SETUP_INFO = 'SUPLTYPE';
  RELATION_CODE = :SUPPLIER;
  ID = 2;
  SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
  EXECUTE PROCEDURE INV_GLBUFFER_ERROR(SETUP_INFO,GL_ACCOUNT,GL_DEPT,GL_COST,SUPLTYPE,SUPLTYPE)
  RETURNING_VALUES ERROR_TEXT,SETUP_INFO;  
  SUSPEND;
  /* ------------------------------------------------------------------------ */
  /*  SUPPLIER TYPE                                                           */
  /* ------------------------------------------------------------------------ */
  select AP_COMMISSION_GL_ACCOUNT,AP_COMMISSION_GL_DEPT,AP_COMMISSION_GL_COST from SYSPARAM
  into GL_ACCOUNT,GL_DEPT,GL_COST;
  
  SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;  
  ID = 1;
  DEBIT = TOTAL;
  CREDIT = 0;
  INFO = 'Voucher';
  ERROR_TEXT = '';
  SETUP_INFO = 'SYSPARAM';
  EXECUTE PROCEDURE INV_GLBUFFER_ERROR(SETUP_INFO,GL_ACCOUNT,GL_DEPT,GL_COST,SUPLTYPE,SUPLTYPE)
  RETURNING_VALUES ERROR_TEXT,SETUP_INFO;    
  SUSPEND;
  
END^


ALTER PROCEDURE AP_GLBUFFER_VCH_RECREATE(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER)
RETURNS (
    NUMBER INTEGER,
    OPENDATE DATE,
    INFO VARCHAR(20),
    SUPLTYPE VARCHAR(4),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER,
    ERROR_TEXT VARCHAR(128))
AS
declare variable USR VARCHAR(8);
DECLARE VARIABLE SOURCE CHAR(1);
BEGIN
  if (SDATE IS NULL) then
  BEGIN
     SDATE = '1.7.2005';
     EDATE = '31.7.2005';
     PSAVE = 0;
  END
  if (PSAVE = 1) then
  BEGIN
     DELETE FROM glbuffer
     WHERE APPLICATION = 'AP'
     AND SOURCE = 'VCH'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE;
     
     DELETE FROM GLTRANS
     WHERE APPLICATION = 'AP'
     AND SOURCE = 'VCH'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE
     AND ((CSOURCE='') OR (CSOURCE IS NULL)) /* 29 OCT 2007 */;
  END
  FOR SELECT NUMBER,OPENDATE,SOURCE,EDITUSER FROM APVCH
      WHERE OPENDATE BETWEEN :SDATE AND :EDATE
      AND SOURCE IN ('S','F')
      AND GLSTATUS = 'R'
  INTO :NUMBER,:OPENDATE,SOURCE,USR
  DO
  BEGIN
    /* ----------------------------------------------------------------  */
    /* FO AGENT COMMISSION                                               */
    /* ----------------------------------------------------------------  */
    IF (SOURCE = 'F') THEN
    BEGIN
      FOR
        SELECT INFO,TRANSDATE,ID,GL_ACCOUNT,GL_DEPT,
               GL_COST,ACCNAME,NOTE,REF,DEBIT,CREDIT,
               RELATION_CODE,RELATION_DOCTYPE,ERROR_TEXT
        FROM AP_GLBUFFER_VCH_COMMISSION(:NUMBER)
        INTO :INFO,:TRANSDATE,:ID,:GL_ACCOUNT,:GL_DEPT,
             :GL_COST,:ACCNAME,:NOTE,:REF,:DEBIT,:CREDIT,
             RELATION_CODE,RELATION_DOCTYPE,ERROR_TEXT
      DO
      BEGIN
         if (DEBIT + CREDIT <> 0) then
         BEGIN
           if (PSAVE = 1) then
           BEGIN
            insert into glbuffer
                   (APPLICATION,SOURCE,NUMBER,ID,transdate,
                    ACCOUNT,DEPT,COST,PROJECT,
                    NOTE,REF,
                    DB,CR,
                    EXPORTDATE,EXPORTUSER)
            values ('AP','VCH',:number,:ID,:opendate,
                    :GL_ACCOUNT,:GL_DEPT,:GL_COST,'',
                    :NOTE,:REF,
                    :DEBIT,:CREDIT,
                    'now',:USR);
            END
            ELSE
              SUSPEND;
         END
      END
    END
    ELSE
    /* ---------------------------------------------------------------- */
    /* SHARE REVENUE                                                    */
    /* ---------------------------------------------------------------- */
    IF (SOURCE  IN ('S','Z')) THEN /* 20 MAY 2009,Z = POS Share*/
    BEGIN
      FOR
        SELECT INFO,TRANSDATE,ID,GL_ACCOUNT,GL_DEPT,
               GL_COST,ACCNAME,NOTE,REF,DEBIT,CREDIT,
               RELATION_CODE,RELATION_DOCTYPE,ERROR_TEXT
        FROM AP_GLBUFFER_VCH_SHARE(:NUMBER)
        INTO :INFO,:TRANSDATE,:ID,:GL_ACCOUNT,:GL_DEPT,
             :GL_COST,:ACCNAME,:NOTE,:REF,:DEBIT,:CREDIT,
             RELATION_CODE,RELATION_DOCTYPE,ERROR_TEXT
      DO
      BEGIN
         if (DEBIT + CREDIT <> 0) then
         BEGIN
           if (PSAVE = 1) then
           BEGIN
            insert into glbuffer
                   (APPLICATION,SOURCE,NUMBER,ID,transdate,
                    ACCOUNT,DEPT,COST,PROJECT,
                    NOTE,REF,
                    DB,CR,
                    EXPORTDATE,EXPORTUSER)
            values ('AP','VCH',:number,:ID,:opendate,
                    :GL_ACCOUNT,:GL_DEPT,:GL_COST,'',
                    :NOTE,:REF,
                    :DEBIT,:CREDIT,
                    'now',:USR);
            END
            ELSE
              SUSPEND;
         END
      END
    END
  END

END^


ALTER PROCEDURE AP_GLBUFFER_VCH_SHARE(
    NUMBER INTEGER)
RETURNS (
    INFO VARCHAR(20),
    SUPLTYPE VARCHAR(4),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE SUPPLIER VARCHAR(6);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
BEGIN
  if (NUMBER IS NULL) then
  BEGIN
     NUMBER = 2;
  END
  /* ------------------------------------------------------------------------ */
  /*  VOCUCHER                                                                */
  /* ------------------------------------------------------------------------ */
  SELECT V.TEXT1, DOCUMENT, TOTAL, 
         V.SUPPLIER, V.OPENDATE, S.NAME, S.SUPLTYPE,
         S.RELATION_DOCTYPE,
         T.GLACCOUNT, T.GLDEPT, T.GLCOST
  FROM APVCH V
  LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = V.SUPPLIER
  LEFT JOIN SYSSUPPLIERTYPE T ON T.SUPPLIERTYPE = S.SUPLTYPE
  WHERE V.NUMBER = :NUMBER
  INTO NOTE, REF, TOTAL, 
       SUPPLIER, TRANSDATE, NOTE, SUPLTYPE,
       RELATION_DOCTYPE, GL_ACCOUNT, GL_DEPT, GL_COST;

  DEBIT = 0;
  CREDIT = TOTAL;
  INFO = 'Voucher';
  ERROR_TEXT = '';
  SETUP_INFO = 'SUPLTYPE';
  RELATION_CODE = :SUPPLIER;
  ID = 2;
  SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;
  EXECUTE PROCEDURE INV_GLBUFFER_ERROR(SETUP_INFO, GL_ACCOUNT, GL_DEPT, GL_COST, SUPLTYPE, SUPLTYPE)
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;  
  SUSPEND;
  /* ------------------------------------------------------------------------ */
  /*  SUPPLIER TYPE                                                           */
  /* ------------------------------------------------------------------------ */
  select AP_SHARE_GL_ACCOUNT, AP_SHARE_GL_DEPT, AP_SHARE_GL_COST from SYSPARAM
  into GL_ACCOUNT, GL_DEPT, GL_COST;
  
  SELECT NAME FROM GLCOA WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;  
  ID = 1;
  DEBIT = TOTAL;
  CREDIT = 0;
  INFO = 'Shared Revenue';
  ERROR_TEXT = '';
  SETUP_INFO = 'SYSPARAM';
  EXECUTE PROCEDURE INV_GLBUFFER_ERROR(SETUP_INFO, GL_ACCOUNT, GL_DEPT, GL_COST, SUPLTYPE, SUPLTYPE)
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;    
  SUSPEND;
  
END^


ALTER PROCEDURE AP_JOURNAL(
    SSUPPLIER VARCHAR(6),
    ESUPPLIER VARCHAR(6),
    SDATE DATE,
    EDATE DATE)
RETURNS (
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    SEQUENCE INTEGER,
    NUMBER INTEGER,
    VOUCHERNO INTEGER,
    DOCTYPE VARCHAR(6),
    OPENDATE DATE,
    DOCUMENT VARCHAR(20),
    TEXT1 VARCHAR(30),
    VOUCHER DOUBLE PRECISION,
    CASH DOUBLE PRECISION,
    ADJUST DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION)
AS
DECLARE VARIABLE DEPOSIT DOUBLE PRECISION;
begin
  if (SDATE IS NULL) then
  BEGIN
    SSUPPLIER = 'T003';
    ESUPPLIER = 'T003';
    SDATE = '1.5.2000';
    EDATE = '30.12.2003';
  END
  FOR SELECT SUPPLIER, NAME FROM SYSSUPPLIER
  WHERE SUPPLIER BETWEEN :SSUPPLIER AND :ESUPPLIER
  INTO :SUPPLIER, :NAME
  DO
  BEGIN
    DocType = 'Pre';
    Document = 'Previous Balance';
    OPENDATE = SDATE;
    SEQUENCE = 0;
    NUMBER = 0;
    VOUCHERNO = 0;
    VOUCHER = 0;
    CASH = 0;
    ADJUST = 0;
    DEPOSIT = 0;
    SELECT SUM(TOTAL) FROM APVCH WHERE SUPPLIER = :SUPPLIER AND OPENDATE < :SDATE
      INTO :VOUCHER;

    SELECT SUM(TOTAL-FOREX_GAINLOSS) FROM APCASH0 WHERE SUPPLIER = :SUPPLIER
      AND OPENDATE < :SDATE AND STATUS IN ('R','C','L')
      INTO CASH;

    SELECT SUM(TOTAL+VCH_GAINLOSS) FROM APDEPOS1  /* 5/24/2011 SELECT SUM(APDEPOS1.TOTAL) FROM APDEPOS1 */
     WHERE APDEPOS1.SUPPLIER = :SUPPLIER AND APDEPOS1.APPLIEDDATE < :SDATE
      AND APDEPOS1.STATUS IN ('R','C','L')
      INTO DEPOSIT;

    SELECT SUM(CR-DB) FROM APADJ WHERE SUPPLIER = :SUPPLIER
      AND OPENDATE < :SDATE AND STATUS IN ('R','C')
      INTO :ADJUST;
      
    IF (VOUCHER IS NULL) THEN VOUCHER = 0;
    IF (CASH    IS NULL) THEN CASH    = 0;
    IF (ADJUST  IS NULL) THEN ADJUST  = 0;
    IF (DEPOSIT IS NULL) THEN DEPOSIT = 0;
    TOTAL = VOUCHER - CASH + ADJUST - DEPOSIT;
    SUSPEND;
    DEPOSIT = 0;
     
    FOR
      SELECT NUMBER, (CAST('VCH' AS VARCHAR(6))) DOCTYPE,
             NUMBER VOUCHERNO,
             OPENDATE,
             DOCUMENT,
             TOTAL VOUCHER,
             CAST(0 AS DOUBLE PRECISION) CASH,
             CAST(0 AS DOUBLE PRECISION) ADJUST,
             TOTAL
        FROM APVCH
        WHERE SUPPLIER = :SUPPLIER AND OPENDATE BETWEEN :SDATE AND :EDATE
        
      union
      
      SELECT D.NUMBER, CAST('CASH' AS VARCHAR(6)),
             D.VOUCHERNO,
             H.OPENDATE,
             H.DOCUMENT,
             CAST(0 AS DOUBLE PRECISION) VOUCHER,
             D.TOTAL-D.VCH_GAINLOSS CASH,
             CAST(0 AS DOUBLE PRECISION) ADJUST,
             -(D.TOTAL-D.VCH_GAINLOSS) TOTAL
         FROM APCASH1 D
        INNER JOIN APCASH0 H ON H.NUMBER = D.NUMBER
         WHERE H.SUPPLIER = :SUPPLIER AND H.OPENDATE BETWEEN :SDATE AND :EDATE
         AND H.STATUS IN ('R','L','C')
         
       union
       
       SELECT NUMBER,  CAST('ADJ' AS VARCHAR(6)),
              VOUCHERNO,
              OPENDATE,
              DOCUMENT,
              CAST(0 AS DOUBLE PRECISION) VOUCHER,
              CAST(0 AS DOUBLE PRECISION) CASH,
              (CR-DB) ADJUST,
              (CR-DB)
          FROM APADJ
         WHERE SUPPLIER = :SUPPLIER
         AND OPENDATE BETWEEN :SDATE AND :EDATE
         AND STATUS IN ('R','C')
  
    union
    
       SELECT NUMBER,  CAST('DEP' AS VARCHAR(6)),
              VOUCHERNO,
              APPLIEDDATE,
              CAST('' AS VARCHAR(20)),
              -(TOTAL+VCH_GAINLOSS),
              CAST(0 AS DOUBLE PRECISION),
              CAST(0 AS DOUBLE PRECISION),
              -(TOTAL+VCH_GAINLOSS)
          FROM APDEPOS1
         WHERE SUPPLIER = :SUPPLIER
         AND APPLIEDDATE BETWEEN :SDATE AND :EDATE
         AND STATUS IN ('R','C')
  
         
    into NUMBER, DOCTYPE, VOUCHERNO, OPENDATE, DOCUMENT, VOUCHER, CASH, ADJUST, TOTAL
    DO
    BEGIN
      SUSPEND;
      sequence = number;
      if (doctype = 'Vch') then sequence = 0;
    END
  end
end^


ALTER PROCEDURE AP_MUTATION(
    SSUPPLIER VARCHAR(6),
    ESUPPLIER VARCHAR(6))
RETURNS (
    CREDITCARD INTEGER,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    OPENING NUMERIC(15,4),
    VOUCHER NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    ENDING NUMERIC(15,4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable sDate date;
declare variable eDate date;
declare variable fo_adjust double precision;
declare variable pcash double precision;
declare variable REFDATE DATE;
declare variable XDEPOSIT DOUBLE PRECISION;
declare variable vrow integer;
declare variable adjust1 double precision;
begin
/*  SSUPPLIER = 'PAKTA';
  ESUPPLIER = 'PAKTA';
*/
  CREDITCARD = 0;
  select apsysdate from sysparam into :REFDATE;

  if (SSUPPLIER IS NULL) then BEGIN
     SSUPPLIER = 'NS0005';
     eSUPPLIER = 'NS0005';
  END
  execute procedure sp_beginofmonth (refdate) returning_values sDate;
  execute procedure sp_endofmonth   (refdate) returning_values eDate;
  
  for select SUPPLIER, name from sysSUPPLIER
  where SUPPLIER between :sSUPPLIER and :eSUPPLIER
  into :SUPPLIER, name
  do
  begin
    opening = 0;
    voucher = 0;
    cash = 0;
    adjust = 0;
    ending = 0;
    adjust1 = 0;
    /*========================================================================*/
    /* hitung ending                                                          */
    /*========================================================================*/
    select sum(totaldue) from APvch
     where SUPPLIER = :SUPPLIER 
      into ending;
    /*========================================================================*/
    /* hitung bulan ini                                                       */
    /*========================================================================*/
    select SUM(TOTAL) from APvch   where SUPPLIER = :SUPPLIER
       and OpenDate between :sDate and :eDate
      into :voucher;
      
    select sum(APdepos1.total) from APdepos1
     where APdepos1.SUPPLIER = :SUPPLIER
       and APdepos1.APPlieddate between :sDate and :eDate
      into deposit;

    select sum(total) from APcash0 where SUPPLIER = :SUPPLIER
       and DueDate between :sDate and :eDate
       and status in ('C','L', 'R')
      into :cash;

    select sum(db-cr) from APadj   where SUPPLIER = :SUPPLIER
       and OpenDate between :sDate and :eDate
       and status in ('C', 'R')
      into :adjust1;
    
    if (ending  is null) then ending  = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;
    if (deposit is null) then deposit = 0;
    adjust = adjust + adjust1 - deposit;
    opening = ending - voucher + cash - adjust;
    if (ending+opening + voucher + cash + adjust <> 0) then
       suspend;
  end
end^


ALTER PROCEDURE AP_MUTATION_OLD(
    SSUPPLIER VARCHAR(6),
    ESUPPLIER VARCHAR(6),
    REFDATE DATE)
RETURNS (
    PREFDATE DATE,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    CODETYPE VARCHAR(40),
    NAMETYPE VARCHAR(40),
    GL_ACCOUNT VARCHAR(40),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    OPENING NUMERIC(15,4),
    VOUCHER NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    ENDING NUMERIC(15,4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable sDate date;
declare variable eDate date;
begin
  if (SSUPPLIER IS NULL) then
  BEGIN
     SSUPPLIER = 'R003';
     ESUPPLIER = 'R003';
     REFDATE   = '1.4.2005';
  END
  PREFDATE = REFDATE;

  execute procedure SP_DATE_BOM (refdate) returning_values sDate;
  execute procedure SP_DATE_EOM (refdate) returning_values eDate;

  for select A.supplier, A.name, A.SUPLTYPE, T.NAME,
             T.GLACCOUNT, T.GLDEPT, T.GLCOST, COA.NAME
      from syssupplier A
      LEFT JOIN SYSSUPPLIERTYPE T ON T.SUPPLIERTYPE=A.SUPltype
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.GLACCOUNT
  where supplier between :ssupplier and :esupplier
  into :supplier, name,CODETYPE,NAMETYPE,
       GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME
  do
  begin
    opening = 0;
    voucher = 0;
    cash = 0;
    adjust = 0;
    ending = 0;
    /*========================================================================*/
    /* hitung opening                                                         */
    /*========================================================================*/
    select sum(total) from apvch   where supplier = :supplier and OpenDate < :sDate
      plan (apvch index (APVCH_IDX_SUPPLIER_DATE))
      into voucher;

    select sum(total-forex_gainloss) from apcash0 where supplier = :supplier and DueDate < :sDate /* harus duedate */
       and status in ('R','C','L')
    plan (apcash0 index (APCASH0_IDX_SUPPLIER_DUEDATE))
    into cash;

    select sum(total+vch_gainloss) from apdepos1  /* 5/24/2011 select sum(apdepos1.total) from apdepos1 */
     where apdepos1.supplier = :supplier and apdepos1.applieddate < :sDate
      and apdepos1.status in ('R','C','L')
      into deposit;

    select sum(cr-db) from apadj   where supplier = :supplier and OpenDate < :sDate
      and status in ('R','C') /* 27 JULY 2007 ,'O') */
      plan (apadj index (APADJ_IDX_SUPPLIER_OPENDATE))
      into adjust;


    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (deposit is null) then deposit = 0;
    opening = voucher - cash + adjust - deposit;

    /*========================================================================*/
    /* hitung bulan ini                                                       */
    /*========================================================================*/
    voucher = 0;
    cash    = 0;
    adjust  = 0;
    deposit = 0;
    select sum(total) from apvch   where supplier = :supplier
       and OpenDate between :sDate and :eDate
      plan (apvch index (APVCH_IDX_SUPPLIER_DATE))
      into :voucher;

    select sum(total+VCH_GAINLOSS) from apdepos1  /* 5/24/2011 select sum(apdepos1.total) from apdepos1 */
     where apdepos1.supplier = :supplier and apdepos1.applieddate between :sDate and :eDate
       and apdepos1.status in ('R','C')
      into deposit;

    select sum(total-forex_gainloss) from apcash0 where supplier = :supplier
       and DueDate between :sDate and :eDate /* harus due date */
       and status in ('R','C', 'L')
      plan (apcash0 index (APCASH0_IDX_SUPPLIER_DUEDATE))
      into :cash;

    select sum(cr-db) from apadj
     where supplier = :supplier
       and OpenDate between :sDate and :eDate
       and status in ('R','C') /* 27 JULY 2007,'O') */
      plan (apadj index (APADJ_IDX_SUPPLIER_OPENDATE))
      into :adjust;


    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (deposit is null) then deposit = 0;
    adjust = adjust - deposit;
    ending = opening + voucher - cash + adjust;
    if ((opening <> 0)  or (voucher <> 0) or (cash  <> 0) or (adjust <> 0) or (ending <> 0)) then
    begin
       suspend;
    end
  end
end^


ALTER PROCEDURE AP_PURGE(
    FLAG_DELETE INTEGER,
    USRID VARCHAR(8))
RETURNS (
    VOUCHERNO INTEGER,
    LISTINDEX INTEGER,
    NUMBER INTEGER,
    DOCTYPE VARCHAR(6),
    DOCUMENT VARCHAR(20),
    OPENDATE DATE,
    DUEDATE DATE,
    SOURCE CHAR(1),
    SOURCENUMBER INTEGER,
    TOTAL DOUBLE PRECISION,
    VOUCHER DOUBLE PRECISION,
    ADJUST DOUBLE PRECISION,
    CASH DOUBLE PRECISION,
    DEPOSIT DOUBLE PRECISION,
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    TEXT1 VARCHAR(40),
    PURGE_BATCH INTEGER)
AS
DECLARE VARIABLE TOT_VOUCHER DOUBLE PRECISION;
DECLARE VARIABLE TOT_CASH DOUBLE PRECISION;
DECLARE VARIABLE TOT_ADJUST DOUBLE PRECISION;
begin
   IF (FLAG_DELETE IS NULL) THEN FLAG_DELETE = 0;
   /* ---------------------------------------------------------------- */
   /* GET BATCH NUMBER                                                 */
   /* ---------------------------------------------------------------- */
   SELECT MAX(PURGE_BATCH) FROM APPURGE INTO PURGE_BATCH;
   IF (PURGE_BATCH IS NULL) THEN PURGE_BATCH = 0;
   PURGE_BATCH = PURGE_BATCH + 1;
   /* ---------------------------------------------------------------- */
   /* CHECK TOTAL DELETED HARUS NOL                                    */
   /* ---------------------------------------------------------------- */
   IF (FLAG_DELETE = 1) THEN
   BEGIN
      SELECT SUM(TOTAL) FROM AP_PURGE(0,'?') INTO TOTAL;
      IF (TOTAL NOT BETWEEN -1 AND 1) THEN
      BEGIN
         EXCEPTION ALL_NEGATIVE_VALUE;
      END
   END
   /* ---------------------------------------------------------------- */
   /* SUSPEND OR INSERT                                                */
   /* ---------------------------------------------------------------- */
   FOR SELECT V.NUMBER, V.NUMBER, V.DOCUMENT, V.OPENDATE, V.DUEDATE,
           V.SOURCE, V.RECEIVINGNO, V.TOTAL, V.EXCHANGE, V.CURRENCY,
           V.SUPPLIER, S.NAME, V.TEXT1
    FROM APVCH V
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = V.SUPPLIER
    WHERE STATUS = 'D'
    ORDER BY V.NUMBER
   INTO VOUCHERNO, NUMBER, DOCUMENT, OPENDATE, DUEDATE,
        SOURCE, SOURCENUMBER, TOTAL, EXCHANGE, CURRENCY,
        SUPPLIER, NAME, TEXT1
   DO
   BEGIN
      DOCTYPE = 'Vch';
      ADJUST = 0;
      CASH = 0;
      DEPOSIT = 0;
      VOUCHER = TOTAL;
      LISTINDEX = 0;
      IF (FLAG_DELETE <> 1) THEN SUSPEND;
      ELSE
      BEGIN
        INSERT INTO APPURGE (VOUCHERNO, NUMBER, DOCTYPE, DOCUMENT, LISTINDEX,
                            OPENDATE, DUEDATE, SOURCE, SOURCENUMBER,
                            TOTAL, VOUCHER, ADJUST, CASH, DEPOSIT,
                            SUPPLIER, NAME, TEXT1,
                            DELETEDATE, DELETEUSER, PURGE_BATCH)
        VALUES (:VOUCHERNO, :NUMBER, :DOCTYPE, :DOCUMENT, :LISTINDEX,
                :OPENDATE, :DUEDATE, :SOURCE, :SOURCENUMBER,
                :TOTAL, :VOUCHER, :ADJUST, :CASH, :DEPOSIT,
                :SUPPLIER, :NAME, :TEXT1,
                'NOW',:USRID,:PURGE_BATCH);
      END
      VOUCHER = 0;
      /* ---------------------------------------------------------------- */
      /* ADJUSTMENT                                                       */
      /* ---------------------------------------------------------------- */
      DOCTYPE = 'Adj';
      FOR SELECT D.NUMBER, D.OPENDATE, D.OPENDATE,
                 D.DOCUMENT, D.TEXT1,
                 D.CR-D.DB, D.EXCHANGE,
                 SOURCENUMBER, SOURCE
          FROM APADJ D
          WHERE D.VOUCHERNO = :VOUCHERNO
      INTO NUMBER, OPENDATE, DUEDATE,
           DOCUMENT, TEXT1,
           TOTAL, EXCHANGE,
           SOURCENUMBER, SOURCE
      DO
      BEGIN
         IF (SOURCE IS NULL) THEN
         BEGIN
            SOURCE = '';
            SOURCENUMBER = 0;
         END
         ADJUST = TOTAL;
         LISTINDEX = LISTINDEX + 1;
         IF (FLAG_DELETE <> 1) THEN SUSPEND;
         ELSE
         BEGIN
           INSERT INTO APPURGE (VOUCHERNO, NUMBER, DOCTYPE, DOCUMENT, LISTINDEX,
                               OPENDATE, DUEDATE, SOURCE, SOURCENUMBER,
                               TOTAL, VOUCHER, ADJUST, CASH, DEPOSIT,
                               SUPPLIER, NAME, TEXT1,
                               DELETEDATE, DELETEUSER, PURGE_BATCH)
           VALUES (:VOUCHERNO, :NUMBER, :DOCTYPE, :DOCUMENT, :LISTINDEX,
                   :OPENDATE, :DUEDATE, :SOURCE, :SOURCENUMBER,
                   :TOTAL, :VOUCHER, :ADJUST, :CASH, :DEPOSIT,
                   :SUPPLIER, :NAME, :TEXT1,
                   'NOW',:USRID,:PURGE_BATCH);
         END
      END
      ADJUST = 0;
      /* ---------------------------------------------------------------- */
      /* CASH PAYMENT                                                     */
      /* ---------------------------------------------------------------- */
      SOURCENUMBER = 0;
      SOURCE = '';
      DOCTYPE = 'Pym';
      FOR SELECT D.NUMBER, H.OPENDATE, H.DUEDATE,
                 H.DOCUMENT, H.CHECK_NUMBER,
                 D.VCH_TOTAL, H.EXCHANGE
          FROM APCASH1 D
          LEFT JOIN APCASH0 H ON H.NUMBER = D.NUMBER
          WHERE D.VOUCHERNO = :VOUCHERNO
      INTO NUMBER, OPENDATE, DUEDATE,
           DOCUMENT, TEXT1,
           TOTAL, EXCHANGE
      DO
      BEGIN
         CASH = TOTAL;
         TOTAL = -TOTAL;
         LISTINDEX = LISTINDEX + 1;
         IF (FLAG_DELETE <> 1) THEN SUSPEND;
         ELSE
         BEGIN
           INSERT INTO APPURGE (VOUCHERNO, NUMBER, DOCTYPE, DOCUMENT, LISTINDEX,
                               OPENDATE, DUEDATE, SOURCE, SOURCENUMBER,
                               TOTAL, VOUCHER, ADJUST, CASH, DEPOSIT,
                               SUPPLIER, NAME, TEXT1,
                               DELETEDATE, DELETEUSER, PURGE_BATCH)
           VALUES (:VOUCHERNO, :NUMBER, :DOCTYPE, :DOCUMENT, :LISTINDEX,
                   :OPENDATE, :DUEDATE, :SOURCE, :SOURCENUMBER,
                   :TOTAL, :VOUCHER, :ADJUST, :CASH, :DEPOSIT,
                   :SUPPLIER, :NAME, :TEXT1,
                   'NOW',:USRID,:PURGE_BATCH);
         END
      END
      CASH = 0;
   END
   /* ---------------------------------------------------------------- */
   /* DELETE                                                           */
   /* ---------------------------------------------------------------- */
   IF (FLAG_DELETE = 1) THEN
   BEGIN
      DELETE FROM APADJ   WHERE STATUS = 'D';
      DELETE FROM APCASH0 WHERE STATUS = 'D';
      DELETE FROM APVCH   WHERE STATUS = 'D';
   END
end^


ALTER PROCEDURE AP_PURGE_1(
    SDATE DATE)
RETURNS (
    N INTEGER)
AS
DECLARE VARIABLE NUMBER INTEGER;
DECLARE VARIABLE VOUCHERNO INTEGER;
DECLARE VARIABLE CASH_TOT DOUBLE PRECISION;
DECLARE VARIABLE CASH_DET DOUBLE PRECISION;
begin
  IF (SDATE IS NULL) THEN SDATE = '31.5.2006';

  UPDATE APVCH   SET STATUS = 'C' WHERE STATUS = 'D';
  UPDATE APADJ   SET STATUS = 'C' WHERE STATUS = 'D';
  UPDATE APCASH0 SET STATUS = 'C' WHERE STATUS = 'D';


  FOR SELECT NUMBER, TOTAL FROM APCASH0 WHERE OPENDATE <= :SDATE
      INTO NUMBER, CASH_TOT
  DO
  BEGIN
     SELECT SUM(TOTAL) FROM APCASH1 WHERE NUMBER = :NUMBER INTO CASH_DET;
     
     IF (CASH_TOT = CASH_DET) THEN
     BEGIN
        IF (NOT EXISTS(SELECT * FROM APCASH1 D LEFT JOIN APVCH V ON V.NUMBER = D.VOUCHERNO
                   WHERE (D.NUMBER = :NUMBER)
                     AND ((V.PAIDSTATUS <> 'P')
                         OR (V.FOREX_PAID - D.FOREX_TOTAL NOT BETWEEN -0.05 AND 0.05)))) THEN
        BEGIN
          FOR SELECT VOUCHERNO FROM APCASH1 WHERE NUMBER = :NUMBER
              INTO VOUCHERNO
          DO
          BEGIN
             UPDATE APVCH SET STATUS = 'D' WHERE NUMBER    = :VOUCHERNO;
             UPDATE APADJ SET STATUS = 'D' WHERE VOUCHERNO = :VOUCHERNO;
          END
          UPDATE APCASH0 SET STATUS = 'D' WHERE NUMBER = :NUMBER;
        END
     END
  END
end^


ALTER PROCEDURE AP_RPT_ADJUST_BALANCE(
    PYEAR INTEGER,
    PMONTH INTEGER,
    PACCOUNT VARCHAR(20),
    PDEPT VARCHAR(4),
    PCOST VARCHAR(4))
RETURNS (
    NUMBER INTEGER,
    DOCUMENT VARCHAR(20),
    OPENDATE DATE,
    ACCOUNT VARCHAR(20),
    DEPT VARCHAR(4),
    COST VARCHAR(4),
    TEXT1 VARCHAR(40),
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    OPENING DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION,
    ACCNAME VARCHAR(50),
    GDEPTNAME VARCHAR(20),
    GCOSTNAME VARCHAR(20))
AS
declare variable SDATE DATE;
declare variable EDATE DATE;
BEGIN
  if (pyear is null) then
  begin
     pyear = 2004;
     pmonth = 11;
     paccount = '0402';
     pdept = '10';
     pcost = '050';
  end
  
  SELECT OPENING FROM GLACC A
  WHERE A.PYEAR = :PYEAR
    AND A.PMONTH = :PMONTH
    AND A.ACCOUNT = :PACCOUNT
    AND A.DEPART = :PDEPT
    AND A.COST = :PCOST
    INTO OPENING;

  if (OPENING IS NULL) then OPENING = 0;
  
  SDATE = '1.'||PMONTH || '.'||PYEAR;
  execute procedure sp_endofmonth(SDATE) returning_values EDATE;
  FOR
    SELECT A.NUMBER, A.DOCUMENT, A.OPENDATE,
    A.ACCOUNT, A.DEPT, A.COST,
    A.TEXT1, A.DB, A.CR, A.SUPPLIER,
    S.NAME, GA.NAME,
    GD.NAME, GC.NAME
    FROM APADJ A
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = A.SUPPLIER
    LEFT JOIN GLCOA GA ON A.ACCOUNT = GA.ACCOUNT
    LEFT JOIN GLDEPT GD ON A.DEPT = GD.DEPART
    LEFT JOIN GLCOST GC ON A.COST = GC.COST
    WHERE A.OPENDATE BETWEEN :SDATE AND :EDATE
    AND A.ACCOUNT = :PACCOUNT
    AND A.DEPT = :PDEPT
    AND A.COST = :PCOST
    AND A.STATUS IN ('R','C')
    order by A.OPENDATE, A.NUMBER
    INTO
      :NUMBER,
      :DOCUMENT,
      :OPENDATE,
      :ACCOUNT,
      :DEPT,
      :COST,
      :TEXT1,
      :CR,
      :DB,
      :SUPPLIER,
      :NAME,
      :ACCNAME,
      :GDEPTNAME,
      :GCOSTNAME
  DO
  BEGIN
    BALANCE = OPENING - DB + CR;
    SUSPEND;
    OPENING = BALANCE;
  END
END^


ALTER PROCEDURE AP_RPT_MUTATION_GL(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    AP_OPEN DOUBLE PRECISION,
    AP_ENDING DOUBLE PRECISION,
    AP_MUTATION DOUBLE PRECISION,
    GL_OPEN DOUBLE PRECISION,
    GL_ENDING DOUBLE PRECISION,
    GL_MUTATION DOUBLE PRECISION,
    ACCNAME VARCHAR(40),
    DELTA_OPEN DOUBLE PRECISION,
    DELTA_ENDING DOUBLE PRECISION,
    DELTA_MUTATION DOUBLE PRECISION,
    DELTA_OPEN_ENDING DOUBLE PRECISION,
    AP_VOUCHER DOUBLE PRECISION,
    AP_DEPOSIT DOUBLE PRECISION,
    AP_CASH DOUBLE PRECISION,
    AP_ADJUST DOUBLE PRECISION,
    GL_VOUCHER DOUBLE PRECISION,
    GL_DEPOSIT DOUBLE PRECISION,
    GL_CASH DOUBLE PRECISION,
    GL_ADJUST DOUBLE PRECISION,
    DELTA_VOUCHER DOUBLE PRECISION,
    DELTA_DEPOSIT DOUBLE PRECISION,
    DELTA_CASH DOUBLE PRECISION,
    DELTA_ADJUST DOUBLE PRECISION)
AS
DECLARE VARIABLE REFDATE DATE;
BEGIN
  if (PYEAR IS NULL) then
  BEGIN
     SELECT APSYSDATE FROM SYSPARAM INTO REFDATE;
     PYEAR = 2005;
     PMONTH = 8;
  END
  REFDATE = '1.'||PMONTH||'.'||PYEAR;
  FOR
    SELECT T.GLACCOUNT,T.GLDEPT,T.GLCOST,
           SUM(M.OPENING),
           SUM(M.ENDING-M.OPENING),/* 21 JULI 2006 */
           SUM(M.ENDING),SUM(M.VOUCHER),SUM(M.DEPOSIT),SUM(M.CASH),SUM(M.ADJUST)
    FROM AP_MUTATION_OLD('','zzzzzz',:REFDATE) M
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = M.SUPPLIER
    LEFT JOIN SYSSUPPLIERTYPE T ON T.SUPPLIERTYPE = S.SUPLTYPE
    GROUP BY T.GLACCOUNT,T.GLDEPT,T.GLCOST
    INTO
      :GL_ACCOUNT,
      :GL_DEPT,
      :GL_COST,
      :AP_OPEN,
      :AP_MUTATION,
      :AP_ENDING,
      :AP_VOUCHER,AP_DEPOSIT,AP_CASH,AP_ADJUST
  DO
  BEGIN
    SELECT NAME FROM GLCOA
    WHERE ACCOUNT = :GL_ACCOUNT INTO ACCNAME;

    SELECT SUM(OPENING),SUM(ENDING),SUM(ENDING-OPENING)
    FROM GLACC
    WHERE PYEAR  = :PYEAR
    AND PMONTH   = :PMONTH
    AND ACCOUNT  = :GL_ACCOUNT
    AND DEPART   = :GL_DEPT
    AND COST    = :GL_COST
    INTO GL_OPEN,GL_ENDING,GL_MUTATION;

    if (GL_OPEN IS NULL) then
    BEGIN
       GL_OPEN = 0;
       GL_ENDING = 0;
       GL_MUTATION = 0;
    END
    DELTA_OPEN = AP_OPEN - GL_OPEN;
    DELTA_ENDING = AP_ENDING - GL_ENDING;
    DELTA_MUTATION = AP_MUTATION - GL_MUTATION;
    DELTA_OPEN_ENDING = DELTA_OPEN - DELTA_ENDING;
    /* ---------------------------------------------------------------- */
    /* AP VOUCHER DI GL                                                 */
    /* ---------------------------------------------------------------- */
    SELECT SUM(CR-DB)
    FROM GLJUR
    WHERE PYEAR  = :PYEAR
    AND PMONTH   = :PMONTH
    AND ACCOUNT  = :GL_ACCOUNT
    AND DEPART   = :GL_DEPT
    AND COST    = :GL_COST
    AND APPLICATION = 'INV'
    AND SOURCE = 'RECV'
    INTO GL_VOUCHER;
    IF (GL_VOUCHER IS NULL) THEN GL_VOUCHER = 0;
    /* ---------------------------------------------------------------- */
    /* AP DEPOSIT DI GL                                                 */
    /* ---------------------------------------------------------------- */
    SELECT SUM(DB-CR)
    FROM GLJUR
    WHERE PYEAR  = :PYEAR
    AND PMONTH   = :PMONTH
    AND ACCOUNT  = :GL_ACCOUNT
    AND DEPART   = :GL_DEPT
    AND COST    = :GL_COST
    AND APPLICATION = 'AP'
    AND SOURCE = 'DEP1'
    INTO GL_DEPOSIT;
    IF (GL_DEPOSIT IS NULL) THEN GL_DEPOSIT = 0;
    /* ---------------------------------------------------------------- */
    /* AP CASH DI GL                                                   */
    /* ---------------------------------------------------------------- */
    SELECT SUM(DB-CR)
    FROM GLJUR
    WHERE PYEAR  = :PYEAR
    AND PMONTH   = :PMONTH
    AND ACCOUNT  = :GL_ACCOUNT
    AND DEPART   = :GL_DEPT
    AND COST    = :GL_COST
    AND APPLICATION = 'AP'
    AND SOURCE = 'CASH'
    INTO GL_CASH;
    IF (GL_CASH IS NULL) THEN GL_CASH = 0;
    /* ---------------------------------------------------------------- */
    /* AP CASH DI GL                                                   */
    /* ---------------------------------------------------------------- */
    SELECT SUM(CR-DB)
    FROM GLJUR
    WHERE PYEAR  = :PYEAR
    AND PMONTH   = :PMONTH
    AND ACCOUNT  = :GL_ACCOUNT
    AND DEPART   = :GL_DEPT
    AND COST    = :GL_COST
    AND APPLICATION = 'AP'
    AND SOURCE = 'ADJ'
    INTO GL_ADJUST;
    IF (GL_ADJUST IS NULL) THEN GL_ADJUST = 0;
    AP_ADJUST = AP_ADJUST + AP_DEPOSIT;
    DELTA_VOUCHER = AP_VOUCHER - GL_VOUCHER;
    DELTA_DEPOSIT = AP_DEPOSIT - GL_DEPOSIT;
    DELTA_CASH    = AP_CASH    - GL_CASH;
    DELTA_ADJUST  = AP_ADJUST  - GL_ADJUST;
    /* ---------------------------------------------------------------- */
    if ((AP_OPEN<>0) OR (AP_ENDING <>0) OR (AP_MUTATION <>0) OR
        (GL_OPEN<>0)  OR (GL_ENDING <>0)  OR (GL_MUTATION <>0)) THEN
    SUSPEND;
  END
END^


ALTER PROCEDURE AP_VCH_FORM(
    VCH_NUMBER INTEGER)
RETURNS (
    NUMBER INTEGER,
    CURRENCY VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DBCR VARCHAR(2),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION,
    EXCHANGE DOUBLE PRECISION,
    FOREX_DEBIT DOUBLE PRECISION,
    FOREX_CREDIT DOUBLE PRECISION,
    FOREX_BALANCE DOUBLE PRECISION,
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
declare variable USR VARCHAR(8);
DECLARE VARIABLE VCH_GAINLOSS DOUBLE PRECISION;
DECLARE VARIABLE SOURCE VARCHAR(1);
BEGIN
  if (VCH_NUMBER IS NULL) then
  BEGIN
     VCH_NUMBER = 5225;
  END

  SELECT SOURCE, RECEIVINGNO, CURRENCY, FOREX_GAINLOSS FROM APVCH
  WHERE NUMBER = :VCH_NUMBER
  INTO :SOURCE, :NUMBER, CURRENCY, VCH_GAINLOSS;
  
  IF (SOURCE = 'F') THEN
  BEGIN
     NUMBER = VCH_NUMBER;
     FOR SELECT INFO, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
           GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
           RELATION_CODE, RELATION_DOCTYPE
         FROM AP_GLBUFFER_VCH_COMMISSION(:VCH_NUMBER)
         WHERE (INFO <> 'Voucher')
         INTO :INFO, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
              :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
              RELATION_CODE, RELATION_DOCTYPE
            
     DO
     BEGIN
        BALANCE = DEBIT - CREDIT;
        IF ((EXCHANGE IS NULL) OR (EXCHANGE = 0)) THEN EXCHANGE = 1;
        FOREX_DEBIT = DEBIT / EXCHANGE;
        FOREX_CREDIT = CREDIT / EXCHANGE;
        FOREX_BALANCE = FOREX_DEBIT - FOREX_CREDIT;
        DBCR = 'DB';
        SUSPEND;
     END
  END
  ELSE
  /* ---------------------------------------------------------------- */
  /* SHARE REVENUE                                                    */
  /* ---------------------------------------------------------------- */
  IF (SOURCE  IN ('S', 'Z')) THEN /* 20 MAY 2009, Z = POS SHARE REVENUE */
  BEGIN
     NUMBER = VCH_NUMBER;
     FOR SELECT INFO, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
           GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
           RELATION_CODE, RELATION_DOCTYPE
         FROM AP_GLBUFFER_VCH_SHARE(:VCH_NUMBER)
         WHERE (INFO <> 'Voucher')
         INTO :INFO, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
              :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
              RELATION_CODE, RELATION_DOCTYPE
     DO
     BEGIN
        BALANCE = DEBIT - CREDIT;
        IF ((EXCHANGE IS NULL) OR (EXCHANGE = 0)) THEN EXCHANGE = 1;
        FOREX_DEBIT = DEBIT / EXCHANGE;
        FOREX_CREDIT = CREDIT / EXCHANGE;
        FOREX_BALANCE = FOREX_DEBIT - FOREX_CREDIT;
        DBCR = 'DB';
        SUSPEND;
     END
  END
  ELSE
  BEGIN
     /* ======================================================================== */
     /* RECEVING JOURNAL                                                         */
     /* ======================================================================== */
     FOR
       SELECT INFO, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
              GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
              RELATION_CODE, RELATION_DOCTYPE
       FROM INV_GLBUFFER_RECV(:NUMBER)
       WHERE (INFO <> 'A/P')
       INTO :INFO, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
            :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
            RELATION_CODE, RELATION_DOCTYPE
     DO
     BEGIN
        if (DEBIT + CREDIT <> 0) then
        BEGIN
           SELECT EXCHANGE FROM INVRECV0 WHERE NUMBER = :NUMBER INTO EXCHANGE;
           BALANCE = DEBIT - CREDIT;
           IF ((EXCHANGE IS NULL) OR (EXCHANGE = 0)) THEN EXCHANGE = 1;
           FOREX_DEBIT = DEBIT / EXCHANGE;
           FOREX_CREDIT = CREDIT / EXCHANGE;
           FOREX_BALANCE = FOREX_DEBIT - FOREX_CREDIT;
           DBCR = 'DB';
           SUSPEND;
        END
     END
     /* ======================================================================== */
     /* ADJUSTMENT                                                               */
     /* ======================================================================== */
     FOR SELECT NUMBER, OPENDATE, EDITUSER, EXCHANGE FROM APADJ
         WHERE VOUCHERNO = :VCH_NUMBER
     INTO NUMBER, :TRANSDATE, USR, EXCHANGE
     DO
     BEGIN
       FOR
         SELECT INFO, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
                GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
                RELATION_CODE, RELATION_DOCTYPE
         FROM ap_glbuffer_adjustment(:NUMBER)
         WHERE (INFO <> 'A/P')
         INTO :INFO, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
              :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
              RELATION_CODE, RELATION_DOCTYPE
       DO
       BEGIN
          if (DEBIT + CREDIT <> 0) then
          BEGIN
             IF (DEBIT <> 0) THEN DBCR = 'DB';
             ELSE DBCR = 'CR';

             BALANCE = DEBIT - CREDIT;
             IF ((EXCHANGE IS NULL) OR (EXCHANGE = 0)) THEN EXCHANGE = 1;
             FOREX_DEBIT = DEBIT / EXCHANGE;
             FOREX_CREDIT = CREDIT / EXCHANGE;
             FOREX_BALANCE = FOREX_DEBIT - FOREX_CREDIT;
             SUSPEND;
          END
       END
     END
  END /* END OF RECEIVING */
  IF (VCH_GAINLOSS <> 0) THEN
  BEGIN
     INFO = 'Gain/Loss';
     NUMBER = VCH_NUMBER;
     SELECT OPENDATE FROM APVCH WHERE NUMBER = :VCH_NUMBER INTO TRANSDATE;
     DEBIT = VCH_GAINLOSS;
     CREDIT = 0;
     BALANCE = DEBIT - CREDIT;
     FOREX_DEBIT = 0;
     FOREX_CREDIT = 0;
     FOREX_BALANCE = 0;
     NOTE = 'Loss & Gain';
     EXCHANGE = 0;
     DBCR = '';
     SELECT CFG.APFOREX_GAINLOSS_GLACCOUNT,
            CFG.APFOREX_GAINLOSS_GLDEPT, CFG.APFOREX_GAINLOSS_GLCOST,
            COA.NAME
     FROM SYSPARAM CFG
     LEFT JOIN GLCOA COA ON COA.ACCOUNT = CFG.APFOREX_GAINLOSS_GLACCOUNT
     WHERE CFG.ID = 1
     INTO GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME;
     CURRENCY = '';
     SUSPEND;
  END
END^


ALTER PROCEDURE AP_VCH_FORM_CASH(
    CASH_NUMBER INTEGER)
RETURNS (
    VCH_NUMBER INTEGER,
    VCH_SOURCE VARCHAR(20),
    VCH_OPENDATE DATE,
    VCH_EXCHANGE DOUBLE PRECISION,
    VCH_DOCUMENT VARCHAR(20),
    NUMBER INTEGER,
    CURRENCY VARCHAR(4),
    INFO VARCHAR(20),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DBCR VARCHAR(2),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION,
    EXCHANGE DOUBLE PRECISION,
    FOREX_DEBIT DOUBLE PRECISION,
    FOREX_CREDIT DOUBLE PRECISION,
    FOREX_BALANCE DOUBLE PRECISION,
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER,
    VCH_TEXT1 VARCHAR(40),
    VCH_TEXT2 VARCHAR(40),
    VCH_TEXT3 VARCHAR(40),
    VCH_NOTE VARCHAR(1000),
    VCH_RECEIVINGNO INTEGER)
AS
BEGIN
   IF ((CASH_NUMBER IS NULL) OR (CASH_NUMBER = 0)) THEN CASH_NUMBER = 1;

   FOR SELECT C.VOUCHERNO, V.SOURCE, V.OPENDATE, V.NOTE,
              V.TEXT1, V.TEXT2, V.TEXT3, V.EXCHANGE, V.DOCUMENT,
              V.RECEIVINGNO
       FROM APCASH1 C
       LEFT JOIN APVCH V ON V.NUMBER = C.VOUCHERNO
       WHERE C.NUMBER = :CASH_NUMBER
       INTO VCH_NUMBER, VCH_SOURCE, VCH_OPENDATE, VCH_NOTE,
            VCH_TEXT1, VCH_TEXT2, VCH_TEXT3, VCH_EXCHANGE, VCH_DOCUMENT,
            VCH_RECEIVINGNO
         DO
   BEGIN
    FOR SELECT NUMBER,
        CURRENCY,
        INFO,
        TRANSDATE,
        ID,
        GL_ACCOUNT,
        GL_DEPT,
        GL_COST,
        ACCNAME,
        NOTE,
        REF,
        DBCR,
        DEBIT,
        CREDIT,
        BALANCE,
        EXCHANGE,
        FOREX_DEBIT,
        FOREX_CREDIT,
        FOREX_BALANCE,
        RELATION_CODE,
        RELATION_DOCTYPE FROM AP_VCH_FORM(:VCH_NUMBER)
    INTO
        :NUMBER,
        :CURRENCY,
        :INFO,
        :TRANSDATE,
        :ID,
        :GL_ACCOUNT,
        :GL_DEPT,
        :GL_COST,
        :ACCNAME,
        :NOTE,
        :REF,
        :DBCR,
        :DEBIT,
        :CREDIT,
        :BALANCE,
        :EXCHANGE,
        :FOREX_DEBIT,
        :FOREX_CREDIT,
        :FOREX_BALANCE,
        :RELATION_CODE,
        :RELATION_DOCTYPE
    DO
    BEGIN
      IF (VCH_SOURCE = 'R') THEN VCH_SOURCE = 'Voucher';
      ELSE IF (VCH_SOURCE = 'M') THEN VCH_SOURCE = 'Adjustment';
      ELSE IF (VCH_SOURCE = 'D') THEN VCH_SOURCE = 'D/M';
      ELSE IF (VCH_SOURCE = 'C') THEN VCH_SOURCE = 'C/N';
      ELSE IF (VCH_SOURCE = 'F') THEN VCH_SOURCE = 'Commission';
      ELSE IF (VCH_SOURCE = 'S') THEN VCH_SOURCE = 'Sharing';
      SUSPEND;
    END
  END
END^


ALTER PROCEDURE AR_AGING(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8),
    DETAILFLAG INTEGER,
    CURRENCY VARCHAR(4))
RETURNS (
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    CURR NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4),
    TOTAL NUMERIC(15,4),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    DOCUMENT VARCHAR(20),
    SOURCEID INTEGER,
    SOURCE_REMARK VARCHAR(80),
    AGE INTEGER,
    CREDITCARD INTEGER,
    CUSTTYPE VARCHAR(4),
    TYPENAME VARCHAR(40))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable voucher double precision;
declare variable cash    double precision;
declare variable adjust  double precision;
declare variable depos   double precision;
declare variable FOAdjust double precision;

declare variable F_voucher double precision;
declare variable F_cash    double precision;
declare variable F_adjust  double precision;
declare variable F_depos   double precision;
declare variable F_FOAdjust double precision;
declare variable vPayDate Date;
declare variable ARDate DATE;
declare variable XDEPOSIT DOUBLE PRECISION;
declare variable CREDITLIMIT DOUBLE PRECISION;
begin
  /* Procedure Text */
/*  if ((SCUSTOMER IS NULL) or (SCUSTOMER || ECUSTOMER = '')) then BEGIN
     SCUSTOMER = '';
     ECUSTOMER = 'zzzzzz';
  END
*/
  if (DETAILFLAG IS NULL) then
      DETAILFLAG = 0;
      
  if (CURRENCY IS NULL) then CURRENCY = 'All';
  
  CREDITCARD = 0;
  
  SELECT ARSYSDATE+1 FROM SYSPARAM INTO ARDATE;
  
  for select CUSTOMER, name, CUSTTYPE, CREDITLIMIT from sysCUSTOMER
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER, name, CUSTTYPE, CREDITLIMIT
  do
  begin
    SELECT NAME FROM SYSCUSTOMERTYPE
    WHERE CUSTOMERTYPE = :CUSTTYPE
    INTO :TYPENAME;
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    end
    SOURCEID = 0;
    SOURCE_REMARK = '';
    opendate = null;
    duedate = null;
    document = null;
    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/
    for select number, totaldue, forex_totaldue,
               opendate, duedate, SOURCEID, SOURCE_REMARK, DOCUMENT
          from ARvch
         where PAIDSTATUS = 'O'
           AND CUSTOMER = :CUSTOMER
           and ((totaldue <> 0) or (forex_totaldue <> 0))
           and ((:CURRENCY = 'All') or (CURRENCY = :CURRENCY))
         PLAN (ARVCH INDEX (ARVCH_IDX_PAIDSTATUS))
         into number, voucher, f_voucher, opendate, duedate, SOURCEID, SOURCE_REMARK, DOCUMENT
    do
    begin
       if (CURRENCY <> 'All') then
          voucher = f_voucher;
       d = ARDate - opendate;
      /*======================================================================*/
      /* jika aging detail                                                    */
      /*======================================================================*/
       if (detailflag = 1) then
       begin
          curr = 0;
          over30 = 0;
          over60 = 0;
          over90 = 0;
       end
       if (d <= 30)      then curr   = curr + voucher;
       else if (d <= 60) then over30 = over30 + voucher;
       else if (d <= 90) then over60 = over60 + voucher;
       else over90 = over90 + voucher;
       /* ------------------------------------------------------------------- */
       /* detail aging (ada nomor vouchernya                                  */
       /* ------------------------------------------------------------------- */
       if (detailflag = 1) then
       begin
         age = d;
         total = curr + over30 + over60 + over90;
         if (total <> 0) then
            suspend;
       end
    end
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       total = curr + over30 + over60 + over90;
       number = 0;
       document = '';
       if (total <> 0) then
          suspend;
    end
  end
  /* ------------------------------------------------------------------------ */
  /* credit card journal                                                      */
  /* ------------------------------------------------------------------------ */
  CUSTTYPE = 'CARD';
  TYPENAME = 'Credit Card';
  if (CURRENCY <> 'All') then exit;
  TOTAL  = 0;
  NUMBER = 0;
  CREDITCARD = 1;
  CREDITLIMIT = 0;
  FOR SELECT CREDITCARD, NAME
      FROM AR_CARD
      where CREDITCARD between :sCUSTOMER and :eCUSTOMER
      INTO :CUSTOMER, :NAME
  DO BEGIN
    /* ---------------------------------------------------------------------- */
    /* summary                                                                */
    /* ---------------------------------------------------------------------- */
    if (DETAILFLAG <> 1) then  
    begin
       CURR   = 0;
       OVER30 = 0;
       OVER60 = 0;
       OVER90 = 0;
       for select jr.opendate, sum(jr.total)
             from ar_card_jur jr
            where CREDITCARD = :CUSTOMER
              and status = 'O'
          group by jr.opendate
            PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_STATUS))          
             into opendate, voucher
       do begin
          if (voucher is null) then voucher = 0;
          if (not (vPayDate is Null)) then voucher = 0;
          d = ARDate - opendate;
          if (d <= 30)      then curr   = curr + voucher;
          else if (d <= 60) then over30 = over30 + voucher;
          else if (d <= 90) then over60 = over60 + voucher;
          else over90 = over90 + voucher;
        end
        total = curr + over30 + over60 + over90;
        if (total <> 0) then suspend;
    end /* summary */
    /* ---------------------------------------------------------------------- */
    /* detail                                                                 */
    /* ---------------------------------------------------------------------- */
    if (DETAILFLAG = 1) then
    begin
       for select jr.number, jr.opendate, jr.total, jr.sourceid
             from ar_card_jur jr
            /*left outer join AR_CARD_BATCH b on ((Jr.batch = B.batch) and (jr.bank = B.Bank) and (jr.Outlet = B.Outlet) and (b.status <> 'O'))*/
            where CREDITCARD = :CUSTOMER
              and status = 'O'
             PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_STATUS))
             into number, opendate, voucher, sourceid
       do begin
          CURR   = 0;
          OVER30 = 0;
          OVER60 = 0;
          OVER90 = 0;
          if (voucher is null) then voucher = 0;
          if (not (vPayDate is Null)) then voucher = 0;
          AGE = ARDate - opendate;
          if (AGE <= 30)      then curr   = voucher;
          else if (AGE <= 60) then over30 = voucher;
          else if (AGE <= 90) then over60 = voucher;
          else over90 = voucher;
          total = curr + over30 + over60 + over90;
       end
    end /* detail  */
  end /* credit card */
end^


ALTER PROCEDURE AR_AGING_OLD(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8),
    REFDATE DATE,
    DETAILFLAG INTEGER,
    SOURCE VARCHAR(4),
    PRINT_COMPANY INTEGER,
    PRINT_CREDITCARD INTEGER)
RETURNS (
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    CUSTTYPE VARCHAR(4),
    TYPENAME VARCHAR(40),
    CURR DOUBLE PRECISION,
    OVER30 DOUBLE PRECISION,
    OVER60 DOUBLE PRECISION,
    OVER90 DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    CREDITCARD INTEGER)
AS
DECLARE VARIABLE ARSYSDATE DATE;
DECLARE VARIABLE X INTEGER;
declare variable CURRENCY VARCHAR(4);
BEGIN
  SELECT ARSYSDATE FROM FOSYSPARAM
  INTO ARSYSDATE;

  if ((SCUSTOMER IS NULL) or (SCUSTOMER || ECUSTOMER = '')) then BEGIN
     SCUSTOMER = '';
     ECUSTOMER = 'ZZZZZZ';
     REFDATE  = ARSYSDATE-1;
     DETAILFLAG = 0;
     PRINT_CREDITCARD = 1;
     PRINT_COMPANY = 1;
     CURRENCY = 'All';
/*     DELETE FROM AR_ZHIST_AGE WHERE ARDATE = :REFDATE;*/
  END
  /* JIKA DATE LEBIH BESAR DARI TANGGAL SYSTEM, RECALCULATE */
  if (REFDATE > ARSYSDATE) then
  BEGIN
    FOR select customer, name, CUSTTYPE, TYPENAME, curr, over30, over60, over90, total, CREDITCARD
        from ar_aging_old_calc(:SCUSTOMER,:ECUSTOMER,:REFDATE,0, 'All',:PRINT_COMPANY,:PRINT_CREDITCARD)
        INTO :CUSTOMER, :NAME, CUSTTYPE, TYPENAME, :CURR, :OVER30, :OVER60, :OVER90, :TOTAL, :CREDITCARD
    DO BEGIN
       SUSPEND;
    END
    EXIT;
  END
  /* JIKA TANGGAL LEBIH KECIL DARI TANGGAL SYSTEM AR, BACA DARI DATA */
  SELECT COUNT(*) FROM ar_zhist_age
  WHERE ARDATE = :REFDATE
  INTO X;
  /* SAVE TO HISTORY */
  if (X = 0) then
  BEGIN
    FOR select customer, name, curr, over30, over60, over90, CREDITCARD, TOTAL
        from ar_aging_old_calc('','zzzzzz',:REFDATE,0, :SOURCE,1,1)
        INTO :CUSTOMER, :NAME, :CURR, :OVER30, :OVER60, :OVER90, :CREDITCARD, :TOTAL
    DO BEGIN
       if ((TOTAL < -0.01) or (TOTAL > 0.01)) then
       BEGIN
          INSERT INTO AR_ZHIST_AGE (ARDATE, CUSTOMER, NAME,
              CURR, OVER30,OVER60, OVER90, CREDITCARD)
          VALUES (:REFDATE, :CUSTOMER, :NAME,
              :CURR, :OVER30, :OVER60, :OVER90, :CREDITCARD);
          SUSPEND;
       END
    END
  END
  /* LOAD AGE FROM TABLE */
  FOR select customer, name, curr, over30, over60, over90, total, CREDITCARD
      from ar_zhist_age
      WHERE ARDATE = :REFDATE
      AND CUSTOMER BETWEEN :SCUSTOMER AND :ECUSTOMER
      INTO :CUSTOMER, :NAME, :CURR, :OVER30, :OVER60, :OVER90, :TOTAL, :CREDITCARD
  DO BEGIN
     if (CREDITCARD = 0) then
     BEGIN
        SELECT CS.CUSTTYPE, TY.NAME FROM syscustomer CS
        LEFT JOIN syscustomertype TY ON TY.CUSTOMERTYPE = CS.CUSTTYPE
        WHERE CS.CUSTOMER = :CUSTOMER
        INTO CUSTTYPE, TYPENAME;
        if (PRINT_COMPANY=1) then SUSPEND;
     END
     ELSE
     BEGIN
       CUSTTYPE = 'CARD';
       TYPENAME = 'Credit Card';
       if (PRINT_CREDITCARD=1) then SUSPEND;
     END
  END  
END^


ALTER PROCEDURE AR_AGING_OLD_CALC(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8),
    REFDATE DATE,
    DETAILFLAG INTEGER,
    SOURCE VARCHAR(4),
    PRINT_COMPANY INTEGER,
    PRINT_CREDITCARD INTEGER)
RETURNS (
    ARDATE DATE,
    CUSTOMER VARCHAR(8),
    CUSTTYPE VARCHAR(4),
    TYPENAME VARCHAR(40),
    BALANCE NUMERIC(15,4),
    NAME VARCHAR(40),
    CURR NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    TOTAL NUMERIC(15,4),
    CREDITLIMIT NUMERIC(15,4),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    DOCUMENT VARCHAR(20),
    FO_GUESTNAME VARCHAR(80),
    AGE INTEGER,
    VOUCHER_ORG DOUBLE PRECISION,
    CASH DOUBLE PRECISION,
    ADJUST DOUBLE PRECISION,
    APPLY_DEPOSIT DOUBLE PRECISION,
    CREDITCARD INTEGER)
AS
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE VOUCHER DOUBLE PRECISION;
DECLARE VARIABLE FOADJUST DOUBLE PRECISION;
DECLARE VARIABLE F_VOUCHER DOUBLE PRECISION;
DECLARE VARIABLE F_CASH DOUBLE PRECISION;
DECLARE VARIABLE F_ADJUST DOUBLE PRECISION;
DECLARE VARIABLE F_DEPOS DOUBLE PRECISION;
DECLARE VARIABLE VPAYDATE DATE;
DECLARE VARIABLE VBATCH INTEGER;
DECLARE VARIABLE VOUTLET VARCHAR(4);
DECLARE VARIABLE VCOUNT INTEGER;
DECLARE VARIABLE X_NUMBER INTEGER;
DECLARE VARIABLE X_CASH DOUBLE PRECISION;
DECLARE VARIABLE X_F_CASH DOUBLE PRECISION;
DECLARE VARIABLE X_STATUS CHAR(1);
DECLARE VARIABLE X_DATE DATE;
declare variable CURRENCY VARCHAR(4);
begin
  /* CALC FROM AR_AGING_OLD */
  if ((SCUSTOMER IS NULL) or (SCUSTOMER || ECUSTOMER = '')) then BEGIN
     SCUSTOMER = '125';
     ECUSTOMER = '125';
     REFDATE  = '05.1.2006';
     DETAILFLAG = 0;
     PRINT_CREDITCARD = 0;
     PRINT_COMPANY = 1;
     SOURCE = 'TN';
  END
      
  BALANCE = 0;
  DEPOSIT = 0;
  if (CURRENCY IS NULL) then CURRENCY = 'All';
  CREDITCARD = 0;
  
  ARDATE = REFDATE;
  if (PRINT_COMPANY=1) then
  for select CS.CUSTOMER, CS.NAME, CS.CREDITLIMIT, CS.CUSTTYPE, TY.NAME from syscustomer CS
  LEFT JOIN syscustomertype TY ON TY.CUSTOMERTYPE = CS.CUSTTYPE
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER, NAME, CREDITLIMIT, CUSTTYPE, TYPENAME
  do
  begin
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    end
    else TYPENAME = 'Invoice';

    fo_guestname = '';
    opendate = null;
    duedate = null;
    document = null;
    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/
    for select number, total, forex_total, opendate, duedate
          from ARvch
         where CUSTOMER = :CUSTOMER
           and opendate <= :RefDate
           and source = :source
           and ((:CURRENCY = 'All') or (CURRENCY = :CURRENCY))
           plan (arvch index (ARVCH_IDX_CUSTOMER_OPENDATE))
         into number, voucher, f_voucher, opendate, duedate
    do
    begin
       /* ------------------------------------------------------------------- */    
       /* select cash payment                                                 */
       /* ------------------------------------------------------------------- */
       VOUCHER_ORG = VOUCHER;
       cash = 0;
       f_cash = 0;
       for select d.total, d.forex_total, d.number, h.DUEDATE, h.STATUS
           from ARcash1 d
           left join arcash0 h on h.number = d.number
           where d.voucherno = :number
       into :x_cash, x_f_cash, x_number, x_date, x_status
       do
       begin
         if ((x_date <= RefDate) and (x_status IN ('C','R','L'))) then
         begin
            cash = cash + x_cash;
            f_cash = f_cash + x_f_cash;
         end
       end

       /* ------------------------------------------------------------------- */         
       /* select deposit                                                      */
       /* ------------------------------------------------------------------- */       
       select sum(ARdepos1.total), sum(ARdepos1.forex_total) from ARdepos1
        where ARdepos1.voucherno = :number
          and ARdepos1.APplieddate <= :RefDate
          and ARdepos1.status in ('C','R')
         into apply_deposit, f_depos;

       /* ------------------------------------------------------------------- */
       /* select adjustment                                                   */
       /* ------------------------------------------------------------------- */
       select sum(db-cr), sum(forex_db-forex_cr)  from ARadj
        where voucherno = :number
          and OpenDate <= :RefDate
         into adjust, f_adjust;

                  
       if (voucher is null) then voucher = 0;
       if (cash    is null) then cash    = 0;
       if (adjust  is null) then adjust  = 0;
       if (apply_deposit   is null) then apply_deposit   = 0;
       
       if (f_voucher   is null) then f_voucher = 0;
       if (f_cash      is null) then f_cash    = 0;
       if (f_adjust    is null) then f_adjust  = 0;
       if (f_depos     is null) then f_depos   = 0;
       
       if (CURRENCY = 'All') then
          voucher = voucher - cash + adjust - apply_deposit ;
       else
          voucher = f_voucher - f_cash + f_adjust - f_depos ;
       d = RefDate - opendate;
      /*======================================================================*/
      /* jika aging detail                                                    */
      /*======================================================================*/
       if (detailflag = 1) then
       begin
          curr = 0;
          over30 = 0;
          over60 = 0;
          over90 = 0;
       end
       if (d <= 30)      then curr   = curr + voucher;
       else if (d <= 60) then over30 = over30 + voucher;
       else if (d <= 90) then over60 = over60 + voucher;
       else over90 = over90 + voucher;
       /* ------------------------------------------------------------------- */
       /* detail aging (ada nomor vouchernya                                  */
       /* ------------------------------------------------------------------- */
       if (detailflag = 1) then
       begin
         age = d;
         total = curr + over30 + over60 + over903        suspend;
       end
    end
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    DEPOSIT  = 0;
    IF (detailflag = 1) then
    begin
       TYPENAME = 'Deposit';
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    END
    CASH = 0;
    ADJUST = 0;
    VOUCHER = 0;
    VOUCHER_ORG = 0;
    APPLY_DEPOSIT = 0;
    FOR SELECT NUMBER, OPENDATE, TOTAL FROM ARDEPOS0
         where CUSTOMER = :CUSTOMER
         and opendate <= :RefDate
        INTO :NUMBER, :OPENDATE, :TOTAL
    DO
    BEGIN
       DEPOSIT = DEPOSIT + TOTAL;
       for select TOTAL
          from ARDEPOS1
         where NUMBER = :NUMBER
           and APPLIEDDATE <= :RefDate
       INTO :TOTAL
       DO
       BEGIN
          DEPOSIT = DEPOSIT - TOTAL;
       END
       if (detailflag = 1) then
       BEGIN

          DEPOSIT = -DEPOSIT;
          TOTAL = DEPOSIT;
          AGE = 0;
          SUSPEND;
          DEPOSIT = 0;
       END
    END
    if (detailflag <> 1) then
    begin
       total = curr + over30 + over60 + over90 - deposit;
       number = 0;
       document = '';
       if (total <> 0) then
          suspend;
    end

  end
  /* ------------------------------------------------------------------------ */
  /* CREDIT CARD                                                              */
  /* ------------------------------------------------------------------------ */
  TOTAL  = 0;
  NUMBER = 0;
  CREDITCARD = 1;
  BALANCE = 0;
  CUSTTYPE = 'CARD';
  TYPENAME = 'Credit Card';
  if ((CURRENCY = 'All') AND (PRINT_CREDITCARD=1)) then
  FOR SELECT CREDITCARD, NAME
      FROM AR_CARD
      where CREDITCARD between :sCUSTOMER and :eCUSTOMER
      INTO :CUSTOMER, :NAME
  DO BEGIN
    /* ---------------------------------------------------------------------- */
    /* summary                                                                */
    /* ---------------------------------------------------------------------- */
    if (DETAILFLAG <> 1) then  
    begin
       CURR   = 0;
       OVER30 = 0;
       OVER60 = 0;
       OVER90 = 0;
       for select jr.outlet, jr.batch, jr.opendate, jr.total
             from ar_card_jur jr
            where CREDITCARD = :CUSTOMER
              and jr.opendate <= :RefDate
            PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_CUSTOMER))
             into vOutlet, vBatch, opendate, voucher
       do begin
          vPayDate = Null;

          select count(*) from ar_card_batch
          where outlet = :vOutlet
          and Batch = :vBatch
          and PAY_DATE <= :RefDate
          and status in ('C','R')
          PLAN (AR_CARD_BATCH INDEX (AR_CARD_BATCH_IDX_OUTLET_BATCH))
          into vCount;
          
          if (vCount =0) then
          begin
            d = RefDate - opendate;
            if (d <= 30)      then curr   = curr + voucher;
            else if (d <= 60) then over30 = over30 + voucher;
            else if (d <= 90) then over60 = over60 + voucher;
            else over90 = over90 + voucher;
          end
        end
        total = curr + over30 + over60 + over90;
        BALANCE = BALANCE + TOTAL;
        if (total <> 0) then suspend;
        
    end /* summary */
    /* ---------------------------------------------------------------------- */
    /* detail                                                                 */
    /* ---------------------------------------------------------------------- */
    if (DETAILFLAG = 1) then
    begin
       for select jr.number, jr.opendate, jr.total
             from ar_card_jur jr
            where CREDITCARD = :CUSTOMER
              and status = 'O'
              and jr.opendate <= :RefDate
             into number, opendate, voucher
       do begin
          CURR   = 0;
          OVER30 = 0;
          OVER60 = 0;
          OVER90 = 0;
          if (voucher is null) then voucher = 0;
          if (not (vPayDate is Null)) then voucher = 0;
          AGE = RefDate - opendate;
          if (AGE <= 30)      then curr   = voucher;
          else if (AGE <= 60) then over30 = voucher;
          else if (AGE <= 90) then over60 = voucher;
          else over90 = voucher;
          total = curr + over30 + over60 + over90;
          suspend;
        end
       end
    end /* detail  */
end^


ALTER PROCEDURE AR_AGING_PERIOD(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8),
    DETAILFLAG INTEGER,
    REFFDATE DATE,
    CURRENCY VARCHAR(4))
RETURNS (
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    CURR NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4),
    TOTAL NUMERIC(15,4),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    DOCUMENT VARCHAR(20),
    SOURCEID INTEGER,
    SOURCE_REMARK VARCHAR(80),
    AGE INTEGER,
    CREDITCARD INTEGER,
    CUSTTYPE VARCHAR(4),
    TYPENAME VARCHAR(40))
AS
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE VOUCHER DOUBLE PRECISION;
DECLARE VARIABLE CASH DOUBLE PRECISION;
DECLARE VARIABLE ADJUST DOUBLE PRECISION;
DECLARE VARIABLE DEPOS DOUBLE PRECISION;
DECLARE VARIABLE FOADJUST DOUBLE PRECISION;
DECLARE VARIABLE F_VOUCHER DOUBLE PRECISION;
DECLARE VARIABLE F_CASH DOUBLE PRECISION;
DECLARE VARIABLE F_ADJUST DOUBLE PRECISION;
DECLARE VARIABLE F_DEPOS DOUBLE PRECISION;
DECLARE VARIABLE F_FOADJUST DOUBLE PRECISION;
DECLARE VARIABLE VPAYDATE DATE;
DECLARE VARIABLE ARDATE DATE;
DECLARE VARIABLE XDEPOSIT DOUBLE PRECISION;
DECLARE VARIABLE CREDITLIMIT DOUBLE PRECISION;
begin
    /* Modified by Agus AR Aging By Selection Periode
       Period ARDate Get From Reffdate + 1    */
  /* Procedure Text */
/*  if ((SCUSTOMER IS NULL) or (SCUSTOMER || ECUSTOMER = '')) then BEGIN
     SCUSTOMER = '';
     ECUSTOMER = 'zzzzzz';
  END
*/
  if (DETAILFLAG IS NULL) then
      DETAILFLAG = 0;
      
  if (CURRENCY IS NULL) then CURRENCY = 'All';
  
  CREDITCARD = 0;
  
/*  SELECT ARSYSDATE+1 FROM SYSPARAM INTO ARDATE; */
  ARDATE =:REFFDATE + 1;
  
  for select CUSTOMER, name, CUSTTYPE, CREDITLIMIT from sysCUSTOMER
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER, name, CUSTTYPE, CREDITLIMIT
  do
  begin
    SELECT NAME FROM SYSCUSTOMERTYPE
    WHERE CUSTOMERTYPE = :CUSTTYPE
    INTO :TYPENAME;
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    end
    SOURCEID = 0;
    SOURCE_REMARK = '';
    opendate = null;
    duedate = null;
    document = null;
    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/
    for select number, totaldue, forex_totaldue,
               opendate, duedate, SOURCEID, SOURCE_REMARK
          from ARvch
         where PAIDSTATUS = 'O'
           AND CUSTOMER = :CUSTOMER
           AND OPENDATE <= :REFFDATE
           and ((totaldue <> 0) or (forex_totaldue <> 0))
           and ((:CURRENCY = 'All') or (CURRENCY = :CURRENCY))
         PLAN (ARVCH INDEX (ARVCH_IDX_PAIDSTATUS))
         into number, voucher, f_voucher, opendate, duedate, SOURCEID, SOURCE_REMARK
    do
    begin
       if (CURRENCY <> 'All') then
          voucher = f_voucher;
       d = ARDate - opendate;
      /*======================================================================*/
      /* jika aging detail                                                    */
      /*======================================================================*/
       if (detailflag = 1) then
       begin
          curr = 0;
          over30 = 0;
          over60 = 0;
          over90 = 0;
       end
       if (d <= 30)      then curr   = curr + voucher;
       else if (d <= 60) then over30 = over30 + voucher;
       else if (d <= 90) then over60 = over60 + voucher;
       else over90 = over90 + voucher;
       /* ------------------------------------------------------------------- */
       /* detail aging (ada nomor vouchernya                                  */
       /* ------------------------------------------------------------------- */
       if (detailflag = 1) then
       begin
         age = d;
         total = curr + over30 + over60 + over90;
         if (total <> 0) then
            suspend;
       end
    end
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       total = curr + over30 + over60 + over90;
       number = 0;
       document = '';
       if (total <> 0) then
          suspend;
    end
  end
  /* ------------------------------------------------------------------------ */
  /* credit card journal                                                      */
  /* ------------------------------------------------------------------------ */
  CUSTTYPE = 'CARD';
  TYPENAME = 'Credit Card';
  if (CURRENCY <> 'All') then exit;
  TOTAL  = 0;
  NUMBER = 0;
  CREDITCARD = 1;
  CREDITLIMIT = 0;
  FOR SELECT CREDITCARD, NAME
      FROM AR_CARD
      where CREDITCARD between :sCUSTOMER and :eCUSTOMER
      INTO :CUSTOMER, :NAME
  DO BEGIN
    /* ---------------------------------------------------------------------- */
    /* summary                                                                */
    /* ---------------------------------------------------------------------- */
    if (DETAILFLAG <> 1) then  
    begin
       CURR   = 0;
       OVER30 = 0;
       OVER60 = 0;
       OVER90 = 0;
       for select jr.opendate, sum(jr.total)
             from ar_card_jur jr
            where CREDITCARD = :CUSTOMER
              and status = 'O'
          group by jr.opendate
            PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_STATUS))          
             into opendate, voucher
       do begin
          if (voucher is null) then voucher = 0;
          if (not (vPayDate is Null)) then voucher = 0;
          d = ARDate - opendate;
          if (d <= 30)      then curr   = curr + voucher;
          else if (d <= 60) then over30 = over30 + voucher;
          else if (d <= 90) then over60 = over60 + voucher;
          else over90 = over90 + voucher;
        end
        total = curr + over30 + over60 + over90;
        if (total <> 0) then suspend;
    end /* summary */
    /* ---------------------------------------------------------------------- */
    /* detail                                                                 */
    /* ---------------------------------------------------------------------- */
    if (DETAILFLAG = 1) then
    begin
       for select jr.number, jr.opendate, jr.total, jr.sourceid
             from ar_card_jur jr
            /*left outer join AR_CARD_BATCH b on ((Jr.batch = B.batch) and (jr.bank = B.Bank) and (jr.Outlet = B.Outlet) and (b.status <> 'O'))*/
            where CREDITCARD = :CUSTOMER
              and status = 'O'
             PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_STATUS))
             into number, opendate, voucher, sourceid
       do begin
          CURR   = 0;
          OVER30 = 0;
          OVER60 = 0;
          OVER90 = 0;
          if (voucher is null) then voucher = 0;
          if (not (vPayDate is Null)) then voucher = 0;
          AGE = ARDate - opendate;
          if (AGE <= 30)      then curr   = voucher;
          else if (AGE <= 60) then over30 = voucher;
          else if (AGE <= 90) then over60 = voucher;
          else over90 = voucher;
          total = curr + over30 + over60 + over90;
       end
    end /* detail  */
  end /* credit card */
end^


ALTER PROCEDURE AR_CASHQ(
    SDATE DATE)
RETURNS (
    WK INTEGER,
    WKSDATE DATE,
    WKEDATE DATE,
    VOUCHERDUE NUMERIC(15,4),
    CREDITCARD NUMERIC(15,4),
    CASHDUE NUMERIC(15,4),
    BANKDUE NUMERIC(15,4),
    TOTAL NUMERIC(15,4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
begin
  /* Procedure Text */
  if (sDate is null ) then
     select ARsysdate from sysparam into :sDate;
     
  execute procedure sp_decodedate(sDate) returning_values y, m, d;
  
  if (y < 2000) then
     execute procedure sp_encodedate(y, m, d) returning_values sDate;

  d = -1;
  while (d <> 5) do
  begin
    execute procedure sp_dayofweek(sDate) returning_values d;
    sDate = sDate-1;
  end
  wk = 0;
  while (wk <= 7) do
  begin
    wksdate = sDate+wk*7;
    wkedate = wksdate+6;
    if (wk = 0 ) then wksdate = wksdate - 3650;
    if (wk = 7)  then wkedate = wkedate + 3650;
    CreditCard = 0;
    if (wk = 0) then begin
       select sum(total) from ar_card_jur
       where status = 'O'
       PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_STATUS_CARD))
       into :CreditCard;
    end
    if (CreditCard is Null) then CreditCard = 0;
    
    SELECT SUM(TOTALDUE_PREPARE) FROM ARvch /* invoice due, yang belum di proses */
     WHERE paidstatus = 'O'
     and DUEDATE between :wksdate and :wkedate 
     and forex_totaldue <> 0
     PLAN (ARVCH INDEX (ARVCH_IDX_PAIDSTATUS))

     into voucherdue;
     
    SELECT SUM(TOTAL) FROM ARcash0 /* prepared check */
     WHERE status = 'O'
     AND DUEDATE between :wksdate and :wkedate
     PLAN (ARCASH0 INDEX (ARCASH0_IDX_STATUS))
      into cashdue;


    SELECT SUM(TOTAL) FROM ARcash0 /* received checks tapi belum di reconcile (status=C) */
                                   /* kalau sudah direconcile masuk ke bank book         */
    WHERE status = 'R'
    AND DUEDATE between :wksdate and :wkedate
    PLAN (ARCASH0 INDEX (ARCASH0_IDX_STATUS))
    INTO bankdue;
     
    if (voucherdue is null) then voucherdue = 0;
    if (cashdue    is null) then cashdue    = 0;
    if (bankdue    is null) then bankdue    = 0;
    total = voucherdue + cashdue + bankdue + creditcard;
    suspend;
    wk = wk+1;
  end
end^


ALTER PROCEDURE AR_CASH_RECONCILE_CHECK(
    SDATE DATE,
    EDATE DATE)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    NUMBER INTEGER,
    RECONCILEDATE DATE,
    TOTAL DOUBLE PRECISION,
    REC_BB DOUBLE PRECISION,
    REC_BB_DELTA DOUBLE PRECISION,
    REC_GL DOUBLE PRECISION,
    REC_GL_DELTA DOUBLE PRECISION)
AS
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SDATE = '1.7.2005';
     EDATE = '31.12.2005';
  END
  APPLICATION = 'AP';
  /* ---------------------------------------------------------------- */
  /* CASH RECONCILIATION                                              */
  /* ---------------------------------------------------------------- */
  SOURCE = 'REC';
  FOR
    SELECT NUMBER, RECONCILEDATE, TOTAL
    FROM APCASH0
    WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
    AND STATUS = 'C'
    AND TOTAL <> 0
    PLAN (APCASH0 INDEX (APCASH0_IDX_RECONCILE))
    ORDER BY NUMBER
    INTO
      :NUMBER,
      :RECONCILEDATE,
      :TOTAL
  DO
  BEGIN
    SELECT SUM(DB) FROM GLJUR
    WHERE APPLICATION = :APPLICATION
    AND SOURCE = :SOURCE
    AND SOURCENUMBER = :NUMBER
    PLAN (GLJUR INDEX (GLJUR_IDX_SOURCE))
    INTO REC_GL;
    IF (REC_GL IS NULL) THEN REC_GL = 0;
    REC_GL_DELTA = REC_GL-TOTAL;

    SELECT SUM(FOREX_DB) FROM BBJUR
    WHERE APPLICATION = :APPLICATION
    AND SOURCE = :SOURCE
    AND SOURCENUMBER = :NUMBER
    PLAN (BBJUR INDEX (BBJUR_IDX_APPLICATION))
    INTO REC_BB;
    IF (REC_BB IS NULL) THEN REC_BB = 0;
    REC_BB_DELTA = REC_BB-TOTAL;

    IF ((REC_GL_DELTA NOT BETWEEN -0.1 AND 0.1) OR (REC_BB_DELTA NOT BETWEEN -0.1 AND 0.1)) THEN
       SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* DEPOSIT RECONCILIATION                                           */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DREC';
  FOR
    SELECT NUMBER, RECONCILEDATE, TOTAL
    FROM APDEPOS0
    WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
    AND STATUS = 'C'
    AND TOTAL <> 0
    PLAN (APDEPOS0 INDEX (APDEPOS0_IDX_RECONCILE))
    ORDER BY NUMBER
    INTO
      :NUMBER,
      :RECONCILEDATE,
      :TOTAL
  DO
  BEGIN
    SELECT SUM(DB) FROM GLJUR
    WHERE APPLICATION = :APPLICATION
    AND SOURCE = :SOURCE
    AND SOURCENUMBER = :NUMBER
    PLAN (GLJUR INDEX (GLJUR_IDX_SOURCE))
    INTO REC_GL;
    IF (REC_GL IS NULL) THEN REC_GL = 0;
    REC_GL_DELTA = REC_GL-TOTAL;

    SELECT SUM(FOREX_DB) FROM BBJUR
    WHERE APPLICATION = :APPLICATION
    AND SOURCE = :SOURCE
    AND SOURCENUMBER = :NUMBER
    PLAN (BBJUR INDEX (BBJUR_IDX_APPLICATION))
    INTO REC_BB;
    IF (REC_BB IS NULL) THEN REC_BB = 0;
    REC_BB_DELTA = REC_BB-TOTAL;

    IF ((REC_GL_DELTA NOT BETWEEN -0.1 AND 0.1) OR (REC_BB_DELTA NOT BETWEEN -0.1 AND 0.1)) THEN
       SUSPEND;
  END
END^


ALTER PROCEDURE AR_CASH_RECONCILE_SUMMARY(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    NAME VARCHAR(40),
    FLAG_CLEARANCE INTEGER,
    CASH DOUBLE PRECISION,
    GL DOUBLE PRECISION,
    DELTA DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
BEGIN
  IF ((PYEAR IS NULL) OR (PYEAR = 0)) THEN
  BEGIN
     PYEAR = 2006;
     PMONTH = 2;
  END
  
  SDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES(EDATE);
  APPLICATION = 'AP';
  /* ---------------------------------------------------------------- */
  /* cash payment                                                     */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CASH';
  NAME = 'Cash Payment';
  
  SELECT SUM(TOTAL) FROM APCASH0
  WHERE DUEDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('L','C','R')
  INTO :CASH;
  
  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;
  
  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = 1;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* cash reconciliation                                              */
  /* ---------------------------------------------------------------- */
  SOURCE = 'REC';
  NAME = 'Cash Payment Reconciliation';
  
  SELECT SUM(TOTAL) FROM APCASH0
  WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'C'
  INTO :CASH;

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = -1;
  SUSPEND;
  
  /* ---------------------------------------------------------------- */
  /* deposit payment                                                  */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DEP0';
  NAME = 'Purchase Deposit';

  SELECT SUM(TOTAL) FROM APDEPOS0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('L','C','R')
  INTO :CASH;

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = 1;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* deposit reconciliation                                           */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DREC';
  NAME = 'Purchase Deposit Reconciliation';

  SELECT SUM(TOTAL) FROM APDEPOS0
  WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'C'
  INTO :CASH;

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = -1;
  SUSPEND;
  /* ---------------------------------------------------------------- */
  /* AR                                                               */
  /* ---------------------------------------------------------------- */
  IF (EXISTS(SELECT * FROM SYSPARAM WHERE INSTALLAR = 0)) THEN
  BEGIN
     EXIT;
  END
  APPLICATION = 'AR';
  /* ---------------------------------------------------------------- */
  /* cash receipt                                                     */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CASH';
  NAME = 'Cash Receipt';
  CASH = 0;

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (GL IS NULL) THEN GL = 0;
  FLAG_CLEARANCE = 1;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* cash receipt reconciliation                                      */
  /* ---------------------------------------------------------------- */
  SOURCE = 'REC';
  NAME = 'Cash Receipt Reconciliation';

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = -1;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* a/r deposit payment                                              */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DEP0';
  NAME = 'Reservation Deposit';

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = 1;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* a/r deposit reconciliation                                       */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DREC';
  NAME = 'Reservation Deposit Reconciliation';

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = -1;
  SUSPEND;
  /* ---------------------------------------------------------------- */
  /* card batch receipt                                               */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CCPY';
  NAME = 'Credit Card Settlement';

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = 1;
  SUSPEND;
  /* ---------------------------------------------------------------- */
  /* card batch receipt                                               */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CREC';
  NAME = 'Credit Card Reconciliation';

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = -1;
  SUSPEND;
END^


ALTER PROCEDURE AR_JOURNAL(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8),
    SDATE DATE,
    EDATE DATE)
RETURNS (
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    SEQUENCE INTEGER,
    NUMBER INTEGER,
    VOUCHERNO INTEGER,
    DOCTYPE VARCHAR(16),
    OPENDATE DATE,
    DOCUMENT VARCHAR(20),
    TEXT1 VARCHAR(30),
    VOUCHER NUMERIC(15,4),
    CASH NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    TOTAL NUMERIC(15,4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
begin
  if (scustomer is null) then
  begin
     scustomer = '125';
     ecustomer = '125';
     sdate = '01.01.2000';
     edate = 'NOW';
  end


  for select CUSTOMER, name from sysCUSTOMER
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER, :name
  do
  begin
    DocType = 'Pre';
    Document = 'Previous Balance';
    OpenDate = sDate;
    sequence = 0;
    Number = 0;
    VoucherNo = 0;
    select sum(total) from ARvch where CUSTOMER = :CUSTOMER and opendate < :sDate
      into :Voucher;
    select sum(total) from ARcash0 where CUSTOMER = :CUSTOMER and DueDate < :sDate
      into cash;
    select sum(db-cr) from ARadj where CUSTOMER = :CUSTOMER and opendate < :sDate
      into :Adjust;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    total = voucher - cash - adjust;
    if (voucher + cash + adjust <> 0) then suspend;
    /* ----------------------------------------------------------------------*/
    /* INVOICE                                                               */
    CASH = 0;
    ADJUST = 0;
    DEPOSIT = 0;
    DocType = 'Invoice';
    SEQUENCE = 0;
    for select number,
             Number VoucherNo,
             opendate,
             document,
             total
        from ARvch
        where CUSTOMER = :CUSTOMER and opendate between :sDate and :eDate
    into NUMBER, VOUCHERNO, OPENDATE, DOCUMENT, VOUCHER
    DO
    BEGIN
      TOTAL = VOUCHER;
      SUSPEND;
    END
    /* ----------------------------------------------------------------------*/
    /* adjustment                                                            */
    /* ----------------------------------------------------------------------*/
    DocType = 'Adj';
    VOUCHER = 0;
    SEQUENCE = 1;
    FOR select number,
              voucherno,
              opendate,
              document,
              (db-cr)
          from ARadj
         where CUSTOMER = :CUSTOMER and opendate between :sDate and :eDate
    into NUMBER, VOUCHERNO, OPENDATE, DOCUMENT, ADJUST
    DO
    BEGIN
      TOTAL = ADJUST;
      SUSPEND;
    END
    /* ----------------------------------------------------------------------*/
    /* DEPOSIT                                                               */
    /* ----------------------------------------------------------------------*/
    ADJUST = 0;
    DOCTYPE = '   Deposit';
    VOUCHERNO = 0;
    for select number,
              OPENDATE,
              DOCUMENT,
              total
          from ARDEPOS0
         where CUSTOMER = :CUSTOMER and OPENDATE between :sDate and :eDate
    into NUMBER, OPENDATE, DOCUMENT, DEPOSIT
    DO
    BEGIN
      TOTAL = -DEPOSIT;
      SUSPEND;
    END
    /* ----------------------------------------------------------------------*/
    /* CASH RECIPT                                                           */
    /* ----------------------------------------------------------------------*/
    DEPOSIT = 0;
    DOCTYPE = '   Cash';
    SEQUENCE = 8;
    FOR select ARcash1.number,
             ARcash1.voucherno,
             ARcash0.DueDate,
             ARcash0.document,
             ARcash1.total
         from ARcash1
        left join ARcash0 on ARcash0.number = ARcash1.number
         where ARcash0.CUSTOMER = :CUSTOMER and ARcash0.OPENDATE between :sDate and :eDate
    into NUMBER, VOUCHERNO, OPENDATE, DOCUMENT, CASH
    DO
    BEGIN
       TOTAL = -CASH;
       SUSPEND;
    END
  end
end^


ALTER PROCEDURE AR_JOURNAL_CARD(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8),
    SDATE DATE,
    EDATE DATE)
RETURNS (
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    SEQUENCE INTEGER,
    NUMBER INTEGER,
    VOUCHERNO INTEGER,
    DOCTYPE VARCHAR(6),
    OPENDATE DATE,
    DOCUMENT VARCHAR(20),
    TEXT1 VARCHAR(30),
    VOUCHER NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    TOTAL NUMERIC(15,4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
begin
for select CREDITCARD, NAME  from ar_card
/*where CUSTOMER between :sCUSTOMER and :eCUSTOMER*/
into :CUSTOMER, :name
do
begin
  DocType = 'Pre';
  Document = 'Previous Balance';
  OpenDate = sDate;
  sequence = 0;
  Number = 0;
  VoucherNo = 0;
  select sum(total) from AR_CARD_JUR where CREDITCARD = :CUSTOMER and opendate < :sDate
    into :Voucher;
  select sum(total) from AR_CARD_JUR where CREDITCARD = :CUSTOMER and Pay_Date < :sDate
    and (pay_date is not null)
    into cash;
    
  if (voucher is null) then voucher = 0;
  if (cash    is null) then cash    = 0;
  if (adjust  is null) then adjust  = 0;
  total = voucher - cash - adjust;
  if (voucher + cash + adjust <> 0) then suspend;
for
    select number, (CAST('Vch' AS VARCHAR(6))) DocType,
           Number VoucherNo,
           opendate,
           document,
           total voucher,
           cast(0 as numeric(15,4)) cash,
           cast(0 as numeric(15,4)) adjust,
           total
      from ARvch
      where CUSTOMER = :CUSTOMER and opendate between :sDate and :eDate
    union
    select ARcash1.number, CAST('Cash' AS VARCHAR(6)),
           ARcash1.voucherno,
           ARcash0.OpenDate,
           ARcash0.document,
           cast(0 as numeric(15,4)) voucher,
           ARcash1.total cash,
           cast(0 as numeric(15,4)) adjust,
           -ARcash1.total total
       from ARcash1
      inner join ARcash0 on ARcash0.number = ARcash1.number
       where ARcash0.CUSTOMER = :CUSTOMER and ARcash0.opendate between :sDate and :eDate
     union
     select number,  CAST('Adj' AS VARCHAR(6)),
            voucherno,
            opendate,
            document,
            cast(0 as numeric(15,4)) voucher,
            cast(0 as numeric(15,4)) cash,
            (db-cr) adjust,
            (db-cr)
        from ARadj
       where CUSTOMER = :CUSTOMER and opendate between :sDate and :eDate
  union
     select number,  CAST('Dep' AS VARCHAR(6)),
            voucherno,
            APPlieddate,
            CAST('' AS VARCHAR(20)),
            -total,
            cast(0 as numeric(15,4)),
            cast(0 as numeric(15,4)),
            -total
        from ARdepos1
       where CUSTOMER = :CUSTOMER and APPlieddate between :sDate and :eDate
  into NUMBER, DOCTYPE, VOUCHERNO, OPENDATE, DOCUMENT, VOUCHER, CASH, ADJUST, TOTAL
  DO
  BEGIN
    SUSPEND;
    sequence = number;
    if (doctype = 'Vch') then sequence = 0;
  END

end
end^


ALTER PROCEDURE AR_MUTATION(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8))
RETURNS (
    CREDITCARD INTEGER,
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    OPENING NUMERIC(15,4),
    VOUCHER NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    ENDING NUMERIC(15,4),
    CUSTTYPE VARCHAR(4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable sDate date;
declare variable eDate date;
declare variable fo_adjust double precision;
declare variable pcash double precision;
declare variable REFDATE DATE;
declare variable XDEPOSIT DOUBLE PRECISION;
declare variable vrow integer;
declare variable adjust1 double precision;
declare variable XNUMBER INTEGER;
declare variable xadjust DOUBLE PRECISION;

declare variable XBANK VARCHAR(4);
declare variable XOUTLET VARCHAR(4);
declare variable xcash double precision;
begin

  CREDITCARD = 0;
  select arsysdate from sysparam into :REFDATE;

  if (SCUSTOMER IS NULL) then BEGIN
     SCUSTOMER = '';
     eCUSTOMER = 'ZZZZZZ';
  END
  execute procedure sp_beginofmonth (refdate) returning_values sDate;
  execute procedure sp_endofmonth   (refdate) returning_values eDate;

  for select CUSTOMER, name,CUSTTYPE from sysCUSTOMER
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER, name, CUSTTYPE
  do
  begin
    opening = 0;
    voucher = 0;
    cash = 0;
    adjust = 0;
    ending = 0;
    adjust1 = 0;
    /*========================================================================*/
    /* hitung ending                                                          */
    /*========================================================================*/
    select sum(totaldue) from ARvch
     where PAIDSTATUS = 'O'
       AND CUSTOMER = :CUSTOMER
/*      PLAN (ARVCH INDEX (ARVCH_IDX_PAIDSTATUS)) For FB.2.x 31-Aug-2011 */
      into ending;
    /*========================================================================*/
    /* hitung bulan ini                                                       */
    /*========================================================================*/
    select SUM(TOTAL) from ARvch
     where CUSTOMER = :CUSTOMER
       and OpenDate between :sDate and :eDate
/*        PLAN (ARVCH INDEX (ARVCH_IDX_OPENDATE)) For FB.2.x 31-Aug-2011 */
      into :voucher;
      
    select sum(ARdepos1.total) from ARdepos1
     where ARdepos1.CUSTOMER = :CUSTOMER
       and ARdepos1.APPlieddate between :sDate and :eDate
       AND ARdepos1.STATUS IN ('R','C')
      into deposit;

    select sum(total) from ARcash0 where CUSTOMER = :CUSTOMER
       and DueDate between :sDate and :eDate
       and status in ('C', 'R','L')
/*        PLAN (ARCASH0 INDEX (ARCASH0_IDX_CUST_DUEDATE)) For FB.2.x 31-Aug-2011 */
      into :cash;

    select sum(db-cr) from ARadj
      where CUSTOMER = :CUSTOMER
       and OpenDate between :sDate and :eDate
/*        PLAN (ARADJ INDEX (ARADJ_IDX_OPENDATE)) For FB.2.x 31-Aug-2011 */
      into :adjust1;
      
    /* 10-JAN-2003, SPEEDUP */
    adjust = 0;
    FOR SELECT NUMBER FROM arvch
        WHERE CUSTOMER = :CUSTOMER
        AND OPENDATE >= :sDate 
/*         PLAN (ARVCH INDEX (ARVCH_IDX_OPENDATE)) For FB.2.x 31-Aug-2011 */
    INTO XNUMBER DO
    BEGIN
      select sum(D.debit-D.credit) from ARVCH_DETAIL D
      where D.NUMBER = :XNUMBER
      and D.source = 'A'
      and D.status = 'C'               
      and D.FODATE between :sDate and :eDate
/*       PLAN (ARVCH_DETAIL INDEX (ARVCH_DETAIL_IDX_NO_SOURCE)) For FB.2.x 31-Aug-2011 */
      into xadjust;
      if (xadjust is not null) then
         adjust = adjust + xadjust;
    END
    /* END OF SPEED UP */
/*
    select sum(D.debit-D.credit) from ARVCH_DETAIL D
    INNER JOIN ARVCH H ON D.NUMBER = H.NUMBER
    where H.CUSTOMER = :CUSTOMER
    and D.FODATE between :sDate and :eDate
    and D.status = 'C'  CLOSE, POSTED
    and D.source = 'A'  ADJUSTMENT
    into adjust;
*/
    if (ending  is null) then ending  = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;
    if (deposit is null) then deposit = 0;
    adjust = adjust + adjust1 - deposit;
    opening = ending - voucher + cash - adjust;
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0)) then
       suspend;
  end
  adjust = 0;
  CREDITCARD = 1;
  CUSTTYPE = 'CARD';
  FOR SELECT CREDITCARD, NAME
      FROM AR_CARD
      where CREDITCARD between :sCUSTOMER and :ECUSTOMER
      INTO :CUSTOMER, :NAME
  DO BEGIN
    /* ---------------------------------------------------------------------- */
    /* summary                                                                */
    /* ---------------------------------------------------------------------- */
    opening = 0;
    voucher = 0;
    cash = 0;
    ending = 0;
    /* ending */
    select sum(total) from ar_card_jur
    where creditcard = :customer
    and status = 'O'
/*     PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_STATUS)) For FB.2.x 31-Aug-2011 */
    into :ending;
    
    /* new transaction */
    select sum(total) from ar_card_jur
    where creditcard = :customer
    and opendate between :SDATE and :EDATE
/*     PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_CUSTOMER)) For FB.2.x 31-Aug-2011 */
    into :voucher;        
    
    /* opening */
    select sum(total) from ar_card_jur
    where creditcard = :customer
    and opendate < :sdate
/*     plan (ar_card_jur index (AR_CARD_JUR_IDX_CUSTOMER)) For FB.2.x 31-Aug-2011 */
    into :opening;

    /* cash recipt */
    cash = 0;
    FOR SELECT BANK, OUTLET, BATCH
        FROM AR_CARD_BATCH
        WHERE pay_date between :SDATE and :EDATE
        AND ((STATUS = 'C') or (STATUS = 'R'))
/*         PLAN (ar_card_batch INDEX (AR_CARD_BATCH_IDX_PAYDATE)) For FB.2.x 31-Aug-2011 */
        INTO XBANK, XOUTLET, XNUMBER
    DO BEGIN
       select sum(j.total) from ar_card_jur j
       where (J.batch = :xnumber)
       and (j.creditcard = :customer)
       and (j.outlet=:xoutlet)
       and (j.bank=:xbank) 
/*        PLAN (ar_card_jur INDEX (AR_CARD_JUR_IDX_BATCH)) For FB.2.x 31-Aug-2011 */
       into xcash;
       if (xcash is not null) then
          cash = cash + xcash;
    END

    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (deposit is null) then deposit = 0;
    if (pcash is not null) then opening=opening-pcash;    
    adjust = adjust - deposit;
    opening = ending - voucher + cash - adjust;
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0)) then
       suspend;    
  end
end^


ALTER PROCEDURE AR_MUTATION_OLD(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8),
    REFDATE DATE)
RETURNS (
    CREDITCARD INTEGER,
    CUSTTYPE VARCHAR(4),
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    OPENING NUMERIC(15,4),
    VOUCHER NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    ENDING NUMERIC(15,4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable sDate date;
declare variable eDate date;
declare variable fo_adjust double precision;
declare variable pcash double precision;
declare variable XDEPOSIT DOUBLE PRECISION;
declare variable vrow integer;
declare variable adjust1 double precision;
declare variable xTotal DOUBLE PRECISION;
declare variable xPayDate DATE;
declare variable xOpenDate DATE;
declare variable xSisa DOUBLE PRECISION;

declare variable X DOUBLE PRECISION;
declare variable ARSYSDATE DATE;
declare variable AR_MONTH INTEGER;
declare variable AR_YEAR  INTEGER;

declare variable PMONTH INTEGER;
declare variable PYEAR  INTEGER;
begin
  SELECT ARSYSDATE,
         EXTRACT(MONTH FROM ARSYSDATE), EXTRACT(YEAR FROM ARSYSDATE)
  FROM SYSPARAM WHERE ID = 1
  INTO ARSYSDATE, AR_MONTH, AR_YEAR;


  if (SCUSTOMER IS NULL) then BEGIN
     SCUSTOMER = '';
     eCUSTOMER = 'ZZZZZZ';
     REFDATE = ARSYSDATE;
     REFDATE = '01.11.2003';
  END
  
  PMONTH = EXTRACT(MONTH FROM REFDATE);
  PYEAR  = EXTRACT(YEAR  FROM REFDATE);
  
  if (PYEAR*12+PMONTH >= AR_YEAR*12+AR_MONTH) then
  BEGIN
    FOR SELECT CREDITCARD, CUSTTYPE, CUSTOMER, NAME,
           OPENING, VOUCHER, DEPOSIT, CASH, ADJUST, ENDING
    FROM ar_mutation_old_calc(:SCUSTOMER, :ECUSTOMER, :REFDATE)
    INTO CREDITCARD, CUSTTYPE, CUSTOMER, NAME,
         OPENING, VOUCHER, DEPOSIT, CASH, ADJUST, ENDING
    DO
    BEGIN
      SUSPEND;
    END
    EXIT;
  END
  /* PERIKSA APAKAH ADA DI HISTORY */
  SELECT COUNT(*) FROM ar_zhist_mutation
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  INTO X;  
  /* JIKA DATA ADA DI HISTORY */
  if (X = 0) then
  BEGIN
    FOR SELECT CREDITCARD, CUSTOMER, NAME,
           OPENING, VOUCHER, DEPOSIT, CASH, ADJUST, ENDING
    FROM ar_mutation_old_calc('', 'ZZZZZZ', :REFDATE)
    INTO CREDITCARD, CUSTOMER, NAME,
         OPENING, VOUCHER, DEPOSIT, CASH, ADJUST, ENDING
    DO
    BEGIN
      INSERT INTO ar_zhist_mutation
        (PYEAR, PMONTH,
         CREDITCARD, CUSTOMER, NAME,
         OPENING, VOUCHER, DEPOSIT, CASH, ADJUST)
      VALUES
        (:PYEAR, :PMONTH,
         :CREDITCARD, :CUSTOMER, :NAME,
         :OPENING, :VOUCHER, :DEPOSIT, :CASH, :ADJUST);
    END
  END
  /* LOAD FROM HISTORY */
  FOR SELECT H.CREDITCARD, C.CUSTTYPE, H.CUSTOMER, H.NAME,
           H.OPENING, H.VOUCHER, H.DEPOSIT, H.CASH, H.ADJUST, H.ENDING
  FROM ar_zhist_mutation H
  LEFT JOIN syscustomer C ON C.CUSTOMER = H.CUSTOMER
  WHERE H.PYEAR = :PYEAR
  AND H.PMONTH = :PMONTH
  AND H.CUSTOMER BETWEEN :SCUSTOMER AND :ECUSTOMER
  INTO CREDITCARD, CUSTTYPE, CUSTOMER, NAME,
       OPENING, VOUCHER, DEPOSIT, CASH, ADJUST, ENDING
  DO SUSPEND;

end^


ALTER PROCEDURE AR_MUTATION_OLD_CALC(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8),
    REFDATE DATE)
RETURNS (
    CREDITCARD INTEGER,
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    OPENING NUMERIC(15,4),
    VOUCHER NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    ENDING NUMERIC(15,4),
    CUSTTYPE VARCHAR(4),
    XENDING NUMERIC(15,4),
    XBEDA DOUBLE PRECISION)
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable sDate date;
declare variable eDate date;
declare variable fo_adjust double precision;
declare variable pcash double precision;
declare variable XDEPOSIT DOUBLE PRECISION;
declare variable vrow integer;
declare variable adjust1 double precision;
declare variable xTotal DOUBLE PRECISION;
declare variable xPayDate DATE;
declare variable xOpenDate DATE;
declare variable xSisa DOUBLE PRECISION;
declare variable X DOUBLE PRECISION;
begin

  if (SCUSTOMER IS NULL) then BEGIN
     SCUSTOMER = '';
     eCUSTOMER = 'ZZZZZZ';
     REFDATE = '30.05.2003';
  END
  
  execute procedure SP_DATE_BOM (refdate) returning_values sDate;
  execute procedure SP_DATE_EOM   (refdate) returning_values eDate;
  /*##########################################################################*/
  /* company                                                                  */
  /*##########################################################################*/       
  CREDITCARD = 0;
  X = 0;
  for select CUSTOMER, name,CUSTTYPE from sysCUSTOMER
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER, name, CUSTTYPE
  do
  begin
    opening = 0;
    voucher = 0;
    cash = 0;
    adjust = 0;
    ending = 0;
    adjust1 = 0;
    /*========================================================================*/
    /* hitung opening                                                         */
    /*========================================================================*/    
    select sum(total) from ARvch
     where CUSTOMER = :CUSTOMER
       and OpenDate < :sDate
       and source = 'TN'
/*      plan (arvch index (ARVCH_IDX_CUSTOMER_OPENDATE)) For FB.2.x 31-Aug-2011 */
      into voucher;
      
    select sum(total) from ARcash0 where CUSTOMER = :CUSTOMER and DueDate < :sDate
       and status in ('C', 'R', 'L')
       and source = 'TN'
      into cash;
      
    select sum(ARdepos1.total) from ARdepos1
     where ARdepos1.CUSTOMER = :CUSTOMER and ARdepos1.APPlieddate < :sDate
       AND ARdepos1.status IN ('R','C')
      into deposit;
      
    select sum(A.db-A.cr)
      from ARadj A, ARVCH V
     where A.VOUCHERNO = V.NUMBER
       AND V.CUSTOMER = :CUSTOMER
       and A.OpenDate < :sDate
       and source = 'TN'
      into :adjust1;
      
    select sum(D.debit-D.credit) from ARVCH_DETAIL D
    inner JOIN ARVCH H ON D.NUMBER = H.NUMBER and H.CUSTOMER = :CUSTOMER
    where D.source = 'A' /* ADJUSTMENT */
      and D.status = 'C' /* CLOSE, POSTED */
    and D.FODATE < :sDate
    and source = 'TN'
    into adjust;      
    
    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;    
    if (deposit is null) then deposit = 0;

    opening = voucher - cash + adjust + adjust1 - deposit;
    /*========================================================================*/
    /* hitung bulan ini                                                       */
    /*========================================================================*/
    voucher = 0;
    cash    = 0;
    adjust  = 0;
    adjust1 = 0;    
    deposit = 0;    
    select SUM(TOTAL) from ARvch   where CUSTOMER = :CUSTOMER
       and OpenDate between :sDate and :eDate
      into :voucher;
    
    select sum(ARdepos1.total) from ARdepos1
     where ARdepos1.CUSTOMER = :CUSTOMER
       and ARdepos1.APPlieddate between :sDate and :eDate
       AND ARdepos1.status IN ('R','C')
      into deposit;

    select sum(total) from ARcash0 where CUSTOMER = :CUSTOMER
       and DueDate between :sDate and :eDate
       and status in ('C', 'R', 'L')
       and source = 'TN'
      into :cash;

    select sum(A.db-A.cr)
      from ARadj A, ARVCH V
     where A.VOUCHERNO = V.NUMBER
       AND V.CUSTOMER = :CUSTOMER
       and A.OpenDate between :sDate and :eDate
       and source = 'TN'
      into :adjust1;
            
    select sum(D.debit-D.credit) from ARVCH_DETAIL D
    INNER JOIN ARVCH H ON D.NUMBER = H.NUMBER and H.CUSTOMER = :CUSTOMER
    where D.source = 'A' /* ADJUSTMENT */
    and D.status = 'C' /* CLOSE, POSTED */
    and D.FODATE between :sDate and :eDate
    into adjust;
    
    if (ending  is null) then ending  = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;
    if (deposit is null) then deposit = 0;
    adjust = adjust + adjust1 - deposit;
    ending = opening + voucher - cash + adjust;
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0)) then
       suspend;    
  end
  /*##########################################################################*/
  /* credit card                                                              */
  /*##########################################################################*/     
  adjust = 0;
  CREDITCARD = 1;
  CUSTTYPE = 'CARD';
  FOR SELECT CREDITCARD, NAME
      FROM AR_CARD
      where CREDITCARD between :sCUSTOMER and :ECUSTOMER
      INTO :CUSTOMER, :NAME
  DO BEGIN
    /* ---------------------------------------------------------------------- */
    /* summary                                                                */
    /* ---------------------------------------------------------------------- */
    opening = 0;
    voucher = 0;
    cash = 0;
    ending = 0;
    deposit = 0;
    FOR SELECT JR.OPENDATE, JR.TOTAL, JR.PAY_DATE
        FROM AR_CARD_JUR JR 
        WHERE JR.CREDITCARD = :customer
        AND JR.OPENDATE <= :EDATE
/*         PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_CUSTOMER)) For FB.2.x 31-Aug-2011 */
        INTO xOpenDate, xTotal, xPayDate
        DO BEGIN
           xSisa = xTotal;
           if (xOpenDate BETWEEN :SDATE AND :EDATE) then
              Voucher = Voucher + xTotal;
           if (xPayDate is not null) then
           begin
              if (xPayDate BETWEEN :SDATE AND :EDATE) then
                 Cash = Cash + xTotal;
              if (xPayDate <= :edate) then xSisa = 0;
           end
           ending = ending + xSisa;
        END
    
    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    opening  =  ending - voucher + cash;
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0)) then
       suspend;    
  end 
end^


ALTER PROCEDURE AR_MUTATION_OLD_ORIGINAL(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8),
    REFDATE DATE)
RETURNS (
    CREDITCARD INTEGER,
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    OPENING NUMERIC(15,4),
    VOUCHER NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    ENDING NUMERIC(15,4),
    CUSTTYPE VARCHAR(4),
    XENDING NUMERIC(15,4),
    XBEDA DOUBLE PRECISION)
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable sDate date;
declare variable eDate date;
declare variable fo_adjust double precision;
declare variable pcash double precision;
declare variable XDEPOSIT DOUBLE PRECISION;
declare variable vrow integer;
declare variable adjust1 double precision;
declare variable xTotal DOUBLE PRECISION;
declare variable xPayDate DATE;
declare variable xOpenDate DATE;
declare variable xSisa DOUBLE PRECISION;
declare variable X DOUBLE PRECISION;
begin

  if (SCUSTOMER IS NULL) then BEGIN
     SCUSTOMER = '';
     eCUSTOMER = 'ZZZZZZ';
     REFDATE = '30.05.2003';
  END
  
  execute procedure sp_beginofmonth (refdate) returning_values sDate;
  execute procedure sp_endofmonth   (refdate) returning_values eDate;
  /*##########################################################################*/
  /* company                                                                  */
  /*##########################################################################*/       
  CREDITCARD = 0;
  X = 0;
  for select CUSTOMER, name,CUSTTYPE from sysCUSTOMER
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER, name, CUSTTYPE
  do
  begin
    opening = 0;
    voucher = 0;
    cash = 0;
    adjust = 0;
    ending = 0;
    adjust1 = 0;
    /*========================================================================*/
    /* hitung opening                                                         */
    /*========================================================================*/    
    select sum(total) from ARvch
     where CUSTOMER = :CUSTOMER
       and OpenDate < :sDate
/*      plan (arvch index (ARVCH_IDX_CUSTOMER_OPENDATE)) For FB.2.x 31-Aug-2011 */
      into voucher;
      
    select sum(total) from ARcash0 where CUSTOMER = :CUSTOMER and DueDate < :sDate
       and status in ('C', 'R', 'L')
      into cash;
      
    select sum(ARdepos1.total) from ARdepos1
     where ARdepos1.CUSTOMER = :CUSTOMER and ARdepos1.APPlieddate < :sDate
       AND ARdepos1.status IN ('R','C')
      into deposit;
      
    select sum(A.db-A.cr)
      from ARadj A, ARVCH V
     where A.VOUCHERNO = V.NUMBER
       AND V.CUSTOMER = :CUSTOMER
       and A.OpenDate < :sDate
      into :adjust1;
      
    select sum(D.debit-D.credit) from ARVCH_DETAIL D
    inner JOIN ARVCH H ON D.NUMBER = H.NUMBER and H.CUSTOMER = :CUSTOMER
    where D.source = 'A' /* ADJUSTMENT */
      and D.status = 'C' /* CLOSE, POSTED */
    and D.FODATE < :sDate
    into adjust;      
    
    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;    
    if (deposit is null) then deposit = 0;

    opening = voucher - cash + adjust + adjust1 - deposit;
    /*========================================================================*/
    /* hitung bulan ini                                                       */
    /*========================================================================*/
    voucher = 0;
    cash    = 0;
    adjust  = 0;
    adjust1 = 0;    
    deposit = 0;    
    select SUM(TOTAL) from ARvch   where CUSTOMER = :CUSTOMER
       and OpenDate between :sDate and :eDate
      into :voucher;
    
    select sum(ARdepos1.total) from ARdepos1
     where ARdepos1.CUSTOMER = :CUSTOMER
       and ARdepos1.APPlieddate between :sDate and :eDate
       AND ARdepos1.status IN ('R','C')
      into deposit;

    select sum(total) from ARcash0 where CUSTOMER = :CUSTOMER
       and DueDate between :sDate and :eDate
       and status in ('C', 'R', 'L')
      into :cash;

    select sum(A.db-A.cr)
      from ARadj A, ARVCH V
     where A.VOUCHERNO = V.NUMBER
       AND V.CUSTOMER = :CUSTOMER
       and A.OpenDate between :sDate and :eDate
      into :adjust1;
            
    select sum(D.debit-D.credit) from ARVCH_DETAIL D
    INNER JOIN ARVCH H ON D.NUMBER = H.NUMBER and H.CUSTOMER = :CUSTOMER
    where D.source = 'A' /* ADJUSTMENT */
    and D.status = 'C' /* CLOSE, POSTED */
    and D.FODATE between :sDate and :eDate
    into adjust;
    
    if (ending  is null) then ending  = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;
    if (deposit is null) then deposit = 0;
    adjust = adjust + adjust1 - deposit;
    ending = opening + voucher - cash + adjust;
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0)) then
       suspend;    
  end
  /*##########################################################################*/
  /* credit card                                                              */
  /*##########################################################################*/     
  adjust = 0;
  CREDITCARD = 1;
  CUSTTYPE = 'CARD';
  FOR SELECT CREDITCARD, NAME
      FROM AR_CARD
      where CREDITCARD between :sCUSTOMER and :ECUSTOMER
      INTO :CUSTOMER, :NAME
  DO BEGIN
    /* ---------------------------------------------------------------------- */
    /* summary                                                                */
    /* ---------------------------------------------------------------------- */
    opening = 0;
    voucher = 0;
    cash = 0;
    ending = 0;
    deposit = 0;
    FOR SELECT JR.OPENDATE, JR.TOTAL, JR.PAY_DATE
        FROM AR_CARD_JUR JR 
        WHERE JR.CREDITCARD = :customer
        AND JR.OPENDATE <= :EDATE
/*         PLAN (AR_CARD_JUR INDEX (AR_CARD_JUR_IDX_CUSTOMER)) For FB.2.x 31-Aug-2011 */
        INTO xOpenDate, xTotal, xPayDate
        DO BEGIN
           xSisa = xTotal;
           if (xOpenDate BETWEEN :SDATE AND :EDATE) then
              Voucher = Voucher + xTotal;
           if (xPayDate is not null) then
           begin
              if (xPayDate BETWEEN :SDATE AND :EDATE) then
                 Cash = Cash + xTotal;
              if (xPayDate <= :edate) then xSisa = 0;
           end
           ending = ending + xSisa;
        END
    
    if (opening is null) then opening = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    opening  =  ending - voucher + cash;
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0)) then
       suspend;    
  end 
end^


ALTER PROCEDURE AR_OVERLIMIT_VIEW
RETURNS (
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    LIMIT DOUBLE PRECISION,
    DUE DOUBLE PRECISION,
    OVERDUE DOUBLE PRECISION)
AS
declare variable FOSysDate DATE;
declare variable X INTEGER;
BEGIN
  SELECT arsysdate FROM SYSPARAM WHERE ID = 1
  INTO :FOSysDate;
  
  SELECT COUNT(*) FROM ar_overlimit
  WHERE FODATE = :FOSysDate
  INTO X;
  
  if (X = 0) then
  BEGIN
     DELETE FROM AR_OVERLIMIT;
     FOR SELECT CUSTOMER, NAME, CREDITLIMIT FROM SYSCUSTOMER
         WHERE CREDITLIMIT <> 0
     INTO :CUSTOMER, :NAME, :LIMIT DO
     BEGIN
        select SUM(totaldue)
        from ARvch
        where PAIDSTATUS = 'O'
        AND CUSTOMER = :CUSTOMER
        PLAN (ARVCH INDEX (ARVCH_IDX_PAIDSTATUS))
        into DUE;
        if (DUE IS NULL) then DUE = 0;
        if (DUE > LIMIT) then
        BEGIN
           INSERT INTO AR_OVERLIMIT
           (FODATE, CUSTOMER, NAME, LIMIT, DUE)
           VALUES
           (:FOSysDate, :CUSTOMER, :NAME, :LIMIT, :DUE);
        END
     END
  END
  /*  */
  FOR SELECT CUSTOMER, NAME, LIMIT, DUE, OVERDUE FROM AR_OVERLIMIT
    INTO
      :CUSTOMER,
      :NAME,
      :LIMIT,
      :DUE,
      :OVERDUE
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE AR_QUICK_BROWSE(
    CUSTOMER VARCHAR(8))
RETURNS (
    DOCTYPE VARCHAR(8),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    DOCUMENT VARCHAR(20),
    TOTAL DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION)
AS
BEGIN
  if (CUSTOMER IS NULL) then
  BEGIN
     CUSTOMER = 'B05002';
  END
  BALANCE =0;
  DOCTYPE = 'DEP';
  FOR
    SELECT NUMBER, OPENDATE, OPENDATE, DOCUMENT, -FOREX_BALANCE
    FROM ardepos0
    WHERE CUSTOMER = :CUSTOMER
    AND STATUS_APPLY = 'O'
    PLAN (ardepos0 INDEX (ARDEPOS0_IDX_CUSTOMER_STATUS))
    INTO
      :NUMBER,
      :OPENDATE,
      :DUEDATE,
      :DOCUMENT,
      :TOTAL
  DO
  BEGIN
    BALANCE = BALANCE + TOTAL;
    SUSPEND;
  END    
  DOCTYPE = 'VCH';
  FOR
    SELECT NUMBER, OPENDATE, DUEDATE, DOCUMENT, TOTALDUE_PREPARE
    FROM ARVCH
    WHERE CUSTOMER = :CUSTOMER
    AND PAIDSTATUS = 'O'
    AND TOTALDUE_PREPARE > 0
    PLAN (ARVCH INDEX (ARVCH_IDX_CUSTOMER_STATUS))
    INTO
      :NUMBER,
      :OPENDATE,
      :DUEDATE,
      :DOCUMENT,
      :TOTAL
  DO
  BEGIN
    BALANCE = BALANCE + TOTAL;
    SUSPEND;
  END

END^


ALTER PROCEDURE AR_QUICK_DELETE(
    QNUMBER INTEGER,
    REMARK VARCHAR(40),
    USERID VARCHAR(8))
AS
DECLARE VARIABLE DOC_TYPE CHAR(1);
DECLARE VARIABLE DOC_NUMBER INTEGER;
DECLARE VARIABLE CASH_NO INTEGER;
begin
  FOR SELECT DOC_TYPE, DOC_NUMBER FROM ARCASH_QUICK_DETAIL
      WHERE NUMBER = :QNUMBER
      INTO DOC_TYPE, DOC_NUMBER
  DO
  BEGIN
    IF (DOC_TYPE = 'D') THEN
    BEGIN
       DELETE FROM ARDEPOS1 WHERE NUMBER = :DOC_NUMBER;
       DELETE FROM ARDEPOS0 WHERE NUMBER = :DOC_NUMBER;
    END
    IF (DOC_TYPE = 'V') THEN
    BEGIN
       SELECT NUMBER FROM ARCASH1 WHERE VOUCHERNO = :DOC_NUMBER INTO CASH_NO;
       DELETE FROM ARCASH1 WHERE VOUCHERNO = :DOC_NUMBER;
       DELETE FROM ARCASH0 WHERE NUMBER = :CASH_NO;
       DELETE FROM ARDEPOS1 WHERE VOUCHERNO = :DOC_NUMBER;
    END
  END
  UPDATE ARCASH_QUICK SET DOCUMENT = 'Cancelled', TEXT = :REMARK, TOTAL_DUE = 0, TOTAL_PAID = 0,
         TOTAL_DEPOSIT = 0, CREATEUSER = :USERID
   WHERE NUMBER = :QNUMBER;
  DELETE FROM ARCASH_QUICK_DETAIL WHERE NUMBER = :QNUMBER;
end^


ALTER PROCEDURE AR_QUICK_JOURNAL(
    QNUMBER INTEGER)
RETURNS (
    NUMBER INTEGER,
    CUSTOMER VARCHAR(8),
    DOC_TYPENAME VARCHAR(10),
    DOC_TYPE CHAR(1),
    DOC_SOURCE VARCHAR(4),
    DOC_NUMBER INTEGER,
    DOC_OPENDATE DATE,
    DOC_DUEDATE DATE,
    DOC_DOCUMENT VARCHAR(20),
    DOC_TEXT VARCHAR(40),
    DOC_TOTAL DOUBLE PRECISION,
    DOC_APPLY DOUBLE PRECISION,
    DOC_APPLY_DEPOSIT DOUBLE PRECISION,
    DOC_DUE DOUBLE PRECISION,
    DOC_BALANCE DOUBLE PRECISION)
AS
declare variable OPENDATE DATE;
BEGIN
  if (QNUMBER IS NULL) then
     QNUMBER = 190;
     
  SELECT CUSTOMER, OPENDATE FROM ARCASH_QUICK
  WHERE NUMBER = :QNUMBER
  INTO :CUSTOMER, OPENDATE;
  
  DOC_BALANCE = 0;
  FOR
    SELECT NUMBER, DOC_TYPE, DOC_NUMBER, DOC_TOTAL,
           DOC_APPLY, DOC_APPLY_DEPOSIT
      FROM ARCASH_QUICK_DETAIL
      WHERE NUMBER = :QNUMBER
    INTO
      :NUMBER,
      :DOC_TYPE,
      :DOC_NUMBER,
      :DOC_TOTAL,
      :DOC_APPLY,
      :DOC_APPLY_DEPOSIT
  DO
  BEGIN
    if (DOC_TYPE = 'D') then
    BEGIN
       DOC_TYPENAME = 'Deposit';
       DOC_SOURCE  = '';
       SELECT DOCUMENT, OPENDATE, OPENDATE
       FROM ARDEPOS0
       WHERE NUMBER = :DOC_NUMBER
       INTO DOC_DOCUMENT, DOC_OPENDATE, DOC_DUEDATE;
       DOC_TEXT = '  Deposit';
       DOC_DUE = 0;
       DOC_BALANCE = DOC_BALANCE - DOC_TOTAL;
    END
    ELSE
    BEGIN
       if (DOC_TYPE = 'V') then DOC_TYPENAME = 'Invoice';
       SELECT DOCUMENT, OPENDATE, DUEDATE, NAME, SOURCE
       FROM ARVCH
       WHERE NUMBER = :DOC_NUMBER
       INTO DOC_DOCUMENT, DOC_OPENDATE, DOC_DUEDATE, DOC_TEXT, DOC_SOURCE;
       DOC_DUE = DOC_TOTAL - DOC_APPLY - DOC_APPLY_DEPOSIT;
       DOC_BALANCE = DOC_BALANCE + DOC_TOTAL-DOC_APPLY - DOC_APPLY_DEPOSIT;
    END
    SUSPEND;
  END
  DOC_TYPENAME = 'Deposit';
  DOC_TYPE     = 'D';
  DOC_APPLY_DEPOSIT = 0;
  DOC_TOTAL = 0;
  NUMBER = 0;
  DOC_TEXT = '    Sisa Deposit';
  FOR SELECT NUMBER, DOCUMENT, -BALANCE, OPENDATE, OPENDATE FROM ARDEPOS0
       WHERE CUSTOMER = :CUSTOMER
       AND NOT (BALANCE BETWEEN -0.9 AND 0.9)
       INTO DOC_NUMBER, DOC_DOCUMENT, DOC_DUE, DOC_OPENDATE, DOC_DUEDATE
  DO
  BEGIN
    DOC_BALANCE = DOC_BALANCE + DOC_DUE;
    SUSPEND;
  END
  
END^


ALTER PROCEDURE AR_QUICK_SAVE(
    CUSTOMER VARCHAR(8),
    OPENDATE DATE,
    DOCUMENT VARCHAR(20),
    TEXT VARCHAR(40),
    TOTAL_PAID DOUBLE PRECISION,
    TOTAL_DUE DOUBLE PRECISION,
    BANK VARCHAR(4),
    CREATEUSER VARCHAR(8))
RETURNS (
    NUMBER INTEGER)
AS
declare variable NUMBER_CASH INTEGER;
declare variable NUMBER_DEPOSIT INTEGER;

declare variable VCH_NUMBER INTEGER;
declare variable VCH_TOTAL  DOUBLE PRECISION;

declare variable DEP_NUMBER INTEGER;
declare variable DEP_TOTAL  DOUBLE PRECISION;

declare variable TOTAL_DEPOSIT DOUBLE PRECISION;
declare variable XTOTAL DOUBLE PRECISION;
declare variable ATOTAL DOUBLE PRECISION;
begin
   DEP_NUMBER = 0;
   DEP_TOTAL  = 0;
   TOTAL_DEPOSIT = 0;
  /* ------------------------------------------------------------------------ */
  /* DEPOSIT                                                                  */
  /* ------------------------------------------------------------------------ */
  FOR SELECT NUMBER, BALANCE
  FROM ardepos0
  WHERE CUSTOMER = :CUSTOMER
  AND STATUS_APPLY = 'O'
  PLAN (ardepos0 INDEX (ARDEPOS0_IDX_CUSTOMER_STATUS))
  ORDER BY NUMBER DESC
  INTO
     :DEP_NUMBER,
     :DEP_TOTAL
  DO
  BEGIN
     TOTAL_DEPOSIT = TOTAL_DEPOSIT + DEP_TOTAL;
  END

  if (DEP_TOTAL IS NULL) then
  BEGIN
     DEP_TOTAL = 0;
     DEP_NUMBER = 0;
  END   
  /* INSERT NEW QUICK CASH ENTRY */
  SELECT MAX(NUMBER) FROM arcash_quick
  INTO :NUMBER;
  if (NUMBER IS NULL) then NUMBER = 0;
  NUMBER = NUMBER + 1;
  
  INSERT INTO ARCASH_QUICK
  ( NUMBER, CUSTOMER, OPENDATE, DOCUMENT, TEXT,
    CREATEUSER, CREATEDATE, STATUS, NUMBER_CASH, NUMBER_DEPOSIT,
    TOTAL_DUE, TOTAL_PAID, TOTAL_DEPOSIT)
  VALUES (
    :NUMBER, :CUSTOMER, :OPENDATE, :DOCUMENT, :TEXT,
    :CREATEUSER, 'NOW', 'O', 0, 0, :TOTAL_DUE, :TOTAL_PAID, :DEP_TOTAL);

  /* APPLY OLD DEPOSIT FIRST */
  if (DEP_TOTAL > 0) then
  BEGIN
     FOR
       SELECT NUMBER, TOTALDUE_PREPARE
       FROM ARVCH
       WHERE CUSTOMER = :CUSTOMER
       AND PAIDSTATUS = 'O'
       AND TOTALDUE_PREPARE > 0
       PLAN (ARVCH INDEX (ARVCH_IDX_CUSTOMER_STATUS))
       ORDER BY NUMBER
       INTO :VCH_NUMBER, :VCH_TOTAL
     DO
     BEGIN
       if (DEP_TOTAL > 0) then
       BEGIN
          if (VCH_TOTAL < DEP_TOTAL) then XTOTAL = VCH_TOTAL;
          ELSE XTOTAL = DEP_TOTAL;
          INSERT INTO ARDEPOS1
          ( NUMBER, VOUCHERNO, APPLIEDDATE, CUSTOMER, TEXT1, STATUS,
            CREATEDATE, EDITDATE, CRATEUSER, EDITUSER,
            EXCHANGE, FOREX_TOTAL, VCH_EXCHANGE,VCH_GAINLOSS)
          VALUES
          (:DEP_NUMBER, :VCH_NUMBER, :OPENDATE, :CUSTOMER, :TEXT, 'O',
            'NOW', 'NOW', :CREATEUSER, :CREATEUSER,
            1, :XTOTAL, 1, 0);
            
          INSERT INTO ARCASH_QUICK_DETAIL
             ( NUMBER, DOC_TYPE, DOC_NUMBER, DOC_TOTAL, DOC_APPLY, DOC_APPLY_DEPOSIT)
          VALUES
             (:NUMBER, 'V', :VCH_NUMBER, :VCH_TOTAL, 0, :XTOTAL);
             
          DEP_TOTAL = DEP_TOTAL - XTOTAL;
       END
     END
  END

  /* ------------------------------------------------------------------------ */
  /* SAVE CASH HEADER                                                         */
  /* ------------------------------------------------------------------------ */
  SELECT MAX(NUMBER) FROM ARCASH0
  INTO :NUMBER_CASH;
  if (NUMBER_CASH IS NULL) then NUMBER_CASH = 0;
  NUMBER_CASH = NUMBER_CASH + 1;
         
  INSERT INTO ARCASH0
   (NUMBER, DOCUMENT, CHECK_NUMBER,
    CUSTOMER, OPENDATE, DUEDATE, STATUS, BANK,
    CREATEDATE, EDITDATE, CREATEUSER, EDITUSER, CURRENCY, EXCHANGE, SOURCE)
  VALUES (
    :NUMBER_CASH, :DOCUMENT, :DOCUMENT,
    :CUSTOMER, :OPENDATE, :OPENDATE, 'O', :BANK,
    'NOW', 'NOW', :CREATEUSER, :CREATEUSER, 'IDR', 1, 'TN');
    
  /* ------------------------------------------------------------------------ */
  /* SAVE CASH DETAIL                                                         */
  /* ------------------------------------------------------------------------ */  
  ATOTAL = TOTAL_PAID;
  FOR
     SELECT NUMBER, TOTALDUE_PREPARE
     FROM ARVCH
     WHERE CUSTOMER = :CUSTOMER
     AND PAIDSTATUS = 'O'
     AND TOTALDUE_PREPARE > 0
     PLAN (ARVCH INDEX (ARVCH_IDX_CUSTOMER_STATUS))
     ORDER BY NUMBER
     INTO :VCH_NUMBER, :VCH_TOTAL
   DO
   BEGIN
       if (ATOTAL > 0) then
       BEGIN
          if (VCH_TOTAL < ATOTAL) then XTOTAL = VCH_TOTAL;
          ELSE XTOTAL = ATOTAL;

          INSERT INTO ARCASH1
            (NUMBER, CUSTOMER, VOUCHERNO, TEXT1, CURRENCY,
            EXCHANGE, FOREX_TOTAL, VCH_EXCHANGE)
          VALUES
            (:NUMBER_CASH, :CUSTOMER, :VCH_NUMBER, 'Quick ' || :NUMBER, 'IDR',
            1, :XTOTAL, 1);

          ATOTAL = ATOTAL - XTOTAL;

          INSERT INTO ARCASH_QUICK_DETAIL
             ( NUMBER, DOC_TYPE, DOC_NUMBER, DOC_TOTAL, DOC_APPLY, DOC_APPLY_DEPOSIT)
          VALUES
             (:NUMBER, 'V', :VCH_NUMBER, :VCH_TOTAL, :XTOTAL, 0);
       END
       ELSE
       BEGIN /* SISA HUTANG YANG BELUM DI BAYAR */
          INSERT INTO ARCASH_QUICK_DETAIL
             ( NUMBER, DOC_TYPE, DOC_NUMBER, DOC_TOTAL, DOC_APPLY, DOC_APPLY_DEPOSIT)
          VALUES
             (:NUMBER, 'V', :VCH_NUMBER, :VCH_TOTAL, 0, 0);
       END
       
   END
  /* ------------------------------------------------------------------------ */
  /* SAVE DEPOSIT JIKA MASIH ADA SISA                                         */
  /* ------------------------------------------------------------------------ */
  NUMBER_DEPOSIT = 0;
  if (ATOTAL > 50) then
  BEGIN
     SELECT MAX(NUMBER) FROM ardepos0
     INTO :NUMBER_DEPOSIT;
     if (NUMBER_DEPOSIT IS NULL) then NUMBER_DEPOSIT = 0;
     NUMBER_DEPOSIT = NUMBER_DEPOSIT + 1;

     INSERT INTO ARDEPOS0
       (NUMBER, OPENDATE, DOCUMENT, STATUS, TOTAL, CUSTOMER, BANK,
        CREATEDATE, EDITDATE, CREATEUSER, EDITUSER,
        CHECK_NUMBER, CURRENCY, EXCHANGE, FOREX_TOTAL)
     VALUES (
       :NUMBER_DEPOSIT, :OPENDATE, :DOCUMENT, 'O', :ATOTAL, :CUSTOMER, :BANK,
       'NOW', 'NOW', :CREATEUSER, :CREATEUSER, :DOCUMENT, 'IDR', 1, :ATOTAL);
       
     INSERT INTO ARCASH_QUICK_DETAIL
        ( NUMBER, DOC_TYPE, DOC_NUMBER, DOC_TOTAL, DOC_APPLY, DOC_APPLY_DEPOSIT)
     VALUES
        (:NUMBER, 'D', :NUMBER_DEPOSIT, :ATOTAL, :ATOTAL, 0);
   END
   
   UPDATE arcash_quick SET NUMBER_CASH = :NUMBER_CASH,
          NUMBER_DEPOSIT = :NUMBER_DEPOSIT
   WHERE NUMBER = :NUMBER;
   
   SUSPEND;
end^


ALTER PROCEDURE AR_VCH_JOURNAL(
    ANUMBER INTEGER)
RETURNS (
    NUMBER INTEGER,
    REMARK VARCHAR(80),
    DOCNUMBER INTEGER,
    DOCTYPE VARCHAR(12),
    OPENDATE DATE,
    VOUCHER NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    DEPOSIT DOUBLE PRECISION,
    TOTAL NUMERIC(15,4),
    DUE DOUBLE PRECISION)
AS
begin
    NUMBER = ANUMBER;
    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/
    DOCTYPE = 'Voucher';
    select total, opendate, source_remark, sourceid
    from ARvch
    where NUMBER = :ANUMBER
    into voucher, opendate, remark, docnumber;
    CASH = 0;
    ADJUST = 0;
    TOTAL = VOUCHER;
    DEPOSIT = 0;
    DUE = TOTAL;
    suspend;
    /* ------------------------------------------------------------------- */
    /* select deposit                                                      */
    /* ------------------------------------------------------------------- */
    CASH = 0;
    ADJUST = 0;
    DEPOSIT = 0;
    VOUCHER = 0;    
    DOCTYPE = 'Deposit';
    for select D.total, D.APPLIEDDATE, D.text1, D.number from ARdepos1 D
        where D.voucherno = :number
        into deposit, opendate, remark, docnumber
    do begin
       TOTAL = -DEPOSIT;
       DUE = DUE + TOTAL;
       suspend;
    end    

    /* ------------------------------------------------------------------- */
    /* select cash payment                                                 */
    /* ------------------------------------------------------------------- */
    CASH = 0;
    ADJUST = 0;
    DEPOSIT = 0;
    VOUCHER = 0;
    DOCTYPE = 'Payment';
    for select D.total, H.duedate, H.CHECK_NUMBER, H.NUMBER from ARcash1 D
        inner join ARcash0 H on H.number = D.number
        where D.voucherno = :number
        into cash, opendate, remark, docnumber
    do begin
       TOTAL = -CASH;
       DUE = DUE + TOTAL;
       suspend;
     end
    /* ------------------------------------------------------------------- */
    /* select adjustment                                                   */
    /* ------------------------------------------------------------------- */
    CASH = 0;
    ADJUST = 0;
    DEPOSIT = 0;
    VOUCHER = 0;        
    DOCTYPE = 'Adjustment';
    for select (db-cr), opendate, number  from ARadj
        where voucherno = :number
        into adjust, opendate, docnumber
    do begin
       remark = '';
       total = adjust;
       DUE = DUE + TOTAL;
       suspend;
    end
    CASH = 0;
    ADJUST = 0;
    DEPOSIT = 0;
    VOUCHER = 0;        
    /* ------------------------------------------------------------------- */
    /* Front Office adjustment                                             */
    /* ------------------------------------------------------------------- */
    DOCTYPE = 'Correction';
    for select (Debit-Credit), fodate, remark, fo_trans_id from arvch_detail
        where Number = :number
        and status = 'C' /* C = Close, sudah di posting ke FO, O=Open */
        and source = 'A' /* A = Adjustment, f= Front Office */
    into Adjust, opendate, remark, docnumber
    do begin
       total = adjust;    
       DUE = DUE + TOTAL;
       suspend;
    end
end^


ALTER PROCEDURE BB_ACC_CREATE(
    ABANK VARCHAR(4),
    ADATE DATE)
AS
declare variable PYEAR INTEGER;
declare variable PMONTH INTEGER;
declare variable SDATE DATE;
declare variable EDATE DATE;
declare variable VROW INTEGER;
begin
  EXECUTE PROCEDURE SP_BEGINOFMONTH(ADATE) RETURNING_VALUES(SDATE);
  EXECUTE PROCEDURE SP_ENDOFMONTH(ADATE)   RETURNING_VALUES(EDATE);
  
  SELECT COUNT(*) FROM BBACC
  WHERE BANK = :ABANK
  AND BBDATE BETWEEN :SDATE AND :EDATE
  INTO :VROW;
  if (VROW < 28) then
     WHILE (SDATE <= EDATE) DO
     BEGIN
       SELECT COUNT(*) FROM BBACC
       WHERE BANK = :ABANK
       AND BBDATE = :SDATE
       INTO :VROW;
       if (VROW = 0 ) then
          insert into bbacc (bank, bbdate, opening, db, cr, forex_db, forex_cr, bbline)
          values
          (:abank, :sdate, 0,0,0,0, 0,0);
       sdate = sdate+1;
     END
end^


ALTER PROCEDURE BB_CASHQ(
    SDATE DATE,
    BANK VARCHAR(4))
RETURNS (
    WK INTEGER,
    WKSDATE DATE,
    WKEDATE DATE,
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION)
AS
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
BEGIN
  IF (SDATE IS NULL) THEN
      SELECT INVSYSDATE FROM SYSPARAM WHERE ID = 1 INTO :SDATE;

  IF (Y < 2000) THEN
     EXECUTE PROCEDURE SP_ENCODEDATE(Y, M, D) RETURNING_VALUES SDATE;

  D = -1;
  WHILE (D <> 5) DO
  BEGIN
    EXECUTE PROCEDURE SP_DAYOFWEEK(SDATE) RETURNING_VALUES D;
    SDATE = SDATE-1;
  END
  WK = 0;

  WHILE (WK <= 7) DO
  BEGIN
    WKSDATE = SDATE+WK*7;
    WKEDATE = WKSDATE+6;
    SELECT SUM(DB), SUM(CR) FROM BBJUR
     WHERE BBDATE BETWEEN :WKSDATE AND :WKEDATE
     AND BANK = :BANK
     AND SOURCE = 'BB'
     INTO DB, CR;

    IF (DB IS NULL) THEN DB = 0;
    IF (CR IS NULL) THEN CR = 0;
    TOTAL = CR-DB;
    SUSPEND;
    WK = WK+1;
    WKSDATE = WKEDATE + 1;
    WKEDATE = WKSDATE + 6;
  END

END^


ALTER PROCEDURE BB_DAILY_REPORT(
    BBDATE DATE)
RETURNS (
    BANK VARCHAR(4),
    NAME VARCHAR(40),
    CURRENCY VARCHAR(4),
    OPENING DOUBLE PRECISION,
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    ENDING DOUBLE PRECISION,
    FOREX_OPENING DOUBLE PRECISION,
    FOREX_DB DOUBLE PRECISION,
    FOREX_CR DOUBLE PRECISION,
    FOREX_ENDING DOUBLE PRECISION)
AS
BEGIN
  FOR
    SELECT BANK, BANKNAME, CURRENCY FROM SYSBANK
    ORDER BY BANK
    INTO :BANK, :NAME, :CURRENCY
  DO
  BEGIN
    SELECT OPENING, DB, CR, ENDING,
           FOREX_OPENING,FOREX_DB, FOREX_CR, FOREX_ENDING
    FROM BBACC
    WHERE BANK = :BANK
    AND BBDATE = :BBDATE
    INTO
      :OPENING,
      :DB,
      :CR,
      :ENDING,
      :FOREX_OPENING,
      :FOREX_DB,
      :FOREX_CR,
      :FOREX_ENDING;
    if (OPENING IS NULL) then
    BEGIN
      OPENING = 0;
      DB = 0;
      CR = 0;
      ENDING = 0;
      FOREX_OPENING = 0;
      FOREX_DB = 0;
      FOREX_CR = 0;
      FOREX_ENDING =0;
    END
    SUSPEND;
  END
END^


ALTER PROCEDURE BB_GAINLOSS(
    BANK VARCHAR(4),
    SDATE DATE,
    EDATE DATE)
RETURNS (
    PBANK VARCHAR(4),
    PBANKNAME VARCHAR(40),
    BBDATE DATE,
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    OPENING DOUBLE PRECISION,
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    ENDING DOUBLE PRECISION,
    FOREX_OPENING DOUBLE PRECISION,
    FOREX_DB DOUBLE PRECISION,
    FOREX_CR DOUBLE PRECISION,
    FOREX_ENDING DOUBLE PRECISION,
    NET DOUBLE PRECISION,
    FOREX_NET DOUBLE PRECISION,
    GAINLOSS DOUBLE PRECISION,
    GAINLOSS_OPENING DOUBLE PRECISION,
    TOTAL_GAINLOSS DOUBLE PRECISION)
AS
DECLARE VARIABLE YESTERDAY_EXCHANGE INTEGER;
BEGIN
  IF (BANK IS NULL) THEN
  BEGIN
     BANK = '010';
     SDATE = '1.8.2005';
     EDATE = '31.8.2005';
  END
  
  SELECT BANK, BANKNAME FROM SYSBANK
  WHERE BANK = :BANK
  INTO PBANK, PBANKNAME;
  
  SELECT  OPENING, FOREX_OPENING, FOREX_OPENING * EXCHANGE-OPENING, EXCHANGE FROM BBACC
  WHERE BANK = :BANK
  AND BBDATE = :SDATE
  INTO OPENING, FOREX_OPENING, GAINLOSS_OPENING, EXCHANGE;

  if (OPENING IS NULL) then
  BEGIN
     OPENING = 0;
     FOREX_OPENING = 0;
     GAINLOSS_OPENING = 0;
     EXCHANGE = 1;
  END

  if (FOREX_OPENING <> 0) then YESTERDAY_EXCHANGE = OPENING/FOREX_OPENING;
  ELSE YESTERDAY_EXCHANGE = EXCHANGE;
  TOTAL_GAINLOSS = 0;
  FOR
    SELECT CURRENCY, BBDATE, EXCHANGE, DB, CR,
    FOREX_DB, FOREX_CR
    FROM BBACC
    WHERE BANK = :BANK
    AND BBDATE BETWEEN :SDATE AND :EDATE
    ORDER BY BBDATE /* 8 MAY 2009 */
    INTO
      :CURRENCY,
      :BBDATE,
      :EXCHANGE,
      :DB,
      :CR,
      :FOREX_DB,
      :FOREX_CR
  DO
  BEGIN
    ENDING = OPENING + DB - CR;
    FOREX_ENDING = FOREX_OPENING + FOREX_DB - FOREX_CR;
    NET = DB - CR;
    FOREX_NET = FOREX_DB - FOREX_CR;
    GAINLOSS = FOREX_NET * EXCHANGE - NET;
    GAINLOSS_OPENING = FOREX_OPENING * (EXCHANGE - YESTERDAY_EXCHANGE);
    TOTAL_GAINLOSS = TOTAL_GAINLOSS + GAINLOSS +GAINLOSS_OPENING;
    SUSPEND;
    OPENING = ENDING;
    FOREX_OPENING = FOREX_ENDING;
    YESTERDAY_EXCHANGE = EXCHANGE;
  END
END^


ALTER PROCEDURE BB_GL_DISCREPANCY(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    BANK VARCHAR(4),
    NAME VARCHAR(40),
    ACCOUNT VARCHAR(20),
    DEPT VARCHAR(4),
    COST VARCHAR(4),
    OPENING_BANK DOUBLE PRECISION,
    OPENING_LEDGER DOUBLE PRECISION,
    ENDING_BANK DOUBLE PRECISION,
    ENDING_LEDGER DOUBLE PRECISION,
    MUTATION_BANK DOUBLE PRECISION,
    MUTATION_LEDGER DOUBLE PRECISION,
    OPENING_DELTA DOUBLE PRECISION,
    ENDING_DELTA DOUBLE PRECISION,
    MUTATION_DELTA DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
BEGIN
  SDATE = '1.'|| PMONTH || '.' || PYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES (EDATE);
  FOR
    SELECT BANK, BANKNAME, GL_ACCOUNT, GL_DEPT, GL_COST FROM SYSBANK
    INTO BANK, NAME, ACCOUNT, DEPT, COST
  DO
  BEGIN
     OPENING_BANK = NULL;
     ENDING_BANK = NULL;
     
     OPENING_LEDGER = NULL;
     ENDING_LEDGER = NULL;
     
     SELECT OPENING  FROM BBACC
     WHERE BANK = :BANK
     AND BBDATE = :SDATE
     INTO OPENING_BANK;
     IF (OPENING_BANK IS NULL) THEN
        OPENING_BANK = 0;
     
     SELECT ENDING FROM BBACC
     WHERE BANK = :BANK
     AND BBDATE = :EDATE
     INTO ENDING_BANK;
     IF (ENDING_BANK IS NULL) THEN
        ENDING_BANK = 0;
     
     SELECT OPENING, ENDING FROM GLACC
     WHERE PYEAR = :PYEAR
     AND PMONTH = :PMONTH
     AND ACCOUNT = :ACCOUNT
     AND DEPART = :DEPT
     AND COST = :COST
     INTO OPENING_LEDGER, ENDING_LEDGER;
     
     IF (ENDING_LEDGER IS NULL) THEN
     BEGIN
        OPENING_LEDGER = 0;
        ENDING_LEDGER = 0;
     END
     MUTATION_BANK = ENDING_BANK - OPENING_BANK;
     MUTATION_LEDGER = ENDING_LEDGER - OPENING_LEDGER;
     OPENING_DELTA = OPENING_LEDGER - OPENING_BANK;
     ENDING_DELTA = ENDING_LEDGER - ENDING_BANK;
     MUTATION_DELTA = MUTATION_LEDGER - MUTATION_BANK;
     SUSPEND;
  END
END^


ALTER PROCEDURE BB_JUR_REPORT(
    PBANK VARCHAR(4),
    PSDATE DATE,
    PEDATE DATE)
RETURNS (
    NUMBER INTEGER,
    BANK VARCHAR(4),
    BBDATE DATE,
    BBLINE INTEGER,
    STATUS CHAR(1),
    DOCUMENT VARCHAR(20),
    BBCODE VARCHAR(4),
    ACCOUNT VARCHAR(20),
    DEPT VARCHAR(4),
    COST VARCHAR(4),
    OPENING DOUBLE PRECISION,
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION,
    NOTE VARCHAR(1000),
    REMARK VARCHAR(40),
    REF VARCHAR(20),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    SOURCENUMBER INTEGER,
    CREATE_BY VARCHAR(8),
    CREATE_DATE DATE,
    EDIT_BY VARCHAR(8),
    EDIT_DATE DATE,
    COANAME VARCHAR(40),
    DEPTNAME VARCHAR(40),
    COSTNAME VARCHAR(40),
    FOREX_OPENING DOUBLE PRECISION,
    FOREX_DB DOUBLE PRECISION,
    FOREX_CR DOUBLE PRECISION,
    FOREX_BALANCE DOUBLE PRECISION)
AS
DECLARE VARIABLE XDATE DATE;
DECLARE VARIABLE XGAINLOSS DOUBLE PRECISION;
DECLARE VARIABLE EOM DATE;
BEGIN
  IF (PSDATE IS NULL) THEN
  BEGIN
     PSDATE = '29.4.2005';
     PEDATE = '30.4.2005';
     PBANK  = 'P002';
  END
  SELECT OPENING, FOREX_OPENING FROM bbacc
  WHERE BANK = :PBANK
  AND BBDATE = :PSDATE
  INTO Balance, FOREX_BALANCE;
  if (balance is null) then balance = 0;
  XDATE = PSDATE;

  WHILE (XDATE <= PEDATE) DO
  BEGIN
    FOR
      SELECT JR.NUMBER,
           JR.BANK,
           JR.BBDATE,
           JR.BBLINE,
           JR.STATUS,
           JR.DOCUMENT,
           JR.BBCODE,
           JR.ACCOUNT,
           JR.DEPT,
           JR.COST,
           JR.DB,
           JR.CR,
           JR.NOTE,
           JR.REMARK,
           JR.REF,
           JR.CURRENCY,
           JR.EXCHANGE,
           JR.APPLICATION,
           JR.SOURCE,
           JR.SOURCENUMBER,
           JR.CREATE_BY,
           JR.CREATE_DATE,
           JR.EDIT_BY,
           JR.EDIT_DATE,
           COA.NAME COANAME,
           DP.NAME DEPTNAME,
           CS.NAME COSTNAME,
           JR.FOREX_DB,
           JR.FOREX_CR
      FROM BBJUR JR
         LEFT JOIN GLCOA COA ON (JR.ACCOUNT = COA.ACCOUNT)
         LEFT JOIN GLDEPT DP ON (JR.DEPT = DP.DEPART)
         LEFT JOIN GLCOST CS ON (JR.COST = CS.COST)
      WHERE JR.BANK = :PBANK
      AND JR.BBDATE = :XDATE
      ORDER BY JR.BBDATE, JR.BBLINE
      INTO
        :NUMBER,
        :BANK,
        :BBDATE,
        :BBLINE,
        :STATUS,
        :DOCUMENT,
        :BBCODE,
        :ACCOUNT,
        :DEPT,
        :COST,
        :DB,
        :CR,
        :NOTE,
        :REMARK,
        :REF,
        :CURRENCY,
        :EXCHANGE,
        :APPLICATION,
        :SOURCE,
        :SOURCENUMBER,
        :CREATE_BY,
        :CREATE_DATE,
        :EDIT_BY,
        :EDIT_DATE,
        :COANAME,
        :DEPTNAME,
        :COSTNAME,
        :FOREX_DB,
        :FOREX_CR
        
    DO
    BEGIN
      OPENING = BALANCE;
      BALANCE = BALANCE + CR-DB;
      FOREX_OPENING = FOREX_BALANCE;
      FOREX_BALANCE = FOREX_BALANCE + FOREX_CR - FOREX_DB;
      SUSPEND;
    END
    
    EXECUTE PROCEDURE SP_ENDOFMONTH(XDATE) RETURNING_VALUES(EOM);
    
    IF (XDATE = EOM) THEN
    BEGIN
      SELECT GAINLOSS FROM bbacc WHERE BANK = :PBANK AND BBDATE = :XDATE
      INTO XGAINLOSS;
    
      IF (XGAINLOSS IS NULL) THEN XGAINLOSS = 0;

      IF (XGAINLOSS <> 0) THEN
      BEGIN
         BBLINE = 0;
         select BANK_GAINLOSS_GLACCOUNT, BANK_GAINLOSS_GLDEPT, BANK_GAINLOSS_GLCOST /* 4 NOV 2006, ACCOUNT TADINYA SALAH */
         from sysparam into ACCOUNT, DEPT, COST;

         SELECT NAME FROM GLCOA WHERE ACCOUNT = :ACCOUNT INTO COANAME;
         SELECT NAME FROM GLDEPT WHERE DEPART = :DEPT INTO DEPTNAME;
         SELECT NAME FROM GLCOST WHERE COST = :COST INTO COSTNAME;

         REMARK = '** Gain Loss **';
         DB = -XGAINLOSS;
         CR = 0;
         OPENING = BALANCE;
         BALANCE = BALANCE + CR-DB;
         
         FOREX_DB = 0;
         FOREX_CR = 0;
         SUSPEND;

       END
    END
    XDATE = XDATE + 1;
  END
END^


ALTER PROCEDURE BB_JUR_REPORT_SUMMARY(
    PBANK VARCHAR(4),
    PSDATE DATE,
    PEDATE DATE)
RETURNS (
    BANK VARCHAR(4),
    BANKNAME VARCHAR(40),
    ACCOUNT VARCHAR(20),
    DEPT VARCHAR(4),
    COST VARCHAR(4),
    OPENING DOUBLE PRECISION,
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION,
    COANAME VARCHAR(40),
    DEPTNAME VARCHAR(40),
    COSTNAME VARCHAR(40))
AS
BEGIN
  if (PBANK IS NULL) then
  BEGIN
     PBANK = 'BRI';
     PSDATE = '1.4.2000';
     PEDATE = '30.4.2004';
  END
  BANK = PBANK;
  SELECT BANKNAME FROM SYSBANK
  WHERE BANK = :BANK
  INTO BANKNAME;
  
  SELECT OPENING FROM bbacc
  WHERE BANK = :PBANK
  AND BBDATE = :PSDATE
  INTO Balance;
  if (balance is null) then balance = 0;
  FOR
    SELECT JR.ACCOUNT,
           JR.DEPT,
           JR.COST,
           SUM(JR.DB),
           SUM(JR.CR),
           COA.NAME COANAME,
           DP.NAME DEPTNAME,
           CS.NAME COSTNAME
    FROM BBJUR JR
       LEFT JOIN GLCOA COA ON (JR.ACCOUNT = COA.ACCOUNT)
       LEFT JOIN GLDEPT DP ON (JR.DEPT = DP.DEPART)
       LEFT JOIN GLCOST CS ON (JR.COST = CS.COST)
    WHERE JR.BANK = :PBANK
    AND JR.BBDATE BETWEEN :PSDATE AND :PEDATE
    GROUP BY JR.ACCOUNT, JR.DEPT, JR.COST, COA.NAME, DP.NAME, CS.NAME
    ORDER BY JR.ACCOUNT, JR.DEPT, JR.COST
    INTO
      :ACCOUNT,
      :DEPT,
      :COST,
      :DB,
      :CR,
      :COANAME,
      :DEPTNAME,
      :COSTNAME
  DO
  BEGIN
    OPENING = BALANCE;
    BALANCE = BALANCE + CR-DB;
    SUSPEND;
  END
END^


ALTER PROCEDURE BB_RPT_CASHFLOW(
    ID INTEGER,
    PYEAR INTEGER,
    PMONTH INTEGER,
    FLINE_ID INTEGER)
RETURNS (
    LINE_ID INTEGER,
    TEXT VARCHAR(80),
    FLAG_BOLD SMALLINT,
    FLAG_LINE SMALLINT,
    LINE_TYPE VARCHAR(8),
    LINE_OPERATION VARCHAR(8),
    AMOUNT DOUBLE PRECISION,
    BUDGET DOUBLE PRECISION,
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    NET DOUBLE PRECISION,
    VARIANCE DOUBLE PRECISION,
    ACCOUNT VARCHAR(20),
    DEPART VARCHAR(4),
    COST VARCHAR(4),
    ACCOUNT_NAME VARCHAR(40),
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    SOURCENUMBER INTEGER,
    REMARK VARCHAR(40),
    REF VARCHAR(20),
    BANK VARCHAR(4),
    BB_DATE DATE,
    BB_NUMBER INTEGER,
    LASTYEAR_BUDGET DOUBLE PRECISION)
AS
DECLARE VARIABLE SACCOUNT VARCHAR(20);
DECLARE VARIABLE SDEPT VARCHAR(4);
DECLARE VARIABLE SCOST VARCHAR(4);
DECLARE VARIABLE EACCOUNT VARCHAR(20);
DECLARE VARIABLE EDEPT VARCHAR(4);
DECLARE VARIABLE ECOST VARCHAR(4);
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE SAPPL VARCHAR(4);
DECLARE VARIABLE EAPPL VARCHAR(4);
DECLARE VARIABLE SSOURCE VARCHAR(4);
DECLARE VARIABLE ESOURCE VARCHAR(4);
DECLARE VARIABLE RELATION_TYPE VARCHAR(8);
DECLARE VARIABLE NUMBER INTEGER;
DECLARE VARIABLE XAMT DOUBLE PRECISION;
DECLARE VARIABLE TIN_AMOUNT DOUBLE PRECISION;
DECLARE VARIABLE TIN_BUDGET DOUBLE PRECISION;
DECLARE VARIABLE LIN_BUDGET DOUBLE PRECISION;

DECLARE VARIABLE TOUT_AMOUNT DOUBLE PRECISION;
DECLARE VARIABLE TOUT_BUDGET DOUBLE PRECISION;
DECLARE VARIABLE LOUT_BUDGET DOUBLE PRECISION;

DECLARE VARIABLE TOPEN_AMOUNT DOUBLE PRECISION;
DECLARE VARIABLE TOPEN_BUDGET DOUBLE PRECISION;
DECLARE VARIABLE LOPEN_BUDGET DOUBLE PRECISION;

DECLARE VARIABLE SLINE_ID INTEGER;
DECLARE VARIABLE ELINE_ID INTEGER;

DECLARE VARIABLE ZAMOUNT DOUBLE PRECISION;
DECLARE VARIABLE DB_CR VARCHAR(4);
DECLARE VARIABLE XDB DOUBLE PRECISION;
DECLARE VARIABLE XCR DOUBLE PRECISION;
/* 10/30/2013 */
DECLARE VARIABLE XOPENING DOUBLE PRECISION;
DECLARE VARIABLE XENDING DOUBLE PRECISION;
BEGIN
  IF ((PYEAR = 0) OR (PYEAR IS NULL)) THEN
  BEGIN
     PYEAR = 2008;
     PMONTH = 7;
     ID = 1;
     FLINE_ID = 0;
  END
  IF ((FLINE_ID IS NULL) OR (FLINE_ID = 0)) THEN
  BEGIN
     FLINE_ID = 0;
     SLINE_ID = 0;
     ELINE_ID = 9999999;
  END
  ELSE
  BEGIN
     SLINE_ID = FLINE_ID;
     ELINE_ID = FLINE_ID;
  END
  TOPEN_AMOUNT = 0;
  TIN_AMOUNT = 0;
  TOUT_AMOUNT = 0;
  
  TIN_BUDGET = 0;
  TOUT_BUDGET = 0;
  TOPEN_BUDGET = 0;
  /* -------------------------------------------------------------------- */
  /* 10/30/2013                                                           */
  /* -------------------------------------------------------------------- */
  LIN_BUDGET = 0;
  LOUT_BUDGET = 0;
  LOPEN_BUDGET = 0;
  LASTYEAR_BUDGET  = 0;
  /* -------------------------------------------------------------------- */
  /* 10/30/2013 END OF                                                    */
  /* -------------------------------------------------------------------- */
  BUDGET  = 0;
  VARIANCE = 0;
  /* ---------------------------------------------------------------- */

  SDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES (EDATE);
  /* ---------------------------------------------------------------- */
  FOR
    SELECT LINE_ID, TEXT, FLAG_BOLD, FLAG_LINE, LINE_TYPE, LINE_OPERATION
    FROM BB_CF_LINE
    WHERE ID = :ID
    AND LINE_ID BETWEEN :SLINE_ID AND :ELINE_ID
    ORDER BY LINE_NO
    INTO
      :LINE_ID,
      :TEXT,
      :FLAG_BOLD,
      :FLAG_LINE,
      :LINE_TYPE,
      :LINE_OPERATION
  DO
  BEGIN
    AMOUNT = 0;
    ZAMOUNT = 0;
    DEBIT = 0;
    CREDIT = 0;
    FOR SELECT SACCOUNT, SDEPT, SCOST, EACCOUNT, EDEPT, ECOST, APPLICATION, SOURCE,
               RELATION_TYPE, DB_CR
        FROM BB_CF_LINE_ACCOUNT
        WHERE ID = :ID
        AND LINE_ID = :LINE_ID
        INTO SACCOUNT, SDEPT, SCOST, EACCOUNT, EDEPT, ECOST, SAPPL, SSOURCE,
             RELATION_TYPE, DB_CR
    DO
    BEGIN
       IF (LINE_OPERATION = 'OPEN') THEN
       BEGIN
          FOR SELECT A.ACCOUNT, A.DEPART, A.COST, COA.NAME, A.OPENING
              FROM GLACC A
              LEFT JOIN GLCOA COA ON COA.ACCOUNT = A.ACCOUNT
              WHERE A.PYEAR = :PYEAR
              AND A.PMONTH = :PMONTH
              AND A.ACCOUNT BETWEEN :SACCOUNT AND :EACCOUNT
              AND A.DEPART BETWEEN :SDEPT AND :EDEPT
              AND A.COST BETWEEN :SCOST AND :ECOST
              INTO ACCOUNT, DEPART, COST, ACCOUNT_NAME, XAMT
          DO
          BEGIN
             IF (XAMT IS NULL) THEN XAMT = 0;
             DEBIT = 0;
             CREDIT = 0;
             AMOUNT = XAMT;
             NET = XAMT;
             ZAMOUNT = ZAMOUNT + AMOUNT;
             TOPEN_AMOUNT = TOPEN_AMOUNT + XAMT;
             NET = DEBIT - CREDIT;
             IF (FLINE_ID = LINE_ID) THEN SUSPEND;
          END
          AMOUNT = ZAMOUNT;
       END
       ELSE IF (LINE_OPERATION IN ('IN', 'OUT')) THEN
       BEGIN
          IF (RELATION_TYPE IS NULL) THEN RELATION_TYPE = '';
          IF (SAPPL IS NULL) THEN SAPPL = '';
          IF (SSOURCE IS NULL) THEN SSOURCE = '';

          IF (SAPPL = '') THEN EAPPL = 'ZZZZ';
          ELSE EAPPL = SAPPL;
          IF (SSOURCE = '') THEN ESOURCE = 'ZZZZ';
          ELSE ESOURCE = SSOURCE;

          IF (RELATION_TYPE = '') THEN
          BEGIN
             FOR SELECT J.ACCOUNT, J.DEPT, J.COST, COA.NAME,
                        J.REMARK, J.REF, J.NUMBER, BBDATE,
                        J.APPLICATION, J.SOURCE,  J.SOURCENUMBER, J.BANK,
                        J.CR-J.DB, J.DB, J.CR
                 FROM BBJUR J
                 LEFT JOIN GLCOA COA ON COA.ACCOUNT = J.ACCOUNT
                 WHERE J.BBDATE BETWEEN :SDATE AND :EDATE
                 AND J.ACCOUNT BETWEEN :SACCOUNT AND :EACCOUNT
                 AND J.DEPT BETWEEN :SDEPT AND :EDEPT
                 AND J.COST BETWEEN :SCOST AND :ECOST
                 AND J.APPLICATION BETWEEN :SAPPL AND :EAPPL
                 AND J.SOURCE BETWEEN :SSOURCE AND :ESOURCE
                 INTO ACCOUNT, DEPART, COST, ACCOUNT_NAME,
                      REMARK, REF, BB_NUMBER, BB_DATE,
                      APPLICATION, SOURCE, SOURCENUMBER, BANK, XAMT, XDB, XCR
             DO
             BEGIN
                IF (XAMT IS NULL) THEN XAMT = 0;
                IF (DB_CR = 'DB') THEN AMOUNT = XDB;
                ELSE IF (DB_CR = 'CR') THEN AMOUNT = XCR;
                ELSE IF (DB_CR = 'NET') THEN AMOUNT = XAMT;
                /* -------------------------------------------------------------------- */
                /* 10/30/2013                                                           */
                /* -------------------------------------------------------------------- */
                ELSE IF (DB_CR IN ('OPEN','END')) THEN
                BEGIN
                   SELECT SUM(A.OPENING), SUM(A.ENDING)
                   FROM GLACC A
                   WHERE A.PYEAR = :PYEAR
                   AND A.PMONTH = :PMONTH
                   AND A.ACCOUNT BETWEEN :SACCOUNT AND :EACCOUNT
                   AND A.DEPART BETWEEN :SDEPT AND :EDEPT
                   AND A.COST BETWEEN :SCOST AND :ECOST
                   INTO XOPENING, XENDING;
                   IF (DB_CR ='OPEN') THEN AMOUNT = XOPENING;
                   ELSE IF (DB_CR ='END') THEN AMOUNT = XENDING;
                   XDB = 0;
                   XCR = 0;
                   XAMT = 0;
                END
                /* -------------------------------------------------------------------- */
                /* 10/30/2013 END OF                                                    */
                /* -------------------------------------------------------------------- */
                DEBIT = XDB;
                CREDIT = XCR;
                NET = XAMT;
                ZAMOUNT = ZAMOUNT + AMOUNT;
                IF (LINE_OPERATION = 'IN') THEN
                BEGIN
                   TIN_AMOUNT = TIN_AMOUNT + XAMT;
                END
                ELSE IF (LINE_OPERATION = 'OUT') THEN
                BEGIN
                   TOUT_AMOUNT = TOUT_AMOUNT + XAMT;
                END
                NET = DEBIT - CREDIT;
                IF (FLINE_ID = LINE_ID) THEN SUSPEND;
             END
             AMOUNT = ZAMOUNT;
          END
          ELSE
          BEGIN
             IF (SAPPL = 'AP') THEN
             BEGIN
                FOR SELECT J.ACCOUNT, J.DEPT, J.COST, COA.NAME,
                        J.REMARK, J.REF, J.NUMBER, BBDATE,
                        J.APPLICATION, J.SOURCE, J.SOURCENUMBER, J.BANK,
                        J.CR-J.DB, J.DB, J.CR
                   FROM BBJUR J
                   LEFT JOIN GLCOA COA ON COA.ACCOUNT = J.ACCOUNT
                   WHERE J.BBDATE BETWEEN :SDATE AND :EDATE
                   AND J.ACCOUNT BETWEEN :SACCOUNT AND :EACCOUNT
                   AND J.DEPT BETWEEN :SDEPT AND :EDEPT
                   AND J.COST BETWEEN :SCOST AND :ECOST
                   AND J.APPLICATION BETWEEN :SAPPL AND :EAPPL
                   AND J.SOURCE BETWEEN :SSOURCE AND :ESOURCE
                   INTO ACCOUNT, DEPART, COST, ACCOUNT_NAME,
                        REMARK, REF, BB_NUMBER, BB_DATE,
                        APPLICATION, SOURCE, SOURCENUMBER, BANK, XAMT, XDB, XCR
                DO
                BEGIN
                   IF (XAMT IS NULL) THEN XAMT = 0;
                   IF (SOURCE = 'REC') THEN
                   BEGIN
                      IF (EXISTS(SELECT * FROM APCASH0 C
                                 INNER JOIN SYSSUPPLIER S ON S.SUPPLIER = C.SUPPLIER
                                 WHERE C.NUMBER = :SOURCENUMBER AND S.SUPLTYPE=:RELATION_TYPE )) THEN
                      BEGIN
                         IF (XAMT IS NULL) THEN XAMT = 0;
                         IF (DB_CR = 'DB') THEN AMOUNT = XDB;
                         ELSE IF (DB_CR = 'CR') THEN AMOUNT = XCR;
                         ELSE AMOUNT = XAMT;
                         DEBIT = XDB;
                         CREDIT = XCR;
                         NET = XAMT;
                         ZAMOUNT = ZAMOUNT + AMOUNT;
                         IF (LINE_OPERATION = 'IN') THEN
                         BEGIN
                            TIN_AMOUNT = TIN_AMOUNT + XAMT;
                         END
                         ELSE IF (LINE_OPERATION = 'OUT') THEN
                         BEGIN
                            TOUT_AMOUNT = TOUT_AMOUNT + XAMT;
                         END
                         NET = DEBIT - CREDIT;
                         IF (FLINE_ID = LINE_ID) THEN SUSPEND;
                      END
                   END
                END
                AMOUNT = ZAMOUNT;
             END
          END
       END
    END
    IF (FLINE_ID = 0) THEN
    BEGIN
       BUDGET = 0;
       LASTYEAR_BUDGET  = 0;
       IF (LINE_OPERATION IN ('IN', 'OUT', 'OPEN')) THEN
       BEGIN
          SELECT BUDGET FROM BB_CF_LINE_BUDGET
          WHERE PYEAR = :PYEAR
          AND PMONTH = :PMONTH
          AND ID = :ID
          AND LINE_ID = :LINE_ID
          INTO BUDGET;

          IF (BUDGET IS NULL) THEN BUDGET = 0;

          IF (LINE_OPERATION = 'OPEN') THEN TOPEN_BUDGET = TOPEN_BUDGET + BUDGET;
          ELSE IF (LINE_OPERATION = 'IN') THEN TIN_BUDGET = TIN_BUDGET + BUDGET;
          ELSE IF (LINE_OPERATION = 'OUT') THEN TOUT_BUDGET = TOUT_BUDGET + BUDGET;
          /* -------------------------------------------------------------------- */
          /* 10/30/2013                                                           */
          /* -------------------------------------------------------------------- */
          SELECT BUDGET FROM BB_CF_LINE_BUDGET
          WHERE PYEAR = :PYEAR-1
          AND PMONTH = :PMONTH
          AND ID = :ID
          AND LINE_ID = :LINE_ID
          INTO LASTYEAR_BUDGET;

          IF (LASTYEAR_BUDGET IS NULL) THEN LASTYEAR_BUDGET = 0;
          IF (LINE_OPERATION = 'OPEN') THEN LOPEN_BUDGET = LOPEN_BUDGET + LASTYEAR_BUDGET;
          ELSE IF (LINE_OPERATION = 'IN') THEN LIN_BUDGET = LIN_BUDGET + LASTYEAR_BUDGET;
          ELSE IF (LINE_OPERATION = 'OUT') THEN LOUT_BUDGET = LOUT_BUDGET + LASTYEAR_BUDGET;
       END


       
       IF (LINE_OPERATION = 'TOTOPEN') THEN
       BEGIN
          AMOUNT = TOPEN_AMOUNT;
          BUDGET = TOPEN_BUDGET;
          LASTYEAR_BUDGET = LOPEN_BUDGET;
       END
       ELSE IF (LINE_OPERATION = 'TOTOUT') THEN
       BEGIN
          AMOUNT = TOUT_AMOUNT;
          BUDGET = TOUT_BUDGET;
          LASTYEAR_BUDGET = LOUT_BUDGET;
       END
       ELSE IF (LINE_OPERATION = 'TOTIN') THEN
       BEGIN
          AMOUNT = TIN_AMOUNT;
          BUDGET = TIN_BUDGET;
          LASTYEAR_BUDGET = LIN_BUDGET;
       END
       ELSE IF (LINE_OPERATION = 'END') THEN
       BEGIN
          AMOUNT = TOPEN_AMOUNT + TIN_AMOUNT + TOUT_AMOUNT;
          BUDGET = TOPEN_BUDGET + TIN_BUDGET + TOUT_BUDGET;
          LASTYEAR_BUDGET = LOPEN_BUDGET + LIN_BUDGET + LOUT_BUDGET;
       END
       
       
       VARIANCE = AMOUNT - BUDGET;
       SOURCENUMBER = 0;
       ACCOUNT = '';
       DEPART = '';
       COST = '';
       ACCOUNT_NAME = '';
       APPLICATION = '';
       SOURCE = '';
       REMARK = '';
       REF = '';
       BANK = '';
       BB_NUMBER = 0;
       BB_DATE = NULL;
       NET = DEBIT - CREDIT;
       SUSPEND;
    END
  END
END^


ALTER PROCEDURE BB_RPT_RECONCILE_LIST
RETURNS (
    DATAINDEX INTEGER,
    DATAINFO VARCHAR(20),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    RECONCILEDATE DATE,
    STATUS CHAR(1),
    DOCUMENT VARCHAR(20),
    CHECK_NUMBER VARCHAR(20),
    CODE VARCHAR(6),
    NAME VARCHAR(40),
    BANK VARCHAR(4),
    BANKNAME VARCHAR(40),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION)
AS
BEGIN
  DEBIT = 0;
  DATAINDEX = 0;
  DATAINFO = 'Cash Payment';
  FOR
    SELECT V.NUMBER, V.OPENDATE, V.DUEDATE, V.RECONCILEDATE,
           V.STATUS, V.DOCUMENT, V.CHECK_NUMBER,
           V.SUPPLIER,
           S.NAME,
           V.BANK,
           B.BANKNAME,
           V.TOTAL
    FROM APCASH0 V
    LEFT JOIN SYSBANK B ON B.BANK = V.BANK
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = V.SUPPLIER
    WHERE STATUS IN ('R','L')
    AND V.TOTAL <> 0
    INTO
      :NUMBER,
      :OPENDATE,
      :DUEDATE,
      :RECONCILEDATE,
      :STATUS,
      :DOCUMENT,
      :CHECK_NUMBER,
      :CODE,
      :NAME,
      :BANK,
      :BANKNAME,
      :CREDIT
  DO
  BEGIN
    SUSPEND;
  END
  
  DATAINDEX = 1;
  DATAINFO = 'A/P Deposit';
  FOR
    SELECT D.NUMBER, D.OPENDATE, D.OPENDATE, D.RECONCILEDATE,
           D.STATUS, D.DOCUMENT, D.CHECK_NUMBER,
           D.SUPPLIER,
           S.NAME,
           D.BANK,
           B.BANKNAME,
           D.TOTAL
    FROM APDEPOS0 D
    LEFT JOIN SYSBANK B ON B.BANK = D.BANK
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = D.SUPPLIER
    WHERE STATUS IN ('R','L')
    AND D.TOTAL <> 0
    INTO
      :NUMBER,
      :OPENDATE,
      :DUEDATE,
      :RECONCILEDATE,
      :STATUS,
      :DOCUMENT,
      :CHECK_NUMBER,
      :CODE,
      :NAME,
      :BANK,
      :BANKNAME,
      :CREDIT
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE CASHFLOW_PO(
    SDATE DATE)
RETURNS (
    WK INTEGER,
    WKSDATE DATE,
    WKEDATE DATE,
    PO DOUBLE PRECISION)
AS
declare variable d integer;
begin
  
  if (sDate is null) then
     SELECT INVSYSDATE FROM SYSPARAM INTO :SDATE;
     
     
  d = -1;
  while (d <> 5) do
  begin
    execute procedure sp_dayofweek(SDate) returning_values d;
    SDate = SDate-1;
  end
  wk = 0;
  while (wk <= 7) do
  begin

    wksdate = sDate+wk*7;
    wkedate = wksdate+6;
    
    if (wk = 0 ) then wksdate = wksdate - 3650;
    
    SELECT SUM(TOTAL) FROM INVPO0
     WHERE (DELVDATE+PAYMENTDUE) between :wksdate and :wkedate 
     AND STATUS IN ('R')
    into PO;

    if (PO is null) then PO    = 0;
    suspend;
    wk = wk+1;    
  end
  
end^


ALTER PROCEDURE CLEAR_SALES
AS
begin
  UPDATE slord0 SET STATUS = 'D';
  UPDATE sldo0  SET STATUS = 'D';
  DELETE FROM SLORD1;
  DELETE FROM SLORD0;
  DELETE FROM SLDO1;
  DELETE FROM SLDO0;
  
  UPDATE invmaster SET salesorder = 0;
end^


ALTER PROCEDURE CTRL_INV_CONSUME(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    PARTNO VARCHAR(10),
    ICOST VARCHAR(4),
    TOTAL DOUBLE PRECISION,
    DIRECTUSE DOUBLE PRECISION,
    MONTHLY_TOTAL DOUBLE PRECISION,
    MONTHLY_DIRECTUSE DOUBLE PRECISION,
    DELTA_TOTAL DOUBLE PRECISION,
    DELTA_DIRECTUSE DOUBLE PRECISION)
AS
declare variable SDATE DATE;
declare variable EDATE DATE;
declare variable X INTEGER;
BEGIN
  /* ------------------------------------------------------------------------ */
  /* CALCULATE CONTROL AMOUNT BETWEEN INVSTOCK AND DAILY CONSUMPTION          */
  /* ------------------------------------------------------------------------ */
  if (PYEAR IS NULL) then
  BEGIN
     SELECT INVSYSDATE -1 FROM SYSPARAM INTO :SDATE;
     PYEAR = EXTRACT(YEAR FROM SDATE);
     PMONTH = EXTRACT(MONTH FROM SDATE);
     PYEAR = 2004;
     PMONTH = 9;
  END
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(PMONTH, PYEAR) RETURNING_VALUES(SDATE); /* 3/18/2011 */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE) returning_values :EDATE;

  FOR
    SELECT PARTNO, ICOST, AMTTOTAL, DIRECTUSEAMT FROM INVCONSUME
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH

    INTO
      :PARTNO,
      :ICOST,
      :MONTHLY_TOTAL,
      :MONTHLY_DIRECTUSE
  DO
  BEGIN
    SELECT SUM(AMTTOTAL), SUM(DIRECTUSEAMT) FROM INVCONSUME_DAILY
    WHERE ICOST = :ICOST
    AND PARTNO = :PARTNO
    AND OPENDATE BETWEEN :SDATE AND :EDATE
    INTO TOTAL, DIRECTUSE;
    DELTA_TOTAL = TOTAL - MONTHLY_TOTAL;
    DELTA_DIRECTUSE = DIRECTUSE - MONTHLY_DIRECTUSE;
    SUSPEND;
/*    if ((DELTA_TOTAL > 0.001) or (DELTA_TOTAL < -0.001)) then
    BEGIN
       UPDATE INVCONSUME SET ITEMTYPE = '?'
       WHERE PYEAR = :PYEAR
       AND PMONTH = :PMONTH
       AND ICOST = :ICOST
       AND PARTNO = :PARTNO;
       SUSPEND;
    END
*/
  END
END^


ALTER PROCEDURE CTRL_INV_STOCK_MUTATION(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    ITYPE CHAR(1),
    NAME VARCHAR(40),
    OPENING DOUBLE PRECISION,
    RECEIVING DOUBLE PRECISION,
    RETURN DOUBLE PRECISION,
    ONHAND DOUBLE PRECISION,
    TRFIN DOUBLE PRECISION,
    TRFOUT DOUBLE PRECISION,
    ISSUE DOUBLE PRECISION,
    SPOILAGE DOUBLE PRECISION,
    ADJUST DOUBLE PRECISION,
    DIRECTUSE DOUBLE PRECISION,
    CONSUME DOUBLE PRECISION,
    CONSUME_MONTHLY DOUBLE PRECISION,
    CONSUME_DAILY DOUBLE PRECISION,
    DELTA DOUBLE PRECISION,
    DELTA_MONTHLY DOUBLE PRECISION,
    DELTA_TOTAL DOUBLE PRECISION)
AS
declare variable SDATE DATE;
declare variable EDATE DATE;
BEGIN
  /* ------------------------------------------------------------------------ */
  /* CALCULATE CONTROL AMOUNT BETWEEN INVSTOCK AND DAILY CONSUMPTION          */
  /* ------------------------------------------------------------------------ */
  if (PYEAR IS NULL) then
  BEGIN
     SELECT INVSYSDATE -1 FROM SYSPARAM INTO :SDATE;
     PYEAR = EXTRACT(YEAR FROM SDATE);
     PMONTH = EXTRACT(MONTH FROM SDATE);
  END
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(PMONTH, PYEAR) RETURNING_VALUES(SDATE); /* 3/18/2011 */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE) returning_values :EDATE;
  DELTA_TOTAL = 0;
  /* ------------------------------------------------------------------------ */
  FOR SELECT ITYPE, NAME FROM invtype
      ORDER BY ORDERLISTNO
      INTO ITYPE, NAME
  DO BEGIN
     SELECT SUM(S.AMTOPEN),
            SUM(S.AMTIN),
            SUM(S.AMTRETURN),
            SUM(S.AMTONHAND),
            SUM(S.AMTTRFIN),
            SUM(S.AMTTRFOUT),
            SUM(S.AMTISSUE),
            SUM(S.AMTSPOILAGE),
            SUM(S.AMTADJ),
            SUM(S.AMTCONSUME)
            FROM INVSTOCK S
      WHERE S.PYEAR = :PYEAR AND S.PMONTH = :PMONTH
      AND S.ITYPE = :ITYPE
        INTO  :OPENING,
              :RECEIVING,
              :RETURN,
              :ONHAND,
              :TRFIN,
              :TRFOUT,
              :ISSUE,
              :SPOILAGE,
              :ADJUST,
              :CONSUME;
    if (OPENING IS NULL) then
    BEGIN
       OPENING = 0;
       RECEIVING = 0;
       RETURN = 0;
       ONHAND = 0;
       TRFIN = 0;
       TRFOUT = 0;
       ISSUE = 0;
       SPOILAGE = 0;
       ADJUST = 0;
       CONSUME = 0;
    END

    /* DIRECT USE */
    SELECT SUM(DIRECTUSEAMT), SUM(AMTTOTAL) FROM INVCONSUME_DAILY
    WHERE ITEMTYPE = :ITYPE
    AND OPENDATE BETWEEN :SDATE AND :EDATE
    INTO DIRECTUSE, CONSUME_DAILY;

    /* ---------------------------------------------------------------- */
    /* 26 october 2006                                                  */
    /* ---------------------------------------------------------------- */
    IF (DIRECTUSE IS NULL) THEN
    BEGIN
       DIRECTUSE = 0;
       CONSUME_DAILY = 0;
    END




    /* ---------------------------------------------------------------- */

    DELTA = CONSUME + DIRECTUSE - CONSUME_DAILY;

    SELECT SUM(AMTTOTAL) FROM INVCONSUME
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND ITEMTYPE = :ITYPE
    INTO CONSUME_MONTHLY;
    /* ---------------------------------------------------------------- */

    /* 26 OCT 2006                                                      */
    /* ---------------------------------------------------------------- */
    IF (CONSUME_MONTHLY IS NULL) THEN CONSUME_MONTHLY = 0;

    /* ---------------------------------------------------------------- */

    DELTA_MONTHLY = CONSUME_MONTHLY - CONSUME_DAILY;
    DELTA_TOTAL = DELTA_TOTAL + DELTA_MONTHLY;
    SUSPEND;
  END
END^


ALTER PROCEDURE CTRL_INV_STOCK_MUTATION_DETAIL(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    PARTNO VARCHAR(10),
    NAME VARCHAR(40),
    OPENING DOUBLE PRECISION,
    RECEIVING DOUBLE PRECISION,
    RETURN DOUBLE PRECISION,
    ONHAND DOUBLE PRECISION,
    TRFIN DOUBLE PRECISION,
    TRFOUT DOUBLE PRECISION,
    ISSUE DOUBLE PRECISION,
    SPOILAGE DOUBLE PRECISION,
    ADJUST DOUBLE PRECISION,
    DIRECTUSE DOUBLE PRECISION,
    CONSUME DOUBLE PRECISION,
    CONSUME_MONTHLY DOUBLE PRECISION,
    CONSUME_DAILY DOUBLE PRECISION,
    DELTA DOUBLE PRECISION,
    DELTA_MONTHLY DOUBLE PRECISION,
    DELTA_TOTAL DOUBLE PRECISION)
AS
declare variable SDATE DATE;
declare variable EDATE DATE;
BEGIN
  /* ------------------------------------------------------------------------ */
  /* CALCULATE CONTROL AMOUNT BETWEEN INVSTOCK AND DAILY CONSUMPTION          */
  /* ------------------------------------------------------------------------ */
  if (PYEAR IS NULL) then
  BEGIN
     SELECT INVSYSDATE -1 FROM SYSPARAM INTO :SDATE;
     PYEAR = EXTRACT(YEAR FROM SDATE);
     PMONTH = EXTRACT(MONTH FROM SDATE);
  END
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(PMONTH, PYEAR) RETURNING_VALUES(SDATE); /* 3/18/2011 */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE) returning_values :EDATE;
  DELTA_TOTAL = 0;
  /* ------------------------------------------------------------------------ */
  FOR
    SELECT S.PARTNO,
    SUM(S.AMTOPEN),
    SUM(S.AMTIN),
    SUM(S.AMTRETURN),
    SUM(S.AMTONHAND),
    SUM(S.AMTTRFIN),
    SUM(S.AMTTRFOUT),
    SUM(S.AMTISSUE),
    SUM(S.AMTSPOILAGE),
    SUM(S.AMTADJ),
    SUM(S.AMTCONSUME)
    FROM INVSTOCK S
    WHERE S.PYEAR = :PYEAR AND S.PMONTH = :PMONTH
    GROUP BY S.PARTNO
    ORDER BY S.PARTNO
    INTO
      :PARTNO,
      :OPENING,
      :RECEIVING,
      :RETURN,
      :ONHAND,
      :TRFIN,
      :TRFOUT,
      :ISSUE,
      :SPOILAGE,
      :ADJUST,
      :CONSUME
  DO
  BEGIN
    SELECT NAME FROM INVMASTER WHERE PARTNO = :NAME INTO :NAME;
    /* DIRECT USE */
    SELECT SUM(DIRECTUSEAMT), SUM(AMTTOTAL) FROM INVCONSUME_DAILY
    WHERE PARTNO = :PARTNO
    AND OPENDATE BETWEEN :SDATE AND :EDATE
    INTO DIRECTUSE, CONSUME_DAILY;
    DELTA = CONSUME + DIRECTUSE - CONSUME_DAILY;
    
    SELECT SUM(AMTTOTAL) FROM INVCONSUME
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND PARTNO = :PARTNO
    INTO CONSUME_MONTHLY;
    if (CONSUME_MONTHLY IS NULL) then CONSUME_MONTHLY = 0;
    DELTA_MONTHLY = CONSUME_MONTHLY - CONSUME_DAILY;
    DELTA_TOTAL = DELTA_TOTAL + DELTA_MONTHLY;
    if ((DELTA_MONTHLY < -0.001) or (DELTA_MONTHLY > 0.001)) then
       SUSPEND;
  END
END^


ALTER PROCEDURE CTRL_INV_VERIFY_RECV_DETAIL(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    PARTNO VARCHAR(10),
    DIRECTUSE INTEGER,
    STORE VARCHAR(4),
    ICOST VARCHAR(4),
    QTY DOUBLE PRECISION,
    AMOUNT DOUBLE PRECISION)
AS
declare variable NUMBER INTEGER;
declare variable STORE_HEADER VARCHAR(4);
declare variable SDATE DATE;
declare variable EDATE DATE;
declare variable DU INTEGER;
BEGIN
  /* ------------------------------------------------------------------------ */
  /* CALCULATE CONTROL AMOUNT BETWEEN INVSTOCK AND DAILY CONSUMPTION          */
  /* ------------------------------------------------------------------------ */
  if (PYEAR IS NULL) then
  BEGIN
     SELECT INVSYSDATE -1 FROM SYSPARAM INTO :SDATE;
     PYEAR = EXTRACT(YEAR FROM SDATE);
     PMONTH = EXTRACT(MONTH FROM SDATE);
  END
  
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(PMONTH, PYEAR) RETURNING_VALUES(SDATE); /* 3/18/2011 */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE) returning_values :EDATE;

  
  FOR
    SELECT NUMBER, STORE, ICOST FROM invrecv0
          WHERE OPENDATE BETWEEN :SDATE AND :EDATE
          AND STATUS IN ('R','C')

    INTO
      :NUMBER,
      :STORE_HEADER,
      :ICOST
  DO
  BEGIN
     FOR SELECT D.PARTNO, D.QTYF*D.KONVERSI+D.QTY, D.CALC_COST_FOREX,
                D.DIRECTUSE, D.STORE
           FROM invrecv1 D
           LEFT JOIN INVMASTER M ON M.PARTNO = D.PARTNO
         WHERE NUMBER = :NUMBER
         INTO :PARTNO, QTY, AMOUNT, DU, STORE
     DO
     BEGIN
        if ((DU = 0) AND ((STORE IS NULL) or (STORE = ''))) then STORE = STORE_HEADER;
        if ((DU = 1) or (STORE = '')) then
        BEGIN
           DIRECTUSE = 1;
           STORE = '';
        END
        ELSE
           DIRECTUSE = 0;
        SUSPEND;
     END
  END
END^


ALTER PROCEDURE CTRL_VERIFY_AP_VS_GL(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    AP_DEBIT DOUBLE PRECISION,
    AP_CREDIT DOUBLE PRECISION,
    BUFF_DEBIT DOUBLE PRECISION,
    BUFF_CREDIT DOUBLE PRECISION,
    GL_DEBIT DOUBLE PRECISION,
    GL_CREDIT DOUBLE PRECISION,
    DELTA_DEBIT DOUBLE PRECISION,
    DELTA_CREDIT DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
begin
  /*
    SELECT SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST,
           SUM(AP_DEBIT) DB, SUM(AP_CREDIT) CR,
           SUM(GL_DEBIT+BUFF_DEBIT) GL_DB, SUM(GL_CREDIT+BUFF_CREDIT) GL_CR,
           SUM(DELTA_DEBIT) DELTA_DEBIT, SUM(DELTA_CREDIT) DELTA_CREDIT
    FROM CTRL_VERIFY_AP_VS_GL(2005, 5)
    GROUP BY SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST
  */
  IF (PYEAR IS NULL) THEN
  BEGIN
      SELECT EXTRACT(YEAR FROM APSYSDATE), EXTRACT(MONTH FROM APSYSDATE)
      FROM SYSPARAM INTO PYEAR, PMONTH;
  END
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(PMONTH, PYEAR) RETURNING_VALUES(SDATE); /* 3/18/2011 */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE) returning_values :EDATE;

  GL_DEBIT = 0;
  GL_CREDIT = 0;
  
  BUFF_DEBIT = 0;
  BUFF_CREDIT = 0;
  
  FOR SELECT APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME,
            SUM(DEBIT), SUM(CREDIT)
      FROM AP_GLBUFFER_AALL_RECREATE(:SDATE, :EDATE, 0)
      GROUP BY APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME
      INTO APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME,
           AP_DEBIT, AP_CREDIT
  DO
  BEGIN
     DELTA_DEBIT  = AP_DEBIT  - (GL_DEBIT+BUFF_DEBIT);
     DELTA_CREDIT = AP_CREDIT - (GL_CREDIT+BUFF_CREDIT);
     suspend;
  END
  
  AP_DEBIT = 0;
  AP_CREDIT = 0;
  FOR SELECT JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPART, JR.COST, COA.NAME,
            SUM(JR.DB), SUM(JR.CR)
      FROM GLJUR JR
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = JR.ACCOUNT
      WHERE JR.PYEAR = :PYEAR
      AND JR.PMONTH = :PMONTH
      AND JR.APPLICATION = 'AP'
      GROUP BY JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPART, JR.COST, COA.NAME
      INTO APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME,
           GL_DEBIT, GL_CREDIT
  DO
  BEGIN
     DELTA_DEBIT  = AP_DEBIT  - (GL_DEBIT+BUFF_DEBIT);
     DELTA_CREDIT = AP_CREDIT - (GL_CREDIT+BUFF_CREDIT); 
     suspend;
  END  
  GL_DEBIT = 0;
  GL_CREDIT = 0;
  
  FOR SELECT JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPT, JR.COST, COA.NAME,
            SUM(JR.DB), SUM(JR.CR)
      FROM GLBUFFER JR
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = JR.ACCOUNT
      WHERE JR.APPLICATION = 'AP'
      AND JR.TRANSDATE BETWEEN :SDATE AND :EDATE
      AND JR.STATUS = 'O' 
      GROUP BY JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPT, JR.COST, COA.NAME
/*       PLAN (GLBUFFER INDEX (GLBUFFER_IDX_APPL_DATE))       For FB.2.x 31-Aug-2011 */
      INTO APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME,
           BUFF_DEBIT, BUFF_CREDIT
  DO
  BEGIN
     DELTA_DEBIT  = AP_DEBIT  - (GL_DEBIT+BUFF_DEBIT);
     DELTA_CREDIT = AP_CREDIT - (GL_CREDIT+BUFF_CREDIT);
     suspend;
  END  
end^


ALTER PROCEDURE CTRL_VERIFY_AR_VS_GL(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    AR_DEBIT DOUBLE PRECISION,
    AR_CREDIT DOUBLE PRECISION,
    BUFF_DEBIT DOUBLE PRECISION,
    BUFF_CREDIT DOUBLE PRECISION,
    GL_DEBIT DOUBLE PRECISION,
    GL_CREDIT DOUBLE PRECISION,
    DELTA_DEBIT DOUBLE PRECISION,
    DELTA_CREDIT DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
begin
  /*
    SELECT SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST,
           SUM(AR_DEBIT) DB, SUM(AR_CREDIT) CR,
           SUM(GL_DEBIT+BUFF_DEBIT) GL_DB, SUM(GL_CREDIT+BUFF_CREDIT) GL_CR,
           SUM(DELTA_DEBIT) DELTA_DEBIT, SUM(DELTA_CREDIT) DELTA_CREDIT
    FROM CTRL_VERIFY_AR_VS_GL(2005, 5)
    GROUP BY SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST
  */
  IF (PYEAR IS NULL) THEN
  BEGIN
      PYEAR = 2005;
      PMONTH = 8;
  END
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(PMONTH, PYEAR) RETURNING_VALUES(SDATE); /* 3/18/2011 */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE) returning_values :EDATE;

  AR_DEBIT = 0;
  AR_CREDIT = 0;
  
  GL_DEBIT = 0;
  GL_CREDIT = 0;
  
  BUFF_DEBIT = 0;
  BUFF_CREDIT = 0;
  
  FOR SELECT JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPART, JR.COST, COA.NAME,
            SUM(JR.DB), SUM(JR.CR)
      FROM GLJUR JR
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = JR.ACCOUNT
      WHERE JR.PYEAR = :PYEAR
      AND JR.PMONTH = :PMONTH
      AND JR.APPLICATION = 'AR' AND JR.SOURCENUMBER <> 0
      GROUP BY JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPART, JR.COST, COA.NAME
      INTO APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME,
           GL_DEBIT, GL_CREDIT
  DO
  BEGIN
     DELTA_DEBIT  = AR_DEBIT  - (GL_DEBIT+BUFF_DEBIT);
     DELTA_CREDIT = AR_CREDIT - (GL_CREDIT+BUFF_CREDIT); 
     suspend;
  END  
  GL_DEBIT = 0;
  GL_CREDIT = 0;
  
  FOR SELECT JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPT, JR.COST, COA.NAME,
            SUM(JR.DB), SUM(JR.CR)
      FROM GLBUFFER JR
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = JR.ACCOUNT
      WHERE JR.APPLICATION = 'AR'
      AND JR.TRANSDATE BETWEEN :SDATE AND :EDATE
      AND JR.STATUS = 'O' 
      GROUP BY JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPT, JR.COST, COA.NAME
/*       PLAN (GLBUFFER INDEX (GLBUFFER_IDX_APPL_DATE))       For FB.2.x 31-Aug-2011 */
      INTO APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME,
           BUFF_DEBIT, BUFF_CREDIT
  DO
  BEGIN
     DELTA_DEBIT  = AR_DEBIT  - (GL_DEBIT+BUFF_DEBIT);
     DELTA_CREDIT = AR_CREDIT - (GL_CREDIT+BUFF_CREDIT);
     suspend;
  END  
end^


ALTER PROCEDURE CTRL_VERIFY_CLEARANCE(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    NAME VARCHAR(40),
    FLAG_CLEARANCE INTEGER,
    CASH DOUBLE PRECISION,
    GL DOUBLE PRECISION,
    DELTA DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
BEGIN
  IF ((PYEAR IS NULL) OR (PYEAR = 0)) THEN
  BEGIN
     PYEAR = 2006;
     PMONTH = 2;
  END
  
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(PMONTH, PYEAR) RETURNING_VALUES(SDATE); /* 3/18/2011 */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE) returning_values :EDATE;


  APPLICATION = 'AP';
  /* ---------------------------------------------------------------- */
  /* cash payment                                                     */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CASH';
  NAME = 'Cash Payment';
  
  SELECT SUM(TOTAL) FROM APCASH0
  WHERE DUEDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('L','C','R')
  INTO :CASH;
  
  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;
  
  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = 1;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* cash reconciliation                                              */
  /* ---------------------------------------------------------------- */
  SOURCE = 'REC';
  NAME = 'Cash Payment Reconciliation';
  
  SELECT SUM(TOTAL) FROM APCASH0
  WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'C'
  INTO :CASH;

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = -1;
  SUSPEND;
  
  /* ---------------------------------------------------------------- */
  /* deposit payment                                                  */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DEP0';
  NAME = 'Purchase Deposit';

  SELECT SUM(TOTAL) FROM APDEPOS0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('L','C','R')
  INTO :CASH;

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = 1;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* deposit reconciliation                                           */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DREC';
  NAME = 'Purchase Deposit Reconciliation';

  SELECT SUM(TOTAL) FROM APDEPOS0
  WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'C'
  INTO :CASH;

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = -1;
  SUSPEND;
  /* ---------------------------------------------------------------- */
  /* AR                                                               */
  /* ---------------------------------------------------------------- */
  IF (EXISTS(SELECT * FROM SYSPARAM WHERE INSTALLAR = 0)) THEN
  BEGIN
     EXIT;
  END
  APPLICATION = 'AR';
  /* ---------------------------------------------------------------- */
  /* cash receipt                                                     */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CASH';
  NAME = 'Cash Receipt';
  CASH = 0;

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (GL IS NULL) THEN GL = 0;
  FLAG_CLEARANCE = 1;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* cash receipt reconciliation                                      */
  /* ---------------------------------------------------------------- */
  SOURCE = 'REC';
  NAME = 'Cash Receipt Reconciliation';

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = -1;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* a/r deposit payment                                              */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DEP0';
  NAME = 'Reservation Deposit';

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = 1;
  SUSPEND;

  /* ---------------------------------------------------------------- */
  /* a/r deposit reconciliation                                       */
  /* ---------------------------------------------------------------- */
  SOURCE = 'DREC';
  NAME = 'Reservation Deposit Reconciliation';

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = -1;
  SUSPEND;
  /* ---------------------------------------------------------------- */
  /* card batch receipt                                               */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CCPY';
  NAME = 'Credit Card Settlement';

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = 1;
  SUSPEND;
  /* ---------------------------------------------------------------- */
  /* card batch receipt                                               */
  /* ---------------------------------------------------------------- */
  SOURCE = 'CREC';
  NAME = 'Credit Card Reconciliation';

  SELECT SUM(CR) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = :APPLICATION
  AND SOURCE = :SOURCE
  INTO GL;

  IF (CASH IS NULL) THEN CASH = 0;
  IF (GL IS NULL) THEN GL = 0;
  DELTA = GL-CASH;
  FLAG_CLEARANCE = -1;
  SUSPEND;
END^


ALTER PROCEDURE CTRL_VERIFY_GL_VS_INV(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    SOURCE VARCHAR(4),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    TOTAL_INV_DB DOUBLE PRECISION,
    TOTAL_INV_CR DOUBLE PRECISION,
    TOTAL_GL_DB DOUBLE PRECISION,
    TOTAL_GL_CR DOUBLE PRECISION,
    BUFFER_GL_DB DOUBLE PRECISION,
    BUFFER_GL_CR DOUBLE PRECISION,
    DELTA_INV DOUBLE PRECISION,
    DELTA_GL DOUBLE PRECISION,
    BALANCE_INV DOUBLE PRECISION,
    BALANCE_GL DOUBLE PRECISION,
    BALANCE_BUFFER DOUBLE PRECISION)
AS
BEGIN
  BALANCE_INV =0;
  BALANCE_GL =0;
  BALANCE_BUFFER =0;
  /* ------------------------------------------------------------------------ */
  /* CALCULATE CONTROL AMOUNT BETWEEN INVSTOCK AND DAILY CONSUMPTION          */
  /* ------------------------------------------------------------------------ */
  FOR
    SELECT SOURCE, GL_ACCOUNT,
           SUM(TOTAL_INV_DB),
           SUM(TOTAL_INV_CR),
           SUM(TOTAL_GL_DB),
           SUM(TOTAL_GL_CR),
           SUM(BUFFER_GL_DB),
           SUM(BUFFER_GL_CR)
    FROM ctrl_verify_gl_vs_inv_detail(:PYEAR, :PMONTH)
    WHERE SOURCE = 'RECV'
    GROUP BY SOURCE, GL_ACCOUNT
    INTO
      :SOURCE,
      :GL_ACCOUNT,
      :TOTAL_INV_DB,
      :TOTAL_INV_CR,
      :TOTAL_GL_DB,
      :TOTAL_GL_CR,
      :BUFFER_GL_DB,
      :BUFFER_GL_CR
  DO
  BEGIN
    BALANCE_INV    = BALANCE_INV + TOTAL_INV_DB - TOTAL_INV_CR;
    BALANCE_GL     = BALANCE_GL + TOTAL_GL_DB - TOTAL_GL_CR;
    BALANCE_BUFFER = BALANCE_BUFFER + BUFFER_GL_DB - BUFFER_GL_CR;
    DELTA_INV = (TOTAL_INV_DB - TOTAL_INV_CR) - (BUFFER_GL_DB - BUFFER_GL_CR);
    DELTA_GL  = (TOTAL_GL_DB - TOTAL_GL_CR) - (BUFFER_GL_DB - BUFFER_GL_CR);

    SUSPEND;
  END
END^


ALTER PROCEDURE CTRL_VERIFY_GL_VS_INV_DETAIL(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    SOURCE VARCHAR(4),
    SOURCE_TYPE VARCHAR(4),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    TOTAL_INV_DB DOUBLE PRECISION,
    TOTAL_INV_CR DOUBLE PRECISION,
    TOTAL_GL_DB DOUBLE PRECISION,
    TOTAL_GL_CR DOUBLE PRECISION,
    BUFFER_GL_DB DOUBLE PRECISION,
    BUFFER_GL_CR DOUBLE PRECISION)
AS
declare variable SDATE DATE;
declare variable EDATE DATE;
declare variable ISSUE DOUBLE PRECISION;
declare variable ADJ DOUBLE PRECISION;
declare variable CR2C_DB DOUBLE PRECISION;
declare variable CR2C_CR DOUBLE PRECISION;
declare variable SPL DOUBLE PRECISION;
declare variable DU DOUBLE PRECISION;

declare variable IGL_ACCOUNT VARCHAR(20);
declare variable IGL_DEPT VARCHAR(4);
declare variable IGL_COST VARCHAR(4);

declare variable TOTAL_RECV DOUBLE PRECISION;
    
declare variable X INTEGER;
BEGIN
  /* ------------------------------------------------------------------------ */
  /* CALCULATE CONTROL AMOUNT BETWEEN INVSTOCK AND DAILY CONSUMPTION          */
  /* ------------------------------------------------------------------------ */
  if (PYEAR IS NULL) then
  BEGIN
     SELECT INVSYSDATE -1 FROM SYSPARAM INTO :SDATE;
     PYEAR = EXTRACT(YEAR FROM SDATE);
     PMONTH = EXTRACT(MONTH FROM SDATE);
     PYEAR = 2004;
     PMONTH = 10;
     SOURCE = 'ISUE';
  END
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(PMONTH, PYEAR) RETURNING_VALUES(SDATE); /* 3/18/2011 */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE) returning_values :EDATE;

  TOTAL_GL_DB  = 0;
  TOTAL_GL_CR  = 0;
  BUFFER_GL_DB = 0;
  BUFFER_GL_CR = 0;
  SOURCE_TYPE  = '';
  TOTAL_RECV     = 0;
  FOR
    SELECT G.ACCINV, G.DEPART_INV, G.GL_COST_INV, CD.GL_ACCOUNT, CD.GL_DEPT, CD.GL_COST,
           SUM(CD.AMT),
           SUM(CD.ADJAMT),
           SUM(CD.SPLAMT),
           SUM(CD.CREDIT_AMT_DB),
           SUM(CD.CREDIT_AMT_CR),
           SUM(CD.DIRECTUSEAMT)
    FROM INVCONSUME_DAILY CD
    LEFT JOIN INVGROUP G ON G.GRP = CD.ITEMGROUP
    WHERE OPENDATE BETWEEN :SDATE AND :EDATE
    GROUP BY G.ACCINV, G.DEPART_INV, G.GL_COST_INV, CD.GL_ACCOUNT, CD.GL_DEPT, CD.GL_COST
    INTO
      :IGL_ACCOUNT,
      :IGL_DEPT,
      :IGL_COST,
      :GL_ACCOUNT,
      :GL_DEPT,
      :GL_COST,
      :ISSUE,
      :ADJ,
      :SPL,
      :CR2C_DB,
      :CR2C_CR,
      :DU
  DO
  BEGIN
    TOTAL_INV_DB = 0;
    TOTAL_INV_CR = 0;
    if (ISSUE <> 0) then
    BEGIN
       SOURCE = 'ISUE';
       TOTAL_INV_DB = ISSUE;
       SUSPEND;
    END
    if (ADJ <> 0) then
    BEGIN
       SOURCE = 'ADJ';
       TOTAL_INV_DB = ADJ;
       SUSPEND;
    END
    if (SPL <> 0) then
    BEGIN
       SOURCE = 'SPL';
       TOTAL_INV_DB = SPL;
       SUSPEND;
    END
    if (CR2C_DB <> 0) then
    BEGIN
       SOURCE = 'CR2C';
       TOTAL_INV_DB = CR2C_DB;       
       TOTAL_INV_CR = 0;
       SUSPEND;
       TOTAL_INV_DB = 0;
    END
    if (CR2C_CR <> 0) then
    BEGIN
       SOURCE = 'CR2C';
       TOTAL_INV_DB = 0;
       TOTAL_INV_CR = CR2C_CR;
       SUSPEND;
       TOTAL_INV_CR = 0;       
    END
    TOTAL_INV_DB = 0;
    TOTAL_INV_CR = 0;
    if (DU <> 0) then
    BEGIN
       TOTAL_RECV = TOTAL_RECV + DU;
       SOURCE = 'RECV';
       TOTAL_INV_DB = DU;
       SOURCE_TYPE = 'DU';
       SUSPEND;
       SOURCE_TYPE = '';
    END        

    /* ---------------------------------------------------------------------- */
    /* CREDIT INVENTORY                                                       */
    /* ---------------------------------------------------------------------- */
    GL_ACCOUNT = IGL_ACCOUNT;
    GL_DEPT = IGL_DEPT;
    GL_COST = IGL_COST;
    TOTAL_INV_DB = 0;
    if (ISSUE <> 0) then
    BEGIN
       SOURCE = 'ISUE';
       TOTAL_INV_CR = ISSUE;
       SUSPEND;
    END
    if (ADJ <> 0) then
    BEGIN
       SOURCE = 'ADJ';
       TOTAL_INV_CR = ADJ;
       SUSPEND;
    END
    if (SPL <> 0) then
    BEGIN
       SOURCE = 'SPL';
       TOTAL_INV_CR = SPL;
       SUSPEND;
    END
  END
  SOURCE = 'RECV';
  SOURCE_TYPE = 'DU';
  GL_ACCOUNT = 'AP';
  GL_DEPT = 'AP';
  GL_COST = 'AP';
  TOTAL_INV_DB = 0;
  TOTAL_INV_CR = TOTAL_RECV;
  SUSPEND;  
  TOTAL_RECV = 0;
  
  SOURCE = 'RECV';
  SOURCE_TYPE = 'RECV';
  TOTAL_INV_CR = 0;
  FOR SELECT G.ACCINV, G.DEPART_INV, G.GL_COST_INV, SUM(S.AMTIN) FROM INVSTOCK S
      LEFT JOIN INVGROUP G ON G.GRP = S.GRP
    WHERE S.PYEAR = :PYEAR
    AND S.PMONTH = :PMONTH
    GROUP BY  G.ACCINV, G.DEPART_INV, G.GL_COST_INV
    INTO :GL_ACCOUNT,
         :GL_DEPT,
         :GL_COST,
         :TOTAL_INV_DB
  DO BEGIN
     if (TOTAL_INV_DB <> 0) then
     BEGIN
        SUSPEND;
        TOTAL_RECV = TOTAL_RECV + TOTAL_INV_DB;
     END
  END
  GL_ACCOUNT = 'AP';
  GL_DEPT = 'AP';
  GL_COST = 'AP';
  TOTAL_INV_DB = 0;
  TOTAL_INV_CR = TOTAL_RECV;
  SUSPEND;
  /* ------------------------------------------------------------------------ */
  /* JOURNAL ENTRY                                                            */
  /* ------------------------------------------------------------------------ */
  TOTAL_INV_DB = 0;
  TOTAL_INV_CR = 0;
  FOR SELECT SOURCE, ACCOUNT, DEPART, COST, SUM(DB), SUM(CR) FROM gljur
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND APPLICATION = 'INV'
    GROUP BY SOURCE, ACCOUNT, DEPART, COST
    INTO :SOURCE,
         :GL_ACCOUNT,
         :GL_DEPT,
         :GL_COST,
         :TOTAL_GL_DB,
         :TOTAL_GL_CR
  DO BEGIN
     SUSPEND;
  END
  /* ------------------------------------------------------------------------ */
  /* GLBUFFER                                                                 */
  /* ------------------------------------------------------------------------ */  
  TOTAL_GL_DB  = 0;
  TOTAL_GL_CR  = 0;
  TOTAL_INV_DB = 0;
  TOTAL_INV_CR = 0;
  FOR SELECT SOURCE, ACCOUNT, DEPT, COST, SUM(DB), SUM(CR) FROM GLBUFFER
    WHERE APPLICATION = 'INV'
    AND TRANSDATE BETWEEN :SDATE AND :EDATE
    GROUP BY ACCOUNT, DEPT, COST, SOURCE    
    PLAN (GLBUFFER INDEX (GLBUFFER_IDX_APPL_DATE))
    INTO :SOURCE,
         :GL_ACCOUNT,
         :GL_DEPT,
         :GL_COST,
         :BUFFER_GL_DB,
         :BUFFER_GL_CR
  DO
  BEGIN
     SUSPEND;
  END
END^


ALTER PROCEDURE CTRL_VERIFY_INCOME_VS_GL(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    FO_DEBIT DOUBLE PRECISION,
    FO_CREDIT DOUBLE PRECISION,
    BUFF_DEBIT DOUBLE PRECISION,
    BUFF_CREDIT DOUBLE PRECISION,
    GL_DEBIT DOUBLE PRECISION,
    GL_CREDIT DOUBLE PRECISION,
    DELTA_DEBIT DOUBLE PRECISION,
    DELTA_CREDIT DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
begin
  /*
    SELECT SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST,
           SUM(FO_DEBIT) DB, SUM(FO_CREDIT) CR,
           SUM(GL_DEBIT+BUFF_DEBIT) GL_DB, SUM(GL_CREDIT+BUFF_CREDIT) GL_CR,
           SUM(DELTA_DEBIT) DELTA_DEBIT, SUM(DELTA_CREDIT) DELTA_CREDIT
    FROM CTRL_VERIFY_FO_VS_GL(2005, 5)
    GROUP BY SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST
  */
  IF (PYEAR IS NULL) THEN
  BEGIN
      PYEAR = 2005;
      PMONTH = 4;
  END
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(PMONTH, PYEAR) RETURNING_VALUES(SDATE); /* 3/18/2011 */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE) returning_values :EDATE;

  FO_DEBIT = 0;
  FO_CREDIT = 0;
  
  GL_DEBIT = 0;
  GL_CREDIT = 0;
  
  BUFF_DEBIT = 0;
  BUFF_CREDIT = 0;
  
  FOR SELECT JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPART, JR.COST, COA.NAME,
            SUM(JR.DB), SUM(JR.CR)
      FROM GLJUR JR
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = JR.ACCOUNT
      WHERE JR.PYEAR = :PYEAR
      AND JR.PMONTH = :PMONTH
      AND JR.APPLICATION = 'FO'
      AND JR.SOURCE = 'IC'
      GROUP BY JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPART, JR.COST, COA.NAME
      INTO APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME,
           GL_DEBIT, GL_CREDIT
  DO
  BEGIN
     DELTA_DEBIT  = FO_DEBIT  - (GL_DEBIT+BUFF_DEBIT);
     DELTA_CREDIT = FO_CREDIT - (GL_CREDIT+BUFF_CREDIT); 
     suspend;
  END  
  GL_DEBIT = 0;
  GL_CREDIT = 0;
  
  FOR SELECT JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPT, JR.COST, COA.NAME,
            SUM(JR.DB), SUM(JR.CR)
      FROM GLBUFFER JR
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = JR.ACCOUNT
      WHERE JR.APPLICATION = 'FO'
      AND JR.SOURCE = 'IC'
      AND JR.TRANSDATE BETWEEN :SDATE AND :EDATE
      AND JR.STATUS = 'O' 
      GROUP BY JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPT, JR.COST, COA.NAME
/*       PLAN (GLBUFFER INDEX (GLBUFFER_IDX_APPL_DATE))       For FB.2.x 31-Aug-2011 */
      INTO APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME,
           BUFF_DEBIT, BUFF_CREDIT
  DO
  BEGIN
     DELTA_DEBIT  = FO_DEBIT  - (GL_DEBIT+BUFF_DEBIT);
     DELTA_CREDIT = FO_CREDIT - (GL_CREDIT+BUFF_CREDIT);
     suspend;
  END  
end^


ALTER PROCEDURE CTRL_VERIFY_INV_EXPORT_TO_GL(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    APPLICATION VARCHAR(16),
    TEXT VARCHAR(40),
    INV DOUBLE PRECISION,
    BUFFER DOUBLE PRECISION,
    GL DOUBLE PRECISION,
    STOCK DOUBLE PRECISION,
    DAILY DOUBLE PRECISION,
    DELTA_BUFFER DOUBLE PRECISION,
    DELTA_INV DOUBLE PRECISION)
AS
declare variable SDATE DATE;
declare variable EDATE DATE;
declare variable EOM DATE;
begin
  if (PYEAR IS NULL) then
  BEGIN
     PYEAR = 2004;
     PMONTH = 9;
  END
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(PMONTH, PYEAR) RETURNING_VALUES(SDATE); /* 3/18/2011 */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE) returning_values :EDATE;
  EOM = EDATE;
  /* ------------------------------------------------------------------------ */
  APPLICATION = 'Inventory';
  STOCK = 0;
  DAILY = 0;

  TEXT = 'Receiving';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'INV'
  AND SOURCE = 'RECV'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'INV'
  AND SOURCE = 'RECV'
  INTO :GL;

  SELECT SUM(TOTAL*EXCHANGE) FROM INVRECV0
  WHERE OPENDATE BETWEEN :SDATE AND :EOM
  AND STATUS IN ('R', 'C')
  INTO :INV;

  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;
  SUSPEND;
  /* ------------------------------------------------------------------------ */
  TEXT = 'Issuing';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'INV'
  AND SOURCE = 'ISUE'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'INV'
  AND SOURCE = 'ISUE'
  INTO :GL;

  SELECT SUM(TOTAL) FROM INVISS0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R', 'C')
  INTO :INV;

  SELECT SUM(AMTISSUE) FROM INVSTOCK
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  INTO STOCK;

  SELECT SUM(AMT) FROM INVCONSUME_DAILY
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  INTO :DAILY;

  if (DAILY IS NULL) then DAILY = 0;
  if (STOCK IS NULL) then STOCK = 0;
  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;


  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;
  suspend;
  STOCK = 0;
  DAILY = 0;
  /* ------------------------------------------------------------------ */
  TEXT = 'Credit To Cost';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'INV'
  AND SOURCE = 'CR2C'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'INV'
  AND SOURCE = 'CR2C'
  INTO :GL;

  SELECT SUM(TOTAL) FROM inv_crd_to_cost0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R', 'C')
  INTO :INV;

  SELECT SUM(CREDIT_AMT_DB) FROM INVCONSUME_DAILY
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  INTO :DAILY;

  if (DAILY IS NULL) then DAILY = 0;
  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;
  suspend;
  STOCK = 0;
  DAILY = 0;

  /* ------------------------------------------------------------------ */
  TEXT = 'Adjustment';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'INV'
  AND SOURCE = 'ADJ'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'INV'
  AND SOURCE = 'ADJ'
  INTO :GL;

  SELECT SUM(TOTAL) FROM INVADJ0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R', 'C')
  INTO :INV;

  SELECT SUM(-AMTADJ) FROM INVSTOCK
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  INTO STOCK;

  SELECT SUM(ADJAMT) FROM INVCONSUME_DAILY
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  INTO :DAILY;

  if (DAILY IS NULL) then DAILY = 0;
  if (STOCK IS NULL) then STOCK = 0;
  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV + BUFFER;
  suspend;
  STOCK = 0;

  /* ------------------------------------------------------------------ */
  TEXT = 'Spoilage';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'INV'
  AND SOURCE = 'SPL'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'INV'
  AND SOURCE = 'SPL'
  INTO :GL;

  SELECT SUM(TOTAL) FROM INVSPL0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R', 'C')
  INTO :INV;

  SELECT SUM(AMTSPOILAGE) FROM INVSTOCK
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  INTO STOCK;

  SELECT SUM(SPLAMT) FROM INVCONSUME_DAILY
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  INTO :DAILY;

  if (DAILY IS NULL) then DAILY = 0;
  if (STOCK IS NULL) then STOCK = 0;
  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;
  suspend;
  STOCK = 0;
  DAILY = 0;

  /* ------------------------------------------------------------------ */
  TEXT = 'Return';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'INV'
  AND SOURCE = 'RET'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;
  if (BUFFER IS NULL) then BUFFER = 0;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'INV'
  AND SOURCE = 'RET'
  INTO :GL;

  SELECT SUM(((D.QTYF*D.KONVERSI+D.QTY)*D.COST/D.KONVERSI)*(1+D.TAX/100)) FROM INVRET1 D
  INNER JOIN INVRET0 H ON H.NUMBER =D.NUMBER
  WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE
  AND H.STATUS IN ('R', 'C')
  INTO :INV;


  SELECT SUM(AMTRETURN) FROM INVSTOCK
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  INTO STOCK;

  if (STOCK IS NULL) then STOCK = 0;
  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;
  suspend;
  GL = 0;
  /* ------------------------------------------------------------------------ */
  /* ACCOUNT PAYABLE                                                          */
  /* ------------------------------------------------------------------------ */
  APPLICATION = 'A/P';
  TEXT = 'A/P New Voucher';

  SELECT SUM(TOTAL) FROM APVCH
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND SOURCE IN ('R', 'C')
  INTO INV;
  if (INV IS NULL) then INV = 0;
  BUFFER = 0;
  STOCK = 0;
  DELTA_BUFFER = 0;
  DELTA_INV = 0;
  suspend;
  /* ------------------------------------------------------------------ */
  APPLICATION = 'A/P';
  TEXT = 'A/P Debit Note';

  SELECT SUM(TOTAL) FROM APVCH
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND SOURCE = 'D'
  INTO INV;
  if (INV IS NULL) then INV = 0;
  BUFFER = 0;
  STOCK = 0;
  DELTA_BUFFER = 0;
  DELTA_INV = 0;
  suspend;
  /* ------------------------------------------------------------------ */
  APPLICATION = 'A/P';
  TEXT = 'A/P Adjustment';
  SELECT SUM(CR-DB) FROM GLBUFFER
  WHERE APPLICATION = 'AP'
  AND SOURCE = 'ADJ'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  AND EXISTS(SELECT * FROM syssuppliertype WHERE syssuppliertype.GLACCOUNT = GLBUFFER.ACCOUNT)
  INTO :BUFFER;
  if (BUFFER IS NULL) then BUFFER = 0;

  SELECT SUM(CR-DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'AP'
  AND SOURCE = 'ADJ'
  AND EXISTS(SELECT * FROM syssuppliertype WHERE syssuppliertype.GLACCOUNT = GLJUR.ACCOUNT)
  INTO :GL;

  SELECT SUM(CR-DB) FROM APADJ
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R','C')
  INTO INV;


  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;
  suspend;
  /* ------------------------------------------------------------------ */
  APPLICATION = 'A/P';
  TEXT = 'A/P Cash Payment';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'AP'
  AND SOURCE = 'CASH'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  AND EXISTS(SELECT * FROM syssuppliertype WHERE syssuppliertype.GLACCOUNT = GLBUFFER.ACCOUNT)
  INTO :BUFFER;
  if (BUFFER IS NULL) then BUFFER = 0;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'AP'
  AND SOURCE = 'CASH'
  AND EXISTS(SELECT * FROM syssuppliertype WHERE syssuppliertype.GLACCOUNT = GLJUR.ACCOUNT)
  INTO :GL;

  SELECT SUM(TOTAL-FOREX_GAINLOSS) FROM APCASH0
  WHERE DUEDATE BETWEEN :SDATE AND :EDATE /* 21-NOV-2006, TADINYA OPENDATE, SUKA GAK BALANCE*/
  AND STATUS IN ('R','C','L') /* 27 OCT 2006 - HARUS ADA L, KALAU GAK, TIDAK BALANCE */
  INTO INV;

  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;
  if (STOCK IS NULL) then STOCK = 0;
  INV = INV + STOCK;
  STOCK = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;
  suspend;
  /* ------------------------------------------------------------------------ */
  /* AP RECONCILIATION                                                        */
  /* ------------------------------------------------------------------------ */
  APPLICATION = 'A/P';
  TEXT = 'Reconciliation';
  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'AP'
  AND SOURCE = 'REC'
  INTO GL;


  SELECT SUM(DB) FROM BBJUR
  WHERE APPLICATION = 'AP'
  AND SOURCE = 'REC'
  AND BBDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;


  SELECT SUM(FOREX_TOTAL*EXCHANGE) FROM APCASH0
  WHERE RECONCILEDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'C'
  INTO INV;

  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;
  suspend;
  /* ------------------------------------------------------------------ */
  APPLICATION = 'A/P Mutation';
  TEXT = 'Last Month';
  SELECT SUM(OPENING), SUM(VOUCHER), SUM(CASH), SUM(ADJUST), SUM(ENDING)
  FROM AP_MUTATION_OLD('','zzzzzz', :SDATE-1)
  INTO INV, BUFFER, GL, DELTA_BUFFER, DELTA_INV;
  SUSPEND;
  TEXT = 'This Month';
  SELECT SUM(OPENING), SUM(VOUCHER), SUM(CASH), SUM(ADJUST), SUM(ENDING)
  FROM AP_MUTATION_OLD('','zzzzzz', :EDATE)
  INTO INV, BUFFER, GL, DELTA_BUFFER, DELTA_INV;
  SUSPEND;

end^


ALTER PROCEDURE CTRL_VERIFY_INV_VS_GL(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    INV_DEBIT DOUBLE PRECISION,
    INV_CREDIT DOUBLE PRECISION,
    BUFF_DEBIT DOUBLE PRECISION,
    BUFF_CREDIT DOUBLE PRECISION,
    GL_DEBIT DOUBLE PRECISION,
    GL_CREDIT DOUBLE PRECISION,
    DELTA_DEBIT DOUBLE PRECISION,
    DELTA_CREDIT DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
begin
  IF (PYEAR IS NULL) THEN
  BEGIN
      SELECT INV_YEAR, INV_MONTH FROM SYSPARAM INTO PYEAR, PMONTH;
  END

  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(PMONTH, PYEAR) RETURNING_VALUES(SDATE); /* 3/18/2011 */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE) returning_values :EDATE;

  GL_DEBIT = 0;
  GL_CREDIT = 0;
  
  BUFF_DEBIT = 0;
  BUFF_CREDIT = 0;
  
  FOR SELECT APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME,
            SUM(DEBIT), SUM(CREDIT)
      FROM INV_GLBUFFER_AALL_RECREATE(:SDATE, :EDATE, 0)
      GROUP BY APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME
      INTO APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME,
           INV_DEBIT, INV_CREDIT
  DO
  BEGIN
     DELTA_DEBIT  = INV_DEBIT  - (GL_DEBIT+BUFF_DEBIT);
     DELTA_CREDIT = INV_CREDIT - (GL_CREDIT+BUFF_CREDIT);
     suspend;
  END
  
  INV_DEBIT = 0;
  INV_CREDIT = 0;
  FOR SELECT JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPART, JR.COST, COA.NAME,
            SUM(JR.DB), SUM(JR.CR)
      FROM GLJUR JR
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = JR.ACCOUNT
      WHERE JR.PYEAR = :PYEAR
      AND JR.PMONTH = :PMONTH
      AND JR.APPLICATION = 'INV'
      GROUP BY JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPART, JR.COST, COA.NAME
      INTO APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME,
           GL_DEBIT, GL_CREDIT
  DO
  BEGIN
     DELTA_DEBIT  = INV_DEBIT  - (GL_DEBIT+BUFF_DEBIT);
     DELTA_CREDIT = INV_CREDIT - (GL_CREDIT+BUFF_CREDIT); 
     suspend;
  END  
  GL_DEBIT = 0;
  GL_CREDIT = 0;
  
  FOR SELECT JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPT, JR.COST, COA.NAME,
            SUM(JR.DB), SUM(JR.CR)
      FROM GLBUFFER JR
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = JR.ACCOUNT
      WHERE JR.TRANSDATE BETWEEN :SDATE AND :EDATE
      AND JR.APPLICATION = 'INV'
      AND JR.STATUS = 'O'
      GROUP BY JR.APPLICATION, JR.SOURCE, JR.ACCOUNT, JR.DEPT, JR.COST, COA.NAME
      INTO APPLICATION, SOURCE, GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME,
           BUFF_DEBIT, BUFF_CREDIT
  DO
  BEGIN
     DELTA_DEBIT  = INV_DEBIT  - (GL_DEBIT+BUFF_DEBIT);
     DELTA_CREDIT = INV_CREDIT - (GL_CREDIT+BUFF_CREDIT);
     suspend;
  END  
end^


ALTER PROCEDURE DEPOSIT_OUTSTANDING(
    REFDATE DATE,
    SUPLTYPES VARCHAR(10),
    SUPLTYPEE VARCHAR(10))
RETURNS (
    NUMBER INTEGER,
    OPENDATE DATE,
    STATUS CHAR(1),
    TOTAL DOUBLE PRECISION,
    APPLIED DOUBLE PRECISION,
    SUPPLIER VARCHAR(6),
    BANK VARCHAR(4),
    CHECK_NUMBER VARCHAR(20),
    CURRENCY VARCHAR(4),
    EXCHANGE DOUBLE PRECISION,
    FOREX_TOTAL DOUBLE PRECISION,
    FOREX_GAINLOSS DOUBLE PRECISION,
    FOREX_APPLIED DOUBLE PRECISION,
    NAME VARCHAR(40),
    SUPLTYPE VARCHAR(4),
    NAME1 VARCHAR(40),
    GLACCOUNT VARCHAR(20),
    DEPOS_GLACCOUNT VARCHAR(20),
    DUE DOUBLE PRECISION)
AS
BEGIN
 IF (REFDATE IS NULL)THEN REFDATE ='31.10.2005';
  FOR
  SELECT D.NUMBER,D.OPENDATE,D.STATUS,D.TOTAL,
        D.APPLIED, D.SUPPLIER,D.BANK, D.CHECK_NUMBER,
       D.CURRENCY, D.EXCHANGE, D.FOREX_TOTAL,
       D.FOREX_GAINLOSS,D.FOREX_APPLIED,
       C.NAME, C.SUPLTYPE, T.NAME,T.GLACCOUNT,
       T.DEPOS_GLACCOUNT
    FROM APDEPOS0 D
    LEFT JOIN SYSSUPPLIER C ON C.SUPPLIER = D.SUPPLIER
    LEFT JOIN SYSSUPPLIERTYPE T ON T.SUPPLIERTYPE = C.SUPLTYPE
    WHERE D.OPENDATE <= :REFDATE

    INTO
      :NUMBER,
      :OPENDATE,
      :STATUS,
      :TOTAL,
      :APPLIED,
      :SUPPLIER,
      :BANK,
      :CHECK_NUMBER,
      :CURRENCY,
      :EXCHANGE,
      :FOREX_TOTAL,
      :FOREX_GAINLOSS,
      :FOREX_APPLIED,
      :NAME,
      :SUPLTYPE,
      :NAME1,
      :GLACCOUNT,
      :DEPOS_GLACCOUNT

 DO
  BEGIN
    SELECT SUM(TOTAL) FROM APDEPOS1
    WHERE NUMBER = :NUMBER
    AND APPLIEDDATE >= :REFDATE
    INTO APPLIED;

    IF (APPLIED IS NULL) THEN APPLIED = 0;
    DUE = TOTAL - APPLIED;
    SUSPEND;
  END
END^


ALTER PROCEDURE EC_INVCONSUME(
    HOTEL_ID VARCHAR(4),
    EC_YEAR INTEGER)
RETURNS (
    HOTELID VARCHAR(4),
    PYEAR INTEGER,
    PMONTH INTEGER,
    PARTNO VARCHAR(10),
    ITEMTYPE CHAR(1),
    ITEMCLASS VARCHAR(2),
    ITEMGROUP VARCHAR(4),
    DEPT VARCHAR(4),
    ICOSTYPE CHAR(1),
    ICOST VARCHAR(4),
    QTY DOUBLE PRECISION,
    ADJQTY DOUBLE PRECISION,
    SPLQTY DOUBLE PRECISION,
    DIRECTUSEQTY DOUBLE PRECISION,
    AMT DOUBLE PRECISION,
    ADJAMT DOUBLE PRECISION,
    SPLAMT DOUBLE PRECISION,
    SALESQTY DOUBLE PRECISION,
    SALESAMT DOUBLE PRECISION,
    DIRECTUSEAMT DOUBLE PRECISION,
    RECIPEQTY DOUBLE PRECISION,
    RECIPEAMT DOUBLE PRECISION,
    CREDIT_QTY DOUBLE PRECISION,
    CREDIT_AMT DOUBLE PRECISION)
AS
BEGIN
  HOTELID=:HOTEL_ID;
  FOR
    SELECT PYEAR,
         PMONTH,
         PARTNO,
         ITEMTYPE,
         ITEMCLASS,
         ITEMGROUP,
         DEPT,
         ICOSTYPE,
         ICOST,
         QTY,
         ADJQTY,
         SPLQTY,
         DIRECTUSEQTY,
         AMT,
         ADJAMT,
         SPLAMT,
         SALESQTY,
         SALESAMT,
         DIRECTUSEAMT,
         RECIPEQTY,
         RECIPEAMT,
         CREDIT_QTY,
         CREDIT_AMT FROM INVCONSUME WHERE PYEAR=:EC_YEAR
    INTO :PYEAR,
         :PMONTH,
         :PARTNO,
         :ITEMTYPE,
         :ITEMCLASS,
         :ITEMGROUP,
         :DEPT,
         :ICOSTYPE,
         :ICOST,
         :QTY,
         :ADJQTY,
         :SPLQTY,
         :DIRECTUSEQTY,
         :AMT,
         :ADJAMT,
         :SPLAMT,
         :SALESQTY,
         :SALESAMT,
         :DIRECTUSEAMT,
         :RECIPEQTY,
         :RECIPEAMT,
         :CREDIT_QTY,
         :CREDIT_AMT
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE FA_BOOKVALUE(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    FA_MASTER_ID INTEGER,
    FA_CODE VARCHAR(40),
    FA_TYPE VARCHAR(8),
    TYPENAME VARCHAR(40),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NAME VARCHAR(80),
    DATEACTIVE DATE,
    DEPRE_START_YEAR INTEGER,
    DEPRE_START_MONTH INTEGER,
    VALUE_OPEN DOUBLE PRECISION,
    DEPRECIATION_COUNT DOUBLE PRECISION,
    DEPRECIATION DOUBLE PRECISION,
    BOOKVALUE DOUBLE PRECISION)
AS
BEGIN
  IF ((PYEAR = 0) OR (PYEAR IS NULL)) THEN
  BEGIN
     PYEAR = 2005;
     PMONTH = 10;
  END

  FOR
    SELECT M.FA_MASTER_ID, M.FA_CODE, M.FA_TYPE,
           T.NAME TYPENAME,
           T.ASSET_ACCOUNT GL_ACCOUNT,
           T.ASSET_DEPT GL_DEPT,
           T.ASSET_COST GL_COST,
           A.NAME ACCNAME,
           M.NAME, M.DATEACTIVE, M.VALUE_OPEN,
           M.DEPRE_START_YEAR,
           M.DEPRE_START_MONTH
    FROM FA_MASTER M
    LEFT JOIN FA_TYPE T ON T.FA_TYPE = M.FA_TYPE
    LEFT JOIN GLCOA A ON A.ACCOUNT = T.ASSET_ACCOUNT
    WHERE  M.DEPRE_START_YEAR * 12 + M.DEPRE_START_MONTH <= :PYEAR*12+:PMONTH
    INTO
      :FA_MASTER_ID,
      :FA_CODE,
      :FA_TYPE,
      :TYPENAME,
      :GL_ACCOUNT,
      :GL_DEPT,
      :GL_COST,
      :ACCNAME,
      :NAME,
      :DATEACTIVE,
      :VALUE_OPEN,
      :DEPRE_START_YEAR,
      :DEPRE_START_MONTH
  DO
  BEGIN
    SELECT SUM(AMOUNT), COUNT(*)
    FROM FA_MASTER_DEPRE
    WHERE FA_MASTER_ID = :FA_MASTER_ID
    AND PYEAR*12+PMONTH <= :PYEAR * 12 + :PMONTH
    INTO DEPRECIATION, DEPRECIATION_COUNT;

    IF (DEPRECIATION IS NULL) THEN DEPRECIATION = 0;
    BOOKVALUE = VALUE_OPEN - DEPRECIATION;
    SUSPEND;
  END
END^


ALTER PROCEDURE FA_DEPRECIATION(
    AYEAR INTEGER,
    AMONTH INTEGER,
    SMASTER_ID INTEGER,
    EMASTER_ID INTEGER,
    USRID VARCHAR(8),
    PSAVE INTEGER)
RETURNS (
    PYEAR INTEGER,
    PMONTH INTEGER,
    FA_MASTER_ID INTEGER,
    FA_CODE VARCHAR(40),
    FA_TYPE VARCHAR(8),
    FA_METHOD VARCHAR(4),
    NAME VARCHAR(80),
    FA_STATUS CHAR(1),
    VALUE_OPEN DOUBLE PRECISION,
    VALUE_DEPRE DOUBLE PRECISION,
    VALUE_BOOK DOUBLE PRECISION,
    DEPRE_AMOUNT DOUBLE PRECISION,
    DEPRE_AGE INTEGER,
    DEPRE_COUNT INTEGER,
    DEPRE_START_YEAR INTEGER,
    DEPRE_START_MONTH INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    ACCTYPE VARCHAR(1))
AS
/* */
DECLARE VARIABLE DEPRE_TOTAL DOUBLE PRECISION;
BEGIN
  IF (AYEAR IS NULL) THEN
  BEGIN
     SELECT GLYEAR,GLMONTH FROM SYSPARAM WHERE ID = 1 INTO AYEAR,AMONTH;
     SMASTER_ID = 0;
     EMASTER_ID = 999999;
  END
  PYEAR = AYEAR;
  PMONTH = AMONTH;

  IF (PSAVE = 1) THEN /* 25 JANUARY 2006 */
     DELETE FROM FA_MASTER_DEPRE WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH;

  FOR
    SELECT M.FA_MASTER_ID,M.FA_CODE,M.FA_TYPE,M.FA_METHOD,
           M.NAME,M.FA_STATUS,
           M.VALUE_OPEN,M.VALUE_DEPRE,M.VALUE_BOOK,
           M.DEPRE_AGE,
           T.DEPRE_ACCOUNT,T.DEPRE_DEPT,T.DEPRE_COST,
           A.NAME,A.ACCTYPE,
           M.DEPRE_START_YEAR,M.DEPRE_START_MONTH
    FROM FA_MASTER M
    LEFT JOIN FA_TYPE T ON T.FA_TYPE = M.FA_TYPE
    LEFT JOIN GLCOA A ON A.ACCOUNT = T.DEPRE_ACCOUNT
    WHERE M.FA_MASTER_ID BETWEEN :SMASTER_ID  AND :EMASTER_ID
    AND M.FA_STATUS = 'A'
    AND M.DEPRE_START_YEAR * 12 + M.DEPRE_START_MONTH <= :AYEAR*12+:AMONTH
    ORDER BY M.NAME
    INTO :FA_MASTER_ID,:FA_CODE,:FA_TYPE,:FA_METHOD,
         :NAME,:FA_STATUS,
         :VALUE_OPEN,:VALUE_DEPRE,:VALUE_BOOK,
         :DEPRE_AGE,
         :GL_ACCOUNT,:GL_DEPT,:GL_COST,
         :ACCNAME,ACCTYPE,
         DEPRE_START_YEAR,DEPRE_START_MONTH
  DO
  BEGIN

    SELECT SUM (AMOUNT) FROM FA_MASTER_DEPRE
    WHERE FA_MASTER_ID = :FA_MASTER_ID
    INTO DEPRE_TOTAL;

    DEPRE_COUNT = AYEAR*12+AMONTH - (DEPRE_START_YEAR * 12 + DEPRE_START_MONTH)+1;

    IF (DEPRE_COUNT <= DEPRE_AGE) THEN
    BEGIN
       /* -------------------------------------------------------------------- */
       /* STRAIGH LINE                                                         */
       /* -------------------------------------------------------------------- */
       IF (FA_METHOD = 'SL') THEN
       BEGIN
         IF (DEPRE_AGE <> 0) THEN
         BEGIN
            DEPRE_AMOUNT = VALUE_OPEN / DEPRE_AGE;
         END
       END
       /* -------------------------------------------------------------------- */
       /* DOUBLE DECLINING                                                     */
       /* 1/17/2014                                                            */
       /* -------------------------------------------------------------------- */
       ELSE IF (FA_METHOD = 'DD') THEN
       BEGIN
         DEPRE_AMOUNT = 0;
         SELECT AMOUNT FROM FA_DEPRE_CREATE(:FA_MASTER_ID,0,'')
         WHERE PYEAR=:AYEAR
         AND PMONTH=:AMONTH
         INTO DEPRE_AMOUNT;
         IF (DEPRE_AMOUNT IS NULL) THEN DEPRE_AMOUNT = 0;
       END /* 1/17/2014 END OF */
       ELSE DEPRE_AMOUNT = 0;


       IF (VALUE_OPEN - DEPRE_TOTAL < DEPRE_AMOUNT) THEN
          DEPRE_AMOUNT = VALUE_OPEN - DEPRE_TOTAL;





       IF ((DEPRE_AMOUNT > 0) AND
           (VALUE_BOOK - DEPRE_AMOUNT > -0.5) /* 4 JUN 2008 */)  THEN
       BEGIN
          IF (PSAVE = 1) THEN
          BEGIN
             INSERT INTO FA_MASTER_DEPRE (FA_MASTER_ID,PYEAR,PMONTH,AMOUNT,
                   STATUS,CREATEUSER,EDITUSER)
             VALUES (:FA_MASTER_ID,:PYEAR,:PMONTH,:DEPRE_AMOUNT,
                  'O',:USRID,:USRID);
          END
        ELSE
        BEGIN
           SUSPEND;
        END
      END
    END
  END
END^


ALTER PROCEDURE FA_DEPRE_CREATE(
    FA_ID INTEGER,
    FLAG_SAVE INTEGER,
    USRID VARCHAR(8))
RETURNS (
    INFO VARCHAR(8),
    FA_MASTER_ID INTEGER,
    LISTINDEX INTEGER,
    PYEAR INTEGER,
    PMONTH INTEGER,
    AMOUNT DOUBLE PRECISION,
    STATUS VARCHAR(1),
    TOT_ACC DOUBLE PRECISION,
    DD_YEAR_AGE INTEGER,
    DD_FACTOR DOUBLE PRECISION,
    DD_YEAR INTEGER,
    DD_MONTH INTEGER,
    DD_ACC DOUBLE PRECISION,
    DD_DEPRE DOUBLE PRECISION)
AS
DECLARE VARIABLE OPEN_VALUE DOUBLE PRECISION;
DECLARE VARIABLE DEPRE_AGE INTEGER;
DECLARE VARIABLE DEPRE_START_YEAR INTEGER;
DECLARE VARIABLE DEPRE_START_MONTH INTEGER;
DECLARE VARIABLE DD_COUNT INTEGER;
DECLARE VARIABLE FA_METHOD VARCHAR(2);
BEGIN
  FA_MASTER_ID = FA_ID;
  SELECT VALUE_OPEN, DEPRE_AGE, FA_METHOD,
         DEPRE_START_YEAR, DEPRE_START_MONTH
  FROM FA_MASTER
  WHERE FA_MASTER_ID = :FA_ID
  INTO OPEN_VALUE, DEPRE_AGE, FA_METHOD,
       DEPRE_START_YEAR, DEPRE_START_MONTH;
  TOT_ACC = 0;
  /* -------------------------------------------------------------------- */
  /* DOUBLE DECLINING                                                     */
  /* -------------------------------------------------------------------- */
  IF (FA_METHOD = 'DD') THEN
  BEGIN
      DD_YEAR_AGE = DEPRE_AGE/12;
      DD_FACTOR = 2/DD_YEAR_AGE; /* DEPRE_AGE DALAM BULAN, DIUBAH JADI TAHUN X 2*/
      /* -------------------------------------------------------------------- */
      INFO = 'HISTORY';
      FOR SELECT LISTINDEX, PYEAR, PMONTH, AMOUNT, STATUS
          FROM FA_MASTER_DEPRE
          WHERE FA_MASTER_ID = :FA_ID
          ORDER BY LISTINDEX
      INTO LISTINDEX, PYEAR, PMONTH, AMOUNT, STATUS
      DO
      BEGIN
        TOT_ACC = TOT_ACC + AMOUNT;
        IF (FLAG_SAVE <> 1) THEN
           SUSPEND;
      END
      PMONTH = PMONTH + 1;
      if (PMONTH > 12) then
      BEGIN
         PMONTH = 1;
         PYEAR = PYEAR + 1;
      END
      /* if NO DEPECIATION CREATE then */
      if (LISTINDEX IS NULL) then
      BEGIN
        LISTINDEX = 1;
        PYEAR  = DEPRE_START_YEAR;
        PMONTH = DEPRE_START_MONTH;
      END
      DD_YEAR  = PYEAR - DEPRE_START_YEAR;
      DD_MONTH = PMONTH - DEPRE_START_MONTH;
      IF (DD_MONTH < 0) THEN
      BEGIN
         DD_YEAR  = DD_YEAR - 1;
         DD_MONTH = DD_MONTH + 12;
      END
      STATUS = 'O';
      /* -------------------------------------------------------------------- */
      INFO = 'NEW';
      WHILE (LISTINDEX <= DEPRE_AGE) DO
      BEGIN

        DD_COUNT = DD_YEAR;
        DD_ACC   = 0;
        DD_DEPRE = 0;
        WHILE (DD_COUNT >= 0) DO
        BEGIN
           IF ((DD_YEAR = DD_YEAR_AGE-1) AND (DD_COUNT = 0)) THEN
              DD_DEPRE = (OPEN_VALUE - DD_ACC);
           ELSE
              DD_DEPRE = (OPEN_VALUE - DD_ACC) * DD_FACTOR;
           DD_ACC = DD_ACC + DD_DEPRE;
           DD_COUNT = DD_COUNT - 1;
        END
        /* -------------------------------------------------------------------- */
        AMOUNT = DD_DEPRE / 12;
        TOT_ACC = TOT_ACC + AMOUNT;
        IF (FLAG_SAVE <> 1) THEN SUSPEND;
        ELSE
        BEGIN
    
            INSERT INTO FA_MASTER_DEPRE
               (FA_MASTER_ID,LISTINDEX,PYEAR,PMONTH,AMOUNT,STATUS, CREATEUSER, EDITUSER)
            VALUES
               (:FA_ID, :LISTINDEX, :PYEAR, :PMONTH, :AMOUNT, 'O', :USRID, :USRID);
        END
        LISTINDEX = LISTINDEX + 1;
        PMONTH = PMONTH + 1;
        if (PMONTH > 12) then
        BEGIN
           PMONTH = 1;
           PYEAR = PYEAR + 1;
        END
        DD_MONTH = DD_MONTH + 1;
        IF (DD_MONTH >= 12) THEN
        BEGIN
            DD_MONTH = 0;
            DD_YEAR = DD_YEAR+1;
        END
      END
  END
END^


ALTER PROCEDURE FA_GLBUFFER_ADJUST(
    NUMBER INTEGER)
RETURNS (
    INFO VARCHAR(20),
    ASSETTYPE VARCHAR(8),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE MASTER_ID INTEGER;
DECLARE VARIABLE FTYPE VARCHAR(8);
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;
DECLARE VARIABLE NAME VARCHAR(40);
DECLARE VARIABLE ADC_VALUE_ASSET DOUBLE PRECISION;
DECLARE VARIABLE ADC_VALUE_DEPRE DOUBLE PRECISION;
DECLARE VARIABLE ADC_VALUE_EXPENSES DOUBLE PRECISION;
BEGIN
  if (NUMBER IS NULL) then
  BEGIN
     NUMBER = 1;
  END
  /* ---------------------------------------------------------------- */
  /* NOL KAN ASSET                                                    */
  /* ---------------------------------------------------------------- */
  SELECT D.PYEAR, D.PMONTH, FA_MASTER_ID, OPENDATE, -CR, -CR_ACCUM_DEPRE, -CR_EXPENSES QTY
  FROM FA_MASTER_ADJ D WHERE NUMBER = :NUMBER
  INTO PYEAR, PMONTH, MASTER_ID, TRANSDATE, ADC_VALUE_ASSET, ADC_VALUE_DEPRE, ADC_VALUE_EXPENSES;

  /* -------------------------------------------------------------------- */
  /* FA MASTER                                                            */
  /* -------------------------------------------------------------------- */
  SELECT FA_TYPE, SUBSTR(NAME,1,40)
  FROM FA_MASTER WHERE FA_MASTER_ID = :MASTER_ID
  INTO FTYPE, NAME;

  /* -------------------------------------------------------------------- */
  SELECT T.ASSET_ACCOUNT, T.ASSET_DEPT, T.ASSET_COST, COA.NAME
  FROM FA_TYPE T
  LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.ASSET_ACCOUNT
  WHERE T.FA_TYPE = :FTYPE
  INTO GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME;


  TRANSDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(TRANSDATE) RETURNING_VALUES(TRANSDATE);
  ID = 0;
  DEBIT = 0;
  CREDIT = ADC_VALUE_ASSET;
  INFO = 'Asset';
  SETUP_INFO = 'FA_ADJ';
  ASSETTYPE = FTYPE;
  NOTE = NAME;
  REF = 'CR Init Asset Value';

  EXECUTE PROCEDURE INV_GLBUFFER_ERROR('FA_TYPE', GL_ACCOUNT, GL_DEPT, GL_COST, '', '')
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;
  SUSPEND;
  /* ---------------------------------------------------------------- */
  /* NOL KAN DEPRESIASI                                               */
  /* ---------------------------------------------------------------- */
  SELECT T.DEPRE_ACCOUNT, T.DEPRE_DEPT, T.DEPRE_COST, COA.NAME
  FROM FA_TYPE T
  LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.DEPRE_ACCOUNT
  WHERE T.FA_TYPE = :FTYPE
  INTO GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME;


  ID = 1;
  CREDIT = 0;
  DEBIT = ADC_VALUE_DEPRE;
  INFO = 'Depreciation';
  SETUP_INFO = 'FA_ADJ';
  ASSETTYPE = FTYPE;
  NOTE = NAME;
  REF = 'DB Acc Depre.';

  EXECUTE PROCEDURE INV_GLBUFFER_ERROR('FA_TYPE', GL_ACCOUNT, GL_DEPT, GL_COST, '', '')
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;
  SUSPEND;
  /* ---------------------------------------------------------------- */
  /* MASUKKAN BIAYA ASSET                                             */
  /* 13 APRIL 2010                                                    */
  /* KALAU BARANG SUDAH DIPAKAI HABIS YA, TIDAK PERLU                 */
  /* ---------------------------------------------------------------- */
  IF (ADC_VALUE_EXPENSES = 0) THEN EXIT;
  SELECT D.GL_ACCOUNT, D.GL_DEPT, D.GL_COST, A.NAME
  FROM FA_MASTER_ADJ D
  LEFT JOIN GLCOA A ON A.ACCOUNT = D.GL_ACCOUNT
  WHERE NUMBER = :NUMBER
  INTO GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME;
  /* -------------------------------------------------------------------- */
  /* end of 13 april 2010                                                 */
  /* -------------------------------------------------------------------- */
  DEBIT = ADC_VALUE_EXPENSES;
  ID = 2;
  CREDIT = 0;
  INFO = 'Expense'; /* 4/20/2011 before, Adjustment */
  SETUP_INFO = 'FA_ADJ';
  ASSETTYPE = FTYPE;
  REF = MASTER_ID;

  EXECUTE PROCEDURE INV_GLBUFFER_ERROR('FA_TYPE', GL_ACCOUNT, GL_DEPT, GL_COST, '', '')
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;
  SUSPEND;
END^


ALTER PROCEDURE FA_GLBUFFER_DEPRE(
    NUMBER INTEGER)
RETURNS (
    INFO VARCHAR(20),
    ASSETTYPE VARCHAR(8),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE MASTER_ID INTEGER;
DECLARE VARIABLE FTYPE VARCHAR(8);
DECLARE VARIABLE AMOUNT DOUBLE PRECISION;
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;
BEGIN
  if (NUMBER IS NULL) then
  BEGIN
     NUMBER = 6;
  END

  SELECT D.PYEAR, D.PMONTH, D.AMOUNT, M.FA_TYPE, SUBSTR(M.NAME,1,40), FA_MASTER_ID
  FROM FA_MASTER_DEPRE D
  LEFT JOIN FA_MASTER M ON M.FA_MASTER_ID = D.FA_MASTER_ID
  WHERE DEPRETIATION_ID = :NUMBER
  INTO PYEAR, PMONTH, AMOUNT, FTYPE, NOTE, MASTER_ID;

  TRANSDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE SP_DATE_EOM(TRANSDATE) RETURNING_VALUES(TRANSDATE);

  SELECT T.ACC_DEPRE_ACCOUNT, T.ACC_DEPRE_DEPT,T.ACC_DEPRE_COST , COA.NAME
  FROM FA_TYPE T
  LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.DEPRE_ACCOUNT
  WHERE T.FA_TYPE = :FTYPE
  INTO GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME;
  DEBIT = AMOUNT;
  CREDIT = 0;
  ID = 0;
  INFO = 'Acc.Depreciation';
  SETUP_INFO = 'FA_TYPE';
  ASSETTYPE = FTYPE;
  REF = MASTER_ID;
  EXECUTE PROCEDURE INV_GLBUFFER_ERROR('FA_TYPE', GL_ACCOUNT, GL_DEPT, GL_COST, '', '')
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;
  SUSPEND;

  SELECT T.DEPRE_ACCOUNT, T.DEPRE_DEPT, T.DEPRE_COST, COA.NAME
  FROM FA_TYPE T
  LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.DEPRE_ACCOUNT
  WHERE T.FA_TYPE = :FTYPE
  INTO GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME;
  DEBIT = 0;
  CREDIT = AMOUNT;
  ID = 1;
  INFO = 'Depreciation';
  SETUP_INFO = 'FA_TYPE';
  EXECUTE PROCEDURE INV_GLBUFFER_ERROR('FA_TYPE', GL_ACCOUNT, GL_DEPT, GL_COST, '', '')
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;
  SUSPEND;

END^


ALTER PROCEDURE FA_GLBUFFER_DEPRE_JOURNAL(
    PMONTH INTEGER,
    PYEAR INTEGER)
RETURNS (
    NUMBER INTEGER,
    OPENDATE DATE,
    INFO VARCHAR(20),
    ASSETTYPE VARCHAR(8),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER,
    ERROR_TEXT VARCHAR(128))
AS
declare variable USR VARCHAR(8);
BEGIN
  FOR SELECT DEPRETIATION_ID
      FROM FA_MASTER_DEPRE
      WHERE PYEAR = :PYEAR
      AND PMONTH = :PMONTH
  INTO :NUMBER
  DO
  BEGIN
    FOR
      SELECT INFO, ASSETTYPE, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
             GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
      FROM FA_GLBUFFER_DEPRE(:NUMBER)
      INTO :INFO, :ASSETTYPE, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
           :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
           RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
    DO
    BEGIN
       SUSPEND;
    END
  END
END^


ALTER PROCEDURE FA_GLBUFFER_RELEASE(
    NUMBER INTEGER)
RETURNS (
    INFO VARCHAR(20),
    ASSETTYPE VARCHAR(8),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    ERROR_TEXT VARCHAR(128),
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER)
AS
DECLARE VARIABLE MASTER_ID INTEGER;
DECLARE VARIABLE FTYPE VARCHAR(8);
DECLARE VARIABLE AMOUNT DOUBLE PRECISION;
BEGIN
  if (NUMBER IS NULL) then
  BEGIN
     NUMBER = 6;
  END

  SELECT M.VALUE_OPEN, M.FA_TYPE, SUBSTR(M.NAME,1,40), M.FA_MASTER_ID, M.DATEACTIVE
  FROM  FA_MASTER M
  WHERE M.FA_MASTER_ID = :NUMBER
  INTO AMOUNT, FTYPE, NOTE, MASTER_ID, TRANSDATE;

  SELECT T.ASSET_ACCOUNT, T.ASSET_DEPT, T.ASSET_COST, COA.NAME
  FROM FA_TYPE T
  LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.DEPRE_ACCOUNT
  WHERE T.FA_TYPE = :FTYPE
  INTO GL_ACCOUNT, GL_DEPT, GL_COST, ACCNAME;
  DEBIT = AMOUNT;
  CREDIT = 0;
  ID = 0;
  INFO = 'Asset';
  SETUP_INFO = 'FA_TYPE';
  ASSETTYPE = FTYPE;
  REF = MASTER_ID;
  EXECUTE PROCEDURE INV_GLBUFFER_ERROR('FA_TYPE', GL_ACCOUNT, GL_DEPT, GL_COST, '', '')
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;
  SUSPEND;
  
  SELECT CFG.FA_TRANS_GL_ACCOUNT, CFG.FA_TRANS_GL_DEPT, CFG.FA_TRANS_GL_COST,
         COA.NAME
  FROM SYSPARAM CFG
  LEFT JOIN GLCOA COA ON COA.ACCOUNT = CFG.FA_TRANS_GL_ACCOUNT
  INTO :GL_ACCOUNT, :GL_DEPT, :GL_COST, :ACCNAME;
  INFO = 'Trans. Asset';
  NOTE = 'Transient Asset';

  EXECUTE PROCEDURE INV_GLBUFFER_ERROR('FA_TRANS_ACCOUNT', GL_ACCOUNT, GL_DEPT, GL_COST, NULL, NULL)
  RETURNING_VALUES ERROR_TEXT, SETUP_INFO;
  SETUP_INFO = 'SYSPARAM';
  DEBIT = 0;
  CREDIT = AMOUNT;
  ID = 1;
  SUSPEND;

END^


ALTER PROCEDURE FA_GLBUFFER_RELEASE_RECREATE(
    SDATE DATE,
    EDATE DATE,
    PSAVE INTEGER)
RETURNS (
    NUMBER INTEGER,
    OPENDATE DATE,
    INFO VARCHAR(20),
    ASSETTYPE VARCHAR(8),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    RELATION_CODE VARCHAR(6),
    RELATION_DOCTYPE INTEGER,
    ERROR_TEXT VARCHAR(128))
AS
declare variable USR VARCHAR(8);
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;
BEGIN
  if (SDATE IS NULL) then
  BEGIN
     SDATE = '1.5.2005';
     EDATE = '31.5.2005';
     PSAVE = 0;
  END

  PYEAR = EXTRACT(YEAR FROM SDATE);
  PMONTH = EXTRACT(MONTH FROM SDATE);

  if (PSAVE = 1) then
  BEGIN
     DELETE FROM glbuffer
     WHERE APPLICATION = 'FA'
     AND SOURCE = 'NEW'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE;

     DELETE FROM GLTRANS
     WHERE APPLICATION = 'FA'
     AND SOURCE = 'NEW'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE;
     /* ---------------------------------------------------------------- */
     /* 13 MARET 2008                                                    */
     /* ---------------------------------------------------------------- */
     DELETE FROM glbuffer
     WHERE APPLICATION = 'FA'
     AND SOURCE = 'ADJ'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE;

     DELETE FROM GLTRANS
     WHERE APPLICATION = 'FA'
     AND SOURCE = 'ADJ'
     AND TRANSDATE BETWEEN :SDATE AND :EDATE;
     /* ---------------------------------------------------------------- */
     /* END OF 13 MARET 2008                                             */
     /* ---------------------------------------------------------------- */
  END
  FOR SELECT M.FA_MASTER_ID, M.DATEACTIVE, M.EDITUSER
  FROM  FA_MASTER M
      WHERE DATEACTIVE BETWEEN :SDATE AND :EDATE
      AND INV_RECV_GLSTATUS = 'R'
  INTO :NUMBER, :OPENDATE, USR
  DO
  BEGIN
    FOR
      SELECT INFO, ASSETTYPE, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
             GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
      FROM FA_GLBUFFER_RELEASE(:NUMBER)
      INTO :INFO, :ASSETTYPE, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
           :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
           RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
    DO
    BEGIN
       if (DEBIT + CREDIT <> 0) then
       BEGIN
         if (PSAVE = 1) then
         BEGIN
          insert into glbuffer
                 (APPLICATION, SOURCE, NUMBER, ID, transdate,
                  ACCOUNT, DEPT, COST, PROJECT,
                  NOTE, REF,
                  DB, CR,
                  EXPORTDATE, EXPORTUSER)
          values ('FA','NEW', :number, :ID, :opendate,
                  :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                  :NOTE, :REF,
                  :DEBIT, :CREDIT,
                  'now', :USR);
          END
          ELSE
            SUSPEND;
       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* 13 MARET 2008                                                    */
  /* ADJUSTMENT                                                       */
  /* ---------------------------------------------------------------- */
  FOR SELECT M.NUMBER, M.OPENDATE, M.EDITUSER
  FROM  FA_MASTER_ADJ M
      WHERE PYEAR = :PYEAR
      AND PMONTH = :PMONTH
      AND STATUS = 'R'
  INTO :NUMBER, :OPENDATE, USR
  DO
  BEGIN
    FOR
      SELECT INFO, ASSETTYPE, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
             GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT,
             RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
      FROM FA_GLBUFFER_ADJUST(:NUMBER)
      INTO :INFO, :ASSETTYPE, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
           :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT,
           RELATION_CODE, RELATION_DOCTYPE, ERROR_TEXT
    DO
    BEGIN
       if (DEBIT + CREDIT <> 0) then
       BEGIN
         if (PSAVE = 1) then
         BEGIN
          insert into glbuffer
                 (APPLICATION, SOURCE, NUMBER, ID, transdate,
                  ACCOUNT, DEPT, COST, PROJECT,
                  NOTE, REF,
                  DB, CR,
                  EXPORTDATE, EXPORTUSER)
          values ('FA','ADJ', :number, :ID, :opendate,
                  :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                  :NOTE, :REF,
                  :DEBIT, :CREDIT,
                  'now', :USR);
          END
          ELSE
            SUSPEND;
       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* END OF 13 MARET 2008                                             */
  /* ADJUSTMENT                                                       */
  /* ---------------------------------------------------------------- */
END^


ALTER PROCEDURE FA_GL_DISCREPANCY(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    CODE VARCHAR(16),
    CODE_NAME VARCHAR(40),
    NUMBER INTEGER,
    OPENDATE DATE,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    PO_NUMBER INTEGER,
    PARTNO VARCHAR(10),
    MSTNAME VARCHAR(40),
    MSTUNIT VARCHAR(6),
    QTY DOUBLE PRECISION,
    COST DOUBLE PRECISION,
    LINE INTEGER,
    FA_MASTER_ID INTEGER,
    FA_NAME VARCHAR(80),
    FA_QTY DOUBLE PRECISION,
    FA_COST DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
BEGIN
  SDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE SP_DATE_BOM(SDATE) RETURNING_VALUES(SDATE);  /* 3/18/2011  */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE)   RETURNING_VALUES(EDATE); /* 3/18/2011  */

  FOR
    SELECT H.NUMBER, H.OPENDATE, H.SUPPLIER, S.NAME
     FROM INVRECV0 H
     LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = H.SUPPLIER
     WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE
     AND H.STATUS IN ('R','C')
     AND H.ICOST = 'FA'
     INTO :NUMBER, :OPENDATE, :SUPPLIER, :NAME
     DO
     BEGIN
       FOR SELECT D.LINE, D.PARTNO,  D.PONUMBER, M.NAME, M.UNITF,
           D.CALC_QTY, D.CALC_COST_FOREX/D.CALC_QTY 
           FROM INVRECV1 D
           LEFT JOIN INVMASTER M ON M.PARTNO = D.PARTNO
           WHERE NUMBER = :NUMBER
           AND D.CALC_QTY <> 0
           AND D.DIRECTUSE = 1
       INTO LINE, PARTNO, PO_NUMBER, MSTNAME, MSTUNIT, QTY, COST
       DO
       BEGIN
         FA_MASTER_ID = 0;
         FA_NAME = '';
         FA_QTY = 0;
         FA_COST = 0;
         IF (NOT EXISTS(SELECT * FROM FA_MASTER WHERE INV_RECV_NO = :NUMBER AND INV_RECV_LINE = :LINE)) THEN
         BEGIN
            CODE = 'NOTFOUND';
            CODE_NAME = 'Item Not Imported';
            SUSPEND;
         END
         ELSE
         BEGIN
            SELECT FA_MASTER_ID, NAME, VALUE_QTY, VALUE_COST
            FROM FA_MASTER
            WHERE INV_RECV_NO = :NUMBER AND INV_RECV_LINE = :LINE
            INTO FA_MASTER_ID, FA_NAME, FA_QTY, FA_COST;
            IF (QTY <> FA_QTY) THEN
            BEGIN
               CODE = 'QTY';
               CODE_NAME = 'Quantity Discrepancy';
               SUSPEND;
            END
            ELSE
            IF (COST <> FA_COST) THEN
            BEGIN
               CODE = 'COST';
               CODE_NAME = 'Unit Cost Discrepancy';
               SUSPEND;
          END
       END
     END
  END
END^


ALTER PROCEDURE FA_IMPORT_RECEIVING(
    SDATE DATE,
    EDATE DATE,
    USRID VARCHAR(8),
    PSAVE INTEGER,
    RECV_NUMBER INTEGER,
    RECV_LINE INTEGER)
RETURNS (
    NUMBER INTEGER,
    OPENDATE DATE,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    ADDRESS1 VARCHAR(40),
    ADDRESS2 VARCHAR(40),
    ADDRESS3 VARCHAR(40),
    CONTACT VARCHAR(40),
    PHONE VARCHAR(40),
    FAX VARCHAR(40),
    EMAIL VARCHAR(40),
    PO_NUMBER INTEGER,
    PARTNO VARCHAR(10),
    MSTNAME VARCHAR(40),
    MSTUNIT VARCHAR(6),
    QTY DOUBLE PRECISION,
    COST DOUBLE PRECISION,
    FLAG_IMPORT INTEGER,
    LINE INTEGER)
AS
DECLARE VARIABLE AMT DOUBLE PRECISION;
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;
DECLARE VARIABLE FA_TYPE VARCHAR(20);
BEGIN
  IF (SDATE IS NULL) THEN
  BEGIN
     SELECT INVSYSDATE FROM SYSPARAM INTO SDATE;
     EXECUTE PROCEDURE SP_BEGINOFMONTH(SDATE) RETURNING_VALUES(SDATE);
     EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE)   RETURNING_VALUES(EDATE);
     PSAVE = 0;
  END
  /* ---------------------------------------------------------------- */
  /* 12 JUN 2007                                                      */
  /* SAVE FIXED ASSET ONE BY ONE                                      */
  /* ---------------------------------------------------------------- */
  FLAG_IMPORT = 0;
  IF ((PSAVE = 1) AND (RECV_NUMBER <> 0)) THEN
  BEGIN
     IF (NOT EXISTS(SELECT * FROM FA_MASTER WHERE INV_RECV_NO = :RECV_NUMBER AND INV_RECV_LINE = :RECV_LINE)) THEN
     BEGIN
        /* ---------------------------------------------------------------- */
        /* GET RECEIVING HEADER                                             */
        /* ---------------------------------------------------------------- */
        SELECT H.NUMBER, H.OPENDATE, H.SUPPLIER,
               S.NAME, S.ADDRESS1, S.ADDRESS2, S.ADDRESS3,
               S.CONTACT, S.PHONE, S.FAX, S.EMAIL
        FROM INVRECV0 H
        LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = H.SUPPLIER
        WHERE H.NUMBER = :RECV_NUMBER
        INTO :NUMBER, :OPENDATE, :SUPPLIER, :NAME, :ADDRESS1,
             :ADDRESS2, :ADDRESS3, :CONTACT, :PHONE, :FAX, :EMAIL;
        /* ---------------------------------------------------------------- */
        /* GET DETAIL RECEIVING                                             */
        /* ---------------------------------------------------------------- */
        SELECT D.LINE, D.PARTNO,  D.PONUMBER, M.NAME, M.UNITF,
           D.CALC_QTY-D.QTYRET, /* 17 MARET 2008, SETELAH RETURN */
           D.CALC_COST_FOREX/D.CALC_QTY /*06.01.2006,RECV ASSET USD(RIZAL)*/
        FROM INVRECV1 D
        LEFT JOIN INVMASTER M ON M.PARTNO = D.PARTNO
        WHERE NUMBER = :RECV_NUMBER
        AND LINE = :RECV_LINE
        INTO LINE, PARTNO, PO_NUMBER, MSTNAME, MSTUNIT, QTY, COST;
        /* ---------------------------------------------------------------- */
        /* SAVE TO FIXED ASSET                                              */
        /* ---------------------------------------------------------------- */
        IF (QTY <> 0) THEN
        BEGIN
           INSERT INTO FA_MASTER (
              FA_TYPE,   FA_METHOD, FA_STATUS,
              NAME, DATEACTIVE,
              SUPPLIER, SUPPLIER_NAME, SUPPLIER_ADDRESS,
              SUPPLIER_CONTACT, SUPPLIER_PHONE, SUPPLIER_FAX, SUPPLIER_EMAIL,
              VALUE_COST, VALUE_QTY,
              CREATEDATE, EDITDATE, CREATEUSER, EDITUSER,
              PO_NUMBER,
              DEPRE_AGE, DEPRE_START_YEAR, DEPRE_START_MONTH,
              UNIT,
              DEFA_LOCATION,
              INV_RECV_NO, INV_RECV_PARTNO, INV_RECV_LINE)
           VALUES (
              :FA_TYPE, 'SL',  'A',
              :MSTNAME, :OPENDATE,
              :SUPPLIER, :NAME, :ADDRESS1 || ' ' || :ADDRESS2 || ' ' || :ADDRESS3,
              :CONTACT, :PHONE,  :FAX, :EMAIL,
              :COST, :QTY,
              'NOW', 'NOW', :USRID, :USRID,
              :PO_NUMBER,
              5*12, :PYEAR, :PMONTH,
              :MSTUNIT,
              '',
              :NUMBER, :PARTNO, :LINE);
        END
     END
  END /* PSAVE = 1 */
  /* ---------------------------------------------------------------- */
  /* END OF 12 JUN 2007                                               */
  /* ---------------------------------------------------------------- */
  IF (PSAVE = 0) THEN
  BEGIN
     SELECT MIN(FA_TYPE) FROM FA_TYPE INTO :FA_TYPE;
     FOR
        SELECT H.NUMBER, H.OPENDATE, H.SUPPLIER,
               S.NAME, S.ADDRESS1, S.ADDRESS2, S.ADDRESS3,
               S.CONTACT, S.PHONE, S.FAX, S.EMAIL
       FROM INVRECV0 H
       LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = H.SUPPLIER
       WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE
       AND H.STATUS IN ('R','C')
       AND H.ICOST = 'FA'
       INTO
         :NUMBER,
         :OPENDATE,
         :SUPPLIER,
         :NAME,
         :ADDRESS1,
         :ADDRESS2,
         :ADDRESS3,
         :CONTACT,
         :PHONE,
         :FAX,
         :EMAIL
     DO
     BEGIN
       FOR SELECT D.LINE, D.PARTNO,  D.PONUMBER, M.NAME, M.UNITF,
           D.CALC_QTY, D.CALC_COST_FOREX/D.CALC_QTY /*06.01.2006,RECV ASSET USD(RIZAL)*/
           FROM INVRECV1 D
           LEFT JOIN INVMASTER M ON M.PARTNO = D.PARTNO
           WHERE NUMBER = :NUMBER
           AND D.CALC_QTY-D.QTYRET <> 0 /* 17 MARET 2007, KALAU ADA RETURN GAK USAH */
           AND D.DIRECTUSE = 1
       INTO LINE, PARTNO, PO_NUMBER, MSTNAME, MSTUNIT, QTY, COST
       DO
       BEGIN
         IF (NOT EXISTS(SELECT * FROM FA_MASTER WHERE INV_RECV_NO = :NUMBER AND INV_RECV_LINE = :LINE)) THEN
            SUSPEND;
       END
    END
  END /* PSAVE = 0 */
END^


ALTER PROCEDURE FA_RPT_DETAIL(
    PMONTH INTEGER,
    PYEAR INTEGER)
RETURNS (
    PERIOD DATE,
    FA_MASTER_ID INTEGER,
    NAME VARCHAR(80),
    NOTE BLOB SUB_TYPE 1 SEGMENT SIZE 80,
    FA_CODE VARCHAR(40),
    FA_TYPE VARCHAR(8),
    TYPE_NAME VARCHAR(40),
    DEPRE_START_YEAR INTEGER,
    DEPRE_START_MONTH INTEGER,
    DATEACTIVE DATE,
    VALUE_OPEN DOUBLE PRECISION,
    VALUE_QTY DOUBLE PRECISION,
    VALUE_COST DOUBLE PRECISION,
    DEPRE_AGE INTEGER,
    DEPRE_USED INTEGER,
    ASSET_ACCOUNT VARCHAR(20),
    ASSET_DEPT VARCHAR(4),
    ASSET_COST VARCHAR(4),
    ASSET_ACCOUNT_NAME VARCHAR(40),
    DEPRE_MTD DOUBLE PRECISION,
    DEPRE_YTD DOUBLE PRECISION,
    DEPRE_TOTAL DOUBLE PRECISION,
    QTY_ADJUST_MTD DOUBLE PRECISION,
    QTY_ADJUST_YTD DOUBLE PRECISION,
    QTY_ADJUST_TOTAL DOUBLE PRECISION,
    ADJUST_MTD DOUBLE PRECISION,
    ADJUST_YTD DOUBLE PRECISION,
    ADJUST_TOTAL DOUBLE PRECISION,
    ADJUST_DEPRE_MTD DOUBLE PRECISION,
    ADJUST_DEPRE_YTD DOUBLE PRECISION,
    ADJUST_DEPRE_TOTAL DOUBLE PRECISION,
    ADJUST_EXPENSE_MTD DOUBLE PRECISION,
    ADJUST_EXPENSE_YTD DOUBLE PRECISION,
    ADJUST_EXPENSE_TOTAL DOUBLE PRECISION,
    VALUE_BOOK DOUBLE PRECISION)
AS
BEGIN
  IF ((PYEAR = 0) OR (PYEAR IS NULL)) THEN
  BEGIN
     PYEAR = 2009;
     PMONTH = 5;
  END
  PERIOD = '1.'||PMONTH||'.'||PYEAR;
  FOR
    SELECT M.FA_MASTER_ID, M.NAME, M.FA_CODE,
           M.FA_TYPE, T.NAME TYPE_NAME, M.NOTE,
           M.DEPRE_START_YEAR,
           M.DEPRE_START_MONTH,
           M.DATEACTIVE,
           M.VALUE_OPEN,
           M.VALUE_QTY,
           M.VALUE_COST,
           M.DEPRE_AGE,
           T.ASSET_ACCOUNT,
           T.ASSET_DEPT,
           T.ASSET_COST,
           COA.NAME ASSET_ACCOUNT_NAME
    FROM FA_MASTER M
    LEFT JOIN FA_TYPE T ON T.FA_TYPE = M.FA_TYPE
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.ASSET_ACCOUNT
    WHERE  M.DEPRE_START_YEAR * 12 + M.DEPRE_START_MONTH <= :PYEAR*12+:PMONTH
    INTO
      :FA_MASTER_ID,
      :NAME,
      :FA_CODE,
      :FA_TYPE,
      :TYPE_NAME,
      :NOTE,
      :DEPRE_START_YEAR,
      :DEPRE_START_MONTH,
      :DATEACTIVE,
      :VALUE_OPEN,
      :VALUE_QTY,
      :VALUE_COST,
      :DEPRE_AGE,
      :ASSET_ACCOUNT,
      :ASSET_DEPT,
      :ASSET_COST,
      :ASSET_ACCOUNT_NAME
  DO
  BEGIN
    DEPRE_USED = PYEAR*12+PMONTH - (DEPRE_START_YEAR * 12 + DEPRE_START_MONTH) + 1;
    IF (DEPRE_USED > DEPRE_AGE) THEN DEPRE_USED = DEPRE_AGE;

    IF (DEPRE_USED >= 0) THEN
    BEGIN
       DEPRE_MTD = NULL;
       DEPRE_YTD = NULL;
       DEPRE_TOTAL = NULL;
       ADJUST_MTD = NULL;
       ADJUST_YTD = NULL;
       ADJUST_TOTAL = NULL;
       QTY_ADJUST_MTD = NULL;
       QTY_ADJUST_YTD = NULL;
       QTY_ADJUST_TOTAL = NULL;
       /* ----------------------------------------------------------- */
       /* DEPRECIATION                                                */
       /* ----------------------------------------------------------- */
       SELECT SUM(AMOUNT) FROM FA_MASTER_DEPRE
       WHERE FA_MASTER_ID = :FA_MASTER_ID
       AND PYEAR = :PYEAR
       AND PMONTH = :PMONTH
       INTO DEPRE_MTD;
       IF (DEPRE_MTD IS NULL) THEN DEPRE_MTD = 0;

       SELECT SUM(AMOUNT) FROM FA_MASTER_DEPRE
       WHERE FA_MASTER_ID = :FA_MASTER_ID
       AND PYEAR = :PYEAR
       AND PMONTH <= :PMONTH
       INTO DEPRE_YTD;
       IF (DEPRE_YTD IS NULL) THEN DEPRE_YTD = 0;

       SELECT SUM(AMOUNT) FROM FA_MASTER_DEPRE
       WHERE FA_MASTER_ID = :FA_MASTER_ID
       AND PYEAR * 12 + PMONTH <= :PYEAR * 12 + :PMONTH
       INTO DEPRE_TOTAL;
       IF (DEPRE_TOTAL IS NULL) THEN DEPRE_TOTAL = 0;

       /* ----------------------------------------------------------- */
       /* ADJUSTMENT/DISPOSAL                                         */
       /* ----------------------------------------------------------- */
       SELECT SUM(CR), SUM(CR_ACCUM_DEPRE), SUM(CR_EXPENSES), SUM(QTY) FROM FA_MASTER_ADJ
       WHERE FA_MASTER_ID = :FA_MASTER_ID
       AND PYEAR = :PYEAR
       AND PMONTH = :PMONTH
       INTO ADJUST_MTD, ADJUST_DEPRE_MTD, ADJUST_EXPENSE_MTD, QTY_ADJUST_MTD;
       IF (ADJUST_MTD IS NULL) THEN ADJUST_MTD = 0;
       IF (QTY_ADJUST_MTD IS NULL) THEN QTY_ADJUST_MTD = 0;
       IF (ADJUST_DEPRE_MTD IS NULL) THEN ADJUST_DEPRE_MTD = 0; /* 4/19/2011  */
       IF (ADJUST_EXPENSE_MTD IS NULL) THEN ADJUST_EXPENSE_MTD = 0; /* 4/19/2011  */

       SELECT SUM(CR), SUM(CR_ACCUM_DEPRE), SUM(CR_EXPENSES), SUM(QTY) FROM FA_MASTER_ADJ
       WHERE FA_MASTER_ID = :FA_MASTER_ID
       AND PYEAR = :PYEAR
       AND PMONTH <= :PMONTH
       INTO ADJUST_YTD, ADJUST_DEPRE_YTD, ADJUST_EXPENSE_YTD, QTY_ADJUST_YTD;
       IF (ADJUST_YTD IS NULL) THEN ADJUST_YTD = 0;
       IF (QTY_ADJUST_YTD IS NULL) THEN QTY_ADJUST_YTD = 0;
       IF (ADJUST_DEPRE_YTD IS NULL) THEN ADJUST_DEPRE_YTD = 0; /* 4/19/2011  */
       IF (ADJUST_EXPENSE_YTD IS NULL) THEN ADJUST_EXPENSE_YTD = 0; /* 4/19/2011  */

       SELECT SUM(CR), SUM(CR_ACCUM_DEPRE), SUM(CR_EXPENSES), SUM(QTY) FROM FA_MASTER_ADJ
       WHERE FA_MASTER_ID = :FA_MASTER_ID
       AND PYEAR * 12 + PMONTH <= :PYEAR * 12 + :PMONTH
       INTO ADJUST_TOTAL,ADJUST_DEPRE_TOTAL, ADJUST_EXPENSE_TOTAL, QTY_ADJUST_TOTAL;
       IF (ADJUST_TOTAL IS NULL) THEN ADJUST_TOTAL = 0;
       IF (QTY_ADJUST_TOTAL IS NULL) THEN QTY_ADJUST_TOTAL = 0;
       IF (ADJUST_DEPRE_TOTAL IS NULL) THEN ADJUST_DEPRE_TOTAL = 0; /* 4/19/2011  */
       IF (ADJUST_EXPENSE_TOTAL IS NULL) THEN ADJUST_EXPENSE_TOTAL = 0; /* 4/19/2011  */
       /* ----------------------------------------------------------- */





       VALUE_QTY  = VALUE_QTY  + QTY_ADJUST_TOTAL;
       VALUE_BOOK = VALUE_OPEN - DEPRE_TOTAL + ADJUST_TOTAL; /* 4/19/2011 DIUBAH + ADJ TADINYA - */
       SUSPEND;
    END
  END
END^


ALTER PROCEDURE FA_RPT_DISPOSAL(
    PMONTH INTEGER,
    PYEAR INTEGER)
RETURNS (
    PERIOD DATE,
    OPENDATE DATE,
    FA_MASTER_ID INTEGER,
    NAME VARCHAR(80),
    FA_CODE VARCHAR(40),
    FA_TYPE VARCHAR(8),
    TYPE_NAME VARCHAR(40),
    DEPRE_START_YEAR INTEGER,
    DEPRE_START_MONTH INTEGER,
    DATEACTIVE DATE,
    VALUE_OPEN DOUBLE PRECISION,
    VALUE_QTY DOUBLE PRECISION,
    VALUE_COST DOUBLE PRECISION,
    VALUE_ADJUST DOUBLE PRECISION,
    VALUE_ADJUST_QTY DOUBLE PRECISION,
    VALUE_QTY_ENDING DOUBLE PRECISION,
    DEPRE_AGE INTEGER,
    ADJ_ACCOUNT VARCHAR(20),
    ADJ_DEPT VARCHAR(4),
    ADJ_COST VARCHAR(4),
    ADJ_ACCOUNT_NAME VARCHAR(40),
    VALUE_BOOK DOUBLE PRECISION,
    ADJ_VALUE DOUBLE PRECISION,
    ADJ_VALUE_UNITCOST DOUBLE PRECISION,
    ADJ_QTY DOUBLE PRECISION)
AS
BEGIN
  IF ((PYEAR = 0) OR (PYEAR IS NULL)) THEN
  BEGIN
     PYEAR = 2008;
     PMONTH = 10;
  END
  PERIOD = '1.'||PMONTH||'.'||PYEAR;
  FOR
    SELECT M.FA_MASTER_ID, M.NAME, M.FA_CODE,
           M.FA_TYPE, T.NAME TYPE_NAME, 
           M.DEPRE_START_YEAR,
           M.DEPRE_START_MONTH,
           M.DATEACTIVE,
           M.VALUE_OPEN,
           M.VALUE_QTY,
           M.VALUE_COST,
           M.VALUE_BOOK,
           M.DEPRE_AGE,
           A.GL_ACCOUNT,
           A.GL_DEPT,
           A.GL_COST,
           COA.NAME ASSET_ACCOUNT_NAME,
           A.DB-A.CR,
           A.QTY,
           A.OPENDATE
    FROM FA_MASTER_ADJ A
    LEFT JOIN FA_MASTER M ON M.FA_MASTER_ID = A.FA_MASTER_ID
    LEFT JOIN FA_TYPE T ON T.FA_TYPE = M.FA_TYPE
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.ASSET_ACCOUNT
    WHERE A.PYEAR =:PYEAR
    AND A.PMONTH = :PMONTH
    INTO
      FA_MASTER_ID,
      NAME,
      FA_CODE,
      FA_TYPE,
      TYPE_NAME,
      DEPRE_START_YEAR,
      DEPRE_START_MONTH,
      DATEACTIVE,
      VALUE_OPEN,
      VALUE_QTY,
      VALUE_COST,
      VALUE_BOOK,
      DEPRE_AGE,
      ADJ_ACCOUNT,
      ADJ_DEPT,
      ADJ_COST,
      ADJ_ACCOUNT_NAME,
      ADJ_VALUE,
      ADJ_QTY,
      OPENDATE
  DO
  BEGIN
    IF (ADJ_QTY <> 0) THEN ADJ_VALUE_UNITCOST = ADJ_VALUE/ADJ_QTY;
    ELSE ADJ_VALUE_UNITCOST = 0;
    
    SELECT SUM(A.DB-A.CR), SUM(A.QTY) 
    FROM FA_MASTER_ADJ A
    WHERE A.FA_MASTER_ID = :FA_MASTER_ID
    AND (A.PYEAR*12+A.PMONTH) <= (12*:PYEAR + :PMONTH)
    INTO VALUE_ADJUST, VALUE_ADJUST_QTY;
    
    IF (VALUE_ADJUST IS NULL) THEN
    BEGIN
       VALUE_ADJUST = 0;
       VALUE_ADJUST_QTY = 0;
    END
    VALUE_QTY_ENDING = VALUE_QTY - VALUE_ADJUST_QTY;
    SUSPEND;
  END
END^


ALTER PROCEDURE FA_RPT_YEARLY_DEPRE(
    PYEAR INTEGER)
RETURNS (
    FA_TYPE VARCHAR(8),
    NAME VARCHAR(40),
    M01 DOUBLE PRECISION,
    M02 DOUBLE PRECISION,
    M03 DOUBLE PRECISION,
    M04 DOUBLE PRECISION,
    M05 DOUBLE PRECISION,
    M06 DOUBLE PRECISION,
    M07 DOUBLE PRECISION,
    M08 DOUBLE PRECISION,
    M09 DOUBLE PRECISION,
    M10 DOUBLE PRECISION,
    M11 DOUBLE PRECISION,
    M12 DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION)
AS
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE AMT DOUBLE PRECISION;
BEGIN
  FOR SELECT FA_TYPE, NAME
      FROM FA_TYPE
  INTO FA_TYPE, NAME
  DO
  BEGIN
    M = 1;
    TOTAL = 0;
    WHILE (M <= 12) DO
    BEGIN
       SELECT SUM(D.AMOUNT)
       FROM FA_MASTER_DEPRE D
       LEFT JOIN FA_MASTER M ON M.FA_MASTER_ID = D.FA_MASTER_ID
       WHERE D.PYEAR = :PYEAR
       AND D.PMONTH = :M
       AND M.FA_TYPE = :FA_TYPE
       INTO AMT;
       
       IF (AMT IS NULL) THEN AMT = 0;
       TOTAL = TOTAL + AMT;
       IF (M = 1) THEN M01 = AMT;
       ELSE IF (M = 2) THEN M02 = AMT;
       ELSE IF (M = 3) THEN M03 = AMT;
       ELSE IF (M = 4) THEN M04 = AMT;
       ELSE IF (M = 5) THEN M05 = AMT;
       ELSE IF (M = 6) THEN M06 = AMT;
       ELSE IF (M = 7) THEN M07 = AMT;
       ELSE IF (M = 8) THEN M08 = AMT;
       ELSE IF (M = 9) THEN M09 = AMT;
       ELSE IF (M =10) THEN M10 = AMT;
       ELSE IF (M =11) THEN M11 = AMT;
       ELSE IF (M =12) THEN M12 = AMT;
       M = M + 1;
    END
    SUSPEND;
  END
END^


ALTER PROCEDURE FA_RPT_YEARLY_NEW(
    PYEAR INTEGER)
RETURNS (
    FA_TYPE VARCHAR(8),
    NAME VARCHAR(40),
    M01 DOUBLE PRECISION,
