       ELSE IF (M = 7) THEN M07 = AMT;
       ELSE IF (M = 8) THEN M08 = AMT;
       ELSE IF (M = 9) THEN M09 = AMT;
       ELSE IF (M =10) THEN M10 = AMT;
       ELSE IF (M =11) THEN M11 = AMT;
       ELSE IF (M =12) THEN M12 = AMT;
       M = M + 1;
    END
    SUSPEND;
  END
END^


ALTER PROCEDURE GLACC_CHECK_EARNING(
    RYEAR INTEGER,
    RMONTH INTEGER,
    NMONTH INTEGER,
    PSAVE INTEGER)
RETURNS (
    PYEAR INTEGER,
    PMONTH INTEGER,
    MTD_CURRENT DOUBLE PRECISION,
    YTD_CURRENT DOUBLE PRECISION,
    RETAINED DOUBLE PRECISION)
AS
DECLARE VARIABLE AC_CURR VARCHAR(20);
DECLARE VARIABLE AC_RET VARCHAR(20);
DECLARE VARIABLE DEFA_DEPT VARCHAR(4);
DECLARE VARIABLE DEFA_COST VARCHAR(4);
DECLARE VARIABLE COST VARCHAR(4);
DECLARE VARIABLE DEPT VARCHAR(4);
BEGIN
  IF ((RYEAR IS NULL) OR (RYEAR = 0)) THEN
  BEGIN
     RYEAR = 2005;
     RMONTH = 1;
     NMONTH = 14;
     PSAVE = 1;
  END
  SELECT GLCUREARN, GLRETEARN, GLCUREARN_COST, GL_DEFAULT_DEPT
  FROM SYSPARAM
  INTO AC_CURR, AC_RET, DEFA_COST,DEFA_DEPT;
  PYEAR = RYEAR;
  PMONTH = RMONTH;
  YTD_CURRENT = 0;

  WHILE (NMONTH >= 0) DO
  BEGIN
     SELECT SUM(CR-DB) FROM GLACC
     WHERE PYEAR = :PYEAR
     AND PMONTH = :PMONTH
     AND ACCOUNT = :AC_CURR
     INTO MTD_CURRENT;

     IF (MTD_CURRENT IS NULL) THEN MTD_CURRENT = 0;
     YTD_CURRENT = YTD_CURRENT + MTD_CURRENT;

     SELECT SUM(ENDING) FROM GLACC
     WHERE PYEAR = :PYEAR
     AND PMONTH = :PMONTH
     AND ACCOUNT = :AC_RET
     INTO RETAINED;

     IF (RETAINED IS NULL) THEN RETAINED = 0;

     SUSPEND;
     PMONTH = PMONTH + 1;
     IF (PMONTH > 12) THEN
     BEGIN
        PMONTH = 1;
        PYEAR = PYEAR + 1;
        YTD_CURRENT = 0;
     END
     NMONTH = NMONTH - 1;
  END
  IF (PSAVE = 1) THEN
  BEGIN
     FOR SELECT DEPART, COST, ENDING FROM GLACC
     WHERE PYEAR = :RYEAR
     AND PMONTH = 1
     AND ACCOUNT = :AC_RET
     INTO DEPT, COST, RETAINED
     DO BEGIN
        UPDATE GLACC SET OPENING = :RETAINED
        WHERE PYEAR = :RYEAR
        AND PMONTH > 1
        AND ACCOUNT = :AC_RET
        AND DEPART = :DEPT
        AND COST = :COST;
     END
  END
END^


ALTER PROCEDURE GLACC_CHECK_OPENING(
    PYEAR INTEGER,
    PMONTH INTEGER,
    PSAVE INTEGER)
RETURNS (
    ACCOUNT VARCHAR(20),
    NAME VARCHAR(40),
    DEPART VARCHAR(4),
    COST VARCHAR(4),
    OPENING_THISMONTH DOUBLE PRECISION,
    ENDING_LASTMONTH DOUBLE PRECISION,
    DELTA DOUBLE PRECISION,
    TOTAL_DELTA DOUBLE PRECISION)
AS
DECLARE VARIABLE LYEAR INTEGER;
DECLARE VARIABLE LMONTH INTEGER;
DECLARE VARIABLE READONLY INTEGER;
DECLARE VARIABLE EARNING_CUR VARCHAR(20);
DECLARE VARIABLE EARNING_RET VARCHAR(20);
DECLARE VARIABLE TOTAL DOUBLE PRECISION;
DECLARE VARIABLE PRIOR DOUBLE PRECISION;
DECLARE VARIABLE FREADONLY INTEGER;
BEGIN
  IF (PYEAR IS NULL) THEN
  BEGIN
     PYEAR = 2005;
     PMONTH = 7;
     PSAVE = 0;
  END
  LMONTH = PMONTH-1;
  IF (LMONTH <1) THEN
  BEGIN
     LMONTH = 12;
     LYEAR  = PYEAR -1;
  END
  ELSE LYEAR = PYEAR;
  TOTAL_DELTA = 0;
  SELECT GLCUREARN, GLRETEARN FROM SYSPARAM WHERE ID = 1 INTO EARNING_CUR, EARNING_RET;
  FOR
    SELECT A.ACCOUNT, COA.NAME, A.DEPART, A.COST, A.ENDING
    FROM GLACC A
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = A.ACCOUNT
    WHERE A.PYEAR = :LYEAR
    AND A.PMONTH = :LMONTH
    AND COA.ACCTYPE IN ('A','P')
    AND COA.HEADER = 'D'
    INTO
      :ACCOUNT,
      :NAME,
      :DEPART,
      :COST,
      :ENDING_LASTMONTH
  DO
  BEGIN
    OPENING_THISMONTH = NULL;
    IF ((ACCOUNT <> EARNING_CUR) AND (ACCOUNT <> EARNING_RET)) THEN
    BEGIN
       SELECT OPENING FROM GLACC WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
       AND ACCOUNT = :ACCOUNT
       AND DEPART = :DEPART
       AND COST = :COST
       INTO OPENING_THISMONTH;

       DELTA = OPENING_THISMONTH-ENDING_LASTMONTH;
       IF ((DELTA <> 0) OR (DELTA IS NULL)) THEN
       BEGIN

          TOTAL_DELTA = TOTAL_DELTA + DELTA;
          IF (PSAVE = 1) THEN
          BEGIN
             /* ---------------------------------------------------------------- */
             /* 11 JULY 2007, CHECK ACCOUNT IF EXISTS OR NOT                     */
             /* ---------------------------------------------------------------- */
             IF (NOT EXISTS(SELECT * FROM GLACC WHERE PYEAR=:PYEAR AND PMONTH=:PMONTH
                            AND ACCOUNT = :ACCOUNT AND DEPART=:DEPART AND COST=:COST)) THEN
             BEGIN
                /*IF (DELTA IS NULL) THEN */
                BEGIN
                   INSERT INTO GLACC (PYEAR, PMONTH, ACCOUNT, DEPART, COST, OPENING, DB, CR)
                   VALUES (:PYEAR, :PMONTH, :ACCOUNT, :DEPART, :COST, 0,0,0);
                END
             END /* 17 JULY 2007 */
             /* -------------------------------------------------------------------- */
             /* 2 APRIL 2010                                                         */
             /* OPEN FLAG READONLY                                                   */
             /* -------------------------------------------------------------------- */
             SELECT READONLY FROM GLACC
             WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH AND ACCOUNT = :ACCOUNT AND DEPART = :DEPART AND COST = :COST
             INTO FREADONLY;

             IF (FREADONLY <> 0) THEN
                UPDATE GLACC SET READONLY = 0
                WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH AND ACCOUNT = :ACCOUNT AND DEPART = :DEPART AND COST = :COST;
             /* -------------------------------------------------------------------- */
             /* END OF OPEN FLAG READ ONLY                                           */
             /* -------------------------------------------------------------------- */

             UPDATE GLACC SET OPENING = :ENDING_LASTMONTH
             WHERE PYEAR = :PYEAR
             AND PMONTH = :PMONTH
             AND ACCOUNT = :ACCOUNT
             AND DEPART = :DEPART
             AND COST = :COST;

             /* -------------------------------------------------------------------- */
             /* 2 APRIL 2010                                                         */
             /* OPEN FLAG READONLY                                                   */
             /* -------------------------------------------------------------------- */
             IF (FREADONLY <> 0) THEN
                UPDATE GLACC SET READONLY = :FREADONLY
                WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH AND ACCOUNT = :ACCOUNT AND DEPART = :DEPART AND COST = :COST;
             /* -------------------------------------------------------------------- */
             /* END OF OPEN FLAG READ ONLY                                           */
             /* -------------------------------------------------------------------- */
          END
          ELSE SUSPEND;
       END
     END
     ELSE
     IF (ACCOUNT = EARNING_CUR) THEN
     BEGIN
        /* BUAT CURRENT EARNING */
        IF (NOT EXISTS(SELECT * FROM GLACC WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
                        AND ACCOUNT = :ACCOUNT AND DEPART = :DEPART AND COST = :COST)) THEN
        BEGIN
           INSERT INTO GLACC (PYEAR, PMONTH, ACCOUNT, DEPART, COST, OPENING, DB, CR)
           VALUES (:PYEAR, :PMONTH, :ACCOUNT, :DEPART, :COST, 0,0,0);
        END
        /* BUAT RETAINED EARNING TAHUN LALU */
        IF (NOT EXISTS(SELECT * FROM GLACC WHERE PYEAR = :LYEAR AND PMONTH = :LMONTH
                        AND ACCOUNT = :EARNING_RET AND DEPART = :DEPART AND COST = :COST)) THEN
        BEGIN
           INSERT INTO GLACC (PYEAR, PMONTH, ACCOUNT, DEPART, COST, OPENING, DB, CR)
           VALUES (:LYEAR, :LMONTH, :EARNING_RET, :DEPART, :COST, 0,0,0);
        END
        /* BUAT RETAINED EARNING TAHIN INI */
        IF (NOT EXISTS(SELECT * FROM GLACC WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
                        AND ACCOUNT = :EARNING_RET AND DEPART = :DEPART AND COST = :COST)) THEN
        BEGIN
           INSERT INTO GLACC (PYEAR, PMONTH, ACCOUNT, DEPART, COST, OPENING, DB, CR)
           VALUES (:PYEAR, :PMONTH, :EARNING_RET, :DEPART, :COST, 0,0,0);
        END
        /* SET OPENING CURRENT EARNING MENJADI NOL, UNTUK PERIODE = 1 */
        IF (PMONTH = 1) THEN
        BEGIN
           TOTAL = 0;
        END
        ELSE
        BEGIN
           SELECT SUM(CR-DB) FROM GLACC
           WHERE PYEAR = :PYEAR
           AND PMONTH <= :PMONTH
           AND ACCOUNT = :ACCOUNT
           AND DEPART = :DEPART
           AND COST = :COST
           INTO TOTAL;
           IF (TOTAL IS NULL) THEN TOTAL = 0;
        END
        /* -------------------------------------------------------------------- */
        /* 2 APRIL 2010                                                         */
        /* OPEN FLAG READONLY                                                   */
        /* -------------------------------------------------------------------- */
        SELECT READONLY FROM GLACC
        WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH AND ACCOUNT = :ACCOUNT AND DEPART = :DEPART AND COST = :COST
        INTO FREADONLY;

        IF (FREADONLY <> 0) THEN
           UPDATE GLACC SET READONLY = 0
           WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH AND ACCOUNT = :ACCOUNT AND DEPART = :DEPART AND COST = :COST;
        /* -------------------------------------------------------------------- */
        /* END OF OPEN FLAG READ ONLY                                           */
        /* -------------------------------------------------------------------- */

        UPDATE GLACC SET OPENING = :TOTAL
        WHERE PYEAR = :PYEAR
        AND PMONTH = :PMONTH
        AND ACCOUNT = :ACCOUNT
        AND DEPART = :DEPART
        AND COST = :COST;
        /* -------------------------------------------------------------------- */
        /* 2 APRIL 2010                                                         */
        /* OPEN FLAG READONLY                                                   */
        /* -------------------------------------------------------------------- */
        IF (FREADONLY <> 0) THEN
           UPDATE GLACC SET READONLY = :FREADONLY
           WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH AND ACCOUNT = :ACCOUNT AND DEPART = :DEPART AND COST = :COST;
        /* -------------------------------------------------------------------- */
        /* END OF OPEN FLAG READ ONLY                                           */
        /* -------------------------------------------------------------------- */
     END
     ELSE
     IF (ACCOUNT = EARNING_RET) THEN
     BEGIN
        /* BUAT RETAINED EARNING */
        IF (NOT EXISTS(SELECT * FROM GLACC WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
                        AND ACCOUNT = :ACCOUNT AND DEPART = :DEPART AND COST = :COST)) THEN
        BEGIN
           INSERT INTO GLACC (PYEAR, PMONTH, ACCOUNT, DEPART, COST, OPENING, DB, CR)
           VALUES (:PYEAR, :PMONTH, :ACCOUNT, :DEPART, :COST, 0,0,0);
        END
        /* ---------------------------------------------------------------- */
        /* JIKA PERIODE = 1, HITUNG KEUNTUNGAN TAHUN LALU TAMBAHKAN         */
        /* ---------------------------------------------------------------- */
        TOTAL = 0;
        PRIOR = 0;
        IF (PMONTH = 1) THEN
        BEGIN
           SELECT SUM(A.CR-A.DB) FROM GLACC A
           WHERE A.PYEAR = :LYEAR
           AND (A.ACCOUNT = :EARNING_CUR)
           AND A.DEPART = :DEPART
           AND A.COST = :COST
           INTO :TOTAL;
        END

        SELECT SUM(A.ENDING) FROM GLACC A
        WHERE A.PYEAR = :LYEAR
        AND A.PMONTH = :LMONTH
        AND A.ACCOUNT = :EARNING_RET
        AND A.DEPART = :DEPART
        AND A.COST = :COST
        INTO :PRIOR;

        IF (PRIOR IS NULL) THEN PRIOR = 0;
        IF (TOTAL IS NULL) THEN TOTAL = 0;

        /* -------------------------------------------------------------------- */
        /* 2 APRIL 2010                                                         */
        /* OPEN FLAG READONLY                                                   */
        /* -------------------------------------------------------------------- */
        SELECT READONLY FROM GLACC
        WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH AND ACCOUNT = :ACCOUNT AND DEPART = :DEPART AND COST = :COST
        INTO FREADONLY;

        IF (FREADONLY <> 0) THEN
           UPDATE GLACC SET READONLY = 0
           WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH AND ACCOUNT = :ACCOUNT AND DEPART = :DEPART AND COST = :COST;
        /* -------------------------------------------------------------------- */
        /* END OF OPEN FLAG READ ONLY                                           */
        /* -------------------------------------------------------------------- */

        UPDATE GLACC SET OPENING = :PRIOR+:TOTAL
        WHERE PYEAR = :PYEAR
        AND PMONTH = :PMONTH
        AND ACCOUNT = :ACCOUNT
        AND DEPART = :DEPART
        AND COST = :COST;
        
        /* -------------------------------------------------------------------- */
        /* 2 APRIL 2010                                                         */
        /* OPEN FLAG READONLY                                                   */
        /* -------------------------------------------------------------------- */
        IF (FREADONLY <> 0) THEN
           UPDATE GLACC SET READONLY = :FREADONLY
           WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH AND ACCOUNT = :ACCOUNT AND DEPART = :DEPART AND COST = :COST;
        /* -------------------------------------------------------------------- */
        /* END OF OPEN FLAG READ ONLY                                           */
        /* -------------------------------------------------------------------- */
     END
  END
END^


ALTER PROCEDURE GLACC_CHECK_OPENING_1YEAR(
    PYEAR INTEGER,
    PSAVE INTEGER)
RETURNS (
    RYEAR INTEGER,
    RMONTH INTEGER,
    ACCOUNT VARCHAR(20),
    NAME VARCHAR(40),
    DEPART VARCHAR(4),
    COST VARCHAR(4),
    OPENING_THISMONTH DOUBLE PRECISION,
    ENDING_LASTMONTH DOUBLE PRECISION,
    DELTA DOUBLE PRECISION,
    TOTAL_DELTA DOUBLE PRECISION)
AS
DECLARE VARIABLE M INTEGER;
BEGIN
  IF ((PYEAR = 0) OR (PYEAR IS NULL)) THEN
  BEGIN
     PYEAR = 2005;
     PSAVE = 0;
  END
  M = 1;
  RYEAR = PYEAR;
  WHILE (M <= 12) DO
  BEGIN
    RMONTH = M;
    FOR SELECT ACCOUNT, NAME, DEPART, COST, OPENING_THISMONTH,
               ENDING_LASTMONTH, DELTA, TOTAL_DELTA
        FROM GLACC_CHECK_OPENING(:PYEAR, :M, :PSAVE)
    INTO
      :ACCOUNT,
      :NAME,
      :DEPART,
      :COST,
      :OPENING_THISMONTH,
      :ENDING_LASTMONTH,
      :DELTA,
      :TOTAL_DELTA
    DO
    BEGIN
      SUSPEND;
    END
    M = M + 1;
  END
END^


ALTER PROCEDURE GLACC_JOURNAL_BY_SOURCE(
    PYEAR INTEGER,
    PMONTH INTEGER,
    PACCOUNT VARCHAR(20),
    PDEPT VARCHAR(4),
    PCOST VARCHAR(4))
RETURNS (
    ACCOUNT VARCHAR(20),
    NAME VARCHAR(40),
    DEPT VARCHAR(4),
    COST VARCHAR(4),
    REMARK VARCHAR(40),
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    OPENING NUMERIC(15,4),
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    MUTATION DOUBLE PRECISION,
    ENDING DOUBLE PRECISION)
AS
DECLARE VARIABLE ACCTYPE VARCHAR(1);
BEGIN
  IF ((PYEAR = 0) OR (PYEAR IS NULL)) THEN
  BEGIN
     PYEAR = 2005;
     PMONTH = 8;
     PACCOUNT = '112-470';
     PDEPT = '11HR';
     PCOST = '010';
  END
  SELECT A.ACCOUNT, COA.NAME, COA.ACCTYPE, A.DEPART, A.COST, A.OPENING
  FROM GLACC A
  LEFT JOIN GLCOA COA ON COA.ACCOUNT = A.ACCOUNT
  WHERE A.PYEAR = :PYEAR
  AND A.PMONTH = :PMONTH
  AND A.ACCOUNT = :PACCOUNT
  AND A.DEPART = :PDEPT
  AND A.COST = :PCOST
  INTO :ACCOUNT, :NAME, :ACCTYPE, :DEPT, :COST, :OPENING;

  FOR SELECT J.APPLICATION, J.SOURCE, SUM(J.DB), SUM(J.CR)
      FROM GLJUR J
      LEFT JOIN GLTRANS T ON T.PYEAR = J.PYEAR AND
           T.PMONTH = J.PMONTH AND T.TRANSNO = J.TRANSNO
      WHERE J.PYEAR = :PYEAR
      AND J.PMONTH = :PMONTH
      AND J.ACCOUNT = :PACCOUNT
      AND J.DEPART = :PDEPT
      AND J.COST = :PCOST
      AND T.STATUS = 'P'
      GROUP BY J.APPLICATION, J.SOURCE
  INTO APPLICATION, SOURCE, DB, CR
  DO
  BEGIN
    SELECT NAME FROM GLIMPORT
    WHERE APPLICATION = :APPLICATION AND SOURCE = :SOURCE
    INTO REMARK;
    IF (ACCTYPE IN ('A','C')) THEN
    BEGIN
       MUTATION=DB-CR;
       ENDING = OPENING + DB-CR;
    END
    ELSE
    BEGIN
       MUTATION=-DB+CR;
       ENDING = OPENING - DB+CR;
    END
    SUSPEND;
    OPENING = ENDING;
  END
END^


ALTER PROCEDURE GLCOA_USED_INFO
RETURNS (
    ACCOUNT VARCHAR(20),
    DEPT VARCHAR(4),
    COST VARCHAR(4),
    NAME VARCHAR(40),
    SETUP_TITLE VARCHAR(40),
    SETUP_INFO VARCHAR(16),
    SETUP_CODE VARCHAR(8),
    SETUP_NAME VARCHAR(40),
    SETUP_TEXT VARCHAR(40),
    SUBMODULE VARCHAR(40),
    GROUPINFO VARCHAR(40))
AS
DECLARE VARIABLE FLAG_PRODUCTION INTEGER;
BEGIN
  /* ---------------------------------------------------------------- */
  /* INVENTORY ON HAND                                                */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Inventory On Hand';
  SETUP_INFO  = 'INVGROUP';
  SUBMODULE   = 'Inventory';
  GROUPINFO   = 'On Hand Stock';
  FOR SELECT G.ACCINV, G.DEPART_INV, G.GL_COST_INV,
             COA.NAME, G.GRP, G.NAME, T.NAME
      FROM INVGROUP G
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = G.ACCINV
      LEFT JOIN INVTYPE T ON T.ITYPE = G.GRPTYPE
  INTO ACCOUNT, DEPT, COST, NAME, SETUP_CODE, SETUP_NAME, SETUP_TEXT
  DO
  BEGIN
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* COST ALLOCATION                                                  */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Cost & Expenses Allocation';
  SETUP_INFO  = 'INVGROUPACC';
  SUBMODULE   = 'Inventory';
  FOR SELECT A.GL_ACCOUNT, A.GL_DEPT, A.GL_COST,
             COA.NAME, A.ICOST, C.NAME, T.NAME,
             C.FLAG_PRODUCTION
      FROM INVGROUPACC A
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = A.GL_ACCOUNT
      LEFT JOIN INVGROUP G ON G.GRP = A.GRP
      LEFT JOIN INVCOST C ON A.ICOST = C.ICOST
      LEFT JOIN INVTYPE T ON T.ITYPE = G.GRPTYPE
  INTO ACCOUNT, DEPT, COST, NAME, SETUP_CODE, SETUP_NAME, SETUP_TEXT, FLAG_PRODUCTION
  DO
  BEGIN
    IF (FLAG_PRODUCTION = 1) THEN GROUPINFO = 'Cost';
    ELSE GROUPINFO = 'Expences';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* HOUSE USE CREDIT TO COST                                         */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'House Use Credit To Cost';
  SETUP_INFO  = 'INVCOST';
  SUBMODULE   = 'Inventory';
  GROUPINFO   = 'CR2C-House Use';
  FOR SELECT C.MEAL_FOOD_AC, C.MEAL_FOOD_DEPT, C.MEAL_FOOD_COST,
             COA.NAME, C.ICOST, C.NAME
      FROM INVCOST C
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = C.MEAL_FOOD_AC
  INTO ACCOUNT, DEPT, COST, NAME, SETUP_CODE, SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = 'Food';
    SUSPEND;
  END

  SETUP_TITLE = 'House Use Credit To Cost';
  SETUP_INFO  = 'INVCOST';
  SUBMODULE   = 'Inventory';
  GROUPINFO   = 'CR2C-House Use';
  FOR SELECT C.MEAL_BEV_AC, C.MEAL_BEV_DEPT, C.MEAL_BEV_COST,
             COA.NAME, C.ICOST, C.NAME
      FROM INVCOST C
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = C.MEAL_BEV_AC
  INTO ACCOUNT, DEPT, COST, NAME, SETUP_CODE, SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = 'Beverage';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  /* FIXED ASSET                                                      */
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Fixed Asset';
  SETUP_INFO  = 'FA_TYPE';
  SUBMODULE   = 'Fixed Asset';
  GROUPINFO   = 'Asset';
  FOR SELECT T.ASSET_ACCOUNT, T.ASSET_DEPT, T.ASSET_COST,
             COA.NAME, T.FA_TYPE, T.NAME
      FROM FA_TYPE T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.ASSET_ACCOUNT
  INTO ACCOUNT, DEPT, COST, NAME, SETUP_CODE, SETUP_NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
  /* ---------------------------------------------------------------- */
  SETUP_TITLE = 'Fixed Asset Depreciation';
