  SUBMODULE   = 'Fixed Asset';
  GROUPINFO   = 'Depreciation';
  FOR SELECT T.DEPRE_ACCOUNT, T.DEPRE_DEPT, T.DEPRE_COST,
             COA.NAME, T.FA_TYPE, T.NAME
