  SETUP_INFO  = 'FA_TYPE';
  SUBMODULE   = 'Fixed Asset';
  GROUPINFO   = 'Acc. Depreciation';
  FOR SELECT T.ACC_DEPRE_ACCOUNT, T.ACC_DEPRE_DEPT, T.ACC_DEPRE_COST,
