  SETUP_NAME  = 'System Parameter';
  FOR SELECT T.AP_COMMISSION_GL_ACCOUNT, T.AP_COMMISSION_GL_DEPT, T.AP_COMMISSION_GL_COST,
             COA.NAME
      FROM SYSPARAM T
      LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.DISBURSMENT_GL_ACCOUNT
  INTO ACCOUNT, DEPT, COST, NAME
  DO
  BEGIN
    SETUP_TEXT = '';
    SUSPEND;
  END
END^


ALTER PROCEDURE GLTRANS_RENUMBER(
    PYEAR INTEGER,
    PMONTH INTEGER)
AS
DECLARE VARIABLE XTRANSNO INTEGER;
DECLARE VARIABLE TRANSNO INTEGER;
DECLARE VARIABLE X INTEGER;
BEGIN
  IF ((PYEAR IS NULL) OR (PYEAR = 0)) THEN
  BEGIN
     PYEAR = 2006;
     PMONTH = 2;
  END
  XTRANSNO = -1;
  FOR SELECT TRANSNO FROM GLTRANS
      WHERE PYEAR = :PYEAR
      AND PMONTH = :PMONTH
      ORDER BY TRANSDATE
      INTO TRANSNO
  DO
  BEGIN
    UPDATE GLTRANS SET TRANSNO =:XTRANSNO
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND TRANSNO = :TRANSNO;
    XTRANSNO = XTRANSNO -1;
  END

  UPDATE GLTRANS SET TRANSNO =-TRANSNO
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH;
END^


ALTER PROCEDURE GL_ACCOUNT_TOTAL(
    PACCOUNT VARCHAR(20))
RETURNS (
    ACCOUNT VARCHAR(20))
AS
declare variable len integer;
declare variable s varchar(20);
declare variable Tail integer;
declare variable SysPicture VARCHAR(40);
begin

  SELECT gl_account_picture FROM sysparam INTO :SysPicture;
  if ((SysPicture <> '') and (strlen(SysPicture) >= 5)) then
  begin
    ACCOUNT = '';
    len = strlen(PACCOUNT);
    tail = 1;
    while (len >= 1) do
    begin
      s = substr(PAccount, len, len);
      if ((s = '0') and tail = 1) then ACCOUNT = '9' || ACCOUNT;
      else ACCOUNT =  s || ACCOUNT;
      if (not(s in ('.', '-'))) then
         if (S between '1' and '9') then TAIL = 0;
      len = len - 1;
    end
  end
  else
     Account = PAccount || '999';
  SUSPEND;
end^


ALTER PROCEDURE GL_AP_RECONCILE_BANK_ACCOUNT(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    TRANSNO INTEGER,
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    ACCOUNT VARCHAR(20),
    DEPART VARCHAR(4),
    COST VARCHAR(4),
    NOTE VARCHAR(40),
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    SOURCENUMBER INTEGER,
    BALANCE DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION)
AS
BEGIN
  IF (PYEAR IS NULL) THEN
  BEGIN
     PYEAR = 2005;
     PMONTH = 7;
  END
  FOR SELECT GL_ACCOUNT_APPREPARE, GL_DEPT_APPREPARE, GL_COST_APPREPARE
      FROM sysbank
      GROUP BY GL_ACCOUNT_APPREPARE, GL_DEPT_APPREPARE, GL_COST_APPREPARE
      INTO ACCOUNT, DEPART,COST
  DO
  BEGIN
    FOR SELECT TRANSNO,  NOTE, DB, CR, SOURCENUMBER, APPLICATION, SOURCE
        FROM GLJUR
        WHERE PYEAR = :PYEAR
            AND PMONTH = :PMONTH
            AND ACCOUNT = :ACCOUNT
            AND DEPART = :DEPART
            AND COST = :COST
            INTO :TRANSNO, :NOTE, :DB, :CR, :SOURCENUMBER, APPLICATION, SOURCE
     DO
     BEGIN
       BALANCE = DB - CR;
       TOTAL = DB + CR;
       SUSPEND;
     END
  END
END^


ALTER PROCEDURE GL_AR_RECONCILE(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    TRANSNO INTEGER,
    ACCOUNT VARCHAR(20),
    DEPART VARCHAR(4),
    COST VARCHAR(4),
    NOTE VARCHAR(40),
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    SOURCENUMBER INTEGER,
    BB_TRANSNO INTEGER)
AS
BEGIN
  IF (PYEAR IS NULL) THEN
  BEGIN
     PYEAR = 2005;
     PMONTH = 7;
  END
  FOR
    SELECT TRANSNO, ACCOUNT, DEPART,COST, NOTE, DB, CR, SOURCENUMBER
    FROM GLJUR
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND APPLICATION = 'AR'
    AND SOURCE = 'CASH'
    AND DB <> 0
    PLAN (GLJUR INDEX (GLJUR_IDX_APPLICATION))
    INTO
      :TRANSNO,
      :ACCOUNT,
      :DEPART,
      :COST,
      :NOTE,
      :DB,
      :CR,
      :SOURCENUMBER
  DO
  BEGIN
    BB_TRANSNO = NULL;
    SELECT TRANSNO FROM GLJUR
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND APPLICATION = 'AR'
    AND SOURCE = 'REC'
    AND ACCOUNT = :ACCOUNT
    AND DEPART = :DEPART
    AND COST = :COST
    AND SOURCENUMBER = :SOURCENUMBER
    INTO BB_TRANSNO;
    SUSPEND;
  END
END^


ALTER PROCEDURE GL_AR_RECONCILE_BANK_ACCOUNT(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    TRANSNO INTEGER,
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    ACCOUNT VARCHAR(20),
    DEPART VARCHAR(4),
    COST VARCHAR(4),
    NOTE VARCHAR(40),
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    SOURCENUMBER INTEGER,
    BALANCE DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION)
AS
BEGIN
  IF (PYEAR IS NULL) THEN
  BEGIN
     PYEAR = 2005;
     PMONTH = 7;
  END
  FOR SELECT GL_ACCOUNT_ARPREPARE, GL_DEPT_ARPREPARE, GL_COST_ARPREPARE
      FROM sysbank
      GROUP BY GL_ACCOUNT_ARPREPARE, GL_DEPT_ARPREPARE, GL_COST_ARPREPARE
      INTO ACCOUNT, DEPART,COST
  DO
  BEGIN
    FOR SELECT TRANSNO,  NOTE, DB, CR, SOURCENUMBER, APPLICATION, SOURCE
        FROM GLJUR
        WHERE PYEAR = :PYEAR
            AND PMONTH = :PMONTH
            AND ACCOUNT = :ACCOUNT
            AND DEPART = :DEPART
            AND COST = :COST
            INTO :TRANSNO, :NOTE, :DB, :CR, :SOURCENUMBER, APPLICATION, SOURCE
     DO
     BEGIN
       BALANCE = DB - CR;
       TOTAL = DB + CR;
       SUSPEND;
     END
  END
END^


ALTER PROCEDURE GL_CFLOW(
    PDATE DATE)
RETURNS (
    INFO VARCHAR(8),
    DATA VARCHAR(8),
    TEXT VARCHAR(40),
    WK1 DOUBLE PRECISION,
    WK2 DOUBLE PRECISION,
    WK3 DOUBLE PRECISION,
    WK4 DOUBLE PRECISION,
    WK5 DOUBLE PRECISION,
    WK6 DOUBLE PRECISION,
    WK7 DOUBLE PRECISION,
    WK8 DOUBLE PRECISION)
AS
declare variable V1 DOUBLE PRECISION;
declare variable V2 DOUBLE PRECISION;
declare variable V3 DOUBLE PRECISION;
declare variable V4 DOUBLE PRECISION;
declare variable V5 DOUBLE PRECISION;
declare variable V6 DOUBLE PRECISION;
declare variable V7 DOUBLE PRECISION;
declare variable V8 DOUBLE PRECISION;

declare variable C1 DOUBLE PRECISION;
declare variable C2 DOUBLE PRECISION;
declare variable C3 DOUBLE PRECISION;
declare variable C4 DOUBLE PRECISION;
declare variable C5 DOUBLE PRECISION;
declare variable C6 DOUBLE PRECISION;
declare variable C7 DOUBLE PRECISION;
declare variable C8 DOUBLE PRECISION;

declare variable B1 DOUBLE PRECISION;
declare variable B2 DOUBLE PRECISION;
declare variable B3 DOUBLE PRECISION;
declare variable B4 DOUBLE PRECISION;
declare variable B5 DOUBLE PRECISION;
declare variable B6 DOUBLE PRECISION;
declare variable B7 DOUBLE PRECISION;
declare variable B8 DOUBLE PRECISION;

declare variable WK INTEGER;
declare variable V DOUBLE PRECISION;
declare variable B DOUBLE PRECISION;
declare variable C DOUBLE PRECISION;
declare variable T DOUBLE PRECISION;

declare variable WKSDATE DATE;
declare variable WKEDATE DATE;
BEGIN
   if (PDATE IS NULL) then
      SELECT INVSYSDATE FROM SYSPARAM INTO :PDATE;
   /* ----------------------------------------------------------------------- */
   /* CASH ON HAND                                                            */
   /* ----------------------------------------------------------------------- */
   WK1 = 0; WK2 = 0; WK3 = 0; WK4 = 0; WK5 = 0; WK6 = 0; WK7 = 0; WK8 = 0;
   INFO = 'OPENING';
   DATA = 'TEXT';
   TEXT = 'Cash On Hand';
   SUSPEND;
   T = 0;
   FOR SELECT B.BANK, B.BANKNAME from SYSBANK B
       ORDER BY BANK
       INTO DATA, TEXT
   DO BEGIN
      SELECT OPENING FROM bbacc A
      WHERE A.BANK = :DATA
      AND A.BBDATE = :PDATE
      INTO WK1;
      if (WK1 IS NULL) then WK1 = 0;
      TEXT = '   ' || TEXT;
      T = T + WK1;
      SUSPEND;
   END
   WK1 = T;
   DATA = 'TOTAL';
   TEXT = 'Total Cash On Hand';
   SUSPEND;
   /* ----------------------------------------------------------------------- */
   /* SPACE                                                                   */
   /* ----------------------------------------------------------------------- */
   INFO = 'SPACE';
   DATA = 'SPACE';
   TEXT = '';
   WK1 = 0; WK2 = 0; WK3 = 0; WK4 = 0; WK5 = 0; WK6 = 0; WK7 = 0; WK8 = 0;
   SUSPEND;    
   /* ----------------------------------------------------------------------- */
   /* ACCOUNT PAYABLE                                                         */
   /* ----------------------------------------------------------------------- */    
   INFO = 'TEXT';
   DATA = 'TEXT';
   TEXT = 'Account Payable';
   SUSPEND;

   FOR SELECT WK, VOUCHERDUE, CASHDUE, BANKDUE
   FROM AP_CASHQ(:PDATE) INTO WK, V, C, B
   DO BEGIN
      if (WK = 0) then BEGIN V1 = V; B1 = B; C1 = C; END
      if (WK = 1) then BEGIN V2 = V; B2 = B; C2 = C; END
      if (WK = 2) then BEGIN V3 = V; B3 = B; C3 = C; END
      if (WK = 3) then BEGIN V4 = V; B4 = B; C4 = C; END
      if (WK = 4) then BEGIN V5 = V; B5 = B; C5 = C; END
      if (WK = 5) then BEGIN V6 = V; B6 = B; C6 = C; END
      if (WK = 6) then BEGIN V7 = V; B7 = B; C7 = C; END
      if (WK = 7) then BEGIN V8 = V; B8 = B; C8 = C; END
   END
   INFO = 'AP'; DATA = 'BANK';
   TEXT = '   -Bank Due';
   WK1 = B1; WK2 = B2; WK3 = B3; WK4 = B4; WK5 = B5; WK6 = B6; WK7 = B7; WK8 = B8;
   SUSPEND;

   INFO = 'AP'; DATA = 'CASH';
   TEXT = '   -Cash Due';
   WK1 = C1; WK2 = C2; WK3 = C3; WK4 = C4; WK5 = C5; WK6 = C6; WK7 = C7; WK8 = C8;
   SUSPEND;

   INFO = 'AP'; DATA = 'VOUCHER';
   TEXT = '   -Voucher Due';
   WK1 = V1; WK2 = V2; WK3 = V3; WK4 = V4; WK5 = V5; WK6 = V6; WK7 = V7; WK8 = V8;
   SUSPEND;
   
   INFO = 'AP'; DATA = 'TOTAL';
   TEXT = 'Total Account Payable';
   WK1 = B1+C1+V1;
   WK2 = B2+C2+V2;
   WK3 = B3+C3+V3;
   WK4 = B4+C4+V4;
   WK5 = B5+C5+V5;
   WK6 = B6+C6+V6;
   WK7 = B7+C7+V7;
   WK8 = B8+C8+V8;
   SUSPEND;   
   /* ----------------------------------------------------------------------- */
   /* SPACE                                                                   */
   /* ----------------------------------------------------------------------- */
   INFO = 'SPACE';
   DATA = 'SPACE';
   TEXT = '';
   WK1 = 0; WK2 = 0; WK3 = 0; WK4 = 0; WK5 = 0; WK6 = 0; WK7 = 0; WK8 = 0;
   SUSPEND;       
   /* ----------------------------------------------------------------------- */
   /* PURCHASE ORDER                                                          */
   /* ----------------------------------------------------------------------- */   
   FOR SELECT WK, PO FROM CASHFLOW_PO(:PDATE)
   INTO WK, V
   DO BEGIN
      if (WK = 0) then V1 = V;
      if (WK = 1) then V2 = V; 
      if (WK = 2) then V3 = V;
      if (WK = 3) then V4 = V;
      if (WK = 4) then V5 = V;
      if (WK = 5) then V6 = V;
      if (WK = 6) then V7 = V;
      if (WK = 7) then V8 = V;
   END
   INFO = 'PO'; DATA = 'PO';
   TEXT = 'Purchase Order';
   WK1 = V1; WK2 = V2; WK3 = V3; WK4 = V4; WK5 = V5; WK6 = V6; WK7 = V7; WK8 = V8;
   SUSPEND;   
   /* ----------------------------------------------------------------------- */
   /* SPACE                                                                   */
   /* ----------------------------------------------------------------------- */
   INFO = 'SPACE';
   DATA = 'SPACE';
   TEXT = '';
   WK1 = 0; WK2 = 0; WK3 = 0; WK4 = 0; WK5 = 0; WK6 = 0; WK7 = 0; WK8 = 0;
   SUSPEND;       
   /* ----------------------------------------------------------------------- */
   /* BANK FORECAST                                                           */
   /* ----------------------------------------------------------------------- */
   INFO = 'TEXT';
   DATA = 'TEXT';
   TEXT = 'Bank Income/(Expenses)';
   SUSPEND;
   B1 = 0; B2 = 0; B3 = 0; B4 = 0; B5 = 0; B6 = 0; B7 = 0; B8 = 0;
   INFO = 'BANK';
   FOR SELECT B.BANK, B.BANKNAME from SYSBANK B
       ORDER BY BANK
   INTO DATA, TEXT
   DO BEGIN
      FOR SELECT WK, TOTAL FROM BB_CASHQ(:PDATE, :DATA)
      INTO WK, V
      DO BEGIN
         if (WK = 0) then V1 = V;
         if (WK = 1) then V2 = V;
         if (WK = 2) then V3 = V;
         if (WK = 3) then V4 = V;
         if (WK = 4) then V5 = V;
         if (WK = 5) then V6 = V;
         if (WK = 6) then V7 = V;
         if (WK = 7) then V8 = V;
      END
      TEXT = '   +/-' || TEXT;
      WK1 = V1; WK2 = V2; WK3 = V3; WK4 = V4; WK5 = V5; WK6 = V6; WK7 = V7; WK8 = V8;
      SUSPEND;
      B1 = B1 + WK1;
      B2 = B2 + WK2;
      B3 = B3 + WK3;
      B4 = B4 + WK4;
      B5 = B5 + WK5;
      B6 = B6 + WK6;
      B7 = B7 + WK7;
      B8 = B8 + WK8;
   END
   INFO = 'BANK'; DATA = 'TOTAL';
   TEXT = 'Total Bank Income/Expenses';
   WK1 = B1; WK2 = B2; WK3 = B3; WK4 = B4; WK5 = C5; WK6 = B6; WK7 = B7; WK8 = B8;
   SUSPEND;
   /* ----------------------------------------------------------------------- */
   /* SPACE                                                                   */
   /* ----------------------------------------------------------------------- */
   INFO = 'SPACE';
   DATA = 'SPACE';
   TEXT = '';
   WK1 = 0; WK2 = 0; WK3 = 0; WK4 = 0; WK5 = 0; WK6 = 0; WK7 = 0; WK8 = 0;
   SUSPEND;       
   /* ----------------------------------------------------------------------- */
   /* FORECAST                                                                */
   /* ----------------------------------------------------------------------- */
   INFO = 'TEXT';
   DATA = 'TEXT';
   TEXT = 'Forecast';
   SUSPEND;
   B1 = 0; B2 = 0; B3 = 0; B4 = 0; B5 = 0; B6 = 0; B7 = 0; B8 = 0;
   
   INFO = 'FORECAST';
   FOR SELECT CODE, NAME FROM glcflow_code
       ORDER BY name
       INTO DATA, TEXT
   DO BEGIN
      wk = 1;
      while (wk <= 8) do
      begin
        wksdate = PDATE+wk*7;
        wkedate = wksdate+6;

        SELECT SUM(DB-CR) FROM glcflow_jur
        WHERE CODE = :DATA
        AND CASHDATE BETWEEN :WKSDATE AND :WKEDATE
        into V;
        if (V is null) then V = 0;
        if (WK = 0) then V1 = V;
        if (WK = 1) then V2 = V;
        if (WK = 2) then V3 = V;
        if (WK = 3) then V4 = V;
        if (WK = 4) then V5 = V;
        if (WK = 5) then V6 = V;
        if (WK = 6) then V7 = V;
        if (WK = 7) then V8 = V;
        wk = wk+1;
      END
      TEXT = '   +/-' || TEXT;
      WK1 = V1; WK2 = V2; WK3 = V3; WK4 = V4; WK5 = V5; WK6 = V6; WK7 = V7; WK8 = V8;
      SUSPEND;
      B1 = B1 + WK1;
      B2 = B2 + WK2;
      B3 = B3 + WK3;
      B4 = B4 + WK4;
      B5 = B5 + WK5;
      B6 = B6 + WK6;
      B7 = B7 + WK7;
      B8 = B8 + WK8;
   END
   INFO = 'FORECAST'; DATA = 'TOTAL';
   TEXT = 'Total Forecast';
   WK1 = B1; WK2 = B2; WK3 = B3; WK4 = B4; WK5 = C5; WK6 = B6; WK7 = B7; WK8 = B8;
   SUSPEND;   
END^


ALTER PROCEDURE GL_COA_SETUP_CHECK(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    ACCOUNT_INFO VARCHAR(8),
    GL_MODULE VARCHAR(8),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCOUNTNAME VARCHAR(40),
    CODE VARCHAR(8),
    NAME VARCHAR(40),
    NUMBER INTEGER,
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    SOURCENUMBER INTEGER,
    JURDATE DATE,
    CODE_X VARCHAR(8),
    NAME_X VARCHAR(40),
    TEXT VARCHAR(80))
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE ACCTYPE VARCHAR(1);
DECLARE VARIABLE ACCTYPENAME VARCHAR(40);
DECLARE VARIABLE FO_APPLICATION VARCHAR(4);
DECLARE VARIABLE FO_SOURCE VARCHAR(4);
BEGIN
  IF ((PMONTH IS NULL) OR (PMONTH = 0)) THEN
  BEGIN
     PMONTH = 8;
     PYEAR = 2008;
  END
  SDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES (EDATE);
  /* ---------------------------------------------------------------- */
  /* BANK                                                             */
  /* ---------------------------------------------------------------- */
  /* CEK INVALID BANK ACCOUNT TRANSACATION ENTRY                      */
  /* ---------------------------------------------------------------- */
  ACCOUNT_INFO = 'BANK';
  FOR
    SELECT B.GL_ACCOUNT, B.GL_DEPT, B.GL_COST, B.BANK, B.BANKNAME, COA.NAME
    FROM SYSBANK B
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = B.GL_ACCOUNT
    INTO :GL_ACCOUNT, :GL_DEPT, :GL_COST, :CODE, :NAME, ACCOUNTNAME
  DO
  BEGIN
    GL_MODULE = 'BB';
    TEXT = 'For transfer between Bank/Cash Account please use Crossing Account';
    FOR SELECT NUMBER, APPLICATION, SOURCE, SOURCENUMBER, J.BBDATE
        FROM BBJUR J
        WHERE J.BBDATE BETWEEN :SDATE AND :EDATE
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPT = :GL_DEPT
        AND J.COST = :GL_COST
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       SUSPEND;
    END
    GL_MODULE = 'GL';
    TEXT = 'Do not Directly Posting to Bank/Cash Account, please use Bank Book instead';
    FOR SELECT TRANSNO, APPLICATION, SOURCE, SOURCENUMBER, JURDATE
        FROM GLJUR J
        WHERE J.PYEAR = :PYEAR
        AND J.PMONTH = :PMONTH
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPART = :GL_DEPT
        AND J.COST = :GL_COST
        AND (J.APPLICATION <> 'GL') AND (J.SOURCE NOT IN('BB','BL'))
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       IF (NOT (((APPLICATION = 'GL') AND (SOURCE = 'BB')) OR
                ((APPLICATION = 'AP') AND (SOURCE IN ('REC', 'DREC'))) OR
                ((APPLICATION = 'AR') AND (SOURCE IN ('REC', 'DREC', 'CREC')))
          )) THEN
       SUSPEND;
    END
  END
  /* ---------------------------------------------------------------- */
  /* A/P CLEARANCE                                                    */
  /* ---------------------------------------------------------------- */
  ACCOUNT_INFO = 'CLEAR-AP';
  FOR
    SELECT B.GL_ACCOUNT_APPREPARE, B.GL_DEPT_APPREPARE,
           B.GL_COST_APPREPARE, B.BANK, B.BANKNAME, COA.NAME
    FROM SYSBANK B
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = B.GL_ACCOUNT
    INTO :GL_ACCOUNT, :GL_DEPT, :GL_COST, :CODE, :NAME, ACCOUNTNAME
  DO
  BEGIN
    GL_MODULE = 'BB';
    TEXT = 'Do not Directly Posting to A/P Clearance Account On BB Entry';
    FOR SELECT NUMBER, APPLICATION, SOURCE, SOURCENUMBER, J.BBDATE
        FROM BBJUR J
        WHERE J.BBDATE BETWEEN :SDATE AND :EDATE
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPT = :GL_DEPT
        AND J.COST = :GL_COST
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       IF (NOT (((APPLICATION = 'AP') AND (SOURCE IN ('CASH', 'DEP0', 'REC', 'DREC'))))) THEN
       SUSPEND;
    END
    GL_MODULE = 'GL';
    TEXT = 'Do not Directly Posting to A/P Clearance Account On GL Entry';
    FOR SELECT TRANSNO, APPLICATION, SOURCE, SOURCENUMBER, JURDATE
        FROM GLJUR J
        WHERE J.PYEAR = :PYEAR
        AND J.PMONTH = :PMONTH
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPART = :GL_DEPT
        AND J.COST = :GL_COST
        AND (J.APPLICATION <> 'GL') AND (J.SOURCE NOT IN('BB','BL'))
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       IF (NOT (((APPLICATION = 'AP') AND (SOURCE IN ('CASH', 'DEP0', 'REC', 'DREC'))))) THEN
       SUSPEND;
    END
  END
  /* ---------------------------------------------------------------- */
  /* A/R PAYABLE CLEARANCE                                            */
  /* ---------------------------------------------------------------- */
  ACCOUNT_INFO = 'CLEAR-AR';
  FOR
    SELECT B.GL_ACCOUNT_ARPREPARE, B.GL_DEPT_ARPREPARE, B.GL_COST_ARPREPARE,
           B.BANK, B.BANKNAME, COA.NAME
    FROM SYSBANK B
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = B.GL_ACCOUNT
    INTO :GL_ACCOUNT, :GL_DEPT, :GL_COST, :CODE, :NAME, ACCOUNTNAME
  DO
  BEGIN
    GL_MODULE = 'BB';
    TEXT = 'Do not Directly Posting to A/R Clearance Account On BB Entry';
    FOR SELECT NUMBER, APPLICATION, SOURCE, SOURCENUMBER, J.BBDATE
        FROM BBJUR J
        WHERE J.BBDATE BETWEEN :SDATE AND :EDATE
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPT = :GL_DEPT
        AND J.COST = :GL_COST
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       IF (NOT ((APPLICATION = 'AR') AND (SOURCE IN ('CASH', 'DEP0', 'CCPY', 'REC', 'DREC', 'CREC')))) THEN
       SUSPEND;
    END
    GL_MODULE = 'GL';
    TEXT = 'Do not Directly Posting to A/R Clearance Account On GL Entry';
    FOR SELECT TRANSNO, APPLICATION, SOURCE, SOURCENUMBER, JURDATE
        FROM GLJUR J
        WHERE J.PYEAR = :PYEAR
        AND J.PMONTH = :PMONTH
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPART = :GL_DEPT
        AND J.COST = :GL_COST
        AND (J.APPLICATION <> 'GL') AND (J.SOURCE NOT IN('BB','BL'))
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       IF (NOT ((APPLICATION = 'AR') AND (SOURCE IN ('CASH', 'DEP0', 'CCPY', 'REC', 'DREC', 'CREC')))) THEN
       SUSPEND;
    END
  END





  /* ---------------------------------------------------------------- */
  /* INVENTORY ITEM                                                   */
  /* ---------------------------------------------------------------- */
  ACCOUNT_INFO = 'INV';
  FOR
    SELECT G.ACCINV, G.DEPART_INV, G.GL_COST_INV, G.GRP, G.NAME,
           COA.NAME
    FROM INVGROUP G
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = G.ACCINV
    INTO :GL_ACCOUNT, :GL_DEPT, :GL_COST, :CODE, :NAME, ACCOUNTNAME
  DO
  BEGIN
    GL_MODULE = 'BB';
    TEXT = 'Do not Directly Posting to Inventory Account On BB Entry';
    FOR SELECT NUMBER, APPLICATION, SOURCE, SOURCENUMBER, J.BBDATE
        FROM BBJUR J
        WHERE J.BBDATE BETWEEN :SDATE AND :EDATE
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPT = :GL_DEPT
        AND J.COST = :GL_COST
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       SUSPEND;
    END
    GL_MODULE = 'GL';
    TEXT = 'Do not Directly Posting to Inventory Account On GL Entry';
    FOR SELECT TRANSNO, APPLICATION, SOURCE, SOURCENUMBER, JURDATE
        FROM GLJUR J
        WHERE J.PYEAR = :PYEAR
        AND J.PMONTH = :PMONTH
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPART = :GL_DEPT
        AND J.COST = :GL_COST
        AND J.APPLICATION <> 'INV'
        AND (J.APPLICATION <> 'GL') AND (J.SOURCE NOT IN('BB','BL'))
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       SUSPEND;
    END
  END





  /* ---------------------------------------------------------------- */
  /* SUPPLIER TYPE                                                    */
  /* ACCOUNT PAYABLE ACCOUNT                                          */
  /* ---------------------------------------------------------------- */

  ACCOUNT_INFO = 'SUPL-AP';
  FOR
    SELECT G.GLACCOUNT, G.GLDEPT, G.GLCOST, G.SUPPLIERTYPE, G.NAME,
           COA.NAME
    FROM SYSSUPPLIERTYPE G
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = G.GLACCOUNT
    INTO :GL_ACCOUNT, :GL_DEPT, :GL_COST, :CODE, :NAME, ACCOUNTNAME
  DO
  BEGIN
    GL_MODULE = 'BB';
    TEXT = 'Do not Directly Posting to A/P Account On BB Entry';
    FOR SELECT NUMBER, APPLICATION, SOURCE, SOURCENUMBER, J.BBDATE
        FROM BBJUR J
        WHERE J.BBDATE BETWEEN :SDATE AND :EDATE
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPT = :GL_DEPT
        AND J.COST = :GL_COST
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       SUSPEND;
    END
    GL_MODULE = 'GL';
    TEXT = 'Do not Directly Posting to A/P Account On GL Entry';
    FOR SELECT TRANSNO, APPLICATION, SOURCE, SOURCENUMBER, JURDATE
        FROM GLJUR J
        WHERE J.PYEAR = :PYEAR
        AND J.PMONTH = :PMONTH
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPART = :GL_DEPT
        AND J.COST = :GL_COST
        AND (J.APPLICATION <> 'GL') AND (J.SOURCE NOT IN('BB','BL'))
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       IF (NOT (((APPLICATION = 'INV') AND (SOURCE = 'RECV')) OR
                ((APPLICATION = 'AP') AND (SOURCE = 'CASH')))) THEN
       SUSPEND;
    END
  END


  /* ---------------------------------------------------------------- */
  /* SUPPLIER TYPE                                                    */
  /* PURCHASE DEPOSIT                                                 */
  /* ---------------------------------------------------------------- */

  ACCOUNT_INFO = 'SUPL-DEP';
  FOR
    SELECT G.DEPOS_GLACCOUNT, G.DEPOS_GLDEPT, G.DEPOS_GLCOST, G.SUPPLIERTYPE,
           G.NAME, COA.NAME
    FROM SYSSUPPLIERTYPE G
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = G.GLACCOUNT
    INTO :GL_ACCOUNT, :GL_DEPT, :GL_COST, :CODE, :NAME, ACCOUNTNAME
  DO
  BEGIN
    GL_MODULE = 'BB';
    TEXT = 'Do not Directly Posting to A/P Deposit On BB Entry';
    FOR SELECT NUMBER, APPLICATION, SOURCE, SOURCENUMBER, J.BBDATE
        FROM BBJUR J
        WHERE J.BBDATE BETWEEN :SDATE AND :EDATE
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPT = :GL_DEPT
        AND J.COST = :GL_COST
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       SUSPEND;
    END
    GL_MODULE = 'GL';
    TEXT = 'Do not Directly Posting to A/P Deposit On GL Entry';
    FOR SELECT TRANSNO, APPLICATION, SOURCE, SOURCENUMBER, JURDATE
        FROM GLJUR J
        WHERE J.PYEAR = :PYEAR
        AND J.PMONTH = :PMONTH
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPART = :GL_DEPT
        AND J.COST = :GL_COST
        AND (J.APPLICATION <> 'GL') AND (J.SOURCE NOT IN('BB','BL'))
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       IF (NOT ((APPLICATION = 'AP') AND (SOURCE = 'DEP0'))) THEN
       SUSPEND;
    END
    GL_MODULE = 'AP';
    TEXT = 'Do not A/P Account as A/P Deposit';
    IF (EXISTS(SELECT * FROM SYSSUPPLIERTYPE G WHERE G.GLACCOUNT = :GL_ACCOUNT)) THEN
    BEGIN
       ACCOUNT_INFO = 'AP-SUPL';
       APPLICATION = '';
       SOURCE = '';
       SOURCENUMBER = 0;
       NUMBER = 0;
       JURDATE = NULL;
       SUSPEND;
    END
  END


  /* ---------------------------------------------------------------- */
  /* FRONT OFFICE SETUP                                               */
  /* ---------------------------------------------------------------- */

  FOR
    SELECT FO.GL_ACCOUNT, FO.GL_DEPT, FO.GL_COST, FO.CODE,
           FO.NAME, FO.APPLICATION, FO.SOURCE, COA.NAME
    FROM GLCOA_FO_SETUP FO
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = FO.GL_ACCOUNT
    INTO GL_ACCOUNT, GL_DEPT, GL_COST, CODE, NAME,
         FO_APPLICATION, FO_SOURCE, ACCOUNTNAME
  DO
  BEGIN
    GL_MODULE = 'BB';
    ACCOUNT_INFO = FO_APPLICATION||'-'||FO_SOURCE;
    FOR SELECT NUMBER, APPLICATION, SOURCE, SOURCENUMBER, J.BBDATE
        FROM BBJUR J
        WHERE J.BBDATE BETWEEN :SDATE AND :EDATE
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPT = :GL_DEPT
        AND J.COST = :GL_COST
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       IF ((FO_APPLICATION = 'AR') AND (FO_SOURCE = 'AR')) THEN
       BEGIN
          TEXT = 'Do not Directly Posting to A/R Account On BB Entry';
          SUSPEND;
       END
       ELSE
       IF ((FO_APPLICATION = 'AR') AND (FO_SOURCE = 'CARD')) THEN
       BEGIN
          TEXT = 'Do not Directly Posting to A/R Credit Card On GL Entry';
          SUSPEND;
       END
       ELSE
       IF ((FO_APPLICATION = 'AR') AND (FO_SOURCE = 'DEP')) THEN
       BEGIN
          TEXT = 'Do not Directly Posting to A/R Deposit On GL Entry';
          SUSPEND;
       END
       ELSE
         SUSPEND;
    END
    /* ---------------------------------------------------------------- */
    /* GL ENTRY                                                         */
    /* ---------------------------------------------------------------- */
    GL_MODULE = 'GL';
    FOR SELECT TRANSNO, APPLICATION, SOURCE, SOURCENUMBER, JURDATE
        FROM GLJUR J
        WHERE J.PYEAR = :PYEAR
        AND J.PMONTH = :PMONTH
        AND J.ACCOUNT = :GL_ACCOUNT
        AND J.DEPART = :GL_DEPT
        AND J.COST = :GL_COST
        AND (J.APPLICATION <> 'GL') AND (J.SOURCE NOT IN('BB','BL'))
        INTO NUMBER,  APPLICATION, SOURCE, SOURCENUMBER, JURDATE
    DO
    BEGIN
       IF ((FO_APPLICATION = 'AR') AND (FO_SOURCE = 'AR')) THEN
       BEGIN
          IF (NOT (((APPLICATION = 'AR') AND (SOURCE = 'VCH')) OR
                   ((APPLICATION = 'AR') AND (SOURCE = 'DEP1')) OR
                   ((APPLICATION = 'AR') AND (SOURCE = 'ADJ')) OR
                   ((APPLICATION = 'AR') AND (SOURCE = 'CASH')))) THEN
          BEGIN
             TEXT = 'Do not Directly Posting to A/R Account On GL Entry';
             SUSPEND;
          END
       END
       ELSE
       IF ((FO_APPLICATION = 'AR') AND (FO_SOURCE = 'CARD')) THEN
       BEGIN
          IF (NOT (((APPLICATION = 'FO') AND (SOURCE = 'IC')) OR
                   ((APPLICATION = 'AR') AND (SOURCE = 'CCPY')))) THEN
          BEGIN
             TEXT = 'Do not Directly Posting to A/R Credit Card On GL Entry';
             SUSPEND;
          END
       END
       ELSE
       IF ((FO_APPLICATION = 'AR') AND (FO_SOURCE = 'DEP')) THEN
       BEGIN
          IF (NOT (((APPLICATION = 'AR') AND (SOURCE = 'DEP0')) OR
                   ((APPLICATION = 'AR') AND (SOURCE = 'DEP1')))) THEN
          BEGIN
             TEXT = 'Do not Directly Posting to A/R Deposit On GL Entry';
             SUSPEND;
          END
       END
       ELSE
         SUSPEND;
    END
  END


  
  /* ---------------------------------------------------------------- */
  /* INVENTORY COST ALLOCATION                                        */
  /* ---------------------------------------------------------------- */
  ACCOUNT_INFO = 'INV-COST';
  APPLICATION = '';
  SOURCE = '';
  SOURCENUMBER = 0;
  NUMBER = 0;
  JURDATE = NULL;

  FOR SELECT X.ICOST, CC.NAME, X.GL_ACCOUNT, X.GL_DEPT, X.GL_COST,
             X.GRP, G.NAME, COA.NAME, COA.ACCTYPE, T.NAME
      FROM INVGROUPACC X
      INNER JOIN GLCOA COA ON COA.ACCOUNT = X.GL_ACCOUNT
      LEFT JOIN GLCOATYPE T ON T.ACCTYPE = COA.ACCTYPE
      LEFT JOIN INVCOST CC ON CC.ICOST = X.ICOST
      LEFT JOIN INVGROUP G ON G.GRP = X.GRP
      INTO CODE, NAME, GL_ACCOUNT, GL_DEPT, GL_COST, CODE_X, NAME_X,
           ACCOUNTNAME, ACCTYPE, ACCTYPENAME
  DO
  BEGIN
     TEXT = '';
     IF (ACCTYPE <> 'C') THEN
        TEXT = 'Please use Cost/Expeneses Account type instead of '|| SUBSTR(ACCTYPENAME, 1, 20);
     ELSE
     IF (EXISTS(SELECT * FROM INVGROUP WHERE ACCINV=:GL_ACCOUNT)) THEN
        TEXT = 'Do not use Inventory Account for Cost Allocation';
     ELSE
     IF (EXISTS(SELECT * FROM SYSSUPPLIERTYPE WHERE GLACCOUNT=:GL_ACCOUNT)) THEN
        TEXT = 'Do not use A/P Account (in Supplier Type) for Cost Allocation';
     ELSE
     IF (EXISTS(SELECT * FROM SYSSUPPLIERTYPE WHERE DEPOS_GLACCOUNT=:GL_ACCOUNT)) THEN
        TEXT = 'Do not use A/P Deposit Account (in Supplier Type) for Cost Allocation';
     ELSE
     IF (EXISTS(SELECT * FROM SYSBANK WHERE GL_ACCOUNT=:GL_ACCOUNT)) THEN
        TEXT = 'Do not use Cash/Bank Account (in Bank) for Cost Allocation';
     ELSE
     IF (EXISTS(SELECT * FROM SYSBANK WHERE GL_ACCOUNT_APPREPARE=:GL_ACCOUNT)) THEN
        TEXT = 'Do not use A/P Clearance Account (in Bank) for Cost Allocation';
     ELSE
     IF (EXISTS(SELECT * FROM SYSBANK WHERE GL_DEPT_ARPREPARE=:GL_ACCOUNT)) THEN
        TEXT = 'Do not use A/R Clearance Account (in Bank) for Cost Allocation';

     IF (TEXT <> '') THEN
     SUSPEND;
  END
END^


ALTER PROCEDURE GL_CONTROL
RETURNS (
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    NAME VARCHAR(40),
    GL_COUNT INTEGER,
    GL_DEBIT DOUBLE PRECISION,
    GL_CREDIT DOUBLE PRECISION)
AS
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;
begin
  SELECT GLYEAR, GLMONTH FROM SYSPARAM WHERE ID = 1 INTO PYEAR, PMONTH;

  FOR SELECT APPLICATION, SOURCE, NAME FROM GLIMPORT
  INTO APPLICATION, SOURCE, NAME
  DO
  BEGIN
     suspend;
  END
end^


ALTER PROCEDURE GL_DESKTOP_INV(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    INVSYSDATE DATE,
    ITYPE CHAR(1),
    ITYPENAME VARCHAR(20),
    CODE VARCHAR(16),
    TEXT VARCHAR(40),
    AMOUNT DOUBLE PRECISION,
    FLAG_BOLD INTEGER,
    LINE_COUNTER INTEGER)
AS
DECLARE VARIABLE OPENING DOUBLE PRECISION;
DECLARE VARIABLE ENDING DOUBLE PRECISION;
DECLARE VARIABLE RECEIVING DOUBLE PRECISION;
DECLARE VARIABLE DU DOUBLE PRECISION;
DECLARE VARIABLE AVAILABLE DOUBLE PRECISION;
DECLARE VARIABLE CONSUME DOUBLE PRECISION;
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE I INTEGER;
BEGIN
  IF ((PYEAR = 0) OR (PYEAR IS NULL)) THEN
  BEGIN
     SELECT INV_YEAR, INV_MONTH FROM SYSPARAM INTO PYEAR, PMONTH;
  END
  SELECT INVSYSDATE FROM SYSPARAM INTO INVSYSDATE;

  /* ---------------------------------------------------------------- */
  /* CALCULATE BEGINNING & ENDING DATE                                */
  /* ---------------------------------------------------------------- */
  SDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES EDATE;




  I = 1;
  LINE_COUNTER = 0;
  WHILE (I <= 3) DO
  BEGIN
     /* ---------------------------------------------------------------- */
     /* ITEM TYPE                                                        */
     /* ---------------------------------------------------------------- */
     IF (I = 1) THEN
     BEGIN
        ITYPE = 'F';
        ITYPENAME = 'Food';
     END
     ELSE IF (I = 2) THEN
     BEGIN
        ITYPE = 'B';
        ITYPENAME = 'Beverage';
     END
     ELSE
     BEGIN
        ITYPE = 'M';
        ITYPENAME = 'Material';
     END



     /* ---------------------------------------------------------------- */
     /* FOOD & BEVERAGE                                                  */
     /* ---------------------------------------------------------------- */
     IF (ITYPE IN ('F','B')) THEN
     BEGIN
        /* ---------------------------------------------------------------- */
        /* LOAD FROM INVSTOCK                                               */
        /* ---------------------------------------------------------------- */
        SELECT SUM(I.AMTOPEN), SUM(I.AMTONHAND), SUM(I.AMTIN)
        FROM INVSTOCK I
        WHERE I.PYEAR = :PYEAR
        AND I.PMONTH = :PMONTH
        AND I.ITYPE = :ITYPE
        INTO OPENING, ENDING, RECEIVING;

        /* ---------------------------------------------------------------- */
        /* LOAD FROM CONSUMPTION                                            */
        /* ---------------------------------------------------------------- */
        SELECT SUM(DIRECTUSEAMT)
        FROM INVCONSUME_DAILY
        WHERE OPENDATE BETWEEN :SDATE AND :EDATE
        AND ITEMTYPE = :ITYPE
        INTO DU;









     END /* IF (ITYPE IN ('F','B')) THEN */
     ELSE
     /* ---------------------------------------------------------------- */
     /* MATERIAL                                                         */
     /* ---------------------------------------------------------------- */
     BEGIN
        /* ---------------------------------------------------------------- */
        /* LOAD FROM INVSTOCK                                               */
        /* ---------------------------------------------------------------- */
        SELECT SUM(I.AMTOPEN), SUM(I.AMTONHAND), SUM(I.AMTIN)
        FROM INVSTOCK I
        LEFT JOIN INVGROUP G ON G.GRP = I.GRP
        WHERE I.PYEAR = :PYEAR
        AND I.PMONTH = :PMONTH
        AND G.FLAG_MATERIAL = 1
        INTO OPENING, ENDING, RECEIVING;

        /* ---------------------------------------------------------------- */
        /* LOAD FROM CONSUMPTION                                            */
        /* ---------------------------------------------------------------- */
        SELECT SUM(I.DIRECTUSEAMT)
        FROM INVCONSUME_DAILY I
        LEFT JOIN INVGROUP G ON G.GRP = I.ITEMGROUP
        WHERE I.OPENDATE BETWEEN :SDATE AND :EDATE
        AND G.FLAG_MATERIAL = 1
        INTO DU;









     END
     /* ---------------------------------------------------------------- */
     /* CALCULATION                                                      */
     /* ---------------------------------------------------------------- */
     AVAILABLE = OPENING + RECEIVING + DU;
     CONSUME = AVAILABLE - ENDING;
     /* ---------------------------------------------------------------- */

     CODE = 'OPENING';
     TEXT = 'Opening';
     AMOUNT = OPENING;
     FLAG_BOLD = 1;
     LINE_COUNTER = LINE_COUNTER + 1;
     SUSPEND;

     CODE = 'RECEIVING';
     TEXT = '  Receiving';
     AMOUNT = RECEIVING;
     FLAG_BOLD = 0;
     LINE_COUNTER = LINE_COUNTER + 1;
     SUSPEND;

     CODE = 'DU';
     TEXT = '  Direct Use';
     AMOUNT = DU;
     FLAG_BOLD = 0;
     LINE_COUNTER = LINE_COUNTER + 1;
     SUSPEND;

     CODE = 'AVAILABLE';
     TEXT = 'Available';
     AMOUNT = AVAILABLE;
     FLAG_BOLD = 1;
     LINE_COUNTER = LINE_COUNTER + 1;
     SUSPEND;

     CODE = 'ENDING';
     TEXT = '  Ending';
     AMOUNT = ENDING;
     FLAG_BOLD = 0;
     LINE_COUNTER = LINE_COUNTER + 1;
     SUSPEND;

     CODE = 'CONSUME';
     TEXT = 'Consume';
     AMOUNT = CONSUME;
     FLAG_BOLD = 1;
     LINE_COUNTER = LINE_COUNTER + 1;
     SUSPEND;
     /* ---------------------------------------------------------------- */
     I = I + 1;










  END
END^


ALTER PROCEDURE GL_DESKTOP_STATUS(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    APPL VARCHAR(4),
    SOURCE VARCHAR(4),
    DATATYPE VARCHAR(16),
    DATAFORMAT VARCHAR(16),
    TEXT VARCHAR(40),
    DATADATE DATE,
    DATANUMERIC DOUBLE PRECISION)
AS
DECLARE VARIABLE INVSYDATE DATE;
DECLARE VARIABLE APSYSDATE DATE;
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE GL_YEAR INTEGER;
DECLARE VARIABLE GL_MONTH INTEGER;
DECLARE VARIABLE XSTATUS CHAR(1);
DECLARE VARIABLE XDATE DATE;
BEGIN
  APPL = 'INV';
  SOURCE = 'INFO';
  DATATYPE = 'DATE';
  TEXT = 'Inventory Date';
  DATAFORMAT = 'dd-mmm-yyyy ddd';
  DATANUMERIC = 0;
  SELECT INVSYSDATE, APSYSDATE, GLYEAR, GLMONTH
  FROM SYSPARAM INTO INVSYDATE, APSYSDATE, GL_YEAR, GL_MONTH;
  DATADATE = INVSYDATE;
  SUSPEND;

  SDATE = '1.'||GL_MONTH||'.'||GL_YEAR;
  EXECUTE PROCEDURE SP_BEGINOFMONTH(SDATE) RETURNING_VALUES(EDATE);

  /* ---------------------------------------------------------------- */
  /* RECEIVING NOT RELEASED                                           */
  /* ---------------------------------------------------------------- */
  DATAFORMAT = '#,##0';
  DATATYPE   = 'NUMERIC';
  SELECT COUNT(*) FROM INVRECV0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'O'
  INTO DATANUMERIC;

  IF (DATANUMERIC > 0) THEN
  BEGIN
     SOURCE = 'RECV';
     TEXT = '   Receiving';
     SUSPEND;
  END



  /* ---------------------------------------------------------------- */
  /* RETURN NOT RELEASED                                           */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM INVRET0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'O'
  INTO DATANUMERIC;

  IF (DATANUMERIC > 0) THEN
  BEGIN
     SOURCE = 'RET';
     TEXT = '   Return';
     SUSPEND;
  END



  /* ---------------------------------------------------------------- */
  /* ISSUING NOT RELEASED                                             */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM INVISS0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'O'
  INTO DATANUMERIC;

  IF (DATANUMERIC > 0) THEN
  BEGIN
     SOURCE = 'ISUE';
     TEXT = '   Issuing';
     SUSPEND;
  END


  /* ---------------------------------------------------------------- */
  /* TRANSFER NOT RELEASED                                            */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM INVTRF0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'O'
  INTO DATANUMERIC;

  IF (DATANUMERIC > 0) THEN
  BEGIN
     SOURCE = 'TRF';
     TEXT = '   Transfer';
     SUSPEND;
  END


  /* ---------------------------------------------------------------- */
  /* SPOILAGE NOT RELEASED                                            */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM INVSPL0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'O'
  INTO DATANUMERIC;

  IF (DATANUMERIC > 0) THEN
  BEGIN
     SOURCE = 'SPL';
     TEXT = '   Spoilage/Breakage';
     SUSPEND;
  END


  /* ---------------------------------------------------------------- */
  /* ADJUSTMENT NOT RELEASED                                          */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM INVADJ0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'O'
  INTO DATANUMERIC;

  IF (DATANUMERIC > 0) THEN
  BEGIN
     SOURCE = 'ADJ';
     TEXT = '   Adjustment';
     SUSPEND;
  END



  /* ---------------------------------------------------------------- */
  /* CREDIT TO COST NOT RELEASED                                      */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM INV_CRD_TO_COST0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'O'
  INTO DATANUMERIC;

  IF (DATANUMERIC > 0) THEN
  BEGIN
     SOURCE = 'CR2C';
     TEXT = '   Credit to Cost';
     SUSPEND;
  END

  /* ---------------------------------------------------------------- */
  /* CREDIT TO COST NOT RELEASED                                      */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM INV_OC
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'O'
  INTO DATANUMERIC;

  IF (DATANUMERIC > 0) THEN
  BEGIN
     SOURCE = 'OC';
     TEXT = '   House Use/Compliment';
     SUSPEND;
  END

  /* ---------------------------------------------------------------- */
  /* AP                                                               */
  /* ---------------------------------------------------------------- */
  APPL = 'AP';
  SOURCE = 'INFO';
  SOURCE = 'DATE';
  DATATYPE = 'DATE';
  TEXT = 'Account Payable Date';
  DATAFORMAT = 'dd-mmm-yyyy ddd';
  DATANUMERIC = 0;
  DATADATE = APSYSDATE;
  SUSPEND;


  /* ---------------------------------------------------------------- */
  /* VOUCHER FROM COMMISSION & SHARE                                  */
  /* ---------------------------------------------------------------- */
  DATAFORMAT = '#,##0';
  DATATYPE   = 'NUMERIC';
  SELECT COUNT(*) FROM APVCH
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND SOURCE IN ('C','S','F')
  AND GLSTATUS = 'O'
  INTO DATANUMERIC;

  IF (DATANUMERIC > 0) THEN
  BEGIN
     SOURCE = 'SHARE';
     TEXT = '   Share & Commission';
     SUSPEND;
  END



  /* ---------------------------------------------------------------- */
  /* ADJUSTMENT                                                       */
  /* ---------------------------------------------------------------- */
  SELECT COUNT(*) FROM APADJ
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS = 'O'
  INTO DATANUMERIC;

  IF (DATANUMERIC > 0) THEN
  BEGIN
     SOURCE = 'ADJ';
     TEXT = '   Adjusment';
     SUSPEND;
  END

  /* ---------------------------------------------------------------- */
  /* BANK BOOK                                                        */
  /* ---------------------------------------------------------------- */
  APPL = 'BB';
  DATANUMERIC = 0;
  DATAFORMAT = '#,##0';
  DATATYPE   = 'NUMERIC';
  FOR SELECT A.BANK, B.BANKNAME, COUNT(*) FROM BBACC A
      LEFT JOIN SYSBANK B ON B.BANK = A.BANK
      WHERE A.BBDATE BETWEEN '1.10.2006' AND '31.10.2006'
      AND A.STATUS = 'O'
      GROUP BY A.BANK, B.BANKNAME
      INTO SOURCE, TEXT, DATANUMERIC
  DO
  BEGIN
     SUSPEND;
  END
END^


ALTER PROCEDURE GL_EOM
AS
DECLARE VARIABLE VOMONTH INTEGER;
DECLARE VARIABLE VOYEAR INTEGER;
DECLARE VARIABLE VMONTH INTEGER;
DECLARE VARIABLE VYEAR INTEGER;
DECLARE VARIABLE VACCOUNT VARCHAR(20);
DECLARE VARIABLE VDEPT VARCHAR(4);
DECLARE VARIABLE VCOST VARCHAR(4);
DECLARE VARIABLE VACCTYPE CHAR(1);
DECLARE VARIABLE VOPENING NUMERIC(18,4);
DECLARE VARIABLE VENDING NUMERIC(18,4);
DECLARE VARIABLE VDB NUMERIC(18,4);
DECLARE VARIABLE VCR NUMERIC(18,4);
DECLARE VARIABLE GLCUREARN VARCHAR(20);
DECLARE VARIABLE GLRETEARN VARCHAR(20);
DECLARE VARIABLE DEFA_COST VARCHAR(4);
DECLARE VARIABLE DEFA_DEPT VARCHAR(4);
declare variable EARNING DOUBLE PRECISION;
/* 14 feb 2007, retained earning per year, base on setup */
DECLARE VARIABLE GL_RETAINED VARCHAR(20);




DECLARE VARIABLE VROWS INTEGER;
begin
  select glyear, glmonth, GLCUREARN, GLRETEARN, GL_DEFAULT_COST, GL_DEFAULT_DEPT
  from sysparam
  into :vOYear, :vOMonth, GLCUREARN, GLRETEARN, DEFA_COST, DEFA_DEPT;
  
  vMonth = vOMonth + 1;
  vYear = vOYear;

  if (vMonth > 12) then
  begin
     vMonth = 1;
     vYear = vYear + 1;
  end


  /* -------------------------------------------------------------------------*/
  /* CREATE RETURN EARNING, 6 SEP 2005                                        */
  /* -------------------------------------------------------------------------*/
  /* THIS YEAR RETAINED EARNING                                               */
  /* 14 FEB 2007, LOAD RETAINED EARNING ACCOUNT                               */
  /* ------------------------------------------------------------------------ */
  IF (EXISTS(SELECT * FROM GLCOA_RETAINED WHERE PYEAR = :vOYear-1)) THEN
     SELECT ACCOUNT FROM GLCOA_RETAINED WHERE PYEAR = :vOYear-1 INTO GL_RETAINED; /* AMBIL RETAINED EARNING DARI SETUP */
  ELSE
     GL_RETAINED = GLRETEARN;
  /* ------------------------------------------------------------------------ */


  IF (NOT EXISTS(SELECT * FROM GLACC WHERE PYEAR = :vOYear AND PMONTH = :vOMonth
                 AND ACCOUNT = :GL_RETAINED AND DEPART = :DEFA_DEPT AND COST = :DEFA_COST)) THEN
  BEGIN
     INSERT INTO GLACC (PYEAR, PMONTH, ACCOUNT, DEPART, COST, OPENING, DB, CR)
     VALUES (:vOYear, :vOMonth, :GL_RETAINED, :DEFA_DEPT, :DEFA_COST, 0,0,0);
  END
  /* -------------------------------------------------------------------------*/
  /* NEXT YEAR RETAINED EARNING                                               */
  /* 14 FEB 2007, LOAD RETAINED EARNING ACCOUNT                               */
  /* -------------------------------------------------------------------------*/
  IF (EXISTS(SELECT * FROM GLCOA_RETAINED WHERE PYEAR = :vYear-1)) THEN
     SELECT ACCOUNT FROM GLCOA_RETAINED WHERE PYEAR = :vYear-1 INTO GL_RETAINED; /* AMBIL RETAINED EARNING DARI SETUP */
  ELSE
     GL_RETAINED = GLRETEARN;
  /* ------------------------------------------------------------------------ */
  
  
  
  IF (NOT EXISTS(SELECT * FROM GLACC WHERE PYEAR = :vYear AND PMONTH = :vMonth
                 AND ACCOUNT = :GL_RETAINED AND DEPART = :DEFA_DEPT AND COST = :DEFA_COST)) THEN
  BEGIN
     INSERT INTO GLACC (PYEAR, PMONTH, ACCOUNT, DEPART, COST, OPENING, DB, CR)
     VALUES (:vYear, :vMonth, :GL_RETAINED, :DEFA_DEPT, :DEFA_COST, 0,0,0);
  END
  /* -------------------------------------------------------------------------*/

  for select Account, Depart, Cost, Opening, DB, CR
        from glacc
        where (PYear  = :vOYear)
          and (PMonth = :vOMonth)
        into vAccount, vDept, vCost, vOpening, vDB, vCR
  do
  begin
     if (vOpening is null) then vOpening = 0;
     SELECT AccType from glcoa WHERE Account = :vAccount into :vAccType ;
     
     IF (NOT EXISTS(SELECT * FROM GLACC where (PYear   = :vYear) and (PMonth  = :vMonth)
         and (Account = :vAccount) and (Depart = :vDept) and (Cost = :vCost))) THEN
     BEGIN
        insert into glacc (PYear, PMonth, Account, Depart, Cost, DB, CR, Opening, Budget)
        values (:vYear, :vMonth, :vAccount, :vDept, :vCost, 0,0,0,0);
     END

     if (:vAccType = 'A') then vOpening = vOpening + vDB - vCR;
     else if (:vAccType = 'P') then vOpening = vOpening - vDB + vCR;
     else vOpening = 0; /*  if (:vAccType in ('I', 'C','S')) then  */
     /* --------------------------------------------------------------------- */
     /* jika ganti tahun dan a/c adalah laba ditahan maka saldo jadi nol      */
     /* --------------------------------------------------------------------- */
     if ((vYear <> vOYear) and (vAccount = GLCUREARN)) then
     begin
        vOpening = 0;
     end
     /* --------------------------------------------------------------------- */
     UPDATE GLACC SET Opening = :vOpening
      where (PYear   = :vYear)
        and (PMonth  = :vMonth)
        and (Account = :vAccount)
        and (Depart = :vDept)
        and (Cost = :vCost);
  end
  /* ------------------------------------------------------------------------ */
  /* pindahkan current earning ke retained earning untuk tahun berikutnya     */
  /* ------------------------------------------------------------------------ */
  if (vYear <> vOYear) then
  begin
     /* --------------------------------------------------------------------- */
     /* LOAD RETAIN EARNING ACCOUNT                                           */
     /* --------------------------------------------------------------------- */

     IF (EXISTS(SELECT * FROM GLCOA_RETAINED WHERE PYEAR = :vYear-1)) THEN
        SELECT ACCOUNT FROM GLCOA_RETAINED WHERE PYEAR = :vYear-1 INTO GL_RETAINED; /* AMBIL RETAINED EARNING DARI SETUP */
     ELSE
        GL_RETAINED = GLRETEARN;

     /* --------------------------------------------------------------------- */
     
     UPDATE GLACC SET Opening = 0 /* KOSONGKAN CURRENT EARNING */
        where (PYear   = :vYear)
          and (PMonth  = :vMonth)
          and (Account = :GLCUREARN);
          
     for select Depart, Cost, ending
         from glacc
         where (PYear  = :vOYear)
          and (PMonth = :vOMonth)
          and account = :GLCUREARN
         into vDept, vCost, VENDING
     do
     begin
       if (NOT EXISTS(SELECT * FROM GLACC
               where (PYear   = :vYear)
                   and (PMonth  = :vMonth)
                   and (Account = :GL_RETAINED)
                   and (Depart = :vDept)
                   and (Cost = :vCost))) then
       BEGIN
           insert into glacc
               (PYear, PMonth, Account, Depart, Cost, DB, CR, Opening, Budget)
            values
               (:vYear, :vMonth, :GL_RETAINED, :vDept, :vCost, 0,0,0,0);
       END
       UPDATE GLACC SET
               OPENING = OPENING + :VENDING
         where (PYear   = :vYear)
           and (PMonth  = :vMonth)
           and (Account = :GL_RETAINED)
           and (Depart = :vDept)
           and (Cost = :vCost);
     end
  end
end^


ALTER PROCEDURE GL_IMPORT(
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    NUMBER INTEGER,
    PYEAR INTEGER,
    PMONTH INTEGER,
    TRANSDATE DATE,
    DOCUMENT VARCHAR(20))
AS
declare variable vTransNo INTEGER;
declare variable vID INTEGER;
declare variable vACCOUNT VARCHAR(20);
declare variable vDEPT VARCHAR(4);
declare variable vCOST VARCHAR(4);
declare variable vPROJECT VARCHAR(8);
declare variable vNOTE VARCHAR(40);
declare variable vREF VARCHAR(20);
declare variable vDB DOUBLE PRECISION;
declare variable vCR DOUBLE PRECISION;
declare variable vJurCode VARCHAR(4);
declare variable vFirstRow integer;
declare variable vExist integer;
declare variable vImportType CHAR(3) ;
DECLARE VARIABLE DOCTYPE INTEGER;
begin

   /* begin 24 sep 2002 */
   select pyear, pmonth from GLPERIOD
   where :transdate between date_start and date_end
   into :pyear, :pmonth;
   /* end 24 sep 2002 */
   IF ((PYEAR IS NULL) OR (PYEAR = 0)) THEN
   BEGIN
      PYEAR  = EXTRACT(YEAR FROM TRANSDATE);
      PMONTH = EXTRACT(MONTH FROM TRANSDATE);
      
   END

   SELECT MAX(TRANSNO) FROM GLTRANS
   WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
   INTO vTransNo;

   if (vTransNo is null) then vTransNo = 0;
   vTransNo = vTransNo + 1;


   if (SOURCE = 'DU') then vImportType = 'DAY';
   
   vFirstRow = 0;

   SELECT ImportType, JurCode from glimport
   where Application = :Application and Source = :Source
   into :vImportType, :vJurCode;
   /* -------------------------------------------------------------------------- */
   /* detail import from glbuffer                                                */
   /* -------------------------------------------------------------------------- */
   if (vImportType = 'DET') then
   begin
     SELECT DISTINCT MAX(RELATION_DOCTYPE) FROM GLBUFFER
     WHERE APPLICATION = :APPLICATION AND SOURCE = :SOURCE
     AND NUMBER = :NUMBER INTO DOCTYPE;
     
     FOR SELECT ID, TRANSDATE,
             ACCOUNT, DEPT, COST,PROJECT, 
             NOTE, REF, DB, CR
        FROM GLBUFFER
       WHERE APPLICATION = :APPLICATION
         AND SOURCE = :SOURCE
         AND NUMBER = :NUMBER
         AND RELATION_DOCTYPE = :DOCTYPE
         AND (DB + CR <> 0)
         AND STATUS = 'O'
        INTO vID, TRANSDATE,
             vACCOUNT, vDEPT, vCOST,vPROJECT,
             vNOTE, vREF, vDB, vCR
     DO
     BEGIN
       SELECT DISTINCT MAX(RELATION_DOCTYPE) FROM GLBUFFER
       WHERE APPLICATION = :APPLICATION
       AND SOURCE = :SOURCE
       AND NUMBER = :NUMBER INTO DOCTYPE;     

       IF (DOCTYPE IS NULL) THEN DOCTYPE = 0;
            
       if (vFirstRow = 0) then
       begin
         INSERT INTO GLTRANS
         (PYEAR, PMONTH, TRANSNO, DOCUMENT, JURCODE,
          TRANSDATE, STATUS, REFACCOUNT,
          APPLICATION, SOURCE, SOURCENUMBER, DB, CR, RELATION_DOCTYPE)
         VALUES
         (:PYEAR, :PMONTH, :vTransNo, :DOCUMENT, :vJurCode,
          :TransDate, 'H', '', :Application, :Source, :Number, 0, 0, :DOCTYPE);
       end

       IF (NOT EXISTS(select * from glcoa where account = :vAccount)) then vAccount = '?';
       IF (NOT EXISTS(select * from gldept where depart = :vDept)) then vDept = '0000';
       IF (NOT EXISTS(select * from glcost where cost = :vCost)) then vCost = '0000';

       if ((vDB <> 0) or (vCR <> 0)) then
       begin
          insert into gljur
              (PYEAR, PMONTH, TRANSNO,
               ACCOUNT, DEPART, COST, PROJECT,
               NOTE, REFACCOUNT, JURDATE, REF, DB, CR,
               APPLICATION, SOURCE, SOURCENUMBER)
          VALUES (:PYEAR, :PMONTH, :vTransNo,
               :vAccount, :vDept, :vCost, :vProject,
               :vNote, '', 'NOW', :vRef, :vDB, :vCR,
               :Application, :Source, :Number);
       end
       vFirstRow = vFirstRow + 1;
     END /* FOR BEGIN */
     /* ------------------------------------------------------------------------ */
     /* set status GLBUFFER menjadi menjadi close                                */
     /* ------------------------------------------------------------------------ */
     UPDATE GLBUFFER SET STATUS = 'C'
          WHERE APPLICATION = :APPLICATION
            AND SOURCE = :SOURCE
            AND NUMBER = :NUMBER;

   end /* DETAIL */
   /* -------------------------------------------------------------------------- */
   /* DAILY import from glbuffer                                                 */
   /* -------------------------------------------------------------------------- */
   if (vImportType = 'DAY') then
   begin
      SELECT DISTINCT MAX(RELATION_DOCTYPE) FROM GLBUFFER
      WHERE APPLICATION = :APPLICATION AND SOURCE = :SOURCE
      AND TRANSDATE = :TRANSDATE INTO DOCTYPE;

      IF (DOCTYPE IS NULL) THEN DOCTYPE = 0;
               
      FOR SELECT ID, ACCOUNT, DEPT, COST,PROJECT,
               NOTE, REF, DB, CR, NUMBER
          FROM GLBUFFER
         WHERE APPLICATION = :APPLICATION
           AND SOURCE = :SOURCE
           AND TRANSDATE = :TRANSDATE
           AND STATUS = 'O'
          INTO vID, vACCOUNT, vDEPT, vCOST,vPROJECT,
               vNOTE, vREF, vDB, vCR, NUMBER
      DO
      BEGIN
         if (vFirstRow = 0) then
         begin
           INSERT INTO GLTRANS (PYEAR, PMONTH, TRANSNO, DOCUMENT, JURCODE,
                  TRANSDATE, STATUS, REFACCOUNT,
                  APPLICATION, SOURCE, SOURCENUMBER, DB, CR, RELATION_DOCTYPE)
           VALUES (:PYEAR, :PMONTH, :vTransNo, :DOCUMENT, :vJurCode,
               :TransDate, 'H', '', :Application, :Source, :Number, 0, 0, :DOCTYPE);
        end

        IF (NOT EXISTS(select * from glcoa where account = :vAccount)) then vAccount = '?';
        IF (NOT EXISTS(select * from gldept where depart = :vDept)) then vDept = '0000';
        IF (NOT EXISTS(select * from glcost where cost = :vCost)) then vCost = '0000';

        if ((vDB <> 0) or (vCR <> 0)) then
        begin
           insert into gljur(PYEAR, PMONTH, TRANSNO,
                ACCOUNT, DEPART, COST, PROJECT,
                NOTE, REFACCOUNT, JURDATE, REF, DB, CR,
                APPLICATION, SOURCE, SOURCENUMBER)
           VALUES (:PYEAR, :PMONTH, :vTransNo,
                :vAccount, :vDept, :vCost, :vProject,
                :vNote, '', 'NOW', :vRef, :vDB, :vCR,
                :Application, :Source, :Number);
        end
        vFirstRow = vFirstRow + 1;    
     END
     /* ------------------------------------------------------------------------ */
     /* set status GLBUFFER menjadi menjadi close                                */
     /* ------------------------------------------------------------------------ */
     UPDATE GLBUFFER SET STATUS = 'C'
      WHERE APPLICATION = :APPLICATION
        AND SOURCE = :SOURCE
        AND TRANSDATE = :TRANSDATE;
   end
   /* -------------------------------------------------------------------------- */
   /* SUMMARY import from glbuffer                                               */
   /* -------------------------------------------------------------------------- */
   if (vImportType = 'SUM') then
   begin
      SELECT DISTINCT MAX(RELATION_DOCTYPE) FROM GLBUFFER
      WHERE APPLICATION = :APPLICATION AND SOURCE = :SOURCE
      AND TRANSDATE = :TRANSDATE INTO DOCTYPE;
           
      IF (DOCTYPE IS NULL) THEN DOCTYPE = 0;
     
      FOR SELECT ACCOUNT, DEPT, COST, PROJECT, SUM(DB), SUM(CR)
            FROM GLBUFFER
           WHERE APPLICATION = :APPLICATION
             AND SOURCE = :SOURCE
             AND TRANSDATE = :TRANSDATE
             AND STATUS = 'O'
        GROUP BY ACCOUNT, DEPT, COST, PROJECT
            INTO vACCOUNT, vDEPT, vCOST, vPROJECT, vDB, vCR
      DO
      BEGIN
        if (vFirstRow = 0) then
        begin
          INSERT INTO GLTRANS
          (PYEAR, PMONTH, TRANSNO, DOCUMENT, JURCODE,
           TRANSDATE, STATUS, REFACCOUNT,
           APPLICATION, SOURCE, SOURCENUMBER, DB, CR, RELATION_DOCTYPE)
          VALUES
          (:PYEAR, :PMONTH, :vTransNo, :DOCUMENT, :vJurCode,
           :TransDate, 'H', '', :Application, :Source, 0, 0, 0, :DOCTYPE);
        end

        IF (NOT EXISTS(select * from glcoa where account = :vAccount)) then vAccount = '?';
        IF (NOT EXISTS(select * from gldept where depart = :vDept)) then vDept = '0000';
        IF (NOT EXISTS(select * from glcost where cost = :vCost)) then vCost = '0000';

        if ((vDB <> 0) or (vCR <> 0)) then
        begin
           insert into gljur
               (PYEAR, PMONTH, TRANSNO,
                ACCOUNT, DEPART, COST, PROJECT,
                NOTE, REFACCOUNT, JURDATE, REF, DB, CR,
                APPLICATION, SOURCE, SOURCENUMBER)
           VALUES (:PYEAR, :PMONTH, :vTransNo,
                :vAccount, :vDept, :vCost, :vProject,
                :vNote, '', 'NOW', :vRef, :vDB, :vCR,
                :Application, :Source, 0);
        end
        vFirstRow = vFirstRow + 1;    
      END
      /* ------------------------------------------------------------------------ */
      /* set status GLBUFFER menjadi menjadi close                                */
      /* ------------------------------------------------------------------------ */
      UPDATE GLBUFFER SET STATUS = 'C'  
       WHERE APPLICATION = :APPLICATION
         AND SOURCE = :SOURCE
         AND TRANSDATE = :TRANSDATE;
  end /* END OF SUMMARY IMPORT */
end^


ALTER PROCEDURE GL_IMPORT_VALID(
    APPLICATION VARCHAR(4),
    SOURCE VARCHAR(4),
    NUMBER INTEGER,
    TRANSDATE DATE)
RETURNS (
    RAPPLICATION VARCHAR(4),
    RSOURCE VARCHAR(4),
    RNUMBER INTEGER,
    RACCOUNT VARCHAR(20),
    RDEPT VARCHAR(4),
    RCOST VARCHAR(4),
    RTRANSDATE DATE,
    RERRORMSG VARCHAR(60))
AS
declare variable vImportType VARCHAR(4);
DECLARE VARIABLE JURCODE VARCHAR(4);
begin
   IF (APPLICATION IS NULL) THEN
   BEGIN
      APPLICATION = 'FO';
      SOURCE = 'IC';
      TRANSDATE = '1.7.2005';
      NUMBER = 0;
   END

   SELECT ImportType, JURCODE from glimport
    where Application = :Application and Source = :Source
     into :vImportType, JURCODE;
     
   RTRANSDATE = TRANSDATE;
   RAPPLICATION = APPLICATION;
   RSOURCE = SOURCE;
   /* -------------------------------------------------------------------------- */
   /* Check Journal Code for Import                                              */
   /* -------------------------------------------------------------------------- */   
   IF (NOT EXISTS (SELECT * FROM GLJURCODE WHERE JURCODE = :JURCODE)) THEN
   BEGIN
      IF (JURCODE IS NULL) THEN JURCODE = '';
      RACCOUNT = 'JURCODE';
      RDEPT = '';
      RCOST = '';
      Rerrormsg = 'Journal Code "'|| JURCODE || '" not exists, check G/L Parameter Setup';
      SUSPEND;
   END   
   /* -------------------------------------------------------------------------- */
   /* Check for journal peridode                                                 */
   /* -------------------------------------------------------------------------- */   
   IF (NOT EXISTS (SELECT * FROM GLPERIOD WHERE :TRANSDATE BETWEEN DATE_START AND DATE_END)) THEN 
   BEGIN
      RACCOUNT = 'PERIOD';
      RDEPT = '';
      RCOST = '';
      Rerrormsg = 'Period '|| TRANSDATE || ' not exists, check GL Trans Period Setup';
      SUSPEND;
   END      
   /* -------------------------------------------------------------------------- */
   /* Check for account, department, cost center                                 */
   /* -------------------------------------------------------------------------- */     
   FOR SELECT NUMBER, ACCOUNT, DEPT, COST
         FROM GLBUFFER
        WHERE APPLICATION = :APPLICATION
          AND SOURCE = :SOURCE
          AND TRANSDATE = :TRANSDATE
         INTO :RNUMBER, :RACCOUNT, :RDEPT, :RCOST
   DO
   BEGIN
     IF (NOT EXISTS(select * from glcoa where account = :RAccount)) then
     begin
        Rerrormsg = 'Account does not exist';
        suspend;
     end

     IF (NOT EXISTS(select count(*) from gldept where depart = :RDept)) THEN
     begin
        Rerrormsg = 'Department does not exist';
        suspend;
     end

     IF (NOT EXISTS(select * from glcoadept where depart = :RDept and account = :RAccount)) THEN
     begin
        Rerrormsg = 'Department is not valid for this Account';
        suspend;
     end

     IF (NOT EXISTS(select * from glcost where cost = :RCost)) THEN
     begin
        Rerrormsg = 'Cost Center does not exist';
        suspend;
     end
    
     IF (NOT EXISTS(select * from glcoacost where cost = :Rcost and account = :RAccount)) THEN
     begin
        Rerrormsg = 'Cost Center is not valid for this Account';
        suspend;
     end
   END
end^


ALTER PROCEDURE GL_POST(
    STATUS CHAR(1),
    USRID VARCHAR(8))
AS
DECLARE VARIABLE PYEAR INTEGER;
DECLARE VARIABLE PMONTH INTEGER;
DECLARE VARIABLE ACCOUNT VARCHAR(20);
DECLARE VARIABLE DEPART VARCHAR(4);
DECLARE VARIABLE COST VARCHAR(4);
DECLARE VARIABLE DB DOUBLE PRECISION;
DECLARE VARIABLE CR DOUBLE PRECISION;
/* 25 JANUARI 2007 */
DECLARE VARIABLE PROFIT DOUBLE PRECISION;
DECLARE VARIABLE GLCUREARN VARCHAR(20);
declare variable DEFA_COST VARCHAR(4);
declare variable DEFA_DEPT VARCHAR(4);
BEGIN
  /* ------------------------------------------------------------------------
    8 SEPTEMBER 2005
    POSTING TRANSAKSI BIAR LEBIH CEPAT
    SEBELUM MENJALANKAN TRIGGER GLTRANS_BUPDATE DI INACTIVE KAN
    SETELAH MENJALANKAN TRINGGER GLTRANS_BUPDATE DI ACTIVE KAN
  ------------------------------------------------------------------------ */
  SELECT GLYEAR, GLMONTH, GLCUREARN FROM SYSPARAM WHERE ID = 1
  INTO PYEAR, PMONTH, ACCOUNT;
  /* ------------------------------------------------------------------------ */
  /* OPEN TRANSACATION                                                        */
  /* ------------------------------------------------------------------------ */
  IF (STATUS = 'R') THEN
  BEGIN
     UPDATE GLACC SET DB = 0, CR = 0
     WHERE PYEAR = :PYEAR
     AND PMONTH = :PMONTH;

     UPDATE GLTRANS SET STATUS = 'R', EDITUSER = :USRID, EDITDATE = 'NOW'
     WHERE PYEAR = :PYEAR
     AND PMONTH = :PMONTH
     AND STATUS <> 'R';

     UPDATE GLACC SET DB = 0, CR = 0  /* CLEAR RETURN EARNING */
     WHERE PYEAR = :PYEAR
     AND PMONTH = :PMONTH
     AND ACCOUNT = :ACCOUNT;
     EXIT;
  END
  IF (STATUS <> 'P') THEN EXIT;
  /* ------------------------------------------------------------------------ */
  /* POST  TRANSACATION                                                       */
  /* ------------------------------------------------------------------------ */
  UPDATE GLTRANS SET STATUS = 'P', EDITUSER = :USRID, EDITDATE = 'NOW',
         POSTEDUSER = :USRID, POSTEDDATE = 'NOW'
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND STATUS = 'R';
  /* ------------------------------------------------------------------------ */
  /* UPDATE GLACC                                                             */
  /* ------------------------------------------------------------------------ */
  FOR SELECT J.ACCOUNT, J.DEPART, J.COST, SUM(J.DB), SUM(J.CR)
      FROM GLJUR J
      INNER JOIN GLTRANS H ON H.PYEAR = J.PYEAR AND H.PMONTH = J.PMONTH AND H.TRANSNO = J.TRANSNO
      WHERE J.PYEAR = :PYEAR
      AND J.PMONTH = :PMONTH
      AND H.STATUS = 'P'
      GROUP BY J.ACCOUNT, J.DEPART, J.COST
  INTO ACCOUNT, DEPART, COST, DB, CR
  DO
  BEGIN
     IF (NOT (EXISTS(SELECT * FROM GLACC WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
              AND ACCOUNT = :ACCOUNT AND DEPART = :DEPART AND COST = :COST))) THEN
     BEGIN
        INSERT INTO GLACC
        (PYEAR, PMONTH, ACCOUNT, DEPART, COST, DB, CR, OPENING, BUDGET)
        VALUES
        (:PYEAR, :PMONTH, :ACCOUNT, :DEPART, :COST, 0,0,0,0);
     END

     UPDATE GLACC SET DB = :DB, CR = :CR
     WHERE PYEAR = :PYEAR
     AND PMONTH = :PMONTH
     AND ACCOUNT = :ACCOUNT
     AND DEPART = :DEPART
     AND COST = :COST;
  END
  /* ---------------------------------------------------------------- */
  /* CURRENT EARNING                                                  */
  /* ---------------------------------------------------------------- */
  
  SELECT SUM(A.CR-A.DB) FROM GLACC A
  LEFT JOIN GLCOA C ON C.ACCOUNT = A.ACCOUNT
  WHERE A.PYEAR = :PYEAR
  AND A.PMONTH = :PMONTH
  AND C.ACCTYPE IN ('I','C')
  INTO PROFIT;
  
  select GLCUREARN, GL_DEFAULT_COST, GL_DEFAULT_DEPT from sysparam
  into GLCUREARN, DEFA_COST, DEFA_DEPT;

  if (NOT EXISTS(SELECT * FROM GLACC
                 where pyear = :PYEAR
                 AND pmonth = :PMONTH
                 AND account = :GLCUREARN
                 and depart = :DEFA_DEPT
                 and cost = :DEFA_COST)) then
  BEGIN
     INSERT INTO GLACC
     (PYEAR, PMONTH, ACCOUNT, DEPART, COST, OPENING, DB, CR)
     VALUES
     (:PYEAR, :PMONTH, :GLCUREARN, :DEFA_DEPT,:DEFA_COST, 0, 0, 0);
  END


  UPDATE glacc set CR = :PROFIT
  where pyear = :PYEAR
  AND pmonth = :PMONTH
  AND account = :GLCUREARN
  and depart = :DEFA_DEPT
  and cost = :DEFA_COST;
  /* ---------------------------------------------------------------- */
  
  
  
  
  
  
  
  
  
  
  
  
END^


ALTER PROCEDURE GL_POST_RECALC_EARNING(
    PYEAR INTEGER,
    PMONTH INTEGER)
AS
DECLARE VARIABLE PROFIT DOUBLE PRECISION;
DECLARE VARIABLE GLCUREARN VARCHAR(20);
declare variable DEFA_COST VARCHAR(4);
declare variable DEFA_DEPT VARCHAR(4);
BEGIN
  /* ---------------------------------------------------------------- */
  /* 27 JANUARI 2007                                                  */
  /* RECALCULATE RETURN EARNING                                       */
  /* ---------------------------------------------------------------- */
  SELECT SUM(A.CR-A.DB) FROM GLACC A
  LEFT JOIN GLCOA C ON C.ACCOUNT = A.ACCOUNT
  WHERE A.PYEAR = :PYEAR
  AND A.PMONTH = :PMONTH
  AND C.ACCTYPE IN ('I','C')
  INTO PROFIT;
  
  select GLCUREARN, GL_DEFAULT_COST, GL_DEFAULT_DEPT from sysparam
  into GLCUREARN, DEFA_COST, DEFA_DEPT;

  if (NOT EXISTS(SELECT * FROM GLACC
                 where pyear = :PYEAR
                 AND pmonth = :PMONTH
                 AND account = :GLCUREARN
                 and depart = :DEFA_DEPT
                 and cost = :DEFA_COST)) then
  BEGIN
     INSERT INTO GLACC
     (PYEAR, PMONTH, ACCOUNT, DEPART, COST, OPENING, DB, CR)
     VALUES
     (:PYEAR, :PMONTH, :GLCUREARN, :DEFA_DEPT,:DEFA_COST, 0, 0, 0);
  END


  UPDATE glacc set CR = :PROFIT
  where pyear = :PYEAR
  AND pmonth = :PMONTH
  AND account = :GLCUREARN
  and depart = :DEFA_DEPT
  and cost = :DEFA_COST;
END^


ALTER PROCEDURE GL_RCURR_CREATE_SCHEDULE(
    AYEAR INTEGER,
    AMONTH INTEGER,
    AUSER VARCHAR(8))
RETURNS (
    RCURR_ID INTEGER,
    PYEAR INTEGER,
    PMONTH INTEGER,
    PMONTH_COUNTER INTEGER,
    STATUS CHAR(1),
    DOCUMENT VARCHAR(20),
    JURCODE VARCHAR(4),
    NOTE VARCHAR(40),
    GLTRANS_NUMBER INTEGER)
AS
declare variable X INTEGER;
BEGIN
  if (AYEAR IS NULL) then
  BEGIN
    SELECT GLYEAR, GLMONTH FROM SYSPARAM WHERE ID = 1
    INTO AYEAR, AMONTH;
    AYEAR = 2000;
    AMONTH = 8;
  END
  /*  */
  FOR
    SELECT RCURR_ID, PYEAR, PMONTH, PMONTH_COUNTER, STATUS,
    DOCUMENT, NOTE, JURCODE
    FROM gl_rcurr_trans
    WHERE STATUS = 'A'
    INTO
      :RCURR_ID,
      :PYEAR,
      :PMONTH,
      :PMONTH_COUNTER,
      :STATUS,
      :DOCUMENT,
      :NOTE,
      :JURCODE
  DO
  BEGIN
    SELECT COUNT(*) FROM gl_rcurr_schedule
    WHERE PYEAR = :AYEAR
    AND PMONTH = :AMONTH
    AND RCURR_ID = :RCURR_ID
    INTO X;
    if (X = 0) then
    BEGIN
       if ((AYEAR * 12 + AMONTH) < (PYEAR * 12+PMONTH+PMONTH_COUNTER)) then
       BEGIN
         INSERT INTO GL_RCURR_SCHEDULE
         (RCURR_ID, PYEAR, PMONTH, STATUS, DOCUMENT, NOTE,
          CREATEDATE, CREATEUSER, EDITDATE, EDITUSER, GLTRANS_NUMBER)
         VALUES
         (:RCURR_ID, :AYEAR, :AMONTH, 'O', :DOCUMENT, :NOTE,
          'NOW', :AUSER, 'NOW', :AUSER, 0);
       END
    END
  END
  
  
  FOR SELECT RCURR_ID,
             PYEAR,
             PMONTH,
             STATUS,
             DOCUMENT,
             JURCODE,
             NOTE,
             GLTRANS_NUMBER
      FROM GL_RCURR_SCHEDULE
      INTO :RCURR_ID,
           :PYEAR,
           :PMONTH,
           :STATUS,
           :DOCUMENT,
           :JURCODE,
           :NOTE,
           :GLTRANS_NUMBER
  DO
      BEGIN
        SUSPEND;
      END
END^


ALTER PROCEDURE GL_RPT_BALANCE_SHEET(
    PMONTH INTEGER,
    PYEAR INTEGER)
RETURNS (
    ACCTYPE VARCHAR(1),
    ACCOUNT VARCHAR(20),
    ACCNAME VARCHAR(80),
    ACCSHORTNAME VARCHAR(12),
    ACCLEVEL INTEGER,
    HEADER CHAR(1),
    MTD DOUBLE PRECISION,
    LTD DOUBLE PRECISION)
AS
declare variable vLMONTH integer;
declare variable vLYEAR integer;
declare variable vMTD1 double precision;
declare variable vMTD2 double precision;
declare variable vMTD3 double precision;
declare variable vMTD4 double precision;
declare variable vMTD5 double precision;
declare variable vLTD1 double precision;
declare variable vLTD2 double precision;
declare variable vLTD3 double precision;
declare variable vLTD4 double precision;
declare variable vLTD5 double precision;
begin
vLYEAR = PYEAR;
vLMONTH = PMONTH - 1;
vMTD1 = 0; vMTD2 = 0; vMTD3 = 0; vMTD4 = 0; vMTD5 = 0;
vLTD1 = 0; vLTD2 = 0; vLTD3 = 0; vLTD4 = 0; vLTD5 = 0;
if (vLMONTH < 1) then
begin
  vLYEAR = vLYEAR-1;
  vLMONTH = 12;
end

FOR SELECT
       GLCOA.ACCTYPE,
       GLCOA.ACCOUNT,
       GLCOA.DISPLAYNAME AccName,
       GLCOA.SHORTNAME AccShortName,
       GLCOA.acclevel,
       GLCOA.header
FROM GLCOA
WHERE ACCTYPE IN ('A', 'P')
GROUP BY GLCOA.ACCTYPE, GLCOA.ACCOUNT,
         GLCOA.DISPLAYNAME, GLCOA.SHORTNAME,
         GLCOA.acclevel, GLCOA.header
ORDER BY GLCOA.ACCOUNT

INTO ACCTYPE, ACCOUNT,
     AccName, AccShortName,
     AccLevel, Header

  DO
  BEGIN
    if (Header = 'H') then
    begin
       MTD = 0;
       LTD = 0;
    end
    if (Header = 'D') then
    begin
       SELECT SUM(GLACC.ENDING) FROM GLACC
        WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH AND GLACC.ACCOUNT = :ACCOUNT
        PLAN (GLACC INDEX (GLACC_IDX_COST))
         INTO MTD;
          
       SELECT SUM(GLACC.ENDING) FROM GLACC
        WHERE PYEAR = :vLYEAR AND PMONTH = :vLMONTH AND GLACC.ACCOUNT = :ACCOUNT
        PLAN (GLACC INDEX (GLACC_IDX_COST))
         INTO LTD;
          
      if (MTD is null) then MTD = 0;
      if (LTD is null) then LTD = 0;

      if (acclevel >= 1) then
      begin
         vMTD1 = vMTD1 + MTD;
         vLTD1 = vLTD1 + LTD;
      end
      if (acclevel >= 2) then
      begin
         vMTD2 = vMTD2 + MTD;
         vLTD2 = vLTD2 + LTD;
      end
      if (acclevel >= 3) then
      begin
         vMTD3 = vMTD3 + MTD;
         vLTD3 = vLTD3 + LTD;
      end
      if (acclevel >= 4) then
      begin
         vMTD4 = vMTD4 + MTD;
         vLTD4 = vLTD4 + LTD;
      end
      if (acclevel >= 5) then
      begin
         vMTD5 = vMTD5 + MTD;
         vLTD5 = vLTD5 + LTD;
      end
    end
    if (Header = 'T') then
    begin
      if (acclevel = 1) then
      begin
         MTD   = vMTD1;
         LTD   = vLTD1;
         vMTD1 = 0; vMTD2 = 0; vMTD3 = 0; vMTD4 = 0; vMTD5 = 0;
         vLTD1 = 0; vLTD2 = 0; vLTD3 = 0; vLTD4 = 0; vLTD5 = 0;
      end
      if (acclevel = 2) then
      begin
         MTD   = vMTD2;
         LTD   = vLTD2;
         vMTD2 = 0; vMTD3 = 0; vMTD4 = 0; vMTD5 = 0;
         vLTD2 = 0; vLTD3 = 0; vLTD4 = 0; vLTD5 = 0;
      end
      if (acclevel = 3) then
      begin
         MTD   = vMTD3;
         LTD   = vLTD3;
         vMTD3 = 0; vMTD4 = 0; vMTD5 = 0;
         vLTD3 = 0; vLTD4 = 0; vLTD5 = 0;
      end
      if (acclevel = 4) then
      begin
         MTD   = vMTD4;
         LTD   = vLTD4;
         vMTD4 = 0; vMTD5 = 0;
         vLTD4 = 0; vLTD5 = 0;
      end                  
      if (acclevel >= 5) then
      begin
         MTD    = vMTD5;
         LTD    = vLTD5;
         vMTD5  = 0;
         vLTD5  = 0;
      end      
    end
    if ((MTD <> 0) or (LTD <>0)) then
       if (Account <> '?')   then suspend;
  END
end^


ALTER PROCEDURE GL_RPT_BALANCE_SHEET_NORMAL(
    PMONTH INTEGER,
    PYEAR INTEGER)
RETURNS (
    ACCTYPE VARCHAR(1),
    ACCOUNT VARCHAR(20),
    ACCNAME VARCHAR(80),
    ACCSHORTNAME VARCHAR(12),
    ACCLEVEL INTEGER,
    HEADER CHAR(1),
    MTD DOUBLE PRECISION,
    LTD DOUBLE PRECISION)
AS
declare variable vlmonth integer;
declare variable vlyear integer;
declare variable vmtd1 double precision;
declare variable vmtd2 double precision;
declare variable vmtd3 double precision;
declare variable vmtd4 double precision;
declare variable vmtd5 double precision;
declare variable vltd1 double precision;
declare variable vltd2 double precision;
declare variable vltd3 double precision;
declare variable vltd4 double precision;
declare variable vltd5 double precision;
begin
vLYEAR = PYEAR;
vLMONTH = PMONTH - 1;
vMTD1 = 0; vMTD2 = 0; vMTD3 = 0; vMTD4 = 0; vMTD5 = 0;
vLTD1 = 0; vLTD2 = 0; vLTD3 = 0; vLTD4 = 0; vLTD5 = 0;
if (vLMONTH < 1) then
begin
  vLYEAR = vLYEAR-1;
  vLMONTH = 12;
end

FOR SELECT
       GLCOA.ACCTYPE,
       GLCOA.ACCOUNT,
       GLCOA.DISPLAYNAME AccName,
       GLCOA.SHORTNAME AccShortName,
       GLCOA.acclevel,
       GLCOA.header
FROM GLCOA
WHERE ACCTYPE IN ('A','P')
AND HEADER='D'
GROUP BY GLCOA.ACCTYPE,GLCOA.ACCOUNT,
         GLCOA.DISPLAYNAME,GLCOA.SHORTNAME,
         GLCOA.acclevel,GLCOA.header
ORDER BY GLCOA.ACCOUNT

INTO ACCTYPE,ACCOUNT,
     AccName,AccShortName,
     AccLevel,Header

  DO
  BEGIN
    if (Header = 'H') then
    begin
       MTD = 0;
       LTD = 0;
    end
    if (Header = 'D') then
    begin
       SELECT SUM(GLACC.ENDING) FROM GLACC
        WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH AND GLACC.ACCOUNT = :ACCOUNT
        PLAN (GLACC INDEX (GLACC_IDX_COST))
         INTO MTD;
          
       SELECT SUM(GLACC.ENDING) FROM GLACC
        WHERE PYEAR = :vLYEAR AND PMONTH = :vLMONTH AND GLACC.ACCOUNT = :ACCOUNT
        PLAN (GLACC INDEX (GLACC_IDX_COST))
         INTO LTD;
          
      if (MTD is null) then MTD = 0;
      if (LTD is null) then LTD = 0;

      if (acclevel >= 1) then
      begin
         vMTD1 = vMTD1 + MTD;
         vLTD1 = vLTD1 + LTD;
      end
      if (acclevel >= 2) then
      begin
         vMTD2 = vMTD2 + MTD;
         vLTD2 = vLTD2 + LTD;
      end
      if (acclevel >= 3) then
      begin
         vMTD3 = vMTD3 + MTD;
         vLTD3 = vLTD3 + LTD;
      end
      if (acclevel >= 4) then
      begin
         vMTD4 = vMTD4 + MTD;
         vLTD4 = vLTD4 + LTD;
      end
      if (acclevel >= 5) then
      begin
         vMTD5 = vMTD5 + MTD;
         vLTD5 = vLTD5 + LTD;
      end
    end
    if (Header = 'T') then
    begin
      if (acclevel = 1) then
      begin
         MTD   = vMTD1;
         LTD   = vLTD1;
         vMTD1 = 0; vMTD2 = 0; vMTD3 = 0; vMTD4 = 0; vMTD5 = 0;
         vLTD1 = 0; vLTD2 = 0; vLTD3 = 0; vLTD4 = 0; vLTD5 = 0;
      end
      if (acclevel = 2) then
      begin
         MTD   = vMTD2;
         LTD   = vLTD2;
         vMTD2 = 0; vMTD3 = 0; vMTD4 = 0; vMTD5 = 0;
         vLTD2 = 0; vLTD3 = 0; vLTD4 = 0; vLTD5 = 0;
      end
      if (acclevel = 3) then
      begin
         MTD   = vMTD3;
         LTD   = vLTD3;
         vMTD3 = 0; vMTD4 = 0; vMTD5 = 0;
         vLTD3 = 0; vLTD4 = 0; vLTD5 = 0;
      end
      if (acclevel = 4) then
      begin
         MTD   = vMTD4;
         LTD   = vLTD4;
         vMTD4 = 0; vMTD5 = 0;
         vLTD4 = 0; vLTD5 = 0;
      end                  
      if (acclevel >= 5) then
      begin
         MTD    = vMTD5;
         LTD    = vLTD5;
         vMTD5  = 0;
         vLTD5  = 0;
      end      
    end
    if ((MTD <> 0) or (LTD <>0)) then
       if (Account <> '?')   then suspend;
  END
end^


