ALTER PROCEDURE GL_RPT_DETAIL_LEDGER(
    SDATE DATE,
    EDATE DATE,
    SACCOUNT VARCHAR(20),
    EACCOUNT VARCHAR(20),
    SDEPT VARCHAR(4),
    EDEPT VARCHAR(4),
    SCOST VARCHAR(4),
    ECOST VARCHAR(4))
RETURNS (
    PYEAR INTEGER,
    PMONTH INTEGER,
    TRANSNO INTEGER,
    ACCOUNT VARCHAR(20),
    DEPART VARCHAR(4),
    COST VARCHAR(4),
    PROJECT VARCHAR(8),
    OPENING DOUBLE PRECISION,
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION,
    NOTE VARCHAR(40),
    REFACCOUNT VARCHAR(20),
    REFDEPT VARCHAR(4),
    REFCOST VARCHAR(4),
    JURDATE DATE,
    REF VARCHAR(20),
    CREATEDATE DATE,
    EDITDATE DATE,
    CREATEUSER VARCHAR(8),
    EDITUSER VARCHAR(8),
    SOURCE VARCHAR(4),
    SOURCENUMBER INTEGER,
    APPLICATION VARCHAR(4),
    TRANSDATE DATE,
    JURCODE VARCHAR(4),
    ACCOUNT_NAME VARCHAR(40),
    DEPART_NAME VARCHAR(40),
    COST_NAME VARCHAR(40),
    DOCUMENT VARCHAR(20))
AS
declare variable XACCOUNT VARCHAR(40);
declare variable ZACCOUNT VARCHAR(44);
declare variable ACCTYPE CHAR(1);
declare variable XYEAR INTEGER;
declare variable XMONTH INTEGER;
declare variable XDB DOUBLE PRECISION;
declare variable XCR DOUBLE PRECISION;
declare variable XBOM DATE;
DECLARE VARIABLE XDAY INTEGER;
BEGIN
  if (SACCOUNT IS NULL) then
  BEGIN
     SACCOUNT = '111-301';
     EACCOUNT = '111-301';
     SDATE    = '25.4.2011';
     EDATE    = '24.5.2011';
     SDEPT    = '5000';
     EDEPT    = '5000';
     SCOST    = '5001';
     ECOST    = '5001';
  END

  execute procedure SP_DATE_BOM(SDATE) returning_values XBOM;
  EXECUTE PROCEDURE SP_DATE_DECODE(XBOM) RETURNING_VALUES(XYEAR, XMONTH, XDAY);
  
  XACCOUNT = '?';
  OPENING  =  0;
  FOR SELECT JR.PYEAR,
             JR.PMONTH,
             JR.TRANSNO,
             JR.ACCOUNT,
             JR.DEPART,
             JR.COST,
             JR.PROJECT,
             JR.NOTE,
             JR.REFACCOUNT,
             JR.REFDEPT,
             JR.REFCOST,
             JR.JURDATE,
             JR.REF,
             JR.DB,
             JR.CR,
             JR.CREATEDATE,
             JR.EDITDATE,
             JR.CREATEUSER,
             JR.EDITUSER,
             JR.SOURCE,
             JR.SOURCENUMBER,
             JR.APPLICATION,
             TRN.TRANSDATE,
             TRN.JURCODE,
             TRN.DOCUMENT
      FROM GLJUR JR
      LEFT JOIN GLTRANS TRN ON
               (TRN.PYEAR = JR.PYEAR) AND
               (TRN.PMONTH=JR.PMONTH) AND
               (TRN.TRANSNO=JR.TRANSNO)
      WHERE JR.ACCOUNT BETWEEN :SACCOUNT AND :EACCOUNT
      AND JR.DEPART BETWEEN :SDEPT AND :EDEPT
      AND JR.COST BETWEEN :SCOST AND :ECOST
      AND TRN.TRANSDATE BETWEEN :SDATE AND :EDATE
      AND TRN.STATUS = 'P'
      ORDER BY JR.ACCOUNT, JR.DEPART, JR.COST, TRN.TRANSDATE
      INTO :PYEAR,
           :PMONTH,
           :TRANSNO,
           :ACCOUNT,
           :DEPART,
           :COST,
           :PROJECT,
           :NOTE,
           :REFACCOUNT,
           :REFDEPT,
           :REFCOST,
           :JURDATE,
           :REF,
           :DB,
           :CR,
           :CREATEDATE,
           :EDITDATE,
           :CREATEUSER,
           :EDITUSER,
           :SOURCE,
           :SOURCENUMBER,
           :APPLICATION,
           :TRANSDATE,
           :JURCODE,
           :DOCUMENT
  DO BEGIN
     ZACCOUNT = ACCOUNT ||'-'||DEPART||'-'||COST;
     if (XACCOUNT <> ZACCOUNT) then
     BEGIN
        SELECT ACCTYPE, NAME FROM GLCOA
        WHERE ACCOUNT = :ACCOUNT
        INTO ACCTYPE, ACCOUNT_NAME;
        
        SELECT NAME FROM glcost
        WHERE COST = :COST
        INTO COST_NAME;
        
        SELECT NAME FROM gldept
        WHERE DEPART = :DEPART
        INTO DEPART_NAME;

        BALANCE = 0;

        SELECT OPENING FROM GLACC
        WHERE PYEAR = :XYEAR
        AND PMONTH = :XMONTH
        AND ACCOUNT = :ACCOUNT
        AND DEPART = :DEPART
        AND COST = :COST
        INTO BALANCE;

        if (BALANCE IS NULL) then BALANCE = 0;
        
        SELECT SUM(JR.DB), SUM(JR.CR)
          FROM GLJUR JR
          LEFT JOIN GLTRANS TRN ON
               (TRN.PYEAR = JR.PYEAR) AND
               (TRN.PMONTH=JR.PMONTH) AND
               (TRN.TRANSNO=JR.TRANSNO)
          WHERE JR.ACCOUNT = :ACCOUNT
          AND JR.DEPART = :DEPART
          AND JR.COST = :COST
          AND TRN.TRANSDATE BETWEEN :XBOM AND :SDATE-1
          AND TRN.STATUS = 'P'
          INTO :XDB, :XCR;
          
          if (XDB IS NULL) then
          BEGIN
             XDB = 0;
             XCR = 0;
          END

          if (ACCTYPE IN ('A','C')) then BALANCE = BALANCE + XDB - XCR;
          ELSE BALANCE = BALANCE - XDB + XCR;
          OPENING = BALANCE;
     END
     XACCOUNT = ZACCOUNT;
     if (ACCTYPE IN ('A','C')) then BALANCE = BALANCE + DB - CR;
     ELSE BALANCE = BALANCE - DB + CR;
     SUSPEND;
     OPENING = BALANCE;
  END
END^


ALTER PROCEDURE GL_RPT_INCOME_SUMMARY(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    COST VARCHAR(4),
    NAME VARCHAR(40),
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    AMOUNT DOUBLE PRECISION,
    LM_DB DOUBLE PRECISION,
    LM_CR DOUBLE PRECISION,
    LM DOUBLE PRECISION,
    MTD_DB DOUBLE PRECISION,
    MTD_CR DOUBLE PRECISION,
    MTD DOUBLE PRECISION)
AS
BEGIN
  if (PYEAR IS NULL) then
  BEGIN
    PYEAR = 2004;
    PMONTH = 9;
  END
  FOR
    SELECT COST, NAME FROM GLCOST
    ORDER BY COST
    INTO
      :COST,
      :NAME
  DO
  BEGIN
    SELECT SUM(DB), SUM(CR), SUM(CR-DB) FROM GLACC
    LEFT JOIN GLCOA ON GLCOA.ACCOUNT = GLACC.ACCOUNT
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND COST = :COST
    AND GLCOA.ACCTYPE IN ('I', 'C')
    INTO DB, CR, AMOUNT;

    if (AMOUNT IS NULL) then
    BEGIN
       DB = 0;
       CR = 0;
       AMOUNT = 0;
    END
        
    SELECT SUM(DB), SUM(CR), SUM(CR-DB) FROM GLACC
    LEFT JOIN GLCOA ON GLCOA.ACCOUNT = GLACC.ACCOUNT
    WHERE PYEAR = :PYEAR
    AND COST = :COST    
    AND PMONTH < :PMONTH
    AND GLCOA.ACCTYPE IN ('I', 'C')
    INTO LM_DB, LM_CR, LM;
        
    if (LM IS NULL) then
    BEGIN
       LM_DB = 0;
       LM_CR = 0;
       LM = 0;
    END
    MTD_DB = LM_DB + DB;
    MTD_CR = LM_CR + CR;
    MTD    = LM + (CR-DB);
    
    if ((DB <> 0) or (CR <> 0) or (AMOUNT <> 0) or
        (MTD_DB <> 0) or (MTD_CR <> 0) or (MTD <> 0)) then
       SUSPEND;
  END
END^


ALTER PROCEDURE GL_RPT_LEDGER_BYCOST(
    PYEAR INTEGER,
    PMONTH INTEGER,
    SCOST VARCHAR(4),
    ECOST VARCHAR(4),
    SDEPT VARCHAR(4),
    EDEPT VARCHAR(4),
    SACCOUNT VARCHAR(8),
    EACCOUNT VARCHAR(8))
RETURNS (
    ACCOUNT VARCHAR(20),
    DEPART VARCHAR(4),
    COST VARCHAR(4),
    NAME VARCHAR(40),
    OPENING NUMERIC(15,4),
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    ENDING DOUBLE PRECISION,
    MUTATION DOUBLE PRECISION,
    ACCTYPE CHAR(1),
    REPORT CHAR(20),
    TYPENAME VARCHAR(40),
    COSTNAME VARCHAR(40),
    PROFIT DOUBLE PRECISION)
AS
declare variable MTD_DB DOUBLE PRECISION;
declare variable MTD_CR DOUBLE PRECISION;
BEGIN
  if (PYEAR IS NULL) then
  BEGIN
    PMONTH = 9;
    PYEAR  = 2004;
    SACCOUNT = '';
    EACCOUNT = '999999';
    SCOST    = '201';
    ECOST    = '201';
    SDEPT    = '10';
    EDEPT    = '10';
  END
  FOR
    SELECT JR.ACCOUNT,
           JR.DEPART,
           JR.COST,
           COA.NAME,
           JR.OPENING,
           JR.DB,
           JR.CR,
           JR.ENDING,
           JR.MUTATION,
           COA.ACCTYPE,
           TY.REPORT,
           TY.NAME TYPENAME,
           C.NAME COSTNAME
    FROM GLACC JR
    LEFT JOIN GLCOA COA ON JR.ACCOUNT = COA.ACCOUNT
    LEFT JOIN GLCOATYPE TY ON TY.ACCTYPE = COA.ACCTYPE
    LEFT JOIN GLCOST C ON C.COST = JR.COST
    WHERE PYEAR = :PYEAR
    AND JR.PMONTH = :PMONTH
    AND JR.ACCOUNT BETWEEN :SACCOUNT AND :EACCOUNT    
    AND JR.DEPART BETWEEN :SDEPT AND :EDEPT
    AND JR.COST BETWEEN :SCOST AND :ECOST
    AND COA.ACCTYPE <> 'S'
    ORDER BY JR.COST, TY.REPORT, TY.NUMBER, COA.ACCOUNT
    INTO
      :ACCOUNT,
      :DEPART,
      :COST,
      :NAME,
      :OPENING,
      :DB,
      :CR,
      :ENDING,
      :MUTATION,
      :ACCTYPE,
      :REPORT,
      :TYPENAME,
      :COSTNAME
  DO
  BEGIN
    if (REPORT = 'B') then
    begin
       REPORT = 'Balance Sheet';
       PROFIT = DB-CR;
    end
    ELSE
    begin
       SELECT SUM(ENDING) FROM GLACC
       WHERE PYEAR = :PYEAR
       AND ACCOUNT = :ACCOUNT
       AND DEPART = :DEPART
       AND COST = :COST
       AND PMONTH < :PMONTH
       INTO OPENING;
       if (MTD_DB IS NULL) then
       BEGIN
          MTD_DB = 0;
          MTD_CR = 0;
       END
       if (ACCTYPE = 'I') then
       BEGIN
          ENDING  = OPENING + CR - DB;
       END
       ELSE
       BEGIN
          ENDING  = OPENING + DB - CR;
       END
       REPORT = 'Income Statement';
       PROFIT = CR-DB;
    end
    SUSPEND;
  END
END^


ALTER PROCEDURE GL_RPT_PL(
    PMONTH INTEGER,
    PYEAR INTEGER)
RETURNS (
    ACCTYPE VARCHAR(1),
    ACCOUNT VARCHAR(20),
    ACCNAME VARCHAR(80),
    ACCSHORTNAME VARCHAR(12),
    ACCLEVEL INTEGER,
    HEADER CHAR(1),
    MTD NUMERIC(15,4),
    YTD NUMERIC(15,4),
    LMTD NUMERIC(15,4),
    LYTD NUMERIC(15,4))
AS
declare variable vLMONTH integer;
declare variable vLYEAR integer;
declare variable vMTD1 NUMERIC(15,4);
declare variable vMTD2 NUMERIC(15,4);
declare variable vMTD3 NUMERIC(15,4);
declare variable vMTD4 NUMERIC(15,4);
declare variable vMTD5 NUMERIC(15,4);
declare variable vLMTD1 NUMERIC(15,4);
declare variable vLMTD2 NUMERIC(15,4);
declare variable vLMTD3 NUMERIC(15,4);
declare variable vLMTD4 NUMERIC(15,4);
declare variable vLMTD5 NUMERIC(15,4);

declare variable vYTD1 NUMERIC(15,4);
declare variable vYTD2 NUMERIC(15,4);
declare variable vYTD3 NUMERIC(15,4);
declare variable vYTD4 NUMERIC(15,4);
declare variable vYTD5 NUMERIC(15,4);
declare variable vLYTD1 NUMERIC(15,4);
declare variable vLYTD2 NUMERIC(15,4);
declare variable vLYTD3 NUMERIC(15,4);
declare variable vLYTD4 NUMERIC(15,4);
declare variable vLYTD5 NUMERIC(15,4);


declare variable ProfitMTD NUMERIC(15,4);
declare variable ProfitYTD NUMERIC(15,4);
declare variable ProfitLMTD NUMERIC(15,4);
declare variable ProfitLYTD NUMERIC(15,4);
declare variable vFaktor integer;
begin
vLYEAR = PYEAR;
vLMONTH = PMONTH - 1;
vMTD1   = 0; vMTD2  = 0; vMTD3  = 0; vMTD4  = 0; vMTD5  = 0;
vLMTD1  = 0; vLMTD2 = 0; vLMTD3 = 0; vLMTD4 = 0; vLMTD5 = 0;
vYTD1   = 0; vYTD2  = 0; vYTD3  = 0; vYTD4  = 0; vYTD5  = 0;
vLYTD1  = 0; vLYTD2 = 0; vLYTD3 = 0; vLYTD4 = 0; vLYTD5 = 0;
ProfitMTD = 0; ProfitYTD = 0; ProfitLMTD = 0; ProfitLYTD = 0;
if (vLMONTH < 1) then
begin
  vLYEAR = vLYEAR-1;
  vLMONTH = 12;
end

FOR SELECT
       GLCOA.ACCTYPE,
       GLCOA.ACCOUNT,
       GLCOA.DISPLAYNAME AccName,
       GLCOA.SHORTNAME AccShortName,
       GLCOA.acclevel,
       GLCOA.header
FROM GLCOA
WHERE ACCTYPE IN ('I', 'C')
GROUP BY GLCOA.ACCTYPE, GLCOA.ACCOUNT,
         GLCOA.DISPLAYNAME, GLCOA.SHORTNAME,
         GLCOA.acclevel, GLCOA.header
ORDER BY GLCOA.ACCOUNT

INTO ACCTYPE, ACCOUNT,
     AccName, AccShortName,
     AccLevel, Header

  DO
  BEGIN
    if (Header = 'H') then
    begin
       MTD = 0;
       LMTD = 0;
       YTD = 0;
       LYTD = 0;
    end
    if (Header = 'D') then
    begin
       SELECT SUM(GLACC.ENDING) FROM GLACC
        WHERE PYEAR = :PYEAR
          AND PMONTH = :PMONTH
          AND GLACC.ACCOUNT = :ACCOUNT
        PLAN (GLACC INDEX (GLACC_IDX_COST))
         INTO MTD;
         
       SELECT SUM(GLACC.ENDING) FROM GLACC
        WHERE PYEAR = :PYEAR
          AND GLACC.ACCOUNT = :ACCOUNT        
          AND PMONTH BETWEEN 1 AND :PMONTH
          PLAN (GLACC INDEX (GLACC_IDX_YEAR_ACCOUNT))
         INTO YTD;
          
       SELECT SUM(GLACC.ENDING) FROM GLACC
        WHERE PYEAR = :vLYEAR
          AND PMONTH = :vLMONTH
          AND GLACC.ACCOUNT = :ACCOUNT
        PLAN (GLACC INDEX (GLACC_IDX_COST))
         INTO LMTD;
         
       SELECT SUM(GLACC.ENDING) FROM GLACC
        WHERE PYEAR = :vLYEAR
          AND GLACC.ACCOUNT = :ACCOUNT
          AND PMONTH BETWEEN 1 AND :PMONTH
          PLAN (GLACC INDEX (GLACC_IDX_YEAR_ACCOUNT))
         INTO LYTD;
          
      if (MTD  is null) then MTD = 0;
      if (LMTD is null) then LMTD = 0;
      if (YTD  is null) then YTD = 0;
      if (LYTD is null) then LYTD = 0;
      vFaktor = 1;
      if (AccType = 'C') then vFaktor = -1;
      
      ProfitMTD  = ProfitMTD + vFaktor  * MTD;
      ProfitYTD  = ProfitYTD + vFaktor  * YTD;
      ProfitLMTD = ProfitLMTD + vFaktor * LMTD;
      ProfitLYTD = ProfitLYTD + vFaktor * LYTD;
            
      if (acclevel >= 1) then
      begin
         vMTD1  = vMTD1  + MTD;
         vLMTD1 = vLMTD1 + LMTD;
         vYTD1  = vYTD1  + YTD;
         vLYTD1 = vLYTD1 + LYTD;
      end
      if (acclevel >= 2) then
      begin
         vMTD2  = vMTD2  + MTD;
         vLMTD2 = vLMTD2 + LMTD;
         vYTD2  = vYTD2  + YTD;
         vLYTD2 = vLYTD2 + LYTD;
      end
      if (acclevel >= 3) then
      begin
         vMTD3 = vMTD3 + MTD;
         vLMTD3 = vLMTD3 + LMTD;
         vYTD3  = vYTD3  + YTD;
         vLYTD3 = vLYTD3 + LYTD;
      end
      if (acclevel >= 4) then
      begin
         vMTD4 = vMTD4 + MTD;
         vLMTD4 = vLMTD4 + LMTD;
         vYTD4  = vYTD4  + YTD;
         vLYTD4 = vLYTD4 + LYTD;
      end
      if (acclevel >= 5) then
      begin
         vMTD5 = vMTD5 + MTD;
         vLMTD5 = vLMTD5 + LMTD;
         vYTD5  = vYTD5  + YTD;
         vLYTD5 = vLYTD5 + LYTD;
      end
    end
    if (Header = 'T') then
    begin
      if (acclevel = 1) then
      begin
         MTD   = vMTD1;
         LMTD  = vLMTD1;
         YTD   = vYTD1;
         LYTD  = vLYTD1;
                  
         vMTD1 = 0; vMTD2 = 0; vMTD3 = 0; vMTD4 = 0; vMTD5 = 0;
         vLMTD1 = 0; vLMTD2 = 0; vLMTD3 = 0; vLMTD4 = 0; vLMTD5 = 0;

         vYTD1 = 0; vYTD2 = 0; vYTD3 = 0; vYTD4 = 0; vYTD5 = 0;
         vLYTD1 = 0; vLYTD2 = 0; vLYTD3 = 0; vLYTD4 = 0; vLYTD5 = 0;
      end
      if (acclevel = 2) then
      begin
         MTD   = vMTD2;
         LMTD   = vLMTD2;
         YTD   = vYTD2;
         LYTD  = vLYTD2;
         vMTD2 = 0; vMTD3 = 0; vMTD4 = 0; vMTD5 = 0;
         vLMTD2 = 0; vLMTD3 = 0; vLMTD4 = 0; vLMTD5 = 0;
         vYTD2 = 0; vYTD3 = 0; vYTD4 = 0; vYTD5 = 0;
         vLYTD2 = 0; vLYTD3 = 0; vLYTD4 = 0; vLYTD5 = 0;
      end
      if (acclevel = 3) then
      begin
         MTD   = vMTD3;
         LMTD   = vLMTD3;
         YTD   = vYTD3;
         LYTD  = vLYTD3;
         vMTD3 = 0; vMTD4 = 0; vMTD5 = 0;
         vLMTD3 = 0; vLMTD4 = 0; vLMTD5 = 0;
         vYTD3 = 0; vYTD4 = 0; vYTD5 = 0;
         vLYTD3 = 0; vLYTD4 = 0; vLYTD5 = 0;
      end
      if (acclevel = 4) then
      begin
         MTD    = vMTD4;
         LMTD   = vLMTD4;
         YTD    = vYTD4;
         LYTD   = vLYTD4;
         vMTD4  = 0; vMTD5 = 0;
         vLMTD4 = 0; vLMTD5 = 0;
         vYTD4  = 0; vYTD5 = 0;
         vLYTD4 = 0; vLYTD5 = 0;
      end                  
      if (acclevel >= 5) then
      begin
         MTD    = vMTD5;
         LMTD   = vLMTD5;
         YTD    = vYTD5;
         LYTD   = vLYTD5;
         vMTD5  = 0;
         vLMTD5 = 0;
         vYTD5  = 0;
         vLYTD5 = 0;
      end      
    end
    if (Account <> '?') then suspend;
  END
  ACCTYPE = 'E';
  ACCOUNT = '';
  ACCNAME = 'Profit (Loss)';
  ACCSHORTNAME = 'Profit(Loss)';
  ACCLEVEL = 1;
  HEADER = 'D';
  MTD = ProfitMTD;
  YTD = ProfitYTD;
  LMTD = ProfitLMTD;
  LYTD = ProfitLYTD;
  suspend;
end^


ALTER PROCEDURE GL_RPT_TRIAL(
    PMONTH INTEGER,
    PYEAR INTEGER)
RETURNS (
    ACCTYPE VARCHAR(1),
    ACCOUNT VARCHAR(20),
    ACCNAME VARCHAR(80),
    ACCSHORTNAME VARCHAR(12),
    DEPT VARCHAR(4),
    DEPTNAME VARCHAR(20),
    COST VARCHAR(4),
    COSTNAME VARCHAR(20),
    ACCLEVEL INTEGER,
    HEADER CHAR(1),
    OPENING NUMERIC(15,4),
    DEBIT NUMERIC(15,4),
    CREDIT NUMERIC(15,4),
    ENDING NUMERIC(15,4))
AS
declare variable vLMONTH integer;
declare variable vLYEAR integer;
declare variable vOPENING1 NUMERIC(15,4);
declare variable vOPENING2 NUMERIC(15,4);
declare variable vOPENING3 NUMERIC(15,4);
declare variable vOPENING4 NUMERIC(15,4);
declare variable vOPENING5 NUMERIC(15,4);
declare variable vCREDIT1 NUMERIC(15,4);
declare variable vCREDIT2 NUMERIC(15,4);
declare variable vCREDIT3 NUMERIC(15,4);
declare variable vCREDIT4 NUMERIC(15,4);
declare variable vCREDIT5 NUMERIC(15,4);

declare variable vDEBIT1 NUMERIC(15,4);
declare variable vDEBIT2 NUMERIC(15,4);
declare variable vDEBIT3 NUMERIC(15,4);
declare variable vDEBIT4 NUMERIC(15,4);
declare variable vDEBIT5 NUMERIC(15,4);
declare variable vENDING1 NUMERIC(15,4);
declare variable vENDING2 NUMERIC(15,4);
declare variable vENDING3 NUMERIC(15,4);
declare variable vENDING4 NUMERIC(15,4);
declare variable vENDING5 NUMERIC(15,4);
declare variable vglcurearn varchar(20);
declare variable vglretearn varchar(20);
begin

vLYEAR = PYEAR;
vLMONTH = PMONTH - 1;
vOPENING1 = 0; vOPENING2 = 0; vOPENING3 = 0; vOPENING4 = 0; vOPENING5 = 0;
vCREDIT1  = 0; vCREDIT2  = 0; vCREDIT3  = 0; vCREDIT4  = 0; vCREDIT5  = 0;
vDEBIT1   = 0; vDEBIT2   = 0; vDEBIT3   = 0; vDEBIT4   = 0; vDEBIT5   = 0;
vENDING1  = 0; vENDING2  = 0; vENDING3  = 0; vENDING4  = 0; vENDING5  = 0;
if (vLMONTH < 1) then
begin
  vLYEAR = vLYEAR-1;
  vLMONTH = 12;
end

select glcurearn, glretearn from sysparam into :vglcurearn, :vglretearn;
FOR SELECT
       GLCOA.ACCTYPE,
       GLCOA.ACCOUNT,
       GLCOA.DISPLAYNAME AccName,
       GLCOA.SHORTNAME AccShortName,
       GLCOA.acclevel,
       GLCOA.header
FROM GLCOA
WHERE (GLCOA.ACCOUNT <> :vglcurearn) and
      (GLCOA.ACCOUNT <> :vglretearn)
GROUP BY GLCOA.ACCTYPE, GLCOA.ACCOUNT,
         GLCOA.DISPLAYNAME, GLCOA.SHORTNAME,
         GLCOA.acclevel, GLCOA.header
ORDER BY GLCOA.ACCOUNT

INTO ACCTYPE, ACCOUNT,
     AccName, AccShortName,
     AccLevel, Header

  DO
  BEGIN
    OPENING = 0; 
    CREDIT = 0;
    DEBIT = 0;
    ENDING = 0;
    COST = NULL; DEPT = NULL; DEPTNAME = NULL; COSTNAME = NULL;
    if (Header = 'H') then suspend;
    if (Header = 'D') then
    begin
      FOR SELECT DEPART, COST, SUM(GLACC.OPENING), SUM(DB), SUM(CR), SUM(ENDING) FROM GLACC
           WHERE PYEAR = :PYEAR
             AND PMONTH = :PMONTH
             AND GLACC.ACCOUNT = :ACCOUNT
           GROUP BY DEPART, COST
            INTO DEPT, COST, OPENING, DEBIT, CREDIT, ENDING
      DO
      BEGIN
        SELECT SHORTNAME FROM GLDEPT WHERE DEPART = :DEPT INTO DEPTNAME;
        SELECT SHORTNAME FROM GLCOST WHERE COST = :COST INTO COSTNAME;
        if (Account <> '?') then suspend;        
        if (OPENING  is null) then OPENING = 0;
        if (CREDIT   is null) then CREDIT = 0;
        if (DEBIT    is null) then DEBIT = 0;
        if (ENDING    is null) then ENDING = 0;
        if (acclevel >= 1) then
        begin
           vOPENING1  = vOPENING1  + OPENING;
           vCREDIT1 = vCREDIT1 + CREDIT;
           vDEBIT1  = vDEBIT1  + DEBIT;
           vENDING1 = vENDING1 + ENDING;
        end
        if (acclevel >= 2) then
        begin
           vOPENING2  = vOPENING2  + OPENING;
           vCREDIT2 = vCREDIT2 + CREDIT;
           vDEBIT2  = vDEBIT2  + DEBIT;
           vENDING2 = vENDING2 + ENDING;
        end
        if (acclevel >= 3) then
        begin
           vOPENING3 = vOPENING3 + OPENING;
           vCREDIT3 = vCREDIT3 + CREDIT;
           vDEBIT3  = vDEBIT3  + DEBIT;
           vENDING3 = vENDING3 + ENDING;
        end
        if (acclevel >= 4) then
        begin
           vOPENING4 = vOPENING4 + OPENING;
           vCREDIT4 = vCREDIT4 + CREDIT;
           vDEBIT4  = vDEBIT4  + DEBIT;
           vENDING4 = vENDING4 + ENDING;
        end
        if (acclevel >= 5) then
        begin
           vOPENING5 = vOPENING5 + OPENING;
           vCREDIT5 = vCREDIT5 + CREDIT;
           vDEBIT5  = vDEBIT5  + DEBIT;
           vENDING5 = vENDING5 + ENDING;
        end
      end
    end

    if (Header = 'T') then
    begin
      if (acclevel = 1) then
      begin
         OPENING   = vOPENING1;
         CREDIT  = vCREDIT1;
         DEBIT   = vDEBIT1;
         ENDING  = vENDING1;
         vOPENING1 = 0; vOPENING2 = 0; vOPENING3 = 0; vOPENING4 = 0; vOPENING5 = 0;
         vCREDIT1 = 0; vCREDIT2 = 0; vCREDIT3 = 0; vCREDIT4 = 0; vCREDIT5 = 0;
         vDEBIT1 = 0; vDEBIT2 = 0; vDEBIT3 = 0; vDEBIT4 = 0; vDEBIT5 = 0;
         vENDING1 = 0; vENDING2 = 0; vENDING3 = 0; vENDING4 = 0; vENDING5 = 0;
      end
      if (acclevel = 2) then
      begin
         OPENING   = vOPENING2;
         CREDIT   = vCREDIT2;
         DEBIT   = vDEBIT2;
         ENDING  = vENDING2;
         vOPENING2 = 0; vOPENING3 = 0; vOPENING4 = 0; vOPENING5 = 0;
         vCREDIT2 = 0; vCREDIT3 = 0; vCREDIT4 = 0; vCREDIT5 = 0;
         vDEBIT2 = 0; vDEBIT3 = 0; vDEBIT4 = 0; vDEBIT5 = 0;
         vENDING2 = 0; vENDING3 = 0; vENDING4 = 0; vENDING5 = 0;
      end
      if (acclevel = 3) then
      begin
         OPENING   = vOPENING3;
         CREDIT   = vCREDIT3;
         DEBIT   = vDEBIT3;
         ENDING  = vENDING3;
         vOPENING3 = 0; vOPENING4 = 0; vOPENING5 = 0;
         vCREDIT3 = 0; vCREDIT4 = 0; vCREDIT5 = 0;
         vDEBIT3 = 0; vDEBIT4 = 0; vDEBIT5 = 0;
         vENDING3 = 0; vENDING4 = 0; vENDING5 = 0;
      end
      if (acclevel = 4) then
      begin
         OPENING    = vOPENING4;
         CREDIT   = vCREDIT4;
         DEBIT    = vDEBIT4;
         ENDING   = vENDING4;
         vOPENING4  = 0; vOPENING5 = 0;
         vCREDIT4 = 0; vCREDIT5 = 0;
         vDEBIT4  = 0; vDEBIT5 = 0;
         vENDING4 = 0; vENDING5 = 0;
      end
      if (acclevel >= 5) then
      begin
         OPENING    = vOPENING5;
         CREDIT   = vCREDIT5;
         DEBIT    = vDEBIT5;
         ENDING   = vENDING5;
         vOPENING5  = 0;
         vCREDIT5 = 0;
         vDEBIT5  = 0;
         vENDING5 = 0;
      end
      suspend;
    end
  end
end^


ALTER PROCEDURE GL_RPT_TRIAL_DAILY(
    PDATE DATE)
RETURNS (
    ACCTYPE VARCHAR(1),
    ACCOUNT VARCHAR(20),
    ACCNAME VARCHAR(80),
    ACCSHORTNAME VARCHAR(12),
    DEPT VARCHAR(4),
    DEPTNAME VARCHAR(20),
    COST VARCHAR(4),
    COSTNAME VARCHAR(20),
    ACCLEVEL INTEGER,
    HEADER CHAR(1),
    OPENING NUMERIC(15,4),
    DEBIT NUMERIC(15,4),
    CREDIT NUMERIC(15,4),
    ENDING NUMERIC(15,4))
AS
DECLARE VARIABLE PMONTH INTEGER;
DECLARE VARIABLE PYEAR INTEGER;
declare variable vLMONTH integer;
declare variable vLYEAR integer;
declare variable vOPENING1 NUMERIC(15,4);
declare variable vOPENING2 NUMERIC(15,4);
declare variable vOPENING3 NUMERIC(15,4);
declare variable vOPENING4 NUMERIC(15,4);
declare variable vOPENING5 NUMERIC(15,4);
declare variable vCREDIT1 NUMERIC(15,4);
declare variable vCREDIT2 NUMERIC(15,4);
declare variable vCREDIT3 NUMERIC(15,4);
declare variable vCREDIT4 NUMERIC(15,4);
declare variable vCREDIT5 NUMERIC(15,4);

declare variable vDEBIT1 NUMERIC(15,4);
declare variable vDEBIT2 NUMERIC(15,4);
declare variable vDEBIT3 NUMERIC(15,4);
declare variable vDEBIT4 NUMERIC(15,4);
declare variable vDEBIT5 NUMERIC(15,4);
declare variable vENDING1 NUMERIC(15,4);
declare variable vENDING2 NUMERIC(15,4);
declare variable vENDING3 NUMERIC(15,4);
declare variable vENDING4 NUMERIC(15,4);
declare variable vENDING5 NUMERIC(15,4);
declare variable vglcurearn varchar(20);
declare variable vglretearn varchar(20);
begin
  /* ---------------------------------------------------------------- */
  /* 26 JUNI 2006                                                     */
  /* ---------------------------------------------------------------- */
  IF (PDATE IS NULL) THEN PDATE = '4.12.2005';

  PYEAR  = EXTRACT(YEAR  FROM PDATE);
  PMONTH = EXTRACT(MONTH FROM PDATE);

  vLYEAR = PYEAR;
  vLMONTH = PMONTH - 1;
  vOPENING1 = 0; vOPENING2 = 0; vOPENING3 = 0; vOPENING4 = 0; vOPENING5 = 0;
  vCREDIT1  = 0; vCREDIT2  = 0; vCREDIT3  = 0; vCREDIT4  = 0; vCREDIT5  = 0;
  vDEBIT1   = 0; vDEBIT2   = 0; vDEBIT3   = 0; vDEBIT4   = 0; vDEBIT5   = 0;
  vENDING1  = 0; vENDING2  = 0; vENDING3  = 0; vENDING4  = 0; vENDING5  = 0;
  if (vLMONTH < 1) then
  begin
    vLYEAR = vLYEAR-1;
    vLMONTH = 12;
  end

  select glcurearn, glretearn from sysparam into :vglcurearn, :vglretearn;
  FOR SELECT
         ACCTYPE,
         ACCOUNT,
         DISPLAYNAME AccName,
         SHORTNAME AccShortName,
         acclevel,
         header
  FROM GLCOA
  WHERE (ACCOUNT <> :vglcurearn)
    and (ACCOUNT <> :vglretearn)
    AND (ACCTYPE IN ('A','P','C','I'))
  GROUP BY ACCTYPE, ACCOUNT,
           DISPLAYNAME, SHORTNAME,
           acclevel, header
  ORDER BY ACCOUNT

  INTO ACCTYPE, ACCOUNT,
       AccName, AccShortName,
       AccLevel, Header

    DO
    BEGIN
      OPENING = 0;
      CREDIT = 0;
      DEBIT = 0;
      ENDING = 0;
      DEPT  = NULL;
      COST = NULL;
      DEPTNAME = NULL;
      COSTNAME = NULL;

      if (Header = 'H') then suspend;

      if (Header = 'D') then
      begin
        FOR SELECT DEPART, COST, SUM(GLACC.OPENING)
        FROM GLACC
             WHERE PYEAR = :PYEAR
               AND PMONTH = :PMONTH
               AND GLACC.ACCOUNT = :ACCOUNT
             GROUP BY DEPART, COST
              INTO DEPT, COST, OPENING
        DO
        BEGIN

          SELECT SHORTNAME FROM GLDEPT WHERE DEPART = :DEPT INTO DEPTNAME;
          SELECT SHORTNAME FROM GLCOST WHERE COST   = :COST INTO COSTNAME;
          /* ---------------------------------------------------------------- */
          /* DAILY TRANSACTION                                                */
          /* ---------------------------------------------------------------- */

          SELECT SUM(JR.DB), SUM(JR.CR)
          FROM GLJUR JR
          LEFT JOIN GLTRANS T ON T.PYEAR = JR.PYEAR AND T.PMONTH = JR.PMONTH AND T.TRANSNO = JR.TRANSNO
          WHERE JR.ACCOUNT = :ACCOUNT
          AND JR.DEPART = :DEPT
          AND JR.COST = :COST
          AND JR.PYEAR = :PYEAR
          AND JR.PMONTH = :PMONTH
          AND T.TRANSDATE <= :PDATE
/*           PLAN (GLJUR INDEX (GLJUR_IDX_ACCOUNT)) For FB.2.x 31-Aug-2011 */
          INTO DEBIT, CREDIT;
          /* ---------------------------------------------------------------- */
          /* SAMA SEPERTI GL_RPT_TRIAL                                        */
          /* ---------------------------------------------------------------- */
          if (OPENING  is null) then OPENING = 0;
          if (CREDIT   is null) then CREDIT = 0;
          if (DEBIT    is null) then DEBIT = 0;
          if (ENDING    is null) then ENDING = 0;

          IF (ACCTYPE IN ('A', 'C')) THEN
             ENDING = OPENING + DEBIT - CREDIT;
          ELSE
             ENDING = OPENING - DEBIT + CREDIT;

          if (Account <> '?') then suspend;

          if (acclevel >= 1) then
          begin
             vOPENING1  = vOPENING1  + OPENING;
             vCREDIT1 = vCREDIT1 + CREDIT;
             vDEBIT1  = vDEBIT1  + OPENING;
             vENDING1 = vENDING1 + CREDIT;
          end
          if (acclevel >= 2) then
          begin
             vOPENING2  = vOPENING2  + OPENING;
             vCREDIT2 = vCREDIT2 + CREDIT;
             vDEBIT2  = vDEBIT2  + OPENING;
             vENDING2 = vENDING2 + CREDIT;
          end
          if (acclevel >= 3) then
          begin
             vOPENING3 = vOPENING3 + OPENING;
             vCREDIT3 = vCREDIT3 + CREDIT;
             vDEBIT3  = vDEBIT3  + OPENING;
             vENDING3 = vENDING3 + CREDIT;
          end
          if (acclevel >= 4) then
          begin
             vOPENING4 = vOPENING4 + OPENING;
             vCREDIT4 = vCREDIT4 + CREDIT;
             vDEBIT4  = vDEBIT4  + OPENING;
             vENDING4 = vENDING4 + CREDIT;
          end
          if (acclevel >= 5) then
          begin
             vOPENING5 = vOPENING5 + OPENING;
             vCREDIT5 = vCREDIT5 + CREDIT;
             vDEBIT5  = vDEBIT5  + OPENING;
             vENDING5 = vENDING5 + CREDIT;
          end
        end
      end

      if (Header = 'T') then
      begin
        if (acclevel = 1) then
        begin
           OPENING   = vOPENING1;
           CREDIT  = vCREDIT1;
           DEBIT   = vDEBIT1;
           ENDING  = vENDING1;
           vOPENING1 = 0; vOPENING2 = 0; vOPENING3 = 0; vOPENING4 = 0; vOPENING5 = 0;
           vCREDIT1 = 0; vCREDIT2 = 0; vCREDIT3 = 0; vCREDIT4 = 0; vCREDIT5 = 0;
           vDEBIT1 = 0; vDEBIT2 = 0; vDEBIT3 = 0; vDEBIT4 = 0; vDEBIT5 = 0;
           vENDING1 = 0; vENDING2 = 0; vENDING3 = 0; vENDING4 = 0; vENDING5 = 0;
        end
        if (acclevel = 2) then
        begin
           OPENING   = vOPENING2;
           CREDIT   = vCREDIT2;
           DEBIT   = vDEBIT2;
           ENDING  = vENDING2;
           vOPENING2 = 0; vOPENING3 = 0; vOPENING4 = 0; vOPENING5 = 0;
           vCREDIT2 = 0; vCREDIT3 = 0; vCREDIT4 = 0; vCREDIT5 = 0;
           vDEBIT2 = 0; vDEBIT3 = 0; vDEBIT4 = 0; vDEBIT5 = 0;
           vENDING2 = 0; vENDING3 = 0; vENDING4 = 0; vENDING5 = 0;
        end
        if (acclevel = 3) then
        begin
           OPENING   = vOPENING3;
           CREDIT   = vCREDIT3;
           DEBIT   = vDEBIT3;
           ENDING  = vENDING3;
           vOPENING3 = 0; vOPENING4 = 0; vOPENING5 = 0;
           vCREDIT3 = 0; vCREDIT4 = 0; vCREDIT5 = 0;
           vDEBIT3 = 0; vDEBIT4 = 0; vDEBIT5 = 0;
           vENDING3 = 0; vENDING4 = 0; vENDING5 = 0;
        end
        if (acclevel = 4) then
        begin
           OPENING    = vOPENING4;
           CREDIT   = vCREDIT4;
           DEBIT    = vDEBIT4;
           ENDING   = vENDING4;
           vOPENING4  = 0; vOPENING5 = 0;
           vCREDIT4 = 0; vCREDIT5 = 0;
           vDEBIT4  = 0; vDEBIT5 = 0;
           vENDING4 = 0; vENDING5 = 0;
        end
        if (acclevel >= 5) then
        begin
           OPENING    = vOPENING5;
           CREDIT   = vCREDIT5;
           DEBIT    = vDEBIT5;
           ENDING   = vENDING5;
           vOPENING5  = 0;
           vCREDIT5 = 0;
           vDEBIT5  = 0;
           vENDING5 = 0;
        end
        suspend;
      end
  end
end^


ALTER PROCEDURE GL_TRIAL_BALANCE(
    PMONTH INTEGER,
    PYEAR INTEGER)
RETURNS (
    ACCOUNT VARCHAR(20),
    DEPART VARCHAR(4),
    COST VARCHAR(4),
    OPENING NUMERIC(15,4),
    DB NUMERIC(15,4),
    CR NUMERIC(15,4),
    BUDGET NUMERIC(15,4),
    ENDING NUMERIC(15,4),
    MUTATION NUMERIC(15,4),
    ACCNAME VARCHAR(40),
    ACCSHORTNAME VARCHAR(12),
    DEPTNAME VARCHAR(40),
    DEPTSHORTNAME VARCHAR(12),
    COSTNAME VARCHAR(40),
    COSTSHORTNAME VARCHAR(12))
AS
DECLARE VARIABLE VGLCUREARN VARCHAR(20);
DECLARE VARIABLE VGLRETEARN VARCHAR(20);
begin
select glcurearn, glretearn from sysparam into :vglcurearn, :vglretearn;
FOR SELECT
       GLACC.ACCOUNT,
       GLACC.DEPART,
       GLACC.COST,
       GLACC.OPENING,
       GLACC.DB,
       GLACC.CR,
       GLACC.BUDGET,
       GLACC.ENDING,
       GLACC.MUTATION,
       GLCOA.NAME AccName,
       GLCOA.SHORTNAME AccShortName,
       GLDEPT.NAME DeptName,
       GLDEPT.SHORTNAME DeptShortName,
       GLCOST.NAME CostName,
       GLCOST.SHORTNAME CostShortName
FROM GLACC
   INNER JOIN GLCOST ON (GLCOST.COST = GLACC.COST)
   INNER JOIN GLCOA ON (GLACC.ACCOUNT = GLCOA.ACCOUNT)
   INNER JOIN GLDEPT ON (GLACC.DEPART = GLDEPT.DEPART)
WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
AND ACCTYPE IN ('A','P','I','C')
ORDER BY GLACC.ACCOUNT, GLACC.DEPART, GLACC.COST

INTO ACCOUNT,DEPART, COST,
     OPENING, DB, CR, BUDGET, ENDING, MUTATION,
     AccName, AccShortName,
     DeptName, DeptShortName,
     CostName, CostShortName
  DO
  begin
     if (NOT ((ACCOUNT = vglcurearn) or (account = vglretearn))) THEN
        if ((opening <> 0) or (db <> 0) or (cr <> 0) or (ending <> 0)) then
           suspend;
  end
end^


ALTER PROCEDURE GL_WKS_BUDGET(
    PYEAR INTEGER,
    PDEPART VARCHAR(4),
    PCOST VARCHAR(4))
RETURNS (
    ACCTYPE VARCHAR(1),
    ACCOUNT VARCHAR(20),
    ACCNAME VARCHAR(80),
    ACCSHORTNAME VARCHAR(12),
    DEPT VARCHAR(4),
    DEPTNAME VARCHAR(20),
    COST VARCHAR(4),
    COSTNAME VARCHAR(20),
    ACCLEVEL INTEGER,
    HEADER CHAR(1),
    BG01 NUMERIC(15,4),
    BG02 NUMERIC(15,4),
    BG03 NUMERIC(15,4),
    BG04 NUMERIC(15,4),
    BG05 NUMERIC(15,4),
    BG06 NUMERIC(15,4),
    BG07 NUMERIC(15,4),
    BG08 NUMERIC(15,4),
    BG09 NUMERIC(15,4),
    BG10 NUMERIC(15,4),
    BG11 NUMERIC(15,4),
    BG12 NUMERIC(15,4))
AS
declare variable vglcurearn varchar(20);
declare variable vglretearn varchar(20);

declare variable t5_bg01 double precision;
declare variable t5_bg02 double precision;
declare variable t5_bg03 double precision;
declare variable t5_bg04 double precision;
declare variable t5_bg05 double precision;
declare variable t5_bg06 double precision;
declare variable t5_bg07 double precision;
declare variable t5_bg08 double precision;
declare variable t5_bg09 double precision;
declare variable t5_bg10 double precision;
declare variable t5_bg11 double precision;
declare variable t5_bg12 double precision;

declare variable t4_bg01 double precision;
declare variable t4_bg02 double precision;
declare variable t4_bg03 double precision;
declare variable t4_bg04 double precision;
declare variable t4_bg05 double precision;
declare variable t4_bg06 double precision;
declare variable t4_bg07 double precision;
declare variable t4_bg08 double precision;
declare variable t4_bg09 double precision;
declare variable t4_bg10 double precision;
declare variable t4_bg11 double precision;
declare variable t4_bg12 double precision;

declare variable t3_bg01 double precision;
declare variable t3_bg02 double precision;
declare variable t3_bg03 double precision;
declare variable t3_bg04 double precision;
declare variable t3_bg05 double precision;
declare variable t3_bg06 double precision;
declare variable t3_bg07 double precision;
declare variable t3_bg08 double precision;
declare variable t3_bg09 double precision;
declare variable t3_bg10 double precision;
declare variable t3_bg11 double precision;
declare variable t3_bg12 double precision;

declare variable t2_bg01 double precision;
declare variable t2_bg02 double precision;
declare variable t2_bg03 double precision;
declare variable t2_bg04 double precision;
declare variable t2_bg05 double precision;
declare variable t2_bg06 double precision;
declare variable t2_bg07 double precision;
declare variable t2_bg08 double precision;
declare variable t2_bg09 double precision;
declare variable t2_bg10 double precision;
declare variable t2_bg11 double precision;
declare variable t2_bg12 double precision;

declare variable t1_bg01 double precision;
declare variable t1_bg02 double precision;
declare variable t1_bg03 double precision;
declare variable t1_bg04 double precision;
declare variable t1_bg05 double precision;
declare variable t1_bg06 double precision;
declare variable t1_bg07 double precision;
declare variable t1_bg08 double precision;
declare variable t1_bg09 double precision;
declare variable t1_bg10 double precision;
declare variable t1_bg11 double precision;
declare variable t1_bg12 double precision;

declare variable SDEPART VARCHAR(4);
declare variable EDEPART VARCHAR(4);
declare variable SCOST VARCHAR(4);
declare variable ECOST VARCHAR(4);
begin
  if (PDEPART = 'ALL') then
  BEGIN
    SDEPART = '';
    EDEPART = 'ZZZZ';
  END
  ELSE
  BEGIN
    SDEPART = PDEPART;
    EDEPART = PDEPART;
  END
  
  if (PCOST = 'ALL') then
  BEGIN
     SCOST = '';
     ECOST = 'ZZZZ';
  END
  ELSE
  BEGIN
     SCOST = PCOST;
     ECOST = PCOST;
  END

  T1_BG01 = 0; T1_BG02 = 0; T1_BG03 = 0; T1_BG04 = 0; T1_BG05 = 0; T1_BG06 = 0;
  T1_BG07 = 0; T1_BG08 = 0; T1_BG09 = 0; T1_BG10 = 0; T1_BG11 = 0; T1_BG12 = 0;
  
  T2_BG01 = 0; T2_BG02 = 0; T2_BG03 = 0; T2_BG04 = 0; T2_BG05 = 0; T2_BG06 = 0;
  T2_BG07 = 0; T2_BG08 = 0; T2_BG09 = 0; T2_BG10 = 0; T2_BG11 = 0; T2_BG12 = 0;

  T3_BG01 = 0; T3_BG02 = 0; T3_BG03 = 0; T3_BG04 = 0; T3_BG05 = 0; T3_BG06 = 0;
  T3_BG07 = 0; T3_BG08 = 0; T3_BG09 = 0; T3_BG10 = 0; T3_BG11 = 0; T3_BG12 = 0;

  T4_BG01 = 0; T4_BG02 = 0; T4_BG03 = 0; T4_BG04 = 0; T4_BG05 = 0; T4_BG06 = 0;
  T4_BG07 = 0; T4_BG08 = 0; T4_BG09 = 0; T4_BG10 = 0; T4_BG11 = 0; T4_BG12 = 0;
  
  T5_BG01 = 0; T5_BG02 = 0; T5_BG03 = 0; T5_BG04 = 0; T5_BG05 = 0; T5_BG06 = 0;
  T5_BG07 = 0; T5_BG08 = 0; T5_BG09 = 0; T5_BG10 = 0; T5_BG11 = 0; T5_BG12 = 0;
    
    
  select glcurearn, glretearn from sysparam into :vglcurearn, :vglretearn;
  FOR SELECT
       GLCOA.ACCTYPE,
       GLCOA.ACCOUNT,
       GLCOA.DISPLAYNAME AccName,
       GLCOA.SHORTNAME AccShortName,
       GLCOA.acclevel,
       GLCOA.header
  FROM GLCOA
  WHERE NOT ((GLCOA.ACCOUNT = :vglcurearn) OR
           (GLCOA.ACCOUNT = :vglcurearn))
  GROUP BY GLCOA.ACCTYPE, GLCOA.ACCOUNT,
         GLCOA.DISPLAYNAME, GLCOA.SHORTNAME,
         GLCOA.acclevel, GLCOA.header
  ORDER BY GLCOA.ACCOUNT

  INTO ACCTYPE, ACCOUNT,
       AccName, AccShortName,
       AccLevel, Header
  DO
  BEGIN
    BG01 = 0; BG02 = 0; BG03 = 0; BG04 = 0; BG05 = 0; BG06 = 0;
    BG07 = 0; BG08 = 0; BG09 = 0; BG10 = 0; BG11 = 0; BG12 = 0;
    DEPT = ''; COST = ''; DEPTNAME = ''; COSTNAME = '';
    
    if (Header IN ('H', 'T')) then
    begin
       if (acclevel =1) then
       begin
         bg01 = t1_bg01;  bg02 = t1_bg02; bg03 = t1_bg03; bg04 = t1_bg04;
         bg05 = t1_bg05;  bg06 = t1_bg06; bg07 = t1_bg07; bg08 = t1_bg08;
         bg09 = t1_bg09;  bg10 = t1_bg10; bg11 = t1_bg11; bg12 = t1_bg12;
       end
       
       if (acclevel =2) then
       begin
         bg01 = t2_bg01;  bg02 = t2_bg02; bg03 = t2_bg03; bg04 = t2_bg04;
         bg05 = t2_bg05;  bg06 = t2_bg06; bg07 = t2_bg07; bg08 = t2_bg08;
         bg09 = t2_bg09;  bg10 = t2_bg10; bg11 = t2_bg11; bg12 = t2_bg12;
       end       
       
       if (acclevel =3) then
       begin
         bg01 = t3_bg01;  bg02 = t3_bg02; bg03 = t3_bg03; bg04 = t3_bg04;
         bg05 = t3_bg05;  bg06 = t3_bg06; bg07 = t3_bg07; bg08 = t3_bg08;
         bg09 = t3_bg09;  bg10 = t3_bg10; bg11 = t3_bg11; bg12 = t3_bg12;
       end

       if (acclevel =4) then
       begin
         bg01 = t4_bg01;  bg02 = t4_bg02; bg03 = t4_bg03; bg04 = t4_bg04;
         bg05 = t4_bg05;  bg06 = t4_bg06; bg07 = t4_bg07; bg08 = t4_bg08;
         bg09 = t4_bg09;  bg10 = t4_bg10; bg11 = t4_bg11; bg12 = t4_bg12;
       end
       
       if (acclevel =5) then
       begin
         bg01 = t5_bg01;  bg02 = t5_bg02; bg03 = t5_bg03; bg04 = t5_bg04;
         bg05 = t5_bg05;  bg06 = t5_bg06; bg07 = t5_bg07; bg08 = t5_bg08;
         bg09 = t5_bg09;  bg10 = t5_bg10; bg11 = t5_bg11; bg12 = t5_bg12;
       end                   
       suspend;
       if (acclevel >= 1) then
       begin
         T1_BG01 = 0; T1_BG02 = 0; T1_BG03 = 0; T1_BG04 = 0; T1_BG05 = 0; T1_BG06 = 0;
         T1_BG07 = 0; T1_BG08 = 0; T1_BG09 = 0; T1_BG10 = 0; T1_BG11 = 0; T1_BG12 = 0;
       end
       
       if (acclevel >= 2) then
       begin
         T2_BG01 = 0; T2_BG02 = 0; T2_BG03 = 0; T2_BG04 = 0; T2_BG05 = 0; T2_BG06 = 0;
         T2_BG07 = 0; T2_BG08 = 0; T2_BG09 = 0; T2_BG10 = 0; T2_BG11 = 0; T2_BG12 = 0;
       end       

       if (acclevel >= 3) then
       begin
         T3_BG01 = 0; T3_BG02 = 0; T3_BG03 = 0; T3_BG04 = 0; T3_BG05 = 0; T3_BG06 = 0;
         T3_BG07 = 0; T3_BG08 = 0; T3_BG09 = 0; T3_BG10 = 0; T3_BG11 = 0; T3_BG12 = 0;
       end       
       
       if (acclevel >= 4) then
       begin
         T4_BG01 = 0; T4_BG02 = 0; T4_BG03 = 0; T4_BG04 = 0; T4_BG05 = 0; T4_BG06 = 0;
         T4_BG07 = 0; T4_BG08 = 0; T4_BG09 = 0; T4_BG10 = 0; T4_BG11 = 0; T4_BG12 = 0;
       end       
       
       if (acclevel >= 5) then
       begin
         T5_BG01 = 0; T5_BG02 = 0; T5_BG03 = 0; T5_BG04 = 0; T5_BG05 = 0; T5_BG06 = 0;
         T5_BG07 = 0; T5_BG08 = 0; T5_BG09 = 0; T5_BG10 = 0; T5_BG11 = 0; T5_BG12 = 0;
       end       
    end

    if (Header = 'D') then
    begin
      FOR SELECT GLCOADEPT.DEPART, GLDEPT.SHORTNAME
          FROM GLCOADEPT
          LEFT JOIN GLDEPT ON GLCOADEPT.depart = GLDEPT.depart
          WHERE GLCOADEPT.ACCOUNT = :ACCOUNT
          AND GLCOADEPT.DEPART BETWEEN :SDEPART AND :EDEPART
          INTO :DEPT, :DEPTNAME
      DO
      BEGIN
        FOR SELECT GLCOACOST.COST, GLCOST.SHORTNAME
            FROM GLCOACOST
            LEFT JOIN GLCOST ON GLCOACOST.cost = glcost.cost
            WHERE GLCOACOST.ACCOUNT = :ACCOUNT
            AND GLCOACOST.COST BETWEEN :SCOST AND :ECOST
            INTO :COST, :COSTNAME
        DO
        BEGIN
          execute procedure GL_WKS_BUDGET_GET(PYear, 1, Account, Dept, Cost) returning_values bg01;
          execute procedure GL_WKS_BUDGET_GET(PYear, 2, Account, Dept, Cost) returning_values bg02;
          execute procedure GL_WKS_BUDGET_GET(PYear, 3, Account, Dept, Cost) returning_values bg03;
          execute procedure GL_WKS_BUDGET_GET(PYear, 4, Account, Dept, Cost) returning_values bg04;
          execute procedure GL_WKS_BUDGET_GET(PYear, 5, Account, Dept, Cost) returning_values bg05;
          execute procedure GL_WKS_BUDGET_GET(PYear, 6, Account, Dept, Cost) returning_values bg06;
          execute procedure GL_WKS_BUDGET_GET(PYear, 7, Account, Dept, Cost) returning_values bg07;
          execute procedure GL_WKS_BUDGET_GET(PYear, 8, Account, Dept, Cost) returning_values bg08;
          execute procedure GL_WKS_BUDGET_GET(PYear, 9, Account, Dept, Cost) returning_values bg09;
          execute procedure GL_WKS_BUDGET_GET(PYear,10, Account, Dept, Cost) returning_values bg10;
          execute procedure GL_WKS_BUDGET_GET(PYear,11, Account, Dept, Cost) returning_values bg11;
          execute procedure GL_WKS_BUDGET_GET(PYear,12, Account, Dept, Cost) returning_values bg12;
          suspend;
          
          if (acclevel <= 1) then
          begin
             t1_bg01 = t1_bg01 + bg01; t1_bg02 = t1_bg02 + bg02;
             t1_bg03 = t1_bg03 + bg03; t1_bg04 = t1_bg04 + bg04;
             t1_bg05 = t1_bg05 + bg05; t1_bg06 = t1_bg06 + bg06;
             t1_bg07 = t1_bg07 + bg07; t1_bg08 = t1_bg08 + bg08;
             t1_bg09 = t1_bg09 + bg09; t1_bg10 = t1_bg10 + bg10;
             t1_bg11 = t1_bg11 + bg11; t1_bg12 = t1_bg12 + bg12;
          end

          if (acclevel <= 2) then
          begin
             t2_bg01 = t2_bg01 + bg01; t2_bg02 = t2_bg02 + bg02;
             t2_bg03 = t2_bg03 + bg03; t2_bg04 = t2_bg04 + bg04;
             t2_bg05 = t2_bg05 + bg05; t2_bg06 = t2_bg06 + bg06;
             t2_bg07 = t2_bg07 + bg07; t2_bg08 = t2_bg08 + bg08;
             t2_bg09 = t2_bg09 + bg09; t2_bg10 = t2_bg10 + bg10;
             t2_bg11 = t2_bg11 + bg11; t2_bg12 = t2_bg12 + bg12;
          end          
          
          if (acclevel <= 3) then
          begin
             t3_bg01 = t3_bg01 + bg01; t3_bg02 = t3_bg02 + bg02;
             t3_bg03 = t3_bg03 + bg03; t3_bg04 = t3_bg04 + bg04;
             t3_bg05 = t3_bg05 + bg05; t3_bg06 = t3_bg06 + bg06;
             t3_bg07 = t3_bg07 + bg07; t3_bg08 = t3_bg08 + bg08;
             t3_bg09 = t3_bg09 + bg09; t3_bg10 = t3_bg10 + bg10;
             t3_bg11 = t3_bg11 + bg11; t3_bg12 = t3_bg12 + bg12;
          end

          if (acclevel <= 4) then
          begin
             t4_bg01 = t4_bg01 + bg01; t4_bg02 = t4_bg02 + bg02;
             t4_bg03 = t4_bg03 + bg03; t4_bg04 = t4_bg04 + bg04;
             t4_bg05 = t4_bg05 + bg05; t4_bg06 = t4_bg06 + bg06;
             t4_bg07 = t4_bg07 + bg07; t4_bg08 = t4_bg08 + bg08;
             t4_bg09 = t4_bg09 + bg09; t4_bg10 = t4_bg10 + bg10;
             t4_bg11 = t4_bg11 + bg11; t4_bg12 = t4_bg12 + bg12;
          end

          if (acclevel <= 5) then
          begin
             t5_bg01 = t5_bg01 + bg01; t5_bg02 = t5_bg02 + bg02;
             t5_bg03 = t5_bg03 + bg03; t5_bg04 = t5_bg04 + bg04;
             t5_bg05 = t5_bg05 + bg05; t5_bg06 = t5_bg06 + bg06;
             t5_bg07 = t5_bg07 + bg07; t5_bg08 = t5_bg08 + bg08;
             t5_bg09 = t5_bg09 + bg09; t5_bg10 = t5_bg10 + bg10;
             t5_bg11 = t5_bg11 + bg11; t5_bg12 = t5_bg12 + bg12;
          end                                        
          
        end
      end
    end
  end
end^


ALTER PROCEDURE GL_WKS_BUDGET_GET(
    PYEAR INTEGER,
    PMONTH INTEGER,
    ACCOUNT VARCHAR(20),
    DEPART VARCHAR(4),
    COST VARCHAR(4))
RETURNS (
    BUDGET NUMERIC(15,4))
AS
begin
  SELECT BUDGET FROM GLACC
    WHERE PYEAR = :PYEAR
      AND PMONTH = :PMONTH
      AND ACCOUNT = :ACCOUNT
      AND DEPART = :DEPART
      AND COST = :COST
    INTO :BUDGET;
  if (BUDGET IS NULL) then BUDGET = 0;
end^


ALTER PROCEDURE GL_WKS_BUDGET_PUT(
    PYEAR INTEGER,
    PMONTH INTEGER,
    ACCOUNT VARCHAR(20),
    DEPART VARCHAR(4),
    COST VARCHAR(4),
    BUDGET NUMERIC(15,4))
RETURNS (
    RBUDGET NUMERIC(15,4))
AS
declare variable vRow Integer;
begin
  RBUDGET = BUDGET;
  SELECT count(*) FROM GLACC
    WHERE PYEAR = :PYEAR
      AND PMONTH = :PMONTH
      AND ACCOUNT = :ACCOUNT
      AND DEPART = :DEPART
      AND COST = :COST
    INTO :vRow;
    
  if (vRow = 0) then 
     insert into glacc (pyear, pmonth, account, depart, cost)
            values (:pyear, :pmonth, :account, :depart, :cost);

   update glacc set budget = :budget
    WHERE PYEAR = :PYEAR
      AND PMONTH = :PMONTH
      AND ACCOUNT = :ACCOUNT
      AND DEPART = :DEPART
      AND COST = :COST;
  SUSPEND;
end^


ALTER PROCEDURE GL_WKS_RPT_CHECK(
    WKS_ID INTEGER,
    PYEAR INTEGER,
    PMONTH INTEGER,
    TYPE1 CHAR(1),
    TYPE2 CHAR(1),
    TYPE3 CHAR(1),
    TYPE4 CHAR(1))
RETURNS (
    ROW INTEGER,
    COL INTEGER,
    TEXT VARCHAR(80),
    ACCOUNT VARCHAR(20),
    DEPART VARCHAR(4),
    COST VARCHAR(4),
    ACCOUNTNAME VARCHAR(40),
    ACCTYPE CHAR(1),
    DEPTNAME VARCHAR(40),
    COSTNAME VARCHAR(40),
    MTD DOUBLE PRECISION,
    YTD DOUBLE PRECISION)
AS
BEGIN
  FOR
    SELECT W.ROW, W.COL, W.TEXT,
           A.ACCOUNT, A.DEPART, A.COST,
           COA.NAME ACCOUNTNAME,
           COA.ACCTYPE,
           D.NAME DEPTNAME, C.NAME COSTNAME,
           A.ENDING
    FROM GLACC A
    LEFT JOIN GLCOA COA ON COA.ACCOUNT = A.ACCOUNT
    LEFT JOIN GLDEPT D ON D.DEPART = A.DEPART
    LEFT JOIN GLCOST C ON C.COST = A.COST
    LEFT JOIN GLWKS_DETAIL W ON
    (W.WKS_ID = :WKS_ID) AND (W.DATATYPE = 'RSOURCE')
    AND A.ACCOUNT BETWEEN W.SACCOUNT AND W.EACCOUNT
    AND A.DEPART BETWEEN W.SDEPT AND W.EDEPT
    AND A.COST BETWEEN W.SCOST AND W.ECOST
    WHERE A.PYEAR = :PYEAR
    AND A.PMONTH = :PMONTH
    AND ((COA.ACCTYPE = :TYPE1) OR
         (COA.ACCTYPE = :TYPE2) OR
         (COA.ACCTYPE = :TYPE3) OR
         (COA.ACCTYPE = :TYPE4))
    INTO
      :ROW,
      :COL,
      :TEXT,
      :ACCOUNT,
      :DEPART,
      :COST,
      :ACCOUNTNAME,
      :ACCTYPE,
      :DEPTNAME,
      :COSTNAME,
      :MTD
  DO
  BEGIN
    IF (ACCTYPE IN ('A','P')) THEN
    BEGIN
       YTD = MTD;
    END
    ELSE
    BEGIN
      SELECT SUM(ENDING) FROM GLACC
      WHERE PYEAR = :PYEAR
      AND PMONTH <= :PMONTH
      AND ACCOUNT = :ACCOUNT
      AND DEPART = :DEPART
      AND COST = :COST
      INTO :YTD;
      IF (YTD IS NULL) THEN YTD = 0;
    END
    SUSPEND;
  END
END^


