ALTER PROCEDURE INV_CHECK_INVSTOCK(
    PYEAR INTEGER,
    PMONTH INTEGER,
    PSAVE INTEGER)
RETURNS (
    CODE VARCHAR(4),
    INFO VARCHAR(20),
    STORE VARCHAR(4),
    PARTNO VARCHAR(10),
    NAME VARCHAR(40),
    QTY DOUBLE PRECISION,
    AMOUNT DOUBLE PRECISION,
    STORE_QTY DOUBLE PRECISION,
    STORE_AMOUNT DOUBLE PRECISION,
    DELTA_QTY DOUBLE PRECISION,
    DELTA_AMOUNT DOUBLE PRECISION)
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE X INTEGER;
BEGIN
  IF ((PYEAR IS NULL) OR (PYEAR = 0)) THEN
  BEGIN
     PYEAR = 2006;
     PMONTH = 10;
     PSAVE = 0;
  END
  IF (PSAVE IS NULL) THEN PSAVE = 0;

  SDATE = '1.'||PMONTH||'.'||PYEAR;

  EXECUTE PROCEDURE SP_DATE_BOM(SDATE) RETURNING_VALUES(SDATE); /* 4/23/2011 */
  EXECUTE PROCEDURE SP_DATE_EOM(SDATE) RETURNING_VALUES(EDATE); /* 4/23/2011 */
  
  /* ---------------------------------------------------------------- */
  /* RECEIVING STORE ITEM                                             */
  /* ---------------------------------------------------------------- */
  CODE = 'RECV';
  INFO = 'Receiving';
  FOR
    /* 12/12/2011 tax harus dikalikan dengan exchange rate */
    SELECT H.STORE, D.PARTNO, SUM(D.CALC_QTY), SUM(D.CALC_COST_FOREX-D.EXCHANGE*D.CALC_TAX*CFG.INV_AP_SPLIT_TAX) /* 12 JUN 2007, TAX */
    FROM INVRECV1 D
    INNER JOIN INVRECV0 H ON H.NUMBER = D.NUMBER
    LEFT JOIN SYSPARAM CFG ON ID = 1
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    AND D.DIRECTUSE = 0
    GROUP BY H.STORE, D.PARTNO
    INTO :STORE, :PARTNO, :QTY, :AMOUNT
  DO
  BEGIN
    SELECT QTYIN, AMTIN FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    AND STORE = :STORE AND PARTNO = :PARTNO
    INTO STORE_QTY, STORE_AMOUNT;

    /* ---------------------------------------------------------------- */
    /* 26 OCTOBER 2006                                                  */
    /* ---------------------------------------------------------------- */
    IF (STORE_QTY IS NULL) THEN
    BEGIN
       STORE_QTY = 0;
       STORE_AMOUNT = 0;
    END



    /* ---------------------------------------------------------------- */

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          /* ---------------------------------------------------------------- */
          /* 6 NOVEMBER 2006                                                  */
          /* ---------------------------------------------------------------- */
          IF (NOT EXISTS(SELECT * FROM INVSTOCK WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
              AND STORE = :STORE AND PARTNO = :PARTNO)) THEN
          BEGIN
             INSERT INTO INVSTOCK (PYEAR, PMONTH, STORE, PARTNO)
             VALUES
             (:PYEAR, :PMONTH, :STORE, :PARTNO);
          END


          /* ---------------------------------------------------------------- */
          UPDATE INVSTOCK SET QTYIN = :QTY, AMTIN = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;




       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* RECEIVING DIHITUNG DARI STOCK                                    */
  /* ---------------------------------------------------------------- */
  FOR SELECT STORE, PARTNO, QTYIN, AMTIN FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    INTO :STORE, :PARTNO, STORE_QTY, STORE_AMOUNT
  DO
  BEGIN
    SELECT SUM(D.CALC_QTY), SUM(D.CALC_COST_FOREX-D.EXCHANGE*D.CALC_TAX*CFG.INV_AP_SPLIT_TAX)     /* 12/12/2011 tax harus dikalikan dengan exchange rate */
    FROM INVRECV1 D
    INNER JOIN INVRECV0 H ON H.NUMBER = D.NUMBER
    LEFT JOIN SYSPARAM CFG ON ID = 1
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    AND H.STORE = :STORE
    AND D.PARTNO = :PARTNO
    AND D.DIRECTUSE = 0
    INTO :QTY, :AMOUNT;

    IF (QTY IS NULL) THEN
    BEGIN
       QTY = 0;
       AMOUNT = 0;
    END

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          UPDATE INVSTOCK SET QTYIN = :QTY, AMTIN = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* RETURN STORE ITEM                                                */
  /* ---------------------------------------------------------------- */
  CODE = 'RET';
  INFO = 'Return';

  FOR
    SELECT H.STORE, D.PARTNO, SUM(D.QTYF*D.KONVERSI+D.QTY) QTY, SUM(D.CALC_COST) AMOUNT
    FROM INVRET0 H
    INNER JOIN INVRET1 D ON H.NUMBER = D.NUMBER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    GROUP BY H.STORE, D.PARTNO
    INTO :STORE, :PARTNO, :QTY, :AMOUNT
  DO
  BEGIN
    SELECT QTYRETURN, AMTRETURN FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    AND STORE = :STORE AND PARTNO = :PARTNO
    INTO STORE_QTY, STORE_AMOUNT;

    /* ---------------------------------------------------------------- */
    /* 26 OCTOBER 2006                                                  */
    /* ---------------------------------------------------------------- */
    IF (STORE_QTY IS NULL) THEN
    BEGIN
       STORE_QTY = 0;
       STORE_AMOUNT = 0;
    END



    /* ---------------------------------------------------------------- */

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          UPDATE INVSTOCK SET QTYRETURN = :QTY, AMTRETURN = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* ISSUING DARI STOCK                                               */
  /* ---------------------------------------------------------------- */
  FOR SELECT STORE, PARTNO, QTYRETURN, AMTRETURN  FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    INTO :STORE, :PARTNO, STORE_QTY, STORE_AMOUNT
  DO
  BEGIN
    SELECT SUM(D.QTYF*D.KONVERSI+D.QTY), SUM(D.CALC_COST)
    FROM INVRET1 D
    LEFT JOIN INVRET0 H ON H.NUMBER = D.NUMBER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    AND H.STORE = :STORE
    AND D.PARTNO = :PARTNO
    INTO :QTY, :AMOUNT;

    IF (QTY IS NULL) THEN
    BEGIN
       QTY = 0;
       AMOUNT = 0;
    END

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          UPDATE INVSTOCK SET QTYRETURN = :QTY, AMTRETURN = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END

  /* ---------------------------------------------------------------- */
  /* ISSUING                                                          */
  /* ---------------------------------------------------------------- */
  CODE = 'ISUE';
  INFO = 'Issuing';

  FOR
    SELECT H.STORE, D.PARTNO, SUM(D.QTY) QTY, SUM(D.QTY*D.COST) AMOUNT
    FROM INVISS0 H
    INNER JOIN INVISS1 D ON H.NUMBER = D.NUMBER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    GROUP BY H.STORE, D.PARTNO
    INTO :STORE, :PARTNO, :QTY, :AMOUNT
  DO
  BEGIN
    SELECT QTYISSUE, AMTISSUE FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    AND STORE = :STORE AND PARTNO = :PARTNO
    INTO STORE_QTY, STORE_AMOUNT;

    /* ---------------------------------------------------------------- */
    /* 26 OCTOBER 2006                                                  */
    /* ---------------------------------------------------------------- */
    IF (STORE_QTY IS NULL) THEN
    BEGIN
       STORE_QTY = 0;
       STORE_AMOUNT = 0;
    END



    /* ---------------------------------------------------------------- */

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          UPDATE INVSTOCK SET QTYISSUE = :QTY, AMTISSUE = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* ISSUE DARI STORE                                                 */
  /* ---------------------------------------------------------------- */
  FOR SELECT STORE, PARTNO, QTYISSUE, AMTISSUE FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    INTO :STORE, :PARTNO, STORE_QTY, STORE_AMOUNT
  DO
  BEGIN
    SELECT SUM(D.QTY) , SUM(D.QTY*D.COST)
    FROM INVISS1 D
    LEFT JOIN INVISS0 H ON H.NUMBER = D.NUMBER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    AND H.STORE = :STORE
    AND D.PARTNO = :PARTNO
    INTO :QTY, :AMOUNT;

    IF (QTY IS NULL) THEN
    BEGIN
       QTY = 0;
       AMOUNT = 0;
    END

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          UPDATE INVSTOCK SET QTYISSUE = :QTY, AMTISSUE = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* ADJUSTMENT                                                       */
  /* ---------------------------------------------------------------- */
  CODE = 'ADJ';
  INFO = 'Adjustment';

  FOR
    SELECT H.STORE, D.PARTNO, SUM(D.QTY) QTY, SUM(D.QTY*D.COST) AMOUNT
    FROM INVADJ1 D
    INNER JOIN INVADJ0 H ON H.NUMBER = D.NUMBER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    GROUP BY H.STORE, D.PARTNO
    INTO :STORE, :PARTNO, :QTY, :AMOUNT
  DO
  BEGIN
    SELECT QTYADJ, AMTADJ FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    AND STORE = :STORE AND PARTNO = :PARTNO
    INTO STORE_QTY, STORE_AMOUNT;

    /* ---------------------------------------------------------------- */
    /* 26 OCTOBER 2006                                                  */
    /* ---------------------------------------------------------------- */
    IF (STORE_QTY IS NULL) THEN
    BEGIN
       STORE_QTY = 0;
       STORE_AMOUNT = 0;
    END



    /* ---------------------------------------------------------------- */

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          /* ---------------------------------------------------------------- */
          /* 6 NOVEMBER 2006                                                  */
          /* ---------------------------------------------------------------- */
          IF (NOT EXISTS(SELECT * FROM INVSTOCK WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
              AND STORE = :STORE AND PARTNO = :PARTNO)) THEN
          BEGIN
             INSERT INTO INVSTOCK (PYEAR, PMONTH, STORE, PARTNO)
             VALUES
             (:PYEAR, :PMONTH, :STORE, :PARTNO);
          END


          /* ---------------------------------------------------------------- */
          UPDATE INVSTOCK SET QTYADJ = :QTY, AMTADJ = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* ADJUSTMENT DARI STORE                                            */
  /* ---------------------------------------------------------------- */
  FOR SELECT STORE, PARTNO, QTYADJ, AMTADJ FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    INTO :STORE, :PARTNO, STORE_QTY, STORE_AMOUNT
  DO
  BEGIN
    SELECT SUM(D.QTY) , SUM(D.QTY*D.COST)
    FROM INVADJ1 D
    LEFT JOIN INVADJ0 H ON H.NUMBER = D.NUMBER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    AND H.STORE = :STORE
    AND D.PARTNO = :PARTNO
    INTO :QTY, :AMOUNT;

    IF (QTY IS NULL) THEN
    BEGIN
       QTY = 0;
       AMOUNT = 0;
    END

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          UPDATE INVSTOCK SET QTYADJ = :QTY, AMTADJ = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* SPOILAGE                                                         */
  /* ---------------------------------------------------------------- */
  CODE = 'SPL';
  INFO = 'Spoilage';

  FOR
    SELECT H.STORE, D.PARTNO, SUM(D.QTY) QTY, SUM(D.QTY*D.COST) AMOUNT
    FROM INVSPL1 D
    LEFT JOIN INVSPL0 H ON H.NUMBER = D.NUMBER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    GROUP BY H.STORE, D.PARTNO
    INTO :STORE, :PARTNO, :QTY, :AMOUNT
  DO
  BEGIN
    SELECT QTYSPOILAGE, AMTSPOILAGE FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    AND STORE = :STORE AND PARTNO = :PARTNO
    INTO STORE_QTY, STORE_AMOUNT;

    /* ---------------------------------------------------------------- */
    /* 26 OCTOBER 2006                                                  */
    /* ---------------------------------------------------------------- */
    IF (STORE_QTY IS NULL) THEN
    BEGIN
       STORE_QTY = 0;
       STORE_AMOUNT = 0;
    END



    /* ---------------------------------------------------------------- */

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          UPDATE INVSTOCK SET QTYSPOILAGE = :QTY, AMTSPOILAGE = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* SPOILAGE DARI STORE                                              */
  /* ---------------------------------------------------------------- */
  FOR SELECT STORE, PARTNO, QTYSPOILAGE, AMTSPOILAGE FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    INTO :STORE, :PARTNO, STORE_QTY, STORE_AMOUNT
  DO
  BEGIN
    SELECT SUM(D.QTY) , SUM(D.QTY*D.COST)
    FROM INVSPL1 D
    LEFT JOIN INVSPL0 H ON H.NUMBER = D.NUMBER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    AND H.STORE = :STORE
    AND D.PARTNO = :PARTNO
    INTO :QTY, :AMOUNT;

    IF (QTY IS NULL) THEN
    BEGIN
       QTY = 0;
       AMOUNT = 0;
    END

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          UPDATE INVSTOCK SET QTYADJ = :QTY, AMTADJ = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END

  /* ---------------------------------------------------------------- */
  /* 4 APRIL 2008                                                     */
  /* TRANSFER OUT                                                     */
  /* ---------------------------------------------------------------- */
  CODE = 'TRFO';
  INFO = 'Transfer Out';

  FOR
    SELECT H.STORE, D.PARTNO, SUM(D.QTY) QTY, SUM(D.QTY*D.COST) AMOUNT
    FROM INVTRF1 D
    LEFT JOIN INVTRF0 H ON H.NUMBER = D.NUMBER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    GROUP BY H.STORE, D.PARTNO
    INTO :STORE, :PARTNO, :QTY, :AMOUNT
  DO
  BEGIN
    SELECT QTYTRFOUT, AMTTRFOUT FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    AND STORE = :STORE AND PARTNO = :PARTNO
    INTO STORE_QTY, STORE_AMOUNT;

    IF (STORE_QTY IS NULL) THEN
    BEGIN
       STORE_QTY = 0;
       STORE_AMOUNT = 0;
    END

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          UPDATE INVSTOCK SET QTYTRFOUT = :QTY, AMTTRFOUT = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* TRANSFER OUT CALC FROM STOCK                                     */
  /* ---------------------------------------------------------------- */
  FOR SELECT STORE, PARTNO, QTYTRFOUT, AMTTRFOUT FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    INTO :STORE, :PARTNO, STORE_QTY, STORE_AMOUNT
  DO
  BEGIN
    SELECT SUM(D.QTY) , SUM(D.QTY*D.COST)
    FROM INVTRF1 D
    LEFT JOIN INVTRF0 H ON H.NUMBER = D.NUMBER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    AND H.STORE = :STORE
    AND D.PARTNO = :PARTNO
    INTO :QTY, :AMOUNT;

    IF (QTY IS NULL) THEN
    BEGIN
       QTY = 0;
       AMOUNT = 0;
    END

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          UPDATE INVSTOCK SET QTYTRFOUT = :QTY, AMTTRFOUT = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END


  /* ---------------------------------------------------------------- */
  /* 4 APRIL 2008                                                     */
  /* TRANSFER IN                                                      */
  /* ---------------------------------------------------------------- */
  CODE = 'TRFI';
  INFO = 'Transfer In';

  FOR
    SELECT H.STORETO, D.PARTNO, SUM(D.QTY) QTY, SUM(D.QTY*D.COST) AMOUNT
    FROM INVTRF1 D
    LEFT JOIN INVTRF0 H ON H.NUMBER = D.NUMBER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    GROUP BY H.STORETO, D.PARTNO
    INTO :STORE, :PARTNO, :QTY, :AMOUNT
  DO
  BEGIN
    SELECT QTYTRFIN, AMTTRFIN FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    AND STORE = :STORE AND PARTNO = :PARTNO
    INTO STORE_QTY, STORE_AMOUNT;

    IF (STORE_QTY IS NULL) THEN
    BEGIN
       STORE_QTY = 0;
       STORE_AMOUNT = 0;
    END

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          UPDATE INVSTOCK SET QTYTRFIN = :QTY, AMTTRFIN = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END
  /* ---------------------------------------------------------------- */
  /* TRANSFER IN CALC FROM STOCK                                      */
  /* ---------------------------------------------------------------- */
  FOR SELECT STORE, PARTNO, QTYTRFIN, AMTTRFIN FROM INVSTOCK
    WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
    INTO :STORE, :PARTNO, STORE_QTY, STORE_AMOUNT
  DO
  BEGIN
    SELECT SUM(D.QTY) , SUM(D.QTY*D.COST)
    FROM INVTRF1 D
    LEFT JOIN INVTRF0 H ON H.NUMBER = D.NUMBER
    WHERE H.OPENDATE BETWEEN :SDATE AND :EDATE AND STATUS IN ('R','C')
    AND H.STORETO = :STORE
    AND D.PARTNO = :PARTNO
    INTO :QTY, :AMOUNT;

    IF (QTY IS NULL) THEN
    BEGIN
       QTY = 0;
       AMOUNT = 0;
    END

    DELTA_QTY = STORE_QTY - QTY;
    DELTA_AMOUNT = STORE_AMOUNT - AMOUNT;
    IF ((DELTA_AMOUNT NOT BETWEEN -0.5 AND 0.5) OR
        (DELTA_QTY NOT BETWEEN -0.5 AND 0.5)) THEN
    BEGIN
       SELECT NAME FROM INVMASTER WHERE PARTNO = :PARTNO INTO NAME;
       IF (PSAVE = 0) THEN SUSPEND;
       ELSE
       BEGIN
          UPDATE INVSTOCK SET QTYTRFIN = :QTY, AMTTRFIN = :AMOUNT
          WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
          AND STORE = :STORE AND PARTNO = :PARTNO;
       END
    END
  END
END^


ALTER PROCEDURE INV_CHECK_INVSTOCK_OPENING(
    PYEAR INTEGER,
    PMONTH INTEGER,
    PSAVE INTEGER)
RETURNS (
    RYEAR INTEGER,
    RMONTH INTEGER,
    STORE VARCHAR(4),
    PARTNO VARCHAR(10),
    NAME VARCHAR(40),
    QTY_ONHAND DOUBLE PRECISION,
    AMT_ONHAND DOUBLE PRECISION,
    OYEAR INTEGER,
    OMONTH INTEGER,
    QTY_OPENING DOUBLE PRECISION,
    AMT_OPENING DOUBLE PRECISION,
    DELTA_QTY DOUBLE PRECISION,
    DELTA_AMT DOUBLE PRECISION)
AS
BEGIN
  /* ---------------------------------------------------------------- */
  /* SP UNTUK MENHITUNG APAKAH                                        */
  /* ENDING BULAN LALU == OPENING BULAN SEKARANG                      */
  /* PSAVE = 0    TAMPILKAN SAJA                                      */
  /* PSAVE = 1    UPDATE OPENING SAMA DENGAN ENDING LAST MONTH        */
  /* ---------------------------------------------------------------- */
  IF ((PYEAR IS NULL) OR (PYEAR = 0)) THEN
  BEGIN
     SELECT INV_YEAR, INV_MONTH FROM SYSPARAM INTO PYEAR, PMONTH;
     PSAVE = 0;
  END
  IF (PSAVE IS NULL) THEN PSAVE = 0;
  RYEAR = PYEAR;
  RMONTH = PMONTH;
  
  
  
  /* ---------------------------------------------------------------- */
  /* HITUNG BULAN LALU                                                */
  /* ---------------------------------------------------------------- */
  OYEAR = PYEAR;
  OMONTH = PMONTH-1;
  IF (OMONTH < 1) THEN
  BEGIN
     OMONTH = 12;
     OYEAR = OYEAR-1;
  END


  /* ---------------------------------------------------------------- */
  /* AMBIL SALDO BILAN LALU                                           */
  /* ---------------------------------------------------------------- */
  FOR
    SELECT STORE, PARTNO, NAME, QTYONHAND, AMTONHAND
    FROM INVSTOCK
    WHERE PYEAR = :OYEAR
    AND PMONTH = :OMONTH
    ORDER BY STORE, PARTNO
    INTO
      :STORE,
      :PARTNO,
      :NAME,
      :QTY_ONHAND,
      :AMT_ONHAND
  DO
  BEGIN
    /* ---------------------------------------------------------------- */
    /* 14 MARET 2008                                                    */
    /* ---------------------------------------------------------------- */
    IF (NOT EXISTS(SELECT QTYISSUE, AMTISSUE FROM INVSTOCK
               WHERE PYEAR = :PYEAR AND PMONTH = :PMONTH
               AND STORE = :STORE AND PARTNO = :PARTNO)) THEN
    BEGIN
      INSERT INTO INVSTOCK
      (PYEAR, PMONTH, STORE, PARTNO)
      VALUES
      (:PYEAR, :PMONTH, :STORE, :PARTNO);
    END
    /* ---------------------------------------------------------------- */
    /* END OF 14 MARET 2008                                             */
    /* ---------------------------------------------------------------- */
    SELECT QTYOPEN, AMTOPEN FROM INVSTOCK
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND STORE = :STORE
    AND PARTNO = :PARTNO
    INTO QTY_OPENING, AMT_OPENING;
    IF (QTY_OPENING IS NULL) THEN
    BEGIN
       QTY_OPENING = 0;
       AMT_OPENING = 0;
    END
    /* ---------------------------------------------------------------- */
    /* JIKA HANYA DITAMPILKAN SAJA                                      */
    /* ---------------------------------------------------------------- */
    IF (PSAVE = 0) THEN
    BEGIN
       IF ((QTY_OPENING <> QTY_ONHAND) OR (AMT_OPENING <> AMT_ONHAND)) THEN
       BEGIN
          DELTA_QTY = QTY_OPENING - QTY_ONHAND;
          DELTA_AMT = AMT_OPENING - AMT_ONHAND;
          SUSPEND;
       END
    END
    ELSE
    BEGIN
       UPDATE INVSTOCK SET QTYOPEN=:QTY_ONHAND, AMTOPEN=:AMT_ONHAND
       WHERE PYEAR = :PYEAR
       AND PMONTH = :PMONTH
       AND STORE = :STORE
       AND PARTNO = :PARTNO;
    END
  END
END^


