ALTER PROCEDURE INV_GL_INTERFACE_CONTROL(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    TEXT VARCHAR(40),
    INV DOUBLE PRECISION,
    BUFFER DOUBLE PRECISION,
    GL DOUBLE PRECISION,
    DELTA_BUFFER DOUBLE PRECISION,
    DELTA_INV DOUBLE PRECISION)
AS
declare variable SDATE DATE;
declare variable EDATE DATE;
begin
  if (PYEAR IS NULL) then
  BEGIN
     PYEAR = 2004;
     PMONTH = 9;
  END
  SDATE = '1.'||PMONTH||'.'||PYEAR;
  execute procedure sp_endofmonth SDATE returning_values EDATE;
  
  
  TEXT = 'Receiving';  
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'INV'
  AND SOURCE = 'RECV'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'INV'
  AND SOURCE = 'RECV'
  INTO :GL;
  
  SELECT SUM(TOTAL*EXCHANGE) FROM INVRECV0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R', 'C')
  INTO :INV;

  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;
  
  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;
  SUSPEND;
  /* ------------------------------------------------------------------ */
  TEXT = 'Issuing';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'INV'
  AND SOURCE = 'ISUE'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'INV'
  AND SOURCE = 'ISUE'
  INTO :GL;
  
  SELECT SUM(TOTAL) FROM INVISS0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R', 'C')
  INTO :INV;

  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;
   
  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;  
  suspend;
  /* ------------------------------------------------------------------ */
  TEXT = 'Credit To Cost';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'INV'
  AND SOURCE = 'CR2C'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'INV'
  AND SOURCE = 'CR2C'
  INTO :GL;
  
  SELECT SUM(TOTAL) FROM inv_crd_to_cost0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R', 'C')
  INTO :INV;  
  
  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;  
  suspend;  
  
  /* ------------------------------------------------------------------ */
  TEXT = 'Adjustment';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'INV'
  AND SOURCE = 'ADJ'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'INV'
  AND SOURCE = 'ADJ'
  INTO :GL;
  
  SELECT SUM(TOTAL) FROM INVADJ0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R', 'C')
  INTO :INV;  
  
  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV + BUFFER;  
  suspend;    
  
  /* ------------------------------------------------------------------ */
  TEXT = 'Spoilage';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'INV'
  AND SOURCE = 'SPL'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'INV'
  AND SOURCE = 'SPL'
  INTO :GL;
  
  SELECT SUM(TOTAL) FROM INVSPL0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R', 'C')
  INTO :INV;  
  
  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;

  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;  
  suspend;      
  
  /* ------------------------------------------------------------------ */
  TEXT = 'Return';
  SELECT SUM(DB) FROM GLBUFFER
  WHERE APPLICATION = 'INV'
  AND SOURCE = 'RET'
  AND TRANSDATE BETWEEN :SDATE AND :EDATE
  INTO :BUFFER;
  if (BUFFER IS NULL) then BUFFER = 0;

  SELECT SUM(DB) FROM GLJUR
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND APPLICATION = 'INV'
  AND SOURCE = 'RET'
  INTO :GL;
  
  SELECT SUM(TOTAL) FROM INVRET0
  WHERE OPENDATE BETWEEN :SDATE AND :EDATE
  AND STATUS IN ('R', 'C')
  INTO :INV;  

  if (BUFFER IS NULL) then BUFFER = 0;
  if (INV IS NULL) then INV = 0;
  if (GL IS NULL) then GL = 0;
    
  DELTA_BUFFER = BUFFER - GL;
  DELTA_INV    = INV - BUFFER;  
  suspend;        
  
end^


