ALTER PROCEDURE INV_LOOKUPCOST(
    USERID VARCHAR(8))
RETURNS (
    ICOST VARCHAR(4),
    NAME VARCHAR(40),
    COSTTYPE CHAR(1),
    TYPENAME VARCHAR(40))
AS
declare variable IROW INTEGER;
BEGIN
  if (EXISTS(SELECT * FROM SYSUSER_COST WHERE USERID = :USERID)) then
  BEGIN
    FOR SELECT S.ICOST,C.NAME,C.COSTTYPE,T.NAME
        FROM sysuser_cost S
        LEFT JOIN INVCOST C ON C.ICOST = S.ICOST
        LEFT JOIN INVTYPE  T ON T.ITYPE = C.COSTTYPE
        WHERE S.USERID = :userid
        AND ((C.FLAG_ACTIVE = 1) or (C.FLAG_ACTIVE IS NULL))
        INTO :ICOST,:NAME,:COSTTYPE,:TYPENAME
    DO SUSPEND;
  END
  ELSE
  BEGIN
    FOR SELECT C.ICOST,C.NAME,C.COSTTYPE,T.NAME FROM INVCOST C
        LEFT JOIN INVTYPE  T ON T.ITYPE = C.COSTTYPE
        WHERE ((C.FLAG_ACTIVE = 1) or (C.FLAG_ACTIVE IS NULL))
    INTO :ICOST,:NAME,:COSTTYPE,:TYPENAME
    DO SUSPEND;
  END
END^


