ALTER PROCEDURE INV_RPT_PO_TRACE_ADIW(
    SDATE DATE,
    EDATE DATE,
    SSUPPLIER VARCHAR(6),
    ESUPPLIER VARCHAR(6))
RETURNS (
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    NUMBER INTEGER,
    OPENDATE DATE,
    STORE VARCHAR(4),
    ICOST VARCHAR(4),
    PARTNO VARCHAR(10),
    NAME1 VARCHAR(40),
    UNIT VARCHAR(6),
    UNITF VARCHAR(6),
    QTY DOUBLE PRECISION,
    QTYF DOUBLE PRECISION,
    KONVERSI DOUBLE PRECISION,
    CALC_COST DOUBLE PRECISION,
    REQNO INTEGER,
    SOURCE VARCHAR(4),
    ML_NUMBER INTEGER,
    STATUS CHAR(1),
    PR_NUMBER INTEGER,
    PR_DATE DATE,
    PR_QTYF DOUBLE PRECISION,
    PR_QTY DOUBLE PRECISION,
    PR_KONVERSI DOUBLE PRECISION,
    PR_COST DOUBLE PRECISION)
AS
BEGIN
  FOR
    SELECT P0.SUPPLIER,S.NAME,P1.NUMBER,P0.OPENDATE,P0.STORE,P0.ICOST,P1.PARTNO,MST.NAME,MST.UNIT,
    MST.UNITF,P1.QTY,P1.QTYF,
    P1.KONVERSI,P1.CALC_COST,P1.REQNO,P1.ML_NUMBER,P0.STATUS
    FROM INVPO1 P1
    LEFT JOIN INVPO0 P0 ON P0.NUMBER = P1.NUMBER
    LEFT JOIN INVMASTER MST ON MST.PARTNO = P1.PARTNO
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = P0.SUPPLIER
    WHERE P0.OPENDATE BETWEEN :SDATE AND :EDATE
    AND P0.SUPPLIER BETWEEN :SSUPPLIER AND :ESUPPLIER
    AND P0.STATUS IN('R')

    INTO
      :SUPPLIER,
      :NAME,
      :NUMBER,
      :OPENDATE,
      :STORE,
      :ICOST,
      :PARTNO,
      :NAME1,
      :UNIT,
      :UNITF,
      :QTY,
      :QTYF,
      :KONVERSI,
      :CALC_COST,
      :REQNO,
      :ML_NUMBER,
      :STATUS
   /* -------------------------------------------------------------------- */
    /* PR                                                                   */
    /* -------------------------------------------------------------------- */

DO
BEGIN
 /* -------------------------------------------------------------------- */
    /*PO_DATE = NULL;
    PO_QTY = 0;
    PO_QTYF = 0;
    PO_KONVERSI = 0;
    PO_COST = 0;*/
    PR_NUMBER = 0;
    ML_NUMBER = 0;
    PR_DATE = NULL;
    PR_QTYF = 0;
    PR_QTY = 0;
    PR_KONVERSI = 0;
    PR_COST = 0;
    SOURCE = '';
    /* -------------------------------------------------------------------- */
    IF (REQNO <> 0) THEN
    BEGIN
        SOURCE = 'PR';
        SELECT OPENDATE FROM INVPR0 WHERE NUMBER = :REQNO
        INTO PR_DATE;

        SELECT QTY,QTYF,KONVERSI,CALC_UNITCOST_AFTERTAX
        FROM INVPR1
        WHERE NUMBER = :PR_NUMBER
        AND PARTNO = :PARTNO
        INTO PR_QTY,PR_QTYF,PR_KONVERSI,PR_COST;
    END
    /* -------------------------------------------------------------------- */
    /* ML                                                                   */
    /* -------------------------------------------------------------------- */
    IF (ML_NUMBER <> 0) THEN
    BEGIN
        SOURCE = 'ML';
        SELECT OPENDATE FROM INVMLORDER0 WHERE NUMBER = :ML_NUMBER
        INTO PR_DATE;

        SELECT QTY,QTYF,KONVERSI,COST
        FROM INVMLORDER1
        WHERE NUMBER = :ML_NUMBER
        AND PARTNO = :PARTNO
        INTO PR_QTY,PR_QTYF,PR_KONVERSI,PR_COST;
    END
    SUSPEND;
  END
END^


