ALTER PROCEDURE INV_RPT_RCONS_NDBH(
    PYEAR INTEGER,
    PMONTH INTEGER,
    ITEMTYPE CHAR(1))
RETURNS (
    RYEAR INTEGER,
    RMONTH INTEGER,
    TYPENAME VARCHAR(40),
    DATATYPE VARCHAR(12),
    INFO VARCHAR(12),
    TEXT VARCHAR(50),
    COSTTYPE CHAR(1),
    FLAG_PRODUCTION INTEGER,
    BOLD INTEGER,
    LINE INTEGER,
    AMOUNT DOUBLE PRECISION,
    LASTMONTH DOUBLE PRECISION,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4))
AS
declare variable opening     DOUBLE PRECISION;
declare variable ENDING      DOUBLE PRECISION;
declare variable RECV        DOUBLE PRECISION;
declare variable TCR2C       DOUBLE PRECISION;
declare variable DU          DOUBLE PRECISION;

declare variable L_opening   DOUBLE PRECISION;
declare variable L_ENDING    DOUBLE PRECISION;
declare variable L_RECV      DOUBLE PRECISION;
declare variable L_TCR2C     DOUBLE PRECISION;
declare variable L_DU        DOUBLE PRECISION;

declare variable SDATE       DATE;
declare variable EDATE       DATE;
declare variable SL_DATE     DATE;
declare variable EL_DATE     DATE;
declare variable SALES       DOUBLE PRECISION;
declare variable L_SALES     DOUBLE PRECISION;
declare variable SALESCOST   DOUBLE PRECISION;
declare variable OC_FOOD     DOUBLE PRECISION;
declare variable OC_BEVERAGE DOUBLE PRECISION;
declare variable TOC         DOUBLE PRECISION;
declare variable TCOST       DOUBLE PRECISION;
declare variable L_SALESCOST   DOUBLE PRECISION;
declare variable L_OC_FOOD     DOUBLE PRECISION;
declare variable L_OC_BEVERAGE DOUBLE PRECISION;
declare variable L_TOC         DOUBLE PRECISION;
declare variable L_TCOST       DOUBLE PRECISION;
declare variable CODE4       VARCHAR(4);
declare variable L_YEAR  INTEGER;
declare variable L_MONTH INTEGER;
declare variable TRF_TYPE CHAR(1);
declare variable TRF_AMOUNT    DOUBLE PRECISION;
declare variable TRF_LASTMONTH DOUBLE PRECISION;
declare variable FLAG_FIRST INTEGER;

declare variable SALES_FOOD DOUBLE PRECISION;
declare variable SALES_BEV  DOUBLE PRECISION;
declare variable L_SALES_FOOD DOUBLE PRECISION;
declare variable L_SALES_BEV  DOUBLE PRECISION;
declare variable ACCOUNT_COST VARCHAR(20);
begin
  if (PYEAR IS NULL) then
  BEGIN
    PYEAR = 2004;
    PMONTH = 9;
    ITEMTYPE = 'F';
  END
  
  if (ITEMTYPE = 'F') then
  BEGIN
     TRF_TYPE = 'B';
     ACCOUNT_COST = '3010';
  END
  ELSE if (ITEMTYPE = 'B') then
  BEGIN
     TRF_TYPE = 'F';
     ACCOUNT_COST = '3011';
  END
  
  RYEAR = PYEAR;
  RMONTH = PMONTH;
  FLAG_PRODUCTION = 0;
  
  SELECT NAME FROM invtype
  WHERE ITYPE = :ITEMTYPE
  INTO TYPENAME;
  
  COSTTYPE = '';
  
  SDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE sp_endofmonth(SDATE) returning_values (:EDATE);
  /* LAST MONTH */
  EL_DATE = SDATE -1;
  EXECUTE PROCEDURE sp_beginofmonth(EL_DATE) returning_values (:SL_DATE);
  
  L_YEAR  = EXTRACT(YEAR  FROM EL_DATE);
  L_MONTH = EXTRACT(MONTH FROM EL_DATE);
  /* ------------------------------------------------------------------------ */
  /* GET SALES                                                                */
  /* ------------------------------------------------------------------------ */  
  SALES = 0;
  L_SALES = 0;
  AMOUNT = 0;
  LASTMONTH = 0;
  if (ITEMTYPE IN ('F','B')) then
  BEGIN

     SELECT SUM(S.SALES_FOOD), SUM(S.SALES_BEV) FROM INVOUTLET_SALES S
     WHERE S.OPENDATE BETWEEN :SDATE AND :EDATE
     INTO SALES_FOOD, SALES_BEV;
     
     if (SALES_FOOD IS NULL) then
     BEGIN
        SALES_FOOD = 0;
        SALES_BEV  = 0;
     END

     SELECT SUM(S.SALES_FOOD), SUM(S.SALES_BEV) FROM INVOUTLET_SALES S
     WHERE S.OPENDATE BETWEEN :SL_DATE AND :EL_DATE
     INTO L_SALES_FOOD, L_SALES_BEV;

     if (L_SALES_FOOD IS NULL) then
     BEGIN
        L_SALES_FOOD = 0;
        L_SALES_BEV  = 0;
     END

     if (ITEMTYPE = 'F') then
     BEGIN
        AMOUNT = SALES_FOOD;
        LASTMONTH = L_SALES_FOOD;
     END
     ELSE
     if (ITEMTYPE = 'B') then
     BEGIN
        AMOUNT = SALES_BEV;
        LASTMONTH = L_SALES_BEV;
     END     
     
     SALES = AMOUNT;
     L_SALES = LASTMONTH;

     DATATYPE = 'SALES';
     INFO     = '';
     BOLD     = 1;
     LINE     = 1;
     TEXT     = 'Sales';
     SUSPEND;
     
     TEXT   = '';
     AMOUNT = 0;
     LASTMONTH = 0;
     BOLD   = 0;
     INFO   = '';
     SUSPEND;
  END
  
  /* ------------------------------------------------------------------------ */
  /* GET INVENTORY                                                            */
  /* ------------------------------------------------------------------------ */
  SELECT SUM(AMTOPEN), SUM(AMTONHAND), SUM(AMTIN-AMTRETURN)
  FROM INVSTOCK
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND ITYPE = :ITEMTYPE
  INTO :OPENING, :ENDING, :RECV;
  
  if (OPENING IS NULL) then
  BEGIN
     OPENING = 0;
     ENDING  = 0;
     RECV    = 0;
  END
  
/*
  SELECT SUM(DIRECTUSEAMT)
  FROM INVCONSUME
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND ITEMTYPE = :ITEMTYPE
  INTO :DU;
*/

  SELECT SUM(D.DIRECTUSEAMT)
  FROM INVCONSUME_DAILY D
  WHERE D.OPENDATE BETWEEN :SDATE AND :EDATE
  AND D.ITEMTYPE = :ITEMTYPE
  INTO :DU;
        
  if (DU IS NULL) then DU = 0;
  /* ------------------------------------------------------------------------ */
  /* LAST MONTH GET INVENTORY                                                 */
  /* ------------------------------------------------------------------------ */
  SELECT SUM(AMTOPEN), SUM(AMTONHAND), SUM(AMTIN-AMTRETURN)
  FROM INVSTOCK
  WHERE PYEAR = :L_YEAR
  AND PMONTH = :L_MONTH
  AND ITYPE = :ITEMTYPE
  INTO :L_OPENING, :L_ENDING, :L_RECV;
  
  if (L_OPENING IS NULL) then
  BEGIN
     L_OPENING = 0;
     L_ENDING  = 0;
     L_RECV    = 0;
  END  
  
  
  SELECT SUM(DIRECTUSEAMT)
  FROM INVCONSUME
  WHERE PYEAR = :L_YEAR
  AND PMONTH = :L_MONTH
  AND ITEMTYPE = :ITEMTYPE
  INTO :L_DU;
  if (L_DU IS NULL) then L_DU = 0;
  /* ------------------------------------------------------------------------ */
  /* OPENING INVENTORY                                                        */
  /* ------------------------------------------------------------------------ */
  DATATYPE = 'INVENTORY';
  BOLD = 1;
  LINE = 0;
  TEXT = 'Opening Inventory';
  AMOUNT = :OPENING;
  LASTMONTH = L_OPENING;
  INFO   = 'OPENING';
  suspend;
  /* ------------------------------------------------------------------------ */
  /* RECEIVING INVENTORY                                                      */
  /* ------------------------------------------------------------------------ */
  DATATYPE = 'INVENTORY';
  BOLD = 0;
  LINE = 0;
  TEXT = '    Receiving';
  AMOUNT = :RECV;
  LASTMONTH = L_RECV;
  INFO   = 'RECV';
  suspend;

  DATATYPE = 'INVENTORY';
  BOLD = 0;
  LINE = 0;
  TEXT = '    Direct Purchase';
  AMOUNT = :DU;
  LASTMONTH = L_DU;
  INFO   = 'DU';
  suspend;    
  /* ------------------------------------------------------------------------ */
  /* AVAILABLE INVENTORY                                                      */
  /* ------------------------------------------------------------------------ */  
  DATATYPE = 'INVENTORY';
  BOLD = 1;
  LINE = 1;
  TEXT = 'Available Inventory';
  AMOUNT = :OPENING+:RECV+:DU;
  LASTMONTH = :L_OPENING+:L_RECV+L_DU;
  INFO   = 'AVAILABLE';
  suspend;  
  /* ------------------------------------------------------------------------ */
  /* ENDING INVENTORY                                                         */
  /* ------------------------------------------------------------------------ */    
  DATATYPE = 'INVENTORY';
  BOLD = 0;
  LINE = 0;
  TEXT = '    Ending Inventory';
  AMOUNT = :ENDING;
  LASTMONTH = :L_ENDING;
  INFO   = 'ENDING';
  suspend;  
  /* ------------------------------------------------------------------------ */
  /* CONSUMPTION INVENTORY                                                    */
  /* ------------------------------------------------------------------------ */    
  DATATYPE = 'INVENTORY';
  BOLD = 1;
  LINE = 1;
  TEXT = 'Consumption';
  AMOUNT = :OPENING+:RECV+DU-ENDING;
  LASTMONTH = :L_OPENING+:L_RECV+L_DU-L_ENDING;
  INFO   = 'CONSUME';
  suspend;  
  TCOST = AMOUNT;
  L_TCOST = LASTMONTH;
  /* ------------------------------------------------------------------------ */
  /* DETAIL CONSUMPTION                                                       */
  /* ------------------------------------------------------------------------ */
  DATATYPE = 'CR2C';
  TEXT = '';
  AMOUNT = 0;
  LINE = 0;
  BOLD = 0;
  LASTMONTH = 0;
  INFO   = '';
  SUSPEND;
  TEXT = 'Credit To Cost';
  BOLD = 1;
  SUSPEND;
  BOLD = 0;
  TCR2C = 0;
  L_TCR2C = 0;
  FOR SELECT C.ICOST, C.NAME, D.GL_ACCOUNT, D.GL_DEPT, D.GL_COST, SUM(D.AMTTOTAL)
      FROM INVCONSUME_DAILY D
      LEFT JOIN INVCOST C ON C.ICOST = D.ICOST
      WHERE D.OPENDATE BETWEEN :SDATE AND :EDATE
      AND D.ITEMTYPE = :ITEMTYPE
      AND D.GL_ACCOUNT <> :ACCOUNT_COST
      GROUP BY C.ICOST, C.NAME, D.GL_ACCOUNT, D.GL_DEPT, D.GL_COST
      INTO :CODE4, :TEXT, GL_ACCOUNT, GL_DEPT, GL_COST, AMOUNT
  DO
  BEGIN
     INFO = CODE4;

     TEXT = '    ' || TEXT;
     TCR2C   = TCR2C   + AMOUNT;
     L_TCR2C = L_TCR2C + LASTMONTH;
     if ((AMOUNT <> 0) or (LASTMONTH <> 0)) then
        SUSPEND;
  end /* for   table */
  TEXT = 'Total Credit To Cost';
  LINE = 1;
  BOLD = 1;
  AMOUNT = TCR2C;
  INFO   = '';
  COSTTYPE = '';
  FLAG_PRODUCTION = 0;
  LASTMONTH = L_TCR2C;
  SUSPEND;
  /* ------------------------------------------------------------------------ */
  TRF_AMOUNT = 0;
  TRF_LASTMONTH = 0;
  DATATYPE = 'MIX';
  TEXT = '';
  AMOUNT = 0;
  LINE = 0;
  BOLD = 0;
  LASTMONTH = 0;
  INFO   = '';
  SUSPEND;
  if (ITEMTYPE = 'F') then TEXT = 'Food For Cooking';
  ELSE TEXT = 'Beverage For Cooking';
  BOLD = 1;
  SUSPEND;
  BOLD = 0;
  FOR SELECT C.ICOST, C.NAME, D.GL_ACCOUNT, D.GL_DEPT, D.GL_COST, SUM(D.AMTTOTAL)
      FROM INVCONSUME_DAILY D
      LEFT JOIN INVCOST C ON C.ICOST = D.ICOST
      WHERE D.OPENDATE BETWEEN :SDATE AND :EDATE
      AND D.ITEMTYPE = :TRF_TYPE
      AND D.GL_ACCOUNT = :ACCOUNT_COST
      GROUP BY C.ICOST, C.NAME, D.GL_ACCOUNT, D.GL_DEPT, D.GL_COST
      INTO :CODE4, :TEXT, GL_ACCOUNT, GL_DEPT, GL_COST, AMOUNT
  DO
  BEGIN
     INFO = CODE4;

     TEXT = '    ' || TEXT;
     TRF_AMOUNT   = TRF_AMOUNT   + AMOUNT;
     TRF_LASTMONTH = TRF_LASTMONTH + LASTMONTH;
     if ((AMOUNT <> 0) or (LASTMONTH <> 0)) then
        SUSPEND;
  end /* for   table */
  if (ITEMTYPE = 'F') then TEXT = 'Total Food For Cooking';
  ELSE TEXT = 'Total Beverage For Cooking';
  LINE = 1;
  BOLD = 1;
  AMOUNT = TRF_AMOUNT;
  INFO   = '';
  COSTTYPE = '';
  FLAG_PRODUCTION = 0;
  LASTMONTH = TRF_LASTMONTH;
  SUSPEND;  
  /* ------------------------------------------------------------------------ */
  /* OC AND HOUSE USE                                                         */
  /* ------------------------------------------------------------------------ */
  TOC = 0;
  L_TOC = 0;
  
  FLAG_FIRST = 1;
  FOR SELECT C.ICOST, C.NAME, C.COSTTYPE, C.FLAG_PRODUCTION FROM INVCOST C
      ORDER BY C.NAME
     INTO :CODE4, :TEXT, COSTTYPE, FLAG_PRODUCTION
  DO
  BEGIN
       INFO = CODE4;
       select SUM(OC.FOOD), SUM(OC.BEVERAGE)
       from INV_OC OC
       where OC.OPENDATE BETWEEN :SDATE AND :EDATE
       AND OC.ICOST = :CODE4
       into OC_FOOD, OC_BEVERAGE;

       select SUM(OC.FOOD), SUM(OC.BEVERAGE)
       from INV_OC OC
       where OC.OPENDATE BETWEEN :SL_DATE AND :EL_DATE
       AND OC.ICOST = :CODE4
       into L_OC_FOOD, L_OC_BEVERAGE;


       if (ITEMTYPE = 'F') then
       BEGIN
          AMOUNT = OC_FOOD;
          LASTMONTH = L_OC_FOOD;
       END
       ELSE
       BEGIN
         AMOUNT = OC_BEVERAGE;
         LASTMONTH = L_OC_BEVERAGE;
       END

       if (AMOUNT IS NULL) then AMOUNT = 0;
       if (LASTMONTH IS NULL) then LASTMONTH = 0;
          
       if ((AMOUNT <> 0) or (LASTMONTH <> 0)) then
       BEGIN
          if (FLAG_FIRST = 1) then
          BEGIN
             DATATYPE = 'OC';
             TEXT = '';
             AMOUNT = 0;
             LASTMONTH = 0;
             LINE = 0;
             BOLD = 0;
             INFO   = '';
             SUSPEND;          
             TEXT = 'Credit To Cost (House Use/Compliment)';
             BOLD = 1;
             SUSPEND;
             BOLD = 0;
             TOC  = 0;
             L_TOC = 0;
          END
          TOC = TOC + AMOUNT;
          L_TOC = L_TOC + LASTMONTH;
          TEXT = '   ' || TEXT;
          SUSPEND;
          FLAG_FIRST = 0;
       END
  end
  if (FLAG_FIRST <> 1) then
  BEGIN
    TEXT = 'Total House Use/Compliment';
    LINE = 1;
    BOLD = 1;
    AMOUNT = TOC;
    LASTMONTH = L_TOC;
    INFO   = '';
    COSTTYPE = '';
    SUSPEND;
  END
  /* --------------------------------------------------------------------- */
  /* COGS HEADER                                                           */
  /* --------------------------------------------------------------------- */
  DATATYPE = 'COGS';
  TEXT = '';
  AMOUNT = 0;
  LINE = 0;
  BOLD = 0;
  INFO   = '';
  LASTMONTH = 0;
  SUSPEND;
  /* --------------------------------------------------------------------- */
  /* COGS                                                                  */
  /* --------------------------------------------------------------------- */
  TCOST   = TCOST   - TCR2C   - TOC + TRF_AMOUNT;
  L_TCOST = L_TCOST - L_TCR2C - L_TOC + TRF_LASTMONTH;
  TEXT = 'Cost of Goods Sold';
  AMOUNT = TCOST;
  LASTMONTH = L_TCOST;
  LINE = 1;
  BOLD = 1;
  INFO   = 'COGS';
  SUSPEND;
  /* --------------------------------------------------------------------- */
  /* COGS BLANK                                                            */
  /* --------------------------------------------------------------------- */
  DATATYPE = 'COGS';
  TEXT = '';
  AMOUNT = 0;
  LASTMONTH = 0;
  LINE = 0;
  BOLD = 0;
  INFO   = '';
  SUSPEND;
  /* --------------------------------------------------------------------- */
  /* % COGS                                                                */
  /* --------------------------------------------------------------------- */
  DATATYPE = 'COGS';
  if (ITEMTYPE = 'F') then TEXT = 'Food Cost Percentage';
  ELSE TEXT = 'Beverage Cost Percentage';

  if (SALES <> 0) then AMOUNT = TCOST / SALES*100;
  ELSE AMOUNT = 0;
     
  if (L_SALES <> 0) then LASTMONTH = L_TCOST / L_SALES*100;
  ELSE LASTMONTH = 0;
     
  LINE = 0;
  BOLD = 0;
  INFO   = '%';
  SUSPEND;
end^


ALTER PROCEDURE INV_RPT_RCONS_OLD(
    PYEAR INTEGER,
    PMONTH INTEGER,
    ITEMTYPE CHAR(1))
RETURNS (
    RYEAR INTEGER,
    RMONTH INTEGER,
    TYPENAME VARCHAR(40),
    DATATYPE VARCHAR(12),
    INFO VARCHAR(12),
    TEXT VARCHAR(50),
    COSTTYPE CHAR(1),
    FLAG_PRODUCTION INTEGER,
    BOLD INTEGER,
    LINE INTEGER,
    AMOUNT DOUBLE PRECISION,
    LASTMONTH DOUBLE PRECISION)
AS
declare variable opening     DOUBLE PRECISION;
declare variable ENDING      DOUBLE PRECISION;
declare variable RECV        DOUBLE PRECISION;
declare variable TCR2C       DOUBLE PRECISION;
declare variable DU          DOUBLE PRECISION;

declare variable L_opening   DOUBLE PRECISION;
declare variable L_ENDING    DOUBLE PRECISION;
declare variable L_RECV      DOUBLE PRECISION;
declare variable L_TCR2C     DOUBLE PRECISION;
declare variable L_DU        DOUBLE PRECISION;

declare variable SDATE       DATE;
declare variable EDATE       DATE;
declare variable SL_DATE     DATE;
declare variable EL_DATE     DATE;
declare variable SALES       DOUBLE PRECISION;
declare variable L_SALES     DOUBLE PRECISION;
declare variable SALESCOST   DOUBLE PRECISION;
declare variable OC_FOOD     DOUBLE PRECISION;
declare variable OC_BEVERAGE DOUBLE PRECISION;
declare variable TOC         DOUBLE PRECISION;
declare variable TCOST       DOUBLE PRECISION;
declare variable L_SALESCOST   DOUBLE PRECISION;
declare variable L_OC_FOOD     DOUBLE PRECISION;
declare variable L_OC_BEVERAGE DOUBLE PRECISION;
declare variable L_TOC         DOUBLE PRECISION;
declare variable L_TCOST       DOUBLE PRECISION;
declare variable CODE4       VARCHAR(4);
declare variable L_YEAR  INTEGER;
declare variable L_MONTH INTEGER;
declare variable TRF_TYPE CHAR(1);
declare variable TRF_AMOUNT    DOUBLE PRECISION;
declare variable TRF_LASTMONTH DOUBLE PRECISION;
declare variable FLAG_FIRST INTEGER;

declare variable SALES_FOOD DOUBLE PRECISION;
declare variable SALES_BEV  DOUBLE PRECISION;
declare variable L_SALES_FOOD DOUBLE PRECISION;
declare variable L_SALES_BEV  DOUBLE PRECISION;
begin
  if (PYEAR IS NULL) then
  BEGIN
    SELECT INV_YEAR, INV_MONTH FROM SYSPARAM
    WHERE ID = 1
    INTO :PYEAR, :PMONTH;
    ITEMTYPE = 'F';
  END
  
  if (ITEMTYPE = 'F') then
  BEGIN
     TRF_TYPE = 'B';
  END
  ELSE if (ITEMTYPE = 'B') then
  BEGIN
     TRF_TYPE = 'F';
  END
  
  RYEAR = PYEAR;
  RMONTH = PMONTH;
  FLAG_PRODUCTION = 0;
  
  SELECT NAME FROM invtype
  WHERE ITYPE = :ITEMTYPE
  INTO TYPENAME;
  
  COSTTYPE = '';
  
  SDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE sp_endofmonth(SDATE) returning_values (:EDATE);
  /* LAST MONTH */
  EL_DATE = SDATE -1;
  EXECUTE PROCEDURE sp_beginofmonth(EL_DATE) returning_values (:SL_DATE);
  
  L_YEAR  = EXTRACT(YEAR  FROM EL_DATE);
  L_MONTH = EXTRACT(MONTH FROM EL_DATE);
  /* ------------------------------------------------------------------------ */
  /* GET SALES                                                                */
  /* ------------------------------------------------------------------------ */  
  SALES = 0;
  L_SALES = 0;
  AMOUNT = 0;
  LASTMONTH = 0;
  if (ITEMTYPE IN ('F','B')) then
  BEGIN

     SELECT SUM(S.SALES_FOOD), SUM(S.SALES_BEV) FROM INVOUTLET_SALES S
     WHERE S.OPENDATE BETWEEN :SDATE AND :EDATE
     INTO SALES_FOOD, SALES_BEV;
     
     if (SALES_FOOD IS NULL) then
     BEGIN
        SALES_FOOD = 0;
        SALES_BEV  = 0;
     END

     SELECT SUM(S.SALES_FOOD), SUM(S.SALES_BEV) FROM INVOUTLET_SALES S
     WHERE S.OPENDATE BETWEEN :SL_DATE AND :EL_DATE
     INTO L_SALES_FOOD, L_SALES_BEV;

     if (L_SALES_FOOD IS NULL) then
     BEGIN
        L_SALES_FOOD = 0;
        L_SALES_BEV  = 0;
     END

     if (ITEMTYPE = 'F') then
     BEGIN
        AMOUNT = SALES_FOOD;
        LASTMONTH = L_SALES_FOOD;
     END
     ELSE
     if (ITEMTYPE = 'B') then
     BEGIN
        AMOUNT = SALES_BEV;
        LASTMONTH = L_SALES_BEV;
     END     
     
     SALES = AMOUNT;
     L_SALES = LASTMONTH;

     DATATYPE = 'SALES';
     INFO     = '';
     BOLD     = 1;
     LINE     = 1;
     TEXT     = 'Sales';
     SUSPEND;
     
     TEXT   = '';
     AMOUNT = 0;
     LASTMONTH = 0;
     BOLD   = 0;
     INFO   = '';
     SUSPEND;
  END
  
  /* ------------------------------------------------------------------------ */
  /* GET INVENTORY                                                            */
  /* ------------------------------------------------------------------------ */
  SELECT SUM(AMTOPEN), SUM(AMTONHAND), SUM(AMTIN-AMTRETURN)
  FROM INVSTOCK
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND ITYPE = :ITEMTYPE
  INTO :OPENING, :ENDING, :RECV;
  
  if (OPENING IS NULL) then
  BEGIN
     OPENING = 0;
     ENDING  = 0;
     RECV    = 0;
  END
  
  
  SELECT SUM(DIRECTUSEAMT)
  FROM INVCONSUME
  WHERE PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND ITEMTYPE = :ITEMTYPE
  INTO :DU;
  if (DU IS NULL) then DU = 0;
  /* ------------------------------------------------------------------------ */
  /* LAST MONTH GET INVENTORY                                                 */
  /* ------------------------------------------------------------------------ */
  SELECT SUM(AMTOPEN), SUM(AMTONHAND), SUM(AMTIN-AMTRETURN)
  FROM INVSTOCK
  WHERE PYEAR = :L_YEAR
  AND PMONTH = :L_MONTH
  AND ITYPE = :ITEMTYPE
  INTO :L_OPENING, :L_ENDING, :L_RECV;
  
  if (L_OPENING IS NULL) then
  BEGIN
     L_OPENING = 0;
     L_ENDING  = 0;
     L_RECV    = 0;
  END  
  
  
  SELECT SUM(DIRECTUSEAMT)
  FROM INVCONSUME
  WHERE PYEAR = :L_YEAR
  AND PMONTH = :L_MONTH
  AND ITEMTYPE = :ITEMTYPE
  INTO :L_DU;
  if (L_DU IS NULL) then L_DU = 0;
  /* ------------------------------------------------------------------------ */
  /* OPENING INVENTORY                                                        */
  /* ------------------------------------------------------------------------ */
  DATATYPE = 'INVENTORY';
  BOLD = 1;
  LINE = 0;
  TEXT = 'Opening Inventory';
  AMOUNT = :OPENING;
  LASTMONTH = L_OPENING;
  INFO   = 'OPENING';
  suspend;
  /* ------------------------------------------------------------------------ */
  /* RECEIVING INVENTORY                                                      */
  /* ------------------------------------------------------------------------ */
  DATATYPE = 'INVENTORY';
  BOLD = 0;
  LINE = 0;
  TEXT = '    Receiving';
  AMOUNT = :RECV;
  LASTMONTH = L_RECV;
  INFO   = 'RECV';
  suspend;

  DATATYPE = 'INVENTORY';
  BOLD = 0;
  LINE = 0;
  TEXT = '    Direct Purchase';
  AMOUNT = :DU;
  LASTMONTH = L_DU;
  INFO   = 'DU';
  suspend;    
  /* ------------------------------------------------------------------------ */
  /* AVAILABLE INVENTORY                                                      */
  /* ------------------------------------------------------------------------ */  
  DATATYPE = 'INVENTORY';
  BOLD = 1;
  LINE = 1;
  TEXT = 'Available Inventory';
  AMOUNT = :OPENING+:RECV+:DU;
  LASTMONTH = :L_OPENING+:L_RECV+L_DU;
  INFO   = 'AVAILABLE';
  suspend;  
  /* ------------------------------------------------------------------------ */
  /* ENDING INVENTORY                                                         */
  /* ------------------------------------------------------------------------ */    
  DATATYPE = 'INVENTORY';
  BOLD = 0;
  LINE = 0;
  TEXT = '    Ending Inventory';
  AMOUNT = :ENDING;
  LASTMONTH = :L_ENDING;
  INFO   = 'ENDING';
  suspend;  
  /* ------------------------------------------------------------------------ */
  /* CONSUMPTION INVENTORY                                                    */
  /* ------------------------------------------------------------------------ */    
  DATATYPE = 'INVENTORY';
  BOLD = 1;
  LINE = 1;
  TEXT = 'Consumption';
  AMOUNT = :OPENING+:RECV+DU-ENDING;
  LASTMONTH = :L_OPENING+:L_RECV+L_DU-L_ENDING;
  INFO   = 'CONSUME';
  suspend;  
  TCOST = AMOUNT;
  L_TCOST = LASTMONTH;
  /* ------------------------------------------------------------------------ */
  /* DETAIL CONSUMPTION                                                       */
  /* ------------------------------------------------------------------------ */
  DATATYPE = 'CR2C';
  TEXT = '';
  AMOUNT = 0;
  LINE = 0;
  BOLD = 0;
  LASTMONTH = 0;
  INFO   = '';
  SUSPEND;
  TEXT = 'Credit To Cost';
  BOLD = 1;
  SUSPEND;
  BOLD = 0;
  TCR2C = 0;
  L_TCR2C = 0;
  FOR SELECT C.ICOST, C.NAME, C.COSTTYPE, C.FLAG_PRODUCTION FROM INVCOST C
      ORDER BY C.NAME
      INTO :CODE4, :TEXT, COSTTYPE, FLAG_PRODUCTION
  DO
  BEGIN
     INFO = CODE4;
     SELECT SUM(C.AMTTOTAL) FROM INVCONSUME C
     where (PYEAR = :PYEAR)
     AND (PMONTH = :PMONTH)
     AND (ICOST = :CODE4)
     AND (ITEMTYPE = :ITEMTYPE)
     INTO :AMOUNT;
     
     SELECT SUM(C.AMTTOTAL) FROM INVCONSUME C
     where (PYEAR = :L_YEAR)
     AND (PMONTH = :L_MONTH)
     AND (ICOST = :CODE4)
     AND (ITEMTYPE = :ITEMTYPE)
     INTO :LASTMONTH;
     
     if (AMOUNT IS NULL) then AMOUNT = 0;
     if (LASTMONTH IS NULL) then LASTMONTH = 0;



     TEXT = '    ' || TEXT;
     if (ITEMTYPE <> COSTTYPE) then FLAG_PRODUCTION = 0;
     
     if (FLAG_PRODUCTION=0) then
     BEGIN
        TCR2C   = TCR2C   + AMOUNT;
        L_TCR2C = L_TCR2C + LASTMONTH;
        if ((AMOUNT <> 0) or (LASTMONTH <> 0)) then
           SUSPEND;
     END
  end /* for   table */
  TEXT = 'Total Credit To Cost';
  LINE = 1;
  BOLD = 1;
  AMOUNT = TCR2C;
  INFO   = '';
  COSTTYPE = '';
  FLAG_PRODUCTION = 0;
  LASTMONTH = L_TCR2C;
  SUSPEND;
  /* ------------------------------------------------------------------------ */
  /* FOOD FOR MIXING or (BEVERRAGE FOR COOKING)                               */
  /* ------------------------------------------------------------------------ */
  TRF_AMOUNT = 0;
  TRF_LASTMONTH = 0;
  DATATYPE = 'TRF';
  TEXT = '';
  AMOUNT = 0;
  LINE = 0;
  BOLD = 0;
  LASTMONTH = 0;
  INFO   = '';
  SUSPEND;
  if (ITEMTYPE = 'B') then TEXT = 'Food for Mixing';
  ELSE TEXT = 'Beverage for Cooking';
  BOLD = 1;
  SUSPEND;
  BOLD = 0;
  FOR SELECT C.ICOST, C.NAME, C.COSTTYPE, C.FLAG_PRODUCTION FROM INVCOST C
      WHERE FLAG_PRODUCTION = 1
      AND C.COSTTYPE = :ITEMTYPE
      ORDER BY C.NAME
      INTO :CODE4, :TEXT, COSTTYPE, FLAG_PRODUCTION
  DO
  BEGIN
     SELECT SUM(C.AMTTOTAL) FROM INVCONSUME C
     where (PYEAR = :PYEAR)
     AND (PMONTH = :PMONTH)
     AND (ICOST = :CODE4)
     AND (ITEMTYPE = :TRF_TYPE)
     INTO :AMOUNT;
     
     SELECT SUM(C.AMTTOTAL) FROM INVCONSUME C
     where (PYEAR = :L_YEAR)
     AND (PMONTH = :L_MONTH)
     AND (ICOST = :CODE4)
     AND (ITEMTYPE = :TRF_TYPE)
     INTO :LASTMONTH;

     if (AMOUNT IS NULL) then AMOUNT = 0;
     if (LASTMONTH IS NULL) then LASTMONTH = 0;

     TEXT = '    ' || TEXT;
       
     TRF_AMOUNT    = TRF_AMOUNT + AMOUNT;
     TRF_LASTMONTH = TRF_LASTMONTH + LASTMONTH;

     if ((AMOUNT <> 0) or (LASTMONTH <> 0)) then
        SUSPEND;
  end /* for   table */
  if (ITEMTYPE = 'B') then TEXT = 'Total Food for Mixing';
  ELSE TEXT = 'Total Beverage for Cooking';
  LINE = 1;
  BOLD = 1;
  AMOUNT = TRF_AMOUNT;
  INFO   = '';
  COSTTYPE = '';
  FLAG_PRODUCTION = 0;
  LASTMONTH = TRF_LASTMONTH;
  SUSPEND;
  /* ------------------------------------------------------------------------ */
  /* OC AND HOUSE USE                                                         */
  /* ------------------------------------------------------------------------ */
  TOC = 0;
  L_TOC = 0;
  
  FLAG_FIRST = 1;
  FOR SELECT C.ICOST, C.NAME, C.COSTTYPE, C.FLAG_PRODUCTION FROM INVCOST C
      ORDER BY C.NAME
     INTO :CODE4, :TEXT, COSTTYPE, FLAG_PRODUCTION
  DO
  BEGIN
       INFO = CODE4;
       select SUM(OC.FOOD), SUM(OC.BEVERAGE)
       from INV_OC OC
       where OC.OPENDATE BETWEEN :SDATE AND :EDATE
       AND OC.ICOST = :CODE4
       into OC_FOOD, OC_BEVERAGE;

       select SUM(OC.FOOD), SUM(OC.BEVERAGE)
       from INV_OC OC
       where OC.OPENDATE BETWEEN :SL_DATE AND :EL_DATE
       AND OC.ICOST = :CODE4
       into L_OC_FOOD, L_OC_BEVERAGE;


       if (ITEMTYPE = 'F') then
       BEGIN
          AMOUNT = OC_FOOD;
          LASTMONTH = L_OC_FOOD;
       END
       ELSE
       BEGIN
         AMOUNT = OC_BEVERAGE;
         LASTMONTH = L_OC_BEVERAGE;
       END

       if (AMOUNT IS NULL) then AMOUNT = 0;
       if (LASTMONTH IS NULL) then LASTMONTH = 0;
          
       if ((AMOUNT <> 0) or (LASTMONTH <> 0)) then
       BEGIN
          if (FLAG_FIRST = 1) then
          BEGIN
             DATATYPE = 'OC';
             TEXT = '';
             AMOUNT = 0;
             LASTMONTH = 0;
             LINE = 0;
             BOLD = 0;
             INFO   = '';
             SUSPEND;          
             TEXT = 'Credit To Cost (House Use/Compliment)';
             BOLD = 1;
             SUSPEND;
             BOLD = 0;
             TOC  = 0;
             L_TOC = 0;
          END
          TOC = TOC + AMOUNT;
          L_TOC = L_TOC + LASTMONTH;
          TEXT = '   ' || TEXT;
          SUSPEND;
          FLAG_FIRST = 0;
       END
  end
  if (FLAG_FIRST <> 1) then
  BEGIN
    TEXT = 'Total House Use/Compliment';
    LINE = 1;
    BOLD = 1;
    AMOUNT = TOC;
    LASTMONTH = L_TOC;
    INFO   = '';
    COSTTYPE = '';
    SUSPEND;
  END
  /* --------------------------------------------------------------------- */
  /* COGS HEADER                                                           */
  /* --------------------------------------------------------------------- */
  DATATYPE = 'COGS';
  TEXT = '';
  AMOUNT = 0;
  LINE = 0;
  BOLD = 0;
  INFO   = '';
  LASTMONTH = 0;
  SUSPEND;
  /* --------------------------------------------------------------------- */
  /* COGS                                                                  */
  /* --------------------------------------------------------------------- */
  TCOST   = TCOST   - TCR2C   - TRF_AMOUNT    - TOC;
  L_TCOST = L_TCOST - L_TCR2C - TRF_LASTMONTH - L_TOC;
  TEXT = 'Cost of Goods Sold';
  AMOUNT = TCOST;
  LASTMONTH = L_TCOST;
  LINE = 1;
  BOLD = 1;
  INFO   = 'COGS';
  SUSPEND;
  /* --------------------------------------------------------------------- */
  /* COGS BLANK                                                            */
  /* --------------------------------------------------------------------- */
  DATATYPE = 'COGS';
  TEXT = '';
  AMOUNT = 0;
  LASTMONTH = 0;
  LINE = 0;
  BOLD = 0;
  INFO   = '';
  SUSPEND;
  /* --------------------------------------------------------------------- */
  /* % COGS                                                                */
  /* --------------------------------------------------------------------- */
  DATATYPE = 'COGS';
  if (ITEMTYPE = 'F') then TEXT = 'Food Cost Percentage';
  ELSE TEXT = 'Beverage Cost Percentage';

  if (SALES <> 0) then AMOUNT = TCOST / SALES*100;
  ELSE AMOUNT = 0;
     
  if (L_SALES <> 0) then LASTMONTH = L_TCOST / L_SALES*100;
  ELSE LASTMONTH = 0;
     
  LINE = 0;
  BOLD = 0;
  INFO   = '%';
  SUSPEND;
end^


