ALTER PROCEDURE INV_RPT_RCONS_SETUP_CHECKER(
    PYEAR INTEGER,
    PMONTH INTEGER,
    ITEMTYPE CHAR(1))
RETURNS (
    DATASECTION VARCHAR(30),
    DATATYPE VARCHAR(30),
    ICOST VARCHAR(4),
    ICOSTNAME VARCHAR(40),
    IGROUP VARCHAR(4),
    IGROUPNAME VARCHAR(40),
    AMOUNT_TRANSFER DOUBLE PRECISION,
    AMOUNT_COGS DOUBLE PRECISION,
    AMOUNT_MISSED DOUBLE PRECISION,
    COGS_ACCOUNT VARCHAR(20),
    XACCOUNT VARCHAR(20),
    XACCOUNT_NAME VARCHAR(40))
AS
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE EDATE DATE;
DECLARE VARIABLE AMT DOUBLE PRECISION;
DECLARE VARIABLE XTYPE CHAR(1);
DECLARE VARIABLE FLAG_PRODUCTION INTEGER;
BEGIN
  IF (PYEAR = 0) THEN
  BEGIN
     PYEAR = 2006;
     PMONTH = 10;
     ITEMTYPE = 'F';
  END

  SDATE = '1.'||PMONTH||'.'||PYEAR;
  EXECUTE PROCEDURE SP_ENDOFMONTH(SDATE) RETURNING_VALUES(EDATE);

  IF (ITEMTYPE = 'F') THEN
     SELECT INV_ACCOUNT_FOOD_COST FROM SYSPARAM INTO COGS_ACCOUNT;
  ELSE
     SELECT INV_ACCOUNT_BEV_COST FROM SYSPARAM INTO COGS_ACCOUNT;

  DATASECTION = 'Consumption';


  FOR SELECT ICOST, NAME FROM INVCOST
      WHERE FLAG_PRODUCTION = 1
      AND COSTTYPE = :ITEMTYPE
  INTO ICOST, ICOSTNAME
  DO
  BEGIN
    FOR SELECT G.GRP, G.NAME, G.GRPTYPE, AC.GL_ACCOUNT, SUM(CD.AMTTOTAL)
        FROM INVCONSUME_DAILY CD
        LEFT JOIN INVMASTER MST ON MST.PARTNO = CD.PARTNO
        LEFT JOIN INVGROUP G ON G.GRP = MST.GRP
        LEFT JOIN INVGROUPACC AC ON AC.GRP = MST.GRP AND AC.ICOST = :ICOST
        WHERE CD.ICOST = :ICOST
        AND CD.OPENDATE BETWEEN :SDATE AND :EDATE
        GROUP BY G.GRP, G.NAME, G.GRPTYPE, AC.GL_ACCOUNT
    INTO IGROUP, IGROUPNAME, XTYPE, XACCOUNT, AMT
    DO
    BEGIN
      DATATYPE = 'Production';
      AMOUNT_COGS = 0;
      AMOUNT_MISSED = 0;
      AMOUNT_TRANSFER = 0;
      IF (XTYPE IN ('F','B')) THEN
      BEGIN
         IF (XACCOUNT = COGS_ACCOUNT) THEN
         BEGIN
            IF (XTYPE <> ITEMTYPE) THEN
            BEGIN
               AMOUNT_TRANSFER = AMT;
               IF (ITEMTYPE='F') THEN DATATYPE = 'Beverage for Cooking';
               ELSE DATATYPE = 'Food for Mixing';
            END
            AMOUNT_COGS = AMT;
         END
         ELSE
            AMOUNT_MISSED = AMT;
      END
      ELSE
      BEGIN
         IF (XACCOUNT = COGS_ACCOUNT) THEN
            AMOUNT_MISSED = AMT;
      END
      IF (AMOUNT_COGS+AMOUNT_MISSED <> 0) THEN
      BEGIN
         SELECT NAME FROM GLCOA WHERE ACCOUNT = :XACCOUNT
         INTO XACCOUNT_NAME;
         SUSPEND;
      END
    END
  END
  /* ---------------------------------------------------------------- */
  /* WONG SETUP                                                       */
  /* ---------------------------------------------------------------- */
  DATASECTION = 'Missed Posting';
  DATATYPE = 'Non Production';
  FOR SELECT ICOST, NAME FROM INVCOST
      WHERE FLAG_PRODUCTION = 0
      OR COSTTYPE <> :ITEMTYPE
  INTO ICOST, ICOSTNAME
  DO
  BEGIN
    FOR SELECT G.GRP, G.NAME, G.GRPTYPE, AC.GL_ACCOUNT, SUM(CD.AMTTOTAL)
        FROM INVCONSUME_DAILY CD
        LEFT JOIN INVMASTER MST ON MST.PARTNO = CD.PARTNO
        LEFT JOIN INVGROUP G ON G.GRP = MST.GRP
        LEFT JOIN INVGROUPACC AC ON AC.GRP = MST.GRP AND AC.ICOST = :ICOST
        WHERE CD.ICOST = :ICOST
        AND CD.OPENDATE BETWEEN :SDATE AND :EDATE
        GROUP BY G.GRP, G.NAME, G.GRPTYPE, AC.GL_ACCOUNT
    INTO IGROUP, IGROUPNAME, XTYPE, XACCOUNT, AMT
    DO
    BEGIN
      AMOUNT_COGS = 0;
      AMOUNT_MISSED = 0;
      IF (XACCOUNT = COGS_ACCOUNT) THEN
      BEGIN
         SELECT NAME FROM GLCOA WHERE ACCOUNT = :XACCOUNT
         INTO XACCOUNT_NAME;
         AMOUNT_MISSED = -AMT;
         SUSPEND;
      END
    END
  END
END^


