ALTER PROCEDURE INV_RPT_RECV_TRACE(
    SDATE DATE,
    EDATE DATE,
    SSUPPLIER VARCHAR(6),
    ESUPPLIER VARCHAR(6))
RETURNS (
    SUPPLIER VARCHAR(6),
    SUPPLIER_NAME VARCHAR(40),
    NUMBER INTEGER,
    OPENDATE DATE,
    STORE VARCHAR(4),
    ICOST VARCHAR(4),
    PARTNO VARCHAR(10),
    PARTNO_NAME VARCHAR(40),
    UNIT VARCHAR(6),
    UNITF VARCHAR(6),
    QTYF DOUBLE PRECISION,
    QTY DOUBLE PRECISION,
    KONVERSI DOUBLE PRECISION,
    CALC_COST DOUBLE PRECISION,
    STATUS CHAR(1),
    PO_NUMBER INTEGER,
    PO_LINE INTEGER,
    PO_DATE DATE,
    PO_QTY DOUBLE PRECISION,
    PO_QTYF DOUBLE PRECISION,
    PO_KONVERSI DOUBLE PRECISION,
    PO_COST DOUBLE PRECISION,
    SOURCE VARCHAR(4),
    PR_NUMBER INTEGER,
    ML_NUMBER INTEGER,
    PR_DATE DATE,
    PR_QTYF DOUBLE PRECISION,
    PR_QTY DOUBLE PRECISION,
    PR_KONVERSI DOUBLE PRECISION,
    PR_COST DOUBLE PRECISION)
AS
BEGIN
  FOR
    SELECT
    R0.SUPPLIER,
    S.NAME,
    R1.NUMBER,R0.OPENDATE,
    R0.STORE,
    R0.ICOST,
    R1.PARTNO,
    MST.NAME,
    MST.UNIT,
    MST.UNITF,
    R1.QTYF,R1.QTY,R1.KONVERSI,
    R1.CALC_COST,
    R1.PONUMBER,
    R1.POLINE,
    R0.STATUS
    FROM INVRECV1 R1
    LEFT JOIN INVRECV0 R0 ON R0.NUMBER = R1.NUMBER
    LEFT JOIN INVMASTER MST ON MST.PARTNO = R1.PARTNO
    LEFT JOIN SYSSUPPLIER S ON S.SUPPLIER = R0.SUPPLIER
    WHERE R0.OPENDATE BETWEEN :SDATE AND :EDATE
    AND R0.SUPPLIER BETWEEN :SSUPPLIER AND :ESUPPLIER
    INTO
      :SUPPLIER,
      :SUPPLIER_NAME,
      :NUMBER,
      :OPENDATE,
      :STORE,
      :ICOST,
      :PARTNO,
      :PARTNO_NAME,
      :UNIT,
      :UNITF,
      :QTYF,
      :QTY,
      :KONVERSI,
      :CALC_COST,
      :PO_NUMBER,
      :PO_LINE,
      :STATUS
  DO
  BEGIN
    /* -------------------------------------------------------------------- */
    PO_DATE = NULL;
    PO_QTY = 0;
    PO_QTYF = 0;
    PO_KONVERSI = 0;
    PO_COST = 0;
    PR_NUMBER = 0;
    ML_NUMBER = 0;
    PR_DATE = NULL;
    PR_QTYF = 0;
    PR_QTY = 0;
    PR_KONVERSI = 0;
    PR_COST = 0;
    SOURCE = '';
    /* -------------------------------------------------------------------- */
    IF (PO_NUMBER <> 0) THEN
    BEGIN
        SELECT OPENDATE FROM INVPO0 WHERE NUMBER = :PO_NUMBER
        INTO PO_DATE;

        SELECT QTY,QTYF,KONVERSI,CALC_COST,REQNO,ML_NUMBER
        FROM INVPO1
        WHERE NUMBER = :PO_NUMBER
        AND LINE = :PO_LINE
        INTO PO_QTY,PO_QTYF,PO_KONVERSI,PO_COST,PR_NUMBER,ML_NUMBER;
    END
    /* -------------------------------------------------------------------- */
    /* PR                                                                   */
    /* -------------------------------------------------------------------- */
    IF (PR_NUMBER <> 0) THEN
    BEGIN
        SOURCE = 'PR';
        SELECT OPENDATE FROM INVPR0 WHERE NUMBER = :PR_NUMBER
        INTO PR_DATE;

        SELECT QTY,QTYF,KONVERSI,CALC_UNITCOST_AFTERTAX
        FROM INVPR1
        WHERE NUMBER = :PR_NUMBER
        AND PARTNO = :PARTNO
        INTO PR_QTY,PR_QTYF,PR_KONVERSI,PR_COST;
    END
    /* -------------------------------------------------------------------- */
    /* ML                                                                   */
    /* -------------------------------------------------------------------- */
    IF (ML_NUMBER <> 0) THEN
    BEGIN
        SOURCE = 'ML';
        SELECT OPENDATE FROM INVMLORDER0 WHERE NUMBER = :ML_NUMBER
        INTO PR_DATE;

        SELECT QTY,QTYF,KONVERSI,COST
        FROM INVMLORDER1
        WHERE NUMBER = :ML_NUMBER
        AND PARTNO = :PARTNO
        INTO PR_QTY,PR_QTYF,PR_KONVERSI,PR_COST;
    END
    SUSPEND;
  END
END^


ALTER PROCEDURE INV_RPT_RECV_TRACE1(
    SDATE DATE,
    EDATE DATE,
    SSUPPLIER VARCHAR(6),
    ESUPPLIER VARCHAR(6))
RETURNS (
