    PR_COST DOUBLE PRECISION)
AS
BEGIN
  FOR
    SELECT
    R0.SUPPLIER,
    S.NAME,
    R1.NUMBER,I.OPENDATE,
    R0.STORE,
    R0.ICOST,
    R1.PARTNO,
    MST.NAME,
    MST.UNIT,
    MST.UNITF,
    R1.QTYF,R1.QTY,R1.KONVERSI,
    R1.CALC_COST,
    R1.PONUMBER,
