ALTER PROCEDURE SP_BEGINOFMONTH(
    ADATE DATE)
RETURNS (
    RESULT DATE)
AS
DECLARE VARIABLE WorkYear   INTEGER;
DECLARE VARIABLE WorkMonth  INTEGER;
BEGIN
  EXECUTE PROCEDURE SP_Year(ADate)  RETURNING_VALUES(WorkYear);
  EXECUTE PROCEDURE SP_Month(ADate) RETURNING_VALUES(WorkMonth);
  EXECUTE PROCEDURE sp_encodedate(WorkYear, WorkMonth, 1)  RETURNING_VALUES(Result);
END^


ALTER PROCEDURE SP_BEGINOFYEAR(
    ADATE DATE)
RETURNS (
    RESULT DATE)
AS
DECLARE VARIABLE WorkYear   INTEGER;
