BEGIN
  EXECUTE PROCEDURE SP_Year(ADate)  RETURNING_VALUES(WorkYear);
  EXECUTE PROCEDURE sp_encodedate(WorkYear, 1, 1)  RETURNING_VALUES(Result);
END^


ALTER PROCEDURE SP_DATEONLY(
    ADATE DATE)
RETURNS (
    RDATE DATE)
AS
