BEGIN
  EXECUTE PROCEDURE SP_DecodeDate(ADate) RETURNING_VALUES(AYear, AMonth, ADay);
  EXECUTE PROCEDURE SP_EncodeDate(AYear, AMonth, ADay) RETURNING_VALUES(RDATE);
END^


ALTER PROCEDURE SP_DATE_BOM(
    ADATE DATE)
RETURNS (
    RESULT DATE)
AS
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
     RESULT = '1.' || EXTRACT(MONTH FROM ADATE)|| '.' || EXTRACT(YEAR FROM ADATE);
  END
  ELSE
  BEGIN
    SELECT SDATE FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE INTO RESULT;
  END
END^


ALTER PROCEDURE SP_DATE_BOM_MONTHYEAR(
    AMONTH INTEGER,
    AYEAR INTEGER)
RETURNS (
    RESULT DATE)
AS
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE PYEAR=:AYEAR AND PMONTH=:AMONTH)) THEN
  BEGIN
     RESULT = '1.'|| AMONTH || '.' || AYEAR;
  END
  ELSE
  BEGIN
    SELECT SDATE FROM SYS_PERIOD WHERE PYEAR=:AYEAR AND PMONTH=:AMONTH INTO RESULT;
  END

END^


ALTER PROCEDURE SP_DATE_BOY(
    ADATE DATE)
RETURNS (
    RESULT DATE)
AS
DECLARE VARIABLE AYEAR INTEGER;
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
     RESULT = '1.1.' || EXTRACT(YEAR FROM ADATE);
  END
  ELSE
  BEGIN
    SELECT PYEAR FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE
    INTO AYEAR;
    SELECT SDATE FROM SYS_PERIOD WHERE PYEAR=:AYEAR AND PMONTH=1 INTO RESULT;
  END
END^


ALTER PROCEDURE SP_DATE_DAYOFMONTH(
    ADATE DATE)
RETURNS (
    RESULT INTEGER)
AS
DECLARE VARIABLE BOM DATE;
DECLARE VARIABLE EOM DATE;
BEGIN
  EXECUTE PROCEDURE SP_DATE_BOM(ADATE) RETURNING_VALUES(BOM);
  EXECUTE PROCEDURE SP_DATE_EOM(ADATE) RETURNING_VALUES(EOM);
  RESULT = EOM-BOM+1;
END^


ALTER PROCEDURE SP_DATE_DECODE(
    ADATE DATE)
RETURNS (
    Y INTEGER,
    M INTEGER,
    D INTEGER)
AS
DECLARE VARIABLE SDATE DATE;
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
     Y = EXTRACT(YEAR FROM ADATE);
     M = EXTRACT(MONTH FROM ADATE);
     D = EXTRACT(DAY FROM ADATE);
  END
  ELSE
  BEGIN
    SELECT PYEAR, PMONTH, SDATE
    FROM SYS_PERIOD
    WHERE :ADATE BETWEEN SDATE AND EDATE
    INTO Y, M, SDATE;
    D = ADATE - SDATE +1; /* HARI KE BERAPA DALAM PERIOD TSB */
  END
END^


ALTER PROCEDURE SP_DATE_EOM(
    ADATE DATE)
RETURNS (
    RESULT DATE)
AS
DECLARE VARIABLE WorkYear   INTEGER;
DECLARE VARIABLE WorkMonth  INTEGER;
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
    WorkYear = EXTRACT(YEAR FROM ADATE);
    WorkMonth = EXTRACT(MONTH FROM ADATE);

    WorkMonth = WorkMonth+1;
    if (WorkMonth > 12) then
    begin
    WorkMonth = 1;
    WorkYear  = WorkYear + 1;
    end
    EXECUTE PROCEDURE sp_encodedate(WorkYear, WorkMonth, 1)  RETURNING_VALUES(Result);
    Result = Result - 1;
  END
  ELSE
  BEGIN
    SELECT EDATE FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE INTO RESULT;
  END
END^


ALTER PROCEDURE SP_DATE_EXTRACT_MONTHYEAR(
    ADATE DATE)
RETURNS (
    M INTEGER,
    Y INTEGER)
AS
DECLARE VARIABLE D INTEGER;
BEGIN
   EXECUTE PROCEDURE SP_DATE_DECODE(ADATE) RETURNING_VALUES(Y, M, D);
END^


ALTER PROCEDURE SP_DATE_IS_BOM(
    ADATE DATE)
RETURNS (
    ARESULT INTEGER)
AS
DECLARE VARIABLE SDATE DATE;
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
      EXECUTE PROCEDURE SP_BEGINOFMONTH(ADATE) RETURNING_VALUES(SDATE);
      IF (SDATE <> ADATE) THEN ARESULT = 0;
      ELSE ARESULT = 1;
  END
  ELSE
  BEGIN
      SELECT SDATE FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE INTO SDATE;
      IF (SDATE <> ADATE) THEN ARESULT = 0;
      ELSE ARESULT = 1;
  END
END^


ALTER PROCEDURE SP_DATE_IS_BOY(
    ADATE DATE)
RETURNS (
    ARESULT INTEGER)
AS
DECLARE VARIABLE SDATE DATE;
BEGIN
  IF (NOT EXISTS(SELECT * FROM SYS_PERIOD WHERE :ADATE BETWEEN SDATE AND EDATE)) THEN
  BEGIN
      EXECUTE PROCEDURE SP_BEGINOFYEAR(ADATE) RETURNING_VALUES(SDATE);
      IF (SDATE <> ADATE) THEN ARESULT = 0;
      ELSE ARESULT = 1;
  END
  ELSE
  BEGIN
      EXECUTE PROCEDURE SP_DATE_BOY(ADATE) RETURNING_VALUES(SDATE);
      IF (SDATE <> ADATE) THEN ARESULT = 0;
      ELSE ARESULT = 1;
  END
END^


ALTER PROCEDURE SP_DATE_LASTMONTH(
    ADATE DATE)
RETURNS (
    RESULT DATE)
AS
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE DCOUNT INTEGER;
DECLARE VARIABLE BOM DATE;
BEGIN
  EXECUTE PROCEDURE SP_DECODEDATE(ADATE) RETURNING_VALUES(Y, M, D);
  M = M - 1;
  IF (M < 1) THEN
  BEGIN
     M = 12;
     Y = Y - 1;
  END
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(M, Y) RETURNING_VALUES(BOM);
  EXECUTE PROCEDURE SP_DATE_DAYOFMONTH(BOM) RETURNING_VALUES(DCOUNT);
  RESULT = BOM + D - 1; /* TGL BULAN LALU AWAL BULAN + TGL HARI INI KURANG 1 HARI */
  D = RESULT - BOM + 1;
  IF (D > DCOUNT) THEN /* KALAU HARI LEBIH BESAR DARI AKHIR BULAN, MAKA DIANGGAP AKHIR BULAN */
     EXECUTE PROCEDURE SP_DATE_EOM(BOM) RETURNING_VALUES(RESULT);
END^


ALTER PROCEDURE SP_DATE_LASTYEAR(
    ADATE DATE)
RETURNS (
    RESULT DATE)
AS
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE D INTEGER;
DECLARE VARIABLE DCOUNT INTEGER;
DECLARE VARIABLE BOM DATE;
BEGIN
  EXECUTE PROCEDURE SP_DECODEDATE(ADATE) RETURNING_VALUES(Y, M, D);
  Y = Y - 1;
  EXECUTE PROCEDURE SP_DATE_BOM_MONTHYEAR(M, Y) RETURNING_VALUES(BOM);
  EXECUTE PROCEDURE SP_DATE_DAYOFMONTH(BOM) RETURNING_VALUES(DCOUNT);
  
  if ((M = 2) AND (D > DCOUNT)) then D = DCOUNT;

  EXECUTE PROCEDURE SP_ENCODEDATE(Y, M, D) RETURNING_VALUES(RESULT);
END^


