ALTER PROCEDURE SP_DAY(
    ADATE DATE)
RETURNS (
    RESULT INTEGER)
AS
BEGIN
  Result = CAST(CAST(ADate AS VARCHAR(2)) AS INTEGER);
  WHEN ANY DO Result = CAST(CAST(ADate AS VARCHAR(1)) AS INTEGER);
END^


ALTER PROCEDURE SP_DAYOFWEEK(
    ADATE DATE)
RETURNS (
    RESULT INTEGER)
AS
DECLARE VARIABLE Elapsed INTEGER;
BEGIN
  /* This procedure returns the number of the day of the week:
     0 - Monday; 1 - Tuesday; 2 - Wdnesday; 3 - Thursday; 4 - Friday; 5 - Saturday; 6 - Sunday
  */
  EXECUTE PROCEDURE sp_ElapsedDays("1.1.96", ADate) RETURNING_VALUES Elapsed;
  EXECUTE PROCEDURE sp_Modulus(Elapsed, 7) RETURNING_VALUES Result;
END^


ALTER PROCEDURE SP_DAYOFYEAR(
    ADATE DATE)
RETURNS (
    RESULT INTEGER)
AS
DECLARE VARIABLE WorkYear   INTEGER;
DECLARE VARIABLE WorkMonth  INTEGER;
DECLARE VARIABLE I          INTEGER;
BEGIN
  Result = 0;
  EXECUTE PROCEDURE SP_Year(ADate) RETURNING_VALUES(WorkYear);
  EXECUTE PROCEDURE SP_Month(ADate) RETURNING_VALUES(WorkMonth);
  WorkMonth = WorkMonth-1;  
  WHILE (WorkMonth > 0) DO
  BEGIN
    EXECUTE PROCEDURE SP_DaysOfMonth(WorkYear, WorkMonth) RETURNING_VALUES(I);
    Result = Result+I; 
    WorkMonth = WorkMonth-1; 
  END
  EXECUTE PROCEDURE SP_Day(ADate) RETURNING_VALUES(I);
  Result = Result +I;
END^


ALTER PROCEDURE SP_DAYSOFMONTH(
    AYEAR INTEGER,
    AMONTH INTEGER)
RETURNS (
    RESULT INTEGER)
AS
DECLARE VARIABLE WorkDate   DATE;
BEGIN
  Result = 31;
  WHILE (Result > 28 AND WorkDate IS NULL) DO
  BEGIN
    EXECUTE PROCEDURE SP_EncodeDate(AYear, AMonth, Result) RETURNING_VALUES(WorkDate);
    WHEN ANY DO Result = Result -1;
  END
END^


