ALTER PROCEDURE SP_MODULUS(
    DIVIDEND INTEGER,
    DIVISOR INTEGER)
RETURNS (
    RESULT INTEGER)
AS
BEGIN
  /* This procedure calculates the modulus of two number */
  IF(Dividend = 0) THEN Result = 0;
  ELSE
    Result = Dividend-(CAST((Dividend / Divisor)-0.5 AS INTEGER)*Divisor);
END^


ALTER PROCEDURE SP_MONTH(
    ADATE DATE)
RETURNS (
    RESULT INTEGER)
AS
DECLARE VARIABLE WorkDate DATE;
DECLARE VARIABLE WorkDay  INTEGER;
BEGIN
  WorkDate = ADate;
  Result = 1;
  WHILE(CAST(WorkDate AS VARCHAR(5)) <> '1-JAN') DO
  BEGIN
    EXECUTE PROCEDURE SP_Day(WorkDate) RETURNING_VALUES WorkDay;
    IF(WorkDay = 1) THEN Result = Result+1;
    WorkDate = WorkDate-1;
  END
END^


ALTER PROCEDURE SP_NUMBER_TO_TEXT(
    ALANGUAGE CHAR(1),
    AVALUE DOUBLE PRECISION)
RETURNS (
    TEXT VARCHAR(512))
AS
DECLARE VARIABLE FRAC DOUBLE PRECISION;
DECLARE VARIABLE IVALUE NUMERIC(14,0);
DECLARE VARIABLE THOUSAND DOUBLE PRECISION;
DECLARE VARIABLE MILLION DOUBLE PRECISION;
DECLARE VARIABLE BILLION DOUBLE PRECISION;
DECLARE VARIABLE TRILLION DOUBLE PRECISION;
DECLARE VARIABLE TDIGIT VARCHAR(80);
DECLARE VARIABLE X INTEGER;
BEGIN
  IF ((ALANGUAGE IS NULL) OR (ALANGUAGE NOT IN ('E','I'))) THEN
     ALANGUAGE = 'E';

  IF (AVALUE IS NULL) THEN
  BEGIN
     AVALUE = 0;
  END
  IF (AVALUE < 0) THEN AVALUE = -AVALUE;
  TEXT = '';
  /* ---------------------------------------------------------------- */
  /* hitung dibelakang koma                                           */
  /* ---------------------------------------------------------------- */
  IVALUE = AVALUE-0.5;
  FRAC = AVALUE - IVALUE;
  /* ---------------------------------------------------------------- */
  /* KALAU DI BELAKANG KOMA > 0.99, MAKA DIANGGAP 1                   */
  /* ---------------------------------------------------------------- */
  IF (FRAC > 0.99) THEN
  BEGIN
     AVALUE = IVALUE + 1;
     FRAC = 0;
  END

  IF (AVALUE = 0) THEN
  BEGIN
     IF (ALANGUAGE = 'E') THEN TEXT = 'zero';
     ELSE TEXT = 'Nol';
     SUSPEND;
     EXIT;
  END
  TEXT = ALANGUAGE;

  TEXT = '';
  Thousand = 1000;
  Million  = 1000000;
  Billion  = 1000000000;
  Trillion = 1000000000000;
  /* ---------------------------------------------------------------- */
  /* TRILLION                                                         */
  /* ---------------------------------------------------------------- */
  IF (AVALUE >= Trillion) THEN
  BEGIN
     IVALUE = (AVALUE / Trillion - 0.5);
     EXECUTE PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(ALANGUAGE, IVALUE)
     RETURNING_VALUES(TDIGIT);

     TEXT = TEXT || TDIGIT;
     IF (ALANGUAGE = 'E') THEN TEXT = TEXT || ' trillion';
     ELSE TEXT = TEXT || ' triliun';
     AVALUE = AVALUE - IVALUE * Trillion;
     IF (AVALUE > 0) THEN TEXT = TEXT || ' ';
  END
  /* ---------------------------------------------------------------- */
  /* BILLION                                                          */
  /* ---------------------------------------------------------------- */
  IF (AVALUE >= Billion) THEN
  BEGIN
     IVALUE = (AVALUE / Billion - 0.5);
     EXECUTE PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(ALANGUAGE, IVALUE)
     RETURNING_VALUES(TDIGIT);

     TEXT = TEXT || TDIGIT;
     IF (ALANGUAGE = 'E') THEN TEXT = TEXT || ' billion';
     ELSE TEXT = TEXT || ' milyar';

     AVALUE = AVALUE - IVALUE * Billion;
     IF (AVALUE > 0) THEN TEXT = TEXT || ' ';
  END

  /* ---------------------------------------------------------------- */
  /* MILLION                                                          */
  /* ---------------------------------------------------------------- */
  IF (AVALUE >= Million) THEN
  BEGIN
     IVALUE = (AVALUE / Million - 0.5);
     EXECUTE PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(ALANGUAGE, IVALUE)
     RETURNING_VALUES(TDIGIT);

     TEXT = TEXT || TDIGIT;
     IF (ALANGUAGE = 'E') THEN TEXT = TEXT || ' million';
     ELSE TEXT = TEXT || ' juta';

     AVALUE = AVALUE - IVALUE * Million;
     IF (AVALUE > 0) THEN TEXT = TEXT || ' ';
  END

  /* ---------------------------------------------------------------- */
  /* THOUSAND                                                         */
  /* ---------------------------------------------------------------- */
  IF (AVALUE >= Thousand) THEN
  BEGIN
     IVALUE = (AVALUE / Thousand - 0.5);
     IF (IVALUE = 1) THEN
     BEGIN
        IF (ALANGUAGE = 'E') THEN TEXT = TEXT || 'one thousand';
        ELSE TEXT = TEXT || 'seribu';
     END
     ELSE
     BEGIN
        EXECUTE PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(ALANGUAGE, IVALUE)
           RETURNING_VALUES(TDIGIT);

        TEXT = TEXT || TDIGIT;
        IF (ALANGUAGE = 'E') THEN TEXT = TEXT || ' thousand';
        ELSE TEXT = TEXT || ' ribu';
     END
     AVALUE = AVALUE - IVALUE * Thousand;
     IF (AVALUE > 0) THEN TEXT = TEXT || ' ';
  END

  /* ---------------------------------------------------------------- */
  /* LESS THEN ONE THOUSAND                                           */
  /* ---------------------------------------------------------------- */
  IF (AVALUE >=1) THEN
  BEGIN
     IVALUE = (AVALUE - 0.5);
     EXECUTE PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(ALANGUAGE, IVALUE)
     RETURNING_VALUES(TDIGIT);
     TEXT = TEXT || TDIGIT;
  END
  /* ---------------------------------------------------------------- */
  /* DECIMAL                                                          */
  /* ---------------------------------------------------------------- */
  FRAC = (FRAC+0.005) * 100;
  IVALUE = FRAC-0.5;
  IF (IVALUE > 0) THEN
  BEGIN
     /*
     IF (ALANGUAGE = 'E') THEN TEXT = TEXT || ' and ' || IVALUE || '/100';
     ELSE TEXT = TEXT || ' dan ' || IVALUE || '/100';
     */
     EXECUTE PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(ALANGUAGE, IVALUE)
     RETURNING_VALUES(TDIGIT);

     IF (ALANGUAGE = 'E') THEN TEXT = TEXT || ' and ' || TDIGIT || ' cents';
     ELSE TEXT = TEXT || ' dan ' || TDIGIT || ' sen';
  END
  SUSPEND;
END^


ALTER PROCEDURE SP_NUMBER_TO_TEXT_DIGIT(
    ALANGUAGE CHAR(1),
    I INTEGER)
RETURNS (
    TEXT VARCHAR(80))
AS
DECLARE VARIABLE Hundred VARCHAR(14);
DECLARE VARIABLE One     VARCHAR(14);
DECLARE VARIABLE Two     VARCHAR(14);
DECLARE VARIABLE Three   VARCHAR(14);
DECLARE VARIABLE Four    VARCHAR(14);
DECLARE VARIABLE Five    VARCHAR(14);
DECLARE VARIABLE Six     VARCHAR(14);
DECLARE VARIABLE Seven   VARCHAR(14);
DECLARE VARIABLE Eight   VARCHAR(14);
DECLARE VARIABLE Nine    VARCHAR(14);
DECLARE VARIABLE T10     VARCHAR(14);
DECLARE VARIABLE T11     VARCHAR(14);
DECLARE VARIABLE T12     VARCHAR(14);
DECLARE VARIABLE T13     VARCHAR(14);
DECLARE VARIABLE T14     VARCHAR(14);
DECLARE VARIABLE T15     VARCHAR(14);
DECLARE VARIABLE T16     VARCHAR(14);
DECLARE VARIABLE T17     VARCHAR(14);
DECLARE VARIABLE T18     VARCHAR(14);
DECLARE VARIABLE T19     VARCHAR(14);
DECLARE VARIABLE T20     VARCHAR(14);
DECLARE VARIABLE T30     VARCHAR(14);
DECLARE VARIABLE T40     VARCHAR(14);
DECLARE VARIABLE T50     VARCHAR(14);
DECLARE VARIABLE T60     VARCHAR(14);
DECLARE VARIABLE T70     VARCHAR(14);
DECLARE VARIABLE T80     VARCHAR(14);
DECLARE VARIABLE T90     VARCHAR(14);

DECLARE VARIABLE FLAG INTEGER;
DECLARE VARIABLE IVALUE INTEGER;
BEGIN
  IF (ALANGUAGE <> 'E') THEN
  BEGIN
     Hundred = ' ratus';
     One     = 'satu';
     Two     = 'dua';
     Three   = 'tiga';
     Four    = 'empat';
     Five    = 'lima';
     Six     = 'enam';
     Seven   = 'tujuh';
     Eight   = 'delapan';
     Nine    = 'sembilan';
     T10     = 'sepuluh';
     T11     = 'sebelas';
     T12     = 'dua belas';
     T13     = 'tiga belas';
     T14     = 'empat belas';
     T15     = 'lima belas';
     T16     = 'enam belas';
     T17     = 'tujuh belas';
     T18     = 'delapan belas';
     T19     = 'sebilan belas';
     T20     = 'dua puluh';
     T30     = 'tiga puluh';
     T40     = 'empat puluh';
     T50     = 'lima puluh';
     T60     = 'enam puluh';
     T70     = 'tujuh puluh';
     T80     = 'delapan puluh';
     T90     = 'sembilan puluh';
  END
  ELSE
  BEGIN
     Hundred = ' hundred';
     One     = 'one';
     Two     = 'two';
     Three   = 'three';
     Four    = 'four';
     Five    = 'five';
     Six     = 'six';
     Seven   = 'seven';
     Eight   = 'eight';
     Nine    = 'nine';
     T10     = 'ten';
     T11     = 'eleven';
     T12     = 'twelve';
     T13     = 'thirteen';
     T14     = 'fourteen';
     T15     = 'fifteen';
     T16     = 'sixteen';
     T17     = 'seventeen';
     T18     = 'eighteen';
     T19     = 'nineteen';
     T20     = 'twenty';
     T30     = 'thirty';
     T40     = 'forty';
     T50     = 'fifty';
     T60     = 'sixty';
     T70     = 'seventy';
     T80     = 'eighty';
     T90     = 'ninety';
  END
  FLAG = 0;
  IVALUE = (I / 100 - 0.5);

  IF (IVALUE <> 0) THEN FLAG = 1;
  IF (IVALUE = 0) THEN TEXT = '';
  ELSE IF (IVALUE = 1) THEN
  BEGIN
     IF (ALANGUAGE = 'E') THEN TEXT = One || Hundred;
     ELSE TEXT = 'seratus';
  END
  ELSE IF (IVALUE = 2) THEN TEXT = Two   || Hundred;
  ELSE IF (IVALUE = 3) THEN TEXT = Three || Hundred;
  ELSE IF (IVALUE = 4) THEN TEXT = Four  || Hundred;
  ELSE IF (IVALUE = 5) THEN TEXT = Five  || Hundred;
  ELSE IF (IVALUE = 6) THEN TEXT = Six   || Hundred;
  ELSE IF (IVALUE = 7) THEN TEXT = Seven || Hundred;
  ELSE IF (IVALUE = 8) THEN TEXT = Eight || Hundred;
  ELSE IF (IVALUE = 9) THEN TEXT = Nine  || Hundred;

  IF (FLAG = 1) THEN
     I = I - IVALUE * 100;

  IF (I > 0) THEN TEXT = TEXT || ' ';
  ELSE
  BEGIN
     SUSPEND;
     EXIT;
  END

  /* ---------------------------------------------------------------- */
  /* PULUHAN                                                          */
  /* ---------------------------------------------------------------- */
  FLAG = 1;
  IVALUE = (I / 10 - 0.5);
  IF ((IVALUE = 0) OR (IVALUE = 1)) THEN
  BEGIN
     FLAG = 0;
  END
  ELSE IF (IVALUE = 2) THEN TEXT = TEXT || T20;
  ELSE IF (IVALUE = 3) THEN TEXT = TEXT || T30;
  ELSE IF (IVALUE = 4) THEN TEXT = TEXT || T40;
  ELSE IF (IVALUE = 5) THEN TEXT = TEXT || T50;
  ELSE IF (IVALUE = 6) THEN TEXT = TEXT || T60;
  ELSE IF (IVALUE = 7) THEN TEXT = TEXT || T70;
  ELSE IF (IVALUE = 8) THEN TEXT = TEXT || T80;
  ELSE IF (IVALUE = 9) THEN TEXT = TEXT || T90;

  IF (FLAG = 1) THEN
     I = I - IVALUE * 10;

  IF (I > 0) THEN TEXT = TEXT || ' ';
  ELSE
  BEGIN
     SUSPEND;
     EXIT;
  END

  IF (I = 1) THEN TEXT = TEXT || ONE;
  ELSE IF (I = 2) THEN TEXT = TEXT || Two;
  ELSE IF (I = 3) THEN TEXT = TEXT || Three;
  ELSE IF (I = 4) THEN TEXT = TEXT || Four;
  ELSE IF (I = 5) THEN TEXT = TEXT || Five;
  ELSE IF (I = 6) THEN TEXT = TEXT || Six;
  ELSE IF (I = 7) THEN TEXT = TEXT || Seven;
  ELSE IF (I = 8) THEN TEXT = TEXT || Eight;
  ELSE IF (I = 9) THEN TEXT = TEXT || Nine;
  ELSE IF (I =10) THEN TEXT = TEXT || T10;
  ELSE IF (I =11) THEN TEXT = TEXT || T11;
  ELSE IF (I =12) THEN TEXT = TEXT || T12;
  ELSE IF (I =13) THEN TEXT = TEXT || T13;
  ELSE IF (I =14) THEN TEXT = TEXT || T14;
  ELSE IF (I =15) THEN TEXT = TEXT || T15;
  ELSE IF (I =16) THEN TEXT = TEXT || T16;
  ELSE IF (I =17) THEN TEXT = TEXT || T17;
  ELSE IF (I =18) THEN TEXT = TEXT || T18;
  ELSE IF (I =19) THEN TEXT = TEXT || T19;
  SUSPEND;
END^


ALTER PROCEDURE SP_YEAR(
    ADATE DATE)
RETURNS (
    RESULT INTEGER)
AS
DECLARE VARIABLE ElapsedDays  INTEGER;
DECLARE VARIABLE ElapsedYears INTEGER;
BEGIN
  /* Lets go to the begin of the year */
  WHILE(CAST(ADate AS VARCHAR(5)) <> '1-JAN') DO
    ADate = ADate -1;
  ElapsedDays = ADate -'1.1.1901';
  Result = (ElapsedDays *400 /146097)+1901;
END^


ALTER PROCEDURE SYSPARAM_LOG_SAVE(
    APPLICATION VARCHAR(4),
    LOG_ACTION VARCHAR(8),
    USER_ID VARCHAR(10),
    TEXT VARCHAR(80))
AS
BEGIN
  INSERT INTO SYSPARAM_LOG (
    APPLICATION,
    LOG_ACTION,
    USER_ID,
    TEXT)
  VALUES (
    :APPLICATION,
    :LOG_ACTION,
    :USER_ID,
    :TEXT);
  WHEN ANY DO
  BEGIN
    APPLICATION = APPLICATION;
  END
END^


ALTER PROCEDURE TN_AGING(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8),
    DETAILFLAG INTEGER,
    SOURCE VARCHAR(4))
RETURNS (
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    CURR NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4),
    TOTAL NUMERIC(15,4),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    DOCUMENT VARCHAR(20),
    SOURCEID INTEGER,
    SOURCE_REMARK VARCHAR(80),
    AGE INTEGER,
    CREDITCARD INTEGER,
    CUSTTYPE VARCHAR(4),
    TYPENAME VARCHAR(40))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable voucher double precision;
declare variable cash    double precision;
declare variable adjust  double precision;
declare variable depos   double precision;
declare variable FOAdjust double precision;

declare variable F_voucher double precision;
declare variable F_cash    double precision;
declare variable F_adjust  double precision;
declare variable F_depos   double precision;
declare variable F_FOAdjust double precision;
declare variable vPayDate Date;
declare variable ARDate DATE;
declare variable XDEPOSIT DOUBLE PRECISION;
declare variable CREDITLIMIT DOUBLE PRECISION;
begin
  if (SCUSTOMER IS NULL) then
  BEGIN
     SCUSTOMER = '';
     ECUSTOMER = 'zzzzzz';
     SOURCE    = 'TN';
  END
  if (DETAILFLAG IS NULL) then
      DETAILFLAG = 0;
      
  
  CREDITCARD = 0;
  
  SELECT ARSYSDATE+1 FROM SYSPARAM INTO ARDATE;
  
  for select CUSTOMER, name, CUSTTYPE, CREDITLIMIT from sysCUSTOMER
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER, name, CUSTTYPE, CREDITLIMIT
  do
  begin
    SELECT NAME FROM SYSCUSTOMERTYPE
    WHERE CUSTOMERTYPE = :CUSTTYPE
    INTO :TYPENAME;
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    end
    SOURCEID = 0;
    SOURCE_REMARK = '';
    opendate = null;
    duedate = null;
    document = null;
    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/
    for select number, totaldue, forex_totaldue,
               opendate, duedate, SOURCEID, SOURCE_REMARK, DOCUMENT
          from ARVCH
         where PAIDSTATUS = 'O'
           AND CUSTOMER = :CUSTOMER
           and ((totaldue <> 0) or (forex_totaldue <> 0))
           and SOURCE = :SOURCE
         PLAN (ARVCH INDEX (ARVCH_IDX_PAIDSTATUS))
         into number, voucher, f_voucher, opendate, duedate, SOURCEID, SOURCE_REMARK, DOCUMENT
    do
    begin
       d = ARDate - opendate;
      /*======================================================================*/
      /* jika aging detail                                                    */
      /*======================================================================*/
       if (detailflag = 1) then
       begin
          curr = 0;
          over30 = 0;
          over60 = 0;
          over90 = 0;
       end
       if (d <= 30)      then curr   = curr + voucher;
       else if (d <= 60) then over30 = over30 + voucher;
       else if (d <= 90) then over60 = over60 + voucher;
       else over90 = over90 + voucher;
       /* ------------------------------------------------------------------- */
       /* detail aging (ada nomor vouchernya                                  */
       /* ------------------------------------------------------------------- */
       if (detailflag = 1) then
       begin
         age = d;
         total = curr + over30 + over60 + over90;
         if (total <> 0) then
            suspend;
       end
    end
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       total = curr + over30 + over60 + over90;
       number = 0;
       document = '';
       if (total <> 0) then
          suspend;
    end
  end
end^


ALTER PROCEDURE TN_AGING_OLD(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8),
    DETAILFLAG INTEGER,
    SOURCE VARCHAR(4))
RETURNS (
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    CURR NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4),
    TOTAL NUMERIC(15,4),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    DOCUMENT VARCHAR(20),
    SOURCEID INTEGER,
    SOURCE_REMARK VARCHAR(80),
    AGE INTEGER,
    CREDITCARD INTEGER,
    CUSTTYPE VARCHAR(4),
    TYPENAME VARCHAR(40))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable voucher double precision;
declare variable cash    double precision;
declare variable adjust  double precision;
declare variable depos   double precision;
declare variable FOAdjust double precision;

declare variable F_voucher double precision;
declare variable F_cash    double precision;
declare variable F_adjust  double precision;
declare variable F_depos   double precision;
declare variable F_FOAdjust double precision;
declare variable vPayDate Date;
declare variable ARDate DATE;
declare variable XDEPOSIT DOUBLE PRECISION;
declare variable CREDITLIMIT DOUBLE PRECISION;
begin
  if (SCUSTOMER IS NULL) then
  BEGIN
     SCUSTOMER = '125';
     ECUSTOMER = '125';
     SOURCE    = 'TN';
  END
  if (DETAILFLAG IS NULL) then
      DETAILFLAG = 1;
      
  
  CREDITCARD = 0;
  
  SELECT ARSYSDATE+1 FROM SYSPARAM INTO ARDATE;
  
  for select CUSTOMER, name, CUSTTYPE, CREDITLIMIT from sysCUSTOMER
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER, name, CUSTTYPE, CREDITLIMIT
  do
  begin
    SELECT NAME FROM SYSCUSTOMERTYPE
    WHERE CUSTOMERTYPE = :CUSTTYPE
    INTO :TYPENAME;
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    end
    SOURCEID = 0;
    SOURCE_REMARK = '';
    opendate = null;
    duedate = null;
    document = null;
    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/
    for select number, totaldue, forex_totaldue,
               opendate, duedate, SOURCEID, SOURCE_REMARK, DOCUMENT
          from ARVCH
         where PAIDSTATUS = 'O'
           AND CUSTOMER = :CUSTOMER
           and ((totaldue <> 0) or (forex_totaldue <> 0))
           and SOURCE = :SOURCE
         PLAN (ARVCH INDEX (ARVCH_IDX_PAIDSTATUS))
         into number, voucher, f_voucher, opendate, duedate, SOURCEID, SOURCE_REMARK, DOCUMENT
    do
    begin
       d = ARDate - opendate;
      /*======================================================================*/
      /* jika aging detail                                                    */
      /*======================================================================*/
       if (detailflag = 1) then
       begin
          curr = 0;
          over30 = 0;
          over60 = 0;
          over90 = 0;
       end
       if (d <= 30)      then curr   = curr + voucher;
       else if (d <= 60) then over30 = over30 + voucher;
       else if (d <= 90) then over60 = over60 + voucher;
       else over90 = over90 + voucher;
       /* ------------------------------------------------------------------- */
       /* detail aging (ada nomor vouchernya                                  */
       /* ------------------------------------------------------------------- */
       if (detailflag = 1) then
       begin
         age = d;
         total = curr + over30 + over60 + over90;
         if ((source_remark = '') or (source_remark is null)) then source_remark = 'Billing';
         if (total <> 0) then
            suspend;
       end
    end
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       total = curr + over30 + over60 + over90;
       number = 0;
       document = '';
       if (total <> 0) then
          suspend;
    end
    SOURCEID = 0;
    SOURCE_REMARK = '';
    for select number, balance, forex_balance,
               opendate, opendate,  DOCUMENT
          from ARDEPOS0
         where CUSTOMER = :CUSTOMER
           and STATUS_APPLY <> 'C'
         PLAN (ARDEPOS0 INDEX (ARDEPOS0_IDX_CUSTOMER_STATUS))
    into number, voucher, f_voucher, opendate, duedate, DOCUMENT
    DO
    BEGIN
      CURR = -voucher;
      TOTAL = CURR;
      if (source_remark = '') then source_remark = 'Deposit';
      SUSPEND;
    END
    
  end
end^


ALTER PROCEDURE TN_BILL(
    AYEAR INTEGER,
    AMONTH INTEGER,
    AROOM VARCHAR(8))
RETURNS (
    ROOM VARCHAR(8),
    PYEAR INTEGER,
    PMONTH INTEGER,
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    STATUS CHAR(1),
    PRINTED_COUNTER INTEGER,
    METER_ELECTRIC INTEGER,
    METER_WATER INTEGER,
    METER_GAS INTEGER,
    METER_1 INTEGER,
    METER_2 INTEGER,
    METER_3 INTEGER,
    CREATEUSER VARCHAR(8),
    EDITUSER VARCHAR(8),
    PRINTED_USER VARCHAR(8),
    CREATEDATE DATE,
    EDITDATE DATE,
    PRINTED_DATE DATE,
    INVOICE_NO INTEGER,
    TRANS_ID INTEGER,
    CONSUME_ELECTRIC INTEGER,
    CONSUME_WATER INTEGER,
    CONSUME_GAS INTEGER,
    NAME VARCHAR(40),
    ADDRESS1 VARCHAR(40),
    ADDRESS2 VARCHAR(40),
    ADDRESS3 VARCHAR(40),
    ADDRESS4 VARCHAR(40),
    CUSTOMER VARCHAR(8),
    OPENDATE DATE,
    DUEDATE DATE,
    OWNER_NAME VARCHAR(40),
    OWNER_PHONE VARCHAR(40),
    OWNER_FAX VARCHAR(40),
    OWNER_MOBILE VARCHAR(80),
    OWNER_ADDRESS BLOB SUB_TYPE 0 SEGMENT SIZE 80,
    INWORD CHAR(256),
    TERBILANG CHAR(256),
    COPY INTEGER,
    SQUARE_METER DOUBLE PRECISION,
    PARAM_ELECTRIC VARCHAR(8),
    PARAM_WATER VARCHAR(8),
    COPYBILL VARCHAR(20),
    SERVICE_CHARGE DOUBLE PRECISION,
    POWER_START DOUBLE PRECISION,
    POWER_END DOUBLE PRECISION,
    WATER_START DOUBLE PRECISION,
    WATER_END DOUBLE PRECISION)
AS
BEGIN
  FOR
    select J.ROOM ,
    J.PYEAR ,
    J.PMONTH,
    J.DB ,
    J.CR ,
    J.STATUS ,
    J.PRINTED_COUNTER ,
    J.METER_ELECTRIC ,
    J.METER_WATER ,
    J.METER_GAS ,
    J.METER_1 ,
    J.METER_2 ,
    J.METER_3 ,
    J.CREATEUSER ,
    J.EDITUSER ,
    J.PRINTED_USER ,
    J.CREATEDATE ,
    J.EDITDATE ,
    J.PRINTED_DATE ,
    J.TRANS_ID ,
    J.CONSUME_ELECTRIC ,
    J.CONSUME_WATER ,
    J.CONSUME_GAS ,
    J.NAME ,
    J.ADDRESS1 ,
    J.ADDRESS2 ,
    J.ADDRESS3 ,
    J.ADDRESS4 ,
    J.CUSTOMER ,
    J.OPENDATE ,
    J.DUEDATE,
    R.OWNER_NAME,
    R.OWNER_PHONE,
    R.OWNER_FAX,
    R.OWNER_MOBILE,
    R.OWNER_ADDRESS,
    NTOS('E', J.DB) INWORD,
    NTOS('I', CAST(J.DB AS INTEGER)) TERBILANG,
    J.PRINTED_COUNTER+1 COPY,
    R.SQUARE_METER,
    R.PARAM_ELECTRIC,
    R.PARAM_WATER,
    R.SERVICE_CHARGE,
    J.POWER_START, J.POWER_END,
    J.WATER_START, J.WATER_END, J.VOUCHER_NO
    from TN_TENANT_JUR J
    LEFT JOIN TN_ROOM R ON R.ROOM = J.ROOM
    WHERE J.ROOM = :AROOM
    AND J.PYEAR = :AYEAR
    AND J.PMONTH = :AMONTH
    INTO
      :ROOM,
      :PYEAR,
      :PMONTH,
      :DB,
      :CR,
      :STATUS,
      :PRINTED_COUNTER,
      :METER_ELECTRIC,
      :METER_WATER,
      :METER_GAS,
      :METER_1,
      :METER_2,
      :METER_3,
      :CREATEUSER,
      :EDITUSER,
      :PRINTED_USER,
      :CREATEDATE,
      :EDITDATE,
      :PRINTED_DATE,
      :TRANS_ID,
      :CONSUME_ELECTRIC,
      :CONSUME_WATER,
      :CONSUME_GAS,
      :NAME,
      :ADDRESS1,
      :ADDRESS2,
      :ADDRESS3,
      :ADDRESS4,
      :CUSTOMER,
      :OPENDATE,
      :DUEDATE,
      :OWNER_NAME,
      :OWNER_PHONE,
      :OWNER_FAX,
      :OWNER_MOBILE,
      :OWNER_ADDRESS,
      :INWORD,
      :TERBILANG,
      :COPY,
      :SQUARE_METER,
      :PARAM_ELECTRIC,
      :PARAM_WATER,
      :SERVICE_CHARGE,
      :POWER_START, :POWER_END,
      :WATER_START, :WATER_END, INVOICE_NO
  DO
  BEGIN
    if (COPY = 0) then COPYBILL = 'Asli';
    ELSE COPYBILL = 'Copy '||COPY;
    if (SERVICE_CHARGE = 0) then
       SELECT SERVICE_CHARGE FROM tn_sysparam
       WHERE ID = 1
       INTO SERVICE_CHARGE;
    SUSPEND;
  END
END^


ALTER PROCEDURE TN_BILLING(
    CUSTOMER VARCHAR(8),
    SYEAR INTEGER,
    SMONTH INTEGER)
RETURNS (
    TRANS_ID INTEGER,
    ROOM VARCHAR(8),
    PYEAR INTEGER,
    PMONTH INTEGER,
    CATEGORY VARCHAR(4),
    REMARK VARCHAR(40),
    REFERENCE VARCHAR(20),
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    TTYPE VARCHAR(8),
    LISTINDEX INTEGER)
AS
BEGIN
  if (CUSTOMER IS NULL) then
  BEGIN
     CUSTOMER = '0A7';
     SYEAR = 2004;
     SMONTH = 11;
  END
  FOR
    SELECT JD.TRANS_ID,
           JD.ROOM,
           JD.PYEAR,
           JD.PMONTH,
           JD.CATEGORY,
           JD.REMARK,
           JD.REFERENCE,
           JD.DB,
           JD.CR,
           TG.TTYPE,
           TG.LISTINDEX
    FROM TN_TENANT_JUR_DETAIL JD
    LEFT JOIN TN_CATEGORY TG ON JD.category = TG.code
    WHERE JD.ROOM =:CUSTOMER
     AND  JD.PYEAR=:SYEAR
     AND  JD.PMONTH=:SMONTH
     AND  JD.DB<>0
     ORDER BY TG.LISTINDEX ASC
    INTO
      :TRANS_ID,
      :ROOM,
      :PYEAR,
      :PMONTH,
      :CATEGORY,
      :REMARK,
      :REFERENCE,
      :DB,
      :CR,
      :TTYPE,
      :LISTINDEX
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE TN_BILLING_INVOICE(
    INVOICE_NO INTEGER)
RETURNS (
    CUSTOMER VARCHAR(8),
    SYEAR INTEGER,
    SMONTH INTEGER,
    TRANS_ID INTEGER,
    ROOM VARCHAR(8),
    PYEAR INTEGER,
    PMONTH INTEGER,
    CATEGORY VARCHAR(4),
    DATATYPE VARCHAR(20),
    REMARK VARCHAR(40),
    REFERENCE VARCHAR(20),
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    BALANCE DOUBLE PRECISION,
    TTYPE VARCHAR(8),
    LISTINDEX INTEGER,
    TERBILANG VARCHAR(255))
AS
declare variable OPENDATE DATE;
declare variable XTOTAL DOUBLE PRECISION;
declare variable XADJ   DOUBLE PRECISION;
BEGIN

  
  if (INVOICE_NO IS NULL) then
  BEGIN
     INVOICE_NO = 2416;
  END
  
  SELECT CUSTOMER, SOURCEID, OPENDATE FROM ARVCH
  WHERE NUMBER = :INVOICE_NO
  INTO :CUSTOMER, TRANS_ID, OPENDATE;
  

  if (TRANS_ID IS NOT NULL) then
  BEGIN
    SELECT PYEAR, PMONTH FROM TN_TENANT_JUR
    WHERE TRANS_ID = :TRANS_ID
    INTO SYEAR, SMONTH;
  END
  ELSE
  BEGIN
    execute PROCEDURE sp_beginofmonth(OPENDATE) returning_values :OPENDATE;
    OPENDATE = OPENDATE - 1;
    SYEAR = EXTRACT(YEAR FROM OPENDATE);
    SMONTH = EXTRACT(MONTH FROM OPENDATE);
  END
  
  DATATYPE = 'Billing';
  BALANCE  = 0;
  
  
    SELECT SUM(JD.DB-JD.CR) FROM TN_TENANT_JUR_DETAIL JD
    WHERE JD.ROOM =:CUSTOMER
     AND  JD.PYEAR=:SYEAR
     AND  JD.PMONTH=:SMONTH
     INTO XTOTAL;

    SELECT SUM(DB-CR) FROM ARADJ
    WHERE VOUCHERNO = :INVOICE_NO
    INTO XADJ;
    
    if (XTOTAL IS NULL) then XTOTAL = 0;
    if (XADJ IS NULL) then XADJ = 0;
    XTOTAL = XTOTAL + XADJ;
    
    SELECT NTOS('E', CAST(:XTOTAL AS INTEGER)) FROM SYSPARAM
    INTO TERBILANG;
    
    
       
  FOR
    SELECT JD.TRANS_ID,
           JD.ROOM,
           JD.PYEAR,
           JD.PMONTH,
           JD.CATEGORY,
           JD.REMARK,
           JD.REFERENCE,
           JD.DB,
           JD.CR,
           TG.TTYPE,
           TG.LISTINDEX
    FROM TN_TENANT_JUR_DETAIL JD
    LEFT JOIN TN_CATEGORY TG ON JD.category = TG.code
    WHERE JD.ROOM =:CUSTOMER
     AND  JD.PYEAR=:SYEAR
     AND  JD.PMONTH=:SMONTH
     AND  JD.DB<>0
     ORDER BY TG.LISTINDEX ASC
    INTO
      :TRANS_ID,
      :ROOM,
      :PYEAR,
      :PMONTH,
      :CATEGORY,
      :REMARK,
      :REFERENCE,
      :DB,
      :CR,
      :TTYPE,
      :LISTINDEX
  DO
  BEGIN
    BALANCE = BALANCE + DB - CR;
    TOTAL = DB - CR;
    SUSPEND;
  END
  
  DATATYPE = 'Adjustment';
  CATEGORY = 'ADJ';
  
  FOR SELECT NUMBER, DOCUMENT, DB, CR, SUBSTR(NOTE, 1, 40)  FROM ARADJ
       WHERE VOUCHERNO = :INVOICE_NO
       INTO TRANS_ID, REFERENCE, DB, CR, REMARK
  DO
  BEGIN
    BALANCE = BALANCE + DB - CR;
    TOTAL = DB - CR;
    if (REMARK IS NULL) then REMARK = REFERENCE;
    SUSPEND;  
  END
  TERBILANG = NTOS('E', BALANCE);
END^


ALTER PROCEDURE TN_CALC_PINALTY(
    CUSTOMER VARCHAR(8),
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    CATEGORY VARCHAR(4),
    REMARK VARCHAR(60),
    REFERENCE VARCHAR(20),
    AMOUNT DOUBLE PRECISION,
    NUMBER INTEGER,
    TOTAL DOUBLE PRECISION,
    PDAY INTEGER)
AS
declare variable D_OPEN VARCHAR(20);
declare variable D_PAID VARCHAR(20);
declare variable OPENDATE DATE;
declare variable PAIDDATE DATE;
BEGIN
  if (NOT EXISTS(SELECT * FROM TN_CATEGORY WHERE CODE = 'DEND')) then EXIT;
  
  if (PYEAR IS NULL) then
  BEGIN
     PYEAR = 2004;
     PMONTH = 12;
     CUSTOMER = '0B7';
  END

  CATEGORY = 'DEND';
  FOR
    SELECT NUMBER, TOTAL, OPENDATE FROM ARVCH
    WHERE CUSTOMER = :CUSTOMER
    AND PAIDSTATUS = 'P'
    AND (((PINALTY_YEAR = :PYEAR) AND (PINALTY_MONTH = :PMONTH))
          OR (PINALTY_YEAR = 0) or (PINALTY_YEAR IS NULL))
    INTO
      :NUMBER,
      :TOTAL,
      :OPENDATE
  DO
  BEGIN
    SELECT MAX(C0.OPENDATE) FROM ARCASH1 C1
    INNER JOIN ARCASH0 C0 ON C0.NUMBER = C1.NUMBER
    WHERE C1.VOUCHERNO = :NUMBER
    INTO :PAIDDATE;
    if (PAIDDATE IS NOT NULL) then
    BEGIN
       PDAY = (PAIDDATE - OPENDATE)-19;
       if (PDAY > 0) then
       BEGIN
          D_OPEN = OPENDATE;
          D_PAID = PAIDDATE;
          AMOUNT = TOTAL * PDAY / 1000;
          REMARK = 'Open ' || SUBSTR(D_OPEN, 1, 12)  || ' Paid ' || SUBSTR(D_PAID, 1, 12) ;
          REFERENCE = 'Vch# ' || NUMBER || ' Over ' || PDAY;
          UPDATE ARVCH SET PINALTY_YEAR = :PYEAR, PINALTY_MONTH = :PMONTH, PINALTY_AMOUNT = :AMOUNT, PINALTY_DAYS = :PDAY
          WHERE NUMBER = :NUMBER;
          SUSPEND;
       END
    END
  END
END^


ALTER PROCEDURE TN_CALC_POWER(
    DAYA VARCHAR(8),
    METER DOUBLE PRECISION)
RETURNS (
    CATEGORY VARCHAR(4),
    REMARK VARCHAR(90),
    AMOUNT DOUBLE PRECISION)
AS
DECLARE VARIABLE M1 DOUBLE PRECISION;
DECLARE VARIABLE M2 DOUBLE PRECISION;
DECLARE VARIABLE M3 DOUBLE PRECISION;
DECLARE VARIABLE B1 DOUBLE PRECISION;
DECLARE VARIABLE B2 DOUBLE PRECISION;
DECLARE VARIABLE B3 DOUBLE PRECISION;
DECLARE VARIABLE BEBAN DOUBLE PRECISION;
DECLARE VARIABLE BEA DOUBLE PRECISION;
DECLARE VARIABLE RATE_BEBAN DOUBLE PRECISION;
DECLARE VARIABLE RATE_KWH DOUBLE PRECISION;
DECLARE VARIABLE RATE_SURCHARGE DOUBLE PRECISION;
DECLARE VARIABLE VMETER NUMERIC(5,2);
begin
  if (DAYA IS NULL) then
  BEGIN
    DAYA = '2200';
    METER = 80;
  END
  if (DAYA = 0) then
  BEGIN
    AMOUNT = 0;
    CATEGORY = 'PW0';
    REMARK = 'Abodemen';
    suspend;

    AMOUNT = 0;
    CATEGORY = 'PW1';
    REMARK = 'Pemakaian ';
    suspend;

    AMOUNT = 0;
    CATEGORY = 'PW2';
    REMARK = 'Penerangan Jalan Umum';
    suspend;

    AMOUNT = 0;
    CATEGORY = 'PW3';
    REMARK = 'Bea Beban';
    suspend;

    AMOUNT = 0;
    CATEGORY = 'PW4';
    REMARK = 'Abodemen';
    suspend;

    AMOUNT = 0;
    CATEGORY = 'PW9';
    REMARK = 'Pemakaian ';
    suspend;
    exit;
  end

  REMARK = 'Abodemen ' || DAYA || ' VA';
  CATEGORY = 'PW0';

  SELECT BIAYA_BEBAN, BIAYA_KWH, SURCHARGE FROM TN_POWER
  WHERE DAYA = :DAYA
  INTO RATE_BEBAN, RATE_KWH, RATE_SURCHARGE;

  if (RATE_BEBAN IS NULL) then
  BEGIN
     SELECT BIAYA_BEBAN, BIAYA_KWH, SURCHARGE FROM TN_POWER
     WHERE DAYA = '2200'
     INTO RATE_BEBAN, RATE_KWH, RATE_SURCHARGE;
  END

  BEBAN = RATE_BEBAN + RATE_SURCHARGE;
  AMOUNT = BEBAN;
  SUSPEND;

  REMARK = 'Bea Beban ' ;
  CATEGORY = 'PW3';
  AMOUNT=0;
  BEA = AMOUNT;
  suspend;

  if (METER <= 0) then
  BEGIN
     REMARK = 'Pemakaian '||SUBSTR(METER,1,5);
     CATEGORY = 'PW1';
     AMOUNT = 0;
     suspend;

     REMARK = 'Penerangan Jalan Umum';
     CATEGORY = 'PW2';
     AMOUNT = 0;
     suspend;
     EXIT;
  END

  VMETER = METER;
  REMARK = 'Pemakaian '||CAST( VMETER AS NUMERIC(5,0)) || ' KWh';
  CATEGORY = 'PW1';
  AMOUNT= RATE_KWH * :VMETER ;
  suspend;

  REMARK = 'Penerangan Jalan Umum';
  CATEGORY = 'PW2';
  AMOUNT = ( (RATE_KWH * VMETER) + BEBAN ) * 0.03;
  suspend;
end^


ALTER PROCEDURE TN_CALC_WATER(
    METER DOUBLE PRECISION)
RETURNS (
    CATEGORY VARCHAR(4),
    REMARK VARCHAR(20),
    AMOUNT DOUBLE PRECISION)
AS
DECLARE VARIABLE M1 DOUBLE PRECISION;
DECLARE VARIABLE M2 DOUBLE PRECISION;
DECLARE VARIABLE M3 DOUBLE PRECISION;
DECLARE VARIABLE M4 DOUBLE PRECISION;
DECLARE VARIABLE RATE DOUBLE PRECISION;
DECLARE VARIABLE TREATMENT DOUBLE PRECISION;
DECLARE VARIABLE MINIMUM DOUBLE PRECISION;
DECLARE VARIABLE ZERO_COUNTER INTEGER;
DECLARE VARIABLE XMETER DOUBLE PRECISION;
DECLARE VARIABLE USAGE_START DOUBLE PRECISION;
DECLARE VARIABLE USAGE_END DOUBLE PRECISION;
DECLARE VARIABLE TOT_TREATMENT DOUBLE PRECISION;
DECLARE VARIABLE LAST_RANGE DOUBLE PRECISION;
DECLARE VARIABLE X INTEGER;
begin
  if (METER IS NULL) then METER = 14;
  if (METER <= 0) then
  BEGIN
     REMARK = 'Pemakaian 0';
     CATEGORY = 'WT1';
     AMOUNT = 0;
     SUSPEND;
     REMARK = 'Pelayanan Air Kotor';
     CATEGORY = 'WT2';
     AMOUNT = 0;
     SUSPEND;
     REMARK = 'Pemakaian 0';
     CATEGORY = 'WT9';
     AMOUNT = 0;
     SUSPEND;
     EXIT;
  END

  REMARK = 'Pemakaian ' || CAST(METER AS NUMERIC(5,2)) || ' M3';
  CATEGORY = 'WT1';
  
  SELECT COUNT(*) FROM TN_WATER
  WHERE USAGE_START = 0
  INTO ZERO_COUNTER;
  ZERO_COUNTER = 2;
  if (ZERO_COUNTER <= 1) then
  BEGIN
    SELECT USAGE_RATE, WATER_TREATMENT_PERCENT, MINIMUM
    FROM TN_WATER
    WHERE :METER BETWEEN USAGE_START AND USAGE_END
    INTO :RATE, :TREATMENT, :MINIMUM;
  
    if (MINIMUM > METER) then METER = MINIMUM;
    AMOUNT = METER * RATE;
    SUSPEND;
    if (TREATMENT <> 0) then
    BEGIN
       REMARK = 'Pelayanan Air Kotor';
       CATEGORY = 'WT2';
       AMOUNT = AMOUNT * TREATMENT/100;
       SUSPEND;
    END
    EXIT;
  END
  TOT_TREATMENT = 0;
  AMOUNT = 0;
  XMETER = METER;
  LAST_RANGE = 0;

  FOR SELECT USAGE_END, USAGE_RATE, WATER_TREATMENT_PERCENT, MINIMUM
    FROM TN_WATER
    ORDER BY USAGE_END
    INTO USAGE_END, :RATE, :TREATMENT, :MINIMUM
  DO
  BEGIN
    if (XMETER >= USAGE_END) then
    BEGIN
       AMOUNT = AMOUNT + RATE * (USAGE_END-LAST_RANGE);
    END
    ELSE
    BEGIN
       if (METER > LAST_RANGE) then /* KOREKSI */
          AMOUNT = AMOUNT + RATE * (METER - LAST_RANGE);
    END
    LAST_RANGE = USAGE_END;
  END
  SUSPEND;
  if (TREATMENT <> 0) then
    BEGIN
       REMARK = 'Pelayanan Air Kotor';
       CATEGORY = 'WT2';
       AMOUNT = AMOUNT * TREATMENT/100;
       SUSPEND;
    END
END^


ALTER PROCEDURE TN_CASUAL_DSR_VIEW(
    SDATE DATE)
RETURNS (
    TNDATE DATE,
    CATEGORY VARCHAR(4),
    REMARK VARCHAR(40),
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    DB_ACCOUNT VARCHAR(20),
    DB_DEPT VARCHAR(4),
    DB_COST VARCHAR(4),
    CR_ACCOUNT VARCHAR(20),
    CR_DEPT VARCHAR(4),
    CR_COST VARCHAR(4),
    BALANCE DOUBLE PRECISION,
    MTD_DB DOUBLE PRECISION,
    MTD_CR DOUBLE PRECISION,
    MTD_BALANCE DOUBLE PRECISION,
    POSTED CHAR(1))
AS
declare variable BOM DATE;
BEGIN
  if (SDATE IS NULL) then SDATE = '1.1.2005';
  
  EXECUTE PROCEDURE sp_endofmonth(:SDATE) returning_values BOM;
  
  
  if (NOT EXISTS(SELECT * FROM TN_CASUAL_DSR WHERE TNDATE = :SDATE)) then
  BEGIN
     FOR SELECT CODE, NAME FROM TN_CATEGORY
         WHERE FLAG_CASUAL = 1
     INTO :CATEGORY, :REMARK DO
     BEGIN
         SELECT SUM(DB), SUM(CR) FROM tn_casual_journal
         WHERE TNDATE = :SDATE
         AND CATEGORY = :CATEGORY
         PLAN (TN_CASUAL_JOURNAL INDEX (TN_CASUAL_JOURNAL_IDX_DATE))
         INTO DB, CR;
         if (DB IS NULL) then
         BEGIN
            DB = 0;
            CR = 0;
         END
         
         SELECT SUM(DB), SUM(CR) FROM tn_casual_journal
         WHERE CATEGORY = :CATEGORY
         AND TNDATE BETWEEN :BOM AND :SDATE
         PLAN (TN_CASUAL_JOURNAL INDEX (TN_CASUAL_JOURNAL_IDX_CAT))
         INTO MTD_DB, MTD_CR;
         if (MTD_DB IS NULL) then
         BEGIN
            MTD_DB = 0;
            MTD_CR = 0;
         END         
         
         INSERT INTO TN_CASUAL_DSR (TNDATE, CATEGORY, REMARK, DB, CR, MTD_DB, MTD_CR, POSTED)
         VALUES (:SDATE, :CATEGORY, :REMARK, :DB, :CR, :MTD_DB, :MTD_CR, 0);
     END
  END
  FOR SELECT D.TNDATE,
             D.CATEGORY,
             D.REMARK,
             D.DB,
             D.CR, D.MTD_DB, D.MTD_CR,
             C.CASUAL_DB_ACCOUNT, C.CASUAL_DB_DEPT, C.CASUAL_DB_COST,
             C.CASUAL_CR_ACCOUNT, C.CASUAL_CR_DEPT, C.CASUAL_CR_COST,
             D.POSTED
      FROM TN_CASUAL_DSR D
      LEFT JOIN TN_CATEGORY C ON C.CODE = D.CATEGORY
      WHERE TNDATE = :SDATE
      ORDER BY C.LISTINDEX
      INTO :TNDATE,
           :CATEGORY,
           :REMARK,
           :DB,
           :CR, MTD_DB, MTD_CR,
           :DB_ACCOUNT, :DB_DEPT, :DB_COST,
           :CR_ACCOUNT, :CR_DEPT, :CR_COST,
           :POSTED
  DO BEGIN
     BALANCE = DB-CR;
     MTD_BALANCE = MTD_DB-MTD_CR;
     SUSPEND;
  END
END^


ALTER PROCEDURE TN_CASUAL_RI_REBUILD
AS
declare variable FOLIO INTEGER;
declare variable DATECI DATE;
declare variable DATECO DATE;
declare variable FOLIOSTATUS CHAR(1);
declare variable ROOM VARCHAR(8);
declare variable X INTEGER;
begin
   UPDATE tn_casual_roomno SET OVERLAPPED_COUNTER = -1;
   DELETE FROM TN_CASUAL_RI;
   DELETE FROM TN_CASUAL_RI_ASSIGN WHERE OVERLAPPED = 0;
   DELETE FROM TN_CASUAL_RI_ASSIGN WHERE OVERLAPPED <> 0;
   
   FOR SELECT FOLIO, DATECI, DATECO, FOLIOSTATUS
       FROM TN_CASUAL
       WHERE (FOLIOSTATUS IN ('I','C','T'))
       INTO :FOLIO, DATECI, DATECO, FOLIOSTATUS
   DO
   BEGIN
     FOR SELECT ROOM FROM TN_CASUAL_ROOM
         WHERE FOLIO = :FOLIO
         INTO :ROOM
     DO
     BEGIN
         EXECUTE PROCEDURE TN_CASUAL_RI_SAVE(:FOLIO, :ROOM, :DATECI, :DATECO,
                                             :FOLIOSTATUS, 1);
                                             
         EXECUTE PROCEDURE TN_CASUAL_RI_SAVE_ASSIGN(:FOLIO, :ROOM, :DATECI, :DATECO, 1);
     END
   END
end^


ALTER PROCEDURE TN_CASUAL_RI_SAVE(
    FOLIO INTEGER,
    ROOM VARCHAR(8),
    DATECI DATE,
    DATECO DATE,
    STATUS CHAR(1),
    FACTOR INTEGER)
AS
declare variable XDATE DATE;
declare variable M2 DOUBLE PRECISION;
declare variable ROOMTYPE VARCHAR(4);
declare variable REVENUE DOUBLE PRECISION;
declare variable x integer;
begin
  if (FOLIO IS NULL) then
  BEGIN
     FOLIO = 1;
     ROOM = '1A1';
     DATECI = '1.10.2004';
     DATECO = '7.10.2004';
     STATUS = 'C';
     FACTOR = 1;
  END
  

  SELECT M2, ROOMTYPE FROM TN_CASUAL_ROOMNO WHERE ROOM = :ROOM INTO M2, ROOMTYPE;
  if (M2 IS NULL) then M2 = 0;
  XDATE = DATECI;
  /* CREATE RECORD AND SAVE NEW */
  WHILE (XDATE <= DATECO) DO
  BEGIN
    if (NOT EXISTS(SELECT * FROM TN_CASUAL_RI WHERE ROOMTYPE = :ROOMTYPE AND TNDATE = :XDATE)) then
    BEGIN
       INSERT INTO tn_casual_ri (ROOMTYPE, TNDATE)
       VALUES (:ROOMTYPE, :XDATE);
    END
    
    REVENUE = 0;
    SELECT SUM(DB-CR) FROM tn_casual_journal WHERE FOLIO = :FOLIO  AND TNDATE = :XDATE
    INTO REVENUE;
    if (REVENUE IS NULL) then REVENUE = 0;

    if (STATUS = 'I') then
       UPDATE TN_CASUAL_RI SET M2_INHOUSE = M2_INHOUSE + :M2*:FACTOR, COUNT_INHOUSE = COUNT_INHOUSE + :FACTOR,
                               REVENUE_INHOUSE = REVENUE_INHOUSE + :REVENUE*:FACTOR
       WHERE ROOMTYPE = :ROOMTYPE AND TNDATE = :XDATE;
    ELSE if (STATUS = 'C') then
       UPDATE TN_CASUAL_RI SET M2_CONFIRM = M2_CONFIRM + :M2*:FACTOR, COUNT_CONFIRM = COUNT_CONFIRM + :FACTOR,
                               REVENUE_CONFIRM = REVENUE_CONFIRM+ :REVENUE*:FACTOR
       WHERE ROOMTYPE = :ROOMTYPE AND TNDATE = :XDATE;
    ELSE if (STATUS = 'T') then
       UPDATE TN_CASUAL_RI SET M2_TENTATIVE = M2_TENTATIVE + :M2*:FACTOR, COUNT_TENTATIVE = COUNT_TENTATIVE + :FACTOR,
                               REVENUE_TENTATIVE = REVENUE_TENTATIVE + :REVENUE*:FACTOR
       WHERE ROOMTYPE = :ROOMTYPE AND TNDATE = :XDATE;       

    XDATE = XDATE + 1;
  END
end^


ALTER PROCEDURE TN_CASUAL_RI_SAVE_ASSIGN(
    FOLIO INTEGER,
    ROOM VARCHAR(8),
    DATECI DATE,
    DATECO DATE,
    FACTOR INTEGER)
AS
declare variable XDATE DATE;
declare variable x integer;
begin
  /* HAPUS YANG LAMA */
  if (FACTOR < 0) then
  BEGIN
     DELETE FROM TN_CASUAL_RI_ASSIGN
     WHERE FOLIO = :FOLIO
       AND ROOM = :ROOM
       AND OVERLAPPED = 0;
     EXIT;
  END

  /* CHECK BOOKING */
  if (EXISTS (SELECT * FROM TN_CASUAL_RI_ASSIGN WHERE ROOM = :ROOM AND
              TNDATE BETWEEN :DATECI AND :DATECO
              AND FOLIO <> :FOLIO)) then
     EXCEPTION TN_CASUAL_BOOKED;
  /* DELETE OLD ROOM */
  DELETE FROM TN_CASUAL_RI_ASSIGN
   WHERE FOLIO = :FOLIO
     AND ROOM = :ROOM
     AND OVERLAPPED = 0;
  /* SAVE NEW BOOKING */
  
  XDATE = DATECI;  
  WHILE (XDATE <= DATECO) DO
  BEGIN
    INSERT INTO TN_CASUAL_RI_ASSIGN (ROOM, TNDATE, FOLIO, OVERLAPPED)
    VALUES (:ROOM, :XDATE,:FOLIO, 0);
    XDATE = XDATE + 1;
  END
end^


ALTER PROCEDURE TN_CASUAL_RI_SAVE_ASSIGN_OL(
    ROOM VARCHAR(8))
RETURNS (
    OROOM VARCHAR(8),
    FLAG INTEGER)
AS
declare variable XROOM VARCHAR(8);
begin
  if (ROOM IS NULL) then ROOM = 'AGF';
  
     FOR SELECT OVERLAPPED FROM tn_casual_roomno_overlapped
        WHERE ROOM = :ROOM
        INTO OROOM DO
    BEGIN
      FLAG = 1;
      SUSPEND;
      XROOM = OROOM;
      FLAG = 2;
      FOR SELECT ROOM FROM tn_casual_roomno_overlapped
          WHERE OVERLAPPED = :XROOM
          GROUP BY ROOM
          INTO OROOM DO
      BEGIN
         if (OROOM <> ROOM) then
            SUSPEND;
      END
    END
    FLAG = 2;
    FOR SELECT ROOM FROM tn_casual_roomno_overlapped
        WHERE OVERLAPPED = :ROOM
        GROUP BY ROOM
        INTO OROOM DO
    BEGIN
      if (OROOM <> ROOM) then
         SUSPEND;
    END
end^


