ALTER PROCEDURE TN_CHART_ROOM(
    CHARTTYPE VARCHAR(10))
RETURNS (
    CODE VARCHAR(10),
    NAME VARCHAR(40),
    COUNTER INTEGER,
    M2 DOUBLE PRECISION,
    M2_NET DOUBLE PRECISION)
AS
BEGIN
  if (CHARTTYPE IS NULL) then CHARTTYPE = 'STATUS';
  if (CHARTTYPE = 'TYPE') then
  BEGIN
    FOR
      SELECT ROOMTYPE, COUNT(*), SUM(SQUARE_METER), SUM(SQUARE_METER_NET)
      FROM TN_ROOM
      GROUP BY ROOMTYPE
      INTO
        :CODE,
        :COUNTER,
        :M2,
        :M2_NET
    DO
    BEGIN
      SELECT NAME FROM TN_ROOMTYPE
      WHERE ROOMTYPE = :CODE
      INTO :NAME;
      SUSPEND;
    END
  END
  ELSE
  if (CHARTTYPE = 'STATUS') then
  BEGIN
    FOR
      SELECT STATUS, COUNT(*), SUM(SQUARE_METER), SUM(SQUARE_METER_NET)
      FROM TN_ROOM
      GROUP BY STATUS
      INTO
        :CODE,
        :COUNTER,
        :M2,
        :M2_NET
    DO
    BEGIN
      if (CODE = 'A') then NAME = 'Active';
      ELSE if (CODE = 'N') then NAME = 'Non Active';
      ELSE if (CODE = 'C') then NAME = 'Under Construction';
      ELSE if (CODE = 'O') then NAME = 'Out of Order';
      else name = CODE;
      SUSPEND;
    END
  END  
END^


ALTER PROCEDURE TN_CHECK_INVALID_CUSTOMER(
    PSAVE INTEGER)
RETURNS (
    CASH_NUMBER INTEGER,
    CASH_NAME VARCHAR(40),
    OPENDATE DATE,
    CUSTOMER_CASH VARCHAR(8),
    CUSTOMER_DETAIL VARCHAR(8),
    CUSTOMER_VOUCHER VARCHAR(8),
    VOUCHER_NUMBER INTEGER,
    VOUCHER_OPENDATE DATE,
    VCOUHER_NAME VARCHAR(40))
AS
BEGIN
  FOR
    SELECT H.NUMBER CASH_NUMBER, H.OPENDATE, H.CUSTOMER CUSTOMER_CASH,
           D.CUSTOMER CUSTOMER_DETAIL, V.CUSTOMER CUSTOMER_VOUCHER,
           V.NUMBER VOUCHER_NUMBER,
           V.OPENDATE VOUCHER_OPENDATE
    FROM ARCASH1 D
    LEFT JOIN ARCASH0 H ON H.NUMBER = D.NUMBER
    LEFT JOIN ARVCH V ON V.NUMBER = D.VOUCHERNO
    WHERE H.CUSTOMER <> D.CUSTOMER
    OR D.CUSTOMER <> V.CUSTOMER
    INTO
      :CASH_NUMBER,
      :OPENDATE,
      :CUSTOMER_CASH,
      :CUSTOMER_DETAIL,
      :CUSTOMER_VOUCHER,
      :VOUCHER_NUMBER,
      :VOUCHER_OPENDATE
  DO
  BEGIN
    SELECT NAME FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER_CASH
    INTO CASH_NAME;
    
    SELECT NAME FROM SYSCUSTOMER WHERE CUSTOMER = :CUSTOMER_VOUCHER
    INTO VCOUHER_NAME;
    IF (PSAVE <> 1) THEN SUSPEND;
    ELSE
    BEGIN
       UPDATE ARCASH0 SET CUSTOMER = :CUSTOMER_VOUCHER
       WHERE NUMBER = :CASH_NUMBER;
    END
  END
END^


ALTER PROCEDURE TN_CREATE_JUR(
    PYEAR INTEGER,
    PMONTH INTEGER,
    USER_ID VARCHAR(8))
RETURNS (
    COUNTER INTEGER)
AS
DECLARE VARIABLE ROOM VARCHAR(8);
DECLARE VARIABLE X INTEGER;
DECLARE VARIABLE ARSYSDATE DATE;
DECLARE VARIABLE VMONTH INTEGER;
DECLARE VARIABLE VYEAR INTEGER;
DECLARE VARIABLE FLAG_BILLING INTEGER;
DECLARE VARIABLE ROOMSTATUS CHAR(1);
begin
  SELECT ARSYSDATE FROM sysparam
   WHERE ID=1 INTO :ARSYSDATE;

  VYEAR = EXTRACT(YEAR FROM ARSYSDATE);
 VMONTH = EXTRACT(MONTH FROM ARSYSDATE);
  if (PYEAR IS NULL) then
  BEGIN
     PYEAR  = VYEAR  ;
     PMONTH = VMONTH ;
  END
  IF ((PYEAR=VYEAR) AND (PMONTH<VMONTH)) THEN Exception TN_LESS_MONTH ;
  ELSE IF (PYEAR<VYEAR) THEN Exception TN_LESS_MONTH ;
  COUNTER = 0;

  FOR SELECT ROOM, FLAG_BILLING, STATUS FROM tn_room
  INTO ROOM, FLAG_BILLING, ROOMSTATUS
  DO
  BEGIN
    if ((FLAG_BILLING = 1) AND (ROOMSTATUS = 'A')) then
    BEGIN
       if (NOT EXISTS(SELECT * FROM tn_tenant_jur WHERE ROOM = :ROOM
               AND PYEAR = :PYEAR AND PMONTH = :PMONTH)) THEN
       BEGIN
         COUNTER = COUNTER + 1;
         INSERT INTO TN_TENANT_JUR (
           ROOM,
           PYEAR,
           PMONTH,
           DB,
           CR,
           STATUS,
           PRINTED_COUNTER,
           METER_ELECTRIC,
           METER_WATER,
           METER_GAS,
           METER_1,
           METER_2,
           METER_3,
           CREATEUSER,
           EDITUSER,
           PRINTED_USER,
           CREATEDATE,
           EDITDATE,
           PRINTED_DATE)
         VALUES (
           :ROOM,
           :PYEAR,
           :PMONTH,
           0, /*:DB,*/
           0, /*:CR,*/
           'O', /*:STATUS,*/
           0, /*:PRINTED_COUNTER,*/
           0, /*:METER_ELECTRIC,*/
           0, /*:METER_WATER,*/
           0, /*:METER_GAS,*/
           0, /*:METER_1,*/
           0, /*:METER_2,*/
           0, /*:METER_3,*/
           :USER_ID, /*:CREATEUSER,*/
           :USER_ID, /*:EDITUSER, */
           '', /*:PRINTED_USER,*/
           'NOW', /*:CREATEDATE,*/
           'NOW', /*:EDITDATE,*/
           NULL /*PRINTED_DATE*/);
       END
    END
    ELSE
    BEGIN
       DELETE FROM tn_tenant_jur WHERE ROOM = :ROOM
       AND PYEAR = :PYEAR AND PMONTH = :PMONTH;
    END
  END
  suspend;
end^


ALTER PROCEDURE TN_EOD(
    ACTION_ID INTEGER)
RETURNS (
    TEXT VARCHAR(50))
AS
declare variable SYSDATE  DATE;
begin
  SELECT CASUAL_SYSDATE FROM TN_SYSPARAM INTO SYSDATE;
  
  if (EXISTS(SELECT * FROM TN_CASUAL WHERE DATECI = :SYSDATE AND FOLIOSTATUS IN ('T','C','W'))) then
     exception TN_EOD_NO_SHOW;
     
  if (EXISTS(SELECT * FROM TN_CASUAL WHERE DATECO = :SYSDATE AND FOLIOSTATUS = 'I')) then
     exception TN_EOD_CHECKOUT;

  UPDATE TN_SYSPARAM SET CASUAL_SYSDATE = CASUAL_SYSDATE + 1;
  
end^


ALTER PROCEDURE TN_GLBUFFER_TENANT(
    PROOM VARCHAR(8),
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    INFO VARCHAR(20),
    GRP VARCHAR(4),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    ERROR_TEXT VARCHAR(128))
AS
declare variable ICOST VARCHAR(4);
declare variable XDEFA_ACCOUNT VARCHAR(20);
declare variable XDEFA_DEPT VARCHAR(4);
declare variable XDEFA_COST VARCHAR(4);
declare variable CUSTOMER VARCHAR(8);
declare variable NUMBER INTEGER;
declare variable PDAY INTEGER;
BEGIN
  if (PYEAR IS NULL) then
  BEGIN
     SELECT MAX(TRANS_ID) FROM TN_TENANT_JUR
     INTO NUMBER;
     SELECT ROOM, PYEAR, PMONTH FROM TN_TENANT_JUR
     WHERE TRANS_ID = :NUMBER
     INTO PROOM, PYEAR, PMONTH;
  END
  
  SELECT INVOICE_DAY FROM TN_SYSPARAM
  WHERE ID = 1
  INTO PDAY;
     
  if (PDAY IS NULL) then PDAY = 5;
  if (PDAY NOT BETWEEN 1 AND 28) then PDAY = 5;  
  
  SELECT CUSTOMER, DB-CR, PYEAR, PMONTH, ROOM
  FROM TN_TENANT_JUR
  WHERE ROOM = :PROOM
  AND PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  INTO CUSTOMER, DEBIT, PYEAR, PMONTH, PROOM;
  TRANSDATE = PDAY || '.'||pmonth||'.'||pyear;
  REF = PROOM||'-'||PYEAR||'-'||PMONTH;
  /* --------------------------------------------------------------------- */
  /* DETAIL TO GL BUFFER                                                   */
  /* --------------------------------------------------------------------- */
  SELECT T.GLACCOUNT, A.NAME, T.GLDEPT, T.GLCOST
  FROM syscustomertype T
  LEFT JOIN GLCOA A ON A.ACCOUNT = T.GLACCOUNT  
  WHERE T.CUSTOMERTYPE = '0000'
  INTO GL_ACCOUNT, ACCNAME, GL_DEPT, GL_COST;
  if (GL_COST IS NULL) then GL_COST = '0000';

  SELECT NAME FROM SYSCUSTOMER
  WHERE CUSTOMER = :CUSTOMER
  INTO :NOTE;
  /* AR ACCOUNT */
  SELECT SUM(D.DB-D.CR)
  FROM tn_tenant_jur_detail D
  WHERE ROOM = :PROOM
  AND PYEAR = :PYEAR
  AND PMONTH = :PMONTH  
  INTO :DEBIT;

  if ((DEBIT IS NULL) or (DEBIT =0)) then EXIT;

  CREDIT = 0;
  ID  = 0;
  INFO = 'A/R';
  GRP='AR';
  SUSPEND;
  
  /* GET  HEADER */
  DEBIT = 0;
  INFO = 'Charge';
  FOR
       SELECT D.CATEGORY, SUM(D.DB-D.CR) CR,  D.REMARK,
               C.GL_ACCOUNT, C.GL_DEPT, C.GL_COST, A.NAME
       FROM tn_tenant_jur_detail D
       LEFT JOIN tn_category C ON C.CODE = D.CATEGORY
       LEFT JOIN GLCOA A ON A.ACCOUNT = C.GL_ACCOUNT
       WHERE ROOM = :PROOM
       AND PYEAR = :PYEAR
       AND PMONTH = :PMONTH
       AND (DB+CR) <> 0
       GROUP BY D.CATEGORY, D.REMARK,C.GL_ACCOUNT, C.GL_DEPT, C.GL_COST, A.NAME
       INTO
          :GRP,
          :CREDIT,
          :NOTE,
          :GL_ACCOUNT,
          :GL_DEPT,
          :GL_COST,
          :ACCNAME
  DO
  BEGIN
     ID = ID + 1;
     SUSPEND;
  END
END^


ALTER PROCEDURE TN_GLBUFFER_TENANT_RECREATE(
    PYEAR INTEGER,
    PMONTH INTEGER,
    PSAVE INTEGER)
RETURNS (
    INFO VARCHAR(20),
    GRP VARCHAR(4),
    TRANSDATE DATE,
    ID INTEGER,
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NOTE VARCHAR(40),
    REF VARCHAR(20),
    DEBIT DOUBLE PRECISION,
    CREDIT DOUBLE PRECISION,
    SETUP_INFO VARCHAR(16),
    ERROR_TEXT VARCHAR(128))
AS
declare variable NUMBER INTEGER;
declare variable PROOM VARCHAR(8);
declare variable SDATE DATE;
declare variable DELTA DOUBLE PRECISION;
declare variable USR VARCHAR(8);
declare variable TOTAL DOUBLE PRECISION;
BEGIN
  if (PYEAR IS NULL) then
  BEGIN
     SELECT MAX(TRANS_ID) FROM TN_TENANT_JUR
     INTO NUMBER;
     SELECT PYEAR, PMONTH FROM TN_TENANT_JUR
     WHERE TRANS_ID = :NUMBER
     INTO PYEAR, PMONTH;  
     PSAVE = 0;
  END

  SDATE = '1.'||pmonth||'.'||pyear;
  if (PSAVE = 1) then
  BEGIN
     DELETE FROM glbuffer
     WHERE APPLICATION = 'AR'
     AND SOURCE = 'TENT'
     AND TRANSDATE = :SDATE;
     
     UPDATE GLTRANS SET STATUS = 'R' /* BUKA STATUS MENJADI OPEN */
     WHERE PYEAR = :PYEAR
     AND PMONTH = :PMONTH
     AND APPLICATION = 'AR'
     AND SOURCE = 'TENT'
     AND STATUS = 'P';
     
     DELETE FROM GLTRANS
     WHERE PYEAR = :PYEAR
     AND PMONTH = :PMONTH
     AND APPLICATION = 'AR'
     AND SOURCE = 'TENT';
  END
  DELTA = 0;
  
  FOR SELECT ROOM, TRANS_ID, EDITUSER, DB-CR FROM TN_TENANT_JUR
      WHERE PYEAR = :PYEAR
      AND PMONTH = :PMONTH
      AND STATUS = 'R'
  INTO PROOM, NUMBER, USR, TOTAL
  DO
  BEGIN
    DELTA = DELTA+TOTAL;
    FOR
      SELECT INFO, GRP, TRANSDATE, ID, GL_ACCOUNT, GL_DEPT,
             GL_COST, ACCNAME, NOTE, REF, DEBIT, CREDIT FROM TN_GLBUFFER_TENANT(:PROOM, :PYEAR, :PMONTH)
      INTO :INFO, :GRP, :TRANSDATE, :ID, :GL_ACCOUNT, :GL_DEPT,
           :GL_COST, :ACCNAME, :NOTE, :REF, :DEBIT, :CREDIT
    DO
    BEGIN
       DELTA = DELTA - DEBIT;
       if (DEBIT + CREDIT <> 0) then
       BEGIN
         if (PSAVE = 1) then
         BEGIN
          insert into glbuffer
                 (APPLICATION, SOURCE, NUMBER, ID, transdate,
                  ACCOUNT, DEPT, COST, PROJECT,
                  NOTE, REF,
                  DB, CR,
                  EXPORTDATE, EXPORTUSER)
          values ('AR','TENT', :number, :ID, :SDATE,
                  :GL_ACCOUNT, :GL_DEPT, :GL_COST, '',
                  :NOTE, :REF,
                  :DEBIT, :CREDIT,
                  'now', :USR);
          END
          ELSE
            SUSPEND;
       END
    END
  END  
END^


ALTER PROCEDURE TN_LEASE_JOURNAL(
    NUMBER INTEGER)
RETURNS (
    LINE INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    STATUS CHAR(1),
    CHECK_NUMBER VARCHAR(20),
    CHECK_TEXT VARCHAR(40),
    CHECK_DUE DATE,
    AR_NUMBER INTEGER,
    AMOUNT DOUBLE PRECISION,
    NAME VARCHAR(40))
AS
BEGIN
  if (NUMBER IS NULL) then NUMBER = 0;
  FOR
    SELECT J.LINE,J.OPENDATE, J.DUEDATE, J.STATUS,
           J.CHECK_NUMBER, J.CHECK_TEXT, J.CHECK_DUE,
           J.AR_NUMBER,
           J.AMOUNT,
           C.NAME FROM TN_LEASE_JUR  J
    LEFT JOIN TN_CATEGORY C ON C.CODE = J.JUR_TYPE
    WHERE J.NUMBER = :NUMBER
    ORDER BY J.LINE

    INTO
      :LINE,
      :OPENDATE,
      :DUEDATE,
      :STATUS,
      :CHECK_NUMBER,
      :CHECK_TEXT,
      :CHECK_DUE,
      :AR_NUMBER,
      :AMOUNT,
      :NAME
  DO
  BEGIN
    SUSPEND;
  END
END^


ALTER PROCEDURE TN_LEASE_SCHEDULE
RETURNS (
    PYEAR INTEGER,
    TOTAL DOUBLE PRECISION,
    AMT01 DOUBLE PRECISION,
    AMT02 DOUBLE PRECISION,
    AMT03 DOUBLE PRECISION,
    AMT04 DOUBLE PRECISION,
    AMT05 DOUBLE PRECISION,
    AMT06 DOUBLE PRECISION,
    AMT07 DOUBLE PRECISION,
    AMT08 DOUBLE PRECISION,
    AMT09 DOUBLE PRECISION,
    AMT10 DOUBLE PRECISION,
    AMT11 DOUBLE PRECISION,
    AMT12 DOUBLE PRECISION)
AS
declare variable PMONTH INTEGER;
declare variable Y INTEGER;
declare variable AMT DOUBLE PRECISION;
begin
  SELECT EXTRACT(YEAR FROM  ARSYSDATE) FROM SYSPARAM INTO PYEAR;
  PYEAR = PYEAR - 3;
  Y = 0;
  WHILE (Y <= 20) DO
  BEGIN
     PYEAR = PYEAR + 1;
     PMONTH = 1;
     TOTAL = 0;
     WHILE (PMONTH <= 12) DO
     BEGIN
        AMT = NULL;
        SELECT SUM(AMOUNT+TAX) FROM TN_LEASE_JUR
        WHERE PYEAR = :PYEAR
        AND PMONTH =:PMONTH
        INTO AMT;
        if (AMT IS NULL) then AMT = 0;
        TOTAL = TOTAL + AMT;
        if (PMONTH = 1) then AMT01 = AMT;
        ELSE if (PMONTH = 2) then AMT02 = AMT;
        ELSE if (PMONTH = 3) then AMT03 = AMT;
        ELSE if (PMONTH = 4) then AMT04 = AMT;
        ELSE if (PMONTH = 5) then AMT05 = AMT;
        ELSE if (PMONTH = 6) then AMT06 = AMT;
        ELSE if (PMONTH = 7) then AMT07 = AMT;
        ELSE if (PMONTH = 8) then AMT08 = AMT;
        ELSE if (PMONTH = 9) then AMT09 = AMT;
        ELSE if (PMONTH =10) then AMT10 = AMT;
        ELSE if (PMONTH =11) then AMT11 = AMT;
        ELSE if (PMONTH =12) then AMT12 = AMT;
        PMONTH = PMONTH + 1;
     END
     SUSPEND;
     Y = Y + 1;
  END
end^


ALTER PROCEDURE TN_MUTATION(
    SCUSTOMER VARCHAR(8),
    ECUSTOMER VARCHAR(8),
    SOURCE VARCHAR(4))
RETURNS (
    CREDITCARD INTEGER,
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    OPENING NUMERIC(15,4),
    VOUCHER NUMERIC(15,4),
    DEPOSIT NUMERIC(15,4),
    CASH NUMERIC(15,4),
    ADJUST NUMERIC(15,4),
    ENDING NUMERIC(15,4),
    CUSTTYPE VARCHAR(4))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable sDate date;
declare variable eDate date;
declare variable fo_adjust double precision;
declare variable pcash double precision;
declare variable REFDATE DATE;
declare variable XDEPOSIT DOUBLE PRECISION;
declare variable vrow integer;
declare variable adjust1 double precision;
declare variable XNUMBER INTEGER;
declare variable xadjust DOUBLE PRECISION;

declare variable XBANK VARCHAR(4);
declare variable XOUTLET VARCHAR(4);
declare variable xcash double precision;
begin

  CREDITCARD = 0;
  select arsysdate from sysparam into :REFDATE;

  if (SCUSTOMER IS NULL) then BEGIN
     SCUSTOMER = '';
     eCUSTOMER = 'ZZZZZZ';
  END
  execute procedure sp_beginofmonth (refdate) returning_values sDate;
  execute procedure sp_endofmonth   (refdate) returning_values eDate;

  for select CUSTOMER, name,CUSTTYPE from sysCUSTOMER
  where CUSTOMER between :sCUSTOMER and :eCUSTOMER
  into :CUSTOMER, name, CUSTTYPE
  do
  begin
    opening = 0;
    voucher = 0;
    cash = 0;
    adjust = 0;
    ending = 0;
    adjust1 = 0;
    /*========================================================================*/
    /* hitung ending                                                          */
    /*========================================================================*/
    select sum(totaldue) from ARvch
     where PAIDSTATUS = 'O'
       AND CUSTOMER = :CUSTOMER
     PLAN (ARVCH INDEX (ARVCH_IDX_PAIDSTATUS))
      into ending;
    /*========================================================================*/
    /* hitung bulan ini                                                       */
    /*========================================================================*/
    select SUM(TOTAL) from ARvch
     where CUSTOMER = :CUSTOMER
       and OpenDate between :sDate and :eDate
       PLAN (ARVCH INDEX (ARVCH_IDX_OPENDATE))
      into :voucher;
      
    select sum(ARdepos1.total) from ARdepos1
     where ARdepos1.CUSTOMER = :CUSTOMER
       and ARdepos1.APPlieddate between :sDate and :eDate
       AND ARdepos1.STATUS IN ('R','C')
      into deposit;

    select sum(total) from ARcash0 where CUSTOMER = :CUSTOMER
       and DueDate between :sDate and :eDate
       and status in ('C', 'R','L')
       PLAN (ARCASH0 INDEX (ARCASH0_IDX_CUST_DUEDATE))
      into :cash;

    select sum(db-cr) from ARadj
      where CUSTOMER = :CUSTOMER
       and OpenDate between :sDate and :eDate
       PLAN (ARADJ INDEX (ARADJ_IDX_OPENDATE))
      into :adjust1;
      
    /* 10-JAN-2003, SPEEDUP */
    adjust = 0;
    FOR SELECT NUMBER FROM arvch
        WHERE CUSTOMER = :CUSTOMER
        AND OPENDATE >= :sDate 
        PLAN (ARVCH INDEX (ARVCH_IDX_OPENDATE))
    INTO XNUMBER DO
    BEGIN
      select sum(D.debit-D.credit) from ARVCH_DETAIL D
      where D.NUMBER = :XNUMBER
      and D.source = 'A'
      and D.status = 'C'               
      and D.FODATE between :sDate and :eDate
      PLAN (ARVCH_DETAIL INDEX (ARVCH_DETAIL_IDX_NO_SOURCE))
      into xadjust;
      if (xadjust is not null) then
         adjust = adjust + xadjust;
    END
    /* END OF SPEED UP */
/*
    select sum(D.debit-D.credit) from ARVCH_DETAIL D
    INNER JOIN ARVCH H ON D.NUMBER = H.NUMBER
    where H.CUSTOMER = :CUSTOMER
    and D.FODATE between :sDate and :eDate
    and D.status = 'C'  CLOSE, POSTED
    and D.source = 'A'  ADJUSTMENT
    into adjust;
*/
    if (ending  is null) then ending  = 0;
    if (voucher is null) then voucher = 0;
    if (cash    is null) then cash    = 0;
    if (adjust  is null) then adjust  = 0;
    if (adjust1 is null) then adjust1 = 0;
    if (deposit is null) then deposit = 0;
    adjust = adjust + adjust1 - deposit;
    opening = ending - voucher + cash - adjust;
    if ((opening <> 0) or (ending <> 0)  or (voucher <> 0) or (cash <> 0) or (adjust <> 0)) then
       suspend;
  end
end^


ALTER PROCEDURE TN_RI_VIEW(
    SDATE DATE,
    INFOTYPE VARCHAR(8))
RETURNS (
    DATASECTION VARCHAR(10),
    ROOMTYPE VARCHAR(10),
    TEXT VARCHAR(50),
    FORMAT VARCHAR(30),
    DAY1 DOUBLE PRECISION,
    DAY2 DOUBLE PRECISION,
    DAY3 DOUBLE PRECISION,
    DAY4 DOUBLE PRECISION,
    DAY5 DOUBLE PRECISION,
    DAY6 DOUBLE PRECISION,
    DAY7 DOUBLE PRECISION,
    BOLD INTEGER)
AS
declare variable FLAG_OVERLAPPED INTEGER;
declare variable XDATE DATE;
declare variable D INTEGER;
declare variable TOTAL_SPACE DOUBLE PRECISION;

declare variable DATA DOUBLE PRECISION;
declare variable TOTAL DOUBLE PRECISION;
declare variable REV1 DOUBLE PRECISION;
declare variable REV2 DOUBLE PRECISION;
declare variable REV3 DOUBLE PRECISION;
declare variable REV4 DOUBLE PRECISION;
declare variable REV5 DOUBLE PRECISION;
declare variable REV6 DOUBLE PRECISION;
declare variable REV7 DOUBLE PRECISION;
declare variable REV  DOUBLE PRECISION;

declare variable T_DAY1 DOUBLE PRECISION;
declare variable T_DAY2 DOUBLE PRECISION;
declare variable T_DAY3 DOUBLE PRECISION;
declare variable T_DAY4 DOUBLE PRECISION;
declare variable T_DAY5 DOUBLE PRECISION;
declare variable T_DAY6 DOUBLE PRECISION;
declare variable T_DAY7 DOUBLE PRECISION;
begin
  if (SDATE IS NULL) then
      SELECT ARSYSDATE+5 FROM sysparam INTO SDATE;
  T_DAY1 = 0;
  T_DAY2 = 0;
  T_DAY3 = 0;
  T_DAY4 = 0;
  T_DAY5 = 0;
  T_DAY6 = 0;
  T_DAY7 = 0;
  REV1 = 0;
  REV2 = 0;
  REV3 = 0;
  REV4 = 0;
  REV5 = 0;
  REV6 = 0;
  REV7 = 0;
  
  FORMAT = '#,##0;(#,##0)';
  BOLD   = 0;
  SELECT SUM(TOTAL_COUNT) FROM tn_casual_roomno_type INTO TOTAL_SPACE;
  
  FOR SELECT ROOMTYPE, FLAG_OVERLAPPED, TOTAL_COUNT, NAME FROM tn_casual_roomno_type
      WHERE FLAG_OVERLAPPED = 0
      INTO ROOMTYPE, FLAG_OVERLAPPED, TOTAL, TEXT
  DO
  BEGIN
     TEXT = '  ' || TEXT;  
     if (FLAG_OVERLAPPED = 0) then DATASECTION = 'Single';
     ELSE DATASECTION = 'Combo';
     XDATE = SDATE;
     D = 0;
     WHILE (D <= 7) DO
     BEGIN
        DATA = NULL;
        REV = 0;
        SELECT SUM(COUNT_AVAILABLE), SUM(REVENUE_TOTAL) FROM tn_casual_ri
        WHERE ROOMTYPE = :ROOMTYPE
        AND TNDATE = :XDATE
        INTO DATA, REV;
        
        if (DATA IS NULL) then
        BEGIN
           DATA = TOTAL;
           REV  = 0;
        END
        if (D = 1)      then BEGIN DAY1 = DATA; REV1 = REV1 + REV; END
        ELSE if (D = 2) then BEGIN DAY2 = DATA; REV2 = REV1 + REV; END
        ELSE if (D = 3) then BEGIN DAY3 = DATA; REV3 = REV1 + REV; END
        ELSE if (D = 4) then BEGIN DAY4 = DATA; REV4 = REV1 + REV; END
        ELSE if (D = 5) then BEGIN DAY5 = DATA; REV5 = REV1 + REV; END
        ELSE if (D = 6) then BEGIN DAY6 = DATA; REV6 = REV1 + REV; END
        ELSE if (D = 7) then BEGIN DAY7 = DATA; REV7 = REV1 + REV; END
        XDATE = XDATE + 1;
        D = D + 1;
     END
     T_DAY1 = T_DAY1 + DAY1;
     T_DAY2 = T_DAY2 + DAY2;
     T_DAY3 = T_DAY3 + DAY3;
     T_DAY4 = T_DAY4 + DAY4;
     T_DAY5 = T_DAY5 + DAY5;
     T_DAY6 = T_DAY6 + DAY6;
     T_DAY7 = T_DAY7 + DAY7;
     suspend;
  END
  BOLD = 1;
  DAY1 = T_DAY1;
  DAY2 = T_DAY2;
  DAY3 = T_DAY3;
  DAY4 = T_DAY4;
  DAY5 = T_DAY5;
  DAY6 = T_DAY6;
  DAY7 = T_DAY7;
  TEXT = 'Total Available';
  SUSPEND;
  BOLD = 0;
  DAY1 = TOTAL_SPACE - T_DAY1;
  DAY2 = TOTAL_SPACE - T_DAY2;
  DAY3 = TOTAL_SPACE - T_DAY3;
  DAY4 = TOTAL_SPACE - T_DAY4;
  DAY5 = TOTAL_SPACE - T_DAY5;
  DAY6 = TOTAL_SPACE - T_DAY6;
  DAY7 = TOTAL_SPACE - T_DAY7;
  TEXT = '  Occuppied';
  SUSPEND;
  BOLD = 1;

  if (TOTAL_SPACE <> 0) then
  BEGIN
      FORMAT = '#,##0.00%;(#,##0.00%)';
    DAY1 = (TOTAL_SPACE - T_DAY1) / TOTAL_SPACE * 100;
    DAY2 = (TOTAL_SPACE - T_DAY2) / TOTAL_SPACE * 100;
    DAY3 = (TOTAL_SPACE - T_DAY3) / TOTAL_SPACE * 100;
    DAY4 = (TOTAL_SPACE - T_DAY4) / TOTAL_SPACE * 100;
    DAY5 = (TOTAL_SPACE - T_DAY5) / TOTAL_SPACE * 100;
    DAY6 = (TOTAL_SPACE - T_DAY6) / TOTAL_SPACE * 100;
    DAY7 = (TOTAL_SPACE - T_DAY7) / TOTAL_SPACE * 100;
    TEXT = '% Occuppancy';
    SUSPEND;
  END
  /* combo */
  FORMAT = '#,##0;(#,##0)';
  FOR SELECT ROOMTYPE, FLAG_OVERLAPPED, TOTAL_COUNT, NAME FROM tn_casual_roomno_type
      WHERE FLAG_OVERLAPPED = 1
      ORDER BY FLAG_OVERLAPPED
      INTO ROOMTYPE, FLAG_OVERLAPPED, TOTAL, TEXT
  DO
  BEGIN
     TEXT = '  ' || TEXT;
     if (FLAG_OVERLAPPED = 0) then DATASECTION = 'Single';
     ELSE DATASECTION = 'Combo';
     XDATE = SDATE;
     D = 0;
     WHILE (D <= 7) DO
     BEGIN
        DATA = NULL;
        REV = 0;
        SELECT SUM(COUNT_AVAILABLE), SUM(REVENUE_TOTAL) FROM tn_casual_ri
        WHERE ROOMTYPE = :ROOMTYPE
        AND TNDATE = :XDATE
        INTO DATA, REV;
        
        if (DATA IS NULL) then
        BEGIN
           DATA = TOTAL;
           REV  = 0;
        END
        if (D = 1)      then BEGIN DAY1 = DATA; REV1 = REV1 + REV; END
        ELSE if (D = 2) then BEGIN DAY2 = DATA; REV2 = REV1 + REV; END
        ELSE if (D = 3) then BEGIN DAY3 = DATA; REV3 = REV1 + REV; END
        ELSE if (D = 4) then BEGIN DAY4 = DATA; REV4 = REV1 + REV; END
        ELSE if (D = 5) then BEGIN DAY5 = DATA; REV5 = REV1 + REV; END
        ELSE if (D = 6) then BEGIN DAY6 = DATA; REV6 = REV1 + REV; END
        ELSE if (D = 7) then BEGIN DAY7 = DATA; REV7 = REV1 + REV; END
        XDATE = XDATE + 1;
        D = D + 1;
     END
     T_DAY1 = T_DAY1 + DAY1;
     T_DAY2 = T_DAY2 + DAY2;
     T_DAY3 = T_DAY3 + DAY3;
     T_DAY4 = T_DAY4 + DAY4;
     T_DAY5 = T_DAY5 + DAY5;
     T_DAY6 = T_DAY6 + DAY6;
     T_DAY7 = T_DAY7 + DAY7;
     suspend;
  END
  BOLD = 1;
  DAY1 = REV1;
  DAY2 = REV2;
  DAY3 = REV3;
  DAY4 = REV4;
  DAY5 = REV5;
  DAY6 = REV6;
  DAY7 = REV7;
  TEXT = 'Total Revenue';
  SUSPEND;
end^


ALTER PROCEDURE TN_RPT_TENANT_METER(
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    ROOM VARCHAR(8),
    NAME VARCHAR(40),
    CHARGE_TOTAL DOUBLE PRECISION,
    CHARGE_POWER DOUBLE PRECISION,
    CHARGE_WATER DOUBLE PRECISION,
    CHARGE_POWER_USAGE DOUBLE PRECISION,
    CHARGE_WATER_USAGE DOUBLE PRECISION,
    POWER DOUBLE PRECISION,
    WATER DOUBLE PRECISION)
AS
begin
  IF (PYEAR IS NULL) THEN
  BEGIN
     PYEAR = 2004;
     PMONTH = 10;
  END
   FOR SELECT ROOM, NAME, DB, METER_ELECTRIC,
              METER_WATER FROM tn_tenant_jur
       WHERE PYEAR = :PYEAR
         AND PMONTH = :PMONTH
  ORDER BY ROOM
  INTO :ROOM, NAME, CHARGE_TOTAL, POWER, WATER

  DO
  BEGIN
     SELECT SUM(DB) FROM TN_TENANT_JUR_DETAIL
     WHERE ROOM = :ROOM
     AND PYEAR = :PYEAR
     AND PMONTH = :PMONTH
     AND CATEGORY like 'PW%'
     PLAN (TN_TENANT_JUR_DETAIL INDEX (TN_TENANT_JUR_DETAIL_IDX_ROOM))
     INTO CHARGE_POWER;

     SELECT SUM(DB) FROM TN_TENANT_JUR_DETAIL
     WHERE ROOM = :ROOM
     AND PYEAR = :PYEAR
     AND PMONTH = :PMONTH
     AND CATEGORY like 'WT%'
     PLAN (TN_TENANT_JUR_DETAIL INDEX (TN_TENANT_JUR_DETAIL_IDX_ROOM))
     INTO CHARGE_WATER;

     SELECT SUM(DB) FROM TN_TENANT_JUR_DETAIL
     WHERE ROOM = :ROOM
     AND PYEAR = :PYEAR
     AND PMONTH = :PMONTH
     AND CATEGORY like 'PW1'
     PLAN (TN_TENANT_JUR_DETAIL INDEX (TN_TENANT_JUR_DETAIL_IDX_ROOM))
     INTO CHARGE_POWER_USAGE;

     SELECT SUM(DB) FROM TN_TENANT_JUR_DETAIL
     WHERE ROOM = :ROOM
     AND PYEAR = :PYEAR
     AND PMONTH = :PMONTH
     AND CATEGORY like 'WT1'
     PLAN (TN_TENANT_JUR_DETAIL INDEX (TN_TENANT_JUR_DETAIL_IDX_ROOM))
     INTO CHARGE_WATER_USAGE;

     IF (CHARGE_POWER IS NULL) THEN CHARGE_POWER = 0;
     IF (CHARGE_WATER IS NULL) THEN CHARGE_WATER = 0;
     IF (CHARGE_POWER_USAGE IS NULL) THEN CHARGE_POWER_USAGE = 0;
     IF (CHARGE_WATER_USAGE IS NULL) THEN CHARGE_WATER_USAGE = 0;
     suspend;
  END
end^


ALTER PROCEDURE TN_SUMMARY_TAGIHAN(
    SROOM VARCHAR(8),
    EROOM VARCHAR(8),
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    NUMBER INTEGER,
    DOCUMENT VARCHAR(20),
    SOURCEID INTEGER,
    CUSTOMER VARCHAR(8),
    NAME VARCHAR(40),
    ROOM VARCHAR(8),
    SC_TOTAL DOUBLE PRECISION,
    SC_PPN DOUBLE PRECISION,
    LISTRIK_ABODEMEN DOUBLE PRECISION,
    LISTRIK_PEMAKAIAN DOUBLE PRECISION,
    LISTRIK_PJU DOUBLE PRECISION,
    AIR_PEMAKAIAN DOUBLE PRECISION,
    AIR_TARIF DOUBLE PRECISION,
    LAIN_LAIN DOUBLE PRECISION,
    TOTAL DOUBLE PRECISION,
    PAID_TOTAL DOUBLE PRECISION,
    PAID_DATE DATE,
    SALDO DOUBLE PRECISION,
    LUAS DOUBLE PRECISION,
    TOKO VARCHAR(40),
    VOUCHER_NO INTEGER,
    BILLING_STATUS CHAR(1),
    WATER_START DOUBLE PRECISION,
    WATER_END DOUBLE PRECISION,
    METER_WATER DOUBLE PRECISION,
    POWER_START DOUBLE PRECISION,
    POWER_END DOUBLE PRECISION,
    METER_POWER DOUBLE PRECISION,
    REMARK VARCHAR(40))
AS
DECLARE VARIABLE XPAID DOUBLE PRECISION;
DECLARE VARIABLE SDATE DATE;
DECLARE VARIABLE X INTEGER;
begin
  if (SROOM IS NULL) then
  BEGIN
    SROOM = '';
    EROOM = 'ZZZZ';
    PYEAR = 2005;
    PMONTH = 2;
  END
  SDATE = '1.'||PMONTH||'.'||PYEAR;
  FOR SELECT J.ROOM, J.PYEAR, J.PMONTH, J.CUSTOMER, J.NAME, J.TRANS_ID,
             R.SQUARE_METER, R.SHOP_NAME, J.VOUCHER_NO, J.STATUS,
             J.POWER_START, J.POWER_END, J.METER_ELECTRIC,
             J.WATER_START, J.WATER_END, J.METER_WATER, J.REMARK
      FROM TN_TENANT_JUR J
      INNER JOIN TN_ROOM R ON J.ROOM = R.ROOM AND R.status = 'A'
      WHERE J.PYEAR = :PYEAR
      AND J.PMONTH = :PMONTH
      AND ROOM BETWEEN :SROOM AND :EROOM
  INTO ROOM, PYEAR, PMONTH, CUSTOMER, NAME, SOURCEID, LUAS, TOKO, VOUCHER_NO,
       BILLING_STATUS,
       POWER_START, POWER_END, METER_POWER,
       WATER_START, WATER_END, METER_WATER, REMARK
  DO
  BEGIN
    NUMBER = VOUCHER_NO;
    if (NUMBER IS NULL) then NUMBER = 0;
    if (NUMBER =0) then
    BEGIN
      SELECT NUMBER, DOCUMENT FROM ARVCH
      WHERE SOURCE = 'TN'
      AND SOURCEID = :SOURCEID
      AND CUSTOMER = :CUSTOMER
      AND OPENDATE = :SDATE
      INTO :NUMBER, DOCUMENT;
      if (NUMBER IS NULL) then
      BEGIN
         NUMBER = 0;
         DOCUMENT = '';
      END
    END
    ELSE
      SELECT DOCUMENT FROM ARVCH WHERE NUMBER = :NUMBER INTO :DOCUMENT;
      
    /* TOTAL */
    SELECT SUM(DB) FROM TN_TENANT_JUR_DETAIL
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND ROOM = :ROOM
    PLAN (TN_TENANT_JUR_DETAIL INDEX (TN_TENANT_JUR_DETAIL_IDX_ROOM))
    INTO TOTAL;
    /* SERVICE CHARGE */
    SELECT SUM(DB) FROM TN_TENANT_JUR_DETAIL
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND ROOM = :ROOM
    AND CATEGORY IN ('SC', 'SF', 'SC9') /* BISA DITAMBAH MISALKAN ('SC','SF') */
    PLAN (TN_TENANT_JUR_DETAIL INDEX (TN_TENANT_JUR_DETAIL_IDX_ROOM))
    INTO SC_TOTAL;
    
    /* PPN */
    SELECT SUM(DB) FROM TN_TENANT_JUR_DETAIL
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND ROOM = :ROOM
    AND CATEGORY IN ('PPn','PPn9','PPN')
    PLAN (TN_TENANT_JUR_DETAIL INDEX (TN_TENANT_JUR_DETAIL_IDX_ROOM))
    INTO SC_PPN;
    
    /* LISTIK ABODEMENT */
    SELECT SUM(DB) FROM TN_TENANT_JUR_DETAIL
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND ROOM = :ROOM
    AND CATEGORY IN ('PW0', 'PW3','PW4')
    PLAN (TN_TENANT_JUR_DETAIL INDEX (TN_TENANT_JUR_DETAIL_IDX_ROOM))
    INTO LISTRIK_ABODEMEN;

    /* LISTRIK PEMAKAIAN */
    SELECT SUM(DB) FROM TN_TENANT_JUR_DETAIL
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND ROOM = :ROOM
    AND CATEGORY IN ('PW1', 'PW9')
    PLAN (TN_TENANT_JUR_DETAIL INDEX (TN_TENANT_JUR_DETAIL_IDX_ROOM))
    INTO LISTRIK_PEMAKAIAN;

    /* PENERANGAN JALAN UMUM */
    SELECT SUM(DB) FROM TN_TENANT_JUR_DETAIL
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND ROOM = :ROOM
    AND CATEGORY IN ('PW2', 'PWJ')
    PLAN (TN_TENANT_JUR_DETAIL INDEX (TN_TENANT_JUR_DETAIL_IDX_ROOM))
    INTO LISTRIK_PJU;

    /*  PEMAKAIAN AIR */
    SELECT SUM(DB) FROM TN_TENANT_JUR_DETAIL
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND ROOM = :ROOM
    AND CATEGORY IN ('WT1', 'WT9')
    PLAN (TN_TENANT_JUR_DETAIL INDEX (TN_TENANT_JUR_DETAIL_IDX_ROOM))
    INTO AIR_PEMAKAIAN;

    /* AIR - TARIF */
    SELECT SUM(DB) FROM TN_TENANT_JUR_DETAIL
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND ROOM = :ROOM
    AND CATEGORY IN ('WT0', 'WT2')
    PLAN (TN_TENANT_JUR_DETAIL INDEX (TN_TENANT_JUR_DETAIL_IDX_ROOM))
    INTO AIR_TARIF;


    if (SC_TOTAL IS NULL) then SC_TOTAL = 0;
    if (SC_PPN IS NULL) then SC_PPN = 0;
    if (LISTRIK_ABODEMEN IS NULL) then LISTRIK_ABODEMEN = 0;
    if (LISTRIK_PEMAKAIAN  IS NULL) then LISTRIK_PEMAKAIAN = 0;
    if (LISTRIK_PJU IS NULL) then LISTRIK_PJU = 0;
    if (AIR_PEMAKAIAN IS NULL) then AIR_PEMAKAIAN = 0;
    if (AIR_TARIF IS NULL ) then AIR_TARIF = 0;
    if (TOTAL IS NULL) then TOTAL = 0;
    LAIN_LAIN = TOTAL - SC_TOTAL - SC_PPN - LISTRIK_ABODEMEN - LISTRIK_PEMAKAIAN -
                LISTRIK_PJU - AIR_PEMAKAIAN - AIR_TARIF;

    PAID_TOTAL = 0;
    PAID_DATE  = NULL;
    FOR SELECT H.OPENDATE, D.TOTAL FROM ARCASH1 D
        LEFT JOIN ARCASH0 H ON H.NUMBER = D.NUMBER
        WHERE D.VOUCHERNO = :NUMBER
        ORDER BY H.OPENDATE
        INTO  PAID_DATE, XPAID
    DO BEGIN
       PAID_TOTAL = PAID_TOTAL + XPAID;
    END
    SALDO = TOTAL - PAID_TOTAL;
    SUSPEND;
  END
end^


ALTER PROCEDURE TN_TENANT_JUR_DETAIL_I(
    ROOM VARCHAR(8),
    PYEAR INTEGER,
    PMONTH INTEGER,
    CATEGORY VARCHAR(4),
    REMARK VARCHAR(40),
    REFERENCE VARCHAR(20),
    DB DOUBLE PRECISION,
    CR DOUBLE PRECISION,
    FLAG_SYSTEM INTEGER)
AS
BEGIN
  INSERT INTO TN_TENANT_JUR_DETAIL (
    ROOM,
    PYEAR,
    PMONTH,
    CATEGORY,
    REMARK,
    REFERENCE,
    DB,
    CR,
    FLAG_SYSTEM)
  VALUES (
    :ROOM,
    :PYEAR,
    :PMONTH,
    :CATEGORY,
    :REMARK,
    :REFERENCE,
    :DB,
    :CR,
    :FLAG_SYSTEM);
END^


ALTER PROCEDURE TN_TENANT_JUR_DETAIL_SAVE(
    ROOM VARCHAR(8),
    PYEAR INTEGER,
    PMONTH INTEGER,
    CATEGORY VARCHAR(4),
    REMARK VARCHAR(40),
    REFERENCE VARCHAR(20),
    DB DOUBLE PRECISION)
AS
DECLARE VARIABLE X INTEGER;
BEGIN
  if (DB = 0) then
  BEGIN
    DELETE FROM TN_TENANT_JUR_DETAIL
    WHERE ROOM = :ROOM
    AND PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND CATEGORY = :CATEGORY;
    EXIT;
  END
  
  SELECT COUNT(*) FROM TN_TENANT_JUR_DETAIL
  WHERE ROOM = :ROOM
  AND PYEAR = :PYEAR
  AND PMONTH = :PMONTH
  AND CATEGORY = :CATEGORY
  INTO X;
  
  if (X = 0) then
  BEGIN
    INSERT INTO TN_TENANT_JUR_DETAIL (
      ROOM,
        PYEAR,
        PMONTH,
        CATEGORY,
        REMARK,
        REFERENCE,
        DB,
        CR,
        FLAG_SYSTEM)
      VALUES (
        :ROOM,
        :PYEAR,
        :PMONTH,
        :CATEGORY,
        :REMARK,
        :REFERENCE,
        :DB,
        0,
        1);
  END
  ELSE
  BEGIN
      UPDATE TN_TENANT_JUR_DETAIL
      SET REMARK = :REMARK, REFERENCE = :REFERENCE, DB = :DB
      WHERE ROOM = :ROOM
      AND PYEAR = :PYEAR
      AND PMONTH = :PMONTH
      AND CATEGORY = :CATEGORY;
  END
END^


ALTER PROCEDURE TN_TENANT_METER(
    PROOM VARCHAR(8),
    PYEAR INTEGER,
    PMONTH INTEGER)
RETURNS (
    POWER DOUBLE PRECISION,
    WATER DOUBLE PRECISION)
AS
declare variable X INTEGER;
declare variable OYEAR INTEGER;
declare variable OMONTH INTEGER;
begin
  OYEAR = PYEAR;
  OMONTH = PMONTH - 1;
  if (OMONTH = 0) then
  BEGIN
    OYEAR = OYEAR - 1;
    OMONTH = 12;
  END
  
  SELECT COUNT(*) FROM tn_tenant_jur
  WHERE ROOM = :PROOM
  AND PYEAR = :OYEAR
  AND PMONTH = :OMONTH
  INTO :X;
  
  if (X <> 0) then
  BEGIN
      SELECT METER_ELECTRIC, METER_WATER FROM tn_tenant_jur
      WHERE ROOM = :PROOM
      AND PYEAR = :OYEAR
      AND PMONTH = :OMONTH
      INTO POWER, WATER;
  END
  ELSE
  BEGIN
    SELECT METER_WATER, METER_GAS FROM TN_ROOM
    WHERE ROOM = :PROOM
    INTO POWER, WATER;
  END
  if (POWER IS NULL) then POWER = 0;
  if (WATER IS NULL) then WATER = 0;
  suspend;
end^


ALTER PROCEDURE WEB_COST_DEPT
RETURNS (
    DEPT VARCHAR(4),
    NAME VARCHAR(40),
    FOOD DOUBLE PRECISION,
    BEVERAGE DOUBLE PRECISION,
    OTHERES DOUBLE PRECISION)
AS
declare variable PYEAR INTEGER;
declare variable PMONTH INTEGER;
BEGIN
  SELECT INV_YEAR, INV_MONTH
  FROM SYSPARAM WHERE ID = 1
  INTO :PYEAR, :PMONTH;
  
  FOR
    SELECT DEPT, NAME
    FROM INVDEPT
    INTO
      :DEPT,
      :NAME
  DO
  BEGIN
    SELECT SUM(AMTTOTAL) FROM INVCONSUME
    WHERE PYEAR = :PYEAR
    AND PMONTH = :PMONTH
    AND ITEMTYPE = 'F'
    INTO :FOOD;
    SUSPEND;
  END
END^


ALTER PROCEDURE WEB_RECONCILE_CALC
RETURNS (
    LISTINDEX INTEGER,
    SDATE DATE,
    FOOD DOUBLE PRECISION,
    BEVERAGE DOUBLE PRECISION)
AS
DECLARE VARIABLE INVSYSDATE DATE;
DECLARE VARIABLE M INTEGER;
DECLARE VARIABLE Y INTEGER;
DECLARE VARIABLE BOM DATE;
BEGIN
  SELECT INVSYSDATE FROM SYSPARAM INTO :INVSYSDATE;
  EXECUTE PROCEDURE SP_BEGINOFMONTH(INVSYSDATE) RETURNING_VALUES BOM;
  M = EXTRACT(MONTH FROM BOM - 1);
  Y = EXTRACT(YEAR  FROM BOM - 1);
  LISTINDEX = 0;
  WHILE (LISTINDEX <= 12) DO
  BEGIN
    SDATE = '1.'||M||'.'||Y;
    IF (NOT EXISTS(SELECT * FROM WEB_RECONCILE WHERE PYEAR = :Y AND PMONTH = :M)) THEN
    BEGIN
       SELECT AMOUNT FROM INV_RPT_RCONS(:Y, :M, 'F')
       WHERE DATATYPE = 'COGS' AND INFO = '%'
       INTO FOOD;

       SELECT AMOUNT FROM INV_RPT_RCONS(:Y, :M, 'B')
       WHERE DATATYPE = 'COGS' AND INFO = '%'
       INTO BEVERAGE;

       IF (FOOD IS NULL) THEN FOOD = 0;
       IF (BEVERAGE IS NULL) THEN BEVERAGE = 0;
       SUSPEND;
       INSERT INTO WEB_RECONCILE(PYEAR, PMONTH, FOOD, BEVERAGE)
       VALUES
       (:Y, :M, :FOOD, :BEVERAGE);
    END
    ELSE
    BEGIN
       SELECT FOOD, BEVERAGE FROM WEB_RECONCILE WHERE PYEAR = :Y AND PMONTH = :M
       INTO FOOD, BEVERAGE;
       SUSPEND;
    END
    LISTINDEX = LISTINDEX + 1;
    M = M - 1;
    IF (M < 1) THEN
    BEGIN
       M = 12;
       Y = Y - 1;
    END
  END
END^


ALTER PROCEDURE WEB_STATUS_CALC
RETURNS (
    INFOTYPE VARCHAR(8),
    LINE INTEGER,
    DATATYPE VARCHAR(8),
    DATA1 DOUBLE PRECISION,
    DATA2 DOUBLE PRECISION,
    FORMAT VARCHAR(8),
    TEXT VARCHAR(60))
AS
declare variable PDATE DATE;
declare variable BOM DATE;
declare variable ITYPE CHAR(1);
declare variable T1 DOUBLE PRECISION;
declare variable T2 DOUBLE PRECISION;
declare variable ICOST VARCHAR(4);
begin
  INFOTYPE = 'STATUS';
  SELECT INVSYSDATE-1 FROM SYSPARAM WHERE ID = 1 INTO :PDATE;
  execute procedure sp_beginofmonth(:PDATE) returning_values :BOM;
  /* ------------------------------------------------------------------------ */
  /* CONSUMPTION                                                              */
  /* ------------------------------------------------------------------------ */
  LINE = 0;
  DATATYPE = 'TITLE';
  TEXT = 'Consumed';
  DATA1 = 0;
  DATA2 = 0;
  SUSPEND;
  LINE = LINE + 1;
  DATATYPE = 'CONSUME';
  FORMAT = '#,##0';
  T1 = 0;
  T2 = 0;
  FOR SELECT ITYPE, NAME FROM INVTYPE
      ORDER BY ORDERLISTNO
      INTO :ITYPE, :TEXT
  DO
  BEGIN
    DATA1 = 0;
    DATA2 = 0;
    SELECT SUM(AMTTOTAL) FROM invconsume_daily
    WHERE ITEMTYPE = :ITYPE
    AND OPENDATE = :PDATE
    INTO :DATA1;
    if (DATA1 IS NULL) then DATA1 = 0;
    
    SELECT SUM(AMTTOTAL) FROM invconsume_daily
    WHERE ITEMTYPE = :ITYPE
    AND OPENDATE BETWEEN :BOM AND :PDATE
    INTO :DATA2;
    if (DATA2 IS NULL) then DATA2 = 0;
    TEXT = '    '||TEXT;
    suspend;
    T1 = T1 + DATA1;
    T2 = T2 + DATA2;
    LINE = LINE + 1;
  END
  TEXT = 'Total';
  DATA1 = T1;
  DATA2 = T2;
  SUSPEND;
  LINE = LINE + 1;
  TEXT = '';
  DATATYPE = 'SPACE';
  DATA1 = 0;
  DATA2 = 0;
  SUSPEND;
  LINE = LINE+1;
  /* ------------------------------------------------------------------------ */
  /* SALES                                                                    */
  /* ------------------------------------------------------------------------ */
  LINE = 0;
  DATATYPE = 'TITLE';
  TEXT = 'Sales';
  DATA1 = 0;
  DATA2 = 0;
  SUSPEND;  
  LINE = LINE + 1;
  DATATYPE = 'SALES';
  T1 = 0;
  T2 = 0;
  FOR SELECT SL.SLCLASS, SUM(SL.AMOUNT) FROM irrssale SL
      WHERE SLDATE BETWEEN :BOM AND :PDATE
      GROUP BY SLCLASS
      INTO ITYPE, DATA2
  DO
  BEGIN
     if (ITYPE = 'F') then TEXT = 'Food';
     ELSE if (ITYPE = 'B') then TEXT = 'Beverage';
     ELSE TEXT = 'Others';
     SELECT  SUM(SL.AMOUNT) FROM irrssale SL
     WHERE SLDATE = :PDATE
     AND SLCLASS = :ITYPE
     INTO DATA1;
     if (DATA1 IS NULL) then DATA1 = 0;
     T1 = T1 + DATA1;
     T2 = T2 + DATA2;
     TEXT = '    '||TEXT;
     SUSPEND;
     LINE = LINE+1;
  END
  TEXT = 'Total Sales';
  DATA1 = T1;
  DATA2 = T2;
  SUSPEND;
  LINE = LINE + 1;
  TEXT = '';
  DATATYPE = 'SPACE';
  DATA1 = 0;
  DATA2 = 0;
  SUSPEND;
  LINE = LINE+1;  
  /* ------------------------------------------------------------------------ */
  /* COGS                                                                     */
  /* ------------------------------------------------------------------------ */
  LINE = 0;
  DATATYPE = 'TITLE';
  TEXT = 'Cost of Goods Sold';
  DATA1 = 0;
  DATA2 = 0;
  SUSPEND;  
  LINE = LINE + 1;
  DATATYPE = 'COGS';
  T1 = 0;
  T2 = 0;
  /* COGS FOOD MTD */
  SELECT SUM(C.AMTTOTAL) FROM INVCONSUME_DAILY C
  LEFT JOIN INVCOST CC ON CC.ICOST = C.ICOST
  WHERE C.ITEMTYPE = 'F'
  AND CC.FLAG_PRODUCTION = 1
  AND C.OPENDATE BETWEEN :BOM AND :PDATE
  INTO DATA2;
  
  SELECT SUM(C.AMTTOTAL) FROM INVCONSUME_DAILY C
  LEFT JOIN INVCOST CC ON CC.ICOST = C.ICOST
  WHERE C.ITEMTYPE = 'F'
  AND CC.FLAG_PRODUCTION = 1
  AND C.OPENDATE = :PDATE
  INTO DATA1;  
  
  if (DATA1 IS NULL) then DATA1 = 0;
  if (DATA2 IS NULL) then DATA2 = 0;
  TEXT = '   Food';
  SUSPEND;
  LINE = LINE + 1;
  T1 = T1 + DATA1;
  T2 = T2 + DATA2;
  /* COGS BEVERAGE MTD */
  SELECT SUM(C.AMTTOTAL) FROM INVCONSUME_DAILY C
  LEFT JOIN INVCOST CC ON CC.ICOST = C.ICOST
  WHERE C.ITEMTYPE = 'B'
  AND CC.FLAG_PRODUCTION = 1
  AND C.OPENDATE BETWEEN :BOM AND :PDATE
  INTO DATA2;
  
  SELECT SUM(C.AMTTOTAL) FROM INVCONSUME_DAILY C
  LEFT JOIN INVCOST CC ON CC.ICOST = C.ICOST
  WHERE C.ITEMTYPE = 'B'
  AND CC.FLAG_PRODUCTION = 1
  AND C.OPENDATE = :PDATE
  INTO DATA1;  
  
  if (DATA1 IS NULL) then DATA1 = 0;
  if (DATA2 IS NULL) then DATA2 = 0;
  TEXT = '   Beverage';
  SUSPEND;
  LINE = LINE + 1;    
  T1 = T1 + DATA1;
  T2 = T2 + DATA2;  
  TEXT = 'Total COGS';
  DATA1 = T1;
  DATA2 = T2;
  SUSPEND;
  LINE = LINE + 1;
  TEXT = '';
  DATATYPE = 'SPACE';
  DATA1 = 0;
  DATA2 = 0;
  SUSPEND;
  LINE = LINE+1;    
end^


ALTER PROCEDURE XXX_FILLSUPL_ITEM
RETURNS (
    PARTNO VARCHAR(10),
    ITEM_NAME VARCHAR(40),
    SUPPLIER VARCHAR(6),
    SUPPLIERNAME VARCHAR(40),
    LASTIN DATE,
    COST FLOAT)
AS
DECLARE VARIABLE LISINDEX INTEGER;
BEGIN
  FOR
    SELECT ITEM_NAME,SUPPLIERNAME,LASTIN,COST FROM INVSUPLITEM_NEW
    WHERE PARTNO = ''
    INTO
      :ITEM_NAME,
      :SUPPLIERNAME,LASTIN,COST
  DO
  BEGIN
    SUPPLIER = '';
    PARTNO = '';
    SELECT FIRST 1 SUPPLIER FROM SYSSUPPLIER
    WHERE NAME = :SUPPLIERNAME
    INTO SUPPLIER;
    
    SELECT FIRST 1 PARTNO FROM INVMASTER
    WHERE NAME LIKE :ITEM_NAME||'%'
    INTO PARTNO;


    /*
    UPDATE INVSUPLITEM_NEW SET PARTNO = :PARTNO,SUPPLIER = :SUPPLIER
    WHERE LISTINDEX = :LISINDEX;
    */
    SUSPEND;
  END
END^


ALTER PROCEDURE X_ART_AP_MUTATION(
    SSUPPLIER VARCHAR(6),
    ESUPPLIER VARCHAR(6),
    REFDATE DATE,
    DETAILFLAG INTEGER,
    CURRENCY VARCHAR(4))
RETURNS (
    PREFDATE DATE,
    SUPPLIER VARCHAR(6),
    NAME VARCHAR(40),
    GL_ACCOUNT VARCHAR(20),
    GL_DEPT VARCHAR(4),
    GL_COST VARCHAR(4),
    ACCNAME VARCHAR(40),
    NAMETYPE VARCHAR(40),
    CODETYPE VARCHAR(40),
    CURR NUMERIC(15,4),
    CURR_CASH NUMERIC(15,4),
    OVER30 NUMERIC(15,4),
    OVER60 NUMERIC(15,4),
    OVER90 NUMERIC(15,4),
    TOTAL NUMERIC(15,4),
    NUMBER INTEGER,
    OPENDATE DATE,
    DUEDATE DATE,
    DOCUMENT VARCHAR(20),
    AGE INTEGER,
    T DOUBLE PRECISION,
    RECEIVINGNO INTEGER,
    SOURCE CHAR(1),
    RCVDOC VARCHAR(100))
AS
declare variable d integer;
declare variable m integer;
declare variable y integer;
declare variable voucher numeric(15,4);
declare variable cash numeric(15,4);
declare variable adjust numeric(15,4);
declare variable depos numeric(15,4);
declare variable f_voucher numeric(15,4);
declare variable f_cash numeric(15,4);
declare variable f_adjust numeric(15,4);
declare variable f_depos numeric(15,4);
begin
  if (SSUPPLIER IS NULL) then
  BEGIN
     SSUPPLIER = '';
     ESUPPLIER = 'zzzzzz';
     SELECT APSYSDATE FROM SYSPARAM INTO REFDATE;
     REFDATE = '27.3.2008';
     DETAILFLAG = 0;
     CURRENCY = 'SIN';
  END
  T = 0;
  PREFDATE = REFDATE;



  for select A.supplier,A.name,A.SUPLTYPE,T.NAME,
             T.GLACCOUNT,T.GLDEPT,T.GLCOST,COA.NAME
  from syssupplier A
       LEFT JOIN SYSSUPPLIERTYPE T ON T.SUPPLIERTYPE = A.SUPLTYPE
       LEFT JOIN GLCOA COA ON COA.ACCOUNT = T.GLACCOUNT
  where supplier between :ssupplier and :esupplier
  into :supplier,name,CODETYPE,NAMETYPE,
       GL_ACCOUNT,GL_DEPT,GL_COST,ACCNAME
  do
  begin
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       curr = 0;
       over30 = 0;
       over60 = 0;
       over90 = 0;
    end
    /*========================================================================*/
    /* hitung detail transaction                                              */
    /*========================================================================*/
    for select number,total,opendate,duedate,document,receivingno,source,supplier,
               forex_total /* 27 MARET 2008 */
        from apvch
         where supplier = :supplier
           and opendate <= :RefDate
           and ((:CURRENCY = 'All') or (CURRENCY = :CURRENCY)) /* 27 MARET 2008 */
         plan (apvch index (APVCH_IDX_SUPPLIER_DATE))
         into number,voucher,opendate,duedate,document,receivingno,source,supplier,
              f_voucher /* 27 MARET 2008 */
    do
    begin
       select sum(apcash1.total-apcash1.vch_gainloss),
              sum(apcash1.forex_total) /* 27 MARET 2008 */
        from apcash1
         inner join apcash0 on apcash0.number = apcash1.number
        where apcash1.voucherno = :number and apcash0.duedate <= :RefDate
          and apcash0.status in ('R','C','L')
         into cash,
              f_cash; /* 27 MARET 2008 */

       select sum(apdepos1.total),
              sum(apdepos1.forex_total) /* 27 MARET 2008 */
       from apdepos1
        where apdepos1.voucherno = :number and apdepos1.applieddate <= :RefDate
          and apdepos1.status in ('R','C','L')
         into depos,
              f_depos; /* 27 MARET 2008 */

       select sum(cr-db),
              sum(forex_cr-forex_db)/* 27 MARET 2008 */
        from apadj where voucherno = :number and OpenDate <= :RefDate
         into adjust,f_adjust;

       if (voucher is null) then voucher = 0;
       if (cash    is null) then cash    = 0;
       if (adjust  is null) then adjust  = 0;
       if (depos   is null) then depos   = 0;

       /* ---------------------------------------------------------------- */
       /* 27 MARET 2008                                                    */
       /* ---------------------------------------------------------------- */
       if (f_voucher is null) then f_voucher = 0;
       if (f_cash    is null) then f_cash    = 0;
       if (f_adjust  is null) then f_adjust  = 0;
       if (f_depos   is null) then f_depos   = 0;
       /* ---------------------------------------------------------------- */
       IF (CURRENCY = 'All') THEN
          voucher = voucher - cash + adjust - depos;
       ELSE
          voucher = f_voucher - f_cash + f_adjust - f_depos;

       d = RefDate - opendate;
       /*========================================================================*/
       /* jika aging detail                                                      */
       /*========================================================================*/
       if (detailflag = 1) then
       begin
          curr = 0;
          over30 = 0;
          over60 = 0;
          over90 = 0;
          end


       if (d <= 30)      then curr   = curr + voucher;
       else if (d <= 60) then over30 = over30 + voucher;
       else if (d <= 90) then over60 = over60 + voucher;
       else over90 = over90 + voucher;
       if (detailflag = 1) then
       begin
         age = d;
         total = curr + over30 + over60 + over90;
         if (total <> 0) then suspend;
       end
    end
    /*========================================================================*/
    /* jika aging summary                                                     */
    /*========================================================================*/
    if (detailflag <> 1) then
    begin
       total = curr + over30 + over60 + over90;
       number = 0;
       document = '';
       T = T + TOTAL;
       if (total <> 0) then suspend;
    end
  end
end^


SET TERM ; ^



